def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    if h == 0:
        return []
    w = len(grid[0])

    visited = [[False] * w for _ in range(h)]
    blocks = []
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or visited[r][c]:
                continue

            color = int(grid[r][c])
            stack = [(r, c)]
            visited[r][c] = True
            cells = []

            while stack:
                cr, cc = stack.pop()
                cells.append((cr, cc))
                for dr, dc in dirs:
                    nr, nc = cr + dr, cc + dc
                    if (
                        0 <= nr < h
                        and 0 <= nc < w
                        and not visited[nr][nc]
                        and int(grid[nr][nc]) == color
                    ):
                        visited[nr][nc] = True
                        stack.append((nr, nc))

            rmin = min(rr for rr, _ in cells)
            rmax = max(rr for rr, _ in cells)
            cmin = min(cc for _, cc in cells)
            cmax = max(cc for _, cc in cells)

            # All puzzle objects are 4x4 squares.
            if rmax - rmin + 1 != 4 or cmax - cmin + 1 != 4:
                continue

            sub = [
                [int(grid[rr][cc]) for cc in range(cmin, cmax + 1)]
                for rr in range(rmin, rmax + 1)
            ]

            # Solid: all 16 cells are the object color.
            if all(sub[i][j] == color for i in range(4) for j in range(4)):
                blocks.append((rmin, cmin, sub, "solid"))
                continue

            # Hollow: border is the object color, 2x2 interior is background.
            border_ok = all(
                sub[i][j] == color
                for i in range(4)
                for j in range(4)
                if i in (0, 3) or j in (0, 3)
            )
            interior_ok = all(sub[i][j] == 0 for i in (1, 2) for j in (1, 2))

            if border_ok and interior_ok:
                blocks.append((rmin, cmin, sub, "hollow"))

    hollow = [b for b in blocks if b[3] == "hollow"]
    solid = [b for b in blocks if b[3] == "solid"]

    # Preserve vertical order separately for each type.
    hollow.sort(key=lambda b: (b[0], b[1]))
    solid.sort(key=lambda b: (b[0], b[1]))

    rows = max(len(hollow), len(solid))
    if rows == 0:
        return []

    out = [[0] * 8 for _ in range(rows * 4)]

    for idx, (_, _, sub, _) in enumerate(hollow):
        for i in range(4):
            for j in range(4):
                out[idx * 4 + i][j] = sub[i][j]

    for idx, (_, _, sub, _) in enumerate(solid):
        for i in range(4):
            for j in range(4):
                out[idx * 4 + i][4 + j] = sub[i][j]

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    # Accept either list of lists or list of strings.
    if not grid:
        return []

    g = []
    for row in grid:
        if isinstance(row, str):
            g.append([int(ch) for ch in row])
        else:
            g.append([int(x) for x in row])

    H = len(g)
    W = len(g[0]) if H else 0
    if H == 0 or W == 0:
        return [row[:] for row in g]

    # ------------------------------------------------------------------
    # 1. Find the vertical separator line.
    #    It is the column containing the longest vertical run / largest
    #    count of one non-zero colour, preferably with no other colours.
    # ------------------------------------------------------------------
    best = None  # (score, col, color)
    for c in range(W):
        for color in range(1, 10):
            cnt = 0
            run = 0
            max_run = 0
            other_nonzero = 0

            for r in range(H):
                v = g[r][c]
                if v == color:
                    cnt += 1
                    run += 1
                    if run > max_run:
                        max_run = run
                else:
                    run = 0
                    if v != 0 and v != color:
                        other_nonzero += 1

            if cnt == 0:
                continue

            # Prefer large count, then long contiguous run, then purity.
            score = (cnt, max_run, -other_nonzero)
            if best is None or score > best[0]:
                best = (score, c, color)

    if best is None:
        return [row[:] for row in g]

    _, sep_col, sep_color = best

    # ------------------------------------------------------------------
    # 2. Decide which side of the separator is the source side.
    #    The source side is the side containing the non-zero objects.
    # ------------------------------------------------------------------
    left_nonzero = 0
    right_nonzero = 0
    for r in range(H):
        for c in range(W):
            if g[r][c] == 0:
                continue
            if c < sep_col:
                left_nonzero += 1
            elif c > sep_col:
                right_nonzero += 1

    if left_nonzero == 0 and right_nonzero == 0:
        return [row[:] for row in g]

    source_left = left_nonzero >= right_nonzero

    # ------------------------------------------------------------------
    # 3. For every row, build the periodic pattern on the destination side.
    #
    #    For each non-zero colour c appearing on the source side of the row:
    #      n_c = number of occurrences of c in that source segment.
    #      c is placed at destination offsets p where p % n_c == 0.
    #
    #    If several colours qualify for the same offset, the colour whose
    #    nearest occurrence is closest to the separator wins.
    # ------------------------------------------------------------------
    out = [row[:] for row in g]

    for r in range(H):
        # Source segment.
        if source_left:
            src_cols = range(0, sep_col)
        else:
            src_cols = range(sep_col + 1, W)

        counts = {}
        nearest = {}

        for c in src_cols:
            v = g[r][c]
            if v == 0:
                continue
            counts[v] = counts.get(v, 0) + 1

            if source_left:
                dist = sep_col - c
            else:
                dist = c - sep_col

            if v not in nearest or dist < nearest[v]:
                nearest[v] = dist

        if not counts:
            continue

        # Priority: closest to separator first.
        colors = sorted(counts.keys(), key=lambda x: (nearest[x], -counts[x], x))

        # Destination segment.
        if source_left:
            dest_cols = range(sep_col + 1, W)
        else:
            dest_cols = range(sep_col - 1, -1, -1)

        for p, c in enumerate(dest_cols):
            val = 0
            for color in colors:
                if p % counts[color] == 0:
                    val = color
                    break
            out[r][c] = val

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    a = np.array(grid, dtype=int)
    h, w = a.shape
    out = a.copy()

    # Fill every 0 by copying from the cell reflected through the center
    # of the grid, i.e. (r, c) <- (h - 1 - r, w - 1 - c).
    for r in range(h):
        rr = h - 1 - r
        for c in range(w):
            cc = w - 1 - c
            if out[r, c] == 0:
                out[r, c] = a[rr, cc]

    return out.tolist()

