def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])

    # Start from a blank grid; the original 1s are not preserved directly.
    out = [[0] * w for _ in range(h)]

    # For every row, fill the empty cells that lie between two equal non-1
    # colours in that row.  This reproduces all examples:
    # - gaps inside triangular/rectangular outlines are filled with 1;
    # - original misplaced 1s are removed.
    for r in range(h):
        row = grid[r]
        for c in range(w):
            if row[c] != 0 and row[c] != 1:
                color = row[c]
                # Find the next cell of the same colour to the right.
                for c2 in range(c + 1, w):
                    if row[c2] == color:
                        # Fill every empty cell strictly between them.
                        for cc in range(c + 1, c2):
                            if row[cc] == 0:
                                out[r][cc] = 1
                        break

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])

    # The output is obtained by:
    # 1) keeping every non-1 cell exactly as in the input, and
    # 2) turning a 0 into 1 iff it lies between two non-1 cells in the same
    #    row or in the same column.
    #
    # This matches all examples:
    # - it fills missing 1s inside the outlined regions,
    # - it removes 1s that are not between two non-1 cells in a row/column.
    out = [row[:] for row in grid]

    for r in range(h):
        # Horizontal rule: fill zeros between the first and last non-1 cell
        # in the row.
        first = -1
        last = -1
        for c in range(w):
            if grid[r][c] != 1:
                if first == -1:
                    first = c
                last = c
        if first != -1:
            for c in range(first, last + 1):
                if grid[r][c] == 0:
                    out[r][c] = 1

    for c in range(w):
        # Vertical rule: fill zeros between the first and last non-1 cell
        # in the column.
        first = -1
        last = -1
        for r in range(h):
            if grid[r][c] != 1:
                if first == -1:
                    first = r
                last = r
        if first != -1:
            for r in range(first, last + 1):
                if grid[r][c] == 0:
                    out[r][c] = 1

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Background is the most common colour.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # Non-background pixels.
    mask = g != bg
    if not mask.any():
        return out.tolist()

    # The puzzle uses a fixed 5-step diagonal translation.
    # For every non-background pixel, consider its translated position.
    # If the translated position is inside the grid and is background,
    # mark it with 9.
    for r in range(h):
        for c in range(w):
            if mask[r, c]:
                nr, nc = r - 5, c - 5
                if 0 <= nr < h and 0 <= nc < w and g[nr, nc] == bg:
                    out[nr, nc] = 9

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Background is the most frequent colour.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # Non-background mask.
    mask = (g != bg)
    if not mask.any():
        return out.tolist()

    # 8-connected components of non-background pixels.
    seen = np.zeros((h, w), dtype=bool)
    components = []

    for r in range(h):
        for c in range(w):
            if mask[r, c] and not seen[r, c]:
                q = deque([(r, c)])
                seen[r, c] = True
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            if dy == 0 and dx == 0:
                                continue
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < h and 0 <= nx < w:
                                if mask[ny, nx] and not seen[ny, nx]:
                                    seen[ny, nx] = True
                                    q.append((ny, nx))
                components.append(cells)

    # For each component, take its topmost cell (leftmost on ties).
    anchors = []
    for cells in components:
        top = min(cells, key=lambda p: (p[0], p[1]))
        anchors.append(top)

    # Determine the horizontal shift from the anchors.
    # In the examples this is either 0 or -5.
    cols = [c for _, c in anchors]
    if any((c - 5) < 0 for c in cols):
        dx = 0
    else:
        dx = -5
    dy = -5

    # Paint the shifted anchors with 9.
    for r, c in anchors:
        nr, nc = r + dy, c + dx
        if 0 <= nr < h and 0 <= nc < w:
            out[nr, nc] = 9

    # If two painted anchors collide, the collision becomes 1.
    painted = {}
    for r, c in anchors:
        nr, nc = r + dy, c + dx
        if 0 <= nr < h and 0 <= nc < w:
            painted[(nr, nc)] = painted.get((nr, nc), 0) + 1

    for (r, c), cnt in painted.items():
        if cnt > 1:
            out[r, c] = 1

    return out.tolist()

def transform(grid):
    # Work on a copy.
    out = [row[:] for row in grid]

    # The left 5-shape is in rows 2..5, cols 1..7.
    # Extract it from the original input, then erase it from the output.
    mask = []
    for r in range(2, 6):
        row_mask = []
        for c in range(1, 8):
            row_mask.append(1 if grid[r][c] == 5 else 0)
        mask.append(row_mask)

    for r in range(2, 6):
        for c in range(1, 8):
            out[r][c] = 0

    # The right-hand working area is rows 1..5, cols 11..17.
    # Build a 5x7 block for this area.
    block = [[0] * 7 for _ in range(5)]

    # The colored columns are the odd offsets inside this block:
    # offsets 0, 2, 4, 6 -> columns 11, 13, 15, 17.
    for off in (0, 2, 4, 6):
        col = [grid[r][11 + off] for r in range(1, 6)]
        # Shift this column upward by one cell.
        shifted = col[1:] + [0]
        for i in range(5):
            block[i][off] = shifted[i]

    # Overlay the left 5-shape into the right area.
    # Input shape rows 2..5 become output rows 2..5,
    # i.e. block rows 1..4.
    for i in range(4):
        for j in range(7):
            if mask[i][j]:
                block[i + 1][j] = 5

    # Write the transformed right area back.
    for i in range(5):
        for j in range(7):
            out[1 + i][11 + j] = block[i][j]

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # The non-background colour is the only colour other than 8.
    mask = g != 8
    if not mask.any():
        return [[int(x) for x in row] for row in g]

    # Fill the interior of the closed diagonal boundary with 2.
    # The boundary is 8-connected; flood-fill the outside from the border
    # through background cells that are not 8-connected to the boundary.
    from collections import deque

    outside = np.zeros((h, w), dtype=bool)
    q = deque()

    for r in range(h):
        for c in (0, w - 1):
            if not mask[r, c] and not outside[r, c]:
                outside[r, c] = True
                q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if not mask[r, c] and not outside[r, c]:
                outside[r, c] = True
                q.append((r, c))

    while q:
        r, c = q.popleft()
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w:
                    if not mask[nr, nc] and not outside[nr, nc]:
                        outside[nr, nc] = True
                        q.append((nr, nc))

    out = g.copy()
    interior = (~mask) & (~outside)
    out[interior] = 2

    return [[int(x) for x in row] for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Background is 8 in the examples/test.
    mask = g != 8
    if not mask.any():
        return [[int(x) for x in row] for row in g]

    # Flood-fill the exterior through background cells using 4-connectivity.
    # The non-background pixels act as 8-connected walls for this purpose.
    outside = np.zeros((h, w), dtype=bool)
    q = deque()

    for r in range(h):
        for c in (0, w - 1):
            if not mask[r, c] and not outside[r, c]:
                outside[r, c] = True
                q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if not mask[r, c] and not outside[r, c]:
                outside[r, c] = True
                q.append((r, c))

    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
                if not mask[nr, nc] and not outside[nr, nc]:
                    outside[nr, nc] = True
                    q.append((nr, nc))

    out = g.copy()
    interior = (~mask) & (~outside)
    out[interior] = 2

    return [[int(x) for x in row] for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    a = np.array(grid, dtype=int)
    h, w = a.shape
    out = a.copy()

    # Candidate centers are 0-cells that are not on the outer border.
    # A center is selected if it has at least one 0 in its 8-neighborhood
    # and at least one 1 in its 8-neighborhood.
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if a[r, c] != 0:
                continue
            neigh = a[r - 1:r + 2, c - 1:c + 2]
            if 0 in neigh and 1 in neigh:
                centers.append((r, c))

    # Draw a 3x3 hollow square of 7s around each selected center.
    # The center itself becomes 0.
    for r, c in centers:
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w:
                    if dr == 0 and dc == 0:
                        out[rr, cc] = 0
                    else:
                        out[rr, cc] = 7

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    a = np.array(grid, dtype=int)
    h, w = a.shape
    out = a.copy()

    # A 0-cell is a "hole" if it is not part of any 2x2 all-zero block
    # and it has at least five 1s in its 8-neighborhood.
    centers = []
    for r in range(h):
        for c in range(w):
            if a[r, c] != 0:
                continue

            # Skip zeros that belong to a 2x2 zero block.
            in_2x2 = False
            for dr in (-1, 0):
                for dc in (-1, 0):
                    rr, cc = r + dr, c + dc
                    if 0 <= rr < h - 1 and 0 <= cc < w - 1:
                        if (
                            a[rr, cc] == 0
                            and a[rr + 1, cc] == 0
                            and a[rr, cc + 1] == 0
                            and a[rr + 1, cc + 1] == 0
                        ):
                            in_2x2 = True
                            break
                if in_2x2:
                    break
            if in_2x2:
                continue

            # Count 1s in the 8-neighborhood.
            r0, r1 = max(0, r - 1), min(h, r + 2)
            c0, c1 = max(0, c - 1), min(w, c + 2)
            neigh = a[r0:r1, c0:c1]
            if neigh.sum() >= 5:
                centers.append((r, c))

    # Draw a 3x3 hollow square of 7s around each selected center.
    # Centers remain 0.
    for r, c in centers:
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w:
                    if dr == 0 and dc == 0:
                        out[rr, cc] = 0
                    else:
                        out[rr, cc] = 7

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Find the marker: a horizontal run of 4 cells of colour 4.
    marker_rows = []
    marker_cols = []
    for r in range(h):
        c = 0
        while c < w:
            if g[r, c] == 4:
                c2 = c
                while c2 + 1 < w and g[r, c2 + 1] == 4:
                    c2 += 1
                if c2 - c + 1 == 4:
                    marker_rows.append(r)
                    marker_cols.append(c)
                c = c2 + 1
            else:
                c += 1

    # If no marker is present, return the input unchanged.
    if not marker_rows:
        return [[int(x) for x in row] for row in g]

    # The marker's column interval is the vertical stripe.
    stripe_c0 = min(marker_cols)
    stripe_c1 = max(marker_cols) + 1  # exclusive

    # The object colour is the most frequent non-background, non-marker colour.
    # Background is the most frequent colour overall.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # Object colour: most frequent colour that is not background and not 4.
    obj = None
    best = -1
    for v, cnt in zip(vals, counts):
        if v != bg and v != 4:
            if cnt > best:
                best = cnt
                obj = int(v)

    out = g.copy()

    # 1) On rows congruent to 0 modulo 6, object cells become 3.
    if obj is not None:
        for r in range(0, h, 6):
            out[r, g[r] == obj] = 3

    # 2) Draw the vertical stripe:
    #    rows mod 6 == 0 -> 3
    #    rows mod 6 in {2, 4} -> 4
    #    odd rows -> background
    for r in range(h):
        m = r % 6
        if m == 0:
            out[r, stripe_c0:stripe_c1] = 3
        elif m in (2, 4):
            out[r, stripe_c0:stripe_c1] = 4
        else:
            out[r, stripe_c0:stripe_c1] = bg

    # 3) Restore the original marker cells (they are 4 in the input).
    for r, c in zip(marker_rows, marker_cols):
        out[r, c:c + 4] = 4

    return [[int(x) for x in row] for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Find the marker: all cells with colour 4.
    marker_cells = np.argwhere(g == 4)

    # If there is no marker, return the input unchanged.
    if len(marker_cells) == 0:
        return [[int(x) for x in row] for row in g]

    # Background is the most frequent colour.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # Object colour is the most frequent colour that is neither background nor marker.
    obj = None
    best = -1
    for v, cnt in zip(vals, counts):
        if v != bg and v != 4:
            if cnt > best:
                best = cnt
                obj = int(v)

    out = g.copy()

    rows = marker_cells[:, 0]
    cols = marker_cells[:, 1]

    # Determine marker orientation.
    horizontal = (rows.min() == rows.max())
    vertical = (cols.min() == cols.max())

    if horizontal:
        # Horizontal marker -> vertical stripe over the marker's columns.
        c0, c1 = int(cols.min()), int(cols.max())

        for r in range(h):
            m = r % 6
            if m == 0:
                if obj is not None:
                    out[r, g[r] == obj] = 3
                out[r, c0:c1 + 1] = 3
            elif m in (2, 4):
                out[r, c0:c1 + 1] = 4
            else:
                out[r, c0:c1 + 1] = bg

    elif vertical:
        # Vertical marker -> horizontal stripe over the marker's rows.
        r0, r1 = int(rows.min()), int(rows.max())

        for c in range(w):
            m = c % 6
            if m == 0:
                if obj is not None:
                    out[g[:, c] == obj, c] = 3
                out[r0:r1 + 1, c] = 3
            elif m in (2, 4):
                out[r0:r1 + 1, c] = 4
            else:
                out[r0:r1 + 1, c] = bg

    else:
        # Fallback for unexpected marker shapes: use bounding-box stripe.
        r0, r1 = int(rows.min()), int(rows.max())
        c0, c1 = int(cols.min()), int(cols.max())
        for r in range(h):
            m = r % 6
            if m == 0:
                if obj is not None:
                    out[r, g[r] == obj] = 3
                out[r, c0:c1 + 1] = 3
            elif m in (2, 4):
                out[r, c0:c1 + 1] = 4
            else:
                out[r, c0:c1 + 1] = bg

    # Preserve the original marker cells.
    for r, c in marker_cells:
        out[r, c] = 4

    return [[int(x) for x in row] for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # A row is a "solid" row if, ignoring the left 6/7 border,
    # it consists of exactly one repeated colour.
    def solid_color(row):
        vals = [int(c) for c in row[2:] if int(c) != 7]
        if not vals:
            return None
        if all(v == vals[0] for v in vals):
            return vals[0]
        return None

    # Mark separator rows that lie between two solid rows of the same colour.
    marked = [False] * h
    for r in range(h):
        if solid_color(g[r]) is not None:
            continue
        if 0 < r < h - 1:
            a = solid_color(g[r - 1])
            b = solid_color(g[r + 1])
            if a is not None and a == b:
                marked[r] = True

    # For each marked row, move its left 6 to the rightmost 7 in that row.
    # If the rightmost cell is not 7, the 6 is simply removed.
    for r in range(h):
        if not marked[r]:
            continue
        row = out[r]
        six_cols = np.where(row == 6)[0]
        if len(six_cols) == 0:
            continue
        six_col = int(six_cols[0])

        seven_cols = np.where(g[r] == 7)[0]
        if len(seven_cols) > 0:
            target = int(seven_cols[-1])
            out[r, target] = 6
        out[r, six_col] = 7

    # Boundary solid rows: if the row above/below is a separator row,
    # add a 6 just before the final 7 at the right edge.
    for r in (0, h - 1):
        if solid_color(g[r]) is None:
            continue
        if r == 0:
            if h > 1 and solid_color(g[1]) is None:
                row = out[r]
                if row[-1] == 7 and row[-2] == 7:
                    out[r, w - 2] = 6
        else:
            if h > 1 and solid_color(g[h - 2]) is None:
                row = out[r]
                if row[-1] == 7 and row[-2] == 7:
                    out[r, w - 2] = 6

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # 1) Replace every horizontal 777 block by 868.
    for r in range(h):
        c = 0
        while c < w:
            if c + 2 < w and g[r, c] == 7 and g[r, c + 1] == 7 and g[r, c + 2] == 7:
                out[r, c] = 8
                out[r, c + 1] = 6
                out[r, c + 2] = 8
                c += 3
            else:
                c += 1

    # 2) Propagate the center 6 vertically to the rows immediately above/below.
    for r in range(h):
        for c in range(w):
            if out[r, c] == 6:
                if r > 0:
                    out[r - 1, c] = 6
                if r + 1 < h:
                    out[r + 1, c] = 6

    # 3) Determine which original 3 endpoints survive.
    #    A 3 survives iff it is not in the top row and the cell directly below
    #    it is not a 6.
    for r in range(h):
        for c in range(w):
            if g[r, c] == 3:
                if r > 0 and out[r + 1, c] == 6:
                    out[r, c] = 8
                # otherwise it remains 3

    # 4) Add new 3s immediately to the right of 0 holes in rows that originally
    #    contained a 3 endpoint.
    for r in range(h):
        if 3 in g[r]:
            for c in range(w - 1):
                if g[r, c] == 0 and g[r, c + 1] == 8:
                    out[r, c + 1] = 3

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # 1) Every horizontal 777 becomes 868.
    for r in range(h):
        c = 0
        while c < w:
            if c + 2 < w and g[r, c] == 7 and g[r, c + 1] == 7 and g[r, c + 2] == 7:
                out[r, c] = 8
                out[r, c + 1] = 6
                out[r, c + 2] = 8
                c += 3
            else:
                c += 1

    # 2) The center 6 of each 868 propagates vertically to the rows above/below.
    for r in range(h):
        for c in range(w):
            if out[r, c] == 6:
                if r > 0:
                    out[r - 1, c] = 6
                if r + 1 < h:
                    out[r + 1, c] = 6

    # 3) Keep original 3 endpoints only when the nearest 777 center is above.
    #    If the nearest center is below (or there is no above center), turn it to 8.
    for r in range(h):
        for c in range(w):
            if g[r, c] == 3:
                best_above = None
                best_below = None

                if r > 0:
                    for cc in range(w):
                        if g[r - 1, cc] == 7:
                            d = abs(c - cc)
                            if best_above is None or d < best_above[0]:
                                best_above = (d, cc)

                if r + 1 < h:
                    for cc in range(w):
                        if g[r + 1, cc] == 7:
                            d = abs(c - cc)
                            if best_below is None or d < best_below[0]:
                                best_below = (d, cc)

                keep = False
                if best_above is not None:
                    if best_below is None:
                        keep = True
                    else:
                        keep = best_above[0] <= best_below[0]

                if not keep:
                    out[r, c] = 8

    # 4) Add new 3s next to surviving endpoints / 0 gaps / bottom-row edges
    #    when the nearest 777 center above is within distance 4.
    for r in range(h):
        if r == 0:
            continue

        # Candidate positions:
        # - one cell inward from an original 3 that survived
        # - one cell inward from a 0 gap
        # - bottom-row left/right edges
        candidates = set()

        for c in range(w):
            if g[r, c] == 3 and out[r, c] == 3:
                if c > 0:
                    candidates.add((r, c - 1))
                if c + 1 < w:
                    candidates.add((r, c + 1))

            if g[r, c] == 0:
                if c > 0:
                    candidates.add((r, c - 1))
                if c + 1 < w:
                    candidates.add((r, c + 1))

        if r == h - 1:
            candidates.add((r, 0))
            candidates.add((r, w - 1))

