                continue

            # Find nearest 777 center in the row above.
            best = None
            for c2 in range(w):
                if g[rr - 1, c2] == 7:
                    d = abs(cc - c2)
                    if best is None or d < best[0]:
                        best = (d, c2)

            if best is not None and best[0] <= 4:
                out[rr, cc] = 3

    return out.tolist()

