    w = len(grid[0])

    # Find the vertical separator made of 4s.
    sep = None
    for c in range(w):
        if all(grid[r][c] == 4 for r in range(h)):
            sep = c
            break
    if sep is None:
        sep = w // 2

    # Find the 5 marker on the right side.
    start_x = 0
    for r in range(h):
        for c in range(sep + 1, w):
            if grid[r][c] == 5:
                start_x = c - (sep + 1)
                break
        if start_x is not None:
            break

    # Number of 3-row blocks vertically.
    groups = (h + 3) // 4

    # Read blocks column-major: left column top-to-bottom, then right column.
    seq = []
    for side in (0, 1):
        c0 = 0 if side == 0 else 4
        for g in range(groups):
            r0 = 3 * g
            color = 0
            for r in range(r0, r0 + 3):
                for c in range(c0, c0 + 3):
                    if grid[r][c] != 0:
                        color = grid[r][c]
                        break
                if color:
                    break
            seq.append(color)

    # Segment lengths by color.
    length = {1: 3, 2: 2, 3: 4, 6: 2}

    out = [[0] * 7 for _ in range(h)]
    out[0][start_x] = 5

    r, c = 0, start_x
    direction = 0  # 0=down, 1=right, 2=up, 3=left

    for color in seq:
        if color == 6:
            # Vertical segment: continue down for 2 cells.
            for _ in range(2):
                r += 1
                out[r][c] = 6
        else:
            # Horizontal segment: turn right, then move left/right.
            direction = (direction + 1) % 4
            if direction == 1:
                for _ in range(length[color]):
                    c += 1
                    out[r][c] = color
            else:
                for _ in range(length[color]):
                    c -= 1
                    out[r][c] = color

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])

    # Find the vertical separator made of 4s.
    sep = None
    for c in range(w):
        if all(grid[r][c] == 4 for r in range(h)):
            sep = c
            break
    if sep is None:
        sep = w // 2

    out_w = w - sep - 1

    # Find the starting 5 on the right side.
    start_r, start_c = 0, 0
    found = False
    for r in range(h):
        for c in range(sep + 1, w):
            if grid[r][c] == 5:
                start_r = r
                start_c = c - (sep + 1)
                found = True
                break
        if found:
            break

    # Read the 3x3 instruction blocks in column-major order.
    block_rows = (h + 3) // 4
    block_cols = (sep + 3) // 4
    seq = []

    for b in range(block_cols):
        for g in range(block_rows):
            r0 = 3 * g
            c0 = 4 * b
            color = 0
            for r in range(r0, min(r0 + 3, h)):
                for c in range(c0, min(c0 + 3, sep)):
                    if grid[r][c] != 0:
                        color = grid[r][c]
                        break
                if color:
                    break
            if color != 0:
                seq.append(color)

    out = [[0] * out_w for _ in range(h)]

    if 0 <= start_r < h and 0 <= start_c < out_w:
        out[start_r][start_c] = 5

    r, c = start_r, start_c

    for color in seq:
        if color == 6:
            # Vertical segment: two cells downward.
            for _ in range(2):
                r += 1
                if 0 <= r < h and 0 <= c < out_w:
                    out[r][c] = 6

        elif color in (1, 2, 3):
            # Horizontal segment: one cell down, then left/right.
            r += 1
            if 0 <= r < h and 0 <= c < out_w:
                out[r][c] = color

            if color == 1:
                steps, dc = 2, 1
            elif color == 2:
                steps, dc = 1, -1
            else:  # color == 3
                steps, dc = 3, -1

            for _ in range(steps):
                c += dc
                if 0 <= r < h and 0 <= c < out_w:
                    out[r][c] = color

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Background is the most frequent colour.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    out = g.copy()

    # 4-connected components of non-background cells.
    seen = np.zeros((h, w), dtype=bool)
    for r in range(h):
        for c in range(w):
            if seen[r, c] or g[r, c] == bg:
                continue

            color = g[r, c]
            stack = [(r, c)]
            seen[r, c] = True
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w:
                        if not seen[ny, nx] and g[ny, nx] == color:
                            seen[ny, nx] = True
                            stack.append((ny, nx))

            ys = [p[0] for p in cells]
            xs = [p[1] for p in cells]
            r0, r1 = min(ys), max(ys)
            c0, c1 = min(xs), max(xs)

            # If the component is already a solid rectangle, leave it unchanged.
            if len(cells) == (r1 - r0 + 1) * (c1 - c0 + 1):
                continue

            # Otherwise, keep only the cells that lie on the border of the
            # component's bounding box.
            for y, x in cells:
                if y not in (r0, r1) and x not in (c0, c1):
                    out[y, x] = bg

    return out.tolist()

