from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Background is the most frequent colour.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # Connected components of non-background cells (4-connectivity).
    seen = np.zeros((h, w), dtype=bool)
    comps = []
    for r in range(h):
        for c in range(w):
            if g[r, c] != bg and not seen[r, c]:
                q = deque([(r, c)])
                seen[r, c] = True
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w:
                            if not seen[ny, nx] and g[ny, nx] != bg:
                                seen[ny, nx] = True
                                q.append((ny, nx))
                comps.append(cells)

    # Anchor components are single non-background pixels.
    anchors = [cells[0] for cells in comps if len(cells) == 1]
    if not anchors:
        return [list(row) for row in g]

    # For every non-anchor component, find its unique marker pixel:
    # a colour that appears exactly once in the component and has an anchor.
    out = g.copy()
    anchor_by_color = {}
    for ar, ac in anchors:
        anchor_by_color[int(g[ar, ac])] = (ar, ac)

    for cells in comps:
        if len(cells) == 1:
            continue

        color_counts = {}
        for r, c in cells:
            color_counts[int(g[r, c])] = color_counts.get(int(g[r, c]), 0) + 1

        marker = None
        for r, c in cells:
            col = int(g[r, c])
            if color_counts[col] == 1 and col in anchor_by_color:
                marker = (r, c)
                break
        if marker is None:
            continue

        mr, mc = marker
        ar, ac = anchor_by_color[int(g[mr, mc])]

        # Move along the axis with smaller distance; ties go vertical.
        dr = ar - mr
        dc = ac - mc
        if abs(dr) <= abs(dc):
            shift = (dr, 0)
        else:
            shift = (0, dc)

        sr, sc = shift
        if sr == 0 and sc == 0:
            continue

        # Copy the component to its shifted position.
        for r, c in cells:
            nr, nc = r + sr, c + sc
            if 0 <= nr < h and 0 <= nc < w:
                out[nr, nc] = g[r, c]

        # Remove the component from its original position.
        for r, c in cells:
            out[r, c] = bg

    return [list(row) for row in out]

