def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Find the two 5-marker components.
    mask5 = (g == 5)
    if not mask5.any():
        return []

    seen = np.zeros_like(mask5, dtype=bool)
    comps = []
    for r in range(h):
        for c in range(w):
            if mask5[r, c] and not seen[r, c]:
                stack = [(r, c)]
                seen[r, c] = True
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < h and 0 <= nx < w and mask5[ny, nx] and not seen[ny, nx]:
                                seen[ny, nx] = True
                                stack.append((ny, nx))
                comps.append(cells)

    if len(comps) < 2:
        return []

    # Use the two largest marker components.
    comps.sort(key=len, reverse=True)
    a, b = comps[0], comps[1]

    def bbox(cells):
        rs = [p[0] for p in cells]
        cs = [p[1] for p in cells]
        return min(rs), max(rs), min(cs), max(cs)

    ar0, ar1, ac0, ac1 = bbox(a)
    br0, br1, bc0, bc1 = bbox(b)

    # The marker bounding box defines the output size.
    out_h = max(ar1, br1) - min(ar0, br0) + 1
    out_w = max(ac1, bc1) - min(ac0, bc1) + 1

    # Choose the dominant non-background, non-marker colour.
    counts = {}
    for r in range(h):
        for c in range(w):
            v = g[r, c]
            if v != 0 and v != 5:
                counts[v] = counts.get(v, 0) + 1

    if not counts:
        return [[0] * out_w for _ in range(out_h)]

    target = max(counts, key=lambda k: counts[k])

    # Collect all cells of the target colour.
    pts = [(r, c) for r in range(h) for c in range(w) if g[r, c] == target]

    # Project these cells onto the marker bounding-box axes.
    # The output is the occupied projection pattern, filled with the target colour.
    out = np.zeros((out_h, out_w), dtype=int)

    min_r = min(ar0, br0)
    min_c = min(ac0, bc1)

    for r, c in pts:
        # Map the point into the marker bounding box coordinate system.
        # If it lies outside, clamp to the nearest edge; this produces the
        # compact "shadow" seen in the examples.
        rr = r - min_r
        cc = c - min_c
        if 0 <= rr < out_h and 0 <= cc < out_w:
            out[rr, cc] = 1

    # If direct projection is empty, fall back to a row/column histogram
    # aligned with the marker bounding box.
    if not out.any():
        rows = [r - min_r for r, c in pts]
        cols = [c - min_c for r, c in pts]
        for rr in rows:
            if 0 <= rr < out_h:
                out[rr, 0] = 1
        for cc in cols:
            if 0 <= cc < out_w:
                out[0, cc] = 1

    out[out == 1] = target
    return out.tolist()

import numpy as np
from collections import Counter

def transform(grid: list[list[int]]) -> list[list[int]]:
    a = np.array(grid, dtype=int)
    H, W = a.shape

    # Background is the most frequent colour (also the corner colour in the examples).
    bg = Counter(a.flat).most_common(1)[0][0]

    def is_bg_window(r, c, h, w):
        if r < 0 or c < 0 or r + h > H or c + w > W:
            return False
        return bool(np.all(a[r:r+h, c:c+w] == bg))

    # Find 5x5 solid non-background blocks.
    large = []
    for r in range(H - 4):
        for c in range(W - 4):
            block = a[r:r+5, c:c+5]
            vals = set(np.unique(block).tolist())
            if len(vals) == 1 and vals.pop() != bg:
                # Require a one-cell background margin so we pick isolated blocks.
                if is_bg_window(r-1, c-1, 7, 7):
                    large.append((r, c))

    if not large:
        return [row[:] for row in grid]

    # Find 3x3 pattern windows surrounded by background.
    patterns = {}
    for r in range(H - 2):
        for c in range(W - 2):
            if not is_bg_window(r-1, c-1, 5, 5):
                continue
            win = a[r:r+3, c:c+3]
            vals = set(np.unique(win).tolist())
            if bg in vals and len(vals) == 2:
                col = next(v for v in vals if v != bg)
                # Keep the first pattern for each colour.
                patterns.setdefault(col, win)

    # Output canvas is the bounding box of all large blocks, expanded by one cell.
    min_r = min(r for r, c in large)
    max_r = max(r + 4 for r, c in large)
    min_c = min(c for r, c in large)
    max_c = max(c + 4 for r, c in large)

    out_r0 = max(0, min_r - 1)
    out_r1 = min(H - 1, max_r + 1)
    out_c0 = max(0, min_c - 1)
    out_c1 = min(W - 1, max_c + 1)

    out = np.full((out_r1 - out_r0 + 1, out_c1 - out_c0 + 1), bg, dtype=int)

    for r, c in large:
        col = int(a[r, c])
        rr = r - out_r0
        cc = c - out_c0

        # 5x5 border of the block colour.
        out[rr:rr+5, cc:cc+5] = col

        # Interior is the matching 3x3 pattern with block colour and background swapped.
        if col in patterns:
            pat = patterns[col]
            for i in range(3):
                for j in range(3):
                    v = int(pat[i, j])
                    if v == col:
                        out[rr+1+i, cc+1+j] = bg
                    elif v == bg:
                        out[rr+1+i, cc+1+j] = col
                    else:
                        out[rr+1+i, cc+1+j] = v

    return out.tolist()

import numpy as np
from collections import Counter

def transform(grid: list[list[int]]) -> list[list[int]]:
    a = np.array(grid, dtype=int)
    H, W = a.shape

    # Background is the most frequent colour (also the corner colour in the examples).
    bg = Counter(a.flat).most_common(1)[0][0]

    def is_bg_window(r, c, h, w):
        if r < 0 or c < 0 or r + h > H or c + w > W:
            return False
        return bool(np.all(a[r:r+h, c:c+w] == bg))

    # Find isolated 5x5 solid non-background blocks.
    large = []
    for r in range(H - 4):
        for c in range(W - 4):
            block = a[r:r+5, c:c+5]
            vals = set(np.unique(block).tolist())
            if len(vals) == 1 and vals.pop() != bg:
                # Require a one-cell background margin so we pick isolated blocks.
                if is_bg_window(r-1, c-1, 7, 7):
                    large.append((r, c))

    if not large:
        return [row[:] for row in grid]

    # Find isolated 3x3 pattern windows containing exactly background and one other colour.
    patterns = {}
    for r in range(H - 2):
        for c in range(W - 2):
            if not is_bg_window(r-1, c-1, 5, 5):
                continue
            win = a[r:r+3, c:c+3]
            vals = set(np.unique(win).tolist())
            if bg in vals and len(vals) == 2:
                col = next(v for v in vals if v != bg)
                # Keep the first pattern for each colour.
                patterns.setdefault(col, win)

    # Output canvas is the bounding box of all large blocks, expanded by one cell.
    min_r = min(r for r, c in large)
    max_r = max(r + 4 for r, c in large)
    min_c = min(c for r, c in large)
    max_c = max(c + 4 for r, c in large)

    out_r0 = max(0, min_r - 1)
    out_r1 = min(H - 1, max_r + 1)
    out_c0 = max(0, min_c - 1)
    out_c1 = min(W - 1, max_c + 1)

    out = np.full((out_r1 - out_r0 + 1, out_c1 - out_c0 + 1), bg, dtype=int)

    for r, c in large:
        col = int(a[r, c])
        rr = r - out_r0
        cc = c - out_c0

        # 5x5 border of the block colour.
        out[rr:rr+5, cc:cc+5] = col

        # Interior is the matching 3x3 pattern with block colour and background swapped.
        if col in patterns:
            pat = patterns[col]
            for i in range(3):
                for j in range(3):
                    v = int(pat[i, j])
                    if v == col:
                        out[rr+1+i, cc+1+j] = bg
                    elif v == bg:
                        out[rr+1+i, cc+1+j] = col
                    else:
                        out[rr+1+i, cc+1+j] = v

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Determine the dominant background colour.
    bg = int(np.bincount(g.ravel()).argmax())

    # Find all hollow rectangular frames.
    frames = []
    for c in range(10):
        if c == bg:
            continue
        mask = (g == c)
        for r in range(h):
            if mask[r, 0]:
                continue
            # top edge
            if not np.all(mask[r, 0:w]):
                continue
            # find bottom edge
            bottom = None
            for r2 in range(r + 1, h):
                if np.all(mask[r2, 0:w]):
                    bottom = r2
                    break
            if bottom is None or bottom - r < 3:
                continue
            # left/right edges
            if not np.all(mask[r:bottom + 1, 0]):
                continue
            if not np.all(mask[r:bottom + 1, w - 1]):
                continue
            # interior must be background
            interior = g[r + 1:bottom, 1:w - 1]
            if not np.all(interior == bg):
                continue
            frames.append((r, bottom, c))

    # Remove all non-background pixels outside the frames.
    out = g.copy()
    for r, b, c in frames:
        out[r:b + 1, 1:w - 1] = bg

    # For each frame, count connected components of non-background pixels
    # in the horizontal band of the frame, to the right of the frame.
    for r, b, c in frames:
        band = g[r:b + 1, w - 1:]
        seen = np.zeros(band.shape, dtype=bool)
        count = 0
        for i in range(band.shape[0]):
            for j in range(band.shape[1]):
                if seen[i, j] or band[i, j] == bg:
                    continue
                # BFS 4-connected component
                q = deque([(i, j)])
                seen[i, j] = True
                while q:
                    x, y = q.popleft()
                    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < band.shape[0] and 0 <= ny < band.shape[1]:
                            if not seen[nx, ny] and band[nx, ny] == band[i, j]:
                                seen[nx, ny] = True
                                q.append((nx, ny))
                count += 1

        # Place a unary counter in the centre row of the frame.
        mid = (r + b) // 2
        for k in range(min(count, 4)):
            col = w - 2 - 2 * k
            if 1 <= col <= w - 2:
                out[mid, col] = c

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Background is the most frequent colour.
    bg = int(np.bincount(g.ravel()).argmax())

    # Find all hollow rectangular frames.
    frames = []
    for c in range(10):
        if c == bg:
