        mask = (g == c)
        for r in range(h):
            if not np.all(mask[r, 0:w]):
                continue
            bottom = None
            for r2 in range(r + 1, h):
                if np.all(mask[r2, 0:w]):
                    bottom = r2
                    break
            if bottom is None or bottom - r < 3:
                continue
            if not np.all(mask[r:bottom + 1, 0]):
                continue
            if not np.all(mask[r:bottom + 1, w - 1]):
                continue
            interior = g[r + 1:bottom, 1:w - 1]
            if not np.all(interior == bg):
                continue
            frames.append((r, bottom, c))

    # Mark frame pixels so they are not counted as outside objects.
    frame_mask = np.zeros((h, w), dtype=bool)
    for r, b, c in frames:
        frame_mask[r:b + 1, 0:w] = True

    # Count 4-connected components of each colour outside all frames.
    counts = [0] * 10
    seen = np.zeros((h, w), dtype=bool)
    for r in range(h):
        for c in range(w):
            if seen[r, c] or g[r, c] == bg or frame_mask[r, c]:
                continue
            col = int(g[r, c])
            q = deque([(r, c)])
            seen[r, c] = True
            while q:
                x, y = q.popleft()
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < h and 0 <= ny < w:
                        if not seen[nx, ny] and g[nx, ny] == col:
                            seen[nx, ny] = True
                            q.append((nx, ny))
            counts[col] += 1

    # Build output: keep only frames, erase everything else.
    out = np.full((h, w), bg, dtype=int)
    for r, b, c in frames:
        out[r, 0:w] = c
        out[b, 0:w] = c
        out[r + 1:b, 0] = c
        out[r + 1:b, w - 1] = c

    # Write unary count in the middle row of each frame, right-aligned
    # in every-other-column slots.
    for r, b, c in frames:
        mid = (r + b) // 2
        n = min(counts[c], 4)
        for k in range(n):
            col = w - 2 - 2 * k
            if 1 <= col <= w - 2:
                out[mid, col] = c

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Candidate: a vertical run of one non-zero colour B,
    # immediately bounded above and below by the same non-zero colour A.
    # For each bounding colour A, choose the candidate run that is most
    # isolated horizontally from the other candidate runs bounded by A.
    # Ties are broken by the rightmost column.
    # The chosen run is recoloured to A.

    by_bound = {}

    for c in range(w):
        col = g[:, c]
        r = 0
        while r < h:
            if col[r] == 0:
                r += 1
                continue

            a = col[r]
            r2 = r + 1
            while r2 < h and col[r2] == 0:
                r2 += 1

            if r2 < h and col[r2] == a:
                top, bottom = r, r2
                interior = col[top + 1:bottom]
                if interior.size > 0:
                    if np.all(interior == interior[0]) and interior[0] != 0:
                        by_bound.setdefault(a, []).append((c, top, bottom))
                r = r2 + 1
            else:
                r = r2 if r2 < h else h

    for a, runs in by_bound.items():
        if len(runs) <= 1:
            continue

        cols = [c for c, _, _ in runs]
        best = None
        best_key = None

        for c, top, bottom in runs:
            nearest = min(abs(c - oc) for oc in cols if oc != c)
            key = (nearest, c)  # maximise isolation, then rightmost
            if best_key is None or key > best_key:
                best_key = key
                best = (c, top, bottom)

        if best is not None:
            c, top, bottom = best
            out[top + 1:bottom, c] = a

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Terminals: existing 6 cells and all 2 cells.
    terminals = set()
    for r in range(H):
        for c in range(W):
            if g[r, c] in (2, 6):
                terminals.add((r, c))

    # Free cells are 7 or 6; 2 cells are obstacles for the 6-network.
    free = np.zeros((H, W), dtype=bool)
    free[g == 7] = True
    free[g == 6] = True

    # Multi-source BFS from all terminals through free cells.
    dist = np.full((H, W), 10**9, dtype=int)
    q = deque()
    for (r, c) in terminals:
        if free[r, c]:
            dist[r, c] = 0
            q.append((r, c))

    while q:
        r, c = q.popleft()
        d = dist[r, c]
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if 0 <= nr < H and 0 <= nc < W and free[nr, nc] and dist[nr, nc] > d + 1:
                dist[nr, nc] = d + 1
                q.append((nr, nc))

    # Keep free cells that lie on at least one shortest path between two terminals.
    out = g.copy()
    for r in range(H):
        for c in range(W):
            if not free[r, c]:
                continue
            d = dist[r, c]
            if d == 0:
                continue
            on_shortest = False
            for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
                if 0 <= nr < H and 0 <= nc < W and free[nr, nc]:
                    if dist[nr, nc] == d - 1:
                        on_shortest = True
                        break
            if on_shortest:
                out[r, c] = 6

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Sources are the pre-existing 6 cells.
    sources = [(r, c) for r in range(H) for c in range(W) if g[r, c] == 6]
    if not sources:
        return g.tolist()

    # 2-cells are targets/obstacles; 6-cells are passable; 7-cells are passable.
    passable = (g == 7) | (g == 6)

    # Directed movement: left, right, down (never up).
    moves = ((0, -1), (0, 1), (1, 0))

    # Forward distances from sources.
    dist = np.full((H, W), 10**9, dtype=int)
    q = deque()
    for r, c in sources:
        dist[r, c] = 0
        q.append((r, c))

    while q:
        r, c = q.popleft()
        d = dist[r, c]
        for dr, dc in moves:
            nr, nc = r + dr, c + dc
            if 0 <= nr < H and 0 <= nc < W and passable[nr, nc] and dist[nr, nc] > d + 1:
                dist[nr, nc] = d + 1
                q.append((nr, nc))

    # Reverse distances from every 2-cell, using reversed moves: left, right, up.
    rdist = np.full((H, W), 10**9, dtype=int)
    q = deque()
    for r in range(H):
        for c in range(W):
            if g[r, c] == 2:
                rdist[r, c] = 0
                q.append((r, c))

    rmoves = ((0, -1), (0, 1), (-1, 0))
    while q:
        r, c = q.popleft()
        d = rdist[r, c]
        for dr, dc in rmoves:
            nr, nc = r + dr, c + dc
            if 0 <= nr < H and 0 <= nc < W and passable[nr, nc] and rdist[nr, nc] > d + 1:
                rdist[nr, nc] = d + 1
                q.append((nr, nc))

    out = g.copy()

    # A 7-cell becomes 6 iff it lies on at least one shortest directed path
    # from a source 6 to some 2-cell.
    for r in range(H):
        for c in range(W):
            if g[r, c] == 7 and dist[r, c] < 10**9 and rdist[r, c] < 10**9:
                # Check whether some neighbor on a shortest path continues toward a 2.
                for dr, dc in moves:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < H and 0 <= nc < W:
                        if g[nr, nc] == 2:
                            if dist[r, c] + 1 == rdist[r, c]:
                                out[r, c] = 6
                                break
                        elif passable[nr, nc]:
                            if dist[nr, nc] == dist[r, c] + 1 and rdist[nr, nc] == rdist[r, c] - 1:
                                out[r, c] = 6
                                break

    return out.tolist()

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Choose the axis: rows if more rows than columns contain >=2 nonzeros,
    # otherwise columns.
    row_counts = (g > 0).sum(axis=1)
    col_counts = (g > 0).sum(axis=0)
    horizontal = (row_counts >= 2).sum() > (col_counts >= 2).sum()

    out = np.zeros_like(g)

    if horizontal:
        max_idx = int(np.max(np.where((g > 0).any(axis=0))[0])) if (g > 0).any() else -1
        for r in range(h):
            row = g[r]
            nz = np.where(row > 0)[0]
            if len(nz) < 2:
                out[r, nz] = row[nz]
                continue

            # Period from the first two nonzero cells.
            p = int(nz[1] - nz[0])
            if p <= 0:
                p = 1

            # Candidate colors:
            # - color of the last nonzero cell
            # - colors of cells that lie on the same residue class as the first two
            last_color = int(row[nz[-1]])
            residue = int(nz[0] % p)
            on_residue = nz[(nz % p) == residue]
            colors = {last_color}
            for c in on_residue:
                colors.add(int(row[c]))

            # If there is a unique color on the residue class, use it;
            # otherwise use the last nonzero color.
            if len(colors) == 1:
                color = colors.pop()
            else:
                color = last_color

            for c in range(0, max_idx + 1):
                if c % p == residue:
                    out[r, c] = color

            # Preserve isolated cells not covered by the main progression.
            for c in nz:
                if c % p != residue:
                    out[r, c] = row[c]

    else:
        max_idx = int(np.max(np.where((g > 0).any(axis=1))[0])) if (g > 0).any() else -1
        for c in range(w):
            col = g[:, c]
            nz = np.where(col > 0)[0]
            if len(nz) < 2:
                out[nz, c] = col[nz]
                continue

            p = int(nz[1] - nz[0])
            if p <= 0:
                p = 1

            last_color = int(col[nz[-1]])
            residue = int(nz[0] % p)
            on_residue = nz[(nz % p) == residue]
            colors = {last_color}
            for r in on_residue:
                colors.add(int(col[r]))

            if len(colors) == 1:
                color = colors.pop()
            else:
                color = last_color

            for r in range(0, max_idx + 1):
                if r % p == residue:
                    out[r, c] = color

            for r in nz:
                if r % p != residue:
                    out[r, c] = col[r]

    return out.tolist()

import numpy as np
from collections import Counter

def _fill_line(line: list[int], length: int) -> list[int]:
    out = list(line)
    nz = [i for i, v in enumerate(line) if v != 0]
    if len(nz) < 2:
        return out

    # Find a repeated color and use the first two occurrences to define
    # an arithmetic progression.
    first_pair = None
    last_pos = {}
    for i, v in enumerate(line):
        if v == 0:
            continue
        if v in last_pos:
            first_pair = (v, last_pos[v], i)
            break
        last_pos[v] = i

    if first_pair is None:
        return out

    color, a, b = first_pair
    p = b - a
    if p <= 0:
        p = 1

    # All positions in this line that belong to the progression.
    positions = list(range(a, length, p))
    # Also include positions before `a` with the same residue, if any.
    if a % p != 0:
        positions = list(range(a % p, length, p))

    # Choose the fill color:
    # - if the progression contains another color, prefer the least frequent
    #   color on the progression (in the examples this is the singleton);
    # - otherwise use the repeated color.
    colors_on_progression = Counter(line[i] for i in positions if line[i] != 0)
    if not colors_on_progression:
        fill_color = color
    else:
        # If there is a unique least-frequent color, use it.
        min_count = min(colors_on_progression.values())
        candidates = [c for c, n in colors_on_progression.items() if n == min_count]
        if len(candidates) == 1:
            fill_color = candidates[0]
        else:
            # Tie-break: use the color at the farthest endpoint of the
            # progression if it is present, otherwise the repeated color.
            endpoints = [positions[0], positions[-1]]
            for ep in reversed(endpoints):
                if line[ep] != 0:
                    fill_color = line[ep]
                    break
            else:
                fill_color = color

    for i in positions:
        out[i] = fill_color

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape

    row_counts = (g > 0).sum(axis=1)
    col_counts = (g > 0).sum(axis=0)

    # Process along the axis that has more lines containing at least two
    # non-zero cells.
    horizontal = (row_counts >= 2).sum() >= (col_counts >= 2).sum()

    if horizontal:
        return [_fill_line(g[r].tolist(), w) for r in range(h)]
    else:
        out = np.zeros_like(g)
        for c in range(w):
            filled = _fill_line(g[:, c].tolist(), h)
            out[:, c] = filled
        return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Locate the 6.
    start = None
    for r in range(h):
        for c in range(w):
            if g[r, c] == 6:
                start = (r, c)
                break
        if start is not None:
            break

    if start is None:
        return [[int(x) for x in row] for row in g]

    sr, sc = start

    # The relevant region is the 4-connected component of 8-cells
    # adjacent to the 6.  The 6 itself is not recolored.
    region = np.zeros((h, w), dtype=bool)
    q = deque()

    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
        nr, nc = sr + dr, sc + dc
        if 0 <= nr < h and 0 <= nc < w and g[nr, nc] == 8 and not region[nr, nc]:
            region[nr, nc] = True
            q.append((nr, nc))

    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and not region[nr, nc] and g[nr, nc] == 8:
                region[nr, nc] = True
                q.append((nr, nc))

    # Boundary of that region: region cells that touch, in the 8-neighborhood,
    # a cell outside the region (including 1s, 6, other 8s, or the grid edge).
    boundary = np.zeros((h, w), dtype=bool)

    for r in range(h):
        for c in range(w):
            if not region[r, c]:
                continue

            is_boundary = False
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if not (0 <= nr < h and 0 <= nc < w):
                        is_boundary = True
                        break
                    if not region[nr, nc]:
                        is_boundary = True
                        break
                if is_boundary:
                    break

            if is_boundary:
                boundary[r, c] = True

    out = g.copy()
    out[region & boundary] = 7

    return [[int(x) for x in row] for row in out]

import numpy as np
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    a = np.array(grid, dtype=int)
    h, w = a.shape

    # Background is the border colour that is most common overall.
    border_colors = set(a[0, :].tolist()) | set(a[-1, :].tolist()) | \
                    set(a[:, 0].tolist()) | set(a[:, -1].tolist())
    counts = np.bincount(a.ravel(), minlength=10)
    bg = max(border_colors, key=lambda c: counts[c])

    # The fill colour is the unique non-background colour.
    # If several exist, choose the one closest to the grid centre.
    unique = [c for c in range(10) if c != bg and counts[c] == 1]
    if not unique:
        return a.tolist()

    def center_dist(c):
        ys, xs = np.where(a == c)
        return (ys[0] - (h - 1) / 2.0) ** 2 + (xs[0] - (w - 1) / 2.0) ** 2

    fill = min(unique, key=center_dist)

    out = a.copy()

    # Flood-fill every background component that is not connected to the border.
    visited = np.zeros((h, w), dtype=bool)

    for r in range(h):
        for c in range(w):
            if a[r, c] == bg and not visited[r, c]:
                q = deque([(r, c)])
                visited[r, c] = True
                comp = []
                touches_border = (r == 0 or r == h - 1 or c == 0 or c == w - 1)

                while q:
                    y, x = q.popleft()
                    comp.append((y, x))

                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and not visited[ny, nx] and a[ny, nx] == bg:
                            visited[ny, nx] = True
                            if ny == 0 or ny == h - 1 or nx == 0 or nx == w - 1:
