        r2, c2 = p2
        dr = r2 - r1
        dc = c2 - c1
        steps = max(abs(dr), abs(dc))
        if steps == 0:
            out[r1][c1] = color
            return
        for i in range(steps + 1):
            r = r1 + dr * i / steps
            c = c1 + dc * i / steps
            # round to nearest integer cell
            rr = int(round(r))
            cc = int(round(c))
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color

    # Group input pixels by color
    colors = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                colors.setdefault(grid[r][c], []).append((r, c))

