            continue
        if len(pts) == 1:
            continue
        if len(pts) == 2:
            draw_line(pts[0], pts[1], color)
            continue

        # Sort points by angle around their centroid
        cr = sum(p[0] for p in pts) / len(pts)
        cc = sum(p[1] for p in pts) / len(pts)
        pts_sorted = sorted(pts, key=lambda p: math.atan2(p[0] - cr, p[1] - cc))

        # Draw closed polygon
        for i in range(len(pts_sorted)):
            draw_line(pts_sorted[i], pts_sorted[(i + 1) % len(pts_sorted)], color)

