            cc = sum(p[1] for p in eights) / len(eights)
            eights_sorted = sorted(eights, key=lambda p: math.atan2(p[0] - cr, p[1] - cc))
            for i in range(len(eights_sorted) - 1):
                draw_line(eights_sorted[i], eights_sorted[i + 1], 8)
        elif len(eights) == 1:
            r8, c8 = eights[0]
            non8 = [p for col, pts in colors.items() if col != 8 for p in pts]
            if non8:
                min_r = min(p[0] for p in non8)
                max_r = max(p[0] for p in non8)
                min_c = min(p[1] for p in non8)
                max_c = max(p[1] for p in non8)
