def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Collect connected components of non-zero cells (8-connectivity).
    seen = np.zeros((h, w), dtype=bool)
    components = []
    for r in range(h):
        for c in range(w):
            if g[r, c] != 0 and not seen[r, c]:
                color = g[r, c]
                stack = [(r, c)]
                seen[r, c] = True
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            if dy == 0 and dx == 0:
                                continue
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < h and 0 <= nx < w:
                                if not seen[ny, nx] and g[ny, nx] == color:
                                    seen[ny, nx] = True
                                    stack.append((ny, nx))
                components.append((color, cells))

    def add_line(r0, c0, dr, dc, color):
        r, c = r0, c0
        while 0 <= r < h and 0 <= c < w:
            if out[r, c] == 0:
                out[r, c] = color
            r += dr
            c += dc

    for color, cells in components:
        rows = [r for r, _ in cells]
        cols = [c for _, c in cells]
        rmin, rmax = min(rows), max(rows)
        cmin, cmax = min(cols), max(cols)
        height = rmax - rmin + 1
        width = cmax - cmin + 1

        # 2x2 corner missing top-left:
        #   . X
        #   X X
        if height == 2 and width == 2 and len(cells) == 3:
            if (rmin, cmin) not in cells and (rmin, cmax) in cells:
                add_line(rmax, cmax, 1, 1, color)
            continue

        # Vertical line: emit down-right from top cell.
        if height > 1 and width == 1:
            add_line(rmin, cmin, 1, 1, color)
            continue

        # Horizontal line:
        #   if it is the lowest horizontal component, emit up-right from left end;
        #   otherwise emit down-right from left end.
        if width > 1 and height == 1:
            if rmin == rmax:
                # Determine whether this is the lowest horizontal component.
                lowest = True
                for color2, cells2 in components:
                    if color2 != color:
                        rows2 = [r for r, _ in cells2]
                        cols2 = [c for _, c in cells2]
                        if max(rows2) - min(rows2) + 1 == 1 and len(cols2) > 1:
                            if max(rows2) > rmin:
                                lowest = False
                                break
                if lowest:
                    add_line(rmin, cmin, -1, 1, color)
                else:
                    add_line(rmin, cmin, 1, 1, color)
            continue

    return out.tolist()

