        r, c = r0, c0
        while 0 <= r < h and 0 <= c < w:
            if out[r, c] == 0:
                out[r, c] = color
            r += dr
            c += dc

    # For each component, emit one diagonal ray.
    for color, cells in components:
        rows = [r for r, _ in cells]
        cols = [c for _, c in cells]
        rmin, rmax = min(rows), max(rows)
        cmin, cmax = min(cols), max(cols)
        height = rmax - rmin + 1
        width = cmax - cmin + 1

        # 2x2 L triomino: emit from the filled corner opposite the missing cell.
        if height == 2 and width == 2 and len(cells) == 3:
            if (rmin, cmin) not in cells:          # missing top-left
                add_line(rmax, cmax, 1, 1, color)
            elif (rmin, cmax) not in cells:        # missing top-right
                add_line(rmax, cmin, 1, -1, color)
            elif (rmax, cmin) not in cells:        # missing bottom-left
                add_line(rmin, cmax, -1, 1, color)
            else:                                  # missing bottom-right
                add_line(rmin, cmin, -1, -1, color)
            continue

