def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Count 1s that are not already inside a U-shaped frame.
    # A U-shaped frame for a color c has:
    #   - a bottom row of c spanning [left, right]
    #   - a left vertical side of c from some top row to the bottom row
    #   - a right vertical side of c from some top row to the bottom row
    # The interior is rows max(left_top, right_top) .. bottom-1,
    # and columns left+1 .. right-1.
    def interior_cells():
        cells = set()
        for c in range(1, 10):
            if c == 1:
                continue
            for bottom in range(h):
                for left in range(w):
                    if g[bottom, left] != c:
                        continue
                    right = left
                    while right + 1 < w and g[bottom, right + 1] == c:
                        right += 1
                    if right <= left + 1:
                        continue

                    # left side
                    left_top = bottom
                    while left_top - 1 >= 0 and g[left_top - 1, left] == c:
                        left_top -= 1

                    # right side
                    right_top = bottom
                    while right_top - 1 >= 0 and g[right_top - 1, right] == c:
                        right_top -= 1

                    top = max(left_top, right_top)
                    for r in range(top, bottom):
                        for col in range(left + 1, right):
                            cells.add((r, col))
        return cells

    inside = interior_cells()

    # Fill empty interior cells with 1.
    out = g.copy()
    added = 0
    for r, c in inside:
        if out[r, c] == 0:
            out[r, c] = 1
            added += 1

    # Remove the same number of 1s from the topmost positions.
    if added:
        ones = [(r, c) for r in range(h) for c in range(w) if g[r, c] == 1]
        ones.sort()
        for r, c in ones[:added]:
            out[r, c] = 0

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Count non-zero colors.
    counts = {}
    for v in g.flat:
        if v != 0:
            counts[int(v)] = counts.get(int(v), 0) + 1

    if not counts:
        return [list(map(int, row)) for row in g]

    # The "structure" color is the most frequent non-zero color.
    struct = max(counts, key=lambda c: (counts[c], -c))

    # The two other colors are the remaining non-zero colors.
    other = [c for c in counts if c != struct]
    if len(other) < 2:
        return [list(map(int, row)) for row in g]
    a, b = sorted(other)[:2]

    # Find all 3x3 solid blocks of the structure color.
    blocks = []
    for r in range(h - 2):
        for c in range(w - 2):
            if (g[r:r + 3, c:c + 3] == struct).all():
                blocks.append((r, c))

    if not blocks:
        return [list(map(int, row)) for row in g]

    # Choose the 3x3 block whose center is closest to the structure's centroid.
    ys, xs = np.where(g == struct)
    cy, cx = ys.mean(), xs.mean()
    r0, c0 = min(blocks, key=lambda rc: (rc[0] + 1 - cy) ** 2 + (rc[1] + 1 - cx) ** 2)

    out = g.copy()

    # Keep the border of the chosen 3x3 block as the structure color.
    for dr in range(3):
        for dc in range(3):
            if dr in (0, 2) or dc in (0, 2):
                out[r0 + dr, c0 + dc] = struct

    # Remove the kept border so the remaining structure cells split into components.
    mask = (g == struct)
    for dr in range(3):
        for dc in range(3):
            if dr in (0, 2) or dc in (0, 2):
                mask[r0 + dr, c0 + dc] = False

    # For each remaining structure component, choose the nearer of the two other colors
    # by minimum Manhattan distance from any cell in the component to any cell of that color.
    visited = np.zeros((h, w), dtype=bool)
    for sr in range(h):
        for sc in range(w):
            if not mask[sr, sc] or visited[sr, sc]:
                continue

            q = deque([(sr, sc)])
            visited[sr, sc] = True
            comp = [(sr, sc)]
            while q:
                r, c = q.popleft()
                for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                    if 0 <= nr < h and 0 <= nc < w and mask[nr, nc] and not visited[nr, nc]:
                        visited[nr, nc] = True
                        comp.append((nr, nc))
                        q.append((nr, nc))

            da = min(abs(r - ar) + abs(c - ac)
                     for r, c in comp
                     for ar, ac in np.argwhere(g == a))
            db = min(abs(r - br) + abs(c - bc)
                     for r, c in comp
                     for br, bc in np.argwhere(g == b))

            fill = a if da <= db else b
            for r, c in comp:
                out[r, c] = fill

    # Center of the preserved 3x3 block: choose the nearer of the two other colors.
    cr, cc = r0 + 1, c0 + 1
    da = min(abs(cr - ar) + abs(cc - ac) for ar, ac in np.argwhere(g == a))
    db = min(abs(cr - br) + abs(cc - bc) for br, bc in np.argwhere(g == b))
    out[cr, cc] = a if da <= db else b

    return [list(map(int, row)) for row in out]

