            comp = []
            q = deque([(r, c)])
            seen[r][c] = True
            while q:
                cr, cc = q.popleft()
                comp.append((cr, cc))
                for dr, dc in dirs:
                    nr, nc = cr + dr, cc + dc
                    if in_bounds(nr, nc) and not seen[nr][nc] and g[nr, nc] in (1, 2):
                        seen[nr][nc] = True
                        q.append((nr, nc))

