            border_colors = set()
            for cr, cc in comp:
                for dr, dc in dirs:
                    nr, nc = cr + dr, cc + dc
                    if in_bounds(nr, nc) and g[nr, nc] not in (0, 1, 2):
                        border_colors.add(int(g[nr, nc]))

            if not border_colors:
                continue

            # Prefer a border color that is not 4 and appears most often around the block.
            counts = {}
            for cr, cc in comp:
                for dr, dc in dirs:
                    nr, nc = cr + dr, cc + dc
                    if in_bounds(nr, nc):
                        v = int(g[nr, nc])
                        if v not in (0, 1, 2, 4):
