                score = dr * d[0] + dc * d[1]
                if score > best_score:
                    best_score = score
                    best = d
            if best is not None:
                color_dir[border_color] = best

    # For each 4, determine its movement direction.
    # Use the direction of the wall color that first blocks it in the chosen direction.
    # If multiple colors are possible, choose the one whose blocking wall is closest.
    fours = [(r, c) for r in range(h) for c in range(w) if g[r, c] == 4]

    def is_wall(v):
        return v != 0 and v != 4

    moves = []
    for r, c in fours:
        candidates = []
        for d in dirs:
            if d not in color_dir.values():
                continue
            nr, nc = r + d[0], c + d[1]
            dist = 0
            while in_bounds(nr, nc) and not is_wall(g[nr, nc]):
                dist += 1
                nr += d[0]
                nc += d[1]
            if in_bounds(nr, nc) and is_wall(g[nr, nc]):
                wall_color = int(g[nr, nc])
                if color_dir.get(wall_color) == d:
                    # destination is just before the wall
                    dest_r = nr - d[0]
                    dest_c = nc - d[1]
                    candidates.append((dist, d, (dest_r, dest_c)))

        if not candidates:
            continue

        # Choose the direction with the closest valid blocking wall.
        # Ties are broken by direction order (down, down-right, right, ...).
        candidates.sort(key=lambda x: (x[0], dirs.index(x[1])))
        moves.append((r, c, candidates[0][2]))

    # Apply moves.
    for r, c in fours:
        out[r, c] = 0
    for r, c, (nr, nc) in moves:
        out[nr, nc] = 4

    return out.tolist()

import numpy as np
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Background is the most frequent colour.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    MOV = 2
    dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))

    # Connected components of 2s (4-connected).
    seen = np.zeros((h, w), dtype=bool)
    comps = []
    for r in range(h):
        for c in range(w):
            if g[r, c] == MOV and not seen[r, c]:
                q = deque([(r, c)])
                seen[r, c] = True
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy, dx in dirs:
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w:
                            if not seen[ny, nx] and g[ny, nx] == MOV:
                                seen[ny, nx] = True
                                q.append((ny, nx))
                comps.append(cells)

    # Static non-background, non-moving cells.
    static = (g != bg) & (g != MOV)

    # Bounding boxes of static objects.
    static_seen = np.zeros((h, w), dtype=bool)
    boxes = []
    for r in range(h):
        for c in range(w):
            if static[r, c] and not static_seen[r, c]:
                q = deque([(r, c)])
                static_seen[r, c] = True
                min_r = max_r = r
                min_c = max_c = c
                while q:
                    y, x = q.popleft()
                    min_r = min(min_r, y)
                    max_r = max(max_r, y)
                    min_c = min(min_c, x)
                    max_c = max(max_c, x)
                    for dy, dx in dirs:
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w:
                            if static[ny, nx] and not static_seen[ny, nx]:
                                static_seen[ny, nx] = True
                                q.append((ny, nx))
                boxes.append((min_r, max_r, min_c, max_c))

    def inside_any_box(y, x):
        for min_r, max_r, min_c, max_c in boxes:
            if min_r <= y <= max_r and min_c <= x <= max_c:
                return True
        return False

    out = g.copy()

    # Remove all original 2s; valid ones are redrawn.
    for cells in comps:
        for y, x in cells:
            out[y, x] = bg

    for cells in comps:
        best = None  # (distance, direction, final_cells, trail_cells)

        for dy, dx in dirs:
            ok = True
            final_cells = []
            trail_cells = []
            max_dist = 0

            for y, x in cells:
                ny, nx = y + dy, x + dx
                dist = 0

                # Move through background until the first static cell.
                while 0 <= ny < h and 0 <= nx < w and out[ny, nx] == bg:
                    trail_cells.append((ny, nx))
                    dist += 1
                    ny += dy
                    nx += dx

                if not (0 <= ny < h and 0 <= nx < w):
                    ok = False
                    break

                # The first obstacle must be static, and the cell beyond it
                # must also be static: a wall of thickness at least 2.
                if not static[ny, nx]:
                    ok = False
                    break

                by, bx = ny + dy, nx + dx
                if not (0 <= by < h and 0 <= bx < w) or not static[by, bx]:
                    ok = False
                    break

                # Final position is just before the first static cell.
                fy, fx = ny - dy, nx - dx
                final_cells.append((fy, fx))
                max_dist = max(max_dist, dist)

            if not ok:
                continue

            # The final position must be inside the bounding box of the
            # static object that provides the wall.
            if not all(inside_any_box(fy, fx) for fy, fx in final_cells):
                continue

            # The final position must not overlap a static cell.
            if any(static[fy, fx] for fy, fx in final_cells):
                continue

            cand = (max_dist, dy, dx, final_cells, trail_cells)
            if best is None or cand[0] < best[0]:
                best = cand

        if best is not None:
            _, _, _, final_cells, trail_cells = best
            for y, x in trail_cells:
                out[y, x] = 0
            for y, x in final_cells:
                out[y, x] = MOV

    return out.tolist()

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape

    row_sep = [r for r in range(H) if np.all(g[r] == 6)]
    col_sep = [c for c in range(W) if np.all(g[:, c] == 6)]

    if not row_sep and not col_sep:
        return [[int(x) for x in row] for row in g]

    def boundaries(seps, length):
        bounds = []
        prev = 0
        for s in seps:
            if s > prev:
                bounds.append((prev, s))
            prev = s + 1
        if prev < length:
            bounds.append((prev, length))
        return bounds

    row_bounds = boundaries(row_sep, H)
    col_bounds = boundaries(col_sep, W)

    n_rows = len(row_bounds)
    n_cols = len(col_bounds)

    blocks = np.empty((n_rows, n_cols, 5, 5), dtype=int)
    for i, (r0, r1) in enumerate(row_bounds):
        for j, (c0, c1) in enumerate(col_bounds):
            blocks[i, j] = g[r0:r1, c0:c1]

    # Row-major order of the block matrix after 90° clockwise rotation.
    rotated = np.rot90(blocks, k=-1)
    ordered = rotated.reshape(-1, 5, 5)

    if n_rows > n_cols:
        # Horizontal strip: blocks side by side, separated by one column of 6.
        out_cols = []
        for k, block in enumerate(ordered):
            if k > 0:
                out_cols.append(np.full((5, 1), 6, dtype=int))
            out_cols.append(block)
        out = np.hstack(out_cols)
    else:
        # Vertical strip: blocks stacked, separated by one row of 6.
        out_rows = []
        for k, block in enumerate(ordered):
            if k > 0:
                out_rows.append(np.full((1, 5), 6, dtype=int))
            out_rows.append(block)
        out = np.vstack(out_rows)

    return [[int(x) for x in row] for row in out]

