    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Determine background as the most frequent colour.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # Connected components (4-neighbourhood) of non-background cells.
    seen = np.zeros((h, w), dtype=bool)
    comps = []
    for r in range(h):
        for c in range(w):
            if g[r, c] != bg and not seen[r, c]:
                color = int(g[r, c])
                q = deque([(r, c)])
                seen[r, c] = True
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w:
                            if not seen[ny, nx] and g[ny, nx] == color:
                                seen[ny, nx] = True
                                q.append((ny, nx))
                ys = [p[0] for p in cells]
                xs = [p[1] for p in cells]
                comps.append({
                    "color": color,
                    "cells": cells,
                    "r0": min(ys), "r1": max(ys),
                    "c0": min(xs), "c1": max(xs),
                    "size": len(cells),
                })

    # Candidate pairs: two components of the same colour, each with size >= 2.
    pairs = []
    for i in range(len(comps)):
        for j in range(i + 1, len(comps)):
            a, b = comps[i], comps[j]
            if a["color"] == b["color"] and a["size"] >= 2 and b["size"] >= 2:
                r0 = min(a["r0"], b["r0"])
                r1 = max(a["r1"], b["r1"])
                c0 = min(a["c0"], b["c0"])
                c1 = max(a["c1"], b["c1"])
                area = (r1 - r0 + 1) * (c1 - c0 + 1)
                pairs.append((area, r0, r1, c0, c1, a["color"]))

    # Process larger rectangles first so nested fills are not overwritten.
    pairs.sort(reverse=True)

    for _, r0, r1, c0, c1, color in pairs:
        # Fill the bounding box with the pair colour, but do not overwrite
        # any non-background cell that already exists in the input.
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if g[r, c] == bg:
                    out[r, c] = color

    return out.tolist()

