        for rr in range(lr0, lr1 + 1):
            # Take the first two non-background cells in the row segment.
            row_vals = [int(g[rr, cc]) for cc in range(lc0, lc1 + 1) if g[rr, cc] != bg]
            if len(row_vals) >= 2:
                src, dst = row_vals[0], row_vals[1]
                mapping[src] = dst

    # Candidate rectangles: for each colour, use all components of size >= 2.
    # If there are at least two, take the pair with the largest bounding box.
    by_color = {}
