            for c in range(c0, c1 + 1):
                out[r, c] = fill

    # Preserve all original non-background cells.
    out[g != bg] = g[g != bg]

    return out.tolist()

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Collect all non-background colors.
    colors = [c for c in range(1, 10) if np.any(g == c)]

    # For every pair of colors, try to interpret one as the "frame"
    # and the other as the "inner" color.  The frame must be 8-connected
    # and must have a unique 1-cell-wide neck on one side of its bounding box.
    for frame in colors:
        for inner in colors:
            if frame == inner:
                continue

            frame_mask = (g == frame)
            inner_mask = (g == inner)

            if not np.any(frame_mask) or not np.any(inner_mask):
                continue

            # 8-connected components of the frame.
            visited = np.zeros_like(frame_mask, dtype=bool)
            components = []
            for r in range(h):
                for c in range(w):
                    if frame_mask[r, c] and not visited[r, c]:
                        stack = [(r, c)]
                        visited[r, c] = True
                        comp = []
                        while stack:
                            y, x = stack.pop()
                            comp.append((y, x))
                            for dy in (-1, 0, 1):
                                for dx in (-1, 0, 1):
                                    if dy == 0 and dx == 0:
                                        continue
                                    ny, nx = y + dy, x + dx
                                    if 0 <= ny < h and 0 <= nx < w:
                                        if frame_mask[ny, nx] and not visited[ny, nx]:
                                            visited[ny, nx] = True
                                            stack.append((ny, nx))
                        components.append(comp)

            for comp in components:
                if len(comp) < 3:
                    continue

                ys = [p[0] for p in comp]
                xs = [p[1] for p in comp]
                rmin, rmax = min(ys), max(ys)
                cmin, cmax = min(xs), max(xs)

                # Inner cells must lie strictly inside the frame's bounding box.
                inner_in_box = []
                for r in range(rmin + 1, rmax):
                    for c in range(cmin + 1, cmax + 1):
                        if inner_mask[r, c]:
                            inner_in_box.append((r, c))

                if not inner_in_box:
                    continue

                # Find a unique 1-cell-wide neck on one side of the bbox.
                neck = None
                if rmin > 0:
                    row = g[rmin, cmin:cmax + 1]
                    if np.sum(row == frame) == 1:
                        neck = ('up', rmin, cmin + int(np.argmax(row == frame)))
                if rmax + 1 < h:
                    row = g[rmax, cmin:cmax + 1]
                    if np.sum(row == frame) == 1:
                        neck = ('down', rmax, cmin + int(np.argmax(row == frame)))
                if cmin > 0:
                    col = g[rmin:rmax + 1, cmin]
                    if np.sum(col == frame) == 1:
                        neck = ('left', rmin + int(np.argmax(col == frame)), cmin)
                if cmax + 1 < w:
                    col = g[rmin:rmax + 1, cmax]
                    if np.sum(col == frame) == 1:
                        neck = ('right', rmin + int(np.argmax(col == frame)), cmax)

                if neck is None:
                    continue

                direction, nr, nc = neck

                # Remove all inner cells inside this frame component.
                for r, c in inner_in_box:
                    out[r, c] = 0

                # Project the removed inner cells onto the neck line.
                if direction == 'up' or direction == 'down':
                    line = sorted({r for r, c in inner_in_box})
                else:
                    line = sorted({c for r, c in inner_in_box})

                # Place them outside the frame, starting adjacent to the neck.
                if direction == 'up':
                    for i, r in enumerate(line):
                        rr = nr - 1 - i
                        if 0 <= rr < h:
                            out[rr, nc] = inner
                elif direction == 'down':
                    for i, r in enumerate(line):
                        rr = nr + 1 + i
                        if 0 <= rr < h:
                            out[rr, nc] = inner
                elif direction == 'left':
                    for i, c in enumerate(line):
                        cc = nc - 1 - i
                        if 0 <= cc < w:
                            out[nr, cc] = inner
                elif direction == 'right':
                    for i, c in enumerate(line):
                        cc = nc + 1 + i
                        if 0 <= cc < w:
                            out[nr, cc] = inner

    return out.tolist()

import numpy as np
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # 8-connected components of every non-background colour.
    visited = np.zeros((h, w), dtype=bool)
    components = []

    for r in range(h):
        for c in range(w):
            if g[r, c] != 0 and not visited[r, c]:
                color = g[r, c]
                q = deque([(r, c)])
                visited[r, c] = True
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            if dy == 0 and dx == 0:
                                continue
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < h and 0 <= nx < w:
                                if g[ny, nx] == color and not visited[ny, nx]:
                                    visited[ny, nx] = True
                                    q.append((ny, nx))
                components.append((color, cells))

    # For each component, if its bounding box has a one-cell side,
    # treat that side as the neck.  Move all non-background cells of
    # other colours inside the bounding box out through the neck.
    for color, cells in components:
        if len(cells) < 3:
            continue

        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        rmin, rmax = min(rs), max(rs)
        cmin, cmax = min(cs), max(cs)

        # Candidate necks: sides of the bounding box containing exactly
        # one cell of this component.
        necks = []

        top = [(r, c) for r, c in cells if r == rmin]
        if len(top) == 1:
            necks.append(('up', top[0][0], top[0][1], rmin))

        bottom = [(r, c) for r, c in cells if r == rmax]
        if len(bottom) == 1:
            necks.append(('down', bottom[0][0], bottom[0][1], rmax))

        left = [(r, c) for r, c in cells if c == cmin]
        if len(left) == 1:
            necks.append(('left', left[0][0], left[0][1], cmin))

        right = [(r, c) for r, c in cells if c == cmax]
        if len(right) == 1:
            necks.append(('right', right[0][0], right[0][1], cmax))

        if not necks:
            continue

        # Choose the neck with the most available space outside the grid edge.
        def space(n):
            direction, nr, nc, _ = n
            if direction == 'up':
                return nr
            if direction == 'down':
                return h - 1 - nr
            if direction == 'left':
                return nc
            if direction == 'right':
                return w - 1 - nc
            return 0

        necks.sort(key=space, reverse=True)
        direction, nr, nc, _ = necks[0]

        # Collect contents: non-background cells inside this component's
        # bounding box that are not the component colour.
        contents = []
        for r in range(rmin, rmax + 1):
            for c in range(cmin, cmax + 1):
                v = g[r, c]
                if v != 0 and v != color:
                    contents.append((r, c, v))

        if not contents:
            continue

        # Remove contents.
        for r, c, v in contents:
            out[r, c] = 0

        # Place them in a straight line outside the chosen neck.
        # Preserve the order by the coordinate along the neck line.
        if direction in ('up', 'down'):
            contents.sort(key=lambda x: x[0])
        else:
            contents.sort(key=lambda x: x[1])

        placed = 0
        for r, c, v in contents:
            if direction == 'up':
                rr = nr - 1 - placed
                if 0 <= rr < h:
                    out[rr, nc] = v
                    placed += 1
            elif direction == 'down':
                rr = nr + 1 + placed
                if 0 <= rr < h:
                    out[rr, nc] = v
                    placed += 1
            elif direction == 'left':
                cc = nc - 1 - placed
                if 0 <= cc < w:
                    out[nr, cc] = v
                    placed += 1
            elif direction == 'right':
                cc = nc + 1 + placed
                if 0 <= cc < w:
                    out[nr, cc] = v
                    placed += 1

    return out.tolist()

