            continue
        r2 = r
        while r2 + 1 < H and g[r2 + 1, 0] == border and g[r2 + 1, -1] == border:
            r2 += 1
        if r2 > r:
            interior = g[r + 1:r2, 1:-1]
            if interior.size:
                vals, counts = np.unique(interior, return_counts=True)
                if len(vals) == 1:
                    fill = int(vals[0])
                    if fill != border:
                        targets.append((r, r2, border, fill))
        r = r2 + 1

    # Find all non-background connected components in the input.
    # Background is the most common color.
    bg = int(np.bincount(g.ravel()).argmax())
    seen = np.zeros((H, W), dtype=bool)
    templates = []

    for i in range(H):
        for j in range(W):
            if seen[i, j] or g[i, j] == bg:
                continue
            color = int(g[i, j])
            q = deque([(i, j)])
            seen[i, j] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < H and 0 <= nx < W and not seen[ny, nx] and g[ny, nx] == color:
                        seen[ny, nx] = True
                        q.append((ny, nx))

            ys = [y for y, _ in cells]
            xs = [x for _, x in cells]
            y0, y1 = min(ys), max(ys)
            x0, x1 = min(xs), max(xs)
            h = y1 - y0 + 1
            w = x1 - x0 + 1

            # Templates are small compact objects, not the large target rectangles.
            if h <= 8 and w <= 8 and h * w <= 25:
                # Build a binary mask of the template's foreground color.
                mask = np.zeros((h, w), dtype=bool)
                for y, x in cells:
                    mask[y - y0, x - x0] = True
                templates.append((h, w, mask))

    # Remove all template pixels from the output.
    for h, w, mask in templates:
        # Re-find exact positions is unnecessary if we erase by matching masks;
        # simpler: erase all non-background pixels that are not inside targets.
        pass

    # Erase all non-background pixels outside target rectangles.
    in_target = np.zeros((H, W), dtype=bool)
    for r0, r1, border, fill in targets:
        in_target[r0:r1 + 1, :] = True
    for i in range(H):
        for j in range(W):
            if not in_target[i, j] and g[i, j] != bg:
                out[i, j] = bg

    # For each target, stamp each template that fits, using the target's
    # border/fill colors.  The examples correspond to placing templates from
    # left to right inside the target, starting near the left edge and bottom.
    for r0, r1, border, fill in targets:
        th = r1 - r0 + 1
        # Place templates in the order they appear in the input (top-to-bottom,
        # left-to-right).  This matches the examples.
        for h, w, mask in templates:
            if h > th or w > W - 2:
                continue

            # Try to find a placement where the template does not overlap the
            # outer border of the target and does not overlap previously stamped
            # template pixels.  Prefer the lowest possible row, then leftmost.
            placed = False
            for y in range(r0 + 1, r1 - h + 2):
                for x in range(1, W - w):
                    ok = True
                    for dy in range(h):
                        for dx in range(w):
                            if mask[dy, dx]:
                                if out[y + dy, x + dx] not in (fill, border):
                                    ok = False
                                    break
                        if not ok:
                            break
                    if ok:
                        for dy in range(h):
                            for dx in range(w):
                                if mask[dy, dx]:
                                    out[y + dy, x + dx] = border
                        placed = True
                        break
                if placed:
                    break

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    H, W = g.shape
    out = g.copy()

    # Background is the most frequent color.
    bg = int(np.bincount(g.ravel()).argmax())

    # Find full-width horizontal target bands:
    # consecutive rows whose first and last cells are the same border color,
    # and whose interior is a single fill color different from the border.
    targets = []
    r = 0
    while r < H:
        if g[r, 0] != g[r, -1]:
            r += 1
            continue
        border = int(g[r, 0])
        if border == bg:
            r += 1
            continue

        r2 = r
        while (
            r2 + 1 < H
            and g[r2 + 1, 0] == border
            and g[r2 + 1, -1] == border
        ):
            r2 += 1

        if r2 > r:
            interior = g[r + 1:r2, 1:-1]
            if interior.size:
                vals, counts = np.unique(interior, return_counts=True)
                if len(vals) == 1:
                    fill = int(vals[0])
                    if fill != border:
                        targets.append((r, r2, border, fill))
        r = r2 + 1

    # Mark cells belonging to target bands.
    in_target = np.zeros((H, W), dtype=bool)
    for r0, r1, border, fill in targets:
        in_target[r0:r1 + 1, :] = True

    # Find all monochromatic connected components outside target bands.
    seen = np.zeros((H, W), dtype=bool)
    components = []

    for i in range(H):
        for j in range(W):
            if seen[i, j] or g[i, j] == bg or in_target[i, j]:
                continue

            color = int(g[i, j])
            q = deque([(i, j)])
            seen[i, j] = True
            cells = []

            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (
                        0 <= ny < H
                        and 0 <= nx < W
                        and not seen[ny, nx]
                        and g[ny, nx] == color
                    ):
                        seen[ny, nx] = True
                        q.append((ny, nx))

            ys = [y for y, _ in cells]
            xs = [x for _, x in cells]
            y0, y1 = min(ys), max(ys)
            x0, x1 = min(xs), max(xs)
            h = y1 - y0 + 1
            w = x1 - x0 + 1

            mask = np.zeros((h, w), dtype=bool)
            for y, x in cells:
                mask[y - y0, x - x0] = True

            components.append((color, x0, h, w, mask))

    # Erase all non-background cells outside target bands.
    for i in range(H):
        for j in range(W):
            if not in_target[i, j] and g[i, j] != bg:
                out[i, j] = bg

    # Stamp each component into the target band whose fill color matches it.
    # Keep the same columns and height, align to the bottom of the band.
    for color, x0, h, w, mask in components:
        target = None
        for r0, r1, border, fill in targets:
            if fill == color:
                target = (r0, r1, border, fill)
                break

        if target is None:
            continue

        r0, r1, border, fill = target
        y0 = r1 - h + 1

        for dy in range(h):
            for dx in range(w):
                if mask[dy, dx]:
                    out[y0 + dy, x0 + dx] = border

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Connected components of 1s (4-connectivity)
    comp = np.full((h, w), -1, dtype=int)
    comps = []
    for r in range(h):
        for c in range(w):
            if g[r, c] == 1 and comp[r, c] == -1:
                cid = len(comps)
                stack = [(r, c)]
                comp[r, c] = cid
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w:
                            if g[ny, nx] == 1 and comp[ny, nx] == -1:
                                comp[ny, nx] = cid
                                stack.append((ny, nx))
                comps.append(cells)

    # Bounding boxes of 0 and 2 regions
    def bbox(mask):
        ys, xs = np.where(mask)
        if len(ys) == 0:
            return None
        return ys.min(), ys.max(), xs.min(), xs.max()

    b0 = bbox(g == 0)
    b2 = bbox(g == 2)

    out = g.copy()

    # Fill the 0 region with 1
    if b0 is not None:
        r0, r1, c0, c1 = b0
        out[r0:r1 + 1, c0:c1 + 1] = 1

    # Find the 1-component that is adjacent to the 0 region.
    target_comp = -1
    if b0 is not None:
        r0, r1, c0, c1 = b0
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                if dr == 0 and dc == 0:
                    continue
                for r in range(r0, r1 + 1):
                    for c in range(c0, c1 + 1):
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < h and 0 <= nc < w and comp[nr, nc] != -1:
                            target_comp = comp[nr, nc]
                            break
                    if target_comp != -1:
                        break
                if target_comp != -1:
                    break
            if target_comp != -1:
                break

    # In that component, find the 2x2 square of 1s that is a dead-end branch:
    # it has exactly one 1-neighbor outside the square.
    if target_comp != -1:
        cells = set(comps[target_comp])
        best = None
        best_score = None

        for r in range(h - 1):
            for c in range(w - 1):
                sq = [(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)]
                if all(p in cells for p in sq):
                    outside = set()
                    for y, x in sq:
                        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                            ny, nx = y + dy, x + dx
                            if (ny, nx) not in sq and (ny, nx) in cells:
                                outside.add((ny, nx))
                    if len(outside) == 1:
                        # Prefer the square farthest from the 0 region.
                        if b0 is not None:
                            r0, r1, c0, c1 = b0
                            cy = (r + r + 1) / 2.0
                            cx = (c + c + 1) / 2.0
                            dist = (cy - (r0 + r1) / 2.0) ** 2 + (cx - (c0 + c1) / 2.0) ** 2
                        else:
                            dist = 0
                        score = (dist, r, c)
                        if best_score is None or score > best_score:
                            best_score = score
                            best = sq

        if best is not None:
            for y, x in best:
                out[y, x] = 0

    # If the 2 region is adjacent to the same component and no 1-square was removed,
    # remove the 2 region (examples 1 and 2).
    if b2 is not None and (best is None or target_comp == -1):
        r0, r1, c0, c1 = b2
        out[r0:r1 + 1, c0:c1 + 1] = 0

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Background is the most frequent colour.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # Candidate colours are non-background colours.
    non_bg = [int(c) for c in vals if c != bg]

    # For each candidate colour, find its 8-connected components.
    # A component is eligible if it is adjacent (8-neighbour) to at least
    # one cell of every other non-background colour.
    best = None  # (size, colour, mask)

    for c in non_bg:
        mask = (g == c)
        seen = np.zeros((h, w), dtype=bool)
        for r in range(h):
            for cc in range(w):
                if mask[r, cc] and not seen[r, cc]:
                    q = deque([(r, cc)])
                    seen[r, cc] = True
                    comp = []
                    while q:
                        y, x = q.popleft()
                        comp.append((y, x))
                        for dy in (-1, 0, 1):
                            for dx in (-1, 0, 1):
                                if dy == 0 and dx == 0:
                                    continue
                                ny, nx = y + dy, x + dx
                                if 0 <= ny < h and 0 <= nx < w:
                                    if mask[ny, nx] and not seen[ny, nx]:
                                        seen[ny, nx] = True
                                        q.append((ny, nx))

                    # Check adjacency to all other non-background colours.
                    ok = True
                    for other in non_bg:
                        if other == c:
                            continue
                        other_mask = (g == other)
                        found = False
                        for y, x in comp:
                            for dy in (-1, 0, 1):
                                for dx in (-1, 0, 1):
                                    if dy == 0 and dx == 0:
                                        continue
                                    ny, nx = y + dy, x + dx
                                    if 0 <= ny < h and 0 <= nx < w and other_mask[ny, nx]:
                                        found = True
                                        break
                                if found:
                                    break
                            if found:
                                break
                        if not found:
                            ok = False
                            break

                    if ok:
                        comp_mask = np.zeros((h, w), dtype=bool)
                        for y, x in comp:
                            comp_mask[y, x] = True
                        size = len(comp)
                        if best is None or size > best[0]:
                            best = (size, c, comp_mask)

    if best is None:
        return [list(row) for row in grid]

    _, main_colour, main_mask = best

    # The secondary colour is the non-background colour most adjacent to the
    # selected component.
    adj_counts = {}
    for other in non_bg:
        if other == main_colour:
            continue
        other_mask = (g == other)
        cnt = 0
        for r in range(h):
            for c in range(w):
                if main_mask[r, c]:
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            if dy == 0 and dx == 0:
                                continue
                            ny, nx = r + dy, c + dx
                            if 0 <= ny < h and 0 <= nx < w and other_mask[ny, nx]:
                                cnt += 1
        adj_counts[other] = cnt

    if not adj_counts:
        return [list(row) for row in grid]

    secondary_colour = max(adj_counts, key=lambda k: adj_counts[k])

    # Determine which of the two colours becomes 3 and which becomes 5.
    # Use the colour that has the larger bounding-box area in the selected
    # component; ties are broken by colour value.
    def bbox_area(colour, mask):
        ys, xs = np.where(mask & (g == colour))
        if len(ys) == 0:
            return 0
        return (ys.max() - ys.min() + 1) * (xs.max() - xs.min() + 1)

    main_area = bbox_area(main_colour, main_mask)
    sec_area = bbox_area(secondary_colour, main_mask)

    if (main_area, main_colour) > (sec_area, secondary_colour):
        main_colour -> 3
        secondary_colour -> 5
    else:
        main_colour -> 5
        secondary_colour -> 3

    out = g.copy()
    out[(g == main_colour) & main_mask] = 3 if (main_area, main_colour) > (sec_area, secondary_colour) else 5
    out[(g == secondary_colour) & main_mask] = 5 if (main_area, main_colour) > (sec_area, secondary_colour) else 3

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Background is the most frequent colour.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])
    non_bg = [int(c) for c in vals if c != bg]

    # The marker colour is the non-background colour that appears in the
    # smallest connected component (8-connected).
    def components_of(colour):
        mask = (g == colour)
        seen = np.zeros((h, w), dtype=bool)
        comps = []
        for r in range(h):
            for c in range(w):
                if mask[r, c] and not seen[r, c]:
                    q = deque([(r, c)])
                    seen[r, c] = True
                    comp = []
                    while q:
                        y, x = q.popleft()
                        comp.append((y, x))
                        for dy in (-1, 0, 1):
                            for dx in (-1, 0, 1):
                                if dy == 0 and dx == 0:
                                    continue
                                ny, nx = y + dy, x + dx
                                if 0 <= ny < h and 0 <= nx < w:
                                    if mask[ny, nx] and not seen[ny, nx]:
                                        seen[ny, nx] = True
                                        q.append((ny, nx))
                    comps.append(comp)
        return comps

    marker = None
    best_size = None
    for c in non_bg:
        comps = components_of(c)
        if not comps:
            continue
        min_size = min(len(comp) for comp in comps)
        if best_size is None or min_size < best_size:
            best_size = min_size
            marker = c

    target_colours = [c for c in non_bg if c != marker]
    if len(target_colours) != 2:
        return [list(row) for row in grid]

    # Find all 8-connected components of the union of the two target colours.
    target_mask = np.isin(g, target_colours)
    seen = np.zeros((h, w), dtype=bool)
    best_comp = None
    best_score = None

    for r in range(h):
        for c in range(w):
            if target_mask[r, c] and not seen[r, c]:
                q = deque([(r, c)])
                seen[r, c] = True
                comp = []
                while q:
                    y, x = q.popleft()
                    comp.append((y, x))
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            if dy == 0 and dx == 0:
                                continue
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < h and 0 <= nx < w:
                                if target_mask[ny, nx] and not seen[ny, nx]:
                                    seen[ny, nx] = True
                                    q.append((ny, nx))

                # Keep only components that touch the marker colour.
                touches_marker = False
                for y, x in comp:
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            if dy == 0 and dx == 0:
                                continue
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < h and 0 <= nx < w and g[ny, nx] == marker:
                                touches_marker = True
                                break
                        if touches_marker:
                            break
                    if touches_marker:
                        break

                if not touches_marker:
                    continue

                # Among touching components, choose the one with the largest
                # bounding-box area; ties are broken by component size.
                ys = [y for y, _ in comp]
                xs = [x for _, x in comp]
                bbox_area = (max(ys) - min(ys) + 1) * (max(xs) - min(xs) + 1)
                score = (bbox_area, len(comp))
                if best_score is None or score > best_score:
                    best_score = score
                    best_comp = comp

    if best_comp is None:
        return [list(row) for row in grid]

    comp_mask = np.zeros((h, w), dtype=bool)
    for y, x in best_comp:
        comp_mask[y, x] = True

    # In the selected component, the target colour that touches the marker
    # becomes 5; the other target colour becomes 3.
    def touches_marker(colour):
        for y, x in best_comp:
            if g[y, x] != colour:
                continue
            for dy in (-1, 0, 1):
                for dx in (-1, 0, 1):
                    if dy == 0 and dx == 0:
                        continue
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and g[ny, nx] == marker:
                        return True
        return False

    out = g.copy()
    for colour in target_colours:
        new_colour = 5 if touches_marker(colour) else 3
        out[(g == colour) & comp_mask] = new_colour

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    H, W = g.shape

    def components(mask):
        seen = np.zeros_like(mask, dtype=bool)
        comps = []
        for i in range(mask.shape[0]):
            for j in range(mask.shape[1]):
                if mask[i, j] and not seen[i, j]:
                    q = deque([(i, j)])
                    seen[i, j] = True
                    cells = []
                    while q:
                        r, c = q.popleft()
                        cells.append((r, c))
                        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < mask.shape[0] and 0 <= nc < mask.shape[1]:
                                if mask[nr, nc] and not seen[nr, nc]:
                                    seen[nr, nc] = True
                                    q.append((nr, nc))
                    comps.append(cells)
        return comps

    def bbox(cells):
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        return min(rs), max(rs), min(cs), max(cs)

    def mask_from_cells(cells, color):
        r0, r1, c0, c1 = bbox(cells)
        m = np.zeros((r1 - r0 + 1, c1 - c0 + 1), dtype=int)
        for r, c in cells:
            m[r - r0, c - c0] = 1
        return m

    def anti_diag_reflect(m):
        # Reflect across the anti-diagonal: transpose, then rotate 180 degrees.
        return np.rot90(m.T, 2)

    def scale2(m):
        return np.kron(m, np.ones((2, 2), dtype=int))

    # Candidate container colours: non-zero colours.
    colors = [c for c in range(1, 10) if np.any(g == c)]

    # Precompute all non-container candidate pieces for each possible container.
    best = None

    for cont in colors:
        cont_mask = (g == cont)
        cont_comps = components(cont_mask)
        if not cont_comps:
            continue

        # Use the largest connected component of the candidate container.
        cont_cells = max(cont_comps, key=len)
        r0, r1, c0, c1 = bbox(cont_cells)
        pat = (g[r0:r1 + 1, c0:c1 + 1] == cont).astype(int)
        holes = 1 - pat
        target = scale2(holes)
        th, tw = target.shape

        # Pieces are all connected components of other colours.
        pieces = []
        for c in colors:
            if c == cont:
                continue
            for cells in components(g == c):
                m = mask_from_cells(cells, c)
                pm = anti_diag_reflect(m)
                pieces.append((pm, c))

        # Try to exactly cover the target hole mask with pieces.
        # Pieces are placed on the 2x2 grid, i.e. at even row/col offsets.
        used = np.zeros_like(target, dtype=bool)
        placements = []

        def dfs(idx):
            if idx == len(pieces):
                return used.all()

            pm, color = pieces[idx]
            ph, pw = pm.shape

            # Option 1: skip this piece (it may be a distractor).
            if dfs(idx + 1):
                return True

            # Option 2: place it somewhere that fits entirely in unused target cells.
            for i in range(0, th - ph + 1, 2):
                for j in range(0, tw - pw + 1, 2):
                    block = target[i:i + ph, j:j + pw]
                    if np.array_equal(block, pm) and not used[i:i + ph, j:j + pw].any():
                        used[i:i + ph, j:j + pw] = True
                        placements.append((i, j, color, pm))
                        if dfs(idx + 1):
                            return True
                        used[i:i + ph, j:j + pw] = False
                        placements.pop()
            return False

        # To make search easier, sort pieces by area descending.
        pieces.sort(key=lambda x: -int(x[0].sum()))
        if dfs(0):
            # Prefer the container that uses the most piece cells / largest container.
            score = (int(holes.sum()), len(cont_cells), -cont)
            if best is None or score > best[0]:
                out = np.full((th, tw), cont, dtype=int)
                for i, j, color, pm in placements:
                    out[i:i + pm.shape[0], j:j + pm.shape[1]] = np.where(pm == 1, color, cont)
                best = (score, out)

    if best is None:
        # Fallback: largest colour bounding box, scaled, filled with that colour.
        cont = max(colors, key=lambda c: int(np.sum(g == c)))
        mask = (g == cont)
        rows = np.any(mask, axis=1)
        cols = np.any(mask, axis=0)
        r0, r1 = np.where(rows)[0][[0, -1]]
        c0, c1 = np.where(cols)[0][[0, -1]]
        pat = (g[r0:r1 + 1, c0:c1 + 1] == cont).astype(int)
        return scale2(pat).tolist()

    return best[1].tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    H, W = g.shape
    BG = 8

    def components(mask):
        seen = np.zeros_like(mask, dtype=bool)
        comps = []
        for r in range(H):
            for c in range(W):
                if mask[r, c] and not seen[r, c]:
                    q = deque([(r, c)])
                    seen[r, c] = True
                    cells = []
                    while q:
                        y, x = q.popleft()
                        cells.append((y, x))
                        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < H and 0 <= nx < W and mask[ny, nx] and not seen[ny, nx]:
                                seen[ny, nx] = True
                                q.append((ny, nx))
                    comps.append(cells)
        return comps

    # Find the 2x2 background hub whose four side neighbours are
    # uniform non-background colours, all different.
    hub = None
    for r in range(H - 1):
        for c in range(W - 1):
            if g[r, c] == BG and g[r, c + 1] == BG and g[r + 1, c] == BG and g[r + 1, c + 1] == BG:
                sides = []
                if r > 0 and g[r - 1, c] != BG and g[r - 1, c] == g[r - 1, c + 1]:
                    sides.append((g[r - 1, c], (r - 1, c, c + 1)))
                if r + 2 < H and g[r + 2, c] != BG and g[r + 2, c] == g[r + 2, c + 1]:
                    sides.append((g[r + 2, c], (r + 2, c, c + 1)))
                if c > 0 and g[r, c - 1] != BG and g[r, c - 1] == g[r + 1, c - 1]:
                    sides.append((g[r, c - 1], (r, r + 1, c - 1)))
                if c + 2 < W and g[r, c + 2] != BG and g[r, c + 2] == g[r + 1, c + 2]:
                    sides.append((g[r, c + 2], (r, r + 1, c + 2)))

                if len(sides) == 4 and len(set(col for col, _ in sides)) == 4:
                    hub = (r, c, sides)
                    break
        if hub:
            break

    if hub is None:
        return [[int(x) for x in row] for row in g]

    hr, hc, sides = hub
    out = np.full((H, W), BG, dtype=int)

    # Keep the hub itself (and any non-background cells inside it, if any).
    for dr in range(2):
        for dc in range(2):
            out[hr + dr, hc + dc] = g[hr + dr, hc + dc]

    for col, (r1, c1, c2) in sides:
        mask = (g == col)
        comps = components(mask)

        # Marker component touches the hub side.
        marker = None
        for comp in comps:
            if any((r == r1 and c1 <= c <= c2) or (r == r1 + 1 and c1 <= c <= c2)
                   for r, c in comp):
                marker = comp
                break

        # Source shape is the largest other component of this colour.
        source = None
        best = -1
        for comp in comps:
            if comp is marker:
                continue
            if len(comp) > best:
                best = len(comp)
                source = comp

        if source is None:
            # No separate source shape: keep the marker as-is.
            for r, c in marker:
                out[r, c] = col
            continue

        rs = [r for r, _ in source]
        cs = [c for _, c in source]
        rmin, rmax = min(rs), max(rs)
        cmin, cmax = min(cs), max(cs)
        h = rmax - rmin + 1
        w = cmax - cmin + 1

        pat = np.zeros((h, w), dtype=int)
        for r, c in source:
            pat[r - rmin, c - cmin] = col

        # Rotate the source shape so it points away from the hub.
        if r1 == hr - 1:          # up
            rot = pat
        elif r1 == hr + 2:        # down
            rot = np.rot90(pat, 2)
        elif c1 == hc - 1:        # left
            rot = np.rot90(pat, 1)
        else:                     # right
            rot = np.rot90(pat, 3)

        rh, rw = rot.shape

        # Place it adjacent to the hub, aligned to the side.
        if r1 == hr - 1:          # up
            tr, tc = hr - rh, hc
        elif r1 == hr + 2:        # down
            tr, tc = hr + 2, hc
        elif c1 == hc - 1:        # left
            tr, tc = hr, hc - rw
        else:                     # right
            tr, tc = hr, hc + 2

        for i in range(rh):
            for j in range(rw):
                if rot[i, j] != 0:
                    out[tr + i, tc + j] = int(rot[i, j])

    return [[int(x) for x in row] for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Background is the checkerboard of 0/1.
    bg = np.zeros_like(g, dtype=bool)
    for r in range(h):
        for c in range(w):
            bg[r, c] = (g[r, c] == ((r + c) % 2))

    # Non-background cells are the only cells that can be overwritten.
    nonbg = ~bg

    # Identify the "barrier" colour: the non-background colour that forms
    # a closed diamond/outline.  In the examples it is the colour whose
    # cells have the largest number of non-background diagonal neighbours.
    colours = [int(x) for x in np.unique(g) if x not in (0, 1)]
    barrier = None
    best = -1
    for col in colours:
        mask = (g == col)
        score = 0
        for r in range(h):
            for c in range(w):
                if not mask[r, c]:
                    continue
                for dr, dc in ((-1, -1), (-1, 1), (1, -1), (1, 1)):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and nonbg[nr, nc]:
                        score += 1
        if score > best:
            best = score
            barrier = col

    # If no clear barrier is found, fall back to the most common non-bg colour.
    if barrier is None:
        counts = {col: int(np.sum(g == col)) for col in colours}
        barrier = max(counts, key=counts.get) if counts else 0

    # Propagate every non-barrier non-background colour along its diagonal
    # until it hits a barrier cell or the grid boundary.
    out = g.copy()
    for col in colours:
        if col == barrier:
            continue
        for r in range(h):
            for c in range(w):
                if g[r, c] != col:
                    continue
                for dr, dc in ((-1, -1), (-1, 1), (1, -1), (1, 1)):
                    nr, nc = r + dr, c + dc
                    while 0 <= nr < h and 0 <= nc < w:
                        if out[nr, nc] == barrier:
                            break
                        if nonbg[nr, nc]:
                            out[nr, nc] = col
                        nr += dr
                        nc += dc

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # The background is a 0/1 checkerboard.
    bg = np.zeros((h, w), dtype=bool)
    for r in range(h):
        for c in range(w):
            bg[r, c] = (g[r, c] == ((r + c) % 2))

    nonbg = ~bg

    # The central diamond is the colour that has the most diagonal neighbours
    # among non-background cells.  In the examples this is the 3-diamond.
    colours = [int(x) for x in np.unique(g) if x not in (0, 1)]
    centre = None
    best = -1
    for col in colours:
        mask = (g == col)
        score = 0
        for r in range(h):
            for c in range(w):
                if not mask[r, c]:
                    continue
                for dr, dc in ((-1, -1), (-1, 1), (1, -1), (1, 1)):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and nonbg[nr, nc]:
                        score += 1
        if score > best:
            best = score
            centre = col

    if centre is None:
        return [row[:] for row in grid]

    # Every other non-background colour is a "ray" colour.
    ray_colours = [col for col in colours if col != centre]

    # For each ray colour, find its connected components along the two
    # diagonal directions.  Each component is a short diagonal segment.
    # The two endpoints of the segment emit rays in the two directions
    # parallel to the segment, away from the segment.
    out = g.copy()

    def add_ray(r, c, dr, dc, col):
        nr, nc = r + dr, c + dc
        while 0 <= nr < h and 0 <= nc < w:
            if out[nr, nc] == centre:
                break
            if nonbg[nr, nc]:
                out[nr, nc] = col
            nr += dr
            nc += dc

    for col in ray_colours:
        mask = (g == col)
        seen = np.zeros((h, w), dtype=bool)

        for r in range(h):
            for c in range(w):
                if not mask[r, c] or seen[r, c]:
                    continue

                # Collect the whole diagonal component containing (r, c).
                comp = []
                stack = [(r, c)]
                seen[r, c] = True
                while stack:
                    cr, cc = stack.pop()
                    comp.append((cr, cc))
                    for dr, dc in ((-1, -1), (-1, 1), (1, -1), (1, 1)):
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < h and 0 <= nc < w and mask[nr, nc] and not seen[nr, nc]:
                            seen[nr, nc] = True
                            stack.append((nr, nc))

                # Determine the orientation of the component.
                # It should be a straight diagonal segment.
                rs = [x[0] for x in comp]
                cs = [x[1] for x in comp]
                if len(comp) == 1:
                    # A single cell emits in all four diagonal directions.
                    for dr, dc in ((-1, -1), (-1, 1), (1, -1), (1, 1)):
                        add_ray(r, c, dr, dc, col)
                    continue

                # If r+c is constant, the segment is an anti-diagonal.
                # If r-c is constant, it is a main diagonal.
                sums = {x[0] + x[1] for x in comp}
                diffs = {x[0] - x[1] for x in comp}

                if len(sums) == 1:
                    # Anti-diagonal segment: endpoints are min/max row.
                    p1 = min(comp, key=lambda x: x[0])
                    p2 = max(comp, key=lambda x: x[0])
                    # Emit away from the segment along the same anti-diagonal.
                    add_ray(p1[0], p1[1], -1, 1, col)
                    add_ray(p2[0], p2[1], 1, -1, col)
                elif len(diffs) == 1:
                    # Main diagonal segment: endpoints are min/max row.
                    p1 = min(comp, key=lambda x: x[0])
                    p2 = max(comp, key=lambda x: x[0])
                    # Emit away from the segment along the same main diagonal.
                    add_ray(p1[0], p1[1], -1, -1, col)
                    add_ray(p2[0], p2[1], 1, 1, col)
                else:
                    # Fallback: treat every cell as an emitter.
                    for cr, cc in comp:
                        for dr, dc in ((-1, -1), (-1, 1), (1, -1), (1, 1)):
                            add_ray(cr, cc, dr, dc, col)

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import defaultdict

    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Find the mask: the largest connected component of a non-background colour.
    # The mask colour becomes the output background; its holes are filled.
    best = None
    for color in range(1, 10):
        mask = (g == color)
        if not mask.any():
            continue
        seen = np.zeros_like(mask, dtype=bool)
        for r in range(H):
            for c in range(W):
                if mask[r, c] and not seen[r, c]:
                    stack = [(r, c)]
                    seen[r, c] = True
                    cells = []
                    while stack:
                        y, x = stack.pop()
                        cells.append((y, x))
                        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < H and 0 <= nx < W and mask[ny, nx] and not seen[ny, nx]:
                                seen[ny, nx] = True
                                stack.append((ny, nx))
                    if best is None or len(cells) > best[0]:
                        best = (len(cells), color, cells)

    if best is None:
        return [list(row) for row in grid]

    _, mask_color, mask_cells = best
    ys = [p[0] for p in mask_cells]
    xs = [p[1] for p in mask_cells]
    r0, r1 = min(ys), max(ys)
    c0, c1 = min(xs), max(xs)
    h, w = r1 - r0 + 1, c1 - c0 + 1

    # Holes are background cells inside the mask bounding box.
    hole_mask = np.zeros((h, w), dtype=bool)
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            if g[r, c] != mask_color:
                hole_mask[r - r0, c - c0] = True

    # Connected components of holes.
    hole_comps = []
    seen = np.zeros((h, w), dtype=bool)
    for r in range(h):
        for c in range(w):
            if hole_mask[r, c] and not seen[r, c]:
                stack = [(r, c)]
                seen[r, c] = True
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and hole_mask[ny, nx] and not seen[ny, nx]:
                            seen[ny, nx] = True
                            stack.append((ny, nx))
                hole_comps.append(cells)

    # Collect all non-mask connected components in the whole input.
    all_comps = []
    seen = np.zeros((H, W), dtype=bool)
    for r in range(H):
        for c in range(W):
            if g[r, c] != mask_color and not seen[r, c]:
                color = g[r, c]
                stack = [(r, c)]
                seen[r, c] = True
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < H and 0 <= nx < W and g[ny, nx] == color and not seen[ny, nx]:
                            seen[ny, nx] = True
                            stack.append((ny, nx))
                all_comps.append((color, cells))

    def normalize(cells):
        min_r = min(r for r, _ in cells)
        min_c = min(c for _, c in cells)
        return frozenset((r - min_r, c - min_c) for r, c in cells)

    def variants(cells):
        base = normalize(cells)
        pts = list(base)
        max_r = max(r for r, _ in pts)
        max_c = max(c for _, c in pts)
        res = set()
        for _ in range(4):
            res.add(frozenset(pts))
            pts = [(r, -c) for r, c in pts]
            pts = [(c, r) for r, c in pts]
        return res

    # For each hole shape, choose the most frequent colour among matching input components.
    shape_to_color = {}
    for comp in hole_comps:
        shape = normalize(comp)
        if shape in shape_to_color:
            continue
        counts = defaultdict(int)
        for color, cells in all_comps:
            if color == mask_color:
                continue
            if shape in variants(cells):
                counts[color] += 1
        if counts:
            best_color = max(counts.items(), key=lambda kv: (kv[1], -kv[0]))[0]
        else:
            best_color = 0
        shape_to_color[shape] = best_color

    out = np.full((h, w), mask_color, dtype=int)
    for comp in hole_comps:
        color = shape_to_color[normalize(comp)]
        for r, c in comp:
            out[r, c] = color

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import defaultdict

    g = np.array(grid, dtype=int)
    H, W = g.shape

    def components(mask):
        seen = np.zeros_like(mask, dtype=bool)
        comps = []
        for r in range(H):
            for c in range(W):
                if mask[r, c] and not seen[r, c]:
                    stack = [(r, c)]
                    seen[r, c] = True
                    cells = []
                    while stack:
                        y, x = stack.pop()
                        cells.append((y, x))
                        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < H and 0 <= nx < W and mask[ny, nx] and not seen[ny, nx]:
                                seen[ny, nx] = True
                                stack.append((ny, nx))
                    comps.append(cells)
        return comps

    def normalize(cells):
        min_r = min(r for r, _ in cells)
        min_c = min(c for _, c in cells)
        return frozenset((r - min_r, c - min_c) for r, c in cells)

    def shape_variants(cells):
        base = normalize(cells)
        pts = list(base)
        res = set()
        for _ in range(4):
            res.add(frozenset(pts))
            pts = [(r, -c) for r, c in pts]
            pts = [(c, r) for r, c in pts]
        return res

    # Candidate canvas colours: non-background colours that form a rectangular
    # bounding box whose border is completely filled with that colour.
    color_counts = defaultdict(int)
    for row in g:
        for v in row:
            color_counts[int(v)] += 1

    candidates = []
    for color in range(1, 10):
        if color_counts[color] == 0:
            continue
        mask = (g == color)
        for cells in components(mask):
            rs = [r for r, _ in cells]
            cs = [c for _, c in cells]
            r0, r1 = min(rs), max(rs)
            c0, c1 = min(cs), max(cs)
            h, w = r1 - r0 + 1, c1 - c0 + 1
            if h < 3 or w < 3:
                continue
            # The outer border of the bounding box must be all this colour.
            border_ok = True
            for c in range(c0, c1 + 1):
                if g[r0, c] != color or g[r1, c] != color:
                    border_ok = False
                    break
            if not border_ok:
                continue
            for r in range(r0, r1 + 1):
                if g[r, c0] != color or g[r, c1] != color:
                    border_ok = False
                    break
            if not border_ok:
                continue
            # Prefer large, mostly-solid rectangular canvases.
            area = h * w
            fill = len(cells) / area
            candidates.append((area, fill, color, r0, r1, c0, c1))

    if not candidates:
        return [list(row) for row in grid]

    # Choose the largest rectangular canvas; tie-break by fill ratio.
    candidates.sort(key=lambda x: (x[0], x[1]), reverse=True)
    _, _, canvas_color, r0, r1, c0, c1 = candidates[0]
    h, w = r1 - r0 + 1, c1 - c0 + 1

    # Holes are connected components of non-canvas cells inside the canvas box.
    hole_mask = np.zeros((h, w), dtype=bool)
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            if g[r, c] != canvas_color:
                hole_mask[r - r0, c - c0] = True

    seen = np.zeros((h, w), dtype=bool)
    holes = []
    for r in range(h):
        for c in range(w):
            if hole_mask[r, c] and not seen[r, c]:
                stack = [(r, c)]
                seen[r, c] = True
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and hole_mask[ny, nx] and not seen[ny, nx]:
                            seen[ny, nx] = True
                            stack.append((ny, nx))
                holes.append(cells)

    # All source pieces: connected components outside the canvas, excluding
    # the canvas colour and the dominant background colour.
    bg_color = max(color_counts, key=lambda k: (color_counts[k], -k))
    outside = np.ones((H, W), dtype=bool)
    outside[r0:r1 + 1, c0:c1 + 1] = False

    pieces = []
    for color in range(1, 10):
        if color == canvas_color or color == bg_color:
            continue
        mask = (g == color) & outside
        for cells in components(mask):
            pieces.append((color, cells))

    # For each hole shape, choose the most frequent source colour whose shape
    # matches under rotation/reflection.
    shape_color = {}
    for hole in holes:
        shape = normalize(hole)
        if shape in shape_color:
            continue
        counts = defaultdict(int)
        for color, cells in pieces:
            if shape in shape_variants(cells):
                counts[color] += 1
        if counts:
            best = max(counts.items(), key=lambda kv: (kv[1], -kv[0]))[0]
        else:
            best = 0
        shape_color[shape] = best

    out = np.full((h, w), canvas_color, dtype=int)
    for hole in holes:
        color = shape_color[normalize(hole)]
        for r, c in hole:
            out[r, c] = color

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Locate the vertical separator line of 5s.
    five_cols = [c for c in range(w) if np.all(g[:, c] == 5)]
    if not five_cols:
        return g.tolist()
    sep = five_cols[0]

    out = g.copy()

    # Work only on the left side of the 5-line.
    left = g[:, :sep].copy()

    # Connected components of 0s (4-connectivity) on the left side.
    visited = np.zeros(left.shape, dtype=bool)
    components = []

    for r in range(h):
        for c in range(sep):
            if left[r, c] == 0 and not visited[r, c]:
                stack = [(r, c)]
                visited[r, c] = True
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < sep:
                            if left[ny, nx] == 0 and not visited[ny, nx]:
                                visited[ny, nx] = True
                                stack.append((ny, nx))
                components.append(cells)

    # For each component, shift its 0s right by the number of 6s
    # immediately to the left of the component's leftmost cell.
    for cells in components:
        min_c = min(c for _, c in cells)
        shift = 0
        c = min_c - 1
        while c >= 0 and left[0, c] == 6:  # left boundary is uniform 6 in all examples
            shift += 1
            c -= 1

        for r, c in cells:
            nc = c + shift
            if nc < sep:
                out[r, nc] = 0

    # Fill the left side with 6 where it is not a 0.
    for r in range(h):
        for c in range(sep):
            if out[r, c] != 0:
                out[r, c] = 6

    # For each component, paint the right side with 2 on its middle row(s).
    for cells in components:
        rows = sorted({r for r, _ in cells})
        lo, hi = rows[0], rows[-1]
        mid = (lo + hi) // 2
        if (hi - lo + 1) % 2 == 0:
            mid_rows = [mid, mid + 1]
        else:
            mid_rows = [mid]
        for r in mid_rows:
            out[r, sep + 1:] = 2

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Find the vertical separator line made of 5s.
