                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and not seen2[ny, nx] and g[ny, nx] == 2:
                            seen2[ny, nx] = True
                            stack.append((ny, nx))
                twos.append(cells)

    # For each 2-component, find object cells touching it (8-neighbourhood),
    # expand each touched object to its full 8-connected same-colour component,
    # and reflect it across the 2-component.
    for comp in twos:
        ys = [r for r, c in comp]
        xs = [c for r, c in comp]
        min_y, max_y = min(ys), max(ys)
        min_x, max_x = min(xs), max(xs)

        # Determine reflection type.
        if len(comp) == 1:
            kind = "point"
            axis = (min_y, min_x)
        elif min_y == max_y:
            kind = "h"
            axis = min_y
        elif min_x == max_x:
            kind = "v"
            axis = min_x
        else:
            # Fallback for unexpected non-linear 2 shapes:
            # reflect through the centre of the bounding box.
            kind = "point"
            axis = ((min_y + max_y) / 2.0, (min_x + max_x) / 2.0)

        # Cells of non-background, non-2 colours directly adjacent to the mirror.
        touched = set()
        for r, c in comp:
            for dy in (-1, 0, 1):
                for dx in (-1, 0, 1):
                    if dy == 0 and dx == 0:
                        continue
                    nr, nc = r + dy, c + dx
                    if 0 <= nr < h and 0 <= nc < w:
                        v = g[nr, nc]
                        if v != bg and v != 2:
                            touched.add((nr, nc))

        if not touched:
            continue

        # Expand touched cells into full object components.
        seen_obj = set()
        objects = []
        for start in touched:
            if start in seen_obj:
                continue
            color = g[start[0], start[1]]
            stack = [start]
            seen_obj.add(start)
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        if dy == 0 and dx == 0:
                            continue
                        ny, nx = y + dy, x + dx
                        if (
                            0 <= ny < h
                            and 0 <= nx < w
                            and (ny, nx) not in seen_obj
                            and g[ny, nx] == color
                        ):
                            seen_obj.add((ny, nx))
                            stack.append((ny, nx))
            objects.append(cells)

        # Reflect every touched object component.
        for obj in objects:
            for r, c in obj:
                if kind == "h":
                    nr = 2 * axis - r
                    nc = c
                elif kind == "v":
                    nr = r
                    nc = 2 * axis - c
                else:
                    cy, cx = axis
                    nr = int(round(2 * cy - r))
                    nc = int(round(2 * cx - c))

                if 0 <= nr < h and 0 <= nc < w and out[nr, nc] == bg:
                    out[nr, nc] = g[r, c]

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    H, W = g.shape
    out = np.zeros_like(g)

    # Find the full-width horizontal band.
    band_color = None
    band_rows = []
    for r in range(H):
        row = g[r]
        if np.all(row != 0):
            c = int(row[0])
            if np.all(row == c):
                if band_color is None:
                    band_color = c
                    band_rows = [r]
                elif r == band_rows[-1] + 1:
                    band_rows.append(r)
                else:
                    band_rows = [r]
            else:
                band_color = None
                band_rows = []

    if band_color is None or not band_rows:
        return out.tolist()

    band_top = band_rows[0]
    band_bottom = band_rows[-1]

    # Connected components of non-band, non-zero colors.
    seen = np.zeros((H, W), dtype=bool)
    comps = []
    for r in range(H):
        for c in range(W):
            if seen[r, c] or g[r, c] == 0 or g[r, c] == band_color:
                continue
            color = int(g[r, c])
            q = deque([(r, c)])
            seen[r, c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < H and 0 <= nx < W and not seen[ny, nx] and g[ny, nx] == color:
                        seen[ny, nx] = True
                        q.append((ny, nx))
            ys = [y for y, _ in cells]
            xs = [x for _, x in cells]
            h = max(ys) - min(ys) + 1
            w = max(xs) - min(xs) + 1
            pat = np.zeros((h, w), dtype=int)
            for y, x in cells:
                pat[y - min(ys), x - min(xs)] = color
            comps.append({
                "color": color,
                "top": min(ys),
                "left": min(xs),
                "h": h,
                "w": w,
                "pat": pat,
            })

    # Group by width.
    groups = {}
    for comp in comps:
        groups.setdefault(comp["w"], []).append(comp)

    # Order inside each width group:
    # 1) by vertical position relative to the band (above, then below)
    # 2) by original top row
    # 3) by color
    def order_key(comp):
        above = comp["top"] < band_top
        return (0 if above else 1, comp["top"], comp["color"])

    for comps_list in groups.values():
        comps_list.sort(key=order_key)

    # Place each width group as a vertical stack with one-row overlaps.
    # Width-5 groups go above the band; other groups go below the band.
    for w, comps_list in groups.items():
        if not comps_list:
            continue

        # Build stacked pattern.
        stacked = []
        for i, comp in enumerate(comps_list):
            pat = comp["pat"]
            if i == 0:
                stacked.extend([row.copy() for row in pat])
            else:
                # Overlap the last row of the previous shape with the first row of this shape.
                prev_last = stacked[-1]
                first = pat[0]
                merged = np.where(first != 0, first, prev_last)
                stacked[-1] = merged
                stacked.extend([row.copy() for row in pat[1:]])

        sh = len(stacked)
        sw = w

        # Choose a column: prefer a hole in the band that matches the stack's bottom rows.
        best_col = None
        best_score = -1
        for c in range(0, W - sw + 1):
            score = 0
            ok = True
            for i in range(sh):
                r = band_top + i
                if r < 0 or r >= H:
                    ok = False
                    break
                row = stacked[i]
                for j in range(sw):
                    v = row[j]
                    if v == 0:
                        continue
                    if g[r, c + j] != 0 and g[r, c + j] != band_color:
                        ok = False
                        break
                    if g[r, c + j] == 0:
                        score += 1
                if not ok:
                    break
            if ok and score > best_score:
                best_score = score
                best_col = c

        if best_col is None:
            # Fallback: leftmost non-overlapping column.
            for c in range(0, W - sw + 1):
                ok = True
                for i in range(sh):
                    r = band_top + i
                    if r < 0 or r >= H:
                        ok = False
                        break
                    for j in range(sw):
                        if stacked[i][j] != 0 and g[r, c + j] not in (0, band_color):
                            ok = False
                            break
                    if not ok:
                        break
                if ok:
                    best_col = c
                    break
            if best_col is None:
                best_col = 0

        # Place the stack starting at the band top.
        for i in range(sh):
            r = band_top + i
            if 0 <= r < H:
                for j in range(sw):
                    v = stacked[i][j]
                    if v != 0:
                        out[r, best_col + j] = v

    # Preserve the original band.
    for r in band_rows:
        out[r, :] = g[r, :]

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    H, W = g.shape
    out = g.copy()  # Start with input (preserves stray pixels)

