            q = deque([(r, c)])
            seen[r, c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < H and 0 <= nx < W and not seen[ny,nx] and g[ny,nx] == color:
                        seen[ny,nx] = True
                        q.append((ny,nx))
            ys = [y for y,_ in cells]
            xs = [x for _,x in cells]
            h = max(ys)-min(ys)+1
            w = max(xs)-min(xs)+1
            pat = np.zeros((h,w), dtype=int)
            for y,x in cells:
                pat[y-min(ys), x-min(xs)] = color
            comps.append({"color":color,"top":min(ys),"left":min(xs),"h":h,"w":w,"pat":pat})

    # Clear all shape pixels from output
    for comp in comps:
        for y in range(comp["top"], comp["top"]+comp["h"]):
            for x in range(comp["left"], comp["left"]+comp["w"]):
                if out[y,x] == comp["color"]:
                    out[y,x] = 0

