    def stack_shapes(comps_list):
        stacked = []
        for i, comp in enumerate(comps_list):
            pat = comp["pat"]
            if i == 0:
                stacked.extend([row.copy() for row in pat])
            else:
                prev_last = stacked[-1]
                first = pat[0]
                merged = np.where(first != 0, first, prev_last)
                stacked[-1] = merged
                stacked.extend([row.copy() for row in pat[1:]])
        return stacked

    # Place each width group
    for w, comps_list in groups.items():
        if not comps_list:
            continue
        stacked = stack_shapes(comps_list)
        sh = len(stacked)
        sw = w

        # Determine placement side
        if w == 5:
            # Above band: stack bottom row at band_top
            start_row = band_top - sh + 1
        else:
            # Below band: stack top row at band_bottom
            start_row = band_bottom

        # Find best column (maximize overlap with band holes)
        best_col = 0
        best_score = -1
        for c in range(0, W - sw + 1):
            score = 0
            ok = True
            for i in range(sh):
                r = start_row + i
                if r < 0 or r >= H:
