                    if g[r, c+j] == 0:
                        score += 1
                if not ok:
                    break
            if ok and score > best_score:
                best_score = score
                best_col = c

        # Place stack
        for i in range(sh):
            r = start_row + i
            if 0 <= r < H:
                for j in range(sw):
                    v = stacked[i][j]
                    if v != 0:
                        out[r, best_col+j] = v

    # Restore band
    for r in band_rows:
        out[r, :] = g[r, :]

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import Counter

    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Find the separator colour: a non-background colour that forms a long
    # straight line (vertical or horizontal) and is not just a small seed.
    def line_score(c):
        best = 0
        for r in range(H):
            if np.all(g[r] == c):
                best = max(best, W)
        for col in range(W):
            if np.all(g[:, col] == c):
                best = max(best, H)
        return best

    counts = Counter(g.flat)
    # background is the most common colour
    bg = counts.most_common(1)[0][0]

    sep = None
    best = 0
    for c in counts:
        if c == bg:
            continue
        s = line_score(c)
        if s > best:
            best = s
            sep = c

    # If no full line is found, fall back to the most common non-background colour.
    if sep is None:
        for c, n in counts.most_common():
            if c != bg:
                sep = c
                break

    out = g.copy()

    # Build a mask of separator cells.
    sep_mask = (g == sep)

    # Find rectangular regions of non-separator cells.
    # We scan for maximal rectangles whose border is either grid edge or separator.
    # For each region, collect seed colours along the diagonal from the corner
    # closest to the first seed, then fill with concentric rings cycling those colours.
    visited = np.zeros((H, W), dtype=bool)

    def is_sep(r, c):
        return 0 <= r < H and 0 <= c < W and sep_mask[r, c]

    # Find all maximal empty rectangles by expanding from each non-separator cell.
    # To avoid duplicates, only start at the top-left of a region.
    for r in range(H):
        for c in range(W):
            if sep_mask[r, c] or visited[r, c]:
                continue

            # Determine region bounds:
            # top: first separator above or -1
            top = r
            while top > 0 and not sep_mask[top - 1, c]:
                top -= 1
            bottom = r
            while bottom < H - 1 and not sep_mask[bottom + 1, c]:
                bottom += 1
            left = c
            while left > 0 and not sep_mask[r, left - 1]:
                left -= 1
            right = c
            while right < W - 1 and not sep_mask[r, right + 1]:
                right += 1

            # Ensure the whole rectangle is free of separators.
            valid = True
            for rr in range(top, bottom + 1):
                for cc in range(left, right + 1):
                    if sep_mask[rr, cc]:
                        valid = False
                        break
                if not valid:
                    break

            if not valid:
                # Fallback: connected component of non-separator cells.
                stack = [(r, c)]
                comp = []
                while stack:
                    x, y = stack.pop()
                    if x < 0 or x >= H or y < 0 or y >= W:
                        continue
                    if sep_mask[x, y] or visited[x, y]:
                        continue
                    visited[x, y] = True
                    comp.append((x, y))
                    stack.extend([(x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)])
                if not comp:
                    continue
                rs = [p[0] for p in comp]
                cs = [p[1] for p in comp]
                top, bottom = min(rs), max(rs)
                left, right = min(cs), max(cs)
                # If component is not rectangular, fill only its cells with a
                # simple ring pattern based on its bounding box.
                for x, y in comp:
                    d = min(x - top, y - left, bottom - x, right - y)
                    out[x, y] = g[x, y]
                continue

            # Mark visited.
            for rr in range(top, bottom + 1):
                for cc in range(left, right + 1):
                    visited[rr, cc] = True

            # Collect seeds: non-background, non-separator cells in this region.
            seeds = []
            for rr in range(top, bottom + 1):
                for cc in range(left, right + 1):
                    v = g[rr, cc]
                    if v != bg and v != sep:
                        seeds.append((rr, cc, v))

            if not seeds:
                # No seeds: leave as background.
                for rr in range(top, bottom + 1):
                    for cc in range(left, right + 1):
                        out[rr, cc] = bg
                continue

            # Choose the corner that is closest to the first seed in diagonal order.
            # We try all four corners and pick the one that gives a consistent
            # diagonal sequence (seeds lie on or near the diagonal from that corner).
            corners = [
                (top, left, 1, 1),
                (top, right, 1, -1),
                (bottom, left, -1, 1),
                (bottom, right, -1, -1),
            ]

            best_corner = None
            best_score = -1
            for cr, cc, dr, dc in corners:
                # Score: number of seeds that lie on the diagonal from this corner.
                score = 0
                for rr, ccc, v in seeds:
                    # Check if (rr, ccc) is on the diagonal: rr-cr = dr*k, ccc-cc = dc*k
                    if (rr - cr) * dr >= 0 and (ccc - cc) * dc >= 0:
                        if (rr - cr) * dr == (ccc - cc) * dc:
                            score += 1
                # Prefer corners with more diagonal seeds, then closer to first seed.
                if score > best_score:
                    best_score = score
                    best_corner = (cr, cc, dr, dc)

            cr, cc, dr, dc = best_corner

            # Build colour sequence along the diagonal from the chosen corner.
            # Include only non-background, non-separator colours in order.
            seq = []
            k = 0
            while True:
                rr = cr + dr * k
                ccc = cc + dc * k
                if not (top <= rr <= bottom and left <= ccc <= right):
                    break
                v = g[rr, ccc]
                if v != bg and v != sep:
                    if not seq or seq[-1] != v:
                        seq.append(v)
                k += 1

            # If diagonal did not capture all seeds, append remaining seeds in
            # order of distance from the corner.
            if len(seq) < len(seeds):
                remaining = []
                for rr, ccc, v in seeds:
                    # distance in diagonal steps
                    if (rr - cr) * dr >= 0 and (ccc - cc) * dc >= 0:
                        d = (rr - cr) * dr
                    else:
                        d = 10**9
                    remaining.append((d, rr, ccc, v))
                remaining.sort()
                for d, rr, ccc, v in remaining:
                    if v not in seq:
                        seq.append(v)

            if not seq:
                seq = [bg]

            # Fill region with concentric rings cycling through seq.
            for rr in range(top, bottom + 1):
                for ccc in range(left, right + 1):
                    # Distance from the chosen corner in ring terms.
                    if dr == 1 and dc == 1:
                        d = min(rr - top, ccc - left, bottom - rr, right - ccc)
                    elif dr == 1 and dc == -1:
                        d = min(rr - top, right - ccc, bottom - rr, ccc - left)
                    elif dr == -1 and dc == 1:
                        d = min(bottom - rr, ccc - left, rr - top, right - ccc)
                    else:
                        d = min(bottom - rr, right - ccc, rr - top, ccc - left)
                    out[rr, ccc] = seq[d % len(seq)]

    return out.tolist()

import numpy as np
from collections import Counter, deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape
    out = g.copy()

    # If the grid is empty (not expected), return it.
    if H == 0 or W == 0:
        return out.tolist()

    # ------------------------------------------------------------------
    # 1) Identify the separator colour.
    #    In all examples it is the second most frequent colour overall,
    #    but we also use line-run evidence to make this robust.
    # ------------------------------------------------------------------
    flat = g.ravel()
    counts = Counter(flat.tolist())
    if not counts:
        return out.tolist()

    # Most frequent colour is the global background.
    global_bg = counts.most_common(1)[0][0]

    def line_score(col: int) -> int:
        """Total length of horizontal/vertical runs of this colour."""
        score = 0
        # horizontal runs
        for r in range(H):
            run = 0
            for c in range(W):
                if g[r, c] == col:
                    run += 1
                else:
                    if run > 1:
                        score += run
                    run = 0
            if run > 1:
                score += run
        # vertical runs
        for c in range(W):
            run = 0
            for r in range(H):
                if g[r, c] == col:
                    run += 1
                else:
                    if run > 1:
                        score += run
                    run = 0
            if run > 1:
                score += run
        return score

    candidates = [c for c in counts if c != global_bg]
    if not candidates:
        # No separator; return input.
        return out.tolist()

    # Prefer colours that form long straight lines.  If several are good,
    # fall back to frequency.
    best_sep = None
    best_key = None
    for c in candidates:
        ls = line_score(c)
        # A separator should have substantial straight-line structure.
        # Use (line_score, count) as a robust key.
        key = (ls, counts[c])
        if best_key is None or key > best_key:
            best_key = key
            best_sep = c

    # If the best line score is tiny, use the second most frequent colour.
    if best_key[0] < 3:
        second = counts.most_common(2)
        if len(second) >= 2:
            best_sep = second[1][0]
        else:
            best_sep = candidates[0]

    sep = best_sep

    # ------------------------------------------------------------------
    # 2) Find connected components of non-separator cells (4-connected).
    # ------------------------------------------------------------------
    visited = np.zeros((H, W), dtype=bool)
    components = []

    for r in range(H):
        for c in range(W):
            if visited[r, c] or g[r, c] == sep:
                continue
            q = deque([(r, c)])
            visited[r, c] = True
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < H and 0 <= ny < W:
                        if not visited[nx, ny] and g[nx, ny] != sep:
                            visited[nx, ny] = True
                            q.append((nx, ny))
            components.append(cells)

    # ------------------------------------------------------------------
    # 3) For each component, fill its cells with concentric rings.
    # ------------------------------------------------------------------
    for cells in components:
        if not cells:
            continue

        rs = [r for r, _ in cells]
        cs = [c for _, c in cells]
        top, bottom = min(rs), max(rs)
        left, right = min(cs), max(cs)

        # Background colour of this component: most frequent colour inside it.
        comp_counter = Counter(g[r, c] for r, c in cells)
        bg = comp_counter.most_common(1)[0][0]

        # Try all four corners.  The correct corner is the one whose inward
        # diagonal contains the longest initial palette:
        #   - first cell is always included
        #   - continue while the next diagonal cell is not the component bg
        #   - stop at separator or outside the bounding box
        corners = [
            (top, left, 1, 1),
            (top, right, 1, -1),
            (bottom, left, -1, 1),
            (bottom, right, -1, -1),
        ]

        best_seq = [bg]
        best_score = (-1, -1)

        for r0, c0, dr, dc in corners:
            seq = []
            k = 0
            while True:
                r = r0 + dr * k
                c = c0 + dc * k
                if not (top <= r <= bottom and left <= c <= right):
                    break
                v = g[r, c]
                if v == sep:
                    break
                if k == 0:
                    seq.append(v)
                else:
                    if v == bg:
                        break
                    seq.append(v)
                k += 1

            if not seq:
                seq = [bg]

            # Score: first maximise number of non-background palette colours,
            # then total palette length.
            score = (sum(1 for x in seq if x != bg), len(seq))
            if score > best_score:
                best_score = score
                best_seq = seq

        # If no useful palette was found, just fill with the component bg.
        if not best_seq:
            best_seq = [bg]

        # Fill only the cells belonging to this component, using distance
        # to the bounding-box border.
        for r, c in cells:
            d = min(r - top, c - left, bottom - r, right - c)
            out[r, c] = best_seq[d % len(best_seq)]

    return out.tolist()

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Locate the 0 corner of the L-shaped border.
    zeros = np.argwhere(g == 0)
    if len(zeros) == 0:
        return [[0]]
    r0, c0 = zeros[0]

    # Determine the two border directions from the 0 corner.
    dirs = []
    for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
        nr, nc = r0 + dr, c0 + dc
        if 0 <= nr < H and 0 <= nc < W and g[nr, nc] != 0:
            dirs.append((dr, dc))

    if len(dirs) != 2:
        return [[0]]

    (dr1, dc1), (dr2, dc2) = dirs
    color1 = g[r0 + dr1, c0 + dc1]
    color2 = g[r0 + dr2, c0 + dc2]

    # Canvas is the rectangle inside the L-shaped border.
    if dr1 == -1:
        top = r0
    else:
        top = r0 + 1
    if dr2 == -1:
        top = r0
    else:
        top = min(top, r0 + 1)

    if dr1 == 1:
        bottom = r0
    else:
        bottom = r0 - 1
    if dr2 == 1:
        bottom = r0
    else:
        bottom = max(bottom, r0 - 1)

    if dc1 == -1:
        left = c0
    else:
        left = c0 + 1
    if dc2 == -1:
        left = c0
    else:
        left = min(left, c0 + 1)

    if dc1 == 1:
        right = c0
    else:
        right = c0 - 1
    if dc2 == 1:
        right = c0
    else:
        right = max(right, c0 - 1)

    canvas = g[top:bottom + 1, left:right + 1]
    ch, cw = canvas.shape

    # Connected components of non-8 cells (4-connected).
    seen = np.zeros((ch, cw), dtype=bool)
    comps = []

    for i in range(ch):
        for j in range(cw):
            if seen[i, j] or canvas[i, j] == 8:
                continue
            stack = [(i, j)]
            seen[i, j] = True
            cells = []
            while stack:
                r, c = stack.pop()
                cells.append((r, c))
                for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
                    if 0 <= nr < ch and 0 <= nc < cw and not seen[nr, nc] and canvas[nr, nc] != 8:
                        seen[nr, nc] = True
                        stack.append((nr, nc))

            rmin = min(r for r, _ in cells)
            rmax = max(r for r, _ in cells)
            cmin = min(c for _, c in cells)
            cmax = max(c for _, c in cells)
            block = canvas[rmin:rmax + 1, cmin:cmax + 1]
            comps.append((rmin, cmin, block))

    # Orientation: make each block landscape (width >= height) by rotating CCW if needed.
    oriented = []
    for rmin, cmin, block in comps:
        bh, bw = block.shape
        if bh > bw:
            block = np.rot90(block, k=1)  # counterclockwise
        oriented.append((rmin, cmin, block))

    # Output width is the maximum oriented width.
    out_w = max(b.shape[1] for _, _, b in oriented)

    # Ordering:
    # - If the color-1 border is horizontal, read rows.
    # - If the color-1 border is vertical, read columns.
    # Direction is reversed when the border is on the right/bottom side.
    color1_horizontal = (dr1 == 0)
    if color1_horizontal:
        reverse = (dc1 == 1)
        oriented.sort(key=lambda x: (x[0], -x[1] if reverse else x[1]))
    else:
        reverse = (dr1 == 1)
        oriented.sort(key=lambda x: (x[1], -x[0] if reverse else x[0]))

    # Stack centered horizontally on an 8 background.
    out_rows = []
    for _, _, block in oriented:
        bh, bw = block.shape
        pad = out_w - bw
        left_pad = pad // 2
        right_pad = pad - left_pad
        for row in block:
            out_rows.append([8] * left_pad + list(row) + [8] * right_pad)

    return out_rows

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import Counter

    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Find the most frequent non-zero colour.  In all supplied cases this is
    # the colour that forms the large "background" blocks.
    cnt = Counter(g.flatten().tolist())
    cnt.pop(0, None)
    if not cnt:
        return [[0] * W for _ in range(H)]
    bg = cnt.most_common(1)[0][0]

    # A cell is "solid" if it belongs to the background colour and is not
    # isolated by non-background neighbours.
    solid = np.zeros((H, W), dtype=bool)
    for r in range(H):
        for c in range(W):
            if g[r, c] != bg:
                continue
            ok = True
            for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < H and 0 <= nc < W and g[nr, nc] != bg:
                    ok = False
                    break
            solid[r, c] = ok

    # Connected components of solid background cells.
    comp = np.zeros((H, W), dtype=int)
    comps = []
    for r in range(H):
        for c in range(W):
            if solid[r, c] and comp[r, c] == 0:
                cid = len(comps) + 1
                stack = [(r, c)]
                comp[r, c] = cid
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy, dx in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < H and 0 <= nx < W and solid[ny, nx] and comp[ny, nx] == 0:
                            comp[ny, nx] = cid
                            stack.append((ny, nx))
                ys = [p[0] for p in cells]
                xs = [p[1] for p in cells]
                comps.append({
                    "id": cid,
                    "cells": cells,
                    "minr": min(ys), "maxr": max(ys),
                    "minc": min(xs), "maxc": max(xs),
                    "area": len(cells),
                })

    # For each component, find the first non-background colour that touches it.
    # This is the "marker" colour encoded by the noisy pixels around the block.
    marker = {}
    for compo in comps:
        seen = set()
        for r, c in compo["cells"]:
            for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < H and 0 <= nc < W:
                    v = int(g[nr, nc])
                    if v != bg and v not in seen:
                        seen.add(v)
        if seen:
            # Deterministic choice: smallest colour value.
            marker[compo["id"]] = min(seen)
        else:
            marker[compo["id"]] = bg

    # Build the transposed output.  Each output cell (c, r) is filled with the
    # marker of the solid component that contains input cell (r, c), if any.
    out = np.zeros((W, H), dtype=int)
    for r in range(H):
        for c in range(W):
            cid = comp[r, c]
            if cid:
                out[c, r] = marker[cid]

    # If no solid component was found (defensive fallback), return a zero grid.
    if not comps:
        return [[0] * W for _ in range(H)]

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # The puzzle uses 8 as background.  The “objects” are made of 1/2/3/4.
    # The “rays” are made of the remaining non-background colors.
    obj_colors = {1, 2, 3, 4}
    ray_colors = set(range(1, 10)) - obj_colors - {8}

    def is_obj(v: int) -> bool:
        return v in obj_colors

    def is_ray(v: int) -> bool:
        return v in ray_colors

    # Find connected components of object pixels.
    seen = np.zeros((h, w), dtype=bool)
    comps = []
    for r in range(h):
        for c in range(w):
            if is_obj(g[r, c]) and not seen[r, c]:
                stack = [(r, c)]
                seen[r, c] = True
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and not seen[ny, nx] and is_obj(g[ny, nx]):
                            seen[ny, nx] = True
                            stack.append((ny, nx))
                comps.append(cells)

    # For each object, find the unique ray color that touches it orthogonally.
    # If exactly one such color exists, draw a straight ray from the object
    # in the direction of that color, stopping at the first non-background cell.
    for cells in comps:
        min_r = min(r for r, _ in cells)
        max_r = max(r for r, _ in cells)
        min_c = min(c for _, c in cells)
        max_c = max(c for _, c in cells)

        # Candidate ray colors adjacent to the object's bounding box.
        adj_colors = set()
        for r in range(max(0, min_r - 1), min(h, max_r + 2)):
            for c in (min_c - 1, max_c + 1):
                if 0 <= c < w and is_ray(g[r, c]):
                    adj_colors.add(g[r, c])
        for c in range(max(0, min_c - 1), min(w, max_c + 2)):
            for r in (min_r - 1, max_r + 1):
                if 0 <= r < h and is_ray(g[r, c]):
                    adj_colors.add(g[r, c])

        if len(adj_colors) != 1:
            continue
        color = next(iter(adj_colors))

        # Determine the direction from the object to the adjacent ray pixel.
        # Prefer the side with the largest perpendicular span; this handles
        # both vertical and horizontal objects.
        best_dir = None
        best_score = -1
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            # Check if there is an adjacent ray pixel in this direction.
            found = False
            if dr == -1:
                for c in range(min_c, max_c + 1):
                    if min_r - 1 >= 0 and g[min_r - 1, c] == color:
                        found = True
                        break
            elif dr == 1:
                for c in range(min_c, max_c + 1):
                    if max_r + 1 < h and g[max_r + 1, c] == color:
                        found = True
                        break
            elif dc == -1:
                for r in range(min_r, max_r + 1):
                    if min_c - 1 >= 0 and g[r, min_c - 1] == color:
                        found = True
                        break
            elif dc == 1:
                for r in range(min_r, max_r + 1):
                    if max_c + 1 < w and g[r, max_c + 1] == color:
                        found = True
                        break
            if not found:
                continue

            # Score by how far the ray can extend before hitting a non-background cell.
            if dr == -1:
                start = min_r - 1
                length = 0
                while start - length - 1 >= 0 and g[start - length - 1, min_c] == 8:
                    length += 1
                score = length
            elif dr == 1:
                start = max_r + 1
                length = 0
                while start + length + 1 < h and g[start + length + 1, min_c] == 8:
                    length += 1
                score = length
            elif dc == -1:
                start = min_c - 1
                length = 0
                while start - length - 1 >= 0 and g[min_r, start - length - 1] == 8:
                    length += 1
                score = length
            elif dc == 1:
                start = max_c + 1
                length = 0
                while start + length + 1 < w and g[min_r, start + length + 1] == 8:
                    length += 1
                score = length

            if score > best_score:
                best_score = score
                best_dir = (dr, dc)

        if best_dir is None:
            continue

        dr, dc = best_dir

        # Draw the ray from the object edge outward.
        if dr == -1:
            for c in range(min_c, max_c + 1):
                r = min_r - 1
                while r >= 0 and out[r, c] == 8:
                    out[r, c] = color
                    r -= 1
        elif dr == 1:
            for c in range(min_c, max_c + 1):
                r = max_r + 1
                while r < h and out[r, c] == 8:
                    out[r, c] = color
                    r += 1
        elif dc == -1:
            for r in range(min_r, max_r + 1):
                c = min_c - 1
                while c >= 0 and out[r, c] == 8:
                    out[r, c] = color
                    c -= 1
        elif dc == 1:
            for r in range(min_r, max_r + 1):
                c = max_c + 1
                while c < w and out[r, c] == 8:
                    out[r, c] = color
                    c += 1

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Connected components of non-background pixels.
    seen = np.zeros((h, w), dtype=bool)
    comps = []
    for r in range(h):
        for c in range(w):
            if g[r, c] != 8 and not seen[r, c]:
                stack = [(r, c)]
                seen[r, c] = True
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and not seen[ny, nx] and g[ny, nx] != 8:
                            seen[ny, nx] = True
                            stack.append((ny, nx))
                comps.append(cells)

    # For each component, infer the three beam colors and the side from which
    # they are emitted.  The side is the one with the largest straight run of
    # background cells immediately outside the component's bounding box.
    for cells in comps:
        rs = [r for r, _ in cells]
        cs = [c for _, c in cells]
        r0, r1 = min(rs), max(rs)
        c0, c1 = min(cs), max(cs)
        height = r1 - r0 + 1
        width = c1 - c0 + 1

        # Candidate beam colors: non-background colors in this component that
        # are not the dominant "spine" color.
        color_counts = {}
        for r, c in cells:
            v = int(g[r, c])
            color_counts[v] = color_counts.get(v, 0) + 1
        if not color_counts:
            continue

        # The spine color is the most common color in the component.
        spine_color = max(color_counts.items(), key=lambda kv: (kv[1], -kv[0]))[0]
        beam_colors = [v for v in color_counts if v != spine_color]
        if not beam_colors:
            continue

        # Determine emission side by the longest clear background run outside
        # the bounding box.
        def run_up():
            best = 0
            for c in range(c0, c1 + 1):
                if c0 - 1 < 0:
                    break
                length = 0
                r = r0 - 1
                while r >= 0 and g[r, c] == 8:
                    length += 1
                    r -= 1
                best = max(best, length)
            return best

        def run_down():
            best = 0
            for c in range(c0, c1 + 1):
                if r1 + 1 >= h:
                    break
                length = 0
                r = r1 + 1
                while r < h and g[r, c] == 8:
                    length += 1
                    r += 1
                best = max(best, length)
            return best

        def run_left():
            best = 0
            for r in range(r0, r1 + 1):
                if c0 - 1 < 0:
                    break
                length = 0
                c = c0 - 1
                while c >= 0 and g[r, c] == 8:
                    length += 1
                    c -= 1
                best = max(best, length)
            return best

        def run_right():
            best = 0
            for r in range(r0, r1 + 1):
                if c1 + 1 >= w:
                    break
                length = 0
                c = c1 + 1
                while c < w and g[r, c] == 8:
                    length += 1
                    c += 1
                best = max(best, length)
            return best

        side_scores = {
            "up": run_up(),
            "down": run_down(),
            "left": run_left(),
            "right": run_right(),
        }
        side = max(side_scores.items(), key=lambda kv: (kv[1], kv[0]))[0]
        if side_scores[side] <= 0:
            continue

        # Choose the three beam colors.  If there are exactly three, use them.
        # If there are more, prefer colors that already appear adjacent to the
        # component on the emission side; otherwise use the three smallest.
        if len(beam_colors) == 3:
            chosen = beam_colors
        else:
            adjacent = set()
            if side == "up":
                for c in range(c0, c1 + 1):
                    if r0 - 1 >= 0 and g[r0 - 1, c] != 8:
                        adjacent.add(int(g[r0 - 1, c]))
            elif side == "down":
                for c in range(c0, c1 + 1):
                    if r1 + 1 < h and g[r1 + 1, c] != 8:
                        adjacent.add(int(g[r1 + 1, c]))
            elif side == "left":
                for r in range(r0, r1 + 1):
                    if c0 - 1 >= 0 and g[r, c0 - 1] != 8:
                        adjacent.add(int(g[r, c0 - 1]))
            elif side == "right":
                for r in range(r0, r1 + 1):
                    if c1 + 1 < w and g[r, c1 + 1] != 8:
                        adjacent.add(int(g[r, c1 + 1]))

            chosen = [v for v in beam_colors if v in adjacent]
            if len(chosen) < 3:
                chosen = sorted(beam_colors)[:3]
            else:
                chosen = chosen[:3]

        # Order the three colors.  The examples use a consistent cyclic order
        # for the three beam colors: for 1,5,6 it is 1,5,6; for 3,6,9 it is
        # 3,6,9.  We sort them, which matches both observed palettes.
        chosen = sorted(chosen)

        # Beam positions along the emitting side.
        # For vertical objects (height > width), use offsets 1,3,5 from the top
        # when height is 9, and 1,4,5 when height is 7.  For horizontal objects,
        # use the rightmost three odd/even positions observed in the examples.
        if height >= width:
            if height == 9:
                offsets = [1, 3, 5]
            elif height == 7:
                offsets = [1, 4, 5]
            else:
                # Fallback: evenly spaced positions.
                offsets = [1, height // 2, height - 2]
            positions = [(r0 + off, None) for off in offsets]
        else:
            if width == 9:
                # Observed for the 9-wide horizontal object: rightmost, then
                # two steps left, then four steps left.
                offsets_from_right = [0, 2, 4]
                positions = [(None, c1 - off) for off in offsets_from_right]
            else:
                # Fallback: rightmost three positions spaced by 2.
                positions = [(None, c1 - 2 * i) for i in range(3)]

        # Draw beams.  The color order is assigned from the start of the
        # emission side toward the end: top-to-bottom for vertical, left-to-right
        # for horizontal.  For the observed horizontal case, this gives the
        # required right-to-left color order because positions are generated
        # right-to-left; we therefore sort positions left-to-right and assign
        # colors in reverse for horizontal objects.
        if height >= width:
            # vertical: top-to-bottom
            pos_sorted = sorted(positions, key=lambda p: p[0])
            for (r, _), color in zip(pos_sorted, chosen):
                if side == "left":
                    c = c0 - 1
                    while c >= 0 and out[r, c] == 8:
                        out[r, c] = color
                        c -= 1
                elif side == "right":
                    c = c1 + 1
                    while c < w and out[r, c] == 8:
                        out[r, c] = color
                        c += 1
        else:
            # horizontal: left-to-right positions, but colors are observed
            # right-to-left in the examples.
            pos_sorted = sorted(positions, key=lambda p: p[1])
            for (_, c), color in zip(pos_sorted, reversed(chosen)):
                if side == "up":
                    r = r0 - 1
                    while r >= 0 and out[r, c] == 8:
                        out[r, c] = color
                        r -= 1
                elif side == "down":
                    r = r1 + 1
                    while r < h and out[r, c] == 8:
                        out[r, c] = color
                        r += 1

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    H, W = g.shape
    out = np.full((H, W), 8, dtype=int)

    # Find the 4/2 arrow marker.
    fours = [(r, c) for r in range(H) for c in range(W) if g[r, c] == 4]
    if not fours:
        return out.tolist()

    fr, fc = fours[0]
    # Direction is from the 2 tail toward the 4 head.
    dr, dc = 0, 0
    for r in range(fr + 1, H):
        if g[r, fc] == 2:
            dr, dc = -1, 0
            break
    if dr == 0 and dc == 0:
        for r in range(fr - 1, -1, -1):
            if g[r, fc] == 2:
                dr, dc = 1, 0
                break
    if dr == 0 and dc == 0:
        for c in range(fc + 1, W):
            if g[fr, c] == 2:
                dr, dc = 0, -1
                break
    if dr == 0 and dc == 0:
        for c in range(fc - 1, -1, -1):
            if g[fr, c] == 2:
                dr, dc = 0, 1
                break

    # Keep the original marker segment.
    for r in range(H):
        if g[r, fc] in (2, 4):
            out[r, fc] = 2
    for c in range(W):
        if g[fr, c] in (2, 4):
            out[fr, c] = 2

    # Identify diamond nodes made of 1s and 3s.
    seen = np.zeros((H, W), dtype=bool)
    nodes = []
    for r in range(H):
        for c in range(W):
            if g[r, c] in (1, 3) and not seen[r, c]:
                stack = [(r, c)]
                comp = []
                seen[r, c] = True
                while stack:
                    y, x = stack.pop()
                    comp.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < H and 0 <= nx < W and not seen[ny, nx] and g[ny, nx] in (1, 3):
                            seen[ny, nx] = True
                            stack.append((ny, nx))
                nodes.append(comp)

    def node_dir(comp):
        cells = set(comp)
        ones = [(r, c) for r, c in comp if g[r, c] == 1]
        threes = [(r, c) for r, c in comp if g[r, c] == 3]
        if not threes:
            return None

        # For each 3, see if replacing it by 1 would make the component
        # symmetric under reflection across the corresponding side.
        for r, c in threes:
            # Up
            refl = {(2 * r - rr, cc) for rr, cc in ones}
            if all((rr, cc) in cells or (rr, cc) == (r, c) for rr, cc in refl):
                return (-1, 0)
            # Down
            refl = {(2 * r - rr, cc) for rr, cc in ones}
            if all((rr, cc) in cells or (rr, cc) == (r, c) for rr, cc in refl):
                return (1, 0)
            # Left
            refl = {(rr, 2 * c - cc) for rr, cc in ones}
            if all((rr, cc) in cells or (rr, cc) == (r, c) for rr, cc in refl):
                return (0, -1)
            # Right
            refl = {(rr, 2 * c - cc) for rr, cc in ones}
            if all((rr, cc) in cells or (rr, cc) == (r, c) for rr, cc in refl):
                return (0, 1)
        return None

    def ray_start(comp, d):
        dr, dc = d
        best = None
        for r, c in comp:
            if g[r, c] != 3:
                continue
            # The ray starts just outside the 3 cell.
            sr, sc = r + dr, c + dc
            if not (0 <= sr < H and 0 <= sc < W):
                continue
            # Choose the 3 cell farthest in the ray direction.
            key = (sr * dr + sc * dc) if dr or dc else 0
            if best is None or key > best[0]:
                best = (key, sr, sc)
        if best is None:
            return None
        return best[1], best[2]

    def first_node_hit(sr, sc, dr, dc, exclude):
        r, c = sr, sc
        while 0 <= r < H and 0 <= c < W:
            for idx, comp in enumerate(nodes):
                if idx == exclude:
                    continue
                if (r, c) in comp:
                    return idx
            r += dr
            c += dc
        return None

    active = set()
    queue = []

    # Marker ray.
    r, c = fr + dr, fc + dc
    while 0 <= r < H and 0 <= c < W:
        out[r, c] = 2
        hit = None
        for idx, comp in enumerate(nodes):
            if (r, c) in comp:
                hit = idx
                break
        if hit is not None:
            active.add(hit)
            queue.append(hit)
            break
        r += dr
        c += dc

    # Propagate through active nodes.
    while queue:
        idx = queue.pop()
        d = node_dir(nodes[idx])
        if d is None:
            continue
        start = ray_start(nodes[idx], d)
        if start is None:
            continue
        r, c = start
        while 0 <= r < H and 0 <= c < W:
            out[r, c] = 2
            hit = first_node_hit(r, c, d[0], d[1], idx)
            if hit is not None:
                if hit not in active:
                    active.add(hit)
                    queue.append(hit)
                break
            r += d[0]
            c += d[1]

    # Paint active nodes.
    for idx in active:
        for r, c in nodes[idx]:
            out[r, c] = 2

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    W = len(grid[0])

    out = [[8] * W for _ in range(H)]

    # Find the 4/2 marker.
    four = None
    for r in range(H):
        for c in range(W):
            if grid[r][c] == 4:
                four = (r, c)
                break
        if four is not None:
            break

    if four is None:
        return out

    fr, fc = four

    # The marker points from its 2-tail toward the 4-head.
    tail_dir = None
    for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
        nr, nc = fr + dr, fc + dc
        if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] == 2:
            tail_dir = (dr, dc)
            break

    if tail_dir is None:
        # Fallback: assume the tail is below the head.
        tail_dir = (1, 0)

    mdr, mdc = -tail_dir[0], -tail_dir[1]

    # Keep the original marker segment as 2.
    for r in range(H):
        for c in range(W):
            if grid[r][c] in (2, 4):
                out[r][c] = 2

    # Find all diamond components made of 1s and 3s.
    comp_id = [[-1] * W for _ in range(H)]
    comps = []

    for r in range(H):
        for c in range(W):
            if grid[r][c] in (1, 3) and comp_id[r][c] == -1:
                cid = len(comps)
                stack = [(r, c)]
                comp_id[r][c] = cid
                cells = []

                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if (
                            0 <= ny < H
                            and 0 <= nx < W
                            and comp_id[ny][nx] == -1
                            and grid[ny][nx] in (1, 3)
                        ):
                            comp_id[ny][nx] = cid
                            stack.append((ny, nx))

                comps.append(cells)

    # Determine each component's emission direction from its 3-side.
    dirs = [None] * len(comps)
    threes = [None] * len(comps)

    for i, cells in enumerate(comps):
        t = [(r, c) for r, c in cells if grid[r][c] == 3]
        threes[i] = t
        if not t:
            continue

        min_r = min(r for r, _ in cells)
        max_r = max(r for r, _ in cells)
        min_c = min(c for _, c in cells)
        max_c = max(c for _, c in cells)

        top = sum(1 for r, c in t if r == min_r)
        bottom = sum(1 for r, c in t if r == max_r)
        left = sum(1 for r, c in t if c == min_c)
        right = sum(1 for r, c in t if c == max_c)

        best = max(
            (("up", top), ("down", bottom), ("left", left), ("right", right)),
            key=lambda x: x[1],
        )

        if best[1] == 0:
            dirs[i] = None
        else:
            dirs[i] = {
                "up": (-1, 0),
                "down": (1, 0),
                "left": (0, -1),
                "right": (0, 1),
            }[best[0]]

    active = [False] * len(comps)
    queue = []

    def activate(i):
        if not active[i]:
            active[i] = True
            queue.append(i)
            for r, c in comps[i]:
                out[r][c] = 2

    def shoot(r, c, dr, dc):
        while 0 <= r < H and 0 <= c < W:
            cid = comp_id[r][c]
            if cid != -1:
                out[r][c] = 2
                activate(cid)
                return
            out[r][c] = 2
            r += dr
            c += dc

    # Initial marker beam.
    shoot(fr + mdr, fc + mdc, mdr, mdc)

    # Propagate beams through activated diamonds.
    while queue:
        i = queue.pop()
        d = dirs[i]
        if d is None:
            continue

        dr, dc = d
        for r, c in threes[i]:
            shoot(r + dr, c + dc, dr, dc)

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Candidate frame colours: non-zero colours that form at least one
    # complete horizontal or vertical line of length >= 4.
    candidates = set()
    for c in range(1, 10):
        mask = (g == c)
        # horizontal lines
        for r in range(H):
            run = 0
            for cc in range(W):
                if mask[r, cc]:
                    run += 1
                    if run >= 4:
                        candidates.add(c)
                        break
                else:
                    run = 0
        # vertical lines
        for c in range(W):
            run = 0
            for rr in range(H):
                if mask[rr, c]:
                    run += 1
                    if run >= 4:
                        candidates.add(c)
                        break
                else:
                    run = 0

    # Find rectangular frames for each candidate colour.
    frames = []
    for c in candidates:
        mask = (g == c)
        rows = np.where(mask.any(axis=1))[0]
        cols = np.where(mask.any(axis=0))[0]
        if len(rows) == 0 or len(cols) == 0:
            continue
        r0, r1 = int(rows[0]), int(rows[-1])
        c0, c1 = int(cols[0]), int(cols[-1])
        h = r1 - r0 + 1
        w = c1 - c0 + 1
        if h < 4 or w < 4:
            continue

        # The four sides must be mostly this colour.
        side = (
            mask[r0, c0:c1 + 1].sum() +
            mask[r1, c0:c1 + 1].sum() +
            mask[r0:r1 + 1, c0].sum() +
            mask[r0:r1 + 1, c1].sum()
        )
        perimeter = 2 * (h + w) - 4
        if side < 0.75 * perimeter:
            continue

        frames.append((c, r0, c0, r1, c1))

    if not frames:
        return []

    # The filler colour is the most frequent non-frame, non-background colour.
    frame_colors = {f[0] for f in frames}
    counts = {}
    for v in g.flat:
        v = int(v)
        if v != 0 and v not in frame_colors:
            counts[v] = counts.get(v, 0) + 1
    filler = max(counts, key=lambda x: (counts[x], -x)) if counts else 0

    def hole_count(color, r0, c0, r1, c1):
        # Count enclosed 0-regions inside the frame.
        # Walls are the frame colour, the filler colour, and any other frame colour.
        walls = frame_colors | {filler}
        seen = np.zeros((H, W), dtype=bool)
        q = deque()

        # Seed from outside the frame.
        for r in range(H):
            for c in (c0 - 1, c1 + 1):
                if 0 <= c < W and not seen[r, c] and g[r, c] == 0:
                    seen[r, c] = True
                    q.append((r, c))
        for c in range(W):
            for r in (r0 - 1, r1 + 1):
                if 0 <= r < H and not seen[r, c] and g[r, c] == 0:
                    seen[r, c] = True
                    q.append((r, c))

        while q:
            r, c = q.popleft()
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < H and 0 <= nc < W and not seen[nr, nc] and g[nr, nc] == 0:
                    seen[nr, nc] = True
                    q.append((nr, nc))

        # Any unvisited 0-cell strictly inside the frame is a hole.
        cnt = 0
        for r in range(r0 + 1, r1):
            for c in range(c0 + 1, c1):
                if g[r, c] == 0 and not seen[r, c]:
                    cnt += 1
                    q = deque([(r, c)])
                    seen[r, c] = True
                    while q:
                        rr, cc = q.popleft()
                        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                            nr, nc = rr + dr, cc + dc
                            if (0 <= nr < H and 0 <= nc < W and
                                    not seen[nr, nc] and g[nr, nc] == 0):
                                seen[nr, nc] = True
                                q.append((nr, nc))
        return cnt

    scored = []
    for f in frames:
        c, r0, c0, r1, c1 = f
        h = hole_count(c, r0, c0, r1, c1)
        # Rank is the number of holes, capped at 4 for output width.
        rank = min(max(h, 1), 4)
        scored.append((rank, r0, -c0, c, r0, c0, r1, c1))

    # Sort by rank, then top-to-bottom, then right-to-left.
    scored.sort(key=lambda x: (x[0], x[1], x[2]))

    out = []
    for rank, *_ in scored:
        color = scored[scored.index((rank, *_))][3] if False else None
    # Simpler: rebuild from sorted tuples.
    out = []
    for item in scored:
        rank = item[0]
        color = item[3]
        row = [color] * rank + [filler] * (4 - rank)
        out.append(row)

    return out

