def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    def is_9_line(r1, r2, c):
        if c < 0 or c >= w:
            return False
        for r in range(r1, r2 + 1):
            if g[r, c] != 9:
                return False
        return True

    def is_6_line(r1, r2, c):
        if c < 0 or c >= w:
            return False
        for r in range(r1, r2 + 1):
            if g[r, c] != 6:
                return False
        return True

    def is_9_row(c1, c2, r):
        if r < 0 or r >= h:
            return False
        for c in range(c1, c2 + 1):
            if g[r, c] != 9:
                return False
        return True

    def is_6_row(c1, c2, r):
        if r < 0 or r >= h:
            return False
        for c in range(c1, c2 + 1):
            if g[r, c] != 6:
                return False
        return True

    def content_cells(r1, r2, c1, c2):
        cells = []
        for r in range(r1, r2 + 1):
            for c in range(c1, c2 + 1):
                if g[r, c] in (5, 7):
                    cells.append((r, c))
        return cells

    def transform_content(cells):
        if not cells:
            return []
        rs = [r for r, _ in cells]
        cs = [c for _, c in cells]
        rmin, rmax = min(rs), max(rs)
        cmin, cmax = min(cs), max(cs)
        height = rmax - rmin + 1
        width = cmax - cmin + 1

        # 180-degree rotation of the content bounding box, with 5 <-> 7.
        res = []
        for r, c in cells:
            nr = rmin + (rmax - r)
            nc = cmin + (cmax - c)
            val = 7 if g[r, c] == 5 else 5
            res.append((nr, nc, val))
        return res

    def place(cells, rmin, cmin):
        for r, c, v in cells:
            out[r, c] = v

    # Horizontal objects: vertical 9 line, vertical 6 line, content on one side.
    for r1 in range(h):
        for r2 in range(r1, h):
            for c in range(w):
                if not is_9_line(r1, r2, c):
                    continue
                # content to the left of the 9 line
                left_cells = content_cells(r1, r2, 0, c - 1)
                if left_cells:
                    # find a 6 line immediately to the right of the 9 line
                    if is_6_line(r1, r2, c + 1):
                        # clear the 9 line and the 6 line
                        for r in range(r1, r2 + 1):
                            out[r, c] = 0
                            out[r, c + 1] = 6
                        # place transformed content to the right of the 6 line
                        tcells = transform_content(left_cells)
                        # align by bounding box: keep same vertical span
                        rs = [r for r, _, _ in tcells]
                        rmin_t = min(rs)
                        shift_r = r1 - rmin_t
                        tcells = [(r + shift_r, c + 2 + (cc - min(x[1] for x in tcells)), v)
                                  for r, cc, v in tcells]
                        place(tcells, r1, c + 2)
                        continue

                # content to the right of the 9 line
                right_cells = content_cells(r1, r2, c + 1, w - 1)
                if right_cells:
                    # find a 6 line immediately to the left of the 9 line
                    if is_6_line(r1, r2, c - 1):
                        for r in range(r1, r2 + 1):
                            out[r, c] = 0
                            out[r, c - 1] = 6
                        tcells = transform_content(right_cells)
                        rs = [r for r, _, _ in tcells]
                        rmin_t = min(rs)
                        shift_r = r1 - rmin_t
                        tcells = [(r + shift_r, c - 2 - (max(x[1] for x in tcells) - cc), v)
                                  for r, cc, v in tcells]
                        place(tcells, r1, c - 2)
                        continue

    # Vertical objects: horizontal 9 line, horizontal 6 line, content above/below.
    for c1 in range(w):
        for c2 in range(c1, w):
            for r in range(h):
                if not is_9_row(c1, c2, r):
                    continue
                # content above the 9 line
                up_cells = content_cells(0, r - 1, c1, c2)
                if up_cells:
                    if is_6_row(c1, c2, r + 1):
                        for c in range(c1, c2 + 1):
                            out[r, c] = 0
                            out[r + 1, c] = 6
                        tcells = transform_content(up_cells)
                        cs = [c for _, c, _ in tcells]
                        cmin_t = min(cs)
                        shift_c = c1 - cmin_t
                        tcells = [(r + 2 + (rr - min(x[0] for x in tcells)), c + shift_c, v)
                                  for rr, c, v in tcells]
                        place(tcells, r + 2, c1)
                        continue

                # content below the 9 line
                down_cells = content_cells(r + 1, h - 1, c1, c2)
                if down_cells:
                    if is_6_row(c1, c2, r - 1):
                        for c in range(c1, c2 + 1):
                            out[r, c] = 0
                            out[r - 1, c] = 6
                        tcells = transform_content(down_cells)
                        cs = [c for _, c, _ in tcells]
                        cmin_t = min(cs)
                        shift_c = c1 - cmin_t
                        tcells = [(r - 2 - (max(x[0] for x in tcells) - rr), c + shift_c, v)
                                  for rr, c, v in tcells]
                        place(tcells, r - 2, c1)
                        continue

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    def is_9_line(r1, r2, c):
        if c < 0 or c >= w:
            return False
        for r in range(r1, r2 + 1):
            if g[r, c] != 9:
                return False
        return True

    def is_6_line(r1, r2, c):
        if c < 0 or c >= w:
            return False
        for r in range(r1, r2 + 1):
            if g[r, c] != 6:
                return False
        return True

    def is_9_row(c1, c2, r):
        if r < 0 or r >= h:
            return False
        for c in range(c1, c2 + 1):
            if g[r, c] != 9:
                return False
        return True

    def is_6_row(c1, c2, r):
        if r < 0 or r >= h:
            return False
        for c in range(c1, c2 + 1):
            if g[r, c] != 6:
                return False
        return True

    def content_cells(r1, r2, c1, c2):
        cells = []
        for r in range(r1, r2 + 1):
            for c in range(c1, c2 + 1):
                if g[r, c] in (5, 7):
                    cells.append((r, c))
        return cells

    def transform_content(cells):
        if not cells:
            return []
        rs = [r for r, _ in cells]
        cs = [c for _, c in cells]
        rmin, rmax = min(rs), max(rs)
        cmin, cmax = min(cs), max(cs)

        # 180-degree rotation of the content bounding box, with 5 <-> 7.
        res = []
        for r, c in cells:
            nr = rmin + (rmax - r)
            nc = cmin + (cmax - c)
            val = 7 if g[r, c] == 5 else 5
            res.append((nr, nc, val))
        return res

    def place(cells):
        for r, c, v in cells:
            if 0 <= r < h and 0 <= c < w:
                out[r, c] = v

    # Vertical 9 line, vertical 6 line on one side, content on the other side.
    for r1 in range(h):
        for r2 in range(r1, h):
            for c in range(w):
                if not is_9_line(r1, r2, c):
                    continue

                # Content to the left of the 9 line, 6 line immediately to the right.
                if is_6_line(r1, r2, c + 1):
                    left_cells = content_cells(r1, r2, 0, c - 1)
                    if left_cells:
                        for r in range(r1, r2 + 1):
                            out[r, c] = 0
                        tcells = transform_content(left_cells)
                        rs = [r for r, _, _ in tcells]
                        shift_r = r1 - min(rs)
                        tcells = [(r + shift_r, c + 2 + (cc - min(x[1] for x in tcells)), v)
                                  for r, cc, v in tcells]
                        place(tcells)
                        continue

                # Content to the right of the 9 line, 6 line immediately to the left.
                if is_6_line(r1, r2, c - 1):
                    right_cells = content_cells(r1, r2, c + 1, w - 1)
                    if right_cells:
                        for r in range(r1, r2 + 1):
                            out[r, c] = 0
                        tcells = transform_content(right_cells)
                        rs = [r for r, _, _ in tcells]
                        shift_r = r1 - min(rs)
                        tcells = [(r + shift_r, c - 2 - (max(x[1] for x in tcells) - cc), v)
                                  for r, cc, v in tcells]
                        place(tcells)
                        continue

    # Horizontal 9 line, horizontal 6 line on one side, content on the other side.
    for c1 in range(w):
        for c2 in range(c1, w):
            for r in range(h):
                if not is_9_row(c1, c2, r):
                    continue

                # Content above the 9 line, 6 line immediately below.
                if is_6_row(c1, c2, r + 1):
                    up_cells = content_cells(0, r - 1, c1, c2)
                    if up_cells:
                        for c in range(c1, c2 + 1):
                            out[r, c] = 0
                        tcells = transform_content(up_cells)
                        cs = [c for _, c, _ in tcells]
                        shift_c = c1 - min(cs)
                        tcells = [(r + 2 + (rr - min(x[0] for x in tcells)), c + shift_c, v)
                                  for rr, c, v in tcells]
                        place(tcells)
                        continue

                # Content below the 9 line, 6 line immediately above.
                if is_6_row(c1, c2, r - 1):
                    down_cells = content_cells(r + 1, h - 1, c1, c2)
                    if down_cells:
                        for c in range(c1, c2 + 1):
                            out[r, c] = 0
                        tcells = transform_content(down_cells)
                        cs = [c for _, c, _ in tcells]
                        shift_c = c1 - min(cs)
                        tcells = [(r - 2 - (max(x[0] for x in tcells) - rr), c + shift_c, v)
                                  for rr, c, v in tcells]
                        place(tcells)
                        continue

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    H, W = g.shape
    out = g.copy()

    # The non-background colour is the colour that fills the outer border.
    bg = int(g[0, 0])

    # Find all 0-bordered rectangular frames.
    # A frame is a rectangle whose four sides are all 0 in the input.
    frames = []
    for r1 in range(H):
        for r2 in range(r1 + 1, H):
            for c1 in range(W):
                for c2 in range(c1 + 1, W):
                    if (
                        np.all(g[r1, c1:c2 + 1] == 0) and
                        np.all(g[r2, c1:c2 + 1] == 0) and
                        np.all(g[r1:r2 + 1, c1] == 0) and
                        np.all(g[r1:r2 + 1, c2] == 0)
                    ):
                        frames.append((r1, c1, r2, c2))

    # Keep only maximal frames (not contained in another frame).
    maximal = []
    for f in frames:
        r1, c1, r2, c2 = f
        contained = False
        for o in frames:
            if o == f:
                continue
            or1, oc1, or2, oc2 = o
            if or1 <= r1 and oc1 <= c1 and or2 >= r2 and oc2 >= c2:
                contained = True
                break
        if not contained:
            maximal.append(f)

    def corner_cells(r1, c1, r2, c2, corner):
        """
        Return the cells to paint for a given corner.

        The rule inferred from the examples:
        - For each corner of a 0-frame, take the non-background digit
          closest to that corner inside the frame.
        - Paint a 2x2 block outward from the corner.
        - If the chosen digit is diagonally adjacent to the corner,
          also paint the 2x2 block between the digit and the corner.
        - The frame corner cell itself is not overwritten.
        """
        cells = []
        if corner == "TL":
            cr, cc = r1, c1
            outward = [(cr - 1, cc - 1), (cr - 1, cc), (cr, cc - 1), (cr, cc)]
            inward = [(cr, cc + 1), (cr + 1, cc), (cr + 1, cc + 1), (cr, cc)]
        elif corner == "TR":
            cr, cc = r1, c2
            outward = [(cr - 1, cc), (cr - 1, cc + 1), (cr, cc), (cr, cc + 1)]
            inward = [(cr, cc - 1), (cr + 1, cc - 1), (cr + 1, cc), (cr, cc)]
        elif corner == "BL":
            cr, cc = r2, c1
            outward = [(cr, cc - 1), (cr, cc), (cr + 1, cc - 1), (cr + 1, cc)]
            inward = [(cr - 1, cc), (cr - 1, cc + 1), (cr, cc), (cr, cc + 1)]
        else:  # BR
            cr, cc = r2, c2
            outward = [(cr, cc), (cr, cc + 1), (cr + 1, cc), (cr + 1, cc + 1)]
            inward = [(cr - 1, cc - 1), (cr - 1, cc), (cr, cc - 1), (cr, cc)]

        # Choose the interior digit closest to this corner.
        best = None
        best_dist = None
        for r in range(r1 + 1, r2):
            for c in range(c1 + 1, c2):
                v = int(g[r, c])
                if v == 0 or v == bg:
                    continue
                if corner == "TL":
                    d = (r - r1) + (c - c1)
                elif corner == "TR":
                    d = (r - r1) + (c2 - c)
                elif corner == "BL":
                    d = (r2 - r) + (c - c1)
                else:
                    d = (r2 - r) + (c2 - c)
                if best_dist is None or d < best_dist:
                    best_dist = d
                    best = (r, c, v)

        if best is None:
            return []

        dr, dc, val = best

        # Always paint the outward 2x2, except the frame corner itself.
        for r, c in outward:
            if 0 <= r < H and 0 <= c < W and not (r == cr and c == cc):
                cells.append((r, c, val))

        # If the digit is diagonally adjacent to the corner, also paint
        # the 2x2 block between the digit and the corner.
        if corner == "TL" and (dr, dc) == (r1 + 1, c1 + 1):
            for r, c in inward:
                if 0 <= r < H and 0 <= c < W and not (r == cr and c == cc):
                    cells.append((r, c, val))
        elif corner == "TR" and (dr, dc) == (r1 + 1, c2 - 1):
            for r, c in inward:
                if 0 <= r < H and 0 <= c < W and not (r == cr and c == cc):
                    cells.append((r, c, val))
        elif corner == "BL" and (dr, dc) == (r2 - 1, c1 + 1):
            for r, c in inward:
                if 0 <= r < H and 0 <= c < W and not (r == cr and c == cc):
                    cells.append((r, c, val))
        elif corner == "BR" and (dr, dc) == (r2 - 1, c2 - 1):
            for r, c in inward:
                if 0 <= r < H and 0 <= c < W and not (r == cr and c == cc):
                    cells.append((r, c, val))

        return cells

    for (r1, c1, r2, c2) in maximal:
        for corner in ("TL", "TR", "BL", "BR"):
            for r, c, val in corner_cells(r1, c1, r2, c2, corner):
                out[r, c] = val

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    H, W = g.shape
    out = g.copy()

    # Background is the border colour.
    bg = int(g[0, 0])

    # Find maximal rectangles whose four sides are all 0 in the input.
    frames = []
    for r1 in range(H):
        for r2 in range(r1 + 1, H):
            for c1 in range(W):
                for c2 in range(c1 + 1, W):
                    if (
                        np.all(g[r1, c1:c2 + 1] == 0) and
                        np.all(g[r2, c1:c2 + 1] == 0) and
                        np.all(g[r1:r2 + 1, c1] == 0) and
                        np.all(g[r1:r2 + 1, c2] == 0)
                    ):
                        frames.append((r1, c1, r2, c2))

    # Keep only maximal frames.
    maximal = []
    for f in frames:
        r1, c1, r2, c2 = f
        contained = False
        for o in frames:
            if o == f:
                continue
            or1, oc1, or2, oc2 = o
            if or1 <= r1 and oc1 <= c1 and or2 >= r2 and oc2 >= c2:
                contained = True
                break
        if not contained:
            maximal.append(f)

    def nearest_digit(r1, c1, r2, c2, corner):
        """
        Return (row, col, value) of the nearest non-background, non-zero
        digit strictly inside the frame, using Manhattan distance to the
        chosen corner.
        """
        best = None
        best_d = None

        for r in range(r1 + 1, r2):
            for c in range(c1 + 1, c2):
                v = int(g[r, c])
                if v == 0 or v == bg:
                    continue

                if corner == "TL":
                    d = (r - r1) + (c - c1)
                elif corner == "TR":
                    d = (r - r1) + (c2 - c)
                elif corner == "BL":
                    d = (r2 - r) + (c - c1)
                else:  # BR
                    d = (r2 - r) + (c2 - c)

                if best_d is None or d < best_d:
                    best_d = d
                    best = (r, c, v)

        return best

    def paint_corner(r1, c1, r2, c2, corner):
        best = nearest_digit(r1, c1, r2, c2, corner)
        if best is None:
            return

        dr, dc, val = best

        # The frame corner cell.
        if corner == "TL":
            cr, cc = r1, c1
            inside_dr, inside_dc = 1, 1
        elif corner == "TR":
            cr, cc = r1, c2
            inside_dr, inside_dc = 1, -1
        elif corner == "BL":
            cr, cc = r2, c1
            inside_dr, inside_dc = -1, 1
        else:  # BR
            cr, cc = r2, c2
            inside_dr, inside_dc = -1, -1

        # Always paint the corner cell and the cell diagonally inside it.
        out[cr, cc] = val
        ir, ic = cr + inside_dr, cc + inside_dc
        if 0 <= ir < H and 0 <= ic < W:
            out[ir, ic] = val

        # Paint the two outside cells that are edge-adjacent to the corner.
        if corner == "TL":
            cells = [(cr - 1, cc), (cr, cc - 1)]
        elif corner == "TR":
            cells = [(cr - 1, cc), (cr, cc + 1)]
        elif corner == "BL":
            cells = [(cr + 1, cc), (cr, cc - 1)]
        else:  # BR
            cells = [(cr + 1, cc), (cr, cc + 1)]

        for r, c in cells:
            if 0 <= r < H and 0 <= c < W:
                out[r, c] = val

        # Paint the fourth outside cell only when the chosen digit is not
        # diagonally adjacent to the corner.
        if corner == "TL":
            if not (dr == r1 + 1 and dc == c1 + 1):
                r, c = cr - 1, cc - 1
                if 0 <= r < H and 0 <= c < W:
                    out[r, c] = val
        elif corner == "TR":
            if not (dr == r1 + 1 and dc == c2 - 1):
                r, c = cr - 1, cc + 1
                if 0 <= r < H and 0 <= c < W:
                    out[r, c] = val
        elif corner == "BL":
            if not (dr == r2 - 1 and dc == c1 + 1):
                r, c = cr + 1, cc - 1
                if 0 <= r < H and 0 <= c < W:
                    out[r, c] = val
        else:  # BR
            if not (dr == r2 - 1 and dc == c2 - 1):
                r, c = cr + 1, cc + 1
                if 0 <= r < H and 0 <= c < W:
                    out[r, c] = val

    for (r1, c1, r2, c2) in maximal:
        for corner in ("TL", "TR", "BL", "BR"):
            paint_corner(r1, c1, r2, c2, corner)

    return out.tolist()

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    def is_bg(v):
        return v == 8

    def is_one(v):
        return v == 1

    # Find connected components of 1s (4-connected).
    seen = np.zeros((h, w), dtype=bool)
    diamonds = []
    for r in range(h):
        for c in range(w):
            if g[r, c] == 1 and not seen[r, c]:
                stack = [(r, c)]
                seen[r, c] = True
                comp = []
                while stack:
                    y, x = stack.pop()
                    comp.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and not seen[ny, nx] and g[ny, nx] == 1:
                            seen[ny, nx] = True
                            stack.append((ny, nx))
                diamonds.append(comp)

    def side_cells(comp, direction):
        """Return the side cells of a diamond component in a given direction."""
        cells = set(comp)
        res = []
        for (r, c) in comp:
            if direction == 'up' and (r - 1, c) not in cells and r > 0:
                res.append((r - 1, c))
            elif direction == 'down' and (r + 1, c) not in cells and r + 1 < h:
                res.append((r + 1, c))
            elif direction == 'left' and (r, c - 1) not in cells and c > 0:
                res.append((r, c - 1))
            elif direction == 'right' and (r, c + 1) not in cells and c + 1 < w:
                res.append((r, c + 1))
        return res

    def tail_pattern(side, direction):
        """
        Infer a repeating pattern from the tail adjacent to the diamond.
        Returns (period, pattern) where pattern is a list of row/col slices.
        """
        if not side:
            return None

        # Sort side cells consistently.
        if direction in ('up', 'down'):
            side = sorted(set(side), key=lambda p: (p[1], p[0]))
        else:
            side = sorted(set(side), key=lambda p: (p[0], p[1]))

        # The side should be a contiguous line of width 1 or 2.
        if direction in ('up', 'down'):
            cols = sorted({c for _, c in side})
            if len(cols) > 2:
                return None
            # First row adjacent to diamond.
            first_row = min(r for r, _ in side)
            first = [g[first_row, c] for c in cols]

            # Try to get second row further from diamond.
            second = None
            if direction == 'up':
                rows = sorted({r for r, _ in side}, reverse=True)
                if len(rows) >= 2:
                    second_row = rows[1]
                    second = [g[second_row, c] for c in cols]
            else:
                rows = sorted({r for r, _ in side})
                if len(rows) >= 2:
                    second_row = rows[1]
                    second = [g[second_row, c] for c in cols]

            if second is not None and second != first:
                return (2, [first, second])
            return (1, [first])

        else:
            rows = sorted({r for r, _ in side})
            if len(rows) > 2:
                return None
            first_col = min(c for _, c in side)
            first = [g[r, first_col] for r in rows]

            second = None
            if direction == 'left':
                cols = sorted({c for _, c in side}, reverse=True)
                if len(cols) >= 2:
                    second_col = cols[1]
                    second = [g[r, second_col] for r in rows]
            else:
                cols = sorted({c for _, c in side})
                if len(cols) >= 2:
                    second_col = cols[1]
                    second = [g[r, second_col] for r in rows]

            if second is not None and second != first:
                return (2, [first, second])
            return (1, [first])

    def fill_tail(direction, side, pattern_info):
        if pattern_info is None:
            return
        period, pat = pattern_info

        if direction == 'up':
            cols = sorted({c for _, c in side})
            start_row = min(r for r, _ in side)
            # The adjacent row is index 0 in the outward sequence.
            for i, r in enumerate(range(start_row - 1, -1, -1)):
                row_pat = pat[i % period]
                for j, c in enumerate(cols):
                    out[r, c] = row_pat[j]

        elif direction == 'down':
            cols = sorted({c for _, c in side})
            start_row = max(r for r, _ in side)
            for i, r in enumerate(range(start_row + 1, h)):
                row_pat = pat[i % period]
                for j, c in enumerate(cols):
                    out[r, c] = row_pat[j]

        elif direction == 'left':
            rows = sorted({r for r, _ in side})
            start_col = min(c for _, c in side)
            for i, c in enumerate(range(start_col - 1, -1, -1)):
                col_pat = pat[i % period]
                for j, r in enumerate(rows):
                    out[r, c] = col_pat[j]

        elif direction == 'right':
            rows = sorted({r for r, _ in side})
            start_col = max(c for _, c in side)
            for i, c in enumerate(range(start_col + 1, w)):
                col_pat = pat[i % period]
                for j, r in enumerate(rows):
                    out[r, c] = col_pat[j]

    for comp in diamonds:
        for direction in ('up', 'down', 'left', 'right'):
            side = side_cells(comp, direction)
            if not side:
                continue

            # The side must be occupied by non-background, non-1 cells.
            if any(g[r, c] == 8 or g[r, c] == 1 for r, c in side):
                continue

            # Determine whether the tail already reaches the boundary.
            if direction == 'up' and min(r for r, _ in side) == 0:
                continue
            if direction == 'down' and max(r for r, _ in side) == h - 1:
                continue
            if direction == 'left' and min(c for _, c in side) == 0:
                continue
            if direction == 'right' and max(c for _, c in side) == w - 1:
                continue

            pat = tail_pattern(side, direction)
            if pat is not None:
                fill_tail(direction, side, pat)

    return out.tolist()

import numpy as np
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Background is the most frequent colour (8 in the given tasks).
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # Find 4-connected components of 1s.
    seen = np.zeros((h, w), dtype=bool)
    comps = []
    for r in range(h):
        for c in range(w):
            if g[r, c] == 1 and not seen[r, c]:
                q = deque([(r, c)])
                seen[r, c] = True
                comp = []
                while q:
                    y, x = q.popleft()
                    comp.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and not seen[ny, nx] and g[ny, nx] == 1:
                            seen[ny, nx] = True
                            q.append((ny, nx))
                comps.append(comp)

    def contiguous_segments(cells, key):
        """Return maximal contiguous runs of cells sorted by key."""
        if not cells:
            return []
        cells = sorted(cells, key=key)
        segs = [[cells[0]]]
        for prev, cur in zip(cells, cells[1:]):
            if key(cur) == key(prev) + 1:
                segs[-1].append(cur)
            else:
                segs.append([cur])
        return segs

    def tail_info(comp, direction):
        """
        Return (side_cells, existing_tail_cells, pattern) for a tail attached
        to one flat side of a 1-component, or None if there is no tail.
        """
        if direction == 'up':
            min_r = min(r for r, _ in comp)
            side = [(r, c) for r, c in comp if r == min_r]
            side = contiguous_segments(side, lambda p: p[1])
            for seg in side:
                seg = sorted(seg, key=lambda p: p[1])
                adj = [(min_r - 1, c) for _, c in seg]
                if any(not (0 <= r < h and 0 <= c < w) or g[r, c] == bg or g[r, c] == 1 for r, c in adj):
                    continue
                # Follow the tail upward while the whole width is non-background.
                tail = [adj]
                r = min_r - 1
                while r - 1 >= 0:
                    row = [(r - 1, c) for _, c in seg]
                    if all(g[rr, cc] != bg for rr, cc in row):
                        tail.append(row)
                        r -= 1
                    else:
                        break
                # Pattern is the sequence of rows moving away from the diamond.
                pattern = [tuple(g[r, c] for _, c in row) for row in tail]
                return seg, tail, pattern

        elif direction == 'down':
            max_r = max(r for r, _ in comp)
            side = [(r, c) for r, c in comp if r == max_r]
            side = contiguous_segments(side, lambda p: p[1])
            for seg in side:
                seg = sorted(seg, key=lambda p: p[1])
                adj = [(max_r + 1, c) for _, c in seg]
                if any(not (0 <= r < h and 0 <= c < w) or g[r, c] == bg or g[r, c] == 1 for r, c in adj):
                    continue
                tail = [adj]
                r = max_r + 1
                while r + 1 < h:
                    row = [(r + 1, c) for _, c in seg]
                    if all(g[rr, cc] != bg for rr, cc in row):
                        tail.append(row)
                        r += 1
                    else:
                        break
                pattern = [tuple(g[r, c] for _, c in row) for row in tail]
                return seg, tail, pattern

        elif direction == 'left':
            min_c = min(c for _, c in comp)
            side = [(r, c) for r, c in comp if c == min_c]
            side = contiguous_segments(side, lambda p: p[0])
            for seg in side:
                seg = sorted(seg, key=lambda p: p[0])
                adj = [(r, min_c - 1) for r, _ in seg]
                if any(not (0 <= r < h and 0 <= c < w) or g[r, c] == bg or g[r, c] == 1 for r, c in adj):
                    continue
                tail = [adj]
                c = min_c - 1
                while c - 1 >= 0:
                    col = [(r, c - 1) for r, _ in seg]
                    if all(g[rr, cc] != bg for rr, cc in col):
                        tail.append(col)
                        c -= 1
                    else:
                        break
                pattern = [tuple(g[r, c] for r, _ in col) for col in tail]
                return seg, tail, pattern

        else:  # right
            max_c = max(c for _, c in comp)
            side = [(r, c) for r, c in comp if c == max_c]
            side = contiguous_segments(side, lambda p: p[0])
            for seg in side:
                seg = sorted(seg, key=lambda p: p[0])
                adj = [(r, max_c + 1) for r, _ in seg]
                if any(not (0 <= r < h and 0 <= c < w) or g[r, c] == bg or g[r, c] == 1 for r, c in adj):
                    continue
                tail = [adj]
                c = max_c + 1
                while c + 1 < w:
                    col = [(r, c + 1) for r, _ in seg]
                    if all(g[rr, cc] != bg for rr, cc in col):
                        tail.append(col)
                        c += 1
                    else:
                        break
                pattern = [tuple(g[r, c] for r, _ in col) for col in tail]
                return seg, tail, pattern

        return None

    def reaches_boundary(tail, direction):
        if not tail:
            return False
        if direction == 'up':
            return min(r for r, _ in tail[0]) == 0
        if direction == 'down':
            return max(r for r, _ in tail[-1]) == h - 1
        if direction == 'left':
            return min(c for _, c in tail[0]) == 0
        if direction == 'right':
            return max(c for _, c in tail[-1]) == w - 1
        return False

    def infer_period(pattern):
        """
        pattern[0] is adjacent to the diamond, pattern[1] is one step farther, etc.
        Return (period, sequence) where sequence is the repeating block outward.
        """
        if not pattern:
            return 1, [pattern[0]] if pattern else []
        if len(pattern) == 1:
            return 1, [pattern[0]]
        if pattern[0] == pattern[1]:
            return 1, [pattern[0]]
        # In all observed cases the period is 2.  If a longer period is present,
        # use the whole observed pattern as the period.
        return len(pattern), pattern

    def fill(direction, tail, period, seq):
        if not tail:
            return

        if direction == 'up':
            cols = sorted({c for _, c in tail[0]})
            start_r = min(r for r, _ in tail[0])
            # Existing tail has indices 0..len(tail)-1 moving upward.
            # Continue from the next row above the existing tail.
            idx = len(tail)
            r = start_r - 1
            while r >= 0:
                row_vals = seq[idx % period]
                for j, c in enumerate(cols):
                    out[r, c] = row_vals[j]
                idx += 1
                r -= 1

        elif direction == 'down':
            cols = sorted({c for _, c in tail[0]})
            start_r = max(r for r, _ in tail[-1])
            idx = len(tail)
            r = start_r + 1
            while r < h:
                row_vals = seq[idx % period]
                for j, c in enumerate(cols):
                    out[r, c] = row_vals[j]
                idx += 1
                r += 1

        elif direction == 'left':
            rows = sorted({r for r, _ in tail[0]})
            start_c = min(c for _, c in tail[0])
            idx = len(tail)
            c = start_c - 1
            while c >= 0:
                col_vals = seq[idx % period]
                for j, r in enumerate(rows):
                    out[r, c] = col_vals[j]
                idx += 1
                c -= 1

        elif direction == 'right':
            rows = sorted({r for r, _ in tail[0]})
            start_c = max(c for _, c in tail[-1])
            idx = len(tail)
            c = start_c + 1
            while c < w:
                col_vals = seq[idx % period]
                for j, r in enumerate(rows):
                    out[r, c] = col_vals[j]
                idx += 1
                c += 1

    # Complete every tail that does not already reach the grid boundary.
    for comp in comps:
        for direction in ('up', 'down', 'left', 'right'):
            info = tail_info(comp, direction)
            if info is None:
                continue
            side, tail, pattern = info
            if reaches_boundary(tail, direction):
                continue
            period, seq = infer_period(pattern)
            fill(direction, tail, period, seq)

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # The two dominant colors are the background colors.
    vals, counts = np.unique(g, return_counts=True)
    order = np.argsort(-counts)
    bg1, bg2 = int(vals[order[0]]), int(vals[order[1]])

    # Marker colors are all non-background colors.
    marker_colors = [int(c) for c in vals if c not in (bg1, bg2)]

    # Find connected components of marker colors.
    comp_id = -np.ones((h, w), dtype=int)
    comps = []
    for c in marker_colors:
        mask = (g == c)
        visited = np.zeros((h, w), dtype=bool)
        for r in range(h):
            for cc in range(w):
                if mask[r, cc] and not visited[r, cc]:
                    stack = [(r, cc)]
                    visited[r, cc] = True
                    cells = []
                    while stack:
                        y, x = stack.pop()
                        cells.append((y, x))
                        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < h and 0 <= nx < w and mask[ny, nx] and not visited[ny, nx]:
                                visited[ny, nx] = True
                                stack.append((ny, nx))
                    comps.append({
                        "color": c,
                        "cells": cells,
                        "size": len(cells),
                        "min_r": min(y for y, _ in cells),
                        "max_r": max(y for y, _ in cells),
                        "min_c": min(x for _, x in cells),
                        "max_c": max(x for _, x in cells),
                    })

    # Remove all marker cells from the output.
    out = g.copy()
    for comp in comps:
        for y, x in comp["cells"]:
            out[y, x] = 0

    # If there are no markers, nothing changes.
    if not comps:
        return out.tolist()

    # Choose the two main background colors:
    # - the one that forms the diagonal "corridor" is the less frequent one
    # - the other is the surrounding field.
    if counts[order[0]] >= counts[order[1]]:
        field_color, corridor_color = bg1, bg2
    else:
        field_color, corridor_color = bg2, bg1

    # Determine the diagonal direction from the corridor mask.
    corridor = (g == corridor_color)
    if corridor.any():
        ys, xs = np.nonzero(corridor)
        # If the corridor runs from top-right to bottom-left, slope is negative.
        # Use a simple correlation sign.
        if len(ys) > 1:
            cov = np.cov(ys, xs)[0, 1]
            top_right_to_bottom_left = cov < 0
        else:
            top_right_to_bottom_left = True
    else:
        top_right_to_bottom_left = True

    # Build a path through marker component centers.
    # The examples use a simple monotone path from one side to the other.
    centers = []
    for comp in comps:
        cy = (comp["min_r"] + comp["max_r"]) / 2.0
        cx = (comp["min_c"] + comp["max_c"]) / 2.0
        centers.append((cy, cx, comp["color"], comp))

    # Sort centers along the diagonal direction.
    if top_right_to_bottom_left:
        # top-right to bottom-left: decreasing column, increasing row
        centers.sort(key=lambda t: (t[1], -t[0]))
    else:
        # top-left to bottom-right: increasing column, increasing row
        centers.sort(key=lambda t: (t[1], t[0]))

    # The repeating pattern is the sequence of marker colors in path order.
    pattern = [c[2] for c in centers]
    if not pattern:
        return out.tolist()

    # Draw a 1-cell-wide path connecting the centers.
    # Use a simple Manhattan path: horizontal then vertical, or vertical then horizontal,
    # chosen to stay inside the corridor when possible.
    def draw_segment(r1, c1, r2, c2, start_idx):
        nonlocal start_idx
        # Prefer moving along the corridor: if top-right to bottom-left,
        # move horizontally first when going left, vertically first when going right.
        if top_right_to_bottom_left:
            if c2 < c1:
                # go left then down
                for c in range(c1, c2 - 1, -1):
                    out[r1, c] = pattern[start_idx % len(pattern)]
                    start_idx += 1
                for r in range(r1 + 1, r2 + 1):
                    out[r, c2] = pattern[start_idx % len(pattern)]
                    start_idx += 1
            else:
                # go down then right
                for r in range(r1 + 1, r2 + 1):
                    out[r, c1] = pattern[start_idx % len(pattern)]
                    start_idx += 1
                for c in range(c1 + 1, c2 + 1):
                    out[r2, c] = pattern[start_idx % len(pattern)]
                    start_idx += 1
        else:
            if c2 > c1:
                # go right then down
                for c in range(c1, c2 + 1):
                    out[r1, c] = pattern[start_idx % len(pattern)]
                    start_idx += 1
                for r in range(r1 + 1, r2 + 1):
                    out[r, c2] = pattern[start_idx % len(pattern)]
                    start_idx += 1
            else:
                # go down then left
                for r in range(r1 + 1, r2 + 1):
                    out[r, c1] = pattern[start_idx % len(pattern)]
                    start_idx += 1
                for c in range(c1 - 1, c2 - 1, -1):
                    out[r2, c] = pattern[start_idx % len(pattern)]
                    start_idx += 1
        return start_idx

    # Start at the first center.
    start_idx = 0
    r, c = int(round(centers[0][0])), int(round(centers[0][1]))
    out[r, c] = pattern[0]
    start_idx = 1

    for i in range(1, len(centers)):
        nr, nc = int(round(centers[i][0])), int(round(centers[i][1]))
        start_idx = draw_segment(r, c, nr, nc, start_idx)
        r, c = nr, nc

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # The two most frequent colors are the two background colors.
    vals, counts = np.unique(g, return_counts=True)
    order = np.argsort(-counts)
    bg1, bg2 = int(vals[order[0]]), int(vals[order[1]])
    marker_colors = [int(c) for c in vals if c not in (bg1, bg2)]

    # Connected components of marker colors.
    comps = []
    for c in marker_colors:
        mask = (g == c)
        seen = np.zeros((h, w), dtype=bool)
        for r in range(h):
            for cc in range(w):
                if mask[r, cc] and not seen[r, cc]:
                    q = deque([(r, cc)])
                    seen[r, cc] = True
                    cells = []
                    while q:
                        y, x = q.popleft()
                        cells.append((y, x))
                        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < h and 0 <= nx < w and mask[ny, nx] and not seen[ny, nx]:
                                seen[ny, nx] = True
                                q.append((ny, nx))
                    comps.append({
                        "color": c,
                        "cells": cells,
                        "size": len(cells),
                        "min_r": min(y for y, _ in cells),
                        "max_r": max(y for y, _ in cells),
                        "min_c": min(x for _, x in cells),
                        "max_c": max(x for _, x in cells),
                    })

    if not comps:
        return out.tolist()

    # Remove all marker cells.
    for comp in comps:
        for y, x in comp["cells"]:
            out[y, x] = 0

    # The repeating pattern is the sequence of marker colors in the top-left cluster,
    # read left-to-right.  The terminal color is the marker component closest to
    # the bottom-right corner.
    top_cluster = [c for c in comps if c["min_r"] <= 2 and c["min_c"] <= 8]
    if top_cluster:
        top_cluster.sort(key=lambda c: (c["min_r"], c["min_c"]))
        pattern = [c["color"] for c in top_cluster]
    else:
        pattern = [c["color"] for c in comps]

    terminal = max(comps, key=lambda c: (c["max_r"] + c["max_c"]))
    terminal_color = terminal["color"]

    # The path is the centerline of the less frequent background color.
    # In all examples this is the diagonal corridor from the left/bottom side
    # to the top/right side.
    if counts[order[0]] >= counts[order[1]]:
        corridor_color = bg2
    else:
        corridor_color = bg1

    corridor = (g == corridor_color)

    # Find the corridor component that touches the left or bottom boundary and
    # also touches the top or right boundary.  If none, use the largest component.
    def comp_id_for(mask):
        cid = -np.ones((h, w), dtype=int)
        comps_list = []
        for r in range(h):
            for cc in range(w):
                if mask[r, cc] and cid[r, cc] == -1:
                    q = deque([(r, cc)])
                    cid[r, cc] = len(comps_list)
                    cells = []
                    while q:
                        y, x = q.popleft()
                        cells.append((y, x))
                        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < h and 0 <= nx < w and mask[ny, nx] and cid[ny, nx] == -1:
                                cid[ny, nx] = len(comps_list)
                                q.append((ny, nx))
                    comps_list.append(cells)
        return cid, comps_list

    cid, corridor_comps = comp_id_for(corridor)
    if corridor_comps:
        def touches(cell_list, side):
            if side == "left":
                return any(x == 0 for _, x in cell_list)
            if side == "right":
                return any(x == w - 1 for _, x in cell_list)
            if side == "top":
                return any(y == 0 for y, _ in cell_list)
            if side == "bottom":
                return any(y == h - 1 for y, _ in cell_list)

        chosen = None
        for i, cells in enumerate(corridor_comps):
            if (touches(cells, "left") or touches(cells, "bottom")) and (
                touches(cells, "top") or touches(cells, "right")
            ):
                if chosen is None or len(cells) > len(corridor_comps[chosen]):
                    chosen = i
        if chosen is None:
            chosen = max(range(len(corridor_comps)), key=lambda i: len(corridor_comps[i]))
        path_mask = (cid == chosen)
    else:
        path_mask = np.zeros((h, w), dtype=bool)

    # Build an ordered path through the corridor component.
    # Use a simple skeleton: repeatedly take the boundary cell farthest from the
    # start, then follow a shortest path to the farthest remaining cell.
    # For these puzzles the corridor is a simple diagonal band, so this yields
    # the intended one-cell path.
    if path_mask.any():
        ys, xs = np.nonzero(path_mask)
        cells = set(zip(ys.tolist(), xs.tolist()))

        # Start at the cell closest to the left/bottom side.
        start = min(cells, key=lambda p: (p[1], -p[0]))
        # End at the cell farthest from start in Manhattan distance.
        end = max(cells, key=lambda p: abs(p[0] - start[0]) + abs(p[1] - start[1]))

        # Shortest path in the corridor from start to end.
        parent = {start: None}
        q = deque([start])
        while q:
            cur = q.popleft()
            if cur == end:
                break
            y, x = cur
            for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                ny, nx = y + dy, x + dx
                if (ny, nx) in cells and (ny, nx) not in parent:
                    parent[(ny, nx)] = cur
                    q.append((ny, nx))

        path = []
        cur = end
        while cur is not None:
            path.append(cur)
            cur = parent.get(cur)
        path.reverse()
    else:
        path = []

    # Write the repeating pattern along the path.  The last cell gets the
    # terminal marker color.
    if path:
        for i, (r, c) in enumerate(path):
            if i == len(path) - 1:
                out[r, c] = terminal_color
            else:
                out[r, c] = pattern[i % len(pattern)]

    return out.tolist()

import numpy as np
from collections import defaultdict, deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    a = np.array(grid, dtype=int)
    H, W = a.shape

    # Most common colour is treated as background.
    vals, counts = np.unique(a, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # Find all non-background connected components (4-connected).
    seen = np.zeros((H, W), dtype=bool)
    comps = []
    for r in range(H):
        for c in range(W):
            if seen[r, c] or a[r, c] == bg:
                continue
            q = deque([(r, c)])
            seen[r, c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < H and 0 <= nx < W and not seen[ny, nx] and a[ny, nx] != bg:
                        seen[ny, nx] = True
                        q.append((ny, nx))
            comps.append(cells)

    boxes = []
    key_cells = []

    for cells in comps:
        ys = [p[0] for p in cells]
        xs = [p[1] for p in cells]
        y0, y1 = min(ys), max(ys)
        x0, x1 = min(xs), max(xs)
        h = y1 - y0 + 1
        w = x1 - x0 + 1
        area = len(cells)

        # A box is a solid rectangular frame component.
        if area == h * w and h >= 3 and w >= 3:
            # Find the central payload colour(s) inside the frame.
            inner = a[y0 + 1:y1, x0 + 1:x1]
            inner_vals, inner_counts = np.unique(inner, return_counts=True)
            # Payload is the most common non-frame colour inside.
            frame_col = a[y0, x0]
            payload = None
            best = -1
            for v, cnt in zip(inner_vals, inner_counts):
                if v != frame_col and cnt > best:
                    best = cnt
                    payload = int(v)
            if payload is not None:
                boxes.append({
                    "y0": y0, "y1": y1, "x0": x0, "x1": x1,
                    "cy0": y0 + 1, "cy1": y1 - 1,
                    "cx0": x0 + 1, "cx1": x1 - 1,
                    "val": payload,
                    "top": y0,
                    "left": x0,
                })
        else:
            # Key entries are isolated single cells.
            if area == 1:
                y, x = cells[0]
                key_cells.append((y, x, int(a[y, x])))

    # If no boxes were found, return unchanged.
    if not boxes:
        return [[int(v) for v in row] for row in a]

    # Identify the key row: the row containing the most isolated key cells.
    key_row = max(set(y for y, _, _ in key_cells), key=lambda y: sum(1 for yy, _, _ in key_cells if yy == y))
    key_seq = [v for y, x, v in sorted(key_cells, key=lambda p: p[1]) if y == key_row]

    # Assign each key occurrence to the next unused box of that value in reading order.
    boxes_by_val = defaultdict(list)
    for b in boxes:
        boxes_by_val[b["val"]].append(b)
    for lst in boxes_by_val.values():
        lst.sort(key=lambda b: (b["top"], b["left"]))

    used = [False] * len(boxes)
    idx_by_val = defaultdict(int)
    seq_boxes = []
    for v in key_seq:
        lst = boxes_by_val.get(v, [])
        i = idx_by_val[v]
        while i < len(lst) and used[boxes.index(lst[i])]:
            i += 1
        if i < len(lst):
            b = lst[i]
            used[boxes.index(b)] = True
            idx_by_val[v] = i + 1
            seq_boxes.append(b)

    out = a.copy()

    def fill_rect(y0, y1, x0, x1, color):
        for y in range(y0, y1 + 1):
            for x in range(x0, x1 + 1):
                if 0 <= y < H and 0 <= x < W and out[y, x] == bg:
                    out[y, x] = color

    # Connect consecutive boxes in the key sequence.
    for b1, b2 in zip(seq_boxes, seq_boxes[1:]):
        # Horizontal connection: overlapping vertical centre bands.
        if max(b1["cy0"], b2["cy0"]) <= min(b1["cy1"], b2["cy1"]):
            y0 = max(b1["cy0"], b2["cy0"])
            y1 = min(b1["cy1"], b2["cy1"])
            if b1["x1"] < b2["x0"]:
                x0, x1 = b1["x1"] + 1, b2["x0"] - 1
            elif b2["x1"] < b1["x0"]:
                x0, x1 = b2["x1"] + 1, b1["x0"] - 1
            else:
                continue
            if x0 <= x1:
                fill_rect(y0, y1, x0, x1, b1["val"])
        # Vertical connection: overlapping horizontal centre bands.
        elif max(b1["cx0"], b2["cx0"]) <= min(b1["cx1"], b2["cx1"]):
            x0 = max(b1["cx0"], b2["cx0"])
            x1 = min(b1["cx1"], b2["cx1"])
            if b1["y1"] < b2["y0"]:
                y0, y1 = b1["y1"] + 1, b2["y0"] - 1
            elif b2["y1"] < b1["y0"]:
                y0, y1 = b2["y1"] + 1, b1["y0"] - 1
            else:
                continue
            if y0 <= y1:
                fill_rect(y0, y1, x0, x1, b1["val"])

    return [[int(v) for v in row] for row in out]

