        ys = [p[0] for p in cells]
        xs = [p[1] for p in cells]
        y0, y1 = min(ys), max(ys)
        x0, x1 = min(xs), max(xs)
        h = y1 - y0 + 1
        w = x1 - x0 + 1
        area = len(cells)

        # A box frame is exactly the border of its bounding box.
        if h >= 3 and w >= 3 and area == 2 * h + 2 * w - 4:
            frame_color = a[y0, x0]
            # Verify all border cells are the frame color.
            ok = True
            for x in range(x0, x1 + 1):
                if a[y0, x] != frame_color or a[y1, x] != frame_color:
                    ok = False
                    break
            if ok:
                for y in range(y0, y1 + 1):
                    if a[y, x0] != frame_color or a[y, x1] != frame_color:
                        ok = False
                        break

            if ok:
                # Payload is the dominant non-background, non-frame color inside.
                inner = a[y0 + 1:y1, x0 + 1:x1]
                inner_vals, inner_counts = np.unique(inner, return_counts=True)
                payload = None
                best = -1
                for v, cnt in zip(inner_vals, inner_counts):
                    if v != bg and v != frame_color and cnt > best:
                        best = cnt
                        payload = int(v)

                if payload is not None:
                    # Payload rectangle: the maximal solid payload region inside.
                    # In all cases it is the full interior, but compute it safely.
                    py0, py1 = y0 + 1, y1 - 1
                    px0, px1 = x0 + 1, x1 - 1

                    # Shrink to the largest rectangle of payload color if needed.
                    # This is conservative and works for solid interiors.
                    while py0 <= py1 and px0 <= px1 and not np.all(a[py0:py1 + 1, px0:px1 + 1] == payload):
                        # Try shrinking from the side with least payload coverage.
                        top = np.sum(a[py0, px0:px1 + 1] == payload)
                        bottom = np.sum(a[py1, px0:px1 + 1] == payload)
                        left = np.sum(a[py0:py1 + 1, px0] == payload)
                        right = np.sum(a[py0:py1 + 1, px1] == payload)
                        m = min(top, bottom, left, right)
                        if m == top:
                            py0 += 1
                        elif m == bottom:
                            py1 -= 1
                        elif m == left:
                            px0 += 1
                        else:
                            px1 -= 1

                    boxes.append({
                        "y0": y0, "y1": y1, "x0": x0, "x1": x1,
                        "py0": py0, "py1": py1, "px0": px0, "px1": px1,
                        "val": payload,
                    })
        else:
            # Isolated non-background cells are key candidates if outside boxes.
            if area == 1:
                y, x = cells[0]
                isolated.append((y, x, int(a[y, x])))

    if not boxes:
        return [[int(v) for v in row] for row in a]

    # Keep only isolated cells not inside any box bounding box.
    key_candidates = []
    for y, x, v in isolated:
        inside = False
        for b in boxes:
            if b["y0"] <= y <= b["y1"] and b["x0"] <= x <= b["x1"]:
                inside = True
                break
        if not inside:
            key_candidates.append((y, x, v))

    if not key_candidates:
        return [[int(v) for v in row] for row in a]

    # Key row: row with the most key candidates.
    row_counts = defaultdict(int)
    for y, _, _ in key_candidates:
        row_counts[y] += 1
    key_row = max(row_counts, key=lambda r: (row_counts[r], r))
    key_seq = [v for y, x, v in sorted(key_candidates, key=lambda p: p[1]) if y == key_row]

    # Assign key sequence to boxes of the same payload value in reading order.
    boxes_by_val = defaultdict(list)
    for b in boxes:
        boxes_by_val[b["val"]].append(b)
    for lst in boxes_by_val.values():
        lst.sort(key=lambda b: (b["y0"], b["x0"]))

    ptr = defaultdict(int)
    seq_boxes = []
    for v in key_seq:
        lst = boxes_by_val.get(v, [])
        i = ptr[v]
        if i < len(lst):
            seq_boxes.append(lst[i])
            ptr[v] = i + 1

    out = a.copy()

    def fill_rect(y0, y1, x0, x1, color):
        if y0 > y1 or x0 > x1:
            return
        for y in range(y0, y1 + 1):
            for x in range(x0, x1 + 1):
                if 0 <= y < H and 0 <= x < W and out[y, x] == bg:
                    out[y, x] = color

    # Connect consecutive boxes in the assigned key sequence.
    for b1, b2 in zip(seq_boxes, seq_boxes[1:]):
        # Horizontal connection: overlapping payload row intervals.
        if max(b1["py0"], b2["py0"]) <= min(b1["py1"], b2["py1"]):
            y0 = max(b1["py0"], b2["py0"])
            y1 = min(b1["py1"], b2["py1"])
            if b1["x1"] < b2["x0"]:
                x0, x1 = b1["x1"] + 1, b2["x0"] - 1
            elif b2["x1"] < b1["x0"]:
                x0, x1 = b2["x1"] + 1, b1["x0"] - 1
            else:
                continue
            fill_rect(y0, y1, x0, x1, b1["val"])

        # Vertical connection: overlapping payload column intervals.
        elif max(b1["px0"], b2["px0"]) <= min(b1["px1"], b2["px1"]):
            x0 = max(b1["px0"], b2["px0"])
            x1 = min(b1["px1"], b2["px1"])
            if b1["y1"] < b2["y0"]:
                y0, y1 = b1["y1"] + 1, b2["y0"] - 1
            elif b2["y1"] < b1["y0"]:
                y0, y1 = b2["y1"] + 1, b1["y0"] - 1
            else:
                continue
            fill_rect(y0, y1, x0, x1, b1["val"])

    return [[int(v) for v in row] for row in out]

import numpy as np
from collections import Counter

def _as_list(g):
    return [list(map(int, row)) for row in g]

def _find_regions(grid):
    h = len(grid)
    w = len(grid[0]) if h else 0
    used = [[False] * w for _ in range(h)]
    regions = []

    for r in range(h):
        for c in range(w):
            if used[r][c]:
                continue
            color = grid[r][c]
            if color == 0:
                used[r][c] = True
                continue

            stack = [(r, c)]
            cells = []
            used[r][c] = True
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not used[ny][nx] and grid[ny][nx] == color:
                        used[ny][nx] = True
                        stack.append((ny, nx))

            ys = [y for y, _ in cells]
            xs = [x for _, x in cells]
            y0, y1 = min(ys), max(ys)
            x0, x1 = min(xs), max(xs)
            if (y1 - y0 + 1) * (x1 - x0 + 1) == len(cells):
                regions.append((y0, x0, y1, x1, color))

    return regions

def _infer_pattern(sub):
    h = len(sub)
    w = len(sub[0]) if h else 0
    if h == 0 or w == 0:
        return sub

    best = None
    best_score = -1

    for ph in range(1, h + 1):
        for pw in range(1, w + 1):
            tile = [row[:pw] for row in sub[:ph]]
            score = 0
            for y in range(h):
                for x in range(w):
                    if sub[y][x] == tile[y % ph][x % pw]:
                        score += 1
            if score > best_score:
                best_score = score
                best = tile

    out = [[best[y % len(best)][x % len(best[0])]] for y in range(h) for x in range(w)]
    return [out[y * w:(y + 1) * w] for y in range(h)]

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = _as_list(grid)
    h = len(g)
    w = len(g[0]) if h else 0
    out = [row[:] for row in g]

    for y0, x0, y1, x1, color in _find_regions(g):
        sub = [g[y][x0:x1 + 1] for y in range(y0, y1 + 1)]
        pat = _infer_pattern(sub)
        for i, row in enumerate(pat):
            for j, val in enumerate(row):
                out[y0 + i][x0 + j] = int(val)

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    # The input is a 30x30 grid with a rectangular block of 8s.
    # The output is the corresponding block from the vertically mirrored
    # part of the grid (the part that is not overwritten by the 8s).
    h = len(grid)
    w = len(grid[0])

    # Find the bounding box of the 8s.
    min_r, max_r = h, -1
    min_c, max_c = w, -1
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 8:
                if r < min_r:
                    min_r = r
                if r > max_r:
                    max_r = r
                if c < min_c:
                    min_c = c
                if c > max_c:
                    max_c = c

    # Mirror rows vertically: row r corresponds to row h - 1 - r.
    out = []
    for r in range(min_r, max_r + 1):
        mr = h - 1 - r
        out.append([grid[mr][c] for c in range(min_c, max_c + 1)])

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    out = [row[:] for row in grid]
    h = len(out)
    w = len(out[0])

    # The left pattern is always in columns 1..7.
    # Move it to columns 11..17, keeping its rows unchanged.
    for r in range(h):
        for c in range(1, 8):
            if out[r][c] == 5:
                out[r][c + 10] = 5
            out[r][c] = 0

    # In the right chamber, non-5, non-zero pixels move up by one row
    # if the destination is inside the chamber and is not a 5.
    for r in range(1, 7):
        for c in range(10, 19):
            v = out[r][c]
            if v != 0 and v != 5:
                if r > 1 and out[r - 1][c] != 5:
                    out[r - 1][c] = v
                    out[r][c] = 0

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    out = [row[:] for row in grid]
    h = len(out)
    w = len(out[0])

    # 1) Move colored pixels (not 0 and not 5) in the right chamber up by one row.
    #    They may overwrite 5s, but only inside the chamber.
    for r in range(1, h - 1):
        for c in range(9, w - 1):
            v = out[r][c]
            if v != 0 and v != 5:
                out[r - 1][c] = v
                out[r][c] = 0

    # 2) Move the left 5-pattern right by 10 columns into the chamber.
    #    It overwrites whatever is in the destination cells.
    for r in range(h):
        for c in range(1, 8):
            if out[r][c] == 5:
                out[r][c + 10] = 5
            out[r][c] = 0

    return out

