    order = np.argsort(-counts)
    bg1, bg2 = int(vals[order[0]]), int(vals[order[1]])
    bg = {bg1, bg2}

    # Collect all non-background cells.
    nonbg = [(r, c, int(g[r, c])) for r in range(H) for c in range(W) if g[r, c] not in bg]

    # Identify 2x2 blocks of a single non-background colour.
    blocks = []
    for r in range(H - 1):
        for c in range(W - 1):
            v = int(g[r, c])
            if v in bg:
                continue
            if g[r, c] == g[r, c + 1] == g[r + 1, c] == g[r + 1, c + 1] == v:
                blocks.append((r, c, v))

    # The palette is the sequence of 2x2 blocks in the topmost row of blocks,
    # sorted left to right.
    if blocks:
        top_r = min(b[0] for b in blocks)
        top_blocks = sorted([b for b in blocks if b[0] == top_r], key=lambda x: x[1])
        palette = [b[2] for b in top_blocks]
    else:
        palette = []

    # The target colour is the colour of the lowest 2x2 block (if any).
    target = None
    if blocks:
        target = max(blocks, key=lambda b: (b[0], b[1]))[2]

    # Remove all non-background cells.
    out = np.array(grid, dtype=int)
    for r, c, _ in nonbg:
        out[r, c] = 0

    if not palette:
        return out.tolist()

    # Draw the repeating palette along the main diagonal.
    # The diagonal starts at the top-left and ends at the bottom-right.
