        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                j = pos_to_idx.get((r + dr, c + dc))
                if j is not None:
                    union(i, j)

    comps = {}
    for i, (r, c, col) in enumerate(cells):
        comps.setdefault(find(i), []).append((r, c, col))

