    box_c1 = w - 1

    out = g.copy()

    # 1) Erase the left-side 5 pattern (columns before the box).
    for r in range(h):
        for c in range(box_c0):
            if out[r, c] == 5:
                out[r, c] = 0

    # 2) Erase all non-border 5s inside the right box.
