        for c in range(box_c0 + 1, box_c1):
            if out[r, c] == 5:
                out[r, c] = 0

    # 3) Move the left 5 pattern into the right box by translating +10 columns.
    for r in range(h):
        for c in range(box_c0):
            if g[r, c] == 5:
                nc = c + 10
                if 0 <= nc < w:
                    out[r, nc] = 5

    # 4) For each column inside the box, keep only the topmost non-5 digit
    #    that is not blocked by the moved 5 pattern.
    for c in range(box_c0 + 1, box_c1):
        kept = False
        for r in range(1, h - 1):
            if out[r, c] == 5:
                # Once the moved pattern blocks this column, no lower digit survives.
                break
            if out[r, c] != 0:
                if not kept:
                    kept = True
                else:
