def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # The right-hand box always starts at column 9 in these puzzles.
    box_c0 = 9
    box_c1 = w - 1

    # 1) Extract the left-side 5 pattern (everything left of the box).
    left_pattern = []
    for r in range(h):
        row = []
        for c in range(box_c0):
            row.append(1 if g[r, c] == 5 else 0)
        left_pattern.append(row)

    # 2) Start from the input, but clear the left pattern and all non-border
    #    5s inside the right box.
    out = g.copy()
    for r in range(h):
        for c in range(box_c0):
            if out[r, c] == 5:
                out[r, c] = 0

    for r in range(1, h - 1):
        for c in range(box_c0 + 1, box_c1):
            if out[r, c] == 5:
                out[r, c] = 0

    # 3) Move the left 5 pattern into the right box by translating +10 columns.
    moved_mask = np.zeros((h, w), dtype=int)
    for r in range(h):
        for c in range(box_c0):
            if left_pattern[r][c]:
                nc = c + 10
                if 0 <= nc < w:
                    out[r, nc] = 5
                    moved_mask[r, nc] = 1

    # 4) For each column of the box, keep only the topmost visible digit
    #    that is not blocked by the moved 5 pattern.
    for c in range(box_c0 + 1, box_c1):
        kept = False
        for r in range(1, h - 1):
            if moved_mask[r, c]:
                # Once the moved pattern blocks this column, lower digits are hidden.
                break
            if out[r, c] != 0:
                if not kept:
                    kept = True
                else:
                    out[r, c] = 0

    return out.tolist()

import numpy as np

def _fill_line(line, out_line, n):
    """
    Apply the 1D rule to one row/column.

    A "pattern" is a color that appears at least twice in the line and whose
    positions form an arithmetic progression.  If another color lies on that
    progression, the segment of the progression between the pattern cells and
    that other color is painted with the other color.  If no such other color
    exists, the whole progression is extended to the line boundaries and
    painted with the pattern color.
    """
    positions = {}
    for i, v in enumerate(line):
        if v != 0:
            positions.setdefault(v, []).append(i)

    # Candidate patterns: colors with >=2 positions in arithmetic progression.
    patterns = []
    for c, ps in positions.items():
        if len(ps) < 2:
            continue
        diffs = [ps[i + 1] - ps[i] for i in range(len(ps) - 1)]
        d = diffs[0]
        if d <= 0 or any(x != d for x in diffs):
            continue
        patterns.append((c, ps, d))

    # Prefer the pattern with the largest step; ties by smaller color.
    if not patterns:
        return

    patterns.sort(key=lambda x: (-x[2], x[0]))
    c, ps, d = patterns[0]

    # Find a different color on this progression.
    target = None
    target_pos = None
    for i in range(n):
        if line[i] != 0 and line[i] != c:
            if (i - ps[0]) % d == 0:
                target = line[i]
                target_pos = i
                break

    if target is not None:
        lo = min(min(ps), target_pos)
        hi = max(max(ps), target_pos)
        i = lo
        while i <= hi:
            if (i - ps[0]) % d == 0:
                out_line[i] = target
            i += 1
    else:
        i = ps[0]
        while i >= 0:
            if (i - ps[0]) % d == 0:
                out_line[i] = c
            i -= d
        i = ps[-1]
        while i < n:
            if (i - ps[0]) % d == 0:
                out_line[i] = c
            i += d


def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = np.zeros((h, w), dtype=int)

    # Choose the axis that contains fewer non-empty lines.
    nonempty_rows = sum(1 for r in range(h) if np.any(g[r] != 0))
    nonempty_cols = sum(1 for c in range(w) if np.any(g[:, c] != 0))

    if nonempty_rows <= nonempty_cols:
        for r in range(h):
            _fill_line(g[r].tolist(), out[r], w)
    else:
        for c in range(w):
            _fill_line(g[:, c].tolist(), out[:, c], h)

    return out.tolist()

import numpy as np

def _process_line(line: list[int], out_line: list[int]) -> None:
    n = len(line)

    # Find the color that appears exactly twice in this line.
    positions = {}
    for i, v in enumerate(line):
        if v != 0:
            positions.setdefault(v, []).append(i)

    base = None
    base_pos = None
    for c, ps in positions.items():
        if len(ps) == 2:
            base = c
            base_pos = ps
            break

    if base is None:
        return

    p1, p2 = base_pos
    d = abs(p2 - p1)
    if d == 0:
        return

    # Look for another non-zero color on the same arithmetic progression.
    target = None
    target_pos = None
    for i in range(n):
        v = line[i]
        if v != 0 and v != base and (i - p1) % d == 0:
            target = v
            target_pos = i
            break

    if target is not None:
        lo = min(p1, p2, target_pos)
        hi = max(p1, p2, target_pos)
        i = lo
        while i <= hi:
            if (i - p1) % d == 0:
                out_line[i] = target
            i += 1
    else:
        # Extend the progression to the line boundaries.
        i = p1
        while i >= 0:
            if (i - p1) % d == 0:
                out_line[i] = base
            i -= d
        i = p2
        while i < n:
            if (i - p1) % d == 0:
                out_line[i] = base
            i += d


def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Process rows for tall grids, columns for wide grids.
    if h >= w:
        for r in range(h):
            _process_line(g[r].tolist(), out[r].tolist())
    else:
        for c in range(w):
            _process_line(g[:, c].tolist(), out[:, c].tolist())

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])

    # Determine where the input is placed inside the 20x20 output.
    # From the examples:
    # - if a dimension is strictly less than 10, the input is anchored to the
    #   corresponding bottom/right edge;
    # - if a dimension is 10 or more, it is anchored to the top/left edge.
    r0 = 20 - h if h < 10 else 0
    c0 = 20 - w if w < 10 else 0

    # Use a sentinel for unknown cells.
    UNKNOWN = -1
    out = [[UNKNOWN] * 20 for _ in range(20)]

    # Place the input.
    for i in range(h):
        for j in range(w):
            out[r0 + i][c0 + j] = grid[i][j]

    # Fill unknown cells by diagonal propagation from the top-left.
    for i in range(20):
        for j in range(20):
            if out[i][j] == UNKNOWN:
                if i > 0 and j > 0 and out[i - 1][j - 1] != UNKNOWN:
                    out[i][j] = out[i - 1][j - 1]
                else:
                    # Fallback: should not be needed for valid inputs,
                    # but keep the grid fully filled.
                    out[i][j] = 0

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    # The 30x30 input contains a 4x4 arrangement of 6x6 bordered squares.
    # Each square has a 4x4 interior.  The output is the 4x4 interior of the
    # square whose border colour is the most frequent non-background colour
    # among all such square borders.
    n = len(grid)
    m = len(grid[0])

    # Candidate top-left positions for 6x6 squares.
    positions = []
    for r in range(n - 5):
        for c in range(m - 5):
            positions.append((r, c))

    def border_color(r, c):
        # Check whether the 6x6 block starting at (r,c) has a uniform border.
        border_vals = set()
        for i in range(6):
            border_vals.add(grid[r][c + i])
            border_vals.add(grid[r + 5][c + i])
            border_vals.add(grid[r + i][c])
            border_vals.add(grid[r + i][c + 5])
        if len(border_vals) == 1:
            return border_vals.pop()
        return None

    squares = []
    for r, c in positions:
        col = border_color(r, c)
        if col is not None:
            interior = [
                [grid[r + 1 + i][c + 1 + j] for j in range(4)]
                for i in range(4)
            ]
            squares.append((col, interior))

    if not squares:
        # Fallback: return a zero grid of the expected size.
        return [[0] * 4 for _ in range(4)]

    # Count border colours and choose the most frequent one.
    counts = {}
    for col, _ in squares:
        counts[col] = counts.get(col, 0) + 1

    best_col = max(counts, key=lambda x: (counts[x], -x))
    for col, interior in squares:
        if col == best_col:
            return [row[:] for row in interior]

    # Should not happen.
    return [[0] * 4 for _ in range(4)]

def transform(grid: list[list[int]]) -> list[list[int]]:
    n = len(grid)
    m = len(grid[0])

    # Find all 6x6 squares whose border is a single non-zero colour.
    # The desired square is the one whose border colour appears most often
    # among all such squares.  Return its 4x4 interior.
    best_color = None
    best_count = -1
    best_interior = [[0] * 4 for _ in range(4)]

    for r in range(n - 5):
        for c in range(m - 5):
            border = {
                grid[r][c + i] for i in range(6)
            } | {
                grid[r + 5][c + i] for i in range(6)
            } | {
                grid[r + i][c] for i in range(6)
            } | {
                grid[r + i][c + 5] for i in range(6)
            }

            if len(border) == 1:
                color = border.pop()
                if color == 0:
                    continue

                # Count how many 6x6 squares have this border colour.
                count = 0
                for rr in range(n - 5):
                    for cc in range(m - 5):
                        b = {
                            grid[rr][cc + i] for i in range(6)
                        } | {
                            grid[rr + 5][cc + i] for i in range(6)
                        } | {
                            grid[rr + i][cc] for i in range(6)
                        } | {
                            grid[rr + i][cc + 5] for i in range(6)
                        }
                        if len(b) == 1 and b.pop() == color:
                            count += 1

                if count > best_count:
                    best_count = count
                    best_color = color
                    best_interior = [
                        [grid[r + 1 + i][c + 1 + j] for j in range(4)]
                        for i in range(4)
                    ]

    return best_interior

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Find maximal rectangles whose border is a single non-zero colour.
    # The puzzle consists of such bordered regions; their interiors contain
    # a small periodic pattern with a few corrupted cells.
    for r0 in range(h):
        for c0 in range(w):
            border = g[r0, c0]
            if border == 0:
                continue

            # Expand to the maximal rectangle with this border colour.
            r1 = r0
            while r1 + 1 < h and all(g[r1 + 1, c:c + 1] == border for c in range(w)):
                r1 += 1
            c1 = c0
            while c1 + 1 < w and all(g[r:r + 1, c1 + 1] == border for r in range(h)):
                c1 += 1

            # Check that the whole rectangle border is exactly this colour.
            if not (
                np.all(g[r0, c0:c1 + 1] == border) and
                np.all(g[r1, c0:c1 + 1] == border) and
                np.all(g[r0:r1 + 1, c0] == border) and
                np.all(g[r0:r1 + 1, c1] == border)
            ):
                continue

            # Interior must be at least 1x1.
            if r1 <= r0 + 1 or c1 <= c0 + 1:
                continue

            # The interior should use only two colours: the border colour
            # and one other colour.
            interior = g[r0 + 1:r1, c0 + 1:c1]
            vals = np.unique(interior)
            if len(vals) != 2:
                continue
            if border not in vals:
                continue
            other = int(vals[0] if vals[1] == border else vals[1])

            ih, iw = interior.shape

            # Try to infer a small 2D period from the interior.
            best = None
            for ph in range(1, ih + 1):
                for pw in range(1, iw + 1):
                    # Period must be consistent with all cells that are not
                    # corrupted.  We allow a small number of mismatches.
                    mismatches = 0
                    for i in range(ih):
                        for j in range(iw):
                            if interior[i, j] != interior[i % ph, j % pw]:
                                mismatches += 1
                    # Accept if the pattern explains at least 90% of cells.
                    if mismatches <= max(1, (ih * iw) // 10):
                        score = (ph * pw, mismatches)
                        if best is None or score < best[0]:
                            best = (score, ph, pw)

            if best is None:
                continue

            _, ph, pw = best

            # Reconstruct the periodic interior.
            for i in range(ih):
                for j in range(iw):
                    out[r0 + 1 + i, c0 + 1 + j] = interior[i % ph, j % pw]

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return []

    h = len(grid)
    w = len(grid[0])

    # The background is the colour of the four corners.
    bg = grid[0][0]

    # The object colour is the most frequent non-background colour.
    counts = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v != bg:
                counts[v] = counts.get(v, 0) + 1
    if not counts:
        return [row[:] for row in grid]
    fg = max(counts, key=lambda x: counts[x])

    # Crop to the bounding box of the object.
    min_r = min_c = h
    max_r = max_c = -1
    for r in range(h):
        for c in range(w):
            if grid[r][c] == fg:
                if r < min_r:
                    min_r = r
                if r > max_r:
                    max_r = r
                if c < min_c:
                    min_c = c
                if c > max_c:
                    max_c = c

    H = max_r - min_r + 1
    W = max_c - min_c + 1

    # The input object is a 2x pixelated version of the answer, but the
    # 2x2 blocks overlap by one row/column: output size is (N + 1) // 2.
    out_h = (H + 1) // 2
    out_w = (W + 1) // 2

    out = [[bg] * out_w for _ in range(out_h)]

    for i in range(out_h):
        r0 = 2 * i
        r1 = min(r0 + 1, H - 1)
        for j in range(out_w):
            c0 = 2 * j
            c1 = min(c0 + 1, W - 1)

            # If any cell in the corresponding 2x2 (or edge 1x2/2x1/1x1)
            # block is the object colour, the output pixel is object colour.
            val = bg
            for r in range(r0, r1 + 1):
                for c in range(c0, c1 + 1):
                    if grid[min_r + r][min_c + c] == fg:
                        val = fg
                        break
                if val == fg:
                    break
            out[i][j] = val

    return out

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Collect all non-background cells.
    cells = [(r, c, int(g[r, c])) for r in range(h) for c in range(w) if g[r, c] != 0]
    if not cells:
        return out.tolist()

    # Group cells by color.
    by_color = {}
    for r, c, v in cells:
        by_color.setdefault(v, []).append((r, c))

    # Identify 3-cell L shapes (2x2 with one missing cell).
    l_shapes = {}
    for color, pts in by_color.items():
        if len(pts) != 3:
            continue
        rs = [r for r, _ in pts]
        cs = [c for _, c in pts]
        if max(rs) - min(rs) != 1 or max(cs) - min(cs) != 1:
            continue
        r0, c0 = min(rs), min(cs)
        full = {(r0, c0), (r0, c0 + 1), (r0 + 1, c0), (r0 + 1, c0 + 1)}
        if set(pts) <= full:
            missing = next(iter(full - set(pts)))
            l_shapes[color] = (r0, c0, missing)

    # For each L shape, find a same-color target cell that is down-right of the corner.
    targets = {}
    for color, (r0, c0, missing) in l_shapes.items():
        if missing == (r0, c0):
            corner = (r0 + 1, c0 + 1)
        elif missing == (r0, c0 + 1):
            corner = (r0 + 1, c0)
        elif missing == (r0 + 1, c0):
            corner = (r0, c0 + 1)
        else:
            corner = (r0, c0)

        cr, cc = corner
        best = None
        for r, c in by_color.get(color, []):
            if (r, c) in {(r0, c0), (r0, c0 + 1), (r0 + 1, c0), (r0 + 1, c0 + 1)}:
                continue
            if r > cr and c > cc:
                if best is None or (r - cr, c - cc) < best[0]:
                    best = ((r - cr, c - cc), (r, c))
        if best is not None:
            targets[color] = (corner, best[1])

    def put(r, c, v):
        if 0 <= r < h and 0 <= c < w:
            out[r, c] = v

    # Draw paths from L corners to their targets.
    for color, (corner, target) in targets.items():
        cr, cc = corner
        tr, tc = target
        r, c = cr, cc
        while r < tr and c < tc:
            r += 1
            c += 1
            put(r, c, color)
        while r < tr:
            r += 1
            put(r, c, color)
        while c < tc:
            c += 1
            put(r, c, color)

    # Draw the anti-diagonal boundary beam to each target.
    for color, (corner, target) in targets.items():
        tr, tc = target
        s = tr + tc - 1
        c = tc
        r = s - c
        while 0 <= r < h and 0 <= c < w:
            put(r, c, color)
            r -= 1
            c += 1

    return out.tolist()

