        if in_bounds(r, c):
            out[r, c] = v

    # For each color, find a 3-cell L shape and a separate single-cell target.
    # The L is a 2x2 block with exactly one missing cell.
    for color, pts in by_color.items():
        if len(pts) != 4:
            continue

        # Try to identify the L part: 3 of the 4 cells form a 2x2 L.
        l_cells = None
        target = None
        for i in range(4):
            candidate_target = pts[i]
            rest = [p for j, p in enumerate(pts) if j != i]
            rs = [r for r, _ in rest]
            cs = [c for _, c in rest]
            if max(rs) - min(rs) == 1 and max(cs) - min(cs) == 1:
                r0, c0 = min(rs), min(cs)
                full = {(r0, c0), (r0, c0 + 1), (r0 + 1, c0), (r0 + 1, c0 + 1)}
                if set(rest) <= full and len(set(rest)) == 3:
                    l_cells = rest
                    target = candidate_target
                    break

        if l_cells is None or target is None:
            continue

        tr, tc = target

        # The L emits from the cell diagonally opposite the missing cell.
        r0 = min(r for r, _ in l_cells)
        c0 = min(c for _, c in l_cells)
        full = {(r0, c0), (r0, c0 + 1), (r0 + 1, c0), (r0 + 1, c0 + 1)}
        missing = next(iter(full - set(l_cells)))

        if missing == (r0, c0):
            start = (r0 + 1, c0 + 1)
        elif missing == (r0, c0 + 1):
            start = (r0 + 1, c0)
        elif missing == (r0 + 1, c0):
            start = (r0, c0 + 1)
        else:
            start = (r0, c0)

        sr, sc = start

        # Draw the path from the L to the target:
        # diagonal down-right until the column matches the target, then straight down.
        r, c = sr, sc
        while r < tr and c < tc:
            r += 1
            c += 1
            put(r, c, color)
        while r < tr:
            r += 1
            put(r, c, color)

        # Draw the second beam from the top/right border to the same meeting point
        # just above the target.
        meet_r, meet_c = tr - 1, tc
        r, c = meet_r, meet_c
        while in_bounds(r, c):
            put(r, c, color)
            r -= 1
            c += 1

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Background is the most common colour.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    mask = g != bg
    if not mask.any():
        return [[int(x) for x in row] for row in g]

    # The puzzle uses one non-background colour.
    nonbg_vals, nonbg_counts = np.unique(g[mask], return_counts=True)
    src = int(nonbg_vals[np.argmax(nonbg_counts)])

    # Marker colour:
    # 0 -> 9, 9 -> 1, otherwise 10 - colour.
    if src == 0:
        marker = 9
    elif src == 9:
        marker = 1
    else:
        marker = (10 - src) % 10

    # Connected components of the source colour, 8-connected.
    comp = -np.ones((h, w), dtype=int)
    comps = []
    cid = 0
    for r in range(h):
        for c in range(w):
            if g[r, c] == src and comp[r, c] == -1:
                stack = [(r, c)]
                comp[r, c] = cid
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            if dy == 0 and dx == 0:
                                continue
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < h and 0 <= nx < w:
                                if g[ny, nx] == src and comp[ny, nx] == -1:
                                    comp[ny, nx] = cid
                                    stack.append((ny, nx))
                comps.append(cells)
                cid += 1

    # Keep only components that do not touch the top/bottom border.
    interior = [cells for cells in comps if all(0 < r < h - 1 for r, c in cells)]

    out = g.copy()

    if interior:
        # For each interior component, mark the cell 5 rows above its topmost cell.
        for cells in interior:
            top = min(cells, key=lambda p: (p[0], p[1]))
            r, c = top
            nr = r - 5
            if 0 <= nr < h:
                out[nr, c] = marker

        # Special case seen in the examples:
        # if three markers land on the same row, the middle one by column
        # is changed to the source colour.
        by_row = {}
        for cells in interior:
            top = min(cells, key=lambda p: (p[0], p[1]))
            r, c = top
            nr = r - 5
            if 0 <= nr < h:
                by_row.setdefault(nr, []).append(c)

        for r, cols in by_row.items():
            if len(cols) == 3:
                mid = sorted(cols)[1]
                out[r, mid] = src

    return [[int(x) for x in row] for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Find all 3x3 hollow squares:
    # c c c
    # c 0 c
    # c c c
    squares = []
    for r in range(H - 2):
        for c in range(W - 2):
            col = g[r, c]
            if col == 0:
                continue
            if (
                g[r, c] == col and g[r, c + 1] == col and g[r, c + 2] == col and
                g[r + 1, c] == col and g[r + 1, c + 1] == 0 and g[r + 1, c + 2] == col and
                g[r + 2, c] == col and g[r + 2, c + 1] == col and g[r + 2, c + 2] == col
            ):
                squares.append((r, c, col))

    if not squares:
        return []

    # The target colour is the one whose squares form the longest vertical chain
    # (same column, consecutive top rows separated by 2).
    best_col = None
    best_len = -1
    for col in sorted({s[2] for s in squares}):
        rows = sorted({r for (r, c, cc) in squares if cc == col and c == 0})  # placeholder
        # group by column
        by_c = {}
        for (r, c, cc) in squares:
            if cc == col:
                by_c.setdefault(c, []).append(r)
        for c, rs in by_c.items():
            rs = sorted(rs)
            cur = 1
            for i in range(1, len(rs)):
                if rs[i] == rs[i - 1] + 2:
                    cur += 1
                else:
                    cur = 1
                if cur > best_len:
                    best_len = cur
                    best_col = col

    if best_col is None:
        best_col = squares[0][2]

