    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Find all 3x3 hollow squares:
    # c c c
    # c 0 c
    # c c c
    squares = []
    for r in range(H - 2):
        for c in range(W - 2):
            col = g[r, c]
            if col == 0:
                continue
            if (
                g[r, c] == col and g[r, c + 1] == col and g[r, c + 2] == col and
                g[r + 1, c] == col and g[r + 1, c + 1] == 0 and g[r + 1, c + 2] == col and
                g[r + 2, c] == col and g[r + 2, c + 1] == col and g[r + 2, c + 2] == col
            ):
                squares.append((r, c, col))

    if not squares:
        return []

    # Group squares by color and orientation.
    # A vertical bar of n overlapping 3x3 squares has height 2*n + 1.
    # A horizontal bar of n overlapping 3x3 squares has width 2*n + 1.
    best = None  # (length, color, vertical)

    by_color = {}
    for r, c, col in squares:
        by_color.setdefault(col, []).append((r, c))

    for col, pos in by_color.items():
        # Vertical bars: same column, consecutive top rows.
        by_c = {}
        for r, c in pos:
            by_c.setdefault(c, []).append(r)

        for c, rows in by_c.items():
            rows = sorted(rows)
            cur = 1
            for i in range(1, len(rows)):
                if rows[i] == rows[i - 1] + 1:
                    cur += 1
                else:
                    cur = 1
                if best is None or cur > best[0]:
                    best = (cur, col, True)

        # Horizontal bars: same row, consecutive left columns.
        by_r = {}
        for r, c in pos:
            by_r.setdefault(r, []).append(c)

        for r, cols in by_r.items():
            cols = sorted(cols)
            cur = 1
            for i in range(1, len(cols)):
                if cols[i] == cols[i - 1] + 1:
                    cur += 1
                else:
                    cur = 1
                if best is None or cur > best[0]:
                    best = (cur, col, False)

    n, col, vertical = best

    if vertical:
        h = 2 * n + 1
        w = 3
        out = np.zeros((h, w), dtype=int)
        for i in range(n):
            r0 = 2 * i
            out[r0, :] = col
            out[r0 + 1, 0] = col
            out[r0 + 1, 2] = col
            out[r0 + 2, :] = col
    else:
        h = 3
        w = 2 * n + 1
        out = np.zeros((h, w), dtype=int)
        for i in range(n):
            c0 = 2 * i
            out[:, c0] = col
            out[0, c0 + 1] = col
            out[2, c0 + 1] = col
            out[:, c0 + 2] = col

    return out.tolist()

import numpy as np
from collections import deque, Counter

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Background is the most common colour; wall is the most common non-background colour.
    counts = Counter(g.ravel().tolist())
    bg = counts.most_common(1)[0][0]
    non_bg = {c: n for c, n in counts.items() if c != bg}
    wall = max(non_bg, key=lambda c: non_bg[c]) if non_bg else None

    out = g.copy()

    if wall is None:
        return out.tolist()

    # Components of non-wall cells.
    seen = np.zeros((h, w), dtype=bool)
    for r in range(h):
        for c in range(w):
            if seen[r, c] or g[r, c] == wall:
                continue

            # BFS over non-wall cells.
            q = deque([(r, c)])
            seen[r, c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny, nx] and g[ny, nx] != wall:
                        seen[ny, nx] = True
                        q.append((ny, nx))

            cell_set = set(cells)

            # Markers are non-background cells inside this component.
            markers = [(y, x, int(g[y, x])) for (y, x) in cells if g[y, x] != bg]

            if not markers:
                continue

            if len(markers) == 1:
                color = markers[0][2]
                for y, x in cells:
                    out[y, x] = color
                continue

            # Distance of each cell to the component boundary.
            # Boundary means a 4-neighbour outside the component (wall or grid edge).
            dist = {}
            dq = deque()
            for y, x in cells:
                d = 0
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if not (0 <= ny < h and 0 <= nx < w) or (ny, nx) not in cell_set:
                        d = 0
                        break
                dist[(y, x)] = d
                if d == 0:
                    dq.append((y, x))

            while dq:
                y, x = dq.popleft()
                nd = dist[(y, x)] + 1
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (ny, nx) in cell_set and dist[(ny, nx)] > nd:
                        dist[(ny, nx)] = nd
                        dq.append((ny, nx))

            # Marker colours define the colour for each distance level.
            # If several markers share a level, use the most frequent one.
            level_counts = {}
            for y, x, col in markers:
                level_counts.setdefault(dist[(y, x)], Counter())[col] += 1

            max_level = max(dist.values())
            level_color = {}
            for d in range(max_level + 1):
                if d in level_counts:
                    level_color[d] = level_counts[d].most_common(1)[0][0]
                else:
                    # Cycle through the available marker colours by distance.
                    available = sorted(level_counts.keys())
                    idx = available.index(min(available, key=lambda a: abs(a - d)))
                    level_color[d] = level_counts[available[idx]].most_common(1)[0][0]

            for y, x in cells:
                out[y, x] = level_color[dist[(y, x)]]

    return out.tolist()

