            for d in range(max_level + 1):
                if d in level_counts:
                    level_color[d] = level_counts[d].most_common(1)[0][0]
                else:
                    # Use the nearest marked level with the same parity if possible,
                    # otherwise the nearest marked level.
                    same = [m for m in level_counts if m % 2 == d % 2]
