def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    a = np.array(grid, dtype=int)
    h, w = a.shape

    # The 30x30 input is a 5x5 array of 6x6 cells.
    # Each 6x6 cell contains a 5x5 "window" (the first 5 rows/cols of the cell)
    # that may reveal part of the hidden 5x5 pattern.  Cells outside the
    # revealed pattern are filled with the surrounding 1-4 texture.
    #
    # Reconstruct the hidden 5x5 pattern by taking, for every 5x5 position,
    # the non-texture value that appears in any of the 5x5 windows.
    # Texture colours are the small digits 1, 2, 3, 4; pattern colours are
    # 0, 5, 6, 7, 8, 9 (and 2 when it is part of the pattern, which is
    # disambiguated by consistency across windows).
    out = np.zeros((5, 5), dtype=int)

    for br in range(5):
        for bc in range(5):
            # 5x5 window inside the 6x6 cell
            win = a[br * 6:(br * 6) + 5, bc * 6:(bc * 6) + 5]

            for i in range(5):
                for j in range(5):
                    v = int(win[i, j])
                    # Ignore obvious background texture.
                    if v in (1, 3, 4):
                        continue

                    # v is 0, 2, 5, 6, 7, 8 or 9.
                    # 0 is a valid pattern colour, but in the examples it is
                    # also the "empty" value.  We keep the first non-zero
                    # candidate and only allow 0 to fill a cell if no other
                    # window provides a non-zero value for that position.
                    if v != 0:
                        if out[i, j] == 0:
                            out[i, j] = v
                        # If another window gives a different non-zero value,
                        # keep the one that appears most often.
                        else:
                            # simple majority vote among non-zero candidates
                            pass

    # The simple first-candidate rule above can be made robust by counting
    # non-zero candidates for each output cell.
    counts = np.zeros((5, 5, 10), dtype=int)
    for br in range(5):
        for bc in range(5):
            win = a[br * 6:(br * 6) + 5, bc * 6:(bc * 6) + 5]
            for i in range(5):
                for j in range(5):
                    v = int(win[i, j])
                    if v in (1, 3, 4):
                        continue
                    counts[i, j, v] += 1

    final = np.zeros((5, 5), dtype=int)
    for i in range(5):
        for j in range(5):
            # Prefer non-zero colours; if none, leave 0.
            best = 0
            best_count = 0
            for c in range(1, 10):
                if counts[i, j, c] > best_count:
                    best_count = counts[i, j, c]
                    best = c
            final[i, j] = best

    return final.tolist()

