def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import Counter

    g = np.array(grid, dtype=int)
    H, W = g.shape

    def score_rows(bounds):
        total = 0
        for r0, r1 in zip(bounds[:-1], bounds[1:]):
            for c0, c1 in zip(v_bounds[:-1], v_bounds[1:]):
                sub = g[r0:r1, c0:c1]
                total += Counter(sub.ravel()).most_common(1)[0][1]
        return total

    def score_cols(bounds):
        total = 0
        for r0, r1 in zip(h_bounds[:-1], h_bounds[1:]):
            for c0, c1 in zip(bounds[:-1], bounds[1:]):
                sub = g[r0:r1, c0:c1]
                total += Counter(sub.ravel()).most_common(1)[0][1]
        return total

    # Initial boundaries: full-change boundaries are strong hints.
    h_bounds = [0]
    for r in range(1, H):
        if np.all(g[r] != g[r - 1]):
            h_bounds.append(r)
    h_bounds.append(H)

    v_bounds = [0]
    for c in range(1, W):
        if np.all(g[:, c] != g[:, c - 1]):
            v_bounds.append(c)
    v_bounds.append(W)

    # Refine row boundaries using current column boundaries.
    for _ in range(3):
        best = h_bounds
        best_score = score_rows(h_bounds)
