            r0, r1 = h_bounds[i], h_bounds[i + 1]
            if r1 - r0 < 2:
                continue
            for r in range(r0 + 1, r1):
                cand = h_bounds[:i + 1] + [r] + h_bounds[i + 1:]
                s = score_rows(cand)
                if s > best_score:
                    best_score = s
                    best = cand
        h_bounds = best

