            if c1 - c0 < 2:
                continue
            for c in range(c0 + 1, c1):
                cand = v_bounds[:i + 1] + [c] + v_bounds[i + 1:]
                s = score_cols(cand)
                if s > best_score:
                    best_score = s
                    best = cand
        v_bounds = best

    # Dominant color of each macro-block.
    blocks = []
    for r0, r1 in zip(h_bounds[:-1], h_bounds[1:]):
        row_blocks = []
        for c0, c1 in zip(v_bounds[:-1], v_bounds[1:]):
            sub = g[r0:r1, c0:c1]
            row_blocks.append(Counter(sub.ravel()).most_common(1)[0][0])
        blocks.append(row_blocks)

    R = len(blocks)
    C = len(blocks[0])

    # Transpose the block matrix.
    out_blocks = [[blocks[i][j] for i in range(R)] for j in range(C)]

    # Output block sizes are transposed input block sizes.
    out_h = [v_bounds[j + 1] - v_bounds[j] for j in range(C)]
    out_w = [h_bounds[i + 1] - h_bounds[i] for i in range(R)]

    out = np.zeros((sum(out_h), sum(out_w)), dtype=int)
    r = 0
    for i, h in enumerate(out_h):
        c = 0
        for j, w in enumerate(out_w):
            out[r:r + h, c:c + w] = out_blocks[i][j]
            c += w
        r += h

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    a = np.asarray(grid, dtype=int)
    h, w = a.shape
    N = 20

    # The input is a contiguous crop of the final 20x20 grid.
    # The final grid is uniquely determined by the rule that every 2x2
    # block has an even number of cells equal to the first colour of the
    # input (the "minority"/background colour in the examples).
    #
    # Equivalently, if we encode the first colour as 0 and the other as 1,
    # the 20x20 grid satisfies:
    #     b[i][j] = b[i-1][j] XOR b[i][j-1] XOR b[i-1][j-1]
    # for all i > 0, j > 0.
    #
    # We try every possible crop position.  For each position, propagate the
    # 2x2 parity rule in all four directions.  The valid position is the one
    # that produces a complete 20x20 grid consistent with the given crop.

    first = a[0][0]
    other = 1 - first if first in (0, 1) else (8 if first == 7 else 7)

    # Binary encoding: first colour -> 0, other colour -> 1.
    b = (a != first).astype(int)

    def try_place(r0, c0):
        # Unknown cells are -1.
        g = np.full((N, N), -1, dtype=int)
        g[r0:r0 + h, c0:c0 + w] = b

        changed = True
        while changed:
            changed = False
            for i in range(N):
                for j in range(N):
                    # If any three cells of a 2x2 block are known, infer the fourth.
                    if i > 0 and j > 0:
                        vals = [g[i][j], g[i - 1][j], g[i][j - 1], g[i - 1][j - 1]]
                        if vals.count(-1) == 1:
                            known = [v for v in vals if v != -1]
                            # even parity: xor of all four must be 0
                            missing = vals.index(-1)
                            inferred = known[0] ^ known[1] ^ known[2]
                            if g[i][j] == -1:
                                g[i][j] = inferred
                                changed = True
                            elif g[i][j] != inferred:
                                return None
                    if i < N - 1 and j < N - 1:
                        vals = [g[i][j], g[i + 1][j], g[i][j + 1], g[i + 1][j + 1]]
                        if vals.count(-1) == 1:
                            known = [v for v in vals if v != -1]
                            inferred = known[0] ^ known[1] ^ known[2]
                            idx = vals.index(-1)
                            if g[idx // 4][idx % 4] == -1:
                                g[idx // 4][idx % 4] = inferred
                                changed = True
                            elif g[idx // 4][idx % 4] != inferred:
                                return None

        if -1 in g:
            return None
        return g

    for r0 in range(N - h + 1):
        for c0 in range(N - w + 1):
            g = try_place(r0, c0)
            if g is not None:
                # Convert back to original colours.
                out = np.where(g == 0, first, other).astype(int)
                return out.tolist()

    # Fallback (should not be needed for valid ARC inputs):
    # place the input in the top-left and fill by the same parity rule.
    g = np.full((N, N), -1, dtype=int)
    g[:h, :w] = b
    changed = True
    while changed:
        changed = False
        for i in range(N):
            for j in range(N):
                if i > 0 and j > 0:
                    vals = [g[i][j], g[i - 1][j], g[i][j - 1], g[i - 1][j - 1]]
                    if vals.count(-1) == 1:
                        known = [v for v in vals if v != -1]
                        inferred = known[0] ^ known[1] ^ known[2]
                        if g[i][j] == -1:
                            g[i][j] = inferred
                            changed = True
        # If still unknown, fill remaining cells using the recurrence from top-left.
        if -1 in g:
            for i in range(N):
                for j in range(N):
                    if g[i][j] == -1:
                        if i == 0:
                            g[i][j] = g[i][j - 1]
                        elif j == 0:
                            g[i][j] = g[i - 1][j]
                        else:
                            g[i][j] = g[i - 1][j] ^ g[i][j - 1] ^ g[i - 1][j - 1]
            break

    out = np.where(g == 0, first, other).astype(int)
    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Find the rectangular block of 0s.
    zero_cells = np.argwhere(g == 0)
    if len(zero_cells) == 0:
        return g.tolist()

    zr0, zc0 = zero_cells.min(axis=0)
    zr1, zc1 = zero_cells.max(axis=0)
    zr1 += 1
    zc1 += 1
    zh = zr1 - zr0
    zw = zc1 - zc0

    # Find the rectangular block of 2s.
    two_cells = np.argwhere(g == 2)
    if len(two_cells) == 0:
        return g.tolist()

    tr0, tc0 = two_cells.min(axis=0)
    tr1, tc1 = two_cells.max(axis=0)
    tr1 += 1
    tc1 += 1
    th = tr1 - tr0
    tw = tc1 - tc0

    # Candidate destination rectangles of the same size as the 0-block.
    # They must be filled entirely with 1s or 2s.
    candidates = []
    for r in range(h - zh + 1):
        for c in range(w - zw + 1):
            block = g[r:r + zh, c:c + zw]
            if np.all((block == 1) | (block == 2)):
                candidates.append((r, c))

    if not candidates:
        return g.tolist()

    # Score candidates by how well their surrounding border matches the
    # surrounding border of the 2-block.  The best match is the destination.
    def border_score(r, c):
        score = 0
        for dr in range(-1, zh + 1):
            for dc in range(-1, zw + 1):
                if 0 <= dr < zh and 0 <= dc < zw:
                    continue
                nr = r + dr
                nc = c + dc
                if 0 <= nr < h and 0 <= nc < w:
                    score += int(g[nr, nc] == 1)
        return score

    def two_border_score(r, c):
        score = 0
        for dr in range(-1, th + 1):
            for dc in range(-1, tw + 1):
                if 0 <= dr < th and 0 <= dc < tw:
                    continue
                nr = r + dr
                nc = c + dc
                if 0 <= nr < h and 0 <= nc < w:
                    score += int(g[nr, nc] == 1)
        return score

    target_score = two_border_score(tr0, tc0)

    best = None
    best_val = -1
    for r, c in candidates:
        val = border_score(r, c)
        # Prefer exact match to the 2-block border, then larger 1-border.
        key = (val == target_score, val)
        if key > best_val:
            best_val = key
            best = (r, c)

    dr, dc = best

    out = g.copy()

    # Move the 0-block: original 0s become 1s.
    out[zr0:zr1, zc0:zc1] = 1

    # Destination becomes 0s.
    out[dr:dr + zh, dc:dc + zw] = 0

    return out.tolist()

