from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return [row[:] for row in grid]

    H = len(grid)
    W = len(grid[0])
    g = [list(map(int, row)) for row in grid]

    # Count colours.
    counts = {}
    for r in range(H):
        for c in range(W):
            v = g[r][c]
            counts[v] = counts.get(v, 0) + 1

    # The wall colour is the most frequent colour that forms long straight
    # connected runs.  In the supplied puzzles this is the colour of the
    # partitioning lines.
    def run_score(colour):
        best = 0
        for r in range(H):
            run = 0
            for c in range(W):
                if g[r][c] == colour:
                    run += 1
                    best = max(best, run)
                else:
                    run = 0
        for c in range(W):
            run = 0
            for r in range(H):
                if g[r][c] == colour:
                    run += 1
                    best = max(best, run)
                else:
                    run = 0
        return best

    wall = max(counts, key=lambda x: (run_score(x), counts[x]))

    # Background is the most frequent non-wall colour.
    background = max((v for v in counts if v != wall), key=lambda x: counts[x], default=0)

    # Connected components of non-wall cells.
    seen = [[False] * W for _ in range(H)]
    out = [row[:] for row in g]

    for sr in range(H):
        for sc in range(W):
            if seen[sr][sc] or g[sr][sc] == wall:
                continue

            # BFS component.
            q = deque([(sr, sc)])
            seen[sr][sc] = True
            cells = []
            min_r = max_r = sr
            min_c = max_c = sc

            while q:
                r, c = q.popleft()
                cells.append((r, c))
                min_r = min(min_r, r)
                max_r = max(max_r, r)
                min_c = min(min_c, c)
                max_c = max(max_c, c)

                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < H and 0 <= nc < W:
                        if not seen[nr][nc] and g[nr][nc] != wall:
                            seen[nr][nc] = True
                            q.append((nr, nc))

            # Seeds are non-background, non-wall pixels inside this component.
            seeds = []
            for r, c in cells:
                v = g[r][c]
                if v != background and v != wall:
                    level = min(r - min_r, max_r - r, c - min_c, max_c - c)
                    seeds.append((level, r, c, v))

            if not seeds:
                # No explicit seed: leave the component as background.
                for r, c in cells:
                    out[r][c] = background
                continue

            # Order seeds by nesting level, then position.
            seeds.sort(key=lambda x: (x[0], x[1], x[2]))
            colors = [v for _, _, _, v in seeds]

            # Fill every non-wall cell in the component by its distance to the
            # component bounding box, cycling through the seed colours.
            for r, c in cells:
                level = min(r - min_r, max_r - r, c - min_c, max_c - c)
                out[r][c] = colors[level % len(colors)]

    return out

