    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # background is the most frequent colour
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # candidate corner cells: 0 with at least two orthogonal 0-neighbours
    corners = []
    for r in range(h):
        for c in range(w):
            if g[r, c] != 0:
                continue
            up = r > 0 and g[r - 1, c] == 0
            down = r + 1 < h and g[r + 1, c] == 0
            left = c > 0 and g[r, c - 1] == 0
            right = c + 1 < w and g[r, c + 1] == 0
            if (up + down + left + right) >= 2:
                corners.append((r, c))

    # directions: (dr, dc, corner_anchor_offset)
    dirs = [
        (-1, -1, (-1, -1)),  # NW
        (-1, 1, (-1, 0)),    # NE
        (1, -1, (0, -1)),    # SW
        (1, 1, (0, 0)),      # SE
    ]

    # For every non-background, non-zero pixel, try to connect it diagonally
    # to a 0-corner.  If the whole diagonal is clear of other colours, paint
    # the diagonal and the 2x2 corner block.
    for r in range(h):
        for c in range(w):
            col = g[r, c]
            if col == 0 or col == bg:
                continue

            for dr, dc, (ar, ac) in dirs:
                rr, cc = r, c
                while 0 <= rr < h and 0 <= cc < w:
                    val = g[rr, cc]
                    if val == 0:
                        # found a 0; it must be a corner
                        if (rr, cc) in corners:
                            # check that the diagonal from source to corner
                            # contains only background, 0, or this colour
                            ok = True
                            tr, tc = r, c
                            while (tr, tc) != (rr, cc):
                                tv = g[tr, tc]
                                if tv not in (0, bg, col):
                                    ok = False
                                    break
                                tr += dr
                                tc += dc
                            if ok:
                                # paint diagonal
                                tr, tc = r, c
                                while (tr, tc) != (rr, cc):
                                    out[tr, tc] = col
                                    tr += dr
