def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Find all maximal connected components of 0-cells (4-connected).
    visited = np.zeros((h, w), dtype=bool)
    components = []

    for r in range(h):
        for c in range(w):
            if g[r, c] == 0 and not visited[r, c]:
                stack = [(r, c)]
                visited[r, c] = True
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w:
                            if not visited[ny, nx] and g[ny, nx] == 0:
                                visited[ny, nx] = True
                                stack.append((ny, nx))
                components.append(cells)

    # For each zero component, find diagonal "source" cells of a non-zero color
    # that point to a corner of the component.  Propagate that color to the
    # corner and the two cells adjacent to the corner away from the source.
    for cells in components:
        cell_set = set(cells)
        ys = [r for r, c in cells]
        xs = [c for r, c in cells]
        rmin, rmax = min(ys), max(ys)
        cmin, cmax = min(xs), max(xs)

        # Candidate corners: component cells that are extreme in both row and column.
        corners = [
            (r, c)
            for r, c in cells
            if (r == rmin or r == rmax) and (c == cmin or c == cmax)
        ]

        for cr, cc in corners:
            # Check the four diagonal directions from the corner.
            for dr, dc in ((1, 1), (1, -1), (-1, 1), (-1, -1)):
                sr, sc = cr + dr, cc + dc
                if not (0 <= sr < h and 0 <= sc < w):
                    continue
                color = g[sr, sc]
                if color == 0:
                    continue

                # The source must be outside the zero component.
                if (sr, sc) in cell_set:
                    continue

                # The two cells adjacent to the corner away from the source.
                targets = [
                    (cr, cc),
                    (cr - dr, cc),
                    (cr, cc - dc),
                ]

                # Only overwrite background/non-zero cells that are not part of
                # the zero component and do not already contain another color.
                for tr, tc in targets:
                    if not (0 <= tr < h and 0 <= tc < w):
                        continue
                    if (tr, tc) in cell_set:
                        continue
                    if out[tr, tc] == 0 or out[tr, tc] == color:
                        out[tr, tc] = color

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import math

    h = len(grid)
    w = len(grid[0])
    out = [[0] * w for _ in range(h)]

    # Preserve original pixels first.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                out[r][c] = grid[r][c]

    # Collect points by colour.
    pts = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v != 0:
                pts.setdefault(v, []).append((r, c))

    def draw_line(p, q, color):
        r1, c1 = p
        r2, c2 = q
        dr = r2 - r1
        dc = c2 - c1
        steps = max(abs(dr), abs(dc))
        if steps == 0:
            out[r1][c1] = color
            return
        for i in range(steps + 1):
            r = r1 + round(dr * i / steps)
            c = c1 + round(dc * i / steps)
            if 0 <= r < h and 0 <= c < w:
                out[r][c] = color

    def convex_hull(points):
        pts = sorted(set(points))
        if len(pts) <= 1:
            return pts

        def cross(o, a, b):
            return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

        lower = []
        for p in pts:
            while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
                lower.pop()
            lower.append(p)

        upper = []
        for p in reversed(pts):
            while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
                upper.pop()
            upper.append(p)

        return lower[:-1] + upper[:-1]

    # Draw polygons for colours with at least 3 non-collinear points.
    for color, points in pts.items():
        if len(points) < 3:
            continue
        hull = convex_hull(points)
        if len(hull) < 3:
            continue
        for i in range(len(hull)):
            draw_line(hull[i], hull[(i + 1) % len(hull)], color)

    # Draw lines for colours with exactly 2 points.
    for color, points in pts.items():
        if len(points) == 2:
            draw_line(points[0], points[1], color)

    # Special shadow rule between colours 1 and 8.
    # If one of them has a single point and the other has a polygon,
    # draw the single-point colour as a shifted copy of the polygon.
    if 1 in pts and 8 in pts:
        if len(pts[1]) == 1 and len(pts[8]) >= 3:
            hull = convex_hull(pts[8])
            if len(hull) >= 3:
                sr, sc = pts[1][0]
                # Use the top-left-most hull point as the anchor.
                anchor = min(hull, key=lambda p: (p[0], p[1]))
                dr = sr - anchor[0]
                dc = sc - anchor[1]
                shifted = [(r + dr, c + dc) for r, c in hull]
                for i in range(len(shifted)):
                    draw_line(shifted[i], shifted[(i + 1) % len(shifted)], 1)
        elif len(pts[8]) == 1 and len(pts[1]) >= 3:
            hull = convex_hull(pts[1])
            if len(hull) >= 3:
                sr, sc = pts[8][0]
                anchor = min(hull, key=lambda p: (p[0], p[1]))
                dr = sr - anchor[0]
                dc = sc - anchor[1]
                shifted = [(r + dr, c + dc) for r, c in hull]
                for i in range(len(shifted)):
                    draw_line(shifted[i], shifted[(i + 1) % len(shifted)], 8)

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import math

    h = len(grid)
    w = len(grid[0])
    out = [[0] * w for _ in range(h)]

    # Keep original pixels.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                out[r][c] = grid[r][c]

    # Group original pixels by colour.
    pts = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v != 0:
                pts.setdefault(v, []).append((r, c))

    def draw_line(p, q, color):
        r1, c1 = p
        r2, c2 = q
        dr = r2 - r1
        dc = c2 - c1
        steps = max(abs(dr), abs(dc))
        if steps == 0:
            if 0 <= r1 < h and 0 <= c1 < w:
                out[r1][c1] = color
            return
        for i in range(steps + 1):
            r = r1 + round(dr * i / steps)
            c = c1 + round(dc * i / steps)
            if 0 <= r < h and 0 <= c < w:
                out[r][c] = color

    def convex_hull(points):
        pts = sorted(set(points))
        if len(pts) <= 1:
            return pts

        def cross(o, a, b):
            return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

        lower = []
        for p in pts:
            while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
                lower.pop()
            lower.append(p)

        upper = []
        for p in reversed(pts):
            while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
                upper.pop()
            upper.append(p)

        return lower[:-1] + upper[:-1]

    # Draw ordinary same-colour shapes:
    # - 2 points: line
    # - >=3 non-collinear points: convex-hull border
    for color, points in pts.items():
        if len(points) == 2:
            draw_line(points[0], points[1], color)
        elif len(points) >= 3:
            hull = convex_hull(points)
            if len(hull) >= 3:
                for i in range(len(hull)):
                    draw_line(hull[i], hull[(i + 1) % len(hull)], color)

    # Special paired-colour rule seen in the examples:
    # one colour has a single anchor point, the other has a polygon.
    # The anchor colour draws a shifted copy of the polygon.
    # The shift is chosen so that the shifted polygon's top-left-most
    # hull point lands on the anchor point.
    def draw_shifted_polygon(anchor_color, poly_color):
        if anchor_color not in pts or poly_color not in pts:
            return
        if len(pts[anchor_color]) != 1:
            return
        if len(pts[poly_color]) < 3:
            return

        hull = convex_hull(pts[poly_color])
        if len(hull) < 3:
            return

        ar, ac = pts[anchor_color][0]
        anchor_hull = min(hull, key=lambda p: (p[0], p[1]))
        dr = ar - anchor_hull[0]
        dc = ac - anchor_hull[1]

        shifted = [(r + dr, c + dc) for r, c in hull]
        for i in range(len(shifted)):
            draw_line(shifted[i], shifted[(i + 1) % len(shifted)], anchor_color)

    # The examples use these anchor/polygon pairs.
    draw_shifted_polygon(8, 1)
    draw_shifted_polygon(7, 6)

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    H, W = g.shape
    out = np.full((H, W), 6, dtype=int)

    def is_box(r, c):
        if not (0 <= r < H and 0 <= c < W):
            return False
        if g[r, c] != 0:
            return False
        if r + 1 >= H or g[r + 1, c] != 0:
            return False
        if c + 1 >= W or g[r, c + 1] != 0:
            return False
        if g[r + 1, c + 1] != 0:
            return False
        return True

    def box_dims(r, c):
        r2 = r
        while r2 + 1 < H and g[r2 + 1, c] == 0:
            r2 += 1
        c2 = c
        while c2 + 1 < W and g[r, c2 + 1] == 0:
            c2 += 1
        return r, c, r2, c2

    def wall_len(r, c, dr, dc):
        L = 0
        rr, cc = r, c
        while 0 <= rr < H and 0 <= cc < W and g[rr, cc] == 9:
            L += 1
            rr += dr
            cc += dc
        return L

    def move_box(r, c, r2, c2, dr, dc):
        h = r2 - r + 1
        w = c2 - c + 1
        L = wall_len(r - dr, c - dc, dr, dc)
        d = L - 1
        if d <= 0:
            return

        nr, nc = r + dr * d, c + dc * d
        nr2, nc2 = r2 + dr * d, c2 + dc * d

        if not (0 <= nr < H and 0 <= nc < W and 0 <= nr2 < H and 0 <= nc2 < W):
            return

        # The box and its attached wall move together.
        for i in range(h):
            for j in range(w):
                out[nr + i, nc + j] = g[r + i, c + j]

        # The wall is shortened by the movement amount.
        for i in range(L - d):
            out[r - dr + i * dr, c - dc + i * dc] = 9

        # 7s propagate from existing 7s in the direction opposite to movement.
        for i in range(h):
            for j in range(w):
                if g[r + i, c + j] == 7:
                    for k in range(1, d + 1):
                        ni = i - dr * k
                        nj = j - dc * k
                        if 0 <= ni < h and 0 <= nj < w:
                            out[nr + ni, nc + nj] = 7

    for r in range(H):
        for c in range(W):
            if is_box(r, c):
                r2, c2 = box_dims(r, c)
                if r > 0 and g[r - 1, c] == 9:
                    move_box(r, c, r2, c2, -1, 0)
                elif c > 0 and g[r, c - 1] == 9:
                    move_box(r, c, r2, c2, 0, -1)
                elif r + 1 < H and g[r + 1, c] == 9:
                    move_box(r, c, r2, c2, 1, 0)
                elif c + 1 < W and g[r, c + 1] == 9:
                    move_box(r, c, r2, c2, 0, 1)

    return out.tolist()

