def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    a = np.array(grid, dtype=int)
    h, w = a.shape

    # Background is the corner colour; object is the other colour.
    bg = int(a[0, 0])
    obj = None
    for row in a:
        for v in row:
            if int(v) != bg:
                obj = int(v)
                break
        if obj is not None:
            break
    if obj is None:
        return [[bg]]

    mask = (a == obj).astype(np.uint8)

    # Bounding box of the object.
    rows = np.any(mask, axis=1)
    cols = np.any(mask, axis=0)
    r0, r1 = np.where(rows)[0][[0, -1]]
    c0, c1 = np.where(cols)[0][[0, -1]]
    m = mask[r0:r1 + 1, c0:c1 + 1].copy()

    # Morphological thinning (Zhang-Suen style), preserving 8-connectivity.
    def neighbors8(x, y):
        n = 0
        vals = []
        for dx in (-1, 0, 1):
            for dy in (-1, 0, 1):
                if dx == 0 and dy == 0:
                    continue
                nx, ny = x + dx, y + dy
                if 0 <= nx < m.shape[0] and 0 <= ny < m.shape[1]:
                    vals.append(m[nx, ny])
                else:
                    vals.append(0)
        n = sum(vals)
        # Number of 0->1 transitions in the cyclic 8-neighbourhood.
        trans = 0
        for i in range(8):
            if vals[i] == 0 and vals[(i + 1) % 8] == 1:
                trans += 1
        return n, trans, vals

    def thin_once(img):
        h, w = img.shape
        to_remove = np.zeros((h, w), dtype=bool)

        # Step 1
        for x in range(h):
            for y in range(w):
                if img[x, y] != 1:
                    continue
                n, trans, vals = neighbors8(x, y)
                if 2 <= n <= 6 and trans == 1:
                    # P2*P3*P5 == 0 and P4*P5*P6 == 0
                    # vals order:
                    # 0 1 2
                    # 7   3
                    # 6 5 4
                    p2, p3, p5 = vals[2], vals[3], vals[5]
                    p4, p5b, p6 = vals[4], vals[5], vals[6]
                    if p2 * p3 * p5 == 0 and p4 * p5b * p6 == 0:
                        to_remove[x, y] = True

        img = img.copy()
        img[to_remove] = 0

        # Step 2
        to_remove = np.zeros((h, w), dtype=bool)
        for x in range(h):
            for y in range(w):
                if img[x, y] != 1:
                    continue
                n, trans, vals = neighbors8(x, y)
                if 2 <= n <= 6 and trans == 1:
                    p2, p4, p6 = vals[2], vals[4], vals[6]
                    p3, p4b, p5 = vals[3], vals[4], vals[5]
                    if p2 * p4 * p6 == 0 and p3 * p4b * p5 == 0:
                        to_remove[x, y] = True

        img[to_remove] = 0
        return img

    # Thin until stable.
    while True:
        nxt = thin_once(m)
        if np.array_equal(nxt, m):
            break
        m = nxt

    # Crop to the skeleton bounding box.
    rows = np.any(m, axis=1)
    cols = np.any(m, axis=0)
    if not np.any(rows) or not np.any(cols):
        return [[bg]]

    r0s, r1s = np.where(rows)[0][[0, -1]]
    c0s, c1s = np.where(cols)[0][[0, -1]]
    skel = m[r0s:r1s + 1, c0s:c1s + 1]

    out = np.full(skel.shape, bg, dtype=int)
    out[skel == 1] = obj
    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Count non-zero colours.
    counts = {}
    for v in g.flat:
        if v != 0:
            counts[int(v)] = counts.get(int(v), 0) + 1

    if not counts:
        return [list(map(int, row)) for row in g]

    # The large connected component is the “track”.
    track_color = max(counts, key=lambda c: counts[c])

    # Background is the most common colour that is not the track colour.
    bg_color = max((c for c in counts if c != track_color),
                   key=lambda c: counts[c], default=0)

    # Palette colours are all non-background colours except the track colour.
    palette = [c for c in counts if c != bg_color and c != track_color]

    # If there is no palette, nothing to draw.
    if not palette:
        return [list(map(int, row)) for row in g]

    # Find the track component containing the most track cells.
    best_comp = []
    best_size = -1
    seen = np.zeros((H, W), dtype=bool)

    for r in range(H):
        for c in range(W):
            if g[r, c] == track_color and not seen[r, c]:
                q = deque([(r, c)])
                seen[r, c] = True
                comp = []
                while q:
                    y, x = q.popleft()
                    comp.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < H and 0 <= nx < W:
                            if not seen[ny, nx] and g[ny, nx] == track_color:
                                seen[ny, nx] = True
                                q.append((ny, nx))
                if len(comp) > best_size:
                    best_size = len(comp)
                    best_comp = comp

    if not best_comp:
        return [list(map(int, row)) for row in g]

    comp_set = set(best_comp)

    # Endpoints are palette cells adjacent to the track component.
    endpoints = []
    for r, c in best_comp:
        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dy, c + dx
            if 0 <= nr < H and 0 <= nc < W:
                v = int(g[nr, nc])
                if v != bg_color and v != track_color:
                    endpoints.append((nr, nc, v))

    # If no external endpoints, use the two most extreme track cells.
    if not endpoints:
        pts = sorted(best_comp)
        endpoints = [(pts[0][0], pts[0][1], palette[0]),
                     (pts[-1][0], pts[-1][1], palette[0])]
    else:
        # Keep unique endpoint cells.
        uniq = {}
        for r, c, v in endpoints:
            uniq[(r, c)] = v
        endpoints = [(r, c, v) for (r, c), v in uniq.items()]

        # Choose the two endpoints that are farthest apart.
        best_pair = None
        best_dist = -1
        for i in range(len(endpoints)):
            for j in range(i + 1, len(endpoints)):
                r1, c1, _ = endpoints[i]
                r2, c2, _ = endpoints[j]
                d = abs(r1 - r2) + abs(c1 - c2)
                if d > best_dist:
                    best_dist = d
                    best_pair = (endpoints[i], endpoints[j])
        endpoints = list(best_pair)

    start, end = endpoints

    # Build graph over track cells plus the two endpoint cells.
    nodes = set(comp_set)
    nodes.add((start[0], start[1]))
    nodes.add((end[0], end[1]))

    adj = {node: [] for node in nodes}
    for (r, c) in nodes:
        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dy, c + dx
            if (nr, nc) in nodes:
                adj[(r, c)].append((nr, nc))

    # Shortest path between endpoints.
    prev = {start: None}
    q = deque([start])
    while q:
        cur = q.popleft()
        if cur == end:
            break
        for nxt in adj[cur]:
            if nxt not in prev:
                prev[nxt] = cur
                q.append(nxt)

    path = []
    cur = end
    while cur is not None:
        path.append(cur)
        cur = prev[cur]
    path.reverse()

    # Determine the repeating colour sequence from the small 2x8 key block.
    # It is the top-left 2x8 block of non-background/non-track colours.
    key = []
    for r in range(min(2, H)):
        for c in range(min(8, W)):
            v = int(g[r, c])
            if v != bg_color and v != track_color:
                key.append(v)

    if not key:
        key = palette

    # Remove duplicates while preserving order, but keep the sequence length
    # if it is already a plausible repeating pattern.
    seq = []
    for v in key:
        if v not in seq:
            seq.append(v)

    # In the examples the key gives a short repeating pattern.
    # If the key is longer than the palette, use it directly as the pattern.
    if len(key) > len(palette):
        seq = key
    else:
        seq = key if key else palette

    # Ensure all palette colours appear in the sequence.
    for v in palette:
        if v not in seq:
            seq.append(v)

    # Draw the path with the repeating sequence.
    out = g.copy()
    for i, (r, c) in enumerate(path):
        out[r, c] = seq[i % len(seq)]

    return [list(map(int, row)) for row in out]

