def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape

    out = np.full((H, W), 1, dtype=int)

    sevens = np.argwhere(g == 7)
    twos = np.argwhere(g == 2)

    if len(sevens) == 0:
        out[twos[:, 0], twos[:, 1]] = 2
        return out.tolist()

    rmin, cmin = sevens.min(axis=0)
    rmax, cmax = sevens.max(axis=0)

    # Determine split lines from 2s on the border.
    vcols = set()
    hrows = set()
    for r, c in twos:
        if r == 0 or r == H - 1:
            vcols.add(c)
        if c == 0 or c == W - 1:
            hrows.add(r)

    # If no border 2s, fall back to the 2's column/row.
    if not vcols and not hrows and len(twos):
        r, c = twos[0]
        vcols.add(c)
        hrows.add(r)

    # Keep 7s that lie on the split lines.
    for r, c in sevens:
        if c in vcols or r in hrows:
            out[r, c] = 7

    # Move off-line 7 pieces to the four corners.
    def place(piece, top, left):
        pr, pc = piece.shape
        out[top:top + pr, left:left + pc] = piece

    if vcols:
        vc = min(vcols)
        # Left piece: columns < vc
        if cmin < vc:
            sub = g[rmin:rmax + 1, cmin:vc]
            if (sub == 7).any():
                pr, pc = sub.shape
                place(sub, H - pr, 0)
        # Right piece: columns > vc
        if cmax > vc:
            sub = g[rmin:rmax + 1, vc + 1:cmax + 1]
            if (sub == 7).any():
                pr, pc = sub.shape
                place(sub, H - pr, W - pc)

    if hrows:
        hr = min(hrows)
        # Top piece: rows < hr
        if rmin < hr:
            sub = g[rmin:hr, cmin:cmax + 1]
            if (sub == 7).any():
                pr, pc = sub.shape
                place(sub, 0, 0)
        # Bottom piece: rows > hr
        if rmax > hr:
            sub = g[hr + 1:rmax + 1, cmin:cmax + 1]
            if (sub == 7).any():
                pr, pc = sub.shape
                place(sub, H - pr, W - pc)

    # Place 2s on split lines.
    for r, c in twos:
        out[r, c] = 2

    if vcols:
        vc = min(vcols)
        # Vertical segment between top border and the lowest kept 7 on that column.
        col7 = [r for r in range(H) if out[r, vc] == 7]
        if col7:
            stop = max(col7)
            for r in range(0, stop):
                if out[r, vc] == 1:
                    out[r, vc] = 2
        # If there is a horizontal split, fill the horizontal row between
        # the nearest kept 7 to the left and the right border.
        if hrows:
            hr = min(hrows)
            left7 = [c for c in range(W) if out[hr, c] == 7]
            if left7:
                start = max(c for c in left7 if c < vc) if any(c < vc for c in left7) else -1
                for c in range(start + 1, W):
                    if out[hr, c] == 1:
                        out[hr, c] = 2

    if hrows:
        hr = min(hrows)
        # Horizontal segment between left border and the rightmost kept 7 on that row.
        row7 = [c for c in range(W) if out[hr, c] == 7]
        if row7:
            stop = max(row7)
            for c in range(0, stop):
                if out[hr, c] == 1:
                    out[hr, c] = 2

    return out.tolist()

