import numpy as np
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Find the vertical separator: a column that is entirely one non-zero color
    # and is not the first column.
    sep_col = None
    for c in range(1, w):
        col = g[:, c]
        if np.all(col > 0) and np.all(col == col[0]):
            sep_col = c
            break
    if sep_col is None:
        return out.tolist()

    # Frame borders:
    # left border is the first column to the right of the separator,
    # right border is the last column.
    left_b = sep_col + 1
    right_b = w - 1
    top_b = 0
    bottom_b = h - 1

    # Determine the frame background color from the four border corners.
    corners = [g[top_b, left_b], g[top_b, right_b],
               g[bottom_b, left_b], g[bottom_b, right_b]]
    bg = int(np.bincount(corners).argmax())

    # Collect marker rows/columns for each color on the frame border.
    row_markers = {}
    col_markers = {}

    for r in range(top_b, bottom_b + 1):
        if g[r, left_b] not in (0, bg):
            row_markers.setdefault(int(g[r, left_b]), []).append(r)
        if g[r, right_b] not in (0, bg):
            row_markers.setdefault(int(g[r, right_b]), []).append(r)

    for c in range(left_b, right_b + 1):
        if g[top_b, c] not in (0, bg):
            col_markers.setdefault(int(g[top_b, c]), []).append(c)
        if g[bottom_b, c] not in (0, bg):
            col_markers.setdefault(int(g[bottom_b, c]), []).append(c)

    # Clean duplicate corner markers.
    for color in list(row_markers.keys()):
        rows = sorted(set(row_markers[color]))
        if len(rows) == 1 and rows[0] in (top_b, bottom_b):
            del row_markers[color]
        else:
            row_markers[color] = rows

    for color in list(col_markers.keys()):
        cols = sorted(set(col_markers[color]))
        if len(cols) == 1 and cols[0] in (left_b, right_b):
            del col_markers[color]
        else:
            col_markers[color] = cols

    # Extract connected components from the left palette area.
    palette = g[:, :sep_col]
    seen = np.zeros(palette.shape, dtype=bool)
    components = []

    for r in range(palette.shape[0]):
        for c in range(palette.shape[1]):
            color = int(palette[r, c])
            if color == 0 or seen[r, c]:
                continue

            q = deque([(r, c)])
            seen[r, c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < palette.shape[0] and 0 <= nx < palette.shape[1]:
                        if not seen[ny, nx] and int(palette[ny, nx]) == color:
                            seen[ny, nx] = True
                            q.append((ny, nx))

            ys = [y for y, _ in cells]
            xs = [x for _, x in cells]
            cy = (min(ys) + max(ys)) / 2.0
            cx = (min(xs) + max(xs)) / 2.0
            components.append((color, cells, cy, cx))

    # For each marker color, use the matching palette component, if any.
    for color, rows in row_markers.items():
        if color not in col_markers:
            continue

        # Choose the component of this color closest to the marker center.
        candidates = [comp for comp in components if comp[0] == color]
        if not candidates:
            continue

        target_rows = rows
        target_cols = col_markers[color]

        # Pair markers in sorted order when possible; otherwise cross-pair.
        if len(target_rows) == len(target_cols):
            centers = list(zip(target_rows, target_cols))
        else:
            centers = [(r, c) for r in target_rows for c in target_cols]

        # If there are multiple components of the same color, assign each
        # center to the nearest component.
        for tr, tc in centers:
            comp = min(
                candidates,
                key=lambda comp: (comp[2] - tr) ** 2 + (comp[3] - tc) ** 2
            )
            _, cells, cy, cx = comp

            # Remove the original palette component.
            for y, x in cells:
                out[y, x] = 0

            # Place it centered at the target intersection.
            for y, x in cells:
                ny = int(round(tr + (y - cy)))
                nx = int(round(tc + (x - cx)))
                if 0 <= ny < h and 0 <= nx < w:
                    out[ny, nx] = color

    return out.tolist()

