import numpy as np
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Find the vertical wall: a full column of one non-zero colour.
    wall_col = None
    for c in range(W):
        col = g[:, c]
        if col[0] != 0 and np.all(col == col[0]):
            wall_col = int(c)
            break

    if wall_col is None:
        return [[int(x) for x in row] for row in g]

    L = wall_col
    R = W - 1

    # Interior of the right-hand room.
    r0, r1 = 1, H - 2
    c0, c1 = L + 2, R - 1

    # Background colour inside the room: most common colour on the top border
    # between the wall and the right edge.
    top_segment = g[0, L + 1:R + 1]
    vals, counts = np.unique(top_segment, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # Marker rows: non-background colours on the left border of the room.
    vcol = g[r0:r1 + 1, L + 1]
    v_rows = {}
    for i, val in enumerate(vcol):
        val = int(val)
        if val != bg:
            v_rows.setdefault(val, []).append(r0 + i)

    # Marker columns: non-background colours on the top border of the room.
    hrow = g[0, c0:c1 + 1]
    h_cols = {}
    for j, val in enumerate(hrow):
        val = int(val)
        if val != bg:
            h_cols.setdefault(val, []).append(c0 + j)

    # Extract connected components from the left side of the wall.
    left = g[:, :L]
    seen = np.zeros(left.shape, dtype=bool)
    shapes = {}

    for sr in range(left.shape[0]):
        for sc in range(left.shape[1]):
            if seen[sr, sc] or left[sr, sc] == 0:
                continue

            color = int(left[sr, sc])
            q = deque([(sr, sc)])
            seen[sr, sc] = True
            cells = []

            while q:
                r, c = q.popleft()
                cells.append((r, c))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < left.shape[0] and 0 <= nc < left.shape[1]:
                        if not seen[nr, nc] and int(left[nr, nc]) == color:
                            seen[nr, nc] = True
                            q.append((nr, nc))

            min_r = min(r for r, _ in cells)
            min_c = min(c for _, c in cells)
            rel = [(r - min_r, c - min_c) for r, c in cells]
            shapes.setdefault(color, []).append(rel)

    # Start from the input, but erase left-side shapes whose colour is stamped.
    out = g.copy()
    stamp_colors = set(v_rows.keys()) & set(h_cols.keys())

    for color in stamp_colors:
        for rel in shapes.get(color, []):
            for dr, dc in rel:
                r = int(dr)
                c = int(dc)
                if 0 <= r < H and 0 <= c < L:
                    out[r, c] = 0

    # Draw stamps.  Higher colours are drawn first, so lower colours win overlaps.
    for color in sorted(stamp_colors, reverse=True):
        for rel in shapes.get(color, []):
            min_r = min(dr for dr, _ in rel)
            min_c = min(dc for _, dc in rel)
            max_r = max(dr for dr, _ in rel)
            max_c = max(dc for _, dc in rel)
            h = max_r - min_r + 1
            w = max_c - min_c + 1

            # Centre of the shape's bounding box, in local coordinates.
            cr = (h - 1) / 2.0
            cc = (w - 1) / 2.0

            for vr in v_rows.get(color, []):
                for hc in h_cols.get(color, []):
                    for dr, dc in rel:
                        r = int(round(vr + dr - cr))
                        c = int(round(hc + dc - cc))
                        if r0 <= r <= r1 and c0 <= c <= c1:
                            out[r, c] = color

    return [[int(x) for x in row] for row in out]

