    for color in nonbg:
        mask = (g == color)
        comps = components(mask)
        # prefer the colour whose components are mostly small 3-cell objects
        score = sum(1 for comp in comps if len(comp) == 3)
        if score > best_score:
            best_score = score
            best_color = color
            best_comps = comps

    if not best_comps:
        return [[int(x) for x in row] for row in g]

    # output colour: 2 -> 9, 9 -> 1, otherwise a stable non-background fallback
    if best_color == 2:
        out_color = 9
    elif best_color == 9:
        out_color = 1
    else:
        out_color = (best_color + 7) % 10
        if out_color == bg:
            out_color = (out_color + 1) % 10

    out = g.copy()

    # For every 3-cell object, place a marker at its top-left cell shifted by (-5, -5).
    # If that marker lands on another object of the same colour, recolor that whole object.
    hit_cells = set()
    for comp in best_comps:
        if len(comp) != 3:
            continue
        top_left = (min(r for r, c in comp), min(c for r, c in comp))
        mr, mc = top_left[0] - 5, top_left[1] - 5
        if 0 <= mr < h and 0 <= mc < w:
            out[mr, mc] = out_color
            if out[mr, mc] == best_color:
                # find the component containing this marker position
                for other in best_comps:
                    if (mr, mc) in other:
                        hit_cells.update(other)
                        break

    for r, c in hit_cells:
        out[r, c] = out_color

    return [[int(x) for x in row] for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Background is the most frequent colour.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # Find all 4-connected components of non-background cells.
    mask = (g != bg)
    seen = np.zeros_like(mask, dtype=bool)
    comps = []

    for r in range(h):
        for c in range(w):
            if mask[r, c] and not seen[r, c]:
                stack = [(r, c)]
                seen[r, c] = True
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and mask[ny, nx] and not seen[ny, nx]:
                            seen[ny, nx] = True
                            stack.append((ny, nx))
                comps.append(cells)

    # For each 3-cell component, determine its "point" and direction.
    # - L triomino in a 2x2 box: point is the elbow cell, direction is diagonal.
    # - V triomino in a 2x3 box: point is the single cell, direction is vertical.
    shots = []  # (target_r, target_c, component_cells)

    for comp in comps:
        if len(comp) != 3:
            continue

        rs = [r for r, c in comp]
        cs = [c for r, c in comp]
        rmin, rmax = min(rs), max(rs)
        cmin, cmax = min(cs), max(cs)
        height = rmax - rmin + 1
        width = cmax - cmin + 1

        point = None
        dr = dc = 0

        if height == 2 and width == 2:
            # L triomino: the elbow is the cell with two orthogonal neighbours.
            for r, c in comp:
                neigh = 0
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    if (r + dy, c + dx) in comp:
                        neigh += 1
                if neigh == 2:
                    point = (r, c)
                    break

            if point is None:
                continue

            # Direction is from the missing corner toward the elbow.
            missing_r = rmin + rmax - point[0]
            missing_c = cmin + cmax - point[1]
            dr = (1 if point[0] > missing_r else -1)
            dc = (1 if point[1] > missing_c else -1)

        elif height == 2 and width == 3:
            # V triomino: the point is the cell in the row that has only one cell.
            top_count = sum(1 for r, c in comp if r == rmin)
            if top_count == 1:
                point = next((r, c) for r, c in comp if r == rmin)
                dr, dc = -1, 0
            else:
                point = next((r, c) for r, c in comp if r == rmax)
                dr, dc = 1, 0

        else:
            continue

        tr, tc = point[0] + 5 * dr, point[1] + 5 * dc
        if 0 <= tr < h and 0 <= tc < w:
            shots.append((tr, tc, comp))

    out = g.copy()

    # Apply shots.
    # If a shot lands on background, paint it 9.
    # If it lands on a non-background cell, repaint that whole 4-connected component 9.
    # If two or more shots land on the same background cell, paint it 1.
    target_count = {}
    for tr, tc, comp in shots:
        target_count[(tr, tc)] = target_count.get((tr, tc), 0) + 1

    for (tr, tc), cnt in target_count.items():
        if g[tr, tc] == bg:
            out[tr, tc] = 1 if cnt >= 2 else 9
        else:
            # Repaint the component containing the hit cell.
            for comp in comps:
                if (tr, tc) in comp:
                    for r, c in comp:
                        out[r, c] = 9
                    break

    return [[int(x) for x in row] for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    import math

    h = len(grid)
    w = len(grid[0]) if h else 0

    def line_score(cells):
        """Score a row/column as a valid pattern line."""
        counts = {}
        for v in cells:
            if v != 0:
                counts[v] = counts.get(v, 0) + 1

        if not counts:
            return -1

        repeated = [c for c, n in counts.items() if n >= 2]
        if not repeated:
            return -1

        # Prefer lines with exactly one repeated color and at most one singleton.
        if len(repeated) != 1:
            return -1

        rep = repeated[0]
        singletons = [c for c, n in counts.items() if c != rep and n == 1]
        if len(singletons) > 1:
            return -1

        # The repeated color should form a clean arithmetic progression from 0.
        pos = [i for i, v in enumerate(cells) if v == rep]
        if not pos:
            return -1

        # Period is the smallest positive difference that explains all positions.
        period = None
        for p in range(1, max(len(cells), 1)):
            if all(i % p == 0 for i in pos):
                period = p
                break
        if period is None:
            return -1

        # Stronger score for more repeated pixels and fewer extra colors.
        score = 100 * len(pos)
        if singletons:
            score += 50
        return score

    def best_orientation():
        row_scores = []
        for r in range(h):
            row_scores.append(line_score(grid[r]))

        col_scores = []
        for c in range(w):
            col_scores.append(line_score([grid[r][c] for r in range(h)]))

        row_total = sum(s for s in row_scores if s > 0)
        col_total = sum(s for s in col_scores if s > 0)

        # Choose the orientation with more valid pattern lines.
        # Tie-break by total score, then by horizontal orientation.
        if col_total > row_total:
            return "col", col_scores
        if row_total > col_total:
            return "row", row_scores
        if row_total == col_total:
            if row_total == 0:
                return "row", row_scores
            # If tied, prefer the orientation with more active lines.
            row_active = sum(1 for s in row_scores if s > 0)
            col_active = sum(1 for s in col_scores if s > 0)
            if col_active > row_active:
                return "col", col_scores
            return "row", row_scores
        return "row", row_scores

    orientation, scores = best_orientation()
    out = [[0] * w for _ in range(h)]

    if orientation == "row":
        for r in range(h):
            if scores[r] <= 0:
                continue
            cells = grid[r]
            counts = {}
            for v in cells:
                if v != 0:
                    counts[v] = counts.get(v, 0) + 1

            rep = next(c for c, n in counts.items() if n >= 2)
            singletons = [c for c, n in counts.items() if c != rep and n == 1]
            fill_color = singletons[0] if singletons else rep

            pos = [i for i, v in enumerate(cells) if v == rep]
            period = None
            for p in range(1, w + 1):
                if all(i % p == 0 for i in pos):
                    period = p
                    break
            if period is None:
                continue

            if singletons:
                marker = next(i for i, v in enumerate(cells) if v == singletons[0])
                end = marker + period - 1
            else:
                end = w - 1

            for c in range(0, min(end, w - 1) + 1):
                if c % period == 0:
                    out[r][c] = fill_color

    else:
        for c in range(w):
            if scores[c] <= 0:
                continue
            cells = [grid[r][c] for r in range(h)]
            counts = {}
            for v in cells:
                if v != 0:
                    counts[v] = counts.get(v, 0) + 1

            rep = next(c for c, n in counts.items() if n >= 2)
            singletons = [c for c, n in counts.items() if c != rep and n == 1]
            fill_color = singletons[0] if singletons else rep

            pos = [i for i, v in enumerate(cells) if v == rep]
            period = None
            for p in range(1, h + 1):
                if all(i % p == 0 for i in pos):
                    period = p
                    break
            if period is None:
                continue

            if singletons:
                marker = next(i for i, v in enumerate(cells) if v == singletons[0])
                end = marker + period - 1
            else:
                end = h - 1

            for r in range(0, min(end, h - 1) + 1):
                if r % period == 0:
                    out[r][c] = fill_color

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import math

    h = len(grid)
    w = len(grid[0]) if h else 0

    def line_info(cells):
        """
        Return (fill_color, step, end) for a line if it looks like a valid
        pattern line, otherwise None.

        A valid line has:
        - one color appearing at least twice (the period-defining color), and
        - at most one other color (the optional fill-color marker).
        The step is the gcd of all non-zero coordinates in the line.
        If a marker color exists, fill up to the farthest non-zero coordinate;
        otherwise fill the whole line.
        """
        counts = {}
        for i, v in enumerate(cells):
            if v != 0:
                counts[v] = counts.get(v, 0) + 1

        if not counts:
            return None

        repeated = [c for c, n in counts.items() if n >= 2]
        if len(repeated) != 1:
            return None

        rep = repeated[0]
        others = [c for c, n in counts.items() if c != rep]
        if len(others) > 1:
            return None

        coords = [i for i, v in enumerate(cells) if v != 0]
        if not coords:
            return None

        step = 0
        for x in coords:
            step = math.gcd(step, x)
        if step == 0:
            step = 1

        if others:
            fill_color = others[0]
            end = max(coords)
        else:
            fill_color = rep
            end = len(cells) - 1

        return fill_color, step, end

    def score_line(cells):
        info = line_info(cells)
        if info is None:
            return -1
        fill_color, step, end = info
        # Prefer lines with a clear repeated color and a small step.
        score = 100
        if step == 1:
            score += 10
        # Slight preference for longer filled segments.
        score += end
        return score

    row_scores = [score_line(grid[r]) for r in range(h)]
    col_scores = [score_line([grid[r][c] for r in range(h)]) for c in range(w)]

    row_total = sum(s for s in row_scores if s > 0)
    col_total = sum(s for s in col_scores if s > 0)

    # Choose the orientation that has more valid pattern lines.
    # Tie-break by total score, then by horizontal orientation.
    if col_total > row_total:
        orientation = "col"
        scores = col_scores
    elif row_total > col_total:
        orientation = "row"
        scores = row_scores
    else:
        row_active = sum(1 for s in row_scores if s > 0)
        col_active = sum(1 for s in col_scores if s > 0)
        if col_active > row_active:
            orientation = "col"
            scores = col_scores
        else:
            orientation = "row"
            scores = row_scores

    out = [[0] * w for _ in range(h)]

    if orientation == "row":
        for r in range(h):
            if row_scores[r] <= 0:
                continue
            info = line_info(grid[r])
            if info is None:
                continue
            fill_color, step, end = info
            for c in range(0, min(end, w - 1) + 1):
                if c % step == 0:
                    out[r][c] = fill_color
    else:
        for c in range(w):
            if col_scores[c] <= 0:
                continue
            cells = [grid[r][c] for r in range(h)]
            info = line_info(cells)
            if info is None:
                continue
            fill_color, step, end = info
            for r in range(0, min(end, h - 1) + 1):
                if r % step == 0:
                    out[r][c] = fill_color

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Find maximal rectangles whose border is a single non-zero colour.
    # In the puzzles these are the small pattern boxes.
    boxes = []
    for r0 in range(h):
        for c0 in range(w):
            border = g[r0, c0]
            if border == 0:
                continue
            r1 = r0
            while r1 + 1 < h and g[r1 + 1, c0] == border:
                r1 += 1
            if r1 == r0:
                continue
            c1 = c0
            while c1 + 1 < w and g[r0, c1 + 1] == border:
                c1 += 1
            if c1 == c0:
                continue
            if r1 - r0 < 2 or c1 - c0 < 2:
                continue
            if not np.all(g[r1, c0:c1 + 1] == border):
                continue
            if not np.all(g[r0:r1 + 1, c1] == border):
                continue
            boxes.append((r0, c0, r1, c1))

    # Keep only boxes that are not contained in a larger box.
    boxes.sort(key=lambda b: (b[2] - b[0], b[3] - b[1]), reverse=True)
    kept = []
    for b in boxes:
        r0, c0, r1, c1 = b
        contained = False
        for k in kept:
            kr0, kc0, kr1, kc1 = k
            if kr0 <= r0 and c0 <= kc0 and r1 <= kr1 and c1 <= kc1:
                contained = True
                break
        if not contained:
            kept.append(b)

    def fix_box(r0, c0, r1, c1):
        sub = g[r0 + 1:r1, c0 + 1:c1]
        if sub.size == 0:
            return
        colors = [c for c in np.unique(sub) if c != 0]
        if len(colors) < 2:
            return

        # The separator/background colour is the one that also appears on the
        # box border in the examples; otherwise use the most common colour.
        border_col = g[r0, c0]
        if border_col in colors:
            sep = border_col
        else:
            vals, cnts = np.unique(sub, return_counts=True)
            sep = int(vals[np.argmax(cnts)])

        fill_colors = [c for c in colors if c != sep]
        if not fill_colors:
            return

        # For each fill colour, try all small horizontal periods and phases.
        # A valid pattern must explain almost all cells of that colour.
        best = None
        for fc in fill_colors:
            mask = (sub == fc)
            total = int(mask.sum())
            if total == 0:
                continue
            max_p = min(sub.shape[1], 8)
            for p in range(1, max_p + 1):
                for ph in range(p):
                    # expected fill positions: (col - ph) % p == 0
                    cols = np.arange(sub.shape[1])
                    expected = ((cols - ph) % p == 0)
                    expected = np.tile(expected, (sub.shape[0], 1))
                    # A cell is explained if it is fill where expected,
                    # or separator where not expected.
                    explained = (expected & mask) | (~expected & (sub == sep))
                    score = int(explained.sum())
                    # Require a strong majority; prefer smaller periods.
                    if score * 10 >= sub.size * 9:
                        cand = (score, -p, ph, fc)
                        if best is None or cand > best:
                            best = cand

        if best is None:
            return

        _, neg_p, ph, fc = best
        p = -neg_p
        cols = np.arange(sub.shape[1])
        expected = ((cols - ph) % p == 0)
        expected = np.tile(expected, (sub.shape[0], 1))

        new_sub = sub.copy()
        new_sub[expected] = fc
        new_sub[~expected] = sep
        out[r0 + 1:r1, c0 + 1:c1] = new_sub

    for b in kept:
        fix_box(*b)

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import Counter

    g = np.array(grid, dtype=int)
    H, W = g.shape
    out = g.copy()

    # Background is the colour on the outer border.
    border_vals = np.concatenate([
        g[0, :], g[-1, :], g[:, 0], g[:, -1]
    ])
    bg = int(Counter(border_vals.tolist()).most_common(1)[0][0])

    # Find rectangular frames: uniform non-background border, interior
    # containing only the background and one pattern colour.
    boxes = []
    for r0 in range(H):
        for c0 in range(W):
            f = g[r0, c0]
            if f == bg:
                continue
            r1 = r0
            while r1 + 1 < H and g[r1 + 1, c0] == f:
                r1 += 1
            if r1 <= r0 + 1:
                continue
            c1 = c0
            while c1 + 1 < W and g[r0, c1 + 1] == f:
                c1 += 1
            if c1 <= c0 + 1:
                continue
            if not np.all(g[r1, c0:c1 + 1] == f):
                continue
            if not np.all(g[r0:r1 + 1, c1] == f):
                continue

            inner = g[r0 + 1:r1, c0 + 1:c1]
            if inner.size == 0:
                continue
            vals = set(np.unique(inner).tolist())
            if f in vals:
                continue
            if bg not in vals:
                continue
            non_bg = [v for v in vals if v != bg]
            if len(non_bg) > 1:
                continue
            boxes.append((r0, c0, r1, c1))

    # Keep only maximal frames.
    boxes.sort(key=lambda b: (b[2] - b[0]) * (b[3] - b[1]), reverse=True)
    kept = []
    for b in boxes:
        r0, c0, r1, c1 = b
        contained = False
        for k in kept:
            kr0, kc0, kr1, kc1 = k
            if kr0 <= r0 and kc0 <= c0 and r1 <= kr1 and c1 <= kc1:
                contained = True
                break
        if not contained:
            kept.append(b)

    def best_periodic_pattern(inner: np.ndarray, bg: int):
        """Return the clean two-colour periodic pattern for one frame interior."""
        h, w = inner.shape
        if h == 0 or w == 0:
            return inner.copy()

        vals = set(np.unique(inner).tolist())
        if bg not in vals:
            return inner.copy()
        non_bg = [v for v in vals if v != bg]
        if not non_bg:
            return np.full_like(inner, bg)
        if len(non_bg) > 1:
            # Fallback: use the most common non-background colour.
            cnt = Counter(inner.tolist())
            pat = max(non_bg, key=lambda x: cnt.get(x, 0))
        else:
            pat = non_bg[0]

        # Binary matrix: 1 = pattern colour, 0 = background.
        a = (inner == pat).astype(int)

        # Search small periods.  The intended patterns in these puzzles are
        # compact; larger periods are only used as a fallback.
        max_pr = min(h, 8)
        max_pc = min(w, 8)

        best_score = -1
        best_key = None
        best_tile = None

        for pr in range(1, max_pr + 1):
            for pc in range(1, max_pc + 1):
                # Try all phases.  Phase (0,0) is preferred on ties.
                for ro in range(pr):
                    for co in range(pc):
                        counts = np.zeros((pr, pc), dtype=int)
                        total = np.zeros((pr, pc), dtype=int)
                        for r in range(h):
                            i = (r - ro) % pr
                            row = a[r]
                            for c in range(w):
                                j = (c - co) % pc
                                total[i, j] += 1
                                counts[i, j] += row[c]
                        score = int(np.sum(np.maximum(counts, total - counts)))
                        # Prefer higher score, then simpler period, then phase 0.
                        key = (score, -pr * pc, -pr, -pc, ro == 0, co == 0)
                        if key > best_key:
                            best_score = score
                            best_key = key
                            tile = (counts * 2 >= total).astype(int)
                            best_tile = tile

        # Fallback: if no small period was found, use the whole interior.
        if best_tile is None:
            best_tile = a.copy()

        # Repeat the chosen tile over the whole interior.
        th, tw = best_tile.shape
        reps_h = (h + th - 1) // th
        reps_w = (w + tw - 1) // tw
        repeated = np.tile(best_tile, (reps_h, reps_w))[:h, :w]
        return np.where(repeated == 1, pat, bg).astype(int)

    for r0, c0, r1, c1 in kept:
        inner = g[r0 + 1:r1, c0 + 1:c1]
        fixed = best_periodic_pattern(inner, bg)
        out[r0 + 1:r1, c0 + 1:c1] = fixed

    return out.tolist()

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Background is 3.  The "wire" is made of 1s.
    # Find the connected component of 1s that is adjacent to the 0-object.
    zero_cells = [(r, c) for r in range(h) for c in range(w) if g[r, c] == 0]
    if not zero_cells:
        return g.tolist()

    # 4-connected component of 1s touching any 0 cell.
    start = None
    for r, c in zero_cells:
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and g[nr, nc] == 1:
                start = (nr, nc)
                break
        if start is not None:
            break

    if start is None:
        return g.tolist()

    comp = np.zeros((h, w), dtype=bool)
    stack = [start]
    comp[start] = True
    while stack:
        r, c = stack.pop()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and not comp[nr, nc] and g[nr, nc] == 1:
                comp[nr, nc] = True
                stack.append((nr, nc))

    # Candidate target cells:
    # - any 2 cell adjacent to the 1-component, or
    # - any 1 cell in the component that is a "terminal lobe"
    #   (a 2x2 block of 1s with only one 1-neighbor outside the block).
    candidates = set()

    # 2-cells adjacent to the component.
    for r in range(h):
        for c in range(w):
            if g[r, c] == 2:
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and comp[nr, nc]:
                        candidates.add((r, c))
                        break

    # Terminal 1-lobes: 2x2 blocks of 1s with exactly one external 1-neighbor.
    for r in range(h - 1):
        for c in range(w - 1):
            if all(comp[r + dr, c + dc] for dr in (0, 1) for dc in (0, 1)):
                outside = 0
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < h and 0 <= nc < w and comp[nr, nc]:
                            if not (r <= nr < r + 2 and c <= nc < c + 2):
                                outside += 1
                if outside == 1:
                    for dr in (0, 1):
                        for dc in (0, 1):
                            candidates.add((r + dr, c + dc))

    if not candidates:
        return g.tolist()

    # Distance from the 0-object to each candidate through the 1-component.
    # BFS over 1-cells, with distance to a candidate = distance to its adjacent 1-cell.
    from collections import deque

    # Seed BFS with all 1-cells adjacent to any 0 cell.
    dist = {}
    q = deque()
    for r, c in zero_cells:
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and comp[nr, nc] and (nr, nc) not in dist:
                dist[(nr, nc)] = 0
                q.append((nr, nc))

    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and comp[nr, nc] and (nr, nc) not in dist:
                dist[(nr, nc)] = dist[(r, c)] + 1
                q.append((nr, nc))

    best = None
    best_d = None
    for cell in candidates:
        r, c = cell
        d = None
        if g[r, c] == 2:
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and comp[nr, nc] and (nr, nc) in dist:
                    dd = dist[(nr, nc)] + 1
                    if d is None or dd < d:
                        d = dd
        else:  # 1-cell terminal lobe
            if (r, c) in dist:
                d = dist[(r, c)]
        if d is not None and (best_d is None or d < best_d):
            best_d = d
            best = cell

    if best is None:
        return g.tolist()

    out = g.copy()

    # Original 0-object becomes 1.
    for r, c in zero_cells:
        out[r, c] = 1

    # Target becomes 0.  If target is a 1-lobe, recolor the whole terminal lobe.
    if g[best[0], best[1]] == 2:
        out[best] = 0
    else:
        r, c = best
        # Recolor the 2x2 terminal lobe containing this cell.
        for rr in (r - 1, r):
            for cc in (c - 1, c):
                if 0 <= rr < h and 0 <= cc < w and comp[rr, cc] and g[rr, cc] == 1:
                    # Only include cells in the same terminal 2x2 block.
                    if (rr, cc) in candidates:
                        out[rr, cc] = 0

    return out.tolist()

import numpy as np
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Find the 0-object. It is a solid rectangle in the examples.
    zeros = [(r, c) for r in range(h) for c in range(w) if g[r, c] == 0]
    if not zeros:
        return g.tolist()

    r0 = min(r for r, c in zeros)
    r1 = max(r for r, c in zeros)
    c0 = min(c for r, c in zeros)
    c1 = max(c for r, c in zeros)
    sh = r1 - r0 + 1
    sw = c1 - c0 + 1

    # A destination block of the same size is valid if every cell is 1 or 2.
    # The 0-object can move from one valid block to another if the two blocks
    # overlap by at least one cell (i.e. their top-left positions differ by
    # at most 1 in both coordinates, and are not identical).
    def valid_block(r, c):
        if r < 0 or c < 0 or r + sh > h or c + sw > w:
            return False
        for rr in range(r, r + sh):
            for cc in range(c, c + sw):
                if g[rr, cc] not in (1, 2):
                    return False
        return True

    # The starting block is valid if we treat its 0-cells as passable.
    def start_valid(r, c):
        if r < 0 or c < 0 or r + sh > h or c + sw > w:
            return False
        for rr in range(r, r + sh):
            for cc in range(c, c + sw):
                if g[rr, cc] not in (0, 1, 2):
                    return False
        return True

    # BFS over all valid destination blocks, seeded by the starting block.
    # Distance is the number of block moves from the start.
    dist = {}
    q = deque()

    if start_valid(r0, c0):
        dist[(r0, c0)] = 0
        q.append((r0, c0))

    while q:
        r, c = q.popleft()
        d = dist[(r, c)]
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if (nr, nc) in dist:
                    continue
                if not valid_block(nr, nc):
                    continue
                # Ensure the two blocks overlap (movement by at most one cell).
                if max(r, nr) < min(r + sh, nr + sh) and max(c, nc) < min(c + sw, nc + sw):
                    dist[(nr, nc)] = d + 1
                    q.append((nr, nc))

    if not dist:
        return g.tolist()

    # Choose the farthest reachable block. Ties are broken by preferring 2s,
    # then by lexicographic order for determinism.
    best = None
    best_key = None
    for (r, c), d in dist.items():
        has_two = any(g[rr, cc] == 2 for rr in range(r, r + sh) for cc in range(c, c + sw))
        key = (d, has_two, -r, -c)
        if best_key is None or key > best_key:
            best_key = key
            best = (r, c)

    out = g.copy()

    # Original 0-object becomes 1.
    for rr in range(r0, r0 + sh):
        for cc in range(c0, c0 + sw):
            out[rr, cc] = 1

    # Destination becomes 0.
    br, bc = best
    for rr in range(br, br + sh):
        for cc in range(bc, bc + sw):
            out[rr, cc] = 0

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import Counter

    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Background is the most frequent colour.
    bg = Counter(g.ravel()).most_common(1)[0][0]

    # Connected components of non-background cells (4-connected).
    seen = np.zeros((H, W), dtype=bool)
    comps = []
    for r in range(H):
        for c in range(W):
            if not seen[r, c] and g[r, c] != bg:
                stack = [(r, c)]
                seen[r, c] = True
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < H and 0 <= nx < W and not seen[ny, nx] and g[ny, nx] != bg:
                            seen[ny, nx] = True
                            stack.append((ny, nx))
                comps.append(cells)

    if not comps:
        return [[int(x) for x in row] for row in g]

    # For each component, find the 3x3 sub-block that best looks like a tile:
    # exactly two colours, one of which is a small accent cluster.
    def score_block(block):
        vals = set(block.ravel())
        if len(vals) != 2:
            return -1
        a, b = vals
        ca = int((block == a).sum())
        cb = int((block == b).sum())
        # Prefer the smaller colour to be the accent (1-4 cells).
        if min(ca, cb) < 1 or min(ca, cb) > 4:
            return -1
        # Prefer blocks where the accent is connected and near a corner.
        accent = a if ca < cb else b
        mask = (block == accent)
        ys, xs = np.where(mask)
        if len(ys) == 0:
            return -1
        # Connectedness of accent
        acc = 0
        for y, x in zip(ys, xs):
            for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                ny, nx = y + dy, x + dx
                if 0 <= ny < 3 and 0 <= nx < 3 and mask[ny, nx]:
                    acc += 1
        # Corner bias: accent cells closer to a corner are better.
        corner = min(min(y, 2 - y) + min(x, 2 - x) for y, x in zip(ys, xs))
        return (acc, -corner, -min(ca, cb))

    tiles = []
    for cells in comps:
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        r0, r1 = min(rs), max(rs)
        c0, c1 = min(cs), max(cs)
        best = None
        best_score = None
        for rr in range(r0, r1 - 2 + 1):
            for cc in range(c0, c1 - 2 + 1):
                block = g[rr:rr + 3, cc:cc + 3]
                s = score_block(block)
                if s is not None and (best_score is None or s > best_score):
                    best_score = s
                    best = (rr, cc, block.copy())
        if best is not None:
            tiles.append(best)

    if not tiles:
        return [[int(x) for x in row] for row in g]

    # Determine a 2D layout for the tiles.
    # Use their original component centres, quantised into rows/columns.
    centres = []
    for rr, cc, block in tiles:
        # Centre of the component that produced this tile.
        cells = None
        for comp in comps:
            rs = [r for r, c in comp]
            cs = [c for r, c in comp]
            if min(rs) <= rr <= max(rs) and min(cs) <= cc <= max(cs):
                cells = comp
                break
        if cells is None:
            cells = [(rr, cc)]
        cy = sum(r for r, c in cells) / len(cells)
        cx = sum(c for r, c in cells) / len(cells)
        centres.append((cy, cx, rr, cc, block))

    def cluster_values(vals, tol=2.5):
        vals = sorted(vals)
        groups = []
        cur = [vals[0]]
        for v in vals[1:]:
            if v - cur[-1] <= tol:
                cur.append(v)
            else:
                groups.append(sum(cur) / len(cur))
                cur = [v]
        groups.append(sum(cur) / len(cur))
        return groups

    row_groups = cluster_values([cy for cy, cx, _, _, _ in centres])
    col_groups = cluster_values([cx for cy, cx, _, _, _ in centres])

    def group_index(val, groups):
        return min(range(len(groups)), key=lambda i: abs(groups[i] - val))

    layout = {}
    for cy, cx, rr, cc, block in centres:
        layout[(group_index(cy, row_groups), group_index(cx, col_groups))] = block

    max_r = max(r for r, c in layout)
    max_c = max(c for r, c in layout)

    out = np.zeros(((max_r + 1) * 3, (max_c + 1) * 3), dtype=int)
    for (ri, ci), block in layout.items():
        out[ri * 3:(ri + 1) * 3, ci * 3:(ci + 1) * 3] = block

    return [[int(x) for x in row] for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import Counter

    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Background is the most frequent colour.
    bg = Counter(g.ravel()).most_common(1)[0][0]

    # A valid 3x3 tile contains no background and exactly two colours.
    # The less frequent colour is the accent and should be small (1..4 cells).
    def tile_score(block):
        if (block == bg).any():
            return None
        vals, counts = np.unique(block, return_counts=True)
        if len(vals) != 2:
            return None
        a, b = vals
        ca, cb = int(counts[0]), int(counts[1])
        if min(ca, cb) < 1 or min(ca, cb) > 4:
            return None

        # Prefer the accent to be connected and close to a corner.
        accent = a if ca < cb else b
        mask = (block == accent)
        ys, xs = np.where(mask)
        if len(ys) == 0:
            return None

        connected = 0
        for y, x in zip(ys, xs):
            for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                ny, nx = y + dy, x + dx
                if 0 <= ny < 3 and 0 <= nx < 3 and mask[ny, nx]:
                    connected += 1

        corner = min(min(y, 2 - y) + min(x, 2 - x) for y, x in zip(ys, xs))
        return (connected, -corner, -min(ca, cb))

    # Find all candidate 3x3 tiles.
    candidates = []
    for r in range(H - 2):
        for c in range(W - 2):
            block = g[r:r + 3, c:c + 3]
            score = tile_score(block)
            if score is not None:
                candidates.append((r, c, block.copy(), score))

    if not candidates:
        return [[int(x) for x in row] for row in g]

    # Keep a consistent set of tiles:
    # 1) remove candidates that are clearly worse than another candidate
    #    overlapping them in a 3x3 neighbourhood;
    # 2) cluster remaining candidates into a rectangular macro grid.
    def overlaps(a, b):
        ar, ac = a[0], a[1]
        br, bc = b[0], b[1]
        return abs(ar - br) < 3 and abs(ac - bc) < 3

    # Sort by score descending, then position for determinism.
    candidates.sort(key=lambda x: (x[3], x[0], x[1]), reverse=True)

    kept = []
    for cand in candidates:
        # If a better candidate overlaps this one, discard this one.
        if any(overlaps(cand, k) and k[3] > cand[3] for k in kept):
            continue
        kept.append(cand)

    # If too many overlapping candidates remain, keep only the best in each
    # 3x3 neighbourhood.
    final = []
    for cand in kept:
        if any(overlaps(cand, k) for k in final):
            continue
        final.append(cand)

    if not final:
        return [[int(x) for x in row] for row in g]

    # Cluster tile top-left coordinates into macro rows and columns.
    def cluster_values(vals, tol=2.5):
        vals = sorted(vals)
        groups = []
        cur = [vals[0]]
        for v in vals[1:]:
            if v - cur[-1] <= tol:
                cur.append(v)
            else:
                groups.append(sum(cur) / len(cur))
                cur = [v]
        groups.append(sum(cur) / len(cur))
        return groups

    row_groups = cluster_values([r for r, c, _, _ in final])
    col_groups = cluster_values([c for r, c, _, _ in final])

    def group_index(val, groups):
        return min(range(len(groups)), key=lambda i: abs(groups[i] - val))

    layout = {}
    for r, c, block, _ in final:
        layout[(group_index(r, row_groups), group_index(c, col_groups))] = block

    max_r = max(r for r, c in layout)
    max_c = max(c for r, c in layout)

    # Output is the transposed macro grid of 3x3 tiles.
    out = np.zeros(((max_c + 1) * 3, (max_r + 1) * 3), dtype=int)
    for (ri, ci), block in layout.items():
        out[ci * 3:(ci + 1) * 3, ri * 3:(ri + 1) * 3] = block

    return [[int(x) for x in row] for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Background is the most common colour.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # The main object is the largest connected component of non-background cells.
    nonbg = g != bg
    seen = np.zeros_like(nonbg, dtype=bool)
    best = None
    best_size = -1

    for r in range(H):
        for c in range(W):
            if nonbg[r, c] and not seen[r, c]:
                stack = [(r, c)]
                seen[r, c] = True
                comp = []
                while stack:
                    y, x = stack.pop()
                    comp.append((y, x))
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < H and 0 <= nx < W:
                                if nonbg[ny, nx] and not seen[ny, nx]:
                                    seen[ny, nx] = True
                                    stack.append((ny, nx))
                if len(comp) > best_size:
                    best_size = len(comp)
                    best = comp

    if best is None:
        return [list(row) for row in g]

    ys = [p[0] for p in best]
    xs = [p[1] for p in best]
    r0, r1 = min(ys), max(ys)
    c0, c1 = min(xs), max(xs)
    h = r1 - r0 + 1
    w = c1 - c0 + 1

    # Extract the main shape and its colour.
    shape = np.zeros((h, w), dtype=int)
    for y, x in best:
        shape[y - r0, x - c0] = 1
    main_color = int(g[r0, c0])

    # Marker pixels are all non-background pixels outside the main object.
    markers = []
    for r in range(H):
        for c in range(W):
            if g[r, c] != bg and (r, c) not in set(best):
                markers.append((r, c, int(g[r, c])))

    # If there are no markers, nothing changes.
    if not markers:
        return [list(row) for row in g]

    # The marker pattern is translated so that its centre aligns with the
    # centre of the main object.
    mr = sum(p[0] for p in markers) / len(markers)
    mc = sum(p[1] for p in markers) / len(markers)
    or_ = (r0 + r1) / 2.0
    oc = (c0 + c1) / 2.0
    dr = int(round(or_ - mr))
    dc = int(round(oc - mc))

    out = g.copy()

    # Draw the marker pattern using the main shape as a brush.
    # The marker colour determines the brush colour; the main object colour
    # is used for the central marker.
    for r, c, col in markers:
        nr, nc = r + dr, c + dc
        brush_color = main_color if col == main_color else col
        for i in range(h):
            for j in range(w):
                if shape[i, j]:
                    rr, cc = nr + i, nc + j
                    if 0 <= rr < H and 0 <= cc < W:
                        out[rr, cc] = brush_color

    # Move the original main object to the top of the grid, keeping its colour.
    for i in range(h):
        for j in range(w):
            if shape[i, j]:
                out[i, j] = main_color

    return [list(row) for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    # Normalize input to a plain list of lists of Python ints.
    if isinstance(grid[0], str):
        g = [[int(ch) for ch in row] for row in grid]
