    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    def is_solid(r, c, color):
        if r < 0 or c < 0 or r + 3 > h or c + 3 > w:
            return False
        return bool(np.all(g[r:r + 3, c:c + 3] == color))

    def is_empty(r, c):
        if r < 0 or c < 0 or r + 3 > h or c + 3 > w:
            return False
        return bool(np.all(g[r:r + 3, c:c + 3] == 0))

    def set_plus(r, c, color):
        out[r + 1, c] = color
        out[r, c + 1] = color
        out[r, c + 2] = color
        out[r + 2, c + 1] = color

    # Convert every solid 3x3 colored block into a plus pattern.
    for r in range(h - 2):
        for c in range(w - 2):
            if is_solid(r, c, 0):
                continue
            color = g[r, c]
            if is_solid(r, c, color):
                set_plus(r, c, color)

    # Find empty 3x3 slots that are directly below a vertical 8-stem.
    # The stem is a column of 8s ending just above the slot.
    slots = []
    for r in range(h - 2):
        for c in range(w - 2):
            if not is_empty(r, c):
                continue
            if r == 0:
                continue
            col = c + 1
            if g[r - 1, col] != 8:
                continue
            length = 0
            rr = r - 1
            while rr >= 0 and g[rr, col] == 8:
                length += 1
                rr -= 1
            if length >= 2:
                slots.append((r, c))

    # Collect solid colors from top to bottom, left to right.
    solid_colors = []
    for r in range(h - 2):
        for c in range(w - 2):
            if is_solid(r, c, 0):
                continue
            color = g[r, c]
            if is_solid(r, c, color):
                solid_colors.append(color)

    # Fill empty slots with the solid colors in the same order.
    for (r, c), color in zip(slots, solid_colors):
        set_plus(r, c, color)

    return out.tolist()

