def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Find all solid rectangular borders (top/bottom rows and left/right columns
    # of the same non-zero colour, with a non-empty interior).
    rects = []
    for r in range(h):
        for c in range(w):
            col = g[r, c]
            if col == 0:
                continue
            # bottom row
            r2 = r + 1
            while r2 < h and np.all(g[r2, c:c + 1] == col):
                r2 += 1
            if r2 >= h:
                continue
            if not np.all(g[r2, c] == col):
                continue
