    target = max(rects, key=lambda x: (x[2] - x[0] + 1) * (x[3] - x[1] + 1))
    tr, tc, tr2, tc2, tcol = target

    # Source rectangle: the other rectangle with the largest area.
    source = max(
        (r for r in rects if r != target),
        key=lambda x: (x[2] - x[0] + 1) * (x[3] - x[1] + 1),
        default=None,
    )

    out = g[tr:tr2 + 1, tc:tc2 + 1].copy()

    if source is not None:
        sr, sc, sr2, sc2, scol = source
        src = g[sr:sr2 + 1, sc:sc2 + 1]

        # Collect non-background, non-border pixels from the source rectangle.
        marks = []
        for i in range(src.shape[0]):
            for j in range(src.shape[1]):
                v = src[i, j]
                if v != 0 and v != scol:
                    marks.append((i, j, int(v)))

        # For each mark, place a 3x3 pattern in the target rectangle:
        #   x . x
        #   x x x
        #   . v .
        # where v is the source mark value.
        for i, j, v in marks:
            for di, dj in [(-1, -1), (-1, 1),
                           (0, -1), (0, 0), (0, 1),
                           (1, -1), (1, 1)]:
                ni, nj = i + di, j + dj
                if 0 <= ni < out.shape[0] and 0 <= nj < out.shape[1]:
                    out[ni, nj] = v
            ni, nj = i + 1, j
            if 0 <= ni < out.shape[0] and 0 <= nj < out.shape[1]:
                out[ni, nj] = v

    return [list(row) for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    H, W = g.shape

    # background is the most frequent colour
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # connected components of non-background cells (4-connectivity)
    seen = np.zeros((H, W), dtype=bool)
    comps = []
    for r in range(H):
        for c in range(W):
            if g[r, c] != bg and not seen[r, c]:
                color = int(g[r, c])
                q = deque([(r, c)])
                seen[r, c] = True
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < H and 0 <= nx < W:
                            if not seen[ny, nx] and g[ny, nx] == color:
                                seen[ny, nx] = True
                                q.append((ny, nx))
                comps.append((color, cells))

    if not comps:
        return [list(row) for row in g]

    # If there is only one component, nothing to combine.
    if len(comps) == 1:
        return [list(row) for row in g]

    # Choose the component with the largest bounding-box area as the base.
    def bbox(cells):
        ys = [p[0] for p in cells]
        xs = [p[1] for p in cells]
        return min(ys), max(ys), min(xs), max(xs)

    def bbox_area(cells):
        r0, r1, c0, c1 = bbox(cells)
        return (r1 - r0 + 1) * (c1 - c0 + 1)

    base_idx = max(range(len(comps)), key=lambda i: bbox_area(comps[i][1]))
    base_color, base_cells = comps[base_idx]
    base_set = set(base_cells)
    r0, r1, c0, c1 = bbox(base_cells)
    bh, bw = r1 - r0 + 1, c1 - c0 + 1

    # Empty cells inside the base bounding box.
    holes = [(r, c) for r in range(r0, r1 + 1) for c in range(c0, c1 + 1)
             if (r, c) not in base_set]

    def norm(cells):
        r0 = min(r for r, _ in cells)
        c0 = min(c for _, c in cells)
        return frozenset((r - r0, c - c0) for r, c in cells)

    def rotations(cells):
        n = norm(cells)
        res = [n]
        for _ in range(3):
            n = frozenset((c, -r) for r, c in n)
            res.append(n)
        return res

    # Find a non-base component whose shape (possibly rotated) exactly fills the holes.
    filler = None
    filler_rot = None
    for i, (color, cells) in enumerate(comps):
        if i == base_idx:
            continue
        hole_norm = norm(holes)
        for rot in rotations(cells):
            if rot == hole_norm:
                filler = (color, cells)
                filler_rot = rot
                break
        if filler:
            break

    out = g.copy()

    if filler is not None:
        fcolor, fcells = filler
        # Place the filler into the base's holes.
        # Determine the translation that maps the rotated filler to the holes.
        hole_norm = norm(holes)
        # Build a canonical mapping from normalized coordinates to actual hole cells.
        hr0 = min(r for r, _ in holes)
        hc0 = min(c for _, c in holes)
        hole_map = {}
        for r, c in holes:
            hole_map[(r - hr0, c - hc0)] = (r, c)

        # Find a rotation of filler whose normalized set equals hole_norm.
        for rot in rotations(fcells):
            if rot == hole_norm:
                # Map each normalized filler cell to the corresponding hole cell.
                for nr, nc in rot:
                    out[hole_map[(nr, nc)]] = fcolor
                break

        # Remove the filler from its original location.
        for r, c in fcells:
            out[r, c] = bg

        # Move every other non-base component so that it keeps the same
        # relative position to the filler's original top-left bounding box,
        # now relative to the filler's new top-left bounding box.
        old_fr0, old_fc0 = bbox(fcells)[0], bbox(fcells)[2]
        new_fr0, new_fc0 = hr0, hc0
        dr = new_fr0 - old_fr0
        dc = new_fc0 - old_fc0

        for i, (color, cells) in enumerate(comps):
            if i == base_idx or (color, cells) == filler:
                continue
            # Clear original cells.
            for r, c in cells:
                out[r, c] = bg
            # Shift by the same delta.
            for r, c in cells:
                nr, nc = r + dr, c + dc
                if 0 <= nr < H and 0 <= nc < W:
                    out[nr, nc] = color
    else:
        # Fallback: no exact hole match.  Move all non-base components toward
        # the base bounding box by the same vector that aligns their top-left
        # corners with the base top-left corner.  This is not expected for the
        # supplied ARC cases, but keeps the function total.
        for i, (color, cells) in enumerate(comps):
            if i == base_idx:
                continue
            fr0, fc0 = bbox(cells)[0], bbox(cells)[2]
            dr = r0 - fr0
            dc = c0 - fc0
            for r, c in cells:
                out[r, c] = bg
            for r, c in cells:
                nr, nc = r + dr, c + dc
                if 0 <= nr < H and 0 <= nc < W:
                    out[nr, nc] = color

    return [list(row) for row in out]

