import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Find the vertical separator: column with the strongest vertical run of one non-zero colour.
    best_col = -1
    best_color = 0
    best_count = 0

    for c in range(w):
        col = g[:, c]
        for color in range(1, 10):
            count = int(np.sum(col == color))
            if count > best_count:
                best_count = count
                best_col = c
                best_color = color

    if best_col == -1:
        return out.tolist()

    sep = best_col

    # Decide which side contains the source patterns.
    left_count = int(np.sum(g[:, :sep] != 0))
    right_count = int(np.sum(g[:, sep + 1:] != 0))

    if left_count == 0 and right_count == 0:
        return out.tolist()

    source_left = left_count >= right_count

    # Target side width.
    if source_left:
        target_width = w - sep - 1
    else:
        target_width = sep

    for r in range(h):
        runs = []

        if source_left:
            # Scan from the separator outward to the left.
            c = sep - 1
            while c >= 0:
                if g[r, c] == 0:
                    c -= 1
                    continue
                color = g[r, c]
                start = c
                while c >= 0 and g[r, c] == color:
                    c -= 1
                end = start
                length = end - c
                # Distance of the run's nearest cell to the separator.
                distance = sep - end
                runs.append((distance, length, color))
        else:
            # Scan from the separator outward to the right.
            c = sep + 1
            while c < w:
                if g[r, c] == 0:
                    c += 1
                    continue
                color = g[r, c]
                start = c
                while c < w and g[r, c] == color:
                    c += 1
                end = c - 1
                length = end - start + 1
                distance = start - sep
                runs.append((distance, length, color))

        # Nearer runs are drawn first; later runs only fill still-empty cells.
        runs.sort(key=lambda x: x[0])

        for _, length, color in runs:
            for d in range(1, target_width + 1):
                if (d - 1) % length != 0:
                    continue

                if source_left:
                    tc = sep + d
                else:
                    tc = sep - d

                if 0 <= tc < w and out[r, tc] == 0:
                    out[r, tc] = color

    return out.tolist()

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape

    # The separator is the vertical line of 4s.
    sep_col = None
    for c in range(w):
        if np.all(g[:, c] == 4):
            sep_col = c
            break
    if sep_col is None:
        sep_col = w // 2

    out = np.zeros((h, sep_col), dtype=int)

    # Copy the single 5 from the right side to the output.
    for r in range(h):
        for c in range(sep_col + 1, w):
            if g[r, c] == 5:
                out[r, c - sep_col - 1] = 5

    # Find the starting point of the path.
    start_r, start_c = 0, 0
    found_start = False
    for r in range(h):
        for c in range(sep_col):
            if out[r, c] == 5:
                start_r, start_c = r, c
                found_start = True
                break
        if found_start:
            break

    # Identify 3x3 objects in the left part.
    objects = []
    for r in range(0, h - 2, 4):
        for c in (0, 4):
            block = g[r:r + 3, c:c + 3]
            color = 0
            for val in block.flat:
                if val != 0:
                    color = int(val)
                    break
            if color != 0:
                objects.append((r, c, color))

    # Process left column top-to-bottom, then right column top-to-bottom.
    left = [o for o in objects if o[1] == 0]
    right = [o for o in objects if o[1] == 4]
    left.sort(key=lambda x: x[0])
    right.sort(key=lambda x: x[0])
    ordered = left + right

    # Shape/direction encoded by each object color.
    # (orientation, length, direction)
    # H: horizontal, V: vertical; R: extend right, L: extend left, D: extend down.
    spec = {
        1: ('H', 3, 'R'),
        2: ('H', 2, 'L'),
        3: ('H', 4, 'L'),
        6: ('V', 2, 'D'),
    }

    er, ec = start_r, start_c

    for _, _, color in ordered:
        if color not in spec:
            continue
        orient, length, direction = spec[color]

        if orient == 'V':
            for i in range(length):
                rr = er + 1 + i
                if 0 <= rr < h and 0 <= ec < sep_col:
                    out[rr, ec] = color
            er = er + length
            # ec unchanged
        else:
            rr = er + 1
            if direction == 'R':
                for i in range(length):
                    cc = ec + i
                    if 0 <= rr < h and 0 <= cc < sep_col:
                        out[rr, cc] = color
                ec = ec + length - 1
            else:  # 'L'
                for i in range(length):
                    cc = ec - i
                    if 0 <= rr < h and 0 <= cc < sep_col:
                        out[rr, cc] = color
                ec = ec - length + 1
            er = rr

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return [row[:] for row in grid]

    h = len(grid)
    w = len(grid[0])
    out = [row[:] for row in grid]

    # Find the vertical separator: a column that is constant and non-zero.
    sep_col = -1
    sep_color = 0
    for c in range(w):
        col_val = grid[0][c]
        if col_val == 0:
            continue
        if all(grid[r][c] == col_val for r in range(h)):
            sep_col = c
            sep_color = col_val
            break

    # Fallback: most common full non-zero column, if any.
    if sep_col == -1:
        best_count = 0
        for c in range(w):
            vals = [grid[r][c] for r in range(h)]
            if vals[0] == 0:
                continue
            if all(v == vals[0] for v in vals):
                # already handled, but keep for safety
                sep_col = c
                sep_color = vals[0]
                break

    if sep_col == -1:
        return out

    def source_info(row, side):
        """
        side = 'left' or 'right'.
        Scan outward from the separator on that side.
        Return (color, run_length) for the first non-zero cell and its
        contiguous same-color run, or None if no non-zero cell exists.
        """
        if side == 'left':
            for i in range(sep_col - 1, -1, -1):
                v = row[i]
                if v != 0:
                    color = v
                    length = 1
                    j = i - 1
                    while j >= 0 and row[j] == color:
                        length += 1
                        j -= 1
                    return color, length
            return None
        else:
            for i in range(sep_col + 1, w):
                v = row[i]
                if v != 0:
                    color = v
                    length = 1
                    j = i + 1
                    while j < w and row[j] == color:
                        length += 1
                        j += 1
                    return color, length
            return None

    def has_nonzero(row, side):
        if side == 'left':
            return any(v != 0 for v in row[:sep_col])
        else:
            return any(v != 0 for v in row[sep_col + 1:])

    # Determine the global source side from the examples/test layout:
    # the side that contains the input blocks.
    left_rows = sum(1 for r in range(h) if has_nonzero(grid[r], 'left'))
    right_rows = sum(1 for r in range(h) if has_nonzero(grid[r], 'right'))

    if left_rows >= right_rows and left_rows > 0:
        source_side = 'left'
        target_side = 'right'
    elif right_rows > 0:
        source_side = 'right'
        target_side = 'left'
    else:
        return out

    for r in range(h):
        info = source_info(grid[r], source_side)
        if info is None:
            continue

        color, period = info

        if target_side == 'right':
            # Fill right side: first cell after separator is colored,
            # then repeat every `period` cells.
            for c in range(sep_col + 1, w):
                dist = c - sep_col  # 1-based distance from separator
                out[r][c] = color if (dist - 1) % period == 0 else 0
        else:
            # Fill left side: first cell before separator is colored,
            # then repeat every `period` cells moving left.
            for c in range(0, sep_col):
                dist = sep_col - c  # 1-based distance from separator
                out[r][c] = color if (dist - 1) % period == 0 else 0

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    h = len(grid)
    w = len(grid[0]) if h else 0
    if w == 0:
        return []

    visited = [[False] * w for _ in range(h)]
    hollow = []
    filled = []
    dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or visited[r][c]:
                continue

            color = grid[r][c]
            stack = [(r, c)]
            visited[r][c] = True
            cells = []

            while stack:
                cr, cc = stack.pop()
                cells.append((cr, cc))

                for dr, dc in dirs:
                    nr, nc = cr + dr, cc + dc
                    if (
                        0 <= nr < h
                        and 0 <= nc < w
                        and not visited[nr][nc]
                        and grid[nr][nc] == color
                    ):
                        visited[nr][nc] = True
                        stack.append((nr, nc))

            rmin = min(r for r, _ in cells)
            rmax = max(r for r, _ in cells)
            cmin = min(c for _, c in cells)
            cmax = max(c for _, c in cells)

            if rmax - rmin + 1 == 4 and cmax - cmin + 1 == 4:
                block = [
                    [int(grid[rmin + i][cmin + j]) for j in range(4)]
                    for i in range(4)
                ]

                is_hollow = any(
                    grid[rmin + i][cmin + j] != color
                    for i in range(4)
                    for j in range(4)
                )

                if is_hollow:
                    hollow.append((rmin, cmin, block))
                else:
                    filled.append((rmin, cmin, block))

    hollow.sort(key=lambda x: (x[0], x[1]))
    filled.sort(key=lambda x: (x[0], x[1]))

    rows = max(len(hollow), len(filled))
    if rows == 0:
        return []

    zero_block = [[0, 0, 0, 0] for _ in range(4)]
    out = []

    for i in range(rows):
        left = hollow[i][2] if i < len(hollow) else zero_block
        right = filled[i][2] if i < len(filled) else zero_block

        for k in range(4):
            out.append(left[k] + right[k])

    return out

