    if not grid or not grid[0]:
        return [[0]]

    h, w = len(grid), len(grid[0])
    visited = [[False] * w for _ in range(h)]
    blocks = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 and not visited[r][c]:
                stack = [(r, c)]
                visited[r][c] = True

                min_r = max_r = r
                min_c = max_c = c
                count = 0

                while stack:
                    cr, cc = stack.pop()
                    count += 1

