    hollows = [b for b in blocks if not b[3]]
    solids = [b for b in blocks if b[3]]

    hollows.sort(key=lambda b: (b[0], b[1]))
    solids.sort(key=lambda b: (b[0], b[1]))

    max_h = max(len(b[2]) for b in blocks)
    max_w = max(len(row) for b in blocks for row in b[2])

    rows = max(len(hollows), len(solids))
    out = [[0] * (2 * max_w) for _ in range(rows * max_h)]

    def place(sub, r0, c0):
        for i, row in enumerate(sub):
            for j, val in enumerate(row):
                out[r0 + i][c0 + j] = int(val)

    for i, (_, _, sub, _) in enumerate(hollows):
        place(sub, i * max_h, 0)

    for i, (_, _, sub, _) in enumerate(solids):
        place(sub, i * max_h, max_w)

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    from collections import deque

    # Normalize input to a plain 2D list of ints.
    if not grid:
        return []
    if isinstance(grid[0], str):
        grid = [[int(ch) for ch in row] for row in grid]
    else:
        grid = [[int(v) for v in row] for row in grid]

    h, w = len(grid), len(grid[0])
    visited = [[False] * w for _ in range(h)]
    blocks = []  # (top, left, color, is_hollow)

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or visited[r][c]:
                continue

            color = grid[r][c]
            q = deque([(r, c)])
            visited[r][c] = True

            cells = []
            min_r = max_r = r
            min_c = max_c = c

            while q:
                y, x = q.popleft()
                cells.append((y, x))
                min_r = min(min_r, y)
                max_r = max(max_r, y)
                min_c = min(min_c, x)
                max_c = max(max_c, x)

                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w:
                        if not visited[ny][nx] and grid[ny][nx] == color:
                            visited[ny][nx] = True
                            q.append((ny, nx))

            # Only 4x4 objects are used.
            if max_r - min_r + 1 != 4 or max_c - min_c + 1 != 4:
                continue

            is_solid = True
            is_hollow = True

            for dr in range(4):
                for dc in range(4):
                    val = grid[min_r + dr][min_c + dc]

                    if val != color:
                        is_solid = False

                    if dr in (0, 3) or dc in (0, 3):
                        if val != color:
                            is_hollow = False
                    else:
                        if val != 0:
                            is_hollow = False

            if is_solid:
                blocks.append((min_r, min_c, color, False))
            elif is_hollow:
                blocks.append((min_r, min_c, color, True))

    hollows = [b for b in blocks if b[3]]
    solids = [b for b in blocks if not b[3]]

    # Pair by vertical order within each type.
    hollows.sort(key=lambda b: (b[0], b[1]))
    solids.sort(key=lambda b: (b[0], b[1]))

    n = max(len(hollows), len(solids))
    if n == 0:
        return []

    out = [[0] * 8 for _ in range(4 * n)]

    def block_value(block, dr, dc):
        if block is None:
            return 0
        color = block[2]
        if block[3]:  # hollow
            return color if (dr == 0 or dr == 3 or dc == 0 or dc == 3) else 0
        return color  # solid

    for i in range(n):
        left = hollows[i] if i < len(hollows) else None
        right = solids[i] if i < len(solids) else None

        for dr in range(4):
            for dc in range(4):
                out[4 * i + dr][dc] = block_value(left, dr, dc)
                out[4 * i + dr][4 + dc] = block_value(right, dr, dc)

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])

    # Find the rectangular zero region: bounding box of all 0 cells.
    zero_cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 0]
    if not zero_cells:
        return [row[:] for row in grid]

    r0 = min(r for r, _ in zero_cells)
    r1 = max(r for r, _ in zero_cells) + 1
    c0 = min(c for _, c in zero_cells)
    c1 = max(c for _, c in zero_cells) + 1

    out_h = r1 - r0
    out_w = c1 - c0
    out = [[0] * out_w for _ in range(out_h)]

    # Markers are the non-zero cells inside the zero rectangle.
    markers = []
    for r in range(r0, r1):
        for c in range(c0, c1):
            v = grid[r][c]
            if v != 0:
                markers.append((r - r0, c - c0, v))

    def in_zero_box(r, c):
        return r0 <= r < r1 and c0 <= c < c1

    # Count 8-connected components of each marker colour outside the zero box.
    counts = {}
    for color in {v for _, _, v in markers}:
        seen = set()
        cnt = 0
        for r in range(h):
            for c in range(w):
                if in_zero_box(r, c) or grid[r][c] != color or (r, c) in seen:
                    continue
                cnt += 1
                stack = [(r, c)]
                seen.add((r, c))
                while stack:
                    cr, cc = stack.pop()
                    for dr in (-1, 0, 1):
                        for dc in (-1, 0, 1):
                            if dr == 0 and dc == 0:
                                continue
                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < h and 0 <= nc < w:
                                if not in_zero_box(nr, nc) and grid[nr][nc] == color and (nr, nc) not in seen:
                                    seen.add((nr, nc))
                                    stack.append((nr, nc))
        counts[color] = cnt

    # For each marker, repeat its colour to the right with one-cell gaps.
    for rr, cc, color in markers:
        for k in range(counts[color]):
            nc = cc + 2 * k
            if 0 <= nc < out_w:
                out[rr][nc] = color

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    a = np.array(grid, dtype=int)
    h, w = a.shape

    # Find the zero "screen" as the bounding box of the largest 8-connected zero component.
    zero_mask = (a == 0)
    if not zero_mask.any():
        return []

    best = None
    visited = np.zeros((h, w), dtype=bool)
    for r in range(h):
        for c in range(w):
            if zero_mask[r, c] and not visited[r, c]:
                stack = [(r, c)]
                visited[r, c] = True
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            if dy == 0 and dx == 0:
                                continue
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < h and 0 <= nx < w and zero_mask[ny, nx] and not visited[ny, nx]:
                                visited[ny, nx] = True
                                stack.append((ny, nx))
                if best is None or len(cells) > len(best):
                    best = cells

    if best is None:
        return []

    ys = [p[0] for p in best]
    xs = [p[1] for p in best]
    r0, r1 = min(ys), max(ys)
    c0, c1 = min(xs), max(xs)
    sh, sw = r1 - r0 + 1, c1 - c0 + 1

    # Count 8-connected components of each colour outside the screen.
    outside = np.ones((h, w), dtype=bool)
    outside[r0:r1 + 1, c0:c1 + 1] = False

    counts = {}
    seen = np.zeros((h, w), dtype=bool)
    for r in range(h):
        for c in range(w):
            if outside[r, c] and not seen[r, c]:
                color = a[r, c]
                if color == 0:
                    continue
                stack = [(r, c)]
                seen[r, c] = True
                while stack:
                    y, x = stack.pop()
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            if dy == 0 and dx == 0:
                                continue
                            ny, nx = y + dy, x + dx
                            if (0 <= ny < h and 0 <= nx < w and
                                outside[ny, nx] and not seen[ny, nx] and a[ny, nx] == color):
                                seen[ny, nx] = True
                                stack.append((ny, nx))
                counts[color] = counts.get(color, 0) + 1

    out = np.zeros((sh, sw), dtype=int)
    for r in range(sh):
        for c in range(sw):
            color = a[r0 + r, c0 + c]
            if color != 0:
                n = counts.get(color, 1)
                for k in range(n):
                    nc = c + 2 * k
                    if 0 <= nc < sw:
                        out[r, nc] = color

    return out.tolist()

import sys
from collections import Counter, defaultdict
from typing import List

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return [row[:] for row in grid]

    H = len(grid)
    W = len(grid[0])
    out = [row[:] for row in grid]

    # Background is the corner colour in all supplied cases.
    bg = grid[0][0]

    # Border colour is the most frequent non-background colour.
    cnt = Counter(grid[r][c] for r in range(H) for c in range(W))
    border = None
    best = -1
    for col, n in cnt.items():
        if col != bg and n > best:
            best = n
            border = col
    if border is None:
        return out

    # Find connected components of the border colour.
    seen = [[False] * W for _ in range(H)]
    boxes = []

    for r in range(H):
        for c in range(W):
            if grid[r][c] == border and not seen[r][c]:
                stack = [(r, c)]
                seen[r][c] = True
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < H and 0 <= nx < W:
                            if not seen[ny][nx] and grid[ny][nx] == border:
                                seen[ny][nx] = True
                                stack.append((ny, nx))

                if len(cells) < 8:
                    continue

                rmin = min(y for y, x in cells)
                rmax = max(y for y, x in cells)
                cmin = min(x for y, x in cells)
                cmax = max(x for y, x in cells)

                h = rmax - rmin + 1
                w = cmax - cmin + 1
                if h < 3 or w < 3 or h != w:
                    continue

                # The component should be the perimeter of its bounding box.
                ok = True
                for y in range(rmin, rmax + 1):
                    for x in range(cmin, cmax + 1):
                        on_perim = (y == rmin or y == rmax or x == cmin or x == cmax)
                        if on_perim and grid[y][x] != border:
                            ok = False
                            break
                    if not ok:
                        break
                if not ok:
                    continue

                # Payload cells are non-background, non-border cells inside.
                payload_cells = []
                payload_colors = set()
                for y in range(rmin + 1, rmax):
                    for x in range(cmin + 1, cmax):
                        v = grid[y][x]
                        if v != bg and v != border:
                            payload_cells.append((y, x))
                            payload_colors.add(v)

                if not payload_cells or len(payload_colors) != 1:
                    continue

                digit = payload_colors.pop()
                prs = [y for y, x in payload_cells]
                pcs = [x for y, x in payload_cells]
                boxes.append({
                    'rmin': rmin, 'rmax': rmax,
                    'cmin': cmin, 'cmax': cmax,
                    'digit': digit,
                    'prows': list(range(min(prs), max(prs) + 1)),
                    'pcols': list(range(min(pcs), max(pcs) + 1)),
                })

    if not boxes:
        return out

    # Key sequence: remaining non-background/non-border cells, read left-to-right.
    in_box = [[False] * W for _ in range(H)]
    for b in boxes:
        for y in range(b['rmin'], b['rmax'] + 1):
            for x in range(b['cmin'], b['cmax'] + 1):
                in_box[y][x] = True

    key = []
    for r in range(H):
        for c in range(W):
            v = grid[r][c]
            if v != bg and v != border and not in_box[r][c]:
                key.append(v)

    if not key:
        return out

    # Build graph of directly connectable boxes.
    n = len(boxes)
    adj = defaultdict(list)

    def gap_clear_h(a, b):
        if a['prows'] != b['prows']:
            return None
        if a['cmax'] < b['cmin']:
            left, right = a, b
        elif b['cmax'] < a['cmin']:
            left, right = b, a
        else:
            return None
        c1 = left['cmax'] + 1
        c2 = right['cmin'] - 1
        if c1 > c2:
            return None
        for y in a['prows']:
            for x in range(c1, c2 + 1):
                if grid[y][x] != bg:
                    return None
        return (a['prows'], list(range(c1, c2 + 1)))

    def gap_clear_v(a, b):
        if a['pcols'] != b['pcols']:
            return None
        if a['rmax'] < b['rmin']:
            top, bottom = a, b
        elif b['rmax'] < a['rmin']:
            top, bottom = b, a
        else:
            return None
        r1 = top['rmax'] + 1
        r2 = bottom['rmin'] - 1
        if r1 > r2:
            return None
        for y in range(r1, r2 + 1):
            for x in a['pcols']:
                if grid[y][x] != bg:
                    return None
        return (list(range(r1, r2 + 1)), a['pcols'])

    for i in range(n):
        for j in range(i + 1, n):
            a, b = boxes[i], boxes[j]
            rect = gap_clear_h(a, b)
            if rect is None:
                rect = gap_clear_v(a, b)
            if rect is not None:
                adj[i].append(j)
                adj[j].append(i)

    by_digit = defaultdict(list)
    for i, b in enumerate(boxes):
        by_digit[b['digit']].append(i)

    # Find the path of boxes whose digit sequence is the key row.
    path = None

    def backtrack(pos, used, cur):
        nonlocal path
        if path is not None:
            return
        if pos == len(key):
            path = cur[:]
            return
        d = key[pos]
        if not cur:
            candidates = by_digit.get(d, [])
        else:
            last = cur[-1]
            candidates = [j for j in adj[last] if boxes[j]['digit'] == d]
        for j in candidates:
            if j not in used:
                used.add(j)
                cur.append(j)
                backtrack(pos + 1, used, cur)
                cur.pop()
                used.remove(j)
                if path is not None:
                    return

    backtrack(0, set(), [])

    if path is None:
        return out

    # Fill the gap after each box in the path with that box's digit.
    for idx in range(len(path) - 1):
        a = boxes[path[idx]]
        b = boxes[path[idx + 1]]
        digit = a['digit']
        rect = gap_clear_h(a, b)
        if rect is None:
            rect = gap_clear_v(a, b)
        if rect is None:
            continue
        rows, cols = rect
        for y in rows:
            for x in cols:
                out[y][x] = digit

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    out = np.full((h, w), 1, dtype=int)

    twos = list(zip(*np.where(g == 2)))
    if not twos:
        return out.tolist()

    # The marker used for the vertical split is the topmost 2
    # (if there is a tie, the leftmost one).
    marker = min(twos, key=lambda p: (p[0], p[1]))
    mc = marker[1]

    sevens = list(zip(*np.where(g == 7)))
    if not sevens:
        # No 7s: just draw the vertical 2 line from the marker to the bottom.
        for r in range(marker[0], h):
            out[r, mc] = 2
        return out.tolist()

    min_r = min(r for r, c in sevens)
    max_r = max(r for r, c in sevens)

    left = [(r, c) for r, c in sevens if c < mc]
    right = [(r, c) for r, c in sevens if c > mc]
    on_line = [(r, c) for r, c in sevens if c == mc]

    # Keep 7s on the marker column in their original positions.
    for r, c in on_line:
        out[r, c] = 7

    # Move the left part to the top-left corner, preserving relative shape.
    if left:
        lmin_r = min(r for r, c in left)
        lmin_c = min(c for r, c in left)
        for r, c in left:
            out[r - lmin_r, c - lmin_c] = 7

    # Move the right part to the top-right corner, preserving relative shape.
    if right:
        rmin_r = min(r for r, c in right)
        rmax_c = max(c for r, c in right)
        width = rmax_c - rmin_c + 1
        for r, c in right:
            out[r - rmin_r, w - width + (c - rmin_c)] = 7

    # Draw the 2 line in the marker column from the marker down to the
    # bottom of the original 7-shape bounding box. Existing 7s stay 7.
    for r in range(marker[0], max_r + 1):
        if out[r, mc] != 7:
            out[r, mc] = 2

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = np.full((h, w), 1, dtype=int)

    twos = list(zip(*np.where(g == 2)))
    sevens = list(zip(*np.where(g == 7)))
    if not twos or not sevens:
        return out.tolist()

    # Axes are given by 2s on the border.
    # A top/bottom 2 creates a vertical axis; a left/right 2 creates a horizontal axis.
    v_axes = []
    h_axes = []
    for r, c in twos:
        if r == 0 or r == h - 1:
            v_axes.append(c)
        if c == 0 or c == w - 1:
            h_axes.append(r)

    # If there are multiple, use the one closest to the 7-shape.
    if v_axes:
        v_axes.sort(key=lambda c: min(abs(c - cc) for rr, cc in sevens))
        vc = v_axes[0]
    else:
        vc = None

    if h_axes:
        h_axes.sort(key=lambda r: min(abs(r - rr) for rr, cc in sevens))
        hr = h_axes[0]
    else:
        hr = None

    # Keep 7s that lie exactly on an active axis in their original positions.
    for r, c in sevens:
        if (vc is not None and c == vc) or (hr is not None and r == hr):
            out[r, c] = 7

    # Move off-axis 7 pieces to the corners activated by the border 2s.
    for r, c in sevens:
        if vc is not None and c == vc:
            continue
        if hr is not None and r == hr:
            continue

        # Determine which corner this piece belongs to.
        # If only one axis exists, use the side of the marker for the other coordinate.
        if vc is not None and hr is not None:
            top = r < hr
            left = c < vc
        elif vc is not None:
            # vertical axis only: top/bottom marker decides vertical corner
            top = (min(twos, key=lambda p: (abs(p[0] - r), p[1]))[0] == 0)
            left = c < vc
        elif hr is not None:
            # horizontal axis only: left/right marker decides horizontal corner
            top = r < hr
            left = (min(twos, key=lambda p: (abs(p[1] - c), p[0]))[1] == 0)
        else:
            continue

        # Collect pieces by corner.
        pass

    # The loop above is only for clarity; do the actual grouping below.
    corners = {
        "tl": [],
        "tr": [],
        "bl": [],
        "br": [],
    }

    for r, c in sevens:
        if vc is not None and c == vc:
            continue
        if hr is not None and r == hr:
            continue

        if vc is not None and hr is not None:
            if r < hr and c < vc:
                corners["tl"].append((r, c))
            elif r < hr and c > vc:
                corners["tr"].append((r, c))
            elif r > hr and c < vc:
                corners["bl"].append((r, c))
            elif r > hr and c > vc:
                corners["br"].append((r, c))
        elif vc is not None:
            # top marker -> top corners, bottom marker -> bottom corners
            marker_r = 0 if any(rr == 0 for rr, cc in twos if cc == vc) else h - 1
            if c < vc:
                key = "tl" if marker_r == 0 else "bl"
                corners[key].append((r, c))
            elif c > vc:
                key = "tr" if marker_r == 0 else "br"
                corners[key].append((r, c))
        elif hr is not None:
            # left marker -> left corners, right marker -> right corners
            marker_c = 0 if any(cc == 0 for rr, cc in twos if rr == hr) else w - 1
            if r < hr:
                key = "tl" if marker_c == 0 else "tr"
                corners[key].append((r, c))
            elif r > hr:
                key = "bl" if marker_c == 0 else "br"
                corners[key].append((r, c))

    def place(points, corner):
