            return
        min_r = min(r for r, c in points)
        max_r = max(r for r, c in points)
        min_c = min(c for r, c in points)
        max_c = max(c for r, c in points)
        height = max_r - min_r + 1
        width = max_c - min_c + 1

        if corner == "tl":
            base_r, base_c = 0, 0
        elif corner == "tr":
            base_r, base_c = 0, w - width
        elif corner == "bl":
            base_r, base_c = h - height, 0
        else:  # br
            base_r, base_c = h - height, w - width

        for r, c in points:
            out[base_r + (r - min_r), base_c + (c - min_c)] = 7

    place(corners["tl"], "tl")
    place(corners["tr"], "tr")
    place(corners["bl"], "bl")
    place(corners["br"], "br")

    # Draw 2-lines from border markers to the farthest 7 in that line.
    # Existing 7s on the line remain 7.
    for r, c in twos:
        if r == 0 or r == h - 1:
            # vertical line
            col = c
            line_sevens = [rr for rr, cc in sevens if cc == col]
            if not line_sevens:
                continue
            if r == 0:
                end = max(line_sevens)
                for rr in range(r, end + 1):
                    if out[rr, col] != 7:
                        out[rr, col] = 2
            else:
                end = min(line_sevens)
                for rr in range(end, r + 1):
                    if out[rr, col] != 7:
                        out[rr, col] = 2

        if c == 0 or c == w - 1:
            # horizontal line
            row = r
            line_sevens = [cc for rr, cc in sevens if rr == row]
            if not line_sevens:
                continue
            if c == 0:
                end = max(line_sevens)
                for cc in range(c, end + 1):
                    if out[row, cc] != 7:
                        out[row, cc] = 2
            else:
                end = min(line_sevens)
                for cc in range(end, c + 1):
                    if out[row, cc] != 7:
                        out[row, cc] = 2

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Find the 0-block and 2-block.
    zero_cells = [(r, c) for r in range(H) for c in range(W) if g[r, c] == 0]
    two_cells = [(r, c) for r in range(H) for c in range(W) if g[r, c] == 2]

