    zc1 = max(c for r, c in zero_cells)

    tr0 = min(r for r, c in two_cells)
    tr1 = max(r for r, c in two_cells)
    tc0 = min(c for r, c in two_cells)
    tc1 = max(c for r, c in two_cells)

    # Work on a copy.
    out = g.copy()

    # The 0-block is always converted to 1.
    out[zr0:zr1 + 1, zc0:zc1 + 1] = 1

    # Build the graph of 1-cells.
    ones = [(r, c) for r in range(H) for c in range(W) if g[r, c] == 1]
    one_set = set(ones)

    adj = {cell: [] for cell in ones}
    for r, c in ones:
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nb = (r + dr, c + dc)
            if nb in one_set:
                adj[(r, c)].append(nb)

    # Nearest 1-cell(s) adjacent to the 0-block and 2-block.
    def neighbors_of_block(r0, r1, c0, c1):
        res = []
        for r in range(max(0, r0 - 1), min(H, r1 + 2)):
            for c in range(max(0, c0 - 1), min(W, c1 + 2)):
                if (r, c) in one_set:
                    if not (r0 <= r <= r1 and c0 <= c <= c1):
                        res.append((r, c))
        return res

    zero_adj = neighbors_of_block(zr0, zr1, zc0, zc1)
    two_adj = neighbors_of_block(tr0, tr1, tc0, tc1)

    # If either special block is not attached to the 1-network,
    # fall back to the simple endpoint replacement.
    if not zero_adj or not two_adj:
        out[tr0:tr1 + 1, tc0:tc1 + 1] = 0
        return out.tolist()

    # Multi-source BFS from the 0-side boundary.
    dist = {}
    q = deque()
    for cell in zero_adj:
        dist[cell] = 0
        q.append(cell)

    while q:
        u = q.popleft()
        for v in adj[u]:
            if v not in dist:
                dist[v] = dist[u] + 1
                q.append(v)

    # If the 2-side is not connected to the 0-side, use simple replacement.
    if not any(cell in dist for cell in two_adj):
        out[tr0:tr1 + 1, tc0:tc1 + 1] = 0
        return out.tolist()

    # For every 1-cell, compute the minimum distance to the 2-side boundary.
    # This is the length of the shortest path from that cell to the 2-block.
    dist_to_two = {}
    q = deque()
    for cell in two_adj:
        if cell in dist:
            dist_to_two[cell] = 0
            q.append(cell)

    while q:
        u = q.popleft()
        for v in adj[u]:
            if v not in dist_to_two:
                dist_to_two[v] = dist_to_two[u] + 1
                q.append(v)

    # Candidate cells are 1-cells that lie on some shortest path from 0 to 2.
    candidates = [
        cell for cell in dist
        if cell in dist_to_two and dist[cell] + dist_to_two[cell] == min(
            dist[a] + dist_to_two[a] for a in two_adj if a in dist
        )
    ]

    if not candidates:
        out[tr0:tr1 + 1, tc0:tc1 + 1] = 0
        return out.tolist()

    # Choose the middle layer of the shortest path.
    total = min(dist[a] + dist_to_two[a] for a in two_adj if a in dist)
    mid = total // 2

    # Cells whose distance from the 0-side is as close as possible to mid.
    best = min(abs(dist[cell] - mid) for cell in candidates)
    layer = [cell for cell in candidates if abs(dist[cell] - mid) == best]

    # If the layer is larger than the 0-block, keep the connected component
    # of the layer that is closest to the 0-block.
    zero_size = len(zero_cells)
    if len(layer) > zero_size:
        # BFS within the layer.
        layer_set = set(layer)
        components = []
        seen = set()
        for start in layer:
            if start in seen:
                continue
            comp = []
            dq = deque([start])
            seen.add(start)
            while dq:
                u = dq.popleft()
                comp.append(u)
                for v in adj[u]:
                    if v in layer_set and v not in seen:
                        seen.add(v)
                        dq.append(v)
            components.append(comp)

        # Pick the component with minimum distance to the 0-block.
        def block_distance(comp):
            return min(
                max(0, zr0 - r, r - zr1, zc0 - c, c - zc1)
                for r, c in comp
            )

        layer = min(components, key=block_distance)

    # Place the 0-block at the selected middle layer.
    for r, c in layer:
        out[r, c] = 0

    # If the selected layer is exactly the 2-block neighborhood and the
    # 2-block is the same size as the 0-block, replace the 2-block by 0.
    # This matches examples 1 and 2.
    if len(layer) == zero_size:
        # Check whether the selected layer is adjacent to the 2-block
        # and the 2-block is not already represented by 1-cells.
        if any(
            max(0, tr0 - r, r - tr1, tc0 - c, c - tc1) == 1
            for r, c in layer
        ):
            out[tr0:tr1 + 1, tc0:tc1 + 1] = 0

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import math

    h = len(grid)
    w = len(grid[0])
    out = [row[:] for row in grid]

    def bresenham(x0, y0, x1, y1):
        """Return grid coordinates (r, c) from (y0, x0) to (y1, x1)."""
        pts = []
        dx = abs(x1 - x0)
        dy = abs(y1 - y0)
        sx = 1 if x0 < x1 else -1
        sy = 1 if y0 < y1 else -1
        err = dx - dy
        x, y = x0, y0
        while True:
            pts.append((y, x))
            if x == x1 and y == y1:
                break
            e2 = 2 * err
            if e2 > -dy:
                err -= dy
                x += sx
            if e2 < dx:
                err += dx
                y += sy
        return pts

    def dist2(a, b):
        return (a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2

    def mst_edges(points):
        """Minimum spanning tree edges using Euclidean distance."""
        n = len(points)
        if n <= 1:
            return []
        parent = list(range(n))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        edges = []
        for i in range(n):
            for j in range(i + 1, n):
                a, b = i, j
                if a > b:
                    a, b = b, a
                ra, rb = find(a), find(b)
                if ra != rb:
                    if ra < rb:
                        parent[rb] = ra
                    else:
                        parent[ra] = rb
                    edges.append((i, j))
        return edges

    # Collect points by color.
    colors = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v != 0:
                colors.setdefault(v, []).append((r, c))

    # Draw MST lines for every color with at least two points.
    for pts in colors.values():
        if len(pts) < 2:
            continue
        for i, j in mst_edges(pts):
            for r, c in bresenham(pts[i][1], pts[i][0], pts[j][1], pts[j][0]):
                if 0 <= r < h and 0 <= c < w:
                    out[r][c] = pts[i][0]

    # Special rule for color 8:
    # If there is exactly one 8, draw a rectangle from that 8 to the
    # cell diagonally up-left of the bottom-right corner of the 1-rectangle.
    if 8 in colors and len(colors[8]) == 1 and 1 in colors and len(colors[1]) >= 2:
        r8, c8 = colors[8][0]
        r1s = [p[0] for p in colors[1]]
        c1s = [p[1] for p in colors[1]]
        r2 = max(r1s) - 1
        c2 = max(c1s) - 1

        # top and bottom borders
        for c in range(min(c8, c2), max(c8, c2) + 1):
            out[r8][c] = 8
            out[r2][c] = 8
        # left and right borders
        for r in range(min(r8, r2), max(r8, r2) + 1):
            out[r][c8] = 8
            out[r][c2] = 8

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])
    out = [row[:] for row in grid]

    def bresenham(r0, c0, r1, c1):
        pts = []
        dr = abs(r1 - r0)
        dc = abs(c1 - c0)
        sr = 1 if r0 < r1 else -1
        sc = 1 if c0 < c1 else -1
        err = dc - dr
        r, c = r0, c0
        while True:
            pts.append((r, c))
            if r == r1 and c == c1:
                break
            e2 = 2 * err
            if e2 > -dr:
                err -= dr
                c += sc
            if e2 < dc:
                err += dc
                r += sr
        return pts

    def draw_line(r0, c0, r1, c1, color):
        for r, c in bresenham(r0, c0, r1, c1):
            if 0 <= r < h and 0 <= c < w:
                out[r][c] = color

    def draw_rect(r0, c0, r1, c1, color):
        for c in range(min(c0, c1), max(c0, c1) + 1):
            out[r0][c] = color
            out[r1][c] = color
        for r in range(min(r0, r1), max(r0, r1) + 1):
            out[r][c0] = color
            out[r][c1] = color

    def mst_edges(points):
        n = len(points)
        if n <= 1:
            return []
        parent = list(range(n))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        edges = []
        for i in range(n):
            for j in range(i + 1, n):
                a, b = i, j
                if a > b:
                    a, b = b, a
                ra, rb = find(a), find(b)
                if ra != rb:
                    if ra < rb:
                        parent[rb] = ra
                    else:
                        parent[ra] = rb
                    edges.append((i, j))
        return edges

    def draw_mst(points, color):
        for i, j in mst_edges(points):
            draw_line(points[i][0], points[i][1], points[j][0], points[j][1], color)

    def draw_hull(points, color):
        if len(points) <= 2:
            draw_mst(points, color)
            return

        def cross(o, a, b):
            return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

        pts = sorted(set(points))
        lower = []
        for p in pts:
            while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
                lower.pop()
            lower.append(p)
        upper = []
        for p in reversed(pts):
            while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
                upper.pop()
            upper.append(p)
        hull = lower[:-1] + upper[:-1]
        if len(hull) < 3:
            draw_mst(points, color)
            return
        for i in range(len(hull)):
            draw_line(hull[i][0], hull[i][1], hull[(i + 1) % len(hull)][0], hull[(i + 1) % len(hull)][1], color)

    colors = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v != 0:
                colors.setdefault(v, []).append((r, c))

    # Same-color shapes.
    for color, pts in colors.items():
        if color in (1, 8):
            continue
        if len(pts) >= 2:
            draw_hull(pts, color)

    # Paired shadow rule for 1 and 8.
    if 1 in colors and 8 in colors:
        p1 = colors[1]
        p8 = colors[8]

        if len(p1) == 1 and len(p8) >= 2:
            r1, c1 = p1[0]
            best = None
            for r8, c8 in p8:
                if r8 == r1 + 1 and c8 == c1 + 1:
                    best = (r8, c8)
                    break
            if best is None:
                best = min(p8, key=lambda p: (p[0] - r1) ** 2 + (p[1] - c1) ** 2)

            edges = mst_edges(p8)
            idx = p8.index(best)
            for i, j in edges:
                if i == idx or j == idx:
                    other = j if i == idx else i
                    draw_line(r1, c1, p8[other][0] - 1, p8[other][1] - 1, 1)
            draw_mst(p8, 8)

        elif len(p8) == 1 and len(p1) >= 2:
            r8, c8 = p8[0]
            r1s = [p[0] for p in p1]
            c1s = [p[1] for p in p1]
            r0, c0 = min(r1s), min(c1s)
            r1, c1 = max(r1s), max(c1s)

            if r8 <= r0 and c8 <= c0:
                draw_rect(r8, c8, r1 - 1, c1 - 1, 8)
            elif r8 >= r1 and c8 >= c1:
                draw_rect(r8, c8, r0 + 1, c0 + 1, 8)
            elif r8 <= r0 and c8 >= c1:
                draw_rect(r8, c8, r1 - 1, c0 + 1, 8)
            elif r8 >= r1 and c8 <= c0:
                draw_rect(r8, c8, r0 + 1, c1 - 1, 8)
            else:
                draw_mst(p8, 8)

            draw_hull(p1, 1)

        else:
            draw_hull(p1, 1)
            draw_mst(p8, 8)

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Find the marker: a horizontal run of 4 cells of a color different from
    # the dominant background color.
    marker_color = None
    marker_cols = None
    marker_row = None

    for r in range(h):
        c = 0
        while c < w:
            if g[r, c] != 0:
                cc = g[r, c]
                c2 = c
                while c2 < w and g[r, c2] == cc:
                    c2 += 1
                if c2 - c == 4:
                    marker_color = cc
                    marker_cols = (c, c2 - 1)
                    marker_row = r
                    break
                c = c2
            else:
                c += 1
        if marker_color is not None:
            break

    if marker_color is None:
        return out.tolist()

    # Background is the most common color.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # Connected components of the object color (the non-background, non-marker
    # color that forms the large blobs).
    obj_color = None
    for v in vals:
        if v != bg and v != marker_color:
            obj_color = int(v)
            break

    if obj_color is None:
        return out.tolist()

    seen = np.zeros((h, w), dtype=bool)
    comps = []
    for r in range(h):
        for c in range(w):
            if g[r, c] == obj_color and not seen[r, c]:
                q = deque([(r, c)])
                seen[r, c] = True
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w:
                            if not seen[ny, nx] and g[ny, nx] == obj_color:
                                seen[ny, nx] = True
                                q.append((ny, nx))
                comps.append(cells)

    # Group components that are vertically close (same visual band).
    comps.sort(key=lambda cells: min(r for r, _ in cells))
    groups = []
    for cells in comps:
        rmin = min(r for r, _ in cells)
        rmax = max(r for r, _ in cells)
        placed = False
        for grp in groups:
            if rmin <= grp["rmax"] + 2 and rmax >= grp["rmin"] - 2:
                grp["cells"].extend(cells)
                grp["rmin"] = min(grp["rmin"], rmin)
                grp["rmax"] = max(grp["rmax"], rmax)
                placed = True
                break
        if not placed:
            groups.append({"cells": cells, "rmin": rmin, "rmax": rmax})

    # For each band, mark the top, middle, and bottom rows in the marker columns.
    for grp in groups:
        rmin = grp["rmin"]
        rmax = grp["rmax"]
        mid = (rmin + rmax) // 2
        c0, c1 = marker_cols

        # Top row: if it already has object pixels in the marker window,
        # move the mark one row above; otherwise mark the top row.
        top_mark = rmin
        if any(g[rmin, c] == obj_color for c in range(c0, c1 + 1)):
            top_mark = rmin - 1

        if 0 <= top_mark < h:
            out[top_mark, c0:c1 + 1] = 3
        if 0 <= mid < h:
            out[mid, c0:c1 + 1] = 3
        if 0 <= rmax < h:
            out[rmax, c0:c1 + 1] = 4

        # If the top mark was shifted above the band, also mark the original
        # top row with 4 when it is not the middle/bottom row.
        if top_mark != rmin and 0 <= rmin < h and rmin != mid and rmin != rmax:
            out[rmin, c0:c1 + 1] = 4

    # Preserve the original marker.
    if marker_row is not None:
        out[marker_row, marker_cols[0]:marker_cols[1] + 1] = marker_color

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

