    seen = np.zeros((h, w), dtype=bool)
    marker_cells = []
    for r in range(h):
        for c in range(w):
            if g[r, c] == marker_color and not seen[r, c]:
                q = deque([(r, c)])
                seen[r, c] = True
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w:
                            if not seen[ny, nx] and g[ny, nx] == marker_color:
                                seen[ny, nx] = True
                                q.append((ny, nx))
                if len(cells) > len(marker_cells):
                    marker_cells = cells

    if not marker_cells:
        return out.tolist()

    # Object color is the most common non-background, non-marker color.
    obj_color = None
    best = -1
    for v in vals:
        v = int(v)
        if v != bg and v != marker_color:
            if counts[vals == v][0] > best:
                best = counts[vals == v][0]
                obj_color = v

    if obj_color is None:
        return out.tolist()

    # Marker orientation and projection interval.
    rows = [r for r, _ in marker_cells]
    cols = [c for _, c in marker_cells]
    rmin_m, rmax_m = min(rows), max(rows)
    cmin_m, cmax_m = min(cols), max(cols)
    horizontal = (cmax_m - cmin_m) >= (rmax_m - rmin_m)

    # Connected components of the object color.
    seen = np.zeros((h, w), dtype=bool)
    comps = []
    for r in range(h):
        for c in range(w):
            if g[r, c] == obj_color and not seen[r, c]:
