    for band in bands:
        rmin = band["rmin"]
        rmax = band["rmax"]
        mid = (rmin + rmax) // 2

        # Horizontal marker: work in the marker's column interval.
        if horizontal:
            c0, c1 = cmin_m, cmax_m

