            if top_mark != rmin and 0 <= rmin < h and rmin != mid and rmin != rmax:
                out[rmin, c0:c1 + 1] = 4

            # Paint the middle row across the band's horizontal extent with 3.
            if 0 <= mid < h:
                cmin = min(c for _, c in band["cells"])
                cmax = max(c for _, c in band["cells"])
                out[mid, cmin:cmax + 1] = 3

        # Vertical marker: work in the marker's row interval.
        else:
            r0, r1 = rmin_m, rmax_m

            # Left column: if it already has object pixels in the marker window,
