            left_mark = cmin_m
            if any(g[r, cmin_m] == obj_color for r in range(r0, r1 + 1)):
                left_mark = cmin_m - 1

            if 0 <= left_mark < w:
                out[r0:r1 + 1, left_mark] = 3
            if 0 <= cmax_m < w:
                out[r0:r1 + 1, cmax_m] = 4

            # Paint the middle column across the band's vertical extent with 3.
            if 0 <= mid < h:
                rmin_c = min(r for r, _ in band["cells"])
                rmax_c = max(r for r, _ in band["cells"])
                out[rmin_c:rmax_c + 1, mid] = 3

    # Preserve the original marker.
    for r, c in marker_cells:
        out[r, c] = marker_color

    return out.tolist()

