                                break
                    if ok:
                        boxes.append((r, c, r2, c2))

    # Remove duplicate boxes.
    uniq = []
    for b in boxes:
        if b not in uniq:
            uniq.append(b)
    boxes = uniq

    # For each box, find the 9 segment adjacent to one side.
    # The box is moved to the other 9 segment of the same length,
    # preserving which side of the 9 it is on.
    for (r1, c1, r2, c2) in boxes:
        bh = r2 - r1 + 1
        bw = c2 - c1 + 1

        # Candidate 9 segments adjacent to left/right/top/bottom.
        candidates = []

        # Left side: 9s at c1-1, rows r1..r2
        if c1 - 1 >= 0:
            if all(g[rr, c1 - 1] == 9 for rr in range(r1, r2 + 1)):
                candidates.append(('L', r1, r2, c1 - 1))

        # Right side: 9s at c2+1, rows r1..r2
        if c2 + 1 < w:
            if all(g[rr, c2 + 1] == 9 for rr in range(r1, r2 + 1)):
                candidates.append(('R', r1, r2, c2 + 1))

        # Top side: 9s at r1-1, cols c1..c2
        if r1 - 1 >= 0:
            if all(g[r1 - 1, cc] == 9 for cc in range(c1, c2 + 1)):
                candidates.append(('T', r1 - 1, c1, c2))

        # Bottom side: 9s at r2+1, cols c1..c2
        if r2 + 1 < h:
            if all(g[r2 + 1, cc] == 9 for cc in range(c1, c2 + 1)):
                candidates.append(('B', r2 + 1, c1, c2))

        if not candidates:
            continue

        # Choose the adjacent 9 segment that has another parallel 9 segment
        # of the same length in the same row/column range.
        target = None
        for cand in candidates:
            side, a, b, pos = cand
            found = False
            if side == 'L' or side == 'R':
                # vertical segment at column pos, rows a..b
                for cc in range(w):
                    if cc == pos:
                        continue
                    if all(g[rr, cc] == 9 for rr in range(a, b + 1)):
                        # Ensure it is not part of the same segment (contiguous)
                        if side == 'L' and cc < pos:
                            target = (side, a, b, cc)
                            found = True
                            break
                        if side == 'R' and cc > pos:
                            target = (side, a, b, cc)
                            found = True
                            break
            else:
                # horizontal segment at row pos, cols a..b
                for rr in range(h):
                    if rr == pos:
                        continue
                    if all(g[rr, cc] == 9 for cc in range(a, b + 1)):
                        if side == 'T' and rr < pos:
                            target = (side, rr, a, b)
                            found = True
                            break
                        if side == 'B' and rr > pos:
                            target = (side, rr, a, b)
                            found = True
                            break
            if found:
                break

        if target is None:
            continue

        side, a, b, pos = target

        # Compute new box position.
        if side == 'L':
            # Box is to the left of the 9 segment.
            nr1, nr2 = a, b
            nc2 = pos - 1
            nc1 = nc2 - bw + 1
        elif side == 'R':
            # Box is to the right of the 9 segment.
            nr1, nr2 = a, b
            nc1 = pos + 1
            nc2 = nc1 + bw - 1
        elif side == 'T':
            # Box is above the 9 segment.
            nc1, nc2 = a, b
            nr2 = pos - 1
            nr1 = nr2 - bh + 1
        else:  # 'B'
            # Box is below the 9 segment.
            nc1, nc2 = a, b
            nr1 = pos + 1
            nr2 = nr1 + bh - 1

        # Bounds check.
        if nr1 < 0 or nc1 < 0 or nr2 >= h or nc2 >= w:
            continue

        # Extract interior pattern.
        inner = g[r1 + 1:r2, c1 + 1:c2].copy()
        ih, iw = inner.shape

        # Transform interior: 5s become the 180-degree rotation of the
        # original 7s; all other interior cells become 7.
        if ih > 0 and iw > 0:
            rotated_7 = np.rot90(inner == 7, 2)
            new_inner = np.full((ih, iw), 7, dtype=int)
            new_inner[rotated_7] = 5
        else:
            new_inner = inner

        # Clear old box area (border + interior) to background 6.
        out[r1:r2 + 1, c1:c2 + 1] = 6

        # Draw new box border.
        out[nr1:nr2 + 1, nc1:nc2 + 1] = 6
        out[nr1, nc1:nc2 + 1] = 0
        out[nr2, nc1:nc2 + 1] = 0
        out[nr1:nr2 + 1, nc1] = 0
        out[nr1:nr2 + 1, nc2] = 0

        # Fill new interior.
        if ih > 0 and iw > 0:
            out[nr1 + 1:nr2, nc1 + 1:nc2] = new_inner

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Find all rectangular boxes whose border is 0.
    boxes = []
    for r in range(h):
        for c in range(w):
            if g[r, c] != 0:
                continue
            r2 = r
            while r2 + 1 < h and g[r2 + 1, c] == 0:
                r2 += 1
            c2 = c
            while c2 + 1 < w and g[r, c2 + 1] == 0:
                c2 += 1
            if r2 == r or c2 == c:
                continue

            ok = True
            for rr in range(r, r2 + 1):
                if g[rr, c] != 0 or g[rr, c2] != 0:
                    ok = False
                    break
            if ok:
                for cc in range(c, c2 + 1):
                    if g[r, cc] != 0 or g[r2, cc] != 0:
                        ok = False
                        break
            if ok:
                boxes.append((r, c, r2, c2))

    # Unique boxes.
    uniq = []
    for b in boxes:
        if b not in uniq:
            uniq.append(b)
    boxes = uniq

    def vertical_9s(rows, col):
        return all(0 <= col < w and g[rr, col] == 9 for rr in rows)

    def horizontal_9s(cols, row):
        return all(0 <= row < h and g[row, cc] == 9 for cc in cols)

    def other_vertical_9(rows, avoid_col):
        for cc in range(w):
            if cc == avoid_col:
                continue
            if vertical_9s(rows, cc):
                return cc
        return None

    def other_horizontal_9(cols, avoid_row):
        for rr in range(h):
            if rr == avoid_row:
                continue
            if horizontal_9s(cols, rr):
                return rr
        return None

    def transform_interior(inner):
        # 180-degree rotation, then swap 5 and 7.
        rot = np.rot90(inner, 2)
        res = rot.copy()
        res[rot == 5] = 7
        res[rot == 7] = 5
        return res

    for (r1, c1, r2, c2) in boxes:
        bh = r2 - r1 + 1
        bw = c2 - c1 + 1

        # Determine which side of the box has a 9 segment.
        side = None
        if c1 > 0 and vertical_9s(range(r1, r2 + 1), c1 - 1):
            side = 'L'
        elif c2 + 1 < w and vertical_9s(range(r1, r2 + 1), c2 + 1):
            side = 'R'
        elif r1 > 0 and horizontal_9s(range(c1, c2 + 1), r1 - 1):
            side = 'T'
        elif r2 + 1 < h and horizontal_9s(range(c1, c2 + 1), r2 + 1):
            side = 'B'

        if side is None:
            continue

        # Find the other parallel 9 segment of the same span.
        if side == 'L':
            src_col = c1 - 1
            dst_col = other_vertical_9(range(r1, r2 + 1), src_col)
            if dst_col is None:
                continue
            nr1, nr2 = r1, r2
            nc1 = dst_col + 1
            nc2 = nc1 + bw - 1
        elif side == 'R':
            src_col = c2 + 1
            dst_col = other_vertical_9(range(r1, r2 + 1), src_col)
            if dst_col is None:
                continue
            nr1, nr2 = r1, r2
            nc2 = dst_col - 1
            nc1 = nc2 - bw + 1
        elif side == 'T':
            src_row = r1 - 1
            dst_row = other_horizontal_9(range(c1, c2 + 1), src_row)
            if dst_row is None:
                continue
            nc1, nc2 = c1, c2
            nr1 = dst_row + 1
            nr2 = nr1 + bh - 1
        else:  # 'B'
            src_row = r2 + 1
            dst_row = other_horizontal_9(range(c1, c2 + 1), src_row)
            if dst_row is None:
                continue
            nc1, nc2 = c1, c2
            nr2 = dst_row - 1
            nr1 = nr2 - bh + 1

        if nr1 < 0 or nc1 < 0 or nr2 >= h or nc2 >= w:
            continue

        # Extract and transform the interior.
        inner = g[r1 + 1:r2, c1 + 1:c2].copy()
        new_inner = transform_interior(inner)

        # Clear the old box.
        out[r1:r2 + 1, c1:c2 + 1] = 6

        # Draw the new box.
        out[nr1:nr2 + 1, nc1:nc2 + 1] = 6
        out[nr1, nc1:nc2 + 1] = 0
        out[nr2, nc1:nc2 + 1] = 0
        out[nr1:nr2 + 1, nc1] = 0
        out[nr1:nr2 + 1, nc2] = 0

        if nr2 > nr1 and nc2 > nc1:
            out[nr1 + 1:nr2, nc1 + 1:nc2] = new_inner

    return out.tolist()

import numpy as np

def _components(mask):
    h, w = mask.shape
    seen = np.zeros((h, w), dtype=bool)
    comps = []
    for r in range(h):
        for c in range(w):
            if mask[r, c] and not seen[r, c]:
                stack = [(r, c)]
                seen[r, c] = True
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and mask[ny, nx] and not seen[ny, nx]:
                            seen[ny, nx] = True
                            stack.append((ny, nx))
                comps.append(cells)
    return comps

def _bbox(cells):
    rs = [r for r, _ in cells]
    cs = [c for _, c in cells]
    return min(rs), min(cs), max(rs), max(cs)

def _shape(cells):
    r0, c0, r1, c1 = _bbox(cells)
    h = r1 - r0 + 1
    w = c1 - c0 + 1
    arr = np.zeros((h, w), dtype=int)
    for r, c in cells:
        arr[r - r0, c - c0] = 1
    return arr

def _rot_cw(arr):
    return np.rot90(arr, k=-1)

def _rot_ccw(arr):
    return np.rot90(arr, k=1)

def _mirror_h(arr):
    return arr[:, ::-1]

def _place(out, cells, r0, c0, color):
    for r, c in cells:
        out[r0 + r, c0 + c] = color

def _fit(out, color, cells, r0, c0):
    h, w = out.shape
    for r, c in cells:
        if not (0 <= r0 + r < h and 0 <= c0 + c < w):
            return False
    return True

def _try_place(out, color, cells, r0, c0):
    if not _fit(out, color, cells, r0, c0):
        return False
    for r, c in cells:
        if out[r0 + r, c0 + c] not in (0, color):
            return False
    _place(out, cells, r0, c0, color)
    return True

def _place_shape(out, color, shape, r0, c0):
    h, w = out.shape
    if r0 < 0 or c0 < 0 or r0 + shape.shape[0] > h or c0 + shape.shape[1] > w:
        return False
    for i in range(shape.shape[0]):
        for j in range(shape.shape[1]):
            if shape[i, j]:
                if out[r0 + i, c0 + j] not in (0, color):
                    return False
    for i in range(shape.shape[0]):
        for j in range(shape.shape[1]):
            if shape[i, j]:
                out[r0 + i, c0 + j] = color
    return True

def _attach(out, color, body_shape, handle_shape, r0, c0):
    bh, bw = body_shape.shape
    hh, hw = handle_shape.shape
    candidates = []

    # right
    for dr in range(-hh + 1, bh):
        candidates.append((r0 + dr, c0 + bw, 0, 0))
    # left
    for dr in range(-hh + 1, bh):
        candidates.append((r0 + dr, c0 - hw, 0, 0))
    # top
    for dc in range(-hw + 1, bw):
        candidates.append((r0 - hh, c0 + dc, 0, 0))
    # bottom
    for dc in range(-hw + 1, bw):
        candidates.append((r0 + bh, c0 + dc, 0, 0))

    # Prefer centered attachments.
    def score(pos):
        hr, hc = pos
        if hr < 0 or hc < 0:
            return 10**9
        if hr + hh > out.shape[0] or hc + hw > out.shape[1]:
            return 10**9
        # center alignment score
        if pos[2] == 0 and pos[3] == 0:
            pass
        # vertical side: center handle vertically on body
        if pos[1] == c0 + bw or pos[1] == c0 - hw:
            return abs((hr + hh / 2) - (r0 + bh / 2))
        # horizontal side: center handle horizontally on body
        return abs((hc + hw / 2) - (c0 + bw / 2))

    candidates.sort(key=score)
    for hr, hc, _, _ in candidates:
        if _place_shape(out, color, handle_shape, hr, hc):
            return True
    return False

def _place_color(out, color, comps):
    if not comps:
        return True
    if len(comps) == 1:
        shape = _shape(comps[0])
        # Try original, then rotations, then mirrored rotations.
        variants = [shape, _rot_cw(shape), _rot_ccw(shape),
                    _mirror_h(shape), _mirror_h(_rot_cw(shape)), _mirror_h(_rot_ccw(shape))]
        H, W = out.shape
        for var in variants:
            for r0 in range(H - var.shape[0] + 1):
                for c0 in range(W - var.shape[1] + 1):
                    if _place_shape(out, color, var, r0, c0):
                        return True
        return False

    # Multiple components: choose the largest as body, the rest as handles.
    comps_sorted = sorted(comps, key=len, reverse=True)
    body = _shape(comps_sorted[0])
    handles = [_shape(c) for c in comps_sorted[1:]]

    # Candidate body orientations.
    body_variants = [body, _rot_cw(body), _rot_ccw(body),
                     _mirror_h(body), _mirror_h(_rot_cw(body)), _mirror_h(_rot_ccw(body))]

    H, W = out.shape
    for bvar in body_variants:
        for r0 in range(H - bvar.shape[0] + 1):
            for c0 in range(W - bvar.shape[1] + 1):
                if not _place_shape(out, color, bvar, r0, c0):
                    continue
                ok = True
                for hshape in handles:
                    if not _attach(out, color, bvar, hshape, r0, c0):
                        ok = False
                        break
                if ok:
                    return True
    return False

def transform(grid: list[list[int]]) -> list[list[int]]:
    a = np.array(grid, dtype=int)
    H, W = a.shape
    out = np.zeros((H, W), dtype=int)

    colors = sorted({int(v) for v in a.flat if v != 8})

    # Build components for each color.
    comps_by_color = {}
    for color in colors:
        mask = (a == color)
        comps_by_color[color] = _components(mask)

    # Place colors in a stable order.  In the examples, smaller/simple colors
    # are placed first, then larger composite colors.
    def color_order(color):
        comps = comps_by_color[color]
        total = sum(len(c) for c in comps)
        maxc = max(len(c) for c in comps)
        return (total, maxc, color)

    for color in sorted(colors, key=color_order):
        _place_color(out, color, comps_by_color[color])

    return out.tolist()

import numpy as np
from collections import deque

def _components(mask):
