def _rot_ccw(arr):
    return np.rot90(arr, k=1)

def _mirror_h(arr):
    return arr[:, ::-1]

def _variants(shape):
    base = [shape, _rot_cw(shape), _rot_ccw(shape), _mirror_h(shape)]
    out = []
    seen = set()
    for v in base:
        key = v.tobytes()
        if key not in seen:
            seen.add(key)
            out.append(v)
    return out

def _place_shape(out, color, shape, r0, c0):
    h, w = out.shape
    if r0 < 0 or c0 < 0 or r0 + shape.shape[0] > h or c0 + shape.shape[1] > w:
