        hr, hc = pos
        if hr < 0 or hc < 0 or hr + hh > H or hc + hw > W:
            return 10**9
        # Prefer centered attachments.
        if hc == c0 + bw or hc == c0 - hw:
            return abs((hr + hh / 2.0) - (r0 + bh / 2.0))
        return abs((hc + hw / 2.0) - (c0 + bw / 2.0))

    candidates.sort(key=score)
    for hr, hc in candidates:
