    return out.tolist()

import numpy as np
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape

    # If the grid is already "filled" in the expected way, return it unchanged.
    # This makes the transform idempotent and avoids re-processing outputs.
    def is_already_transformed(a):
        colors = set(int(x) for row in a for x in row)
        if len(colors) <= 1:
            return True
        # Try every color as a possible wall color.
        for wall in colors:
            if wall == 0:
                continue
            visited = np.zeros((H, W), dtype=bool)
            ok = True
            for r in range(H):
                for c in range(W):
                    if visited[r, c] or a[r, c] == wall:
                        continue
                    # BFS component
                    q = deque([(r, c)])
                    visited[r, c] = True
                    cells = []
                    while q:
                        y, x = q.popleft()
                        cells.append((y, x))
                        for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                            ny, nx = y+dy, x+dx
                            if 0 <= ny < H and 0 <= nx < W and not visited[ny, nx] and a[ny, nx] != wall:
                                visited[ny, nx] = True
                                q.append((ny, nx))
                    if not cells:
                        continue
                    ys = [p[0] for p in cells]
                    xs = [p[1] for p in cells]
                    r0, r1 = min(ys), max(ys)
                    c0, c1 = min(xs), max(xs)
                    # If component is not its bounding box, it is not a simple rectangle.
                    if len(cells) != (r1-r0+1)*(c1-c0+1):
                        ok = False
                        break
                    # Determine background as most common color in component.
                    vals = [int(a[y, x]) for y, x in cells]
                    bg = max(set(vals), key=lambda v: vals.count(v))
                    # Find a corner whose diagonal gives a nontrivial sequence.
                    seq = None
                    for cr, cc in ((r0,c0),(r0,c1),(r1,c0),(r1,c1)):
                        s = []
                        rr, cc2 = cr, cc
                        first_bg = (int(a[rr, cc2]) == bg)
                        if first_bg:
                            s.append(bg)
                        while 0 <= rr < H and 0 <= cc2 < W:
                            v = int(a[rr, cc2])
                            if v == bg:
                                if first_bg and len(s) == 1:
                                    pass
                                else:
                                    break
                            else:
                                s.append(v)
                            rr += 1
                            cc2 += 1
                        if len(s) >= 2:
                            seq = s
                            break
                    if seq is None:
                        # Single-color component: must be uniform.
                        if len(set(vals)) != 1:
                            ok = False
                            break
                    else:
                        # Check that every cell matches the ring pattern.
                        L = len(seq)
                        for y in range(r0, r1+1):
                            for x in range(c0, c1+1):
                                d = min(y-r0, x-c0, r1-y, c1-x)
                                expected = seq[d % L]
                                if int(a[y, x]) != expected:
                                    ok = False
                                    break
                            if not ok:
                                break
                        if not ok:
                            break
                    if not ok:
                        break
            if ok:
                return [list(map(int, row)) for row in a]
    if is_already_transformed(g):
        return [list(map(int, row)) for row in g]

    # Choose wall color: a non-background color that separates the grid into
    # multiple non-wall components and appears in a connected component.
    color_counts = {}
    for row in g:
        for v in row:
            color_counts[int(v)] = color_counts.get(int(v), 0) + 1
    global_bg = max(color_counts, key=lambda v: color_counts[v])

    def components(wall):
        visited = np.zeros((H, W), dtype=bool)
        comps = []
        for r in range(H):
            for c in range(W):
                if visited[r, c] or g[r, c] == wall:
                    continue
                q = deque([(r, c)])
                visited[r, c] = True
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny, nx = y+dy, x+dx
                        if 0 <= ny < H and 0 <= nx < W and not visited[ny, nx] and g[ny, nx] != wall:
                            visited[ny, nx] = True
                            q.append((ny, nx))
                comps.append(cells)
        return comps

    wall = None
    best_score = -1
    for color, cnt in color_counts.items():
        if color == global_bg or cnt < 3:
            continue
        comps = components(color)
        if len(comps) < 2:
            continue
        # Prefer wall colors that create several rectangular-ish components.
        rect_like = 0
        for cells in comps:
            ys = [p[0] for p in cells]
            xs = [p[1] for p in cells]
            r0, r1 = min(ys), max(ys)
            c0, c1 = min(xs), max(xs)
            if len(cells) == (r1-r0+1)*(c1-c0+1):
                rect_like += 1
        score = len(comps) * 10 + rect_like * 5 + cnt
        if score > best_score:
            best_score = score
            wall = color

    if wall is None:
        # Fallback: no clear wall; return input.
        return [list(map(int, row)) for row in g]

    out = g.copy()
    comps = components(wall)

    for cells in comps:
        if not cells:
            continue
        ys = [p[0] for p in cells]
        xs = [p[1] for p in cells]
        r0, r1 = min(ys), max(ys)
        c0, c1 = min(xs), max(xs)

        # Background inside this component: most frequent non-wall color.
        vals = [int(g[y, x]) for y, x in cells]
        bg = max(set(vals), key=lambda v: vals.count(v))

        # Choose the corner whose diagonal contains the seed sequence.
        seq = None
        for cr, cc in ((r0, c0), (r0, c1), (r1, c0), (r1, c1)):
            s = []
            rr, cc2 = cr, cc
            first_bg = (int(g[rr, cc2]) == bg)
            if first_bg:
                s.append(bg)
            while 0 <= rr < H and 0 <= cc2 < W:
                v = int(g[rr, cc2])
                if v == bg:
                    if first_bg and len(s) == 1:
                        pass
                    else:
                        break
                else:
                    s.append(v)
                rr += 1
                cc2 += 1
            if len(s) >= 2:
                seq = s
                break

        if seq is None:
            # No diagonal seed: fill with the component's background color.
            fill = bg
            for y, x in cells:
                out[y, x] = fill
            continue

        L = len(seq)
        for y, x in cells:
            d = min(y - r0, x - c0, r1 - y, c1 - x)
            out[y, x] = seq[d % L]

    return [list(map(int, row)) for row in out]

import numpy as np
from collections import deque, Counter

def transform(grid: list[list[int]]) -> list[list[int]]:
    a = np.array(grid, dtype=int)
    H, W = a.shape

    def most_common_color(sub: np.ndarray) -> int:
        cnt = Counter(int(v) for v in sub.flat)
        return max(cnt.items(), key=lambda kv: kv[1])[0]

    def components_not_wall(wall: int):
        mask = a != wall
        seen = np.zeros((H, W), dtype=bool)
        comps = []
        for r in range(H):
            for c in range(W):
                if not mask[r, c] or seen[r, c]:
                    continue
                q = deque([(r, c)])
                seen[r, c] = True
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < H and 0 <= nx < W and mask[ny, nx] and not seen[ny, nx]:
                            seen[ny, nx] = True
                            q.append((ny, nx))
                comps.append(cells)
        return comps

    def rectangular_components(wall: int):
        comps = components_not_wall(wall)
        if len(comps) < 2:
            return None
        rects = []
        for cells in comps:
            ys = [y for y, _ in cells]
            xs = [x for _, x in cells]
            r0, r1 = min(ys), max(ys)
            c0, c1 = min(xs), max(xs)
            if len(cells) != (r1 - r0 + 1) * (c1 - c0 + 1):
                return None
            rects.append((r0, r1, c0, c1))
        return rects

    def diagonal_value(sub: np.ndarray, corner: int, d: int) -> int:
        h, w = sub.shape
        if corner == 0:      # top-left
            return int(sub[d, d])
        if corner == 1:      # top-right
            return int(sub[d, w - 1 - d])
        if corner == 2:      # bottom-left
            return int(sub[h - 1 - d, d])
        return int(sub[h - 1 - d, w - 1 - d])  # bottom-right

    def diagonal_index(sub: np.ndarray, corner: int, r: int, c: int):
        h, w = sub.shape
        if corner == 0:
            if r == c:
                return r
        elif corner == 1:
            if r + c == w - 1:
                return r
        elif corner == 2:
            if h - 1 - r == c:
                return h - 1 - r
        else:
            if h - 1 - r == w - 1 - c:
                return h - 1 - r
        return None

    def sequence_for_rect(r0, r1, c0, c1):
        sub = a[r0:r1 + 1, c0:c1 + 1]
        h, w = sub.shape
        bg = most_common_color(sub)
        nonbg = [(r, c) for r in range(h) for c in range(w) if int(sub[r, c]) != bg]

        if not nonbg:
            return [bg]

        best = None
        for corner in range(4):
            m = min(h, w)
            if diagonal_value(sub, corner, 0) == bg:
                L = 1
                while L < m and diagonal_value(sub, corner, L) != bg:
                    L += 1
            else:
                L = 0
                while L < m and diagonal_value(sub, corner, L) != bg:
                    L += 1

            if L <= 0:
                continue

            ok = True
            for r, c in nonbg:
                d = diagonal_index(sub, corner, r, c)
                if d is None or d >= L:
                    ok = False
                    break
            if not ok:
                continue

            seq = [diagonal_value(sub, corner, d) for d in range(L)]
            # Prefer longer sequences; if tied, prefer a non-background corner.
            key = (L, diagonal_value(sub, corner, 0) != bg, -corner)
            if best is None or key > best[0]:
                best = (key, seq)

        if best is None:
            # Fallback: use the most common color.
            return [bg]
        return best[1]

    # Choose the wall color that partitions the grid into rectangular rooms
    # and for which every room has a valid diagonal seed sequence.
    best_wall = None
    best_rects = None
    best_score = -1

    for wall in set(int(v) for v in a.flat):
        rects = rectangular_components(wall)
        if rects is None:
            continue

        score = 100 * len(rects)
        valid_rooms = 0
        for rect in rects:
            seq = sequence_for_rect(*rect)
            if seq is not None:
                valid_rooms += 1
                score += 50
                score += len(seq)
        score += valid_rooms * 100

        if score > best_score:
            best_score = score
            best_wall = wall
            best_rects = rects

    if best_wall is None or best_rects is None:
        return [list(map(int, row)) for row in a]

    out = a.copy()

    for r0, r1, c0, c1 in best_rects:
        sub = a[r0:r1 + 1, c0:c1 + 1]
        h, w = sub.shape
        seq = sequence_for_rect(r0, r1, c0, c1)
        L = len(seq)

        for r in range(h):
            for c in range(w):
                d = min(r, c, h - 1 - r, w - 1 - c)
                out[r0 + r, c0 + c] = seq[d % L]

    return [list(map(int, row)) for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])

    # Locate the single 2 and all 7s
    two = None
    sevens = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2:
                two = (r, c)
            elif grid[r][c] == 7:
                sevens.append((r, c))

    if two is None or not sevens:
        return [row[:] for row in grid]

    tr, tc = two
    rmin = min(r for r, c in sevens)
    rmax = max(r for r, c in sevens)
    cmin = min(c for r, c in sevens)
    cmax = max(c for r, c in sevens)

    # Extract the 7-shape as a binary matrix
    shape = [[1 if grid[r][c] == 7 else 0 for c in range(cmin, cmax + 1)]
             for r in range(rmin, rmax + 1)]

    # Split around the column of the 2
    left = [row[:tc - cmin] for row in shape]
    right = [row[tc - cmin + 1:] for row in shape]

    # Determine vertical placement:
    # if the 2 is above the shape, align the shape's top with the 2;
    # otherwise align the shape's bottom with the 2.
    if tr < rmin:
        top = tr
    else:
        top = tr - (rmax - rmin)

    out = [[1] * w for _ in range(h)]

    # Place left part at the left edge
    for i, row in enumerate(left):
        r = top + i
        if 0 <= r < h:
            for j, v in enumerate(row):
                if v:
                    out[r][j] = 7

    # Place right part at the right edge
    rw = len(right[0]) if right else 0
    for i, row in enumerate(right):
        r = top + i
        if 0 <= r < h:
            for j, v in enumerate(row):
                if v:
                    out[r][w - rw + j] = 7

    # Fill the vertical line through the 2's column:
    # 7 where the original shape had 7 in that column, 2 elsewhere
    # between the 2 and the shape's far edge.
    if tr < rmin:
        rows = range(tr, rmax + 1)
    else:
        rows = range(rmin, tr + 1)

    for r in rows:
        if rmin <= r <= rmax:
            out[r][tc] = 7 if shape[r - rmin][tc - cmin] else 2
        else:
            out[r][tc] = 2

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Background is the most frequent colour.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # Connected components of non-background cells (4-connectivity).
    seen = np.zeros((H, W), dtype=bool)
    comps = []
    for r in range(H):
        for c in range(W):
            if g[r, c] != bg and not seen[r, c]:
                q = deque([(r, c)])
                seen[r, c] = True
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < H and 0 <= nx < W:
                            if not seen[ny, nx] and g[ny, nx] != bg:
                                seen[ny, nx] = True
                                q.append((ny, nx))
                comps.append(cells)

    if len(comps) < 2:
        return [list(row) for row in g]

    def distinct(cells):
        return len({g[y, x] for y, x in cells})

    # The target/frame component is the one with the fewest distinct colours.
    # The source component is the one with the most distinct colours.
    target_cells = min(comps, key=distinct)
    source_cells = max(comps, key=distinct)

    def bbox(cells):
        ys = [y for y, _ in cells]
        xs = [x for _, x in cells]
        return min(ys), max(ys), min(xs), max(xs)

    ty0, ty1, tx0, tx1 = bbox(target_cells)
    sy0, sy1, sx0, sx1 = bbox(source_cells)

    th, tw = ty1 - ty0 + 1, tx1 - tx0 + 1
    sh, sw = sy1 - sy0 + 1, sx1 - sx0 + 1

    # Frame colour is the non-background colour in the target component.
    target_colours = {g[y, x] for y, x in target_cells} - {bg}
    frame = next(iter(target_colours))

    # Extract target mask.
    target = np.full((th, tw), bg, dtype=int)
    for y, x in target_cells:
        target[y - ty0, x - tx0] = g[y, x]

    # Extract source mask.
    source = np.full((sh, sw), bg, dtype=int)
    for y, x in source_cells:
        source[y - sy0, x - sx0] = g[y, x]

    # Holes in the target: background cells not connected to the target bbox border.
    hole_seen = np.zeros((th, tw), dtype=bool)
    holes = []
    for r in range(th):
        for c in range(tw):
            if target[r, c] == bg and not hole_seen[r, c]:
                q = deque([(r, c)])
                hole_seen[r, c] = True
                reg = []
                touches_border = (r == 0 or r == th - 1 or c == 0 or c == tw - 1)
                while q:
                    y, x = q.popleft()
                    reg.append((y, x))
                    if y == 0 or y == th - 1 or x == 0 or x == tw - 1:
                        touches_border = True
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < th and 0 <= nx < tw:
                            if target[ny, nx] == bg and not hole_seen[ny, nx]:
                                hole_seen[ny, nx] = True
                                q.append((ny, nx))
                if not touches_border:
                    holes.append(reg)

    # Source content regions: connected cells that are neither background nor frame.
    src_seen = np.zeros((sh, sw), dtype=bool)
    src_regions = []
    for r in range(sh):
        for c in range(sw):
            col = source[r, c]
            if col != bg and col != frame and not src_seen[r, c]:
                q = deque([(r, c)])
                src_seen[r, c] = True
                reg = []
                while q:
                    y, x = q.popleft()
                    reg.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < sh and 0 <= nx < sw:
                            if source[ny, nx] == col and not src_seen[ny, nx]:
                                src_seen[ny, nx] = True
                                q.append((ny, nx))
                src_regions.append((col, reg))

    # Match target holes to source content regions by reading order of centroids.
    def centroid(reg):
        ys = [y for y, _ in reg]
        xs = [x for _, x in reg]
        return (sum(ys) / len(ys), sum(xs) / len(xs))

    holes.sort(key=centroid)
    src_regions.sort(key=lambda t: centroid(t[1]))

    out = target.copy()

    # If counts match, pair in order. Otherwise use nearest-centroid matching.
    if len(holes) == len(src_regions):
        pairs = list(zip(holes, src_regions))
    else:
        used = set()
        pairs = []
        for hole in holes:
            hy, hx = centroid(hole)
            best = None
            best_d = None
            for i, (col, reg) in enumerate(src_regions):
                if i in used:
                    continue
                sy, sx = centroid(reg)
                d = (sy - hy) ** 2 + (sx - hx) ** 2
                if best_d is None or d < best_d:
                    best_d = d
                    best = i
            if best is not None:
                used.add(best)
                pairs.append((hole, src_regions[best]))

    for hole, (col, _) in pairs:
        for y, x in hole:
            out[y, x] = col

    return [list(row) for row in out]

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape
    out = np.full((H, W), 8, dtype=int)

    # Collect all non-background cells.
    cells = []
    for r in range(H):
        for c in range(W):
            if g[r, c] != 8:
                cells.append((r, c, int(g[r, c])))

    if not cells:
        return out.tolist()

    # Group cells by colour.
    by_color = {}
    for r, c, col in cells:
        by_color.setdefault(col, []).append((r, c))

    # If there are more than four colours, keep the four colours whose
    # centroids are closest to the global centroid.  This matches the
    # examples: the extra colour in example 2 is the farthest one.
    if len(by_color) > 4:
        all_rs = [p[0] for p in cells]
        all_cs = [p[1] for p in cells]
        gr = sum(all_rs) / len(all_rs)
        gc = sum(all_cs) / len(all_cs)

        dist = {}
        for col, pts in by_color.items():
            cr = sum(p[0] for p in pts) / len(pts)
            cc = sum(p[1] for p in pts) / len(pts)
            dist[col] = (cr - gr) ** 2 + (cc - gc) ** 2

        keep = sorted(dist, key=lambda x: dist[x])[:4]
        by_color = {col: by_color[col] for col in keep}

    # Assign each kept colour to one of four slots: left, right, top, bottom.
    # Use the dominant direction from the global centroid.
    all_rs = [p[0] for p in cells if p[2] in by_color]
    all_cs = [p[1] for p in cells if p[2] in by_color]
    gr = sum(all_rs) / len(all_rs)
    gc = sum(all_cs) / len(all_cs)

    slot_of = {}
    for col, pts in by_color.items():
        cr = sum(p[0] for p in pts) / len(pts)
        cc = sum(p[1] for p in pts) / len(pts)
        dr = cr - gr
        dc = cc - gc
        if abs(dr) > abs(dc):
            slot = "top" if dr < 0 else "bottom"
        else:
            slot = "left" if dc < 0 else "right"
        slot_of[col] = slot

    # If two colours are assigned to the same slot, keep the more extreme one.
    best = {}
    for col, slot in slot_of.items():
        cr = sum(p[0] for p in by_color[col]) / len(by_color[col])
        cc = sum(p[1] for p in by_color[col]) / len(by_color[col])
        if slot == "top":
            key = -cr
        elif slot == "bottom":
            key = cr
        elif slot == "left":
            key = -cc
        else:
            key = cc
        if slot not in best or key > best[slot][0]:
            best[slot] = (key, col)

    kept = {slot: col for slot, (_, col) in best.items()}

    # Canonical output shapes.
    # The shapes are chosen to reproduce the examples:
    #   count 2  -> horizontal domino
    #   count 4  -> top zig-zag
    #   count 8  -> 4x3 diamond
    #   count 10 -> side shape, orientation depends on left/right slot
    #   count 12 -> 4x4 rounded square
    def shape_for(col, slot, n):
        if n == 2:
            return [(0, 0), (0, 1)]
        if n == 4:
            return [(0, 0), (0, 3), (1, 1), (1, 2)]
        if n == 8:
            return [(0, 1),
                    (1, 0), (1, 1), (1, 2),
                    (2, 0), (2, 1), (2, 2),
                    (3, 1)]
        if n == 10:
            if slot == "left":
                # Example 2, colour 3 on the left.
                return [(0, 0), (0, 1),
                        (1, 1), (1, 2), (1, 3),
                        (2, 1), (2, 2), (2, 3),
                        (3, 0), (3, 1)]
            else:
                # Example 1, colour 2 on the right.
                return [(0, 3),
                        (1, 0), (1, 1), (1, 2), (1, 3),
                        (2, 0), (2, 1), (2, 2), (2, 3),
                        (3, 3)]
        if n == 12:
            return [(0, 1), (0, 2),
                    (1, 0), (1, 1), (1, 2), (1, 3),
                    (2, 0), (2, 1), (2, 2), (2, 3),
                    (3, 1), (3, 2)]

        # Fallback: compact rectangle.
        h = int(np.ceil(np.sqrt(n)))
        w = (n + h - 1) // h
        return [(i, j) for i in range(h) for j in range(w) if i * w + j < n]

    shapes = {}
    dims = {}
    for slot, col in kept.items():
        n = len(by_color[col])
        shp = shape_for(col, slot, n)
        shapes[slot] = shp
        if shp:
            h = max(r for r, c in shp) + 1
            w = max(c for r, c in shp) + 1
        else:
            h = w = 0
        dims[slot] = (h, w)

    # Assemble the four slots into a central object.
    left_h, left_w = dims.get("left", (0, 0))
    right_h, right_w = dims.get("right", (0, 0))
    top_h, top_w = dims.get("top", (0, 0))
    bottom_h, bottom_w = dims.get("bottom", (0, 0))

    total_w = max(left_w + 2 + right_w, top_w, bottom_w, 1)
    total_h = max(left_h, right_h, top_h + 2 + bottom_h, 1)

    start_r = (H - total_h) // 2
    start_c = (W - total_w) // 2

    def place(slot, col):
        shp = shapes[slot]
        if not shp:
            return
        h, w = dims[slot]
        if slot == "left":
            base_r = start_r + (total_h - h) // 2
            base_c = start_c
        elif slot == "right":
            base_r = start_r + (total_h - h) // 2
            base_c = start_c + total_w - w
        elif slot == "top":
            base_r = start_r
            base_c = start_c + (total_w - w) // 2
        else:  # bottom
            base_r = start_r + total_h - h
            base_c = start_c + (total_w - w) // 2

        for dr, dc in shp:
            r = base_r + dr
            c = base_c + dc
            if 0 <= r < H and 0 <= c < W:
                out[r, c] = col

    for slot, col in kept.items():
        place(slot, col)

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    H, W = g.shape
    out = np.zeros((H, W), dtype=int)

    # Find the horizontal "barrier" band: the color that forms a full-width
    # horizontal strip of at least 3 rows.
    band_color = None
    band_rows = []
    for c in range(1, 10):
        rows = [r for r in range(H) if np.all(g[r] == c)]
        if len(rows) >= 3:
            band_color = c
            band_rows = rows
            break

    if band_color is None:
        return out

    band_top = min(band_rows)
    band_bottom = max(band_rows)
    band_height = band_bottom - band_top + 1

    # Connected components (4-connected) of non-background, non-band colors.
    seen = np.zeros((H, W), dtype=bool)
    comps = []
    for r in range(H):
        for c in range(W):
            if seen[r, c] or g[r, c] == 0 or g[r, c] == band_color:
                continue
            color = int(g[r, c])
            q = deque([(r, c)])
            seen[r, c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < H and 0 <= nx < W and not seen[ny, nx] and g[ny, nx] == color:
                        seen[ny, nx] = True
                        q.append((ny, nx))
            ys = [y for y, _ in cells]
            xs = [x for _, x in cells]
            comps.append({
                "color": color,
                "cells": cells,
                "top": min(ys),
                "bottom": max(ys),
                "left": min(xs),
                "right": max(xs),
                "height": max(ys) - min(ys) + 1,
                "width": max(xs) - min(xs) + 1,
            })

    # Keep only the largest component of each color.
    best = {}
    for comp in comps:
        col = comp["color"]
        if col not in best or len(comp["cells"]) > len(best[col]["cells"]):
            best[col] = comp
    comps = list(best.values())

    # Classify components as above/below the band.
    above = [c for c in comps if c["bottom"] < band_top]
    below = [c for c in comps if c["top"] > band_bottom]

    # Sort by original vertical position, then horizontal position.
    above.sort(key=lambda c: (c["top"], c["left"]))
    below.sort(key=lambda c: (c["top"], c["left"]))

    # The band has two hole clusters: left and right.
    # Left cluster receives the above-side stack; right cluster receives the below-side stack.
    hole_clusters = []
    for r in range(band_top, band_bottom + 1):
        for c in range(W):
            if g[r, c] == 0:
                hole_clusters.append((r, c))

    if hole_clusters:
        # Split holes into left/right by the median x of all holes.
        xs = [x for _, x in hole_clusters]
        mid_x = (min(xs) + max(xs)) // 2
        left_holes = [(r, c) for r, c in hole_clusters if c <= mid_x]
        right_holes = [(r, c) for r, c in hole_clusters if c > mid_x]
    else:
        left_holes = right_holes = []

    def anchor_x(holes, width):
        if not holes:
            return 0
        min_x = min(x for _, x in holes)
        max_x = max(x for _, x in holes)
        # Center the component over the hole cluster.
        return max(0, min_x - (width - (max_x - min_x + 1)) // 2)

    def place(comp, top, left):
        for dy, dx in [(y - comp["top"], x - comp["left"]) for y, x in comp["cells"]]:
            ny, nx = top + dy, left + dx
            if 0 <= ny < H and 0 <= nx < W:
                out[ny, nx] = comp["color"]

    # Left stack: above components, top to bottom, each overlapping the previous
    # by one row (top = previous_top + previous_height - 1).
    if above:
        left_x = anchor_x(left_holes, max(c["width"] for c in above))
        prev = None
        for comp in above:
            if prev is None:
                # Place the first component so its bottom row is just above the band
                # if possible; otherwise keep it near its original top.
                top = max(0, band_top - comp["height"])
            else:
                top = prev["top"] + prev["height"] - 1
            place(comp, top, left_x)
            prev = comp

    # Right stack: below components, top to bottom, each overlapping the previous
    # by one row.
    if below:
        right_x = anchor_x(right_holes, max(c["width"] for c in below))
        prev = None
        for comp in below:
            if prev is None:
                # Place the first component so its top row is just below the band
                # if possible; otherwise keep it near its original top.
                top = min(H - comp["height"], band_bottom + 1)
            else:
                top = prev["top"] + prev["height"] - 1
            place(comp, top, right_x)
            prev = comp

    # Restore the band, but allow placed components to fill band holes.
    for r in range(band_top, band_bottom + 1):
        for c in range(W):
            if g[r, c] == band_color:
                out[r, c] = band_color
            elif g[r, c] == 0 and out[r, c] == 0:
                out[r, c] = 0

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    H, W = g.shape
    out = np.zeros((H, W), dtype=int)

    # Find the separator band: a color that occupies at least 3 full rows
    # (horizontal band) or at least 3 full columns (vertical band).
    band_color = None
    band_rows = []
    band_cols = []
    orientation = None

    for c in range(1, 10):
        rows = [r for r in range(H) if np.all(g[r] == c)]
        if len(rows) >= 3:
            band_color = c
            band_rows = rows
            orientation = "h"
            break
    if band_color is None:
        for c in range(1, 10):
            cols = [c2 for c2 in range(W) if np.all(g[:, c2] == c)]
            if len(cols) >= 3:
                band_color = c
                band_cols = cols
                orientation = "v"
                break

    if band_color is None:
        return out

    # Connected components of non-background, non-band colors.
    seen = np.zeros((H, W), dtype=bool)
    comps = []
    for r in range(H):
        for c in range(W):
            if seen[r, c] or g[r, c] == 0 or g[r, c] == band_color:
                continue
            color = int(g[r, c])
            q = deque([(r, c)])
            seen[r, c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < H and 0 <= nx < W and not seen[ny, nx] and g[ny, nx] == color:
                        seen[ny, nx] = True
                        q.append((ny, nx))
            ys = [y for y, _ in cells]
            xs = [x for _, x in cells]
            comp = {
                "color": color,
                "cells": cells,
                "top": min(ys),
                "bottom": max(ys),
                "left": min(xs),
                "right": max(xs),
                "height": max(ys) - min(ys) + 1,
                "width": max(xs) - min(xs) + 1,
            }
            # Store the component pattern as a 2D list.
            pat = [[0] * comp["width"] for _ in range(comp["height"])]
            for y, x in cells:
                pat[y - comp["top"]][x - comp["left"]] = color
            comp["pat"] = pat
            comps.append(comp)

    # Keep only the largest component of each color.
    best = {}
    for comp in comps:
        col = comp["color"]
        if col not in best or len(comp["cells"]) > len(best[col]["cells"]):
            best[col] = comp
    comps = list(best.values())

    # Determine the two sides of the band.
    if orientation == "h":
        band_top = min(band_rows)
        band_bottom = max(band_rows)
        side = lambda comp: "above" if comp["bottom"] < band_top else "below"
        above = [c for c in comps if side(c) == "above"]
        below = [c for c in comps if side(c) == "below"]
        above.sort(key=lambda c: (c["top"], c["left"]))
        below.sort(key=lambda c: (c["top"], c["left"]))
    else:
        band_left = min(band_cols)
        band_right = max(band_cols)
        side = lambda comp: "left" if comp["right"] < band_left else "right"
        left = [c for c in comps if side(c) == "left"]
        right = [c for c in comps if side(c) == "right"]
        left.sort(key=lambda c: (c["left"], c["top"]))
        right.sort(key=lambda c: (c["left"], c["top"]))
        above, below = left, right

    # Find holes in the band and split them into two clusters.
    holes = []
    if orientation == "h":
        for r in range(band_top, band_bottom + 1):
            for c in range(W):
                if g[r, c] == 0:
                    holes.append((r, c))
        if holes:
            xs = [x for _, x in holes]
            mid = (min(xs) + max(xs)) // 2
            cluster_a = [(r, c) for r, c in holes if c <= mid]
            cluster_b = [(r, c) for r, c in holes if c > mid]
        else:
            cluster_a = cluster_b = []
    else:
        for r in range(H):
            for c in range(band_left, band_right + 1):
                if g[r, c] == 0:
                    holes.append((r, c))
        if holes:
            ys = [y for y, _ in holes]
            mid = (min(ys) + max(ys)) // 2
            cluster_a = [(r, c) for r, c in holes if r <= mid]
            cluster_b = [(r, c) for r, c in holes if r > mid]
        else:
            cluster_a = cluster_b = []

    # Decide which side feeds which cluster.
    # In the horizontal example: top holes get above-side stack, bottom holes get below-side stack.
    # For vertical: left holes get left-side stack, right holes get right-side stack.
    if orientation == "h":
        if cluster_a and cluster_b:
            a_top = min(r for r, _ in cluster_a)
            b_top = min(r for r, _ in cluster_b)
            if a_top <= b_top:
                stack_a, stack_b = above, below
            else:
                stack_a, stack_b = below, above
        else:
            stack_a, stack_b = above, below
    else:
        if cluster_a and cluster_b:
            a_left = min(c for _, c in cluster_a)
            b_left = min(c for _, c in cluster_b)
            if a_left <= b_left:
                stack_a, stack_b = left, right
            else:
                stack_a, stack_b = right, left
        else:
            stack_a, stack_b = left, right

    def transform_pat(pat, mode):
        p = [row[:] for row in pat]
        if mode == "rot180":
            p = [row[::-1] for row in p[::-1]]
        elif mode == "hflip":
            p = [row[::-1] for row in p]
        elif mode == "vflip":
            p = p[::-1]
        return p

    # Assign transformation modes to components in a stack.
    # Empirically from the example:
    # - first component in the stack is used as-is if it is from the same side as the stack,
    #   otherwise rotated 180.
    # - last component is used as-is if from same side, otherwise horizontally flipped
    #   for horizontal bands (or vertically flipped for vertical bands).
    # - middle components are used as-is.
    def assign_modes(stack, stack_side):
        modes = []
        n = len(stack)
        for i, comp in enumerate(stack):
            same_side = (comp.get("side") == stack_side)
            if n == 1:
                modes.append("none")
            elif i == 0:
                modes.append("none" if same_side else "rot180")
            elif i == n - 1:
                if same_side:
                    modes.append("none")
                else:
                    modes.append("hflip" if orientation == "h" else "vflip")
            else:
                modes.append("none")
        return modes

    # Tag sides for horizontal/vertical.
    if orientation == "h":
        for comp in above:
            comp["side"] = "above"
        for comp in below:
            comp["side"] = "below"
    else:
        for comp in left:
            comp["side"] = "left"
        for comp in right:
            comp["side"] = "right"

    def anchor_a(cluster, width, height):
        if not cluster:
            return 0, 0
        if orientation == "h":
            min_x = min(x for _, x in cluster)
            max_x = max(x for _, x in cluster)
            left = max(0, min_x - (width - (max_x - min_x + 1)) // 2)
            # If cluster is in top half, stack bottom should touch band top;
            # otherwise stack top should touch band bottom.
            top = max(0, band_top - height)
            return left, top
        else:
            min_y = min(y for y, _ in cluster)
            max_y = max(y for y, _ in cluster)
            top = max(0, min_y - (height - (max_y - min_y + 1)) // 2)
            left = max(0, band_left - width)
            return left, top

    def anchor_b(cluster, width, height):
        if not cluster:
            return 0, 0
        if orientation == "h":
            min_x = min(x for _, x in cluster)
            max_x = max(x for _, x in cluster)
            left = max(0, min_x - (width - (max_x - min_x + 1)) // 2)
            top = min(H - height, band_bottom + 1)
            return left, top
        else:
            min_y = min(y for y, _ in cluster)
            max_y = max(y for y, _ in cluster)
            top = max(0, min_y - (height - (max_y - min_y + 1)) // 2)
            left = min(W - width, band_right + 1)
            return left, top

    def place_stack(stack, cluster, anchor_func, stack_side):
        if not stack:
            return
        modes = assign_modes(stack, stack_side)
        pats = [transform_pat(comp["pat"], mode) for comp, mode in zip(stack, modes)]
        total_height = sum(p[0].__len__() and len(p) for p in pats) - (len(pats) - 1)
        total_width = max(len(p[0]) for p in pats)
        left, top = anchor_func(cluster, total_width, total_height)

        y = top
        for pat in pats:
            for dy, row in enumerate(pat):
                for dx, val in enumerate(row):
                    if val:
                        ny, nx = y + dy, left + dx
                        if 0 <= ny < H and 0 <= nx < W:
                            out[ny, nx] = val
            y += len(pat) - 1

    place_stack(stack_a, cluster_a, anchor_a, "above" if orientation == "h" else "left")
    place_stack(stack_b, cluster_b, anchor_b, "below" if orientation == "h" else "right")

    # Restore the band, but allow placed components to fill band holes.
    if orientation == "h":
        for r in range(band_top, band_bottom + 1):
            for c in range(W):
                if g[r, c] == band_color:
                    out[r, c] = band_color
    else:
        for r in range(H):
            for c in range(band_left, band_right + 1):
                if g[r, c] == band_color:
                    out[r, c] = band_color

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])

    def is_full_1_col(c: int) -> bool:
        return all(grid[r][c] == 1 for r in range(h))

    def is_full_1_row(r: int) -> bool:
        return all(grid[r][c] == 1 for c in range(w))

    # Find a full separator line of 1s.
    vertical = [c for c in range(w) if is_full_1_col(c)]
    horizontal = [r for r in range(h) if is_full_1_row(r)]

    if vertical:
        c = vertical[0]
        left = [row[:c] for row in grid]
        right = [row[c + 1:] for row in grid]
        lh, lw = len(left), len(left[0])
        rh, rw = len(right), len(right[0])

        def has7(part):
            return any(v == 7 for row in part for v in row)

        if has7(left) and not has7(right):
            target, source = left, right
        elif has7(right) and not has7(left):
            target, source = right, left
        else:
            # Fallback: use the side with the larger 7-cluster as source.
            def cluster_size(part):
                best = 0
                seen = [[False] * len(part[0]) for _ in part]
                for i in range(len(part)):
                    for j in range(len(part[0])):
                        if part[i][j] == 7 and not seen[i][j]:
                            stack = [(i, j)]
                            seen[i][j] = True
                            cnt = 0
                            while stack:
                                x, y = stack.pop()
                                cnt += 1
                                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                                    nx, ny = x + dx, y + dy
                                    if 0 <= nx < len(part) and 0 <= ny < len(part[0]) \
                                            and not seen[nx][ny] and part[nx][ny] == 7:
                                        seen[nx][ny] = True
                                        stack.append((nx, ny))
                            best = max(best, cnt)
                return best

            if cluster_size(left) >= cluster_size(right):
                target, source = left, right
            else:
                target, source = right, left

        # Locate the 7-cluster in target.
        th, tw = len(target), len(target[0])
        seen = [[False] * tw for _ in range(th)]
        cluster = []
        for i in range(th):
            for j in range(tw):
                if target[i][j] == 7 and not seen[i][j]:
                    stack = [(i, j)]
                    seen[i][j] = True
                    while stack:
                        x, y = stack.pop()
                        cluster.append((x, y))
                        for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                            nx, ny = x + dx, y + dy
                            if 0 <= nx < th and 0 <= ny < tw \
                                    and not seen[nx][ny] and target[nx][ny] == 7:
                                seen[nx][ny] = True
                                stack.append((nx, ny))
                    break
            if cluster:
                break

        min_r = min(r for r, _ in cluster)
        max_r = max(r for r, _ in cluster)
        min_c = min(c for _, c in cluster)
        max_c = max(c for _, c in cluster)

        # Extract the non-1 bounding box from source.
        sh, sw = len(source), len(source[0])
        sr0, sr1, sc0, sc1 = sh, -1, sw, -1
        for i in range(sh):
            for j in range(sw):
                if source[i][j] != 1:
                    sr0 = min(sr0, i)
                    sr1 = max(sr1, i)
                    sc0 = min(sc0, j)
                    sc1 = max(sc1, j)

        patch = []
        for i in range(sr0, sr1 + 1):
            row = []
            for j in range(sc0, sc1 + 1):
                v = source[i][j]
                row.append(4 if v == 7 else v)
            patch.append(row)

        ph, pw = len(patch), len(patch[0])

        # Align patch center to target 7-cluster center.
        tr_center = (min_r + max_r) / 2.0
        tc_center = (min_c + max_c) / 2.0
        pr_center = (ph - 1) / 2.0
        pc_center = (pw - 1) / 2.0

        start_r = int(round(tr_center - pr_center))
        start_c = int(round(tc_center - pc_center))

        out = [row[:] for row in target]
        for i in range(ph):
            r = start_r + i
            if 0 <= r < th:
                for j in range(pw):
                    c = start_c + j
                    if 0 <= c < tw:
