                                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                                    nx, ny = x + dx, y + dy
                                    if 0 <= nx < len(part) and 0 <= ny < len(part[0]) \
                                            and not seen[nx][ny] and part[nx][ny] == 7:
                                        seen[nx][ny] = True
                                        stack.append((nx, ny))
                            best = max(best, cnt)
                return best

            if cluster_size(top) >= cluster_size(bottom):
                target, source = top, bottom
            else:
