        ph, pw = len(patch), len(patch[0])

        tr_center = (min_r + max_r) / 2.0
        tc_center = (min_c + max_c) / 2.0
        pr_center = (ph - 1) / 2.0
        pc_center = (pw - 1) / 2.0

        start_r = int(round(tr_center - pr_center))
