    full_rows = [r for r in range(h) if all(grid[r][c] == 1 for c in range(w))]
    full_cols = [c for c in range(w) if all(grid[r][c] == 1 for r in range(h))]

    horizontal = len(full_rows) >= len(full_cols)

    def crop_active(panel):
        rows = [r for r in range(len(panel)) if any(panel[r][c] != 0 for c in range(len(panel[0])))]
        cols = [c for c in range(len(panel[0])) if any(panel[r][c] != 0 for r in range(len(panel)))]
        if not rows or not cols:
            return [[0] * len(panel[0]) for _ in panel]
        r0, r1 = rows[0], rows[-1]
        c0, c1 = cols[0], cols[-1]
        return [row[c0:c1 + 1] for row in panel[r0:r1 + 1]]

    def solid_color(panel):
        for row in panel:
            for v in row:
                if v not in (0, 1):
                    return v
        return 0

    if horizontal:
        # Panels are stacked vertically: 4, 3, colorA, colorB.
        bounds = [0] + full_rows + [h]
        panels = []
        for i in range(len(bounds) - 1):
            a, b = bounds[i], bounds[i + 1]
            if b > a:
                panels.append(grid[a:b])
        p4, p3, pa, pb = panels[0], panels[1], panels[2], panels[3]
        a_color = solid_color(pa)
        b_color = solid_color(pb)

        a4 = crop_active(p4)
        a3 = crop_active(p3)

        H4, W4 = len(a4), len(a4[0])
        H3, W3 = len(a3), len(a3[0])

        # Build the core pattern in the vertical orientation.
        core = []
        for i in range(H4):
            row = []
            for j in range(W4):
                if a4[i][j] == 4:
                    for k in range(H3):
                        row.append(1 if a3[k][j] == 3 else 0)
                else:
                    for k in range(H3):
                        row.append(0)
            core.append(row)

        # Horizontal input means the final output is transposed.
        out = [[core[r][c] for r in range(len(core))] for c in range(len(core[0]))]
        return [[a_color if v == 0 else b_color for v in row] for row in out]

    else:
        # Panels are arranged horizontally: 4, 3, colorA, colorB.
        bounds = [0] + full_cols + [w]
        panels = []
        for i in range(len(bounds) - 1):
            a, b = bounds[i], bounds[i + 1]
            if b > a:
                panels.append([row[a:b] for row in grid])
        p4, p3, pa, pb = panels[0], panels[1], panels[2], panels[3]
        a_color = solid_color(pa)
        b_color = solid_color(pb)

        a4 = crop_active(p4)
