        H4, W4 = len(a4), len(a4[0])
        H3, W3 = len(a3), len(a3[0])

        core = []
        for i in range(H4):
            row = []
            for j in range(W4):
                if a4[i][j] == 4:
                    for k in range(H3):
                        row.append(1 if a3[k][j] == 3 else 0)
                else:
                    for k in range(H3):
                        row.append(0)
            core.append(row)

        return [[a_color if v == 0 else b_color for v in row] for row in core]

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # The two non-background colours used in the puzzle.
    colors = sorted({int(c) for c in g.flat if c != 0})
    if len(colors) < 2:
        return [[int(x) for x in row] for row in g]

    a, b = colors[0], colors[1]
    other = {a: b, b: a}

    # Find zero components that are locally surrounded by exactly one colour.
    # A component is valid if every non-zero cell adjacent to it has the same colour.
    seen = np.zeros((h, w), dtype=bool)
    valid_zero = np.zeros((h, w), dtype=bool)

    for r in range(h):
        for c in range(w):
            if g[r, c] != 0 or seen[r, c]:
                continue

            stack = [(r, c)]
            seen[r, c] = True
            comp = []
            surround = set()

            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        if dy == 0 and dx == 0:
                            continue
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w:
                            v = g[ny, nx]
                            if v == 0:
                                if not seen[ny, nx]:
                                    seen[ny, nx] = True
                                    stack.append((ny, nx))
                            elif v != 0:
                                surround.add(int(v))

            if len(surround) == 1:
                for y, x in comp:
                    valid_zero[y, x] = True

    out = g.copy()

    # For every valid zero, paint its 3x3 neighbourhood with the opposite colour,
    # then mark the zero itself as 8.
    for r in range(h):
        for c in range(w):
            if valid_zero[r, c]:
                # Determine the surrounding colour from the component's neighbours.
                # It is the only non-zero colour adjacent to this zero component.
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        ny, nx = r + dy, c + dx
                        if 0 <= ny < h and 0 <= nx < w and g[ny, nx] in (a, b):
                            out[r, c] = other[int(g[ny, nx])]
                            break
                    else:
                        continue
                    break

    # Zeros that were valid become 8.
    out[valid_zero] = 8

    return [[int(x) for x in row] for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # The two non-background colours.
    colors = sorted({int(c) for c in g.flat if c != 0})
    if len(colors) < 2:
        return [[int(x) for x in row] for row in out]

    a, b = colors[0], colors[1]
    other = {a: b, b: a}

    # A zero is a "hole" if all non-zero cells in its 3x3 neighbourhood
    # (ignoring zeros and out-of-bounds cells) have the same colour.
    hole = np.zeros((h, w), dtype=bool)
    hole_color = np.zeros((h, w), dtype=int)

    for r in range(h):
        for c in range(w):
            if g[r, c] != 0:
                continue

            seen_colors = set()
            ok = True
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w:
                        v = int(g[nr, nc])
                        if v != 0:
                            seen_colors.add(v)
                            if len(seen_colors) > 1:
                                ok = False
                                break
                if not ok:
                    break

            if ok and len(seen_colors) == 1:
                hole[r, c] = True
                hole_color[r, c] = next(iter(seen_colors))

    # For every hole, paint its 3x3 neighbourhood with the opposite colour.
    for r in range(h):
        for c in range(w):
            if not hole[r, c]:
                continue
            fill = other[int(hole_color[r, c])]
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w:
                        out[nr, nc] = fill

    # Finally mark the holes themselves as 8.
    out[hole] = 8

    return [[int(x) for x in row] for row in out]

