def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Find all 3x3 "plus" objects:
    # the four orthogonal neighbours of the centre are the same non-zero colour,
    # and the centre is a different colour.
    objects = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            b = g[r - 1, c]
            if b == 0:
                continue
            if g[r + 1, c] == b and g[r, c - 1] == b and g[r, c + 1] == b:
                ctr = g[r, c]
                if ctr != b:
                    objects.append((r, c, int(b), int(ctr)))

    # Build directed links: object A points to object B if A's centre colour
    # equals B's border colour.
    by_border = {}
    for i, (r, c, b, ctr) in enumerate(objects):
        by_border.setdefault(b, []).append(i)

    target = [-1] * len(objects)
    for i, (r, c, b, ctr) in enumerate(objects):
        cands = by_border.get(ctr, [])
        if len(cands) == 1:
            target[i] = cands[0]

    indeg = [0] * len(objects)
    for i, t in enumerate(target):
        if t != -1:
            indeg[t] += 1

    # Resolve chains starting from objects with no incoming links.
    # A source keeps its border, takes the centre colour of its target,
    # and the target is erased. Erased objects do not continue their links.
    new_center = [None] * len(objects)
    erased = [False] * len(objects)

    for i in range(len(objects)):
        if indeg[i] == 0 and not erased[i]:
            cur = i
            while cur != -1 and not erased[cur]:
                t = target[cur]
                if t == -1:
                    # No valid target: this object is erased.
                    erased[cur] = True
                    break
                # Current object survives and adopts the target's centre.
                new_center[cur] = objects[t][3]
                # Target is erased and its outgoing link is ignored.
                erased[t] = True
                cur = t

    # Any object not explicitly surviving is erased.
    for i in range(len(objects)):
        if new_center[i] is None:
            erased[i] = True

    out = g.copy()

    for i, (r, c, b, ctr) in enumerate(objects):
        if erased[i]:
            # Erase the centre and all border-coloured perimeter cells.
            out[r, c] = 0
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if dr == 0 and dc == 0:
                        continue
                    rr, cc = r + dr, c + dc
                    if 0 <= rr < h and 0 <= cc < w and out[rr, cc] == b:
                        out[rr, cc] = 0
        else:
            out[r, c] = new_center[i]

    return out.tolist()

