    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Sources are the existing 6 cells.
    sources = np.argwhere(g == 6)
    if len(sources) == 0:
        return out.tolist()

    # Targets are the 2 cells.
    targets = np.argwhere(g == 2)
    if len(targets) == 0:
        return out.tolist()

