    # Ties are broken by smaller source row, then smaller source column.
    best_src = np.empty((len(targets), 2), dtype=int)
    for i, (tr, tc) in enumerate(targets):
        d = np.abs(sources[:, 0] - tr) + np.abs(sources[:, 1] - tc)
        d = d * 1000000 + sources[:, 0] * 1000 + sources[:, 1]
        best_src[i] = sources[np.argmin(d)]

    # A background cell becomes 6 iff it lies on at least one shortest
    # Manhattan path from its assigned target to that target's best source.
    for (tr, tc), (sr, sc) in zip(targets, best_src):
        if tr == sr and tc == sc:
            continue

        # All shortest paths from (tr, tc) to (sr, sc) stay inside the
        # axis-aligned rectangle with these opposite corners.
        r0, r1 = sorted((tr, sr))
