    # The separator is the vertical line of 4s.
    sep = None
    for c in range(W):
        if all(grid[r][c] == 4 for r in range(H)):
            sep = c
            break
    if sep is None:
        sep = W // 2

    # Find the starting 5 in the right half.
    start_r = start_c = None
    for r in range(H):
        for c in range(sep + 1, W):
            if grid[r][c] == 5:
                start_r = r
                start_c = c - (sep + 1)
                break
        if start_r is not None:
            break

    # Identify 3x3 glyph blocks in the left half.
    blocks = []
    for r in range(0, H - 2, 4):
        for c in (0, 4):
            vals = []
            ok = True
            for dr in range(3):
                for dc in range(3):
                    v = grid[r + dr][c + dc]
                    if v not in (0, 1, 2, 3, 6):
                        ok = False
                    vals.append(v)
            if not ok:
                continue
            nonzeros = [v for v in vals if v != 0]
            if not nonzeros:
                continue
            color = nonzeros[0]
            if all(v == color for v in nonzeros):
                blocks.append((r, c, color))

    # Order blocks by row, then left-to-right.
    blocks.sort(key=lambda x: (x[0], x[1]))

    # Move semantics inferred from examples:
    # 2 -> horizontal left, length 2
    # 1 -> horizontal right, length 3
    # 3 -> horizontal left, length 4
    # 6 -> vertical down, length 2
    moves = []
    for _, _, color in blocks:
        if color == 2:
            moves.append(('L', 2))
        elif color == 1:
            moves.append(('R', 3))
        elif color == 3:
            moves.append(('L', 4))
        elif color == 6:
            moves.append(('D', 2))

    out = [[0] * 7 for _ in range(H)]
    r, c = start_r, start_c
    out[r][c] = 5

    for kind, length in moves:
        if kind == 'D':
            for i in range(1, length + 1):
                nr = r + i
                if 0 <= nr < H and 0 <= c < 7:
                    out[nr][c] = 6
            r += length
        else:
