                    if 0 <= r < H and 0 <= nc < 7:
                        out[r][nc] = 2 if kind == 'L' and length == 2 else 3
            else:
                for i in range(length):
                    nc = c + i
                    if 0 <= r < H and 0 <= nc < 7:
                        out[r][nc] = 1
            c += -length if kind == 'L' else length

    return out

