        for c in range(sep + 1, W):
            if grid[r][c] == 5:
                sr, sc = r, c - (sep + 1)
                break
        if sr is not None:
            break

    # Extract 3x3 command blocks from the left half.
    # Blocks are aligned in 3-row bands separated by one blank row,
    # and in two 3-column slots separated by one blank column.
    blocks = []
    for br in range(0, H - 2, 4):
        for bc in (0, 4):
            vals = []
            ok = True
            for dr in range(3):
                for dc in range(3):
                    v = grid[br + dr][bc + dc]
                    if v not in (0, 1, 2, 3, 6):
                        ok = False
                    vals.append(v)
            if not ok:
                continue
            nz = [v for v in vals if v != 0]
            if not nz:
                continue
            color = nz[0]
            if all(v == color for v in nz):
                blocks.append((br, bc, color))

    # Reading order: top-to-bottom, left-to-right.
    blocks.sort(key=lambda x: (x[0], x[1]))

    # Command semantics:
    # 2 -> horizontal left, length 2
    # 1 -> horizontal right, length 3
    # 3 -> horizontal left, length 4
    # 6 -> vertical down, length 2
    out = [[0] * 7 for _ in range(H)]
    if sr is not None and 0 <= sc < 7:
        out[sr][sc] = 5

    r, c = sr, sc
    for _, _, color in blocks:
        if color == 2:
            r += 1
            for i in range(2):
                nc = c - i
                if 0 <= r < H and 0 <= nc < 7:
                    out[r][nc] = 2
            c -= 1
        elif color == 1:
            r += 1
            for i in range(3):
                nc = c + i
                if 0 <= r < H and 0 <= nc < 7:
                    out[r][nc] = 1
            c += 2
        elif color == 3:
            r += 1
            for i in range(4):
                nc = c - i
                if 0 <= r < H and 0 <= nc < 7:
                    out[r][nc] = 3
            c -= 3
        elif color == 6:
            for i in range(2):
                nr = r + 1 + i
                if 0 <= nr < H and 0 <= c < 7:
                    out[nr][c] = 6
            r += 2

    return out

import numpy as np
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Find the color-mapping table:
    # a solid rectangular component of non-zero cells, with one side length 2.
    mapping = {}
    visited = np.zeros((h, w), dtype=bool)

    for r in range(h):
        for c in range(w):
            if g[r, c] == 0 or visited[r, c]:
                continue

            # BFS over all non-zero cells to get one connected component.
            q = deque([(r, c)])
            visited[r, c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not visited[ny, nx] and g[ny, nx] != 0:
                        visited[ny, nx] = True
                        q.append((ny, nx))

            ys = [y for y, _ in cells]
            xs = [x for _, x in cells]
            y0, y1 = min(ys), max(ys)
            x0, x1 = min(xs), max(xs)
            ch, cw = y1 - y0 + 1, x1 - x0 + 1

            # Must be a completely filled rectangle.
            if g[y0:y1 + 1, x0:x1 + 1].min() == 0:
                continue

            # Must have at least two colors and one dimension equal to 2.
            colors = set(g[y0:y1 + 1, x0:x1 + 1].tolist())
            if len(colors) < 2:
                continue
            if ch != 2 and cw != 2:
                continue

            # Build mapping.  For a 2x2 table, use top-to-bottom.
            if ch == 2:
                for x in range(x0, x1 + 1):
                    key = int(g[y0, x])
                    val = int(g[y1, x])
                    if key != 0:
                        mapping[key] = val
            else:  # cw == 2
                for y in range(y0, y1 + 1):
                    key = int(g[y, x0])
                    val = int(g[y, x1])
                    if key != 0:
                        mapping[key] = val

    # Fill zero holes whose boundary is uniformly one mapped color.
    out = g.copy()
    seen = np.zeros((h, w), dtype=bool)

    for r in range(h):
        for c in range(w):
            if g[r, c] != 0 or seen[r, c]:
                continue

            q = deque([(r, c)])
            seen[r, c] = True
            comp = []
            boundary_colors = set()
            touches_border = (r == 0 or c == 0 or r == h - 1 or c == w - 1)

            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w:
                        if g[ny, nx] == 0:
                            if not seen[ny, nx]:
                                seen[ny, nx] = True
                                q.append((ny, nx))
                        else:
                            boundary_colors.add(int(g[ny, nx]))

            if touches_border:
                continue
            if len(boundary_colors) == 1:
                color = next(iter(boundary_colors))
                if color in mapping:
                    fill = mapping[color]
                    for y, x in comp:
                        out[y, x] = fill

    return out.tolist()

import numpy as np
from collections import deque
from itertools import product

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Find enclosed zero regions and their boundary colors.
    zero_comps = []
    seen = np.zeros((h, w), dtype=bool)

    for r in range(h):
        for c in range(w):
            if g[r, c] != 0 or seen[r, c]:
                continue

            q = deque([(r, c)])
            seen[r, c] = True
            cells = []
            boundary = set()
            touches_border = (r == 0 or c == 0 or r == h - 1 or c == w - 1)

            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w:
                        if g[ny, nx] == 0:
                            if not seen[ny, nx]:
                                seen[ny, nx] = True
                                q.append((ny, nx))
                        else:
                            boundary.add(int(g[ny, nx]))

            if not touches_border:
                zero_comps.append((cells, boundary))

    # Candidate mapping tables: solid non-zero rectangles with one side length 2.
    candidates = []
    visited = np.zeros((h, w), dtype=bool)

    for r in range(h):
        for c in range(w):
            if g[r, c] == 0 or visited[r, c]:
                continue

            q = deque([(r, c)])
            visited[r, c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not visited[ny, nx] and g[ny, nx] != 0:
                        visited[ny, nx] = True
                        q.append((ny, nx))

            ys = [y for y, _ in cells]
            xs = [x for _, x in cells]
            y0, y1 = min(ys), max(ys)
            x0, x1 = min(xs), max(xs)
            ch, cw = y1 - y0 + 1, x1 - x0 + 1

            if ch < 2 or cw < 2:
                continue
            if ch != 2 and cw != 2:
                continue
            if not np.all(g[y0:y1 + 1, x0:x1 + 1] != 0):
                continue
            if len(np.unique(g[y0:y1 + 1, x0:x1 + 1])) < 2:
                continue

            candidates.append((y0, x0, y1, x1))

    if not candidates:
        return out.tolist()

    # Build possible mappings for each candidate.
    possible = []
    for y0, x0, y1, x1 in candidates:
        ch = y1 - y0 + 1
        cw = x1 - x0 + 1

        if ch == 2:
            m = {}
            for x in range(x0, x1 + 1):
                k = int(g[y0, x])
                v = int(g[y1, x])
                if k != 0:
                    m[k] = v
            possible.append((m, 0))  # 0 = top-to-bottom

        if cw == 2:
            m = {}
            for y in range(y0, y1 + 1):
                k = int(g[y, x0])
                v = int(g[y, x1])
                if k != 0:
                    m[k] = v
            possible.append((m, 1))  # 1 = left-to-right

    # If a 2x2 table gives both orientations, choose the better one.
    # Otherwise merge all non-conflicting mappings.
    def score(mapping):
        total = 0
        for cells, boundary in zero_comps:
            if len(boundary) == 1:
                color = next(iter(boundary))
                if color in mapping:
                    total += len(cells)
        return total

    best_mapping = None
    best_score = -1

    # Try all orientation choices for 2x2 candidates.
    n = len(possible)
    for choice in product([0, 1], repeat=n):
        mapping = {}
        ok = True
        for i, (m, _) in enumerate(possible):
            # For non-2x2 candidates, only one mapping exists; choice is ignored.
            for k, v in m.items():
                if k in mapping and mapping[k] != v:
                    ok = False
                    break
                mapping[k] = v
            if not ok:
                break
        if not ok:
            continue

        s = score(mapping)
        if s > best_score:
            best_score = s
            best_mapping = mapping

    if best_mapping is None:
        # Fallback: use the first candidate's first mapping.
        best_mapping = possible[0][0]

    # Apply the chosen mapping to enclosed zero regions.
    for cells, boundary in zero_comps:
        if len(boundary) == 1:
            color = next(iter(boundary))
            if color in best_mapping:
                fill = int(best_mapping[color])
                for y, x in cells:
                    out[y, x] = fill

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Find the most frequent colour as background.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # Collect all non-background cells.
    ys, xs = np.where(g != bg)
    if len(ys) == 0:
        return out.tolist()

    # Connected components using 8-connectivity.
    parent = list(range(len(ys)))

    def find(a):
        while parent[a] != a:
            parent[a] = parent[parent[a]]
            a = parent[a]
        return a

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[rb] = ra

    pos_to_idx = {}
    for i, (y, x) in enumerate(zip(ys, xs)):
        pos_to_idx[(y, x)] = i

    for i, (y, x) in enumerate(zip(ys, xs)):
        for dy in (-1, 0, 1):
            for dx in (-1, 0, 1):
                if dy == 0 and dx == 0:
                    continue
                j = pos_to_idx.get((y + dy, x + dx))
                if j is not None:
                    union(i, j)

    comps = {}
    for i in range(len(ys)):
        comps.setdefault(find(i), []).append(i)

    # A component is a "frame" if it contains both 1 and 2.
    # Payload cells are non-background cells in that component that are not 1 or 2.
    for cells in comps.values():
        colors = {g[ys[i], xs[i]] for i in cells}
        if 1 not in colors or 2 not in colors:
            continue

        # Anchor is the 2-cell(s) in the component.
        anchor_ys = [ys[i] for i in cells if g[ys[i], xs[i]] == 2]
        anchor_xs = [xs[i] for i in cells if g[ys[i], xs[i]] == 2]
        cy = (min(anchor_ys) + max(anchor_ys)) / 2.0
        cx = (min(anchor_xs) + max(anchor_xs)) / 2.0

        # Payload cells.
        payload = []
        for i in cells:
            y, x = ys[i], xs[i]
            c = int(g[y, x])
            if c not in (1, 2):
                payload.append((y, x, c))

        if not payload:
            continue

        # Determine the dominant vertical side of the payload relative to the anchor.
        above = sum(1 for y, x, c in payload if y < cy)
        below = sum(1 for y, x, c in payload if y > cy)

        # If the payload is clearly on one vertical side, reflect it to the opposite side.
        # This handles the Example 1 style frames.
        if above == 0 and below > 0:
            for y, x, c in payload:
                ny = int(round(2 * cy - y))
                nx = x
                if 0 <= ny < h and 0 <= nx < w:
                    out[ny, nx] = c
                    out[y, x] = bg
        elif below == 0 and above > 0:
            for y, x, c in payload:
                ny = int(round(2 * cy - y))
                nx = x
                if 0 <= ny < h and 0 <= nx < w:
                    out[ny, nx] = c
                    out[y, x] = bg
        else:
            # Example 2 style: payload is on the open side of a 1-frame.
            # Recolour payload cells by their vertical distance from the anchor:
            # distance 1 -> 2, distance >= 2 -> 3, except when the payload is
            # already colour 8, in which case it becomes 8 (stable fill colour).
            for y, x, c in payload:
                dist = abs(y - cy)
                if c == 8:
                    nc = 8
                elif dist <= 1:
                    nc = 2
                else:
                    nc = 3
                out[y, x] = nc

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Background is the most frequent colour.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # Connected components of non-background cells, 8-connected.
    ys, xs = np.where(g != bg)
    n = len(ys)
    if n == 0:
        return out.tolist()

    parent = list(range(n))

    def find(a: int) -> int:
        while parent[a] != a:
            parent[a] = parent[parent[a]]
            a = parent[a]
        return a

    def union(a: int, b: int) -> None:
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[rb] = ra

    pos_to_idx = {}
    for i, (y, x) in enumerate(zip(ys, xs)):
        pos_to_idx[(y, x)] = i

    for i, (y, x) in enumerate(zip(ys, xs)):
        for dy in (-1, 0, 1):
            for dx in (-1, 0, 1):
                if dy == 0 and dx == 0:
                    continue
                j = pos_to_idx.get((y + dy, x + dx))
                if j is not None:
                    union(i, j)

    comps = {}
    for i in range(n):
        comps.setdefault(find(i), []).append(i)

    def set_cell(y: int, x: int, c: int) -> None:
        if 0 <= y < h and 0 <= x < w:
            out[y, x] = c

    for cells in comps.values():
        # Component bounding box.
        comp_ys = [ys[i] for i in cells]
        comp_xs = [xs[i] for i in cells]
        y0, y1 = min(comp_ys), max(comp_ys)
        x0, x1 = min(comp_xs), max(comp_xs)

        # Centre of the component.
        cy = (y0 + y1) / 2.0
        cx = (x0 + x1) / 2.0

        # Structure cells are 1 and 2.  The "payload" is the other colour(s).
        payload = []
        for i in cells:
            y, x = ys[i], xs[i]
            c = int(g[y, x])
            if c not in (1, 2):
                payload.append((y, x, c))

        if not payload:
            continue

        # If the payload is a single colour and is exactly one cell/block away
        # from the centre on one side, move it to the opposite side and swap
        # 4 <-> 6.  This covers the first example.
        payload_colors = {c for _, _, c in payload}
        if len(payload_colors) == 1:
            c = next(iter(payload_colors))
            if c in (4, 6):
                py = [y for y, _, _ in payload]
                px = [x for _, x, _ in payload]
                # The payload must be on one vertical side of the centre.
                if all(y < cy for y in py) or all(y > cy for y in py):
                    new_c = 6 if c == 4 else 4
                    for y, x, _ in payload:
                        ny = int(round(2 * cy - y))
                        nx = int(round(2 * cx - x))
                        set_cell(ny, nx, new_c)
                        out[y, x] = bg
                    continue

        # Otherwise, the payload is a bottom/top cap made of two colours.
        # In the examples this toggles between:
        #   state A: near-centre cell(s) are 2, far cell(s) are 3
        #   state B: all cap cell(s) are 8
        # Determine which state is present and toggle it.
        has_2 = any(c == 2 for _, _, c in payload)
        has_3 = any(c == 3 for _, _, c in payload)
        has_8 = any(c == 8 for _, _, c in payload)

        # State A: contains 3 and may contain 2, but not 8.
        if has_3 and not has_8:
            for y, x, _ in payload:
                out[y, x] = 8

        # State B: contains 8 and no 3.
        elif has_8 and not has_3:
            # The cell(s) closest to the centre become 2; the rest become 3.
            # For the observed shapes this is exactly the single near-centre
            # cell/block versus the wider far block.
            # Use vertical distance from the centre as the primary key.
            payload_sorted = sorted(payload, key=lambda t: (abs(t[0] - cy), abs(t[1] - cx)))
            if payload_sorted:
                # The closest payload cell(s) form the near part.
                min_dist = abs(payload_sorted[0][0] - cy)
                for y, x, _ in payload:
                    if abs(y - cy) == min_dist:
                        out[y, x] = 2
                    else:
                        out[y, x] = 3

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return []

    # Determine the background colour.
    # In the given tasks the border is uniformly the background colour.
    # Fall back to the most frequent colour if the border is not uniform.
    border = (
        [grid[0][c] for c in range(len(grid[0]))]
        + [grid[r][0] for r in range(len(grid))]
        + [grid[r][-1] for r in range(len(grid))]
        + [grid[-1][c] for c in range(len(grid[-1]))]
    )
    if all(x == border[0] for x in border):
        bg = border[0]
    else:
        counts = {}
        for row in grid:
            for v in row:
                counts[v] = counts.get(v, 0) + 1
        bg = max(counts, key=lambda k: counts[k])

    h = len(grid)
    w = len(grid[0])
    visited = [[False] * w for _ in range(h)]

    components = []

    for r in range(h):
        for c in range(w):
            if visited[r][c] or grid[r][c] == bg:
                continue

            color = grid[r][c]
            stack = [(r, c)]
            visited[r][c] = True
            cells = []
            top = r
            left = c

            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                if y < top:
                    top = y
                if y == top and x < left:
                    left = x

                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w:
                        if not visited[ny][nx] and grid[ny][nx] == color:
                            visited[ny][nx] = True
                            stack.append((ny, nx))

            components.append((top, left, color, len(cells)))

    # Order objects top-to-bottom, then left-to-right.
    components.sort(key=lambda t: (t[0], t[1]))

    out = []
    for _, _, color, size in components:
        out.extend([[color] for _ in range(size)])

    return out

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape
    out = np.full((H, W), 8, dtype=int)

    def neighbors(r, c):
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < H and 0 <= nc < W:
                yield nr, nc

    # Identify object components made of 1s and 3s.
    obj_id = np.full((H, W), -1, dtype=int)
    objects = []
    for r in range(H):
        for c in range(W):
            if g[r, c] in (1, 3) and obj_id[r, c] == -1:
                oid = len(objects)
                stack = [(r, c)]
                obj_id[r, c] = oid
                cells = []
                while stack:
                    cr, cc = stack.pop()
                    cells.append((cr, cc))
                    for nr, nc in neighbors(cr, cc):
                        if g[nr, nc] in (1, 3) and obj_id[nr, nc] == -1:
                            obj_id[nr, nc] = oid
                            stack.append((nr, nc))
                ones = [p for p in cells if g[p[0], p[1]] == 1]
                threes = [p for p in cells if g[p[0], p[1]] == 3]
                objects.append({"cells": cells, "ones": ones, "threes": threes})

    # Determine exit direction for each object from its 3-cells.
    for obj in objects:
        dr = dc = 0
        if obj["threes"] and obj["ones"]:
            min_r1 = min(r for r, _ in obj["ones"])
            max_r1 = max(r for r, _ in obj["ones"])
            min_c1 = min(c for _, c in obj["ones"])
            max_c1 = max(c for _, c in obj["ones"])

            min_r3 = min(r for r, _ in obj["threes"])
            max_r3 = max(r for r, _ in obj["threes"])
            min_c3 = min(c for _, c in obj["threes"])
            max_c3 = max(c for _, c in obj["threes"])

            if max_r3 < min_r1:
                dr, dc = -1, 0
            elif min_r3 > max_r1:
                dr, dc = 1, 0
            elif max_c3 < min_c1:
                dr, dc = 0, -1
            elif min_c3 > max_c1:
                dr, dc = 0, 1
        obj["dir"] = (dr, dc)

    # Find the starting 4/2 line.
    start_id = np.full((H, W), -1, dtype=int)
    start_cells = []
    four_cells = []
    two_cells = []

    for r in range(H):
        for c in range(W):
            if g[r, c] == 4 and start_id[r, c] == -1:
                stack = [(r, c)]
                start_id[r, c] = 0
                comp = []
                while stack:
                    cr, cc = stack.pop()
                    comp.append((cr, cc))
                    if g[cr, cc] == 4:
                        four_cells.append((cr, cc))
                    elif g[cr, cc] == 2:
                        two_cells.append((cr, cc))
                    for nr, nc in neighbors(cr, cc):
                        if g[nr, nc] in (2, 4) and start_id[nr, nc] == -1:
                            start_id[nr, nc] = 0
                            stack.append((nr, nc))
                start_cells = comp
                break
        if start_cells:
            break

    if not start_cells:
        return out.tolist()

    # Mark the initial line.
    for r, c in start_cells:
        out[r, c] = 2

    # Initial direction: from the 2-tail toward the 4-head.
    if four_cells and two_cells:
        ar4 = sum(r for r, _ in four_cells) / len(four_cells)
        ac4 = sum(c for _, c in four_cells) / len(four_cells)
        ar2 = sum(r for r, _ in two_cells) / len(two_cells)
        ac2 = sum(c for _, c in two_cells) / len(two_cells)
        dr = int(np.sign(ar4 - ar2))
        dc = int(np.sign(ac4 - ac2))
        if dr == 0 and dc == 0:
            dr, dc = -1, 0
    else:
        dr, dc = -1, 0

    front = set(four_cells)
    visited = set()

    while front:
        nxt = set()
        for r, c in front:
            nr, nc = r + dr, c + dc
            if 0 <= nr < H and 0 <= nc < W:
                nxt.add((nr, nc))
        if not nxt:
            break

        hit_objs = set()
        for r, c in nxt:
            oid = obj_id[r, c]
            if oid != -1 and oid not in visited:
                hit_objs.add(oid)

        if hit_objs:
            dirs = []
            new_front = set()
            for oid in hit_objs:
                visited.add(oid)
                obj = objects[oid]
                for r, c in obj["cells"]:
                    out[r, c] = 2
                if obj["dir"] != (0, 0):
                    dirs.append(obj["dir"])
                new_front.update(obj["threes"])

