            if any(obj_id[r, c] != -1 for r, c in nxt):
                break
            for r, c in nxt:
                out[r, c] = 2
            front = nxt

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return []

    h = len(grid)
    w = len(grid[0])
    out = [row[:] for row in grid]

    # Columns that are "active" in the current row.
    # These are 6-cells that have been reached from above or are original 6-cells.
    active = set()

    for r in range(h):
        # Original 6-cells in this row are also active.
        for c in range(w):
            if grid[r][c] == 6:
                active.add(c)

        # Columns that will continue downward into the next row.
        next_active = set()

        # If a cell has a 2 directly below it, it spreads horizontally
        # in the current row until it reaches a column whose cell below is
        # not 2, or the grid boundary.
        for c in list(active):
            if r + 1 < h and grid[r + 1][c] == 2:
                left = c
                while left - 1 >= 0 and grid[r + 1][left - 1] == 2:
                    left -= 1

                right = c
                while right + 1 < w and grid[r + 1][right + 1] == 2:
                    right += 1

                for nc in range(left, right + 1):
                    out[r][nc] = 6
                    active.add(nc)

        # After horizontal spreading, every 6-cell in this row whose cell
        # below is not blocked by 2 continues downward.
        if r + 1 < h:
            for c in range(w):
                if out[r][c] == 6 and grid[r + 1][c] != 2:
                    next_active.add(c)

        active = next_active

    return out

