from collections import Counter

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Find separator rows/columns (full constant lines).  Fallback to the
    # regular 4-pixel period used by the examples.
    def constant_rows(a):
        return [i for i in range(a.shape[0]) if len(np.unique(a[i])) == 1]

    def constant_cols(a):
        return [j for j in range(a.shape[1]) if len(np.unique(a[:, j])) == 1]

    rows = constant_rows(g)
    cols = constant_cols(g)

    # Keep only lines that form a regular grid of 3-cell interiors.
    def regular_lines(lines, n):
        if len(lines) < 2:
            return None
        diffs = [b - a for a, b in zip(lines, lines[1:])]
        if all(d == 4 for d in diffs) and lines[0] == 0 and lines[-1] == n - 1:
            return lines
        return None

    row_lines = regular_lines(rows, h)
    col_lines = regular_lines(cols, w)

    if row_lines is None or col_lines is None:
        # Fallback: standard ARC layout: 0,4,8,...,n-1
        if (h - 1) % 4 == 0 and (w - 1) % 4 == 0:
            row_lines = list(range(0, h, 4))
            col_lines = list(range(0, w, 4))
        else:
            return [list(map(int, row)) for row in grid]

    # Extract all 3x3 macro-cell interiors.
    cells = []
    positions = []
    for r0, r1 in zip(row_lines[:-1], row_lines[1:]):
        for c0, c1 in zip(col_lines[:-1], col_lines[1:]):
            block = g[r0 + 1:r1, c0 + 1:c1]
            if block.shape != (3, 3):
                continue
            cells.append(tuple(tuple(row) for row in block))
            positions.append((len(positions) // len(col_lines), len(positions) % len(col_lines)))

    if not cells:
        return [list(map(int, row)) for row in grid]

    counts = Counter(cells)
    normal_pattern, _ = counts.most_common(1)[0]

    # The special pattern is the most common non-normal pattern.
    special_pattern = None
    special_count = -1
    for pat, cnt in counts.items():
        if pat != normal_pattern and cnt > special_count:
            special_pattern = pat
            special_count = cnt

    if special_pattern is None:
        return [list(map(int, row)) for row in grid]

    # Binary 3x3 mask: positions where the special cell differs from normal.
    mask = [[special_pattern[i][j] != normal_pattern[i][j] for j in range(3)] for i in range(3)]

    # Macro coordinates of currently special cells.
    special_cells = set()
    for idx, pat in enumerate(cells):
        if pat != normal_pattern:
            special_cells.add(positions[idx])

    if not special_cells:
        return [list(map(int, row)) for row in grid]

    macro_h = len(row_lines) - 1
    macro_w = len(col_lines) - 1

    # Find the 3x3 macro offset where the input special cells are a subset
    # of the special pattern's mask.
    candidates = []
    for R in range(max(0, macro_h - 2)):
        for C in range(max(0, macro_w - 2)):
            ok = True
            for r, c in special_cells:
                dr, dc = r - R, c - C
                if not (0 <= dr < 3 and 0 <= dc < 3 and mask[dr][dc]):
                    ok = False
                    break
            if ok:
                candidates.append((R, C))

    if not candidates:
        # Fallback: use the bounding box of special cells as the 3x3 anchor.
        rs = [r for r, _ in special_cells]
        cs = [c for _, c in special_cells]
        R = max(0, min(rs) - 1)
        C = max(0, min(cs) - 1)
        R = min(R, max(0, macro_h - 3))
        C = min(C, max(0, macro_w - 3))
    else:
        # Prefer the candidate that adds the fewest cells; if tied, top-left.
        def score(rc):
            R, C = rc
            added = 0
            for i in range(3):
                for j in range(3):
                    if mask[i][j] and (R + i, C + j) not in special_cells:
                        added += 1
            return (added, R, C)
        R, C = min(candidates, key=score)

    # Build output grid.
    out = g.copy()

    def set_cell(r, c, pattern):
        rr = row_lines[r] + 1
        cc = col_lines[c] + 1
        for i in range(3):
            for j in range(3):
                out[rr + i, cc + j] = pattern[i][j]

    # Fill all foreground macro cells of the 3x3 mask with the special pattern.
    for i in range(3):
        for j in range(3):
            if mask[i][j]:
                set_cell(R + i, C + j, special_pattern)

    return [list(map(int, row)) for row in out]

