    import heapq

    h = len(grid)
    w = len(grid[0])

    # Initial 6 cells are the sources.
    sources = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    if not sources:
        return [row[:] for row in grid]

    # A cell is passable if it is not a 2.
    def passable(r, c):
        return 0 <= r < h and 0 <= c < w and grid[r][c] != 2

    # For each source, compute the shortest path to every passable cell
    # using only moves that do not go upward: left, right, down.
    # This matches the examples, where the drawn 6 network grows downward.
    best = {}
    parent = {}

    for sr, sc in sources:
        dist = {(sr, sc): 0}
        pq = [(0, sr, sc)]
        while pq:
            d, r, c = heapq.heappop(pq)
            if d != dist.get((r, c)):
                continue
            for nr, nc in ((r, c - 1), (r, c + 1), (r + 1, c)):
                if not passable(nr, nc):
                    continue
                nd = d + 1
                if nd < dist.get((nr, nc), 10**18):
                    dist[(nr, nc)] = nd
                    heapq.heappush(pq, (nd, nr, nc))

        for cell, d in dist.items():
            if cell not in best or d < best[cell]:
                best[cell] = d
                parent[cell] = (sr, sc)
            elif d == best[cell]:
                # Tie-break deterministically: prefer the source that is
                # lexicographically smaller, then the cell itself.
                if (sr, sc) < parent[cell]:
                    parent[cell] = (sr, sc)

    # Reconstruct the union of all shortest paths from sources to all cells.
    out = [row[:] for row in grid]
    for r, c in out[0]:
        pass
    out = [[grid[r][c] for c in range(w)] for r in range(h)]

    for cell in best:
        cur = cell
        while True:
            out[cur[0]][cur[1]] = 6
            if cur in parent and parent[cur] != cur:
                cur = parent[cur]
            else:
                break

    return out

