def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Find the 2x2 palette block: four distinct non-zero colours.
    pal = None
    for r in range(h - 1):
        for c in range(w - 1):
            b = g[r:r + 2, c:c + 2]
            vals = b.flatten().tolist()
            if len(set(vals)) == 4 and all(v != 0 for v in vals):
                pal = b
                break
        if pal is not None:
            break

    if pal is None:
        return [row[:] for row in grid]

    tl, tr, bl, br = (int(pal[0, 0]), int(pal[0, 1]),
                      int(pal[1, 0]), int(pal[1, 1]))

    # Connected components of non-zero cells.
    seen = np.zeros((h, w), dtype=bool)
    comps = []
    for i in range(h):
        for j in range(w):
            if g[i, j] != 0 and not seen[i, j]:
                color = g[i, j]
                stack = [(i, j)]
                seen[i, j] = True
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w:
                            if not seen[ny, nx] and g[ny, nx] == color:
                                seen[ny, nx] = True
                                stack.append((ny, nx))
                comps.append((color, cells))

    # The palette block belongs to the component that surrounds/contains it.
    # Merge all palette cells into that component.
    pal_cells = set()
    for dr in range(2):
        for dc in range(2):
            pal_cells.add((r + dr, c + dc))

    main_idx = None
    for idx, (color, cells) in enumerate(comps):
        if any(cell in pal_cells for cell in cells):
            main_idx = idx
            break

    if main_idx is None:
        # Fallback: largest component.
        main_idx = max(range(len(comps)), key=lambda i: len(comps[i][1]))

    main_cells = set(comps[main_idx][1]) | pal_cells
    others = []
    for idx, (color, cells) in enumerate(comps):
        if idx == main_idx:
            continue
        others.append(cells)

    # Sort the three other components by area:
    # smallest -> bottom-left, middle -> top-right, largest -> bottom-right.
    others.sort(key=len)
    bl_cells, tr_cells, br_cells = others

    total = len(main_cells) + len(bl_cells) + len(tr_cells) + len(br_cells)
    n = int(round(total ** 0.5))
    if n * n != total:
        n = int(total ** 0.5)

    out = np.zeros((n, n), dtype=int)

    def place(cells, color, corner):
        pts = sorted(cells)
        min_r = min(r for r, _ in pts)
        min_c = min(c for _, c in pts)
        max_r = max(r for r, _ in pts)
        max_c = max(c for _, c in pts)
        bh = max_r - min_r + 1
        bw = max_c - min_c + 1

        for r, c in pts:
            rr = r - min_r
            cc = c - min_c
            if corner == "TL":
                R, C = rr, cc
            elif corner == "TR":
                R, C = rr, bw - 1 - cc
            elif corner == "BL":
                R, C = bh - 1 - rr, cc
            elif corner == "BR":
                R, C = bh - 1 - rr, bw - 1 - cc
            if 0 <= R < n and 0 <= C < n:
                out[R, C] = color

    place(main_cells, tl, "TL")
    place(tr_cells, tr, "TR")
    place(bl_cells, bl, "BL")
    place(br_cells, br, "BR")

    # Any unfilled cells are filled with the bottom-right palette colour.
    out[out == 0] = br

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return [row[:] for row in grid]

    h = len(grid)
    w = len(grid[0])
    out = [row[:] for row in grid]

    # Start from every existing 6 cell.
    # The 6 "fluid" moves downward. When it is blocked by a 2, it spreads
    # horizontally in the row above the contiguous 2 segment, then continues
    # downward from the open cells on both sides of that segment.
    stack = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]

    while stack:
        r, c = stack.pop()
        if r < 0 or r >= h or c < 0 or c >= w:
            continue
        if grid[r][c] == 2:
            continue

        # Paint the current cell if it is background.
        if grid[r][c] == 7:
            out[r][c] = 6

        # If the cell below is a 2, spread horizontally above that 2 segment.
        if r + 1 < h and grid[r + 1][c] == 2:
            # Find the contiguous 2 segment in the row below.
            left = c
            while left - 1 >= 0 and grid[r + 1][left - 1] == 2:
                left -= 1
            right = c
            while right + 1 < w and grid[r + 1][right + 1] == 2:
                right += 1

            # Paint the horizontal spread just above the segment.
            for cc in range(left, right + 1):
                if grid[r][cc] == 7:
                    out[r][cc] = 6

            # Continue downward from the open cells immediately outside the segment.
            if left - 1 >= 0:
                stack.append((r + 1, left - 1))
            if right + 1 < w:
                stack.append((r + 1, right + 1))
        else:
            # Otherwise continue straight down.
            stack.append((r + 1, c))

    return out

