from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Identify the legend: non-zero, non-5 cells in the upper part.
    legend = {}
    for r in range(h):
        for c in range(w):
            v = g[r, c]
            if v != 0 and v != 5:
                legend.setdefault(v, []).append((r, c))

    # If no legend is present, nothing to do.
    if not legend:
        return out.tolist()

    # Find connected components of 5s (4-connectivity).
    seen = np.zeros((h, w), dtype=bool)
    comps = []
    for r in range(h):
        for c in range(w):
            if g[r, c] == 5 and not seen[r, c]:
                q = deque([(r, c)])
                seen[r, c] = True
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and not seen[ny, nx] and g[ny, nx] == 5:
                            seen[ny, nx] = True
                            q.append((ny, nx))
                comps.append(cells)

    # For each legend color, compute a simple shape signature:
    # normalized bounding-box mask, area, and hole count.
    def mask_signature(cells):
        if not cells:
            return None
        ys = [p[0] for p in cells]
        xs = [p[1] for p in cells]
        y0, y1 = min(ys), max(ys)
        x0, x1 = min(xs), max(xs)
        hh, ww = y1 - y0 + 1, x1 - x0 + 1
        m = np.zeros((hh, ww), dtype=bool)
        for y, x in cells:
            m[y - y0, x - x0] = True
        # Count holes: background components not touching border.
        holes = 0
        bg = ~m
        visited = np.zeros_like(bg)
        for i in range(hh):
            for j in range(ww):
                if bg[i, j] and not visited[i, j]:
                    q = deque([(i, j)])
                    visited[i, j] = True
                    touches_border = (i == 0 or i == hh - 1 or j == 0 or j == ww - 1)
                    while q:
                        a, b = q.popleft()
                        if a == 0 or a == hh - 1 or b == 0 or b == ww - 1:
                            touches_border = True
                        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                            na, nb = a + dy, b + dx
                            if 0 <= na < hh and 0 <= nb < ww and bg[na, nb] and not visited[na, nb]:
                                visited[na, nb] = True
                                q.append((na, nb))
                    if not touches_border:
                        holes += 1
        return (m, len(cells), holes)

    legend_sigs = {}
    for color, cells in legend.items():
        sig = mask_signature(cells)
        if sig is not None:
            legend_sigs[color] = sig

    # Score each 5-component against each legend signature.
    def score(comp_cells, sig):
        m, area, holes = sig
        comp_sig = mask_signature(comp_cells)
        if comp_sig is None:
            return -1
        cm, c_area, c_holes = comp_sig
        # Exact mask match is strongest.
        if cm.shape == m.shape and np.array_equal(cm, m):
            return 1000 + (1 if c_holes == holes else 0)
        # Otherwise use area and hole similarity.
        s = 0
        s += 10 * (c_holes == holes)
        s += 5 * (c_area == area)
        # Penalize large area mismatch.
        s -= abs(c_area - area) // 10
        return s

    for cells in comps:
        best_color = None
        best_score = -10**9
        for color, sig in legend_sigs.items():
            sc = score(cells, sig)
            if sc > best_score:
                best_score = sc
                best_color = color

        # If the component is too small or does not match well, erase it.
        # In the examples, valid components are at least 3 cells and match a legend.
        if best_color is not None and best_score >= 0 and len(cells) >= 3:
            for y, x in cells:
                out[y, x] = best_color
        else:
            for y, x in cells:
                out[y, x] = 0

    return out.tolist()

import numpy as np
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Find the legend: small non-zero, non-5 components in the upper part.
    seen = np.zeros((h, w), dtype=bool)
    legend = []
    for r in range(h):
        for c in range(w):
            v = g[r, c]
            if v != 0 and v != 5 and not seen[r, c]:
                q = deque([(r, c)])
                seen[r, c] = True
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and not seen[ny, nx] and g[ny, nx] == v:
                            seen[ny, nx] = True
                            q.append((ny, nx))
                ys = [p[0] for p in cells]
                xs = [p[1] for p in cells]
                hh = max(ys) - min(ys) + 1
                ww = max(xs) - min(xs) + 1
                # Legend templates are compact and not the long separator line.
                if len(cells) <= 20 and hh <= 5 and ww <= 6:
                    legend.append((v, cells))

    if not legend:
        return out.tolist()

    # Find all 5-components.
    seen5 = np.zeros((h, w), dtype=bool)
    comps = []
    for r in range(h):
        for c in range(w):
            if g[r, c] == 5 and not seen5[r, c]:
                q = deque([(r, c)])
                seen5[r, c] = True
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and not seen5[ny, nx] and g[ny, nx] == 5:
                            seen5[ny, nx] = True
                            q.append((ny, nx))
                comps.append(cells)

    def mask(cells):
        ys = [p[0] for p in cells]
        xs = [p[1] for p in cells]
        y0, x0 = min(ys), min(xs)
        hh = max(ys) - y0 + 1
        ww = max(xs) - x0 + 1
        m = np.zeros((hh, ww), dtype=bool)
        for y, x in cells:
            m[y - y0, x - x0] = True
        return m

    def holes(m):
        if m.size == 0:
            return 0
        hh, ww = m.shape
        bg = ~m
        vis = np.zeros_like(bg)
        cnt = 0
        for i in range(hh):
            for j in range(ww):
                if bg[i, j] and not vis[i, j]:
                    q = deque([(i, j)])
                    vis[i, j] = True
                    border = (i == 0 or i == hh - 1 or j == 0 or j == ww - 1)
                    while q:
                        a, b = q.popleft()
                        if a == 0 or a == hh - 1 or b == 0 or b == ww - 1:
                            border = True
                        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                            na, nb = a + dy, b + dx
                            if 0 <= na < hh and 0 <= nb < ww and bg[na, nb] and not vis[na, nb]:
                                vis[na, nb] = True
                                q.append((na, nb))
                    if not border:
                        cnt += 1
        return cnt

    legend_info = []
    for color, cells in legend:
        m = mask(cells)
        legend_info.append((color, m, len(cells), holes(m)))

    def score(comp_cells, info):
        color, lm, larea, lholes = info
        cm = mask(comp_cells)
        carea = len(comp_cells)
        choles = holes(cm)
        s = 0
        if choles == lholes:
            s += 100
        else:
            s -= 50
        s -= abs(carea - larea) // 5
        # Prefer templates with similar aspect ratio.
        lh, lw = lm.shape
        ch, cw = cm.shape
        s -= abs(lh / max(lw, 1) - ch / max(cw, 1)) * 10
        return s

    for cells in comps:
        best_color = None
        best_score = -10**9
        for info in legend_info:
            sc = score(cells, info)
            if sc > best_score:
                best_score = sc
                best_color = info[0]

        if best_color is not None and len(cells) >= 3:
            for y, x in cells:
                out[y, x] = best_color
        else:
            for y, x in cells:
                out[y, x] = 0

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return [row[:] for row in grid]

    h = len(grid)
    w = len(grid[0])
    out = [row[:] for row in grid]

    # Find all maximal vertical runs of 6 in the input.
    # Each run is treated as a seed for a vertical "wire" that is extended
    # downward, detouring around horizontal 2-blocks.
    seeds = []
    r = 0
    while r < h:
        c = 0
        while c < w:
            if grid[r][c] == 6:
                c0 = c
                while c < w and grid[r][c] == 6:
                    c += 1
                r0 = r
                while r + 1 < h and all(grid[r + 1][cc] == 6 for cc in range(c0, c)):
                    r += 1
                seeds.append((r0, r, c0, c - 1))
            else:
                c += 1
        r += 1

    def block_at(row, col):
        """Return (left, right) of the horizontal 2-run containing (row, col),
        or None if the cell is not 2."""
        if row < 0 or row >= h or col < 0 or col >= w or grid[row][col] != 2:
            return None
        l = col
        while l > 0 and grid[row][l - 1] == 2:
            l -= 1
        rr = col
        while rr + 1 < w and grid[row][rr + 1] == 2:
            rr += 1
        return l, rr

    def set6(rr, cc):
        if 0 <= rr < h and 0 <= cc < w and out[rr][cc] != 2:
            out[rr][cc] = 6

    for r0, r1, c0, c1 in seeds:
        # Preserve the original seed run.
        for rr in range(r0, r1 + 1):
            for cc in range(c0, c1):
                set6(rr, cc)

        # Extend each column of the seed run independently downward.
        for start_col in range(c0, c1):
            col = start_col
            row = r1 + 1
            while row < h:
                blk = block_at(row, col)
                if blk is None:
                    set6(row, col)
                    row += 1
                    continue

                left, right = blk
                # Choose a side to go around the 2-block.
                # Prefer the left side if it is inside the grid; otherwise right.
                if left > 0:
                    new_col = left - 1
                    # Fill the row above the block from the chosen side to the
                    # opposite edge of the block (clamped to the grid).
                    fill_l = new_col
                    fill_r = right
                else:
                    new_col = right + 1
                    fill_l = left
                    fill_r = new_col

                if 0 <= new_col < w:
                    if row > 0:
                        for cc in range(max(0, fill_l), min(w, fill_r + 1)):
                            set6(row - 1, cc)
                    set6(row, new_col)
                    col = new_col
                    row += 1
                else:
                    # No possible detour; stop this wire.
                    break

    return out

