        for start_col in range(c0, c1 + 1):
            col = start_col
            row = r1 + 1
            while row < h:
                blk = two_block(row, col)
                if blk is None:
                    set6(row, col)
                    row += 1
                    continue

                left, right = blk

                # Detour around the 2-block.  Prefer the left side if possible,
                # otherwise use the right side.
                if left > 0:
                    new_col = left - 1
                    fill_l = new_col
                    fill_r = right
                else:
                    new_col = right + 1
                    fill_l = left
                    fill_r = new_col

                if 0 <= new_col < w:
                    # Horizontal segment on the row above the block.
                    if row > 0:
                        for cc in range(max(0, fill_l), min(w, fill_r + 1)):
                            set6(row - 1, cc)
                    # Continue below the block in the detour column.
                    set6(row, new_col)
