def transform(grid: list[list[int]]) -> list[list[int]]:
    out = [row[:] for row in grid]
    h = len(grid)
    w = len(grid[0])

    # The puzzle uses a 7x25 grid with a 1-cell border and four 5x5 panels.
    # The fourth panel is filled from the first three panels.
    if h != 7 or w != 25:
        return out

    # Border color is the corner color.
    border = grid[0][0]

    # Interior background is the color filling the initially empty fourth panel.
    bg = grid[1][19]

    # Extract the three source 5x5 panels.
    p1 = [grid[r][1:6] for r in range(1, 6)]
    p2 = [grid[r][7:12] for r in range(1, 6)]
    p3 = [grid[r][13:18] for r in range(1, 6)]

    # The non-background colors in the first three panels.
    c1 = next(v for row in p1 for v in row if v != bg)
    c2 = next(v for row in p2 for v in row if v != bg)
    c3 = next(v for row in p3 for v in row if v != bg)

    # Masks for the three panels.
    m1 = [[1 if v == c1 else 0 for v in row] for row in p1]
    m2 = [[1 if v == c2 else 0 for v in row] for row in p2]
    m3 = [[1 if v == c3 else 0 for v in row] for row in p3]

    # Determine the separator line from panel 1.
    # It is one of: vertical, horizontal, main diagonal, anti-diagonal.
    # The side of the separator containing the extra marker is the side
    # where panel 2 is kept; panel 3 is kept on the opposite side.
    line = None
    marker_side = None

    # Vertical line: a full column of m1.
    for col in range(5):
        if all(m1[r][col] for r in range(5)):
            line = ('v', col)
            # Marker is the first m1 pixel not on the line.
            for r in range(5):
                for cc in range(5):
                    if m1[r][cc] and cc != col:
                        marker_side = 'left' if cc < col else 'right'
                        break
                if marker_side:
                    break
            break

    # Horizontal line: a full row of m1.
    if line is None:
        for row in range(5):
            if all(m1[row][c] for c in range(5)):
                line = ('h', row)
                for rr in range(5):
                    for cc in range(5):
                        if m1[rr][cc] and rr != row:
                            marker_side = 'top' if rr < row else 'bottom'
                            break
                    if marker_side:
                        break
                break

    # Main diagonal: (0,0), (1,1), ..., (4,4).
    if line is None:
        if all(m1[i][i] for i in range(5)):
            line = ('d', None)
            # Marker is the first m1 pixel not on the main diagonal.
            for r in range(5):
                for c in range(5):
                    if m1[r][c] and r != c:
                        # Side: above/left of diagonal is r < c, below/right is r > c.
                        marker_side = 'above' if r < c else 'below'
                        break
                if marker_side:
                    break

    # Anti-diagonal: (0,4), (1,3), ..., (4,0).
    if line is None:
        if all(m1[i][4 - i] for i in range(5)):
            line = ('a', None)
            # Marker is the first m1 pixel not on the anti-diagonal.
            for r in range(5):
                for c in range(5):
                    if m1[r][c] and r + c != 4:
                        # Side: top-left is r + c < 4, bottom-right is r + c > 4.
                        marker_side = 'top-left' if r + c < 4 else 'bottom-right'
                        break
                if marker_side:
                    break

    # Fallback: if detection fails, leave the fourth panel unchanged.
    if line is None or marker_side is None:
        return out

    # Build the output fourth panel.
    result = [[bg] * 5 for _ in range(5)]

    for r in range(5):
        for c in range(5):
            # Decide which side of the separator this cell belongs to.
            # Cells on the separator are considered both sides; panel 2 wins.
            if line[0] == 'v':
                col = line[1]
                if marker_side == 'left':
                    side2 = c <= col
                    side3 = c >= col
                else:  # right
                    side2 = c >= col
                    side3 = c <= col
            elif line[0] == 'h':
                row = line[1]
                if marker_side == 'top':
                    side2 = r <= row
                    side3 = r >= row
                else:  # bottom
                    side2 = r >= row
                    side3 = r <= row
            elif line[0] == 'd':
                if marker_side == 'above':
                    side2 = r <= c
                    side3 = r >= c
                else:  # below
                    side2 = r >= c
                    side3 = r <= c
            else:  # anti-diagonal
                if marker_side == 'top-left':
                    side2 = r + c <= 4
                    side3 = r + c >= 4
                else:  # bottom-right
                    side2 = r + c >= 4
                    side3 = r + c <= 4

            # Panel 2 has priority on the separator.
            if side2 and m2[r][c]:
                result[r][c] = c2
            elif side3 and m3[r][c]:
                result[r][c] = c3

    # Write the computed panel back into the output grid.
    for r in range(5):
        for c in range(5):
            out[1 + r][19 + c] = result[r][c]

    return out

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Find connected components of non-zero cells (4-connectivity).
    seen = np.zeros((H, W), dtype=bool)
    comps = []
    for r in range(H):
        for c in range(W):
            if g[r, c] != 0 and not seen[r, c]:
                stack = [(r, c)]
                seen[r, c] = True
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < H and 0 <= nx < W and not seen[ny, nx] and g[ny, nx] != 0:
                            seen[ny, nx] = True
                            stack.append((ny, nx))
                ys = [p[0] for p in cells]
                xs = [p[1] for p in cells]
                r0, r1 = min(ys), max(ys)
                c0, c1 = min(xs), max(xs)
                h = r1 - r0 + 1
                w = c1 - c0 + 1
                patch = g[r0:r1 + 1, c0:c1 + 1].copy()
                comps.append({
                    'cells': cells,
                    'r0': r0, 'c0': c0,
                    'h': h, 'w': w,
                    'patch': patch,
                    'center': (r0 + r1) / 2.0, (c0 + c1) / 2.0
                })

    if not comps:
        return [[0] * W for _ in range(H)]

    # Build a graph: connect components if their bounding boxes are adjacent
    # and the touching border cells are both 2.
    n = len(comps)
    adj = {i: set() for i in range(n)}

    def border_pairs(a, b):
        # Return list of (cell_a, cell_b) where boxes touch and both cells are 2.
        pairs = []
        ar0, ar1 = a['r0'], a['r0'] + a['h'] - 1
        ac0, ac1 = a['c0'], a['c0'] + a['w'] - 1
        br0, br1 = b['r0'], b['r0'] + b['h'] - 1
        bc0, bc1 = b['c0'], b['c0'] + b['w'] - 1

        # a right touches b left
        if ac1 + 1 == bc0 and not (ar1 < br0 or br1 < ar0):
            for y in range(max(ar0, br0), min(ar1, br1) + 1):
                if g[y, ac1] == 2 and g[y, bc0] == 2:
                    pairs.append(((y, ac1), (y, bc0)))
        # b right touches a left
        if bc1 + 1 == ac0 and not (br1 < ar0 or ar1 < br0):
            for y in range(max(ar0, br0), min(ar1, br1) + 1):
                if g[y, bc1] == 2 and g[y, ac0] == 2:
                    pairs.append(((y, ac0), (y, bc1)))
        # a bottom touches b top
        if ar1 + 1 == br0 and not (ac1 < bc0 or bc1 < ac0):
            for x in range(max(ac0, bc0), min(ac1, bc1) + 1):
                if g[ar1, x] == 2 and g[br0, x] == 2:
                    pairs.append(((ar1, x), (br0, x)))
        # b bottom touches a top
        if br1 + 1 == ar0 and not (bc1 < ac0 or ac1 < bc0):
            for x in range(max(ac0, bc0), min(ac1, bc1) + 1):
                if g[br1, x] == 2 and g[ar0, x] == 2:
                    pairs.append(((ar0, x), (br1, x)))
        return pairs

    for i in range(n):
        for j in range(i + 1, n):
            if border_pairs(comps[i], comps[j]):
                adj[i].add(j)
                adj[j].add(i)

    # Choose a root: component with fewest connections, tie by original position.
    root = min(range(n), key=lambda i: (len(adj[i]), comps[i]['r0'], comps[i]['c0']))

    # BFS to orient the tree.
    parent = {root: None}
    order = [root]
    q = [root]
    while q:
        u = q.pop(0)
        for v in adj[u]:
            if v not in parent:
                parent[v] = u
                order.append(v)
                q.append(v)

    # If graph is not connected, add remaining components as isolated roots.
    for i in range(n):
        if i not in parent:
            parent[i] = None
            order.append(i)

    # Compute relative offsets from root by summing edge vectors.
    offset = {root: (0, 0)}
    for u in order:
        for v in adj[u]:
            if parent.get(v) == u:
                # Vector from u to v in original coordinates.
                dy = comps[v]['r0'] - comps[u]['r0']
                dx = comps[v]['c0'] - comps[u]['c0']
                offset[v] = (offset[u][0] + dy, offset[u][1] + dx)
            elif parent.get(u) == v:
                # Already handled when v is parent? Ensure all nodes get offset.
                pass

    # Fill any missing offsets (should not happen for connected components).
    for i in range(n):
        if i not in offset:
            offset[i] = (0, 0)

    # Normalize offsets so minimum row/col is 0.
    min_r = min(off[0] for off in offset.values())
    min_c = min(off[1] for off in offset.values())
    norm = {i: (off[0] - min_r, off[1] - min_c) for i, off in offset.items()}

    # Determine output canvas size.
    max_r = max(norm[i][0] + comps[i]['h'] for i in range(n))
    max_c = max(norm[i][1] + comps[i]['w'] for i in range(n))
    out = np.zeros((max_r, max_c), dtype=int)

    # Draw components. Later components overwrite earlier ones.
    # Use BFS order from root; this matches the examples' overlap behavior.
    for i in order:
        r, c = norm[i]
        out[r:r + comps[i]['h'], c:c + comps[i]['w']] = comps[i]['patch']

    return out.tolist()

