                        ny, nx = y + dy, x + dx
                        if 0 <= ny < H and 0 <= nx < W and not seen[ny, nx] and g[ny, nx] != 0:
                            seen[ny, nx] = True
                            stack.append((ny, nx))
                ys = [p[0] for p in cells]
                xs = [p[1] for p in cells]
                r0, r1 = min(ys), max(ys)
                c0, c1 = min(xs), max(xs)
                comps.append({
                    'cells': cells,
                    'r0': r0, 'c0': c0,
                    'h': r1 - r0 + 1,
                    'w': c1 - c0 + 1,
                    'patch': g[r0:r1 + 1, c0:c1 + 1].copy(),
                })

    if not comps:
        return [[0] * W for _ in range(H)]

    n = len(comps)

    # Build adjacency: two components are connected if their bounding boxes
    # touch and the touching border cells are both 2.
    adj = {i: set() for i in range(n)}

    def touching_pairs(a, b):
        pairs = []
        ar0, ar1 = a['r0'], a['r0'] + a['h'] - 1
        ac0, ac1 = a['c0'], a['c0'] + a['w'] - 1
        br0, br1 = b['r0'], b['r0'] + b['h'] - 1
        bc0, bc1 = b['c0'], b['c0'] + b['w'] - 1

        if ac1 + 1 == bc0 and not (ar1 < br0 or br1 < ar0):
            for y in range(max(ar0, br0), min(ar1, br1) + 1):
                if g[y, ac1] == 2 and g[y, bc0] == 2:
                    pairs.append(((y, ac1), (y, bc0)))
        if bc1 + 1 == ac0 and not (br1 < ar0 or ar1 < br0):
            for y in range(max(ar0, br0), min(ar1, br1) + 1):
                if g[y, bc1] == 2 and g[y, ac0] == 2:
                    pairs.append(((y, ac0), (y, bc1)))
        if ar1 + 1 == br0 and not (ac1 < bc0 or bc1 < ac0):
            for x in range(max(ac0, bc0), min(ac1, bc1) + 1):
                if g[ar1, x] == 2 and g[br0, x] == 2:
                    pairs.append(((ar1, x), (br0, x)))
        if br1 + 1 == ar0 and not (bc1 < ac0 or ac1 < bc0):
            for x in range(max(ac0, bc0), min(ac1, bc1) + 1):
                if g[br1, x] == 2 and g[ar0, x] == 2:
                    pairs.append(((ar0, x), (br1, x)))
        return pairs

    for i in range(n):
        for j in range(i + 1, n):
            if touching_pairs(comps[i], comps[j]):
                adj[i].add(j)
                adj[j].add(i)

    # Root: least connected, then topmost/leftmost.
    root = min(range(n), key=lambda i: (len(adj[i]), comps[i]['r0'], comps[i]['c0']))

    # BFS tree orientation.
    parent = {root: None}
    order = [root]
    q = deque([root])
    while q:
        u = q.popleft()
        for v in sorted(adj[u]):
            if v not in parent:
                parent[v] = u
                order.append(v)
                q.append(v)

    # Add any disconnected components (should not happen for valid puzzles).
    for i in range(n):
        if i not in parent:
            parent[i] = None
            order.append(i)

    # Relative offsets from root by summing original top-left deltas along tree.
    offset = {root: (0, 0)}
    for u in order:
        for v in adj[u]:
            if parent.get(v) == u:
                dy = comps[v]['r0'] - comps[u]['r0']
                dx = comps[v]['c0'] - comps[u]['c0']
                offset[v] = (offset[u][0] + dy, offset[u][1] + dx)

    for i in range(n):
        if i not in offset:
            offset[i] = (0, 0)

    min_r = min(off[0] for off in offset.values())
    min_c = min(off[1] for off in offset.values())
    norm = {i: (off[0] - min_r, off[1] - min_c) for i, off in offset.items()}

    max_r = max(norm[i][0] + comps[i]['h'] for i in range(n))
    max_c = max(norm[i][1] + comps[i]['w'] for i in range(n))
    out = np.zeros((max_r, max_c), dtype=int)

    # Draw in BFS order; later pieces overwrite earlier ones where they overlap.
    for i in order:
        r, c = norm[i]
        out[r:r + comps[i]['h'], c:c + comps[i]['w']] = comps[i]['patch']

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Determine background as the most frequent colour.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # Connected components (4-neighbour) of non-background cells.
    seen = np.zeros((H, W), dtype=bool)
    comps = []
    for r in range(H):
        for c in range(W):
            if g[r, c] != bg and not seen[r, c]:
                color = int(g[r, c])
                q = deque([(r, c)])
                seen[r, c] = True
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < H and 0 <= nx < W:
                            if not seen[ny, nx] and g[ny, nx] == color:
                                seen[ny, nx] = True
                                q.append((ny, nx))
                comps.append({
                    "color": color,
                    "cells": cells,
                    "size": len(cells),
                    "min_r": min(y for y, _ in cells),
                    "max_r": max(y for y, _ in cells),
                    "min_c": min(x for _, x in cells),
                    "max_c": max(x for _, x in cells),
                })

    if not comps:
        return []

    # The frame is the largest component.
    frame = max(comps, key=lambda c: c["size"])
    fr, fc = frame["min_r"], frame["min_c"]
    fh, fw = frame["max_r"] - fr + 1, frame["max_c"] - fc + 1

    # Build the frame mask and its holes.
    frame_mask = np.zeros((fh, fw), dtype=bool)
    for y, x in frame["cells"]:
        frame_mask[y - fr, x - fc] = True
    holes = [(y, x) for y in range(fh) for x in range(fw) if not frame_mask[y, x]]

    # Candidate pieces: all non-frame components.
    pieces = [c for c in comps if c is not frame]

    # Normalise a component to its bounding-box mask.
    def norm_mask(comp):
        h = comp["max_r"] - comp["min_r"] + 1
        w = comp["max_c"] - comp["min_c"] + 1
        m = np.zeros((h, w), dtype=bool)
        for y, x in comp["cells"]:
            m[y - comp["min_r"], x - comp["min_c"]] = True
        return m

    # All 8 rotations/reflections of a mask.
    def variants(mask):
        res = []
        m = mask
        for _ in range(4):
            res.append(m)
            res.append(np.fliplr(m))
            m = np.rot90(m)
        # de-duplicate
        uniq = []
        for v in res:
            if not any(np.array_equal(v, u) for u in uniq):
                uniq.append(v)
        return uniq

    # Extract a hole region of the same shape as a piece mask.
    def hole_mask_at(hy, hx, ph, pw):
        if hy < 0 or hx < 0 or hy + ph > fh or hx + pw > fw:
            return None
        return np.array([[not frame_mask[hy + i, hx + j] for j in range(pw)]
                         for i in range(ph)], dtype=bool)

    # Try to place pieces into holes, preserving component shape.
    placed = {}
    used_holes = set()
    used_pieces = set()

    # First place pieces whose normalised shape exactly matches a hole region.
    for idx, p in enumerate(pieces):
        pm = norm_mask(p)
        ph, pw = pm.shape
        best = None
        for hy in range(fh - ph + 1):
            for hx in range(fw - pw + 1):
                hm = hole_mask_at(hy, hx, ph, pw)
                if hm is None:
                    continue
                if np.array_equal(hm, pm):
                    # Prefer holes not already used; deterministic by position.
                    if best is None:
                        best = (hy, hx)
        if best is not None:
            hy, hx = best
            placed[(p["color"], idx)] = (hy, hx, pm)
            for i in range(ph):
                for j in range(pw):
                    if pm[i, j]:
                        used_holes.add((hy + i, hx + j))
            used_pieces.add(idx)

    # Remaining holes are filled by remaining pieces, one cell per component cell,
    # in deterministic order. This handles single-cell / small filler pieces.
    remaining_holes = [h for h in holes if h not in used_holes]
    remaining_holes.sort()
    remaining_pieces = [p for i, p in enumerate(pieces) if i not in used_pieces]
    remaining_pieces.sort(key=lambda c: (c["min_r"], c["min_c"], c["color"]))

    # Flatten remaining piece cells in deterministic order.
    filler_cells = []
    for p in remaining_pieces:
        cells = sorted(p["cells"])
        for y, x in cells:
            filler_cells.append((p["color"], y, x))
    filler_cells.sort(key=lambda t: (t[1], t[2], t[0]))

    # If there are more holes than filler cells, repeat filler cells;
    # if fewer, ignore extra filler cells.
    for k, (hy, hx) in enumerate(remaining_holes):
        if k < len(filler_cells):
            color, _, _ = filler_cells[k]
            placed.setdefault(("fill", k), None)
            # Store directly in output later via a map.
            placed[("hole", hy, hx)] = color
        else:
            placed[("hole", hy, hx)] = 0

    # Build output.
    out = np.zeros((fh, fw), dtype=int)
    for y in range(fh):
        for x in range(fw):
            if frame_mask[y, x]:
                out[y, x] = frame["color"]
            else:
                # Check if covered by a placed shaped piece.
                val = 0
                for key, val2 in placed.items():
                    if key[0] == "hole" and key[1] == y and key[2] == x:
                        val = val2
                        break
                out[y, x] = val

    # Overlay shaped pieces (they may have been placed before filler mapping).
    for key, val in placed.items():
        if key[0] == "hole":
            continue
        if val is None:
            continue
        hy, hx, pm = val
        color = key[0] if isinstance(key[0], int) else 0
        for i in range(pm.shape[0]):
            for j in range(pm.shape[1]):
                if pm[i, j]:
                    out[hy + i, hx + j] = color

    return out.tolist()

