    frame = max(comps, key=lambda c: c["size"])
    fr, fc = frame["min_r"], frame["min_c"]
    fh, fw = frame["h"], frame["w"]

    # Frame mask in local coordinates.
    frame_mask = np.zeros((fh, fw), dtype=bool)
    for y, x in frame["cells"]:
        frame_mask[y - fr, x - fc] = True

    # Holes are all non-frame cells inside the frame bounding box.
    holes = [(y, x) for y in range(fh) for x in range(fw) if not frame_mask[y, x]]

    # Pieces are all non-frame components.
    pieces = [c for c in comps if c is not frame]

    def norm_mask(comp):
        h, w = comp["h"], comp["w"]
        m = np.zeros((h, w), dtype=bool)
        for y, x in comp["cells"]:
            m[y - comp["min_r"], x - comp["min_c"]] = True
        return m

    def hole_mask_at(hy, hx, ph, pw):
        if hy < 0 or hx < 0 or hy + ph > fh or hx + pw > fw:
            return None
        return np.array([[not frame_mask[hy + i, hx + j] for j in range(pw)]
                         for i in range(ph)], dtype=bool)

