    remaining_holes = [h for h in holes if h not in used_holes]
    remaining_holes.sort()
    remaining_pieces = [p for i, p in enumerate(pieces) if i not in used_pieces]
    remaining_pieces.sort(key=lambda c: (c["min_r"], c["min_c"], c["color"]))

