        for y, x in p["cells"]:
            filler_cells.append((p["color"], y, x))
    filler_cells.sort(key=lambda t: (t[1], t[2], t[0]))

    hole_fill = {}
    for k, (hy, hx) in enumerate(remaining_holes):
        if k < len(filler_cells):
            hole_fill[(hy, hx)] = filler_cells[k][0]
        else:
            hole_fill[(hy, hx)] = 0

    # Build output.
    out = np.zeros((fh, fw), dtype=int)
    for y in range(fh):
        for x in range(fw):
            if frame_mask[y, x]:
                out[y, x] = frame["color"]
            else:
                out[y, x] = hole_fill.get((y, x), 0)

    # Overlay exact-shape placements.
    for color, hy, hx, pm in placed_shapes:
        for i in range(pm.shape[0]):
            for j in range(pm.shape[1]):
                if pm[i, j]:
                    out[hy + i, hx + j] = color

    return out.tolist()

