    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # 8-connected components of non-zero cells
    seen = np.zeros((h, w), dtype=bool)
    comps = []
    for r in range(h):
        for c in range(w):
            if g[r, c] != 0 and not seen[r, c]:
                color = g[r, c]
                q = deque([(r, c)])
                seen[r, c] = True
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            if dy == 0 and dx == 0:
                                continue
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < h and 0 <= nx < w:
                                if not seen[ny, nx] and g[ny, nx] == color:
                                    seen[ny, nx] = True
                                    q.append((ny, nx))
                comps.append((color, cells))

    # For each component, find other colors inside its bounding box.
    # Those are treated as "contents" to be moved.
    containers = []
    for color, cells in comps:
        rmin = min(r for r, _ in cells)
        rmax = max(r for r, _ in cells)
        cmin = min(c for _, c in cells)
        cmax = max(c for _, c in cells)

        contents = {}
        for r in range(rmin, rmax + 1):
            for c in range(cmin, cmax + 1):
                v = g[r, c]
                if v != 0 and v != color:
                    contents.setdefault(v, []).append((r, c))

        if contents:
            containers.append((color, cells, rmin, cmin, cmax, contents))

    # Remove all content cells.
    for _, _, _, _, _, contents in containers:
        for cells in contents.values():
            for r, c in cells:
                out[r, c] = 0

    # Draw vertical bars above each container.
    for color, cells, rmin, cmin, cmax, contents in containers:
        # Choose the leftmost cell in the top row of the container.
        top_cells = [(r, c) for r, c in cells if r == rmin]
        anchor_c = min(c for _, c in top_cells)

        for s_color, s_cells in contents.items():
            s_rmin = min(r for r, _ in s_cells)
            s_rmax = max(r for r, _ in s_cells)
            length = s_rmax - s_rmin + 1

            # Place immediately above the container, truncated if necessary.
            start = max(0, rmin - length)
            for r in range(start, rmin):
                if 0 <= r < h and 0 <= anchor_c < w:
                    out[r, anchor_c] = s_color

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # 8-connected components of non-zero cells
    seen = np.zeros((h, w), dtype=bool)
    components = []

    for r in range(h):
        for c in range(w):
            if g[r, c] != 0 and not seen[r, c]:
                q = deque([(r, c)])
                seen[r, c] = True
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            if dy == 0 and dx == 0:
                                continue
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < h and 0 <= nx < w:
                                if not seen[ny, nx] and g[ny, nx] != 0:
                                    seen[ny, nx] = True
                                    q.append((ny, nx))
                components.append(cells)

    for cells in components:
        colors = {g[r, c] for r, c in cells}
        if len(colors) < 2:
            continue

        top_row = min(r for r, _ in cells)
        top_cells = [(r, c) for r, c in cells if r == top_row]
        top_colors = {g[r, c] for r, c in top_cells}

        # The container is the color appearing in the component's top row.
        # If several colors appear there, choose the one with the most top cells.
        if len(top_colors) == 1:
            container_color = next(iter(top_colors))
        else:
            counts = {}
            for r, c in top_cells:
                col = g[r, c]
                counts[col] = counts.get(col, 0) + 1
            container_color = max(counts.items(), key=lambda kv: (kv[1], -kv[0]))[0]

        container_cells = [(r, c) for r, c in cells if g[r, c] == container_color]
        content_colors = colors - {container_color}

        # Remove all content cells in this component.
        for r, c in cells:
            if g[r, c] in content_colors:
                out[r, c] = 0

        # For each content color, draw a vertical bar above the container.
        for color in content_colors:
            ccells = [(r, c) for r, c in cells if g[r, c] == color]
            if not ccells:
                continue

            rmin = min(r for r, _ in ccells)
            rmax = max(r for r, _ in ccells)
            height = rmax - rmin + 1

            # Anchor column:
            # Prefer the topmost content cell's column if it lies under a container top cell.
            # Otherwise use the container top cell closest to the content's horizontal center.
            top_content_cols = sorted({c for r, c in ccells if r == rmin})
            container_top_cols = sorted({c for r, c in container_cells if r == top_row})

            anchor = None
            for c in top_content_cols:
                if c in container_top_cols:
                    anchor = c
                    break

            if anchor is None:
                cmin = min(c for _, c in ccells)
                cmax = max(c for _, c in ccells)
                center = (cmin + cmax) / 2.0
                anchor = min(container_top_cols, key=lambda c: (abs(c - center), c))

            start = top_row - height
            for r in range(start, top_row):
                if 0 <= r < h and 0 <= anchor < w:
                    out[r, anchor] = color

    return out.tolist()

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Find the 0 corner.
    zeros = np.argwhere(g == 0)
    if len(zeros) == 0:
        return [[int(x) for x in row] for row in g]

    r0, c0 = zeros[0]

    # Determine the interior rectangle: exclude the border row and border column.
    if r0 == 0:
        row_slice = slice(1, H)
    elif r0 == H - 1:
        row_slice = slice(0, H - 1)
    else:
        row_slice = slice(0, H)

    if c0 == 0:
        col_slice = slice(1, W)
    elif c0 == W - 1:
        col_slice = slice(0, W - 1)
    else:
        col_slice = slice(0, W)

    interior = g[row_slice, col_slice]
    ih, iw = interior.shape

    # Identify border colors: horizontal border color and vertical border color.
    def border_color(cells):
        vals = [int(v) for v in cells if v != 0]
        if not vals:
            return None
        # The border is uniform in the examples; take the most common non-zero.
        from collections import Counter
        return Counter(vals).most_common(1)[0][0]

    if r0 == 0 or r0 == H - 1:
        h_border = border_color(g[r0, :])
    else:
        h_border = None

    if c0 == 0 or c0 == W - 1:
        v_border = border_color(g[:, c0])
    else:
        v_border = None

    # Primary axis is the axis whose border color is 2.
    # If horizontal border is 2, primary is horizontal; otherwise vertical.
    primary_horizontal = (h_border == 2)

    # Connected components of non-8 cells inside the interior.
    visited = np.zeros((ih, iw), dtype=bool)
    blocks = []

    for i in range(ih):
        for j in range(iw):
            if visited[i, j] or interior[i, j] == 8:
                continue

            stack = [(i, j)]
            visited[i, j] = True
            cells = []
            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < ih and 0 <= ny < iw:
                        if not visited[nx, ny] and interior[nx, ny] != 8:
                            visited[nx, ny] = True
                            stack.append((nx, ny))

            ys = [p[0] for p in cells]
            xs = [p[1] for p in cells]
            y0, y1 = min(ys), max(ys)
            x0, x1 = min(xs), max(xs)
            block = interior[y0:y1 + 1, x0:x1 + 1]

            # Convert interior bbox to original grid coordinates.
            oy0 = y0 + (row_slice.start if row_slice.start is not None else 0)
            ox0 = x0 + (col_slice.start if col_slice.start is not None else 0)
            oy1 = y1 + (row_slice.start if row_slice.start is not None else 0)
            ox1 = x1 + (col_slice.start if col_slice.start is not None else 0)

            # Coordinate along an axis measured away from the 0 corner.
            def start_coord_vertical(ya, yb):
                if r0 == 0:
                    return ya
                elif r0 == H - 1:
                    return H - 1 - yb
                else:
                    return ya

            def start_coord_horizontal(xa, xb):
                if c0 == 0:
                    return xa
                elif c0 == W - 1:
                    return W - 1 - xb
                else:
                    return xa

            if primary_horizontal:
                primary_key = start_coord_horizontal(ox0, ox1)
                secondary_key = start_coord_vertical(oy0, oy1)
            else:
                primary_key = start_coord_vertical(oy0, oy1)
                secondary_key = start_coord_horizontal(ox0, ox1)

            blocks.append((primary_key, secondary_key, block))

    if not blocks:
        return []

    # Sort by primary axis, then secondary axis.
    blocks.sort(key=lambda t: (t[0], t[1]))

    # Normalize each block to 2 rows.
    normalized = []
    for _, _, b in blocks:
        bh, bw = b.shape

        if primary_horizontal:
            # The 2-thickness should be horizontal. If it is vertical, rotate CCW.
            if bw == 2 and bh != 2:
                nb = np.rot90(b, k=1)
            elif bh == 2:
                nb = b
            else:
                # Fallback: make height 2 by cropping/padding.
                if bh > 2:
                    nb = b[:2, :]
                else:
                    nb = np.zeros((2, bw), dtype=int)
                    nb[:bh, :] = b
        else:
            # The 2-thickness should be vertical. If it is horizontal, rotate CCW.
            if bh == 2:
                nb = b
            elif bw == 2:
                nb = np.rot90(b, k=1)
            else:
                if bh > 2:
                    nb = b[:2, :]
                else:
                    nb = np.zeros((2, bw), dtype=int)
                    nb[:bh, :] = b

        normalized.append(nb)

    out_w = max(b.shape[1] for b in normalized)

    out_rows = []
    for b in normalized:
        bh, bw = b.shape
        if bw < out_w:
            pad = out_w - bw
            left = pad // 2
            right = pad - left
            row0 = np.concatenate([np.full(left, 8), b[0], np.full(right, 8)])
            row1 = np.concatenate([np.full(left, 8), b[1], np.full(right, 8)])
        else:
            row0 = b[0]
            row1 = b[1]

        out_rows.append([int(x) for x in row0])
        out_rows.append([int(x) for x in row1])

    return out_rows

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Background is the most common colour.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # Find the sparse "legend" in the top-left:
    # non-background pixels on odd rows/cols starting at (1,1).
    legend_rows = []
    for r in range(1, H, 2):
        row_vals = []
        for c in range(1, W, 2):
            v = int(g[r, c])
            if v != bg:
                row_vals.append(v)
            else:
                row_vals.append(None)
        if any(v is not None for v in row_vals):
            legend_rows.append(row_vals)
        else:
            break

    if not legend_rows:
        return [list(map(int, row)) for row in g]

    M = len(legend_rows)
    N = max(len(row) for row in legend_rows)
    for row in legend_rows:
        while len(row) < N:
            row.append(None)

    # Find candidate block sizes from non-background components outside the legend.
    def components(mask):
        seen = np.zeros_like(mask, dtype=bool)
        comps = []
        for i in range(H):
            for j in range(W):
                if mask[i, j] and not seen[i, j]:
                    stack = [(i, j)]
                    seen[i, j] = True
                    cells = []
                    while stack:
                        y, x = stack.pop()
                        cells.append((y, x))
                        for dy in (-1, 0, 1):
                            for dx in (-1, 0, 1):
                                ny, nx = y + dy, x + dx
                                if 0 <= ny < H and 0 <= nx < W:
                                    if mask[ny, nx] and not seen[ny, nx]:
                                        seen[ny, nx] = True
                                        stack.append((ny, nx))
                    ys = [p[0] for p in cells]
                    xs = [p[1] for p in cells]
                    comps.append((min(ys), min(xs), max(ys), max(xs), cells))
        return comps

    nonbg = g != bg
    comps = components(nonbg)

    # Legend bounding box (single pixels).
    legend_cells = [(r, c) for r in range(1, H, 2) for c in range(1, W, 2) if g[r, c] != bg]
    if legend_cells:
        lr0 = min(r for r, c in legend_cells)
        lr1 = max(r for r, c in legend_cells)
        lc0 = min(c for r, c in legend_cells)
        lc1 = max(c for r, c in legend_cells)
    else:
        lr0 = lr1 = lc0 = lc1 = -1

    def outside_legend(comp):
        r0, c0, r1, c1, cells = comp
        # Ignore components that are only legend pixels.
        if r0 >= lr0 and r1 <= lr1 and c0 >= lc0 and c1 <= lc1:
            return False
        # If it overlaps the legend bounding box, require most cells outside.
        if r0 <= lr1 and r1 >= lr0 and c0 <= lc1 and c1 >= lc0:
            outside = sum(1 for (r, c) in cells if not (lr0 <= r <= lr1 and lc0 <= c <= lc1))
            return outside > len(cells) / 2
        return True

    block_comps = [comp for comp in comps if outside_legend(comp)]

    # Determine block size from square components.
    S = None
    for r0, c0, r1, c1, cells in block_comps:
        h = r1 - r0 + 1
        w = c1 - c0 + 1
        if h == w and h > 1 and len(cells) == h * w:
            if S is None or h > S:
                S = h

    if S is None:
        # Fallback: use the largest square component size, or 1.
        for r0, c0, r1, c1, cells in block_comps:
            h = r1 - r0 + 1
            w = c1 - c0 + 1
            if h == w:
                S = max(S or 1, h)
        if S is None:
            S = 1

    # Collect all square block components of size S.
    blocks = []
    for r0, c0, r1, c1, cells in block_comps:
        h = r1 - r0 + 1
        w = c1 - c0 + 1
        if h == S and w == S and len(cells) == S * S:
            # Uniform colour?
            col = int(g[r0, c0])
            if np.all(g[r0:r0 + S, c0:c0 + S] == col):
                blocks.append((r0, c0, col))

    if not blocks:
        return [list(map(int, row)) for row in g]

    # Infer horizontal pitch from blocks in the same row.
    by_row = {}
    for r, c, col in blocks:
        by_row.setdefault(r, []).append((c, col))

    pitch_col = None
    for r, items in by_row.items():
        cs = sorted(c for c, _ in items)
        if len(cs) >= 2:
            diffs = [cs[i + 1] - cs[i] for i in range(len(cs) - 1)]
            # Use the smallest positive difference as pitch.
            pitch_col = min(d for d in diffs if d > 0)
            break

    if pitch_col is None:
        pitch_col = S + 1

    # Infer vertical pitch.
    # If multiple block rows exist, use their spacing.
    rows = sorted(by_row.keys())
    pitch_row = None
    if len(rows) >= 2:
        diffs = [rows[i + 1] - rows[i] for i in range(len(rows) - 1)]
        pitch_row = min(d for d in diffs if d > 0)

    if pitch_row is None:
        # Usually the same as horizontal pitch, except when the examples show
        # a vertical pitch of S + 2 while horizontal is S + 1.
        # Use a conservative rule: if horizontal pitch is S + 1 and the seed row
        # is at the top of the grid, allow S + 2 only when it keeps the canvas
        # inside the grid and matches the legend height better.
        if pitch_col == S + 1 and rows and rows[0] <= 1:
            # Try S + 2 if it fits and S + 1 would not use the available space
            # as in Example 3.
            if rows[0] + (M - 1) * (S + 2) + S - 1 < H:
                pitch_row = S + 2
            else:
                pitch_row = pitch_col
        else:
            pitch_row = pitch_col

    # Determine which legend row the existing block row(s) correspond to.
    # Build a map from block row to candidate legend row by colour matching.
    def row_matches(legend_row, block_cols, block_colors):
        # block_cols are absolute column starts; we only compare relative order.
        # For each existing block, its colour must equal the legend cell at the
        # corresponding block column index.
        # We do not yet know c0, so try all possible alignments.
        return None

    # Determine horizontal origin c0 from existing blocks.
    # Try all possible c0 such that existing block columns are congruent modulo pitch_col.
    possible_c0 = set()
    for r, items in by_row.items():
        for c, col in items:
            # c0 can be c - k*pitch_col for k >= 0, within grid.
            k = 0
            while True:
                c0 = c - k * pitch_col
                if c0 < 0:
                    break
                if c0 + (N - 1) * pitch_col + S - 1 < W:
                    possible_c0.add(c0)
                k += 1

    # Choose c0 that best matches legend colours for at least one block row.
    best_c0 = None
    best_score = -1
    for c0 in possible_c0:
        score = 0
        for r, items in by_row.items():
            # Determine block column indices for this row.
            col_idx = {}
            for c, col in items:
                if (c - c0) % pitch_col == 0:
                    idx = (c - c0) // pitch_col
                    if 0 <= idx < N:
                        col_idx[idx] = col
            # Try each legend row.
            for li, lrow in enumerate(legend_rows):
                match = 0
                for idx, col in col_idx.items():
                    if lrow[idx] is not None and lrow[idx] == col:
                        match += 1
                    elif lrow[idx] is None and col == bg:
                        match += 1
                if match == len(col_idx) and col_idx:
                    score += match
        if score > best_score:
            best_score = score
            best_c0 = c0

    if best_c0 is None:
        # Fallback: leftmost existing block column.
        best_c0 = min(c for _, c, _ in blocks)

    # Determine vertical origin r0 similarly.
    possible_r0 = set()
    for r, items in by_row.items():
        k = 0
        while True:
            r0 = r - k * pitch_row
            if r0 < 0:
                break
            if r0 + (M - 1) * pitch_row + S - 1 < H:
                possible_r0.add(r0)
            k += 1

    best_r0 = None
    best_score = -1
    for r0 in possible_r0:
        score = 0
        for r, items in by_row.items():
            if (r - r0) % pitch_row == 0:
                li = (r - r0) // pitch_row
                if 0 <= li < M:
                    lrow = legend_rows[li]
                    for c, col in items:
                        if (c - best_c0) % pitch_col == 0:
                            ci = (c - best_c0) // pitch_col
                            if 0 <= ci < N:
                                if lrow[ci] is not None and lrow[ci] == col:
                                    score += 1
        if score > best_score:
            best_score = score
            best_r0 = r0

    if best_r0 is None:
        # Fallback: topmost existing block row.
        best_r0 = min(r for r, _, _ in blocks)

    # Fill the output.
    out = g.copy()
    for i in range(M):
        for j in range(N):
            val = legend_rows[i][j]
            if val is None or val == bg:
                continue
            r = best_r0 + i * pitch_row
            c = best_c0 + j * pitch_col
            if 0 <= r and 0 <= c and r + S <= H and c + S <= W:
                out[r:r + S, c:c + S] = val

    return [list(map(int, row)) for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Find the two non-8 border colors and the corner 0.
    border_colors = set()
    for i in range(h):
        for j in range(w):
            if (i == 0 or i == h - 1 or j == 0 or j == w - 1) and g[i, j] not in (0, 8):
                border_colors.add(int(g[i, j]))

    corner = None
    for i, j in ((0, 0), (0, w - 1), (h - 1, 0), (h - 1, w - 1)):
        if g[i, j] == 0:
            corner = (i, j)
            break

    # Determine whether the interior blocks are arranged in horizontal or vertical bands.
    # A horizontal layout has two 2-row-high bands; a vertical layout has two 2-col-wide bands.
    horizontal = False
    if h >= 6 and w >= 6:
        # Check for a full 8 separator row between two 2-row bands.
        for sep in range(2, h - 4):
            if np.all(g[sep, :] == 8):
                top_band = g[sep - 2:sep, :]
                bot_band = g[sep + 1:sep + 3, :]
                if np.any(top_band != 8) and np.any(bot_band != 8):
                    horizontal = True
                    break

    def extract_blocks_horizontal(g):
        h, w = g.shape
        blocks = []
        for sep in range(2, h - 4):
            if np.all(g[sep, :] == 8):
                for band in (g[sep - 2:sep, :], g[sep + 1:sep + 3, :]):
                    col = 0
                    while col < w:
                        if band[0, col] != 8:
                            start = col
                            while col < w and band[0, col] != 8:
                                col += 1
                            blocks.append(band[:, start:col].copy())
                        else:
                            col += 1
                break
        return blocks

    def extract_blocks_vertical(g):
        h, w = g.shape
        blocks = []
        for sep in range(2, w - 4):
            if np.all(g[:, sep] == 8):
                for band in (g[:, sep - 2:sep], g[:, sep + 1:sep + 3]):
                    row = 0
                    while row < h:
                        if band[row, 0] != 8:
                            start = row
                            while row < h and band[row, 0] != 8:
                                row += 1
                            blocks.append(band[start:row, :].copy())
                        else:
                            row += 1
                break
        return blocks

    if horizontal:
        blocks = extract_blocks_horizontal(g)
        # If the 2-border is on the right, read each band right-to-left.
        # In the examples this corresponds to the corner 0 being on the right side.
        if corner is not None and corner[1] == w - 1:
            # Reverse order within each original band.
            # The extractor returns top band blocks then bottom band blocks.
            # Re-extract with explicit band separation to reverse correctly.
            h, w = g.shape
            blocks = []
            for sep in range(2, h - 4):
                if np.all(g[sep, :] == 8):
                    for band in (g[sep - 2:sep, :], g[sep + 1:sep + 3, :]):
                        band_blocks = []
                        col = 0
                        while col < w:
                            if band[0, col] != 8:
                                start = col
                                while col < w and band[0, col] != 8:
                                    col += 1
                                band_blocks.append(band[:, start:col].copy())
                            else:
                                col += 1
                        band_blocks.reverse()
                        blocks.extend(band_blocks)
                    break
    else:
        blocks = extract_blocks_vertical(g)
        # For vertical layouts, transpose each block so it becomes a horizontal strip.
        blocks = [b.T.copy() for b in blocks]

        # Determine reading order from the border/corner.
        # Examples:
        #   top=2, left=1  -> read left band top-to-bottom, then right band top-to-bottom.
        #   top=2, right=1 -> read right band bottom-to-top, then left band bottom-to-top.
        # We infer the side of the 1-border.
        side_one = None
        if corner is not None:
            if corner[0] == 0 and corner[1] == 0:
                # top-left corner: check left column vs top row for color 1
                if g[1, 0] == 1:
                    side_one = 'left'
                elif g[0, 1] == 1:
                    side_one = 'top'
            elif corner[0] == 0 and corner[1] == w - 1:
                if g[1, w - 1] == 1:
                    side_one = 'right'
                elif g[0, w - 2] == 1:
                    side_one = 'top'

        # Re-extract vertical blocks with explicit band separation and ordering.
        h, w = g.shape
        ordered = []
        for sep in range(2, w - 4):
            if np.all(g[:, sep] == 8):
                left_band = g[:, sep - 2:sep]
                right_band = g[:, sep + 1:sep + 3]

                def band_blocks(band):
                    res = []
                    row = 0
                    hh = band.shape[0]
                    while row < hh:
                        if band[row, 0] != 8:
                            start = row
                            while row < hh and band[row, 0] != 8:
                                row += 1
                            res.append(band[start:row, :].copy())
                        else:
                            row += 1
                    return res

                lb = band_blocks(left_band)
                rb = band_blocks(right_band)

                if side_one == 'left':
                    ordered = lb + rb
                elif side_one == 'right':
                    ordered = list(reversed(rb)) + list(reversed(lb))
                else:
                    # Fallback: left-to-right, top-to-bottom.
                    ordered = lb + rb
                break

        blocks = [b.T.copy() for b in ordered]

    # Build output: vertical stack of horizontal strips, centered in max width.
    max_w = max(b.shape[1] for b in blocks)
    out_h = sum(b.shape[0] for b in blocks)
    out = np.full((out_h, max_w), 8, dtype=int)

    y = 0
    for b in blocks:
        bh, bw = b.shape
        x = (max_w - bw) // 2
        out[y:y + bh, x:x + bw] = b
        y += bh

    return out.tolist()

