        if g[0, 1] == 1:
            side1 = 'top'
        elif g[1, 0] == 1:
            side1 = 'left'
        if g[0, 1] == 2:
            side2 = 'top'
        elif g[1, 0] == 2:
            side2 = 'left'
    elif corner[0] == 0 and corner[1] == w - 1:
        # top-right
        if g[0, w - 2] == 1:
            side1 = 'top'
        elif g[1, w - 1] == 1:
            side1 = 'right'
        if g[0, w - 2] == 2:
            side2 = 'top'
        elif g[1, w - 1] == 2:
            side2 = 'right'
    elif corner[0] == h - 1 and corner[1] == 0:
        # bottom-left
        if g[h - 1, 1] == 1:
            side1 = 'bottom'
        elif g[h - 2, 0] == 1:
            side1 = 'left'
        if g[h - 1, 1] == 2:
            side2 = 'bottom'
        elif g[h - 2, 0] == 2:
            side2 = 'left'
    else:
        # bottom-right
        if g[h - 1, w - 2] == 1:
            side1 = 'bottom'
        elif g[h - 2, w - 1] == 1:
            side1 = 'right'
        if g[h - 1, w - 2] == 2:
            side2 = 'bottom'
        elif g[h - 2, w - 1] == 2:
