    def vertical_blocks(g, side1, side2):
        """Extract 2-column-wide blocks from two vertical bands."""
        hh, ww = g.shape
        bands = []
        for sep in range(2, ww - 4):
            if np.all(g[:, sep] == 8):
                bands.append(g[:, sep - 2:sep])
                bands.append(g[:, sep + 1:sep + 3])
                break

        # side1 chooses which vertical band comes first.
        if side1 == 'left':
            band_order = [0, 1]
        elif side1 == 'right':
            band_order = [1, 0]
        else:
            band_order = [0, 1]

        # side2 chooses top-to-bottom or bottom-to-top inside each band.
        reverse = (side2 == 'bottom')

