    if not horizontal:
        rotated = []
        for b in blocks:
            t = b.T
            if side1 == 'left':
                t = t[::-1, :]
            # if side1 == 'right', keep t as is
            rotated.append(t)
        blocks = rotated

    # Build the output canvas: vertical stack of blocks, centered horizontally.
    if not blocks:
        return []

    max_w = max(b.shape[1] for b in blocks)
    out_h = sum(b.shape[0] for b in blocks)
    out = np.full((out_h, max_w), 8, dtype=int)

    y = 0
    for b in blocks:
        bh, bw = b.shape
        x = (max_w - bw) // 2
        out[y:y + bh, x:x + bw] = b
        y += bh

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import heapq
    from collections import deque

    h = len(grid)
    w = len(grid[0])

    # Existing 6 cells are seeds.
    seeds = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]

    # 2-cells are terminals.
    terminals = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]

    # If there are no seeds or no terminals, nothing changes.
    if not seeds or not terminals:
        return [row[:] for row in grid]

    # Build a graph whose nodes are:
    #   - all seed cells
    #   - all terminal cells
    # Edges are shortest path lengths through cells that are not 2,
    # except the destination terminal cell itself.
    #
    # This models "draw 6 paths from seeds to terminals", where 2-cells
    # are obstacles except when they are the final target.
    nodes = seeds + terminals
    node_id = {p: i for i, p in enumerate(nodes)}
    n = len(nodes)

    # For each node, run Dijkstra over the grid.
    # State: (distance, node_index, r, c)
    # We only need distances from each node to every other node.
    dist = [[10**18] * n for _ in range(n)]
    for i, (sr, sc) in enumerate(nodes):
        dist[i][i] = 0
        pq = [(0, i, sr, sc)]
        while pq:
            d, _, r, c = heapq.heappop(pq)
            if d > dist[i][node_id[(r, c)]] if (r, c) in node_id else False:
                pass
            # More direct check:
            if (r, c) in node_id:
                if d > dist[i][node_id[(r, c)]]:
                    continue
            else:
                # We do not store distances for non-node cells in dist,
                # so use a separate visited/distance map for this Dijkstra.
                pass

    # The above is awkward; implement clean Dijkstra per node with local dist map.
    dist = [[10**18] * n for _ in range(n)]
    for i, (sr, sc) in enumerate(nodes):
        local = {(sr, sc): 0}
        pq = [(0, sr, sc)]
        while pq:
            d, r, c = heapq.heappop(pq)
            if d != local.get((r, c), 10**18):
                continue
            if (r, c) in node_id:
                dist[i][node_id[(r, c)]] = d
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w:
                    # Cannot pass through 2-cells unless it is the destination.
                    if grid[nr][nc] == 2 and (nr, nc) != (sr, sc):
                        # Allow entering a terminal only if it is a node;
                        # but once entered, we do not expand from it.
                        if (nr, nc) in node_id:
                            nd = d + 1
                            if nd < local.get((nr, nc), 10**18):
                                local[(nr, nc)] = nd
                                heapq.heappush(pq, (nd, nr, nc))
                        continue
                    nd = d + 1
                    if nd < local.get((nr, nc), 10**18):
                        local[(nr, nc)] = nd
                        heapq.heappush(pq, (nd, nr, nc))

    # Build a minimum spanning tree over all nodes using these distances.
    # This gives the set of pairwise connections that the 6-paths should realize.
    edges = []
    for i in range(n):
        for j in range(i + 1, n):
            if dist[i][j] < 10**18:
                edges.append((dist[i][j], i, j))
    edges.sort()

    parent = list(range(n))
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    mst_edges = []
    for d, i, j in edges:
        ri, rj = find(i), find(j)
        if ri != rj:
            parent[ri] = rj
            mst_edges.append((i, j))

    # For each MST edge, add the actual shortest path cells (excluding terminals,
    # including seeds and intermediate 7-cells) to the output as 6.
    out = [row[:] for row in grid]

    # Reconstruct one shortest path for each MST edge using Dijkstra parent pointers.
    for a, b in mst_edges:
        ar, ac = nodes[a]
        br, bc = nodes[b]

        # Dijkstra from a to b, with 2-cells blocked except b.
        local = {(ar, ac): 0}
        parent_cell = {(ar, ac): None}
        pq = [(0, ar, ac)]
        while pq:
            d, r, c = heapq.heappop(pq)
            if (r, c) == (br, bc):
                break
            if d != local.get((r, c), 10**18):
                continue
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w:
                    if grid[nr][nc] == 2 and (nr, nc) != (br, bc):
                        continue
                    nd = d + 1
                    if nd < local.get((nr, nc), 10**18):
                        local[(nr, nc)] = nd
                        parent_cell[(nr, nc)] = (r, c)
                        heapq.heappush(pq, (nd, nr, nc))

        # Trace path back from b to a.
        path = []
        cur = (br, bc)
        while cur is not None:
            path.append(cur)
            cur = parent_cell.get(cur, None)
        path.reverse()

        for r, c in path:
            # Do not overwrite 2-cells; seeds and 7-cells become 6.
            if grid[r][c] != 2:
                out[r][c] = 6

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import heapq
    from collections import deque

    h = len(grid)
    w = len(grid[0])
    out = [row[:] for row in grid]

    seeds = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    twos = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]

    if not seeds or not twos:
        return out

    # 4-connected components of 2-cells.
    comp_id = {}
    comps = []
    for r, c in twos:
        if (r, c) in comp_id:
            continue
        cid = len(comps)
        q = deque([(r, c)])
        comp_id[(r, c)] = cid
        cells = []
        while q:
            cr, cc = q.popleft()
            cells.append((cr, cc))
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = cr + dr, cc + dc
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 2 and (nr, nc) not in comp_id:
                    comp_id[(nr, nc)] = cid
                    q.append((nr, nc))
        comps.append(cells)

    # For each 2-component, choose the cell closest to any seed.
    # Ties are broken by smaller row, then smaller column.
    targets = []
    for cells in comps:
        best = None
        for (r, c) in cells:
            d = min(abs(r - sr) + abs(c - sc) for sr, sc in seeds)
            key = (d, r, c)
            if best is None or key < best[0]:
                best = (key, (r, c))
        targets.append(best[1])

    # Nodes: seeds + chosen target cells.
    nodes = seeds + targets
    node_id = {p: i for i, p in enumerate(nodes)}
    n = len(nodes)

    # All-pairs shortest paths between nodes.
    # 2-cells are obstacles, except the destination node itself.
    INF = 10**18
    dist = [[INF] * n for _ in range(n)]

    for i, (sr, sc) in enumerate(nodes):
        local = {(sr, sc): 0}
        pq = [(0, sr, sc)]
        while pq:
            d, r, c = heapq.heappop(pq)
            if d != local.get((r, c), INF):
                continue
            if (r, c) in node_id:
                dist[i][node_id[(r, c)]] = d
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w:
                    if grid[nr][nc] == 2 and (nr, nc) != (sr, sc):
                        # May enter a target 2-cell, but do not expand from it.
                        if (nr, nc) in node_id:
                            nd = d + 1
                            if nd < local.get((nr, nc), INF):
                                local[(nr, nc)] = nd
                                heapq.heappush(pq, (nd, nr, nc))
                        continue
                    nd = d + 1
                    if nd < local.get((nr, nc), INF):
                        local[(nr, nc)] = nd
                        heapq.heappush(pq, (nd, nr, nc))

    # Minimum spanning tree over all nodes.
    edges = []
    for i in range(n):
        for j in range(i + 1, n):
            if dist[i][j] < INF:
                edges.append((dist[i][j], i, j))
    edges.sort()

    parent = list(range(n))
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    mst_edges = []
    for d, i, j in edges:
        ri, rj = find(i), find(j)
        if ri != rj:
            parent[ri] = rj
            mst_edges.append((i, j))

    # For each MST edge, add one shortest path.
    # Paint only non-2 cells as 6.
    for a, b in mst_edges:
        ar, ac = nodes[a]
        br, bc = nodes[b]

        local = {(ar, ac): 0}
        par = {(ar, ac): None}
        pq = [(0, ar, ac)]
        while pq:
            d, r, c = heapq.heappop(pq)
            if (r, c) == (br, bc):
                break
            if d != local.get((r, c), INF):
                continue
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w:
                    if grid[nr][nc] == 2 and (nr, nc) != (br, bc):
                        continue
                    nd = d + 1
                    if nd < local.get((nr, nc), INF):
                        local[(nr, nc)] = nd
                        par[(nr, nc)] = (r, c)
                        heapq.heappush(pq, (nd, nr, nc))

        path = []
        cur = (br, bc)
        while cur is not None:
            path.append(cur)
            cur = par.get(cur)
        path.reverse()

        for r, c in path:
            if grid[r][c] != 2:
                out[r][c] = 6

    return out

