                if (nr, nc) not in seen and g[nr, nc] == color:
                    seen.add((nr, nc))
                    q.append((nr, nc))
        return seen

    def touches(a, b):
        for r, c in a:
            for nr, nc in neighbors8(r, c):
                if (nr, nc) in b:
                    return True
        return False

    def side_score(comp, side):
        # side: 0=N, 1=E, 2=S, 3=W
        if side == 0:
            return -min(r for r, c in comp)
        if side == 1:
            return max(c for r, c in comp)
        if side == 2:
            return max(r for r, c in comp)
        return -min(c for r, c in comp)

    def anchor(comp, side):
        if side == 0:
            mr = min(r for r, c in comp)
            return (mr, min(c for r, c in comp if r == mr))
        if side == 1:
            mc = max(c for r, c in comp)
            return (min(r for r, c in comp if c == mc), mc)
        if side == 2:
            mr = max(r for r, c in comp)
            return (mr, min(c for r, c in comp if r == mr))
        mc = min(c for r, c in comp)
        return (min(r for r, c in comp if c == mc), mc)

    def place_line(anchor_cell, side, count, color):
        ar, ac = anchor_cell
        if side == 0:
            for i in range(1, count + 1):
                r = ar - i
                if 0 <= r < h:
                    out[r, ac] = color
        elif side == 1:
            for i in range(1, count + 1):
                c = ac + i
                if 0 <= c < w:
                    out[ar, c] = color
        elif side == 2:
            for i in range(1, count + 1):
                r = ar + i
                if 0 <= r < h:
                    out[r, ac] = color
        else:
            for i in range(1, count + 1):
                c = ac - i
                if 0 <= c < w:
                    out[ar, c] = color

