    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if g[r, c] != 0 and (r, c) not in seen:
                comp = component((r, c), g[r, c])
                seen.update(comp)
                comps.append((g[r, c], comp))

    # For each pair of touching components, move the smaller one to the
    # opposite side of the larger component.
    for i in range(len(comps)):
