            if color_a == color_b or not touches(comp_a, comp_b):
                continue

            if len(comp_a) < len(comp_b):
                main_color, main_comp = color_b, comp_b
                pay_color, pay_comp = color_a, comp_a
            else:
                main_color, main_comp = color_a, comp_a
