import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Find the initial 3 marker.
    starts = np.argwhere(g == 3)
    if len(starts) == 0:
        return g.tolist()
    sr, sc = starts[0]

    # Determine the main traversal direction:
    # from the edge containing the 3 marker to the opposite edge.
    if sr == 0:
        axis = 'v'
        start_line = 0
        end_line = h - 1
        start_pos = sc
    elif sr == h - 1:
        axis = 'v'
        start_line = h - 1
        end_line = 0
        start_pos = sc
    elif sc == 0:
        axis = 'h'
        start_line = 0
        end_line = w - 1
        start_pos = sr
    elif sc == w - 1:
        axis = 'h'
        start_line = w - 1
        end_line = 0
        start_pos = sr
    else:
        # Fallback: choose the shorter distance to an edge.
        if min(sr, h - 1 - sr) <= min(sc, w - 1 - sc):
            axis = 'v'
            if sr <= h - 1 - sr:
                start_line, end_line = 0, h - 1
            else:
                start_line, end_line = h - 1, 0
            start_pos = sc
        else:
            axis = 'h'
            if sc <= w - 1 - sc:
                start_line, end_line = 0, w - 1
            else:
                start_line, end_line = w - 1, 0
            start_pos = sr

    # Collect all non-background, non-3 cells as obstacles.
    # In the examples these are the 1/2 lines.
    obstacles = set()
    for r in range(h):
        for c in range(w):
            if g[r, c] not in (8, 3):
                obstacles.add((r, c))

    def line_cells(line):
        """Return sorted positions of obstacles on a given line."""
        if axis == 'v':
            return sorted(c for (r, c) in obstacles if r == line)
        else:
            return sorted(r for (r, c) in obstacles if c == line)

    # Build the sequence of obstacle lines between start and end.
    if axis == 'v':
        lines = [r for r in range(h) if line_cells(r)]
    else:
        lines = [c for c in range(w) if line_cells(c)]

    # Keep only obstacle lines that lie between the start and end edges.
    if start_line < end_line:
        lines = [x for x in lines if start_line < x < end_line]
    else:
        lines = [x for x in lines if end_line < x < start_line]

    # If there are no obstacles, simply draw a straight line.
    if not lines:
        out = g.copy()
        if axis == 'v':
            for r in range(min(start_line, end_line), max(start_line, end_line) + 1):
                out[r, start_pos] = 3
        else:
            for c in range(min(start_line, end_line), max(start_line, end_line) + 1):
                out[start_pos, c] = 3
        return out.tolist()

    # For each obstacle line, determine the gap to use.
    # The path alternates sides: first use the side that is open and closest
    # to the start position, then alternate.
    gaps = []
    side = None  # 0 = low side, 1 = high side
    for line in lines:
        obs = line_cells(line)
        # Find contiguous free intervals on this line.
        intervals = []
        prev = -1
        for p in obs:
            if p - prev > 1:
                intervals.append((prev + 1, p - 1))
            prev = p
        if prev + 1 < (h if axis == 'v' else w):
            intervals.append((prev + 1, (h if axis == 'v' else w) - 1))

        # Filter to intervals that actually contain free cells.
        intervals = [(a, b) for a, b in intervals if a <= b]

        if not intervals:
            # Should not happen in valid puzzles; skip this obstacle.
            continue

        # Choose an interval. Prefer the one containing the current position
        # if possible; otherwise choose the side opposite the previous side.
        current = start_pos if not gaps else gaps[-1][1]
        chosen = None
        for a, b in intervals:
            if a <= current <= b:
                chosen = (a, b)
                break
        if chosen is None:
            # Alternate sides: low/high relative to the obstacle line.
            if side is None:
                # First obstacle: choose the side closer to the start position.
                low = [iv for iv in intervals if iv[1] < min(obs)]
                high = [iv for iv in intervals if iv[0] > max(obs)]
                if low and high:
                    # Choose the side whose interval is closer to start_pos.
                    low_dist = min(abs(start_pos - a) + abs(start_pos - b) for a, b in low)
                    high_dist = min(abs(start_pos - a) + abs(start_pos - b) for a, b in high)
                    chosen = (low[0] if low_dist <= high_dist else high[0])
                    side = 0 if chosen in low else 1
                elif low:
                    chosen = low[0]
                    side = 0
                else:
                    chosen = high[0]
                    side = 1
            else:
                # Alternate to the other side.
                want = 1 - side
                if want == 0:
                    low = [iv for iv in intervals if iv[1] < min(obs)]
                    chosen = low[0] if low else intervals[0]
                else:
                    high = [iv for iv in intervals if iv[0] > max(obs)]
                    chosen = high[0] if high else intervals[-1]
                side = want

        a, b = chosen
        # Choose a position inside the gap.
        # Use the midpoint, biased toward the side edge that is farther from
        # the previous position to create the observed stable vertical/horizontal
        # segments.
        if not gaps:
            pos = (a + b) // 2
        else:
            prev_pos = gaps[-1][1]
            # Prefer the endpoint of the gap that is farther from prev_pos,
            # but not too far: use a point one cell inside from that edge.
            if prev_pos < a:
                pos = a + 1 if a + 1 <= b else a
            elif prev_pos > b:
                pos = b - 1 if b - 1 >= a else b
            else:
                pos = (a + b) // 2
        gaps.append((line, pos))

    # Build the polyline.
    # It starts at the start edge, goes to the first gap line at the start
    # position, then alternates horizontal/vertical moves through the gaps.
    points = []
    if axis == 'v':
        points.append((start_line, start_pos))
        for line, pos in gaps:
            points.append((line, start_pos if len(points) == 1 else points[-1][1]))
            points.append((line, pos))
        points.append((end_line, gaps[-1][1]))
    else:
        points.append((start_pos, start_line))
        for line, pos in gaps:
            points.append((points[-1][0], line if len(points) == 1 else points[-1][1]))
            points.append((pos, line))
        points.append((gaps[-1][1], end_line))

    # Clean up consecutive duplicate points.
    cleaned = []
    for p in points:
        if not cleaned or cleaned[-1] != p:
            cleaned.append(p)

    out = g.copy()

    # Draw the 3 path.
    for (r1, c1), (r2, c2) in zip(cleaned, cleaned[1:]):
        if r1 == r2:
            for c in range(min(c1, c2), max(c1, c2) + 1):
                out[r1, c] = 3
        elif c1 == c2:
            for r in range(min(r1, r2), max(r1, r2) + 1):
                out[r, c1] = 3

    # Convert all 1s to 2s (normalize the lines).
    out[out == 1] = 2

    return out.tolist()

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Obstacles are the 1/2 line cells. 3 is the start.
    obstacles = set()
    start = None
    for r in range(h):
        for c in range(w):
            v = g[r, c]
            if v in (1, 2):
                obstacles.add((r, c))
            elif v == 3:
                start = (r, c)

    # Normalize obstacle colour to 2.
    out = g.copy()
    out[out == 1] = 2

    if start is None:
        return out.tolist()

    sr, sc = start

    # Determine whether the main movement is horizontal or vertical.
    # In all examples the start is on an edge and the path exits through
    # the opposite edge.  Use the edge containing the start.
    on_left = (sc == 0)
    on_right = (sc == w - 1)
    on_top = (sr == 0)
    on_bottom = (sr == h - 1)

    # If start is on a vertical edge, path is primarily horizontal.
    horizontal = on_left or on_right

    # Helper: for a horizontal line (fixed row), find obstacle columns.
    def obs_cols(row):
        return sorted(c for (r, c) in obstacles if r == row)

    # Helper: for a vertical line (fixed col), find obstacle rows.
    def obs_rows(col):
        return sorted(r for (r, c) in obstacles if c == col)

    # Find the relevant wall segments that block the direct path.
    # For horizontal movement, walls are vertical segments.
    # For vertical movement, walls are horizontal segments.
    # We collect all obstacle cells and group them into maximal straight
    # segments.  Only segments that intersect the direct line from start to
    # opposite edge are considered, but in the given tasks all 1/2 cells are
    # such blocking segments.
    segments = []
    used = set()

    # Group horizontal segments.
    for (r, c) in obstacles:
        if (r, c) in used:
            continue
        # extend left
        c0 = c
        while (r, c0 - 1) in obstacles:
            c0 -= 1
        # extend right
        c1 = c
        while (r, c1 + 1) in obstacles:
            c1 += 1
        for cc in range(c0, c1 + 1):
            used.add((r, cc))
        segments.append(('h', r, c0, c1))

    # Group vertical segments.
    used = set()
    for (r, c) in obstacles:
        if (r, c) in used:
            continue
        r0 = r
        while (r0 - 1, c) in obstacles:
            r0 -= 1
        r1 = r
        while (r1 + 1, c) in obstacles:
            r1 += 1
        for rr in range(r0, r1 + 1):
            used.add((rr, c))
        segments.append(('v', c, r0, r1))

    # Choose the blocking segments in order along the main axis.
    if horizontal:
        # vertical segments that cross the start row or lie between left/right
        walls = []
        for seg in segments:
            if seg[0] != 'v':
                continue
            _, col, r0, r1 = seg
            # A vertical wall blocks horizontal movement if the start row is
            # within its span, or if it is one of the alternating walls used
            # in the examples.  Keep all vertical walls and sort by column.
            walls.append((col, r0, r1))
        walls.sort()
    else:
        walls = []
        for seg in segments:
            if seg[0] != 'h':
                continue
            _, row, c0, c1 = seg
            walls.append((row, c0, c1))
        walls.sort()

    # Build the path as a sequence of axis-aligned segments.
    # The observed rule is:
    # - move from the start edge to the opposite edge;
    # - when a wall blocks the direct line, detour around its end;
    # - the detour line is placed at the midpoint between the two adjacent
    #   boundaries (edge or wall end), rounded toward the start side.
    # This reproduces all provided examples.

    path = [(sr, sc)]

    if horizontal:
        # Move left-to-right or right-to-left.
        if on_left:
            # start at left edge, exit right edge.
            # For each vertical wall in increasing column order, if it blocks
            # the current row, go around it.
            cur_r, cur_c = sr, sc
            for col, r0, r1 in walls:
                if col <= cur_c:
                    continue
                # If current row is blocked by this wall, detour.
                if r0 <= cur_r <= r1:
                    # Choose a row below or above the wall.
                    # Prefer the side that gives a larger gap to the next
                    # boundary.  In examples: if wall touches top, go below;
                    # if wall touches bottom, go above; otherwise choose the
                    # side with the larger free space.
                    top_gap = r0
                    bottom_gap = h - 1 - r1
                    if top_gap >= bottom_gap:
                        # go above
                        # boundary above is top edge (0) or previous wall end.
                        # Use midpoint between 0 and r0-1, but not above start.
                        target_r = max(0, (0 + (r0 - 1)) // 2)
                        # If that is not free of other walls, move to the
                        # nearest free row above the wall.
                        while target_r < r0 and any(
                            (target_r, cc) in obstacles for cc in range(cur_c, col)
                        ):
                            target_r -= 1
                        if target_r < 0:
                            target_r = 0
                    else:
                        # go below
                        target_r = min(h - 1, (r1 + 1 + (h - 1)) // 2)
                        while target_r > r1 and any(
                            (target_r, cc) in obstacles for cc in range(cur_c, col)
                        ):
                            target_r += 1
                        if target_r >= h:
                            target_r = h - 1

                    # Move vertically to target_r, then horizontally past wall.
                    if target_r != cur_r:
                        path.append((target_r, cur_c))
                        cur_r = target_r
                    # Move horizontally to a column just past the wall.
                    # Use midpoint between wall column and next boundary.
                    # For simplicity, move to col+1 if free, else further.
                    target_c = col + 1
                    while target_c < w and (cur_r, target_c) in obstacles:
                        target_c += 1
                    if target_c >= w:
                        target_c = w - 1
                    if target_c != cur_c:
                        path.append((cur_r, target_c))
                        cur_c = target_c
                else:
                    # Not blocked at current row; move horizontally to just
                    # before the wall if needed.
                    if col > cur_c:
                        path.append((cur_r, col - 1))
                        cur_c = col - 1
            # Exit to right edge.
            if cur_c != w - 1:
                path.append((cur_r, w - 1))
                cur_c = w - 1
        else:
            # start at right edge, exit left edge.
            cur_r, cur_c = sr, sc
            for col, r0, r1 in reversed(walls):
                if col >= cur_c:
                    continue
                if r0 <= cur_r <= r1:
                    top_gap = r0
                    bottom_gap = h - 1 - r1
                    if top_gap >= bottom_gap:
                        target_r = max(0, (0 + (r0 - 1)) // 2)
                        while target_r < r0 and any(
                            (target_r, cc) in obstacles for cc in range(col, cur_c)
                        ):
                            target_r -= 1
                        if target_r < 0:
                            target_r = 0
                    else:
                        target_r = min(h - 1, (r1 + 1 + (h - 1)) // 2)
                        while target_r > r1 and any(
                            (target_r, cc) in obstacles for cc in range(col, cur_c)
                        ):
                            target_r += 1
                        if target_r >= h:
                            target_r = h - 1

                    if target_r != cur_r:
                        path.append((target_r, cur_c))
                        cur_r = target_r
                    target_c = col - 1
                    while target_c >= 0 and (cur_r, target_c) in obstacles:
                        target_c -= 1
                    if target_c < 0:
                        target_c = 0
                    if target_c != cur_c:
                        path.append((cur_r, target_c))
                        cur_c = target_c
                else:
                    if col < cur_c:
                        path.append((cur_r, col + 1))
                        cur_c = col + 1
            if cur_c != 0:
                path.append((cur_r, 0))
                cur_c = 0

    else:
        # Vertical movement.
        if on_top:
            cur_r, cur_c = sr, sc
            for row, c0, c1 in walls:
                if row <= cur_r:
                    continue
                if c0 <= cur_c <= c1:
                    left_gap = c0
                    right_gap = w - 1 - c1
                    if left_gap >= right_gap:
                        target_c = max(0, (0 + (c0 - 1)) // 2)
                        while target_c < c0 and any(
                            (rr, target_c) in obstacles for rr in range(cur_r, row)
                        ):
                            target_c -= 1
                        if target_c < 0:
                            target_c = 0
                    else:
                        target_c = min(w - 1, (c1 + 1 + (w - 1)) // 2)
                        while target_c > c1 and any(
                            (rr, target_c) in obstacles for rr in range(cur_r, row)
                        ):
                            target_c += 1
                        if target_c >= w:
                            target_c = w - 1

                    if target_c != cur_c:
                        path.append((cur_r, target_c))
                        cur_c = target_c
                    target_r = row + 1
                    while target_r < h and (target_r, cur_c) in obstacles:
                        target_r += 1
                    if target_r >= h:
                        target_r = h - 1
                    if target_r != cur_r:
                        path.append((target_r, cur_c))
                        cur_r = target_r
                else:
                    if row > cur_r:
                        path.append((row - 1, cur_c))
                        cur_r = row - 1
            if cur_r != h - 1:
                path.append((h - 1, cur_c))
                cur_r = h - 1
        else:
            cur_r, cur_c = sr, sc
            for row, c0, c1 in reversed(walls):
                if row >= cur_r:
                    continue
                if c0 <= cur_c <= c1:
                    left_gap = c0
                    right_gap = w - 1 - c1
                    if left_gap >= right_gap:
                        target_c = max(0, (0 + (c0 - 1)) // 2)
                        while target_c < c0 and any(
                            (rr, target_c) in obstacles for rr in range(row, cur_r)
                        ):
                            target_c -= 1
                        if target_c < 0:
                            target_c = 0
                    else:
                        target_c = min(w - 1, (c1 + 1 + (w - 1)) // 2)
                        while target_c > c1 and any(
                            (rr, target_c) in obstacles for rr in range(row, cur_r)
                        ):
                            target_c += 1
                        if target_c >= w:
                            target_c = w - 1

                    if target_c != cur_c:
                        path.append((cur_r, target_c))
                        cur_c = target_c
                    target_r = row - 1
                    while target_r >= 0 and (target_r, cur_c) in obstacles:
                        target_r -= 1
                    if target_r < 0:
                        target_r = 0
                    if target_r != cur_r:
                        path.append((target_r, cur_c))
                        cur_r = target_r
                else:
                    if row < cur_r:
                        path.append((row + 1, cur_c))
                        cur_r = row + 1
            if cur_r != 0:
                path.append((0, cur_c))
                cur_r = 0

    # Remove consecutive duplicates.
    clean = []
    for p in path:
        if not clean or clean[-1] != p:
            clean.append(p)

    # Draw the path with colour 3.
    for (r1, c1), (r2, c2) in zip(clean, clean[1:]):
        if r1 == r2:
            for c in range(min(c1, c2), max(c1, c2) + 1):
                out[r1, c] = 3
        elif c1 == c2:
            for r in range(min(r1, r2), max(r1, r2) + 1):
                out[r, c1] = 3

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    H, W = g.shape
    out = g.copy()

    def neighbors8(r, c):
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < H and 0 <= nc < W:
                    yield nr, nc

    def component(mask, start):
        sr, sc = start
        seen = {(sr, sc)}
        q = deque([(sr, sc)])
        while q:
            r, c = q.popleft()
            for nr, nc in neighbors8(r, c):
                if (nr, nc) not in seen and mask[nr, nc]:
                    seen.add((nr, nc))
                    q.append((nr, nc))
        return seen

    def bbox(cells):
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        return min(rs), max(rs), min(cs), max(cs)

    def direction_from_container(cells):
        rmin, rmax, cmin, cmax = bbox(cells)
        h = rmax - rmin + 1
        w = cmax - cmin + 1

        # Prefer the most extreme single cell in the 4 cardinal directions.
        best = None
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            if dr == -1:
                key = min(cells, key=lambda p: (p[0], abs(p[1] - (cmin + cmax) / 2)))
            elif dr == 1:
                key = max(cells, key=lambda p: (p[0], abs(p[1] - (cmin + cmax) / 2)))
            elif dc == -1:
                key = min(cells, key=lambda p: (p[1], abs(p[0] - (rmin + rmax) / 2)))
            else:
                key = max(cells, key=lambda p: (p[1], abs(p[0] - (rmin + rmax) / 2)))
            score = 0
            if dr == -1:
                score = rmin - key[0]
            elif dr == 1:
                score = key[0] - rmax
            elif dc == -1:
                score = cmin - key[1]
            else:
                score = key[1] - cmax
            if best is None or score > best[0]:
                best = (score, (dr, dc), key)
        return best[1]

    def place_line(out, anchor, direction, length, color):
        dr, dc = direction
        cells = []
        for i in range(1, length + 1):
            r = anchor[0] + dr * i
            c = anchor[1] + dc * i
            if 0 <= r < H and 0 <= c < W:
                cells.append((r, c))
        if not cells:
            return
        # If the first cell is occupied by the container color, shift inward
        # by one cell, as seen in the examples.
        first = cells[0]
        if out[first[0], first[1]] != 0 and out[first[0], first[1]] != color:
            cells = cells[1:]
            if not cells:
                return
        for r, c in cells:
            out[r, c] = color

    # Find all non-background colors.
    colors = [c for c in range(1, 10) if np.any(g == c)]

    # For each color, find its 8-connected components.
    comps = {}
    for color in colors:
        mask = (g == color)
        seen = np.zeros((H, W), dtype=bool)
        lst = []
        for r in range(H):
            for c in range(W):
                if mask[r, c] and not seen[r, c]:
                    cells = component(mask, (r, c))
                    for rr, cc in cells:
                        seen[rr, cc] = True
                    lst.append((color, cells))
        comps[color] = lst

    # Identify container/payload pairs.
    # A container is a component that has another color's component(s)
    # inside its bounding box and not touching its exterior.
    pairs = []
    for color, comps_c in comps.items():
        for container in comps_c:
            rmin, rmax, cmin, cmax = bbox(container)
            for pcolor, comps_p in comps.items():
                if pcolor == color:
                    continue
                for payload in comps_p:
                    prmin, prmax, pcmin, pcmax = bbox(payload)
                    # Payload must be strictly inside the container bbox.
                    if prmin >= rmin and prmax <= rmax and pcmin >= cmin and pcmax <= cmax:
                        # Ensure payload is not connected to container by 8-neighborhood.
                        touches = False
                        for pr, pc in payload:
                            for nr, nc in neighbors8(pr, pc):
                                if (nr, nc) in container:
                                    touches = True
                                    break
                            if touches:
                                break
                        if not touches:
                            pairs.append((color, container, pcolor, payload))

    # Process each pair.
    for container_color, container, payload_color, payload in pairs:
        # Remove payload cells.
        for r, c in payload:
            out[r, c] = 0

        # Direction: opposite to the payload's offset from the container centroid.
        cr = sum(r for r, c in container) / len(container)
        cc = sum(c for r, c in container) / len(container)
        pr = sum(r for r, c in payload) / len(payload)
        pc = sum(c for r, c in payload) / len(payload)

        dr = pr - cr
        dc = pc - cc

        # Choose the dominant axis, then the opposite sign.
        if abs(dr) >= abs(dc):
            direction = (-1, 0) if dr > 0 else (1, 0)
        else:
            direction = (0, -1) if dc > 0 else (0, 1)

        # Length: projection of payload on the movement axis.
        if direction[0] != 0:
            length = max(r for r, c in payload) - min(r for r, c in payload) + 1
        else:
            length = max(c for r, c in payload) - min(c for r, c in payload) + 1

        # Anchor: the container cell most extreme in the movement direction.
        if direction == (-1, 0):
            anchor = min(container, key=lambda p: (p[0], abs(p[1] - cc)))
        elif direction == (1, 0):
            anchor = max(container, key=lambda p: (p[0], abs(p[1] - cc)))
        elif direction == (0, -1):
            anchor = min(container, key=lambda p: (p[1], abs(p[0] - cr)))
        else:
            anchor = max(container, key=lambda p: (p[1], abs(p[0] - cr)))

        place_line(out, anchor, direction, length, payload_color)

    return out.tolist()

import numpy as np
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape
    out = g.copy()

    def neighbors8(r, c):
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < H and 0 <= nc < W:
                    yield nr, nc

    def component(mask, start):
        sr, sc = start
        seen = {(sr, sc)}
        q = deque([(sr, sc)])
        while q:
            r, c = q.popleft()
            for nr, nc in neighbors8(r, c):
                if (nr, nc) not in seen and mask[nr, nc]:
                    seen.add((nr, nc))
                    q.append((nr, nc))
        return seen

    def bbox(cells):
        rs = [r for r, _ in cells]
        cs = [c for _, c in cells]
        return min(rs), max(rs), min(cs), max(cs)

    # Connected components of every non-zero color.
    comps = []
    seen = np.zeros((H, W), dtype=bool)
    for r in range(H):
        for c in range(W):
            if g[r, c] != 0 and not seen[r, c]:
                color = g[r, c]
                mask = (g == color)
                cells = component(mask, (r, c))
                for rr, cc in cells:
                    seen[rr, cc] = True
                comps.append((color, cells))

    # Find container/payload pairs.
    pairs = []
    for i, (ccolor, ccells) in enumerate(comps):
        crmin, crmax, ccmin, ccmax = bbox(ccells)
        for j, (pcolor, pcells) in enumerate(comps):
            if i == j or pcolor == ccolor:
                continue
            prmin, prmax, pcmin, pcmax = bbox(pcells)

            # Payload must be inside the container's bounding box.
            if not (prmin >= crmin and prmax <= crmax and pcmin >= ccmin and pcmax <= ccmax):
                continue

            # Payload must not be 8-adjacent to the container.
            touches = False
            for pr, pc in pcells:
                for nr, nc in neighbors8(pr, pc):
                    if (nr, nc) in ccells:
                        touches = True
                        break
                if touches:
                    break
            if touches:
                continue

            pairs.append((ccolor, ccells, pcolor, pcells))

    def side_score(cells, side):
        rmin, rmax, cmin, cmax = bbox(cells)
        if side == 'U':
            return sum(1 for r, c in cells if r == rmin)
        if side == 'D':
            return sum(1 for r, c in cells if r == rmax)
        if side == 'L':
            return sum(1 for r, c in cells if c == cmin)
        if side == 'R':
            return sum(1 for r, c in cells if c == cmax)
        return 0

    def choose_direction(container, payload):
        # Prefer the side of the container bounding box with the fewest container cells.
        # Break ties by moving away from the payload's centroid.
        crmin, crmax, ccmin, ccmax = bbox(container)
        pr = sum(r for r, _ in payload) / len(payload)
        pc = sum(c for _, c in payload) / len(payload)

        sides = ['U', 'D', 'L', 'R']
        scores = {s: side_score(container, s) for s in sides}
        best_score = min(scores.values())
        candidates = [s for s in sides if scores[s] == best_score]

        if len(candidates) == 1:
            side = candidates[0]
        else:
            # Choose the candidate side opposite the payload offset from container center.
            cr = (crmin + crmax) / 2.0
            cc = (ccmin + ccmax) / 2.0
            dr = pr - cr
            dc = pc - cc
            if abs(dr) >= abs(dc):
                side = 'U' if dr > 0 else 'D'
                if side not in candidates:
                    side = candidates[0]
            else:
                side = 'L' if dc > 0 else 'R'
                if side not in candidates:
                    side = candidates[0]

        return {'U': (-1, 0), 'D': (1, 0), 'L': (0, -1), 'R': (0, 1)}[side]

    def anchor_for(container, direction):
        dr, dc = direction
        crmin, crmax, ccmin, ccmax = bbox(container)
        if direction == (-1, 0):
            return min(container, key=lambda p: (p[0], abs(p[1] - (ccmin + ccmax) / 2)))
        if direction == (1, 0):
            return max(container, key=lambda p: (p[0], abs(p[1] - (ccmin + ccmax) / 2)))
        if direction == (0, -1):
            return min(container, key=lambda p: (p[1], abs(p[0] - (crmin + crmax) / 2)))
        return max(container, key=lambda p: (p[1], abs(p[0] - (crmin + crmax) / 2)))

    def line_length(payload, direction):
        if direction[0] != 0:
            rs = [r for r, _ in payload]
            return max(rs) - min(rs) + 1
        cs = [c for _, c in payload]
        return max(cs) - min(cs) + 1

    def place_line(anchor, direction, length, color):
        dr, dc = direction
        cells = []
        for i in range(1, length + 1):
            r = anchor[0] + dr * i
            c = anchor[1] + dc * i
            if 0 <= r < H and 0 <= c < W:
                cells.append((r, c))
        if not cells:
            return
        # If the first cell is occupied by another color, shift inward by one.
        if out[cells[0][0], cells[0][1]] not in (0, color):
            cells = cells[1:]
        for r, c in cells:
            out[r, c] = color

    for _, container, _, payload in pairs:
        # Remove payload.
        for r, c in payload:
            out[r, c] = 0

        direction = choose_direction(container, payload)
        anchor = anchor_for(container, direction)
        length = line_length(payload, direction)
        place_line(anchor, direction, length, payload)

    return out.tolist()

import numpy as np
from collections import Counter, deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    a = np.array(grid, dtype=int)
    h, w = a.shape

    # Background is the most common colour.
    bg = Counter(a.flatten()).most_common(1)[0][0]

    # 8-connected components.
    comp_id = -np.ones((h, w), dtype=int)
    comps = []
    for r in range(h):
        for c in range(w):
            if a[r, c] != bg and comp_id[r, c] == -1:
                color = a[r, c]
                q = deque([(r, c)])
                comp_id[r, c] = len(comps)
                cells = [(r, c)]
                while q:
                    y, x = q.popleft()
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            if dy == 0 and dx == 0:
                                continue
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < h and 0 <= nx < w:
                                if a[ny, nx] == color and comp_id[ny, nx] == -1:
                                    comp_id[ny, nx] = len(comps)
                                    cells.append((ny, nx))
                                    q.append((ny, nx))
                comps.append((color, cells))

    # Identify hollow rectangular frames.
    frames = []
    for color, cells in comps:
        if len(cells) < 8:
            continue
        rs = [r for r, _ in cells]
        cs = [c for _, c in cells]
        r0, r1 = min(rs), max(rs)
        c0, c1 = min(cs), max(cs)
        height = r1 - r0 + 1
        width = c1 - c0 + 1
        if height < 3 or width < 3:
            continue

        cell_set = set(cells)
        ok = True
        # All border cells must be present.
        for c in range(c0, c1 + 1):
            if (r0, c) not in cell_set or (r1, c) not in cell_set:
                ok = False
                break
        if ok:
            for r in range(r0, r1 + 1):
                if (r, c0) not in cell_set or (r, c1) not in cell_set:
                    ok = False
                    break
        # No interior cells of this component.
        if ok:
            for r in range(r0 + 1, r1):
                for c in range(c0 + 1, c1):
                    if (r, c) in cell_set:
                        ok = False
                        break
                if not ok:
                    break

        if ok:
            frames.append((color, r0, r1, c0, c1))

    # Output starts as background.
    out = np.full((h, w), bg, dtype=int)

    # Draw all frames.
    for color, r0, r1, c0, c1 in frames:
        out[r0, c0:c1 + 1] = color
        out[r1, c0:c1 + 1] = color
        out[r0:r1 + 1, c0] = color
        out[r0:r1 + 1, c1] = color

    # For each frame, count non-frame components of the same colour.
    for color, r0, r1, c0, c1 in frames:
        count = 0
        for col, cells in comps:
            if col != color:
                continue
            # Skip if this component is the frame itself.
            rs = [r for r, _ in cells]
            cs = [c for _, c in cells]
            if min(rs) == r0 and max(rs) == r1 and min(cs) == c0 and max(cs) == c1:
                continue
            count += 1

        # Middle row (upper middle for even height).
        mid_r = (r0 + r1) // 2

        # Draw `count` ticks from the right side, every second column.
        for i in range(count):
            c = c1 - 2 - 2 * i
            if c > c0:
                out[mid_r, c] = color

    return out.tolist()

import sys
from collections import Counter, defaultdict

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    W = len(grid[0]) if H else 0
    g = [list(map(int, row)) for row in grid]

    if H == 0 or W == 0:
        return g

    # Background is the most frequent colour.
    bg = Counter(x for row in g for x in row).most_common(1)[0][0]

    # Connected components of non-background cells.
    seen = [[False] * W for _ in range(H)]
    comps = []

    for r in range(H):
        for c in range(W):
            if seen[r][c] or g[r][c] == bg:
                continue
            stack = [(r, c)]
            seen[r][c] = True
            cells = []
            rmin = rmax = r
            cmin = cmax = c
            colors = Counter()

            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                v = g[y][x]
                colors[v] += 1
                rmin = min(rmin, y)
                rmax = max(rmax, y)
                cmin = min(cmin, x)
                cmax = max(cmax, x)

                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < H and 0 <= nx < W and not seen[ny][nx] and g[ny][nx] != bg:
                        seen[ny][nx] = True
                        stack.append((ny, nx))

            comps.append({
                "cells": cells,
                "bbox": (rmin, cmin, rmax, cmax),
                "colors": colors,
                "area": len(cells),
            })

    boxes = []
    box_cell_mask = [[False] * W for _ in range(H)]

    for comp in comps:
        r1, c1, r2, c2 = comp["bbox"]
        h = r2 - r1 + 1
        w = c2 - c1 + 1

        # Boxes are square and larger than isolated key digits.
        if h != w or h < 3 or comp["area"] < 4:
            continue

        border = g[r1][c1]
        if border == bg:
            continue

        # Centre colour is the most common non-background, non-border colour.
        center = None
        best = -1
        for val, cnt in comp["colors"].items():
            if val != bg and val != border and cnt > best:
                best = cnt
                center = val

        if center is None:
            continue

        cr1 = cr2 = None
        cc1 = cc2 = None
        for y, x in comp["cells"]:
            if g[y][x] == center:
                if cr1 is None:
                    cr1 = cr2 = y
                    cc1 = cc2 = x
                else:
                    cr1 = min(cr1, y)
                    cr2 = max(cr2, y)
                    cc1 = min(cc1, x)
                    cc2 = max(cc2, x)

        if cr1 is None:
            continue

        boxes.append({
            "label": center,
            "rect": (cr1, cc1, cr2, cc2),
        })

        for y, x in comp["cells"]:
            box_cell_mask[y][x] = True

    # Find the key line: row/column containing the most non-box, non-background cells.
    key_cells = []
    for r in range(H):
        for c in range(W):
            if g[r][c] != bg and not box_cell_mask[r][c]:
                key_cells.append((r, c, g[r][c]))

    row_counts = Counter(r for r, _, _ in key_cells)
    col_counts = Counter(c for _, c, _ in key_cells)

    key_seq = []
    if key_cells:
        best_row = max(row_counts.items(), key=lambda kv: kv[1])[0] if row_counts else None
        best_col = max(col_counts.items(), key=lambda kv: kv[1])[0] if col_counts else None

        use_row = (best_row is not None and (best_col is None or row_counts[best_row] >= col_counts[best_col]))

        if use_row:
            cells = sorted((c, r, v) for r, c, v in key_cells if r == best_row)
            key_seq = [v for _, _, v in cells]
        else:
            cells = sorted((r, c, v) for r, c, v in key_cells if c == best_col)
            key_seq = [v for _, _, v in cells]

    if not boxes or not key_seq:
        return g

    by_label = defaultdict(list)
    for i, b in enumerate(boxes):
        by_label[b["label"]].append(i)

    def center_key(i):
        r1, c1, r2, c2 = boxes[i]["rect"]
        return r1 + r2, c1 + c2

    def aligned(i, j):
        if i == j:
            return False
        ar1, ac1, ar2, ac2 = boxes[i]["rect"]
        br1, bc1, br2, bc2 = boxes[j]["rect"]

        row_overlap = max(ar1, br1) <= min(ar2, br2)
        col_overlap = max(ac1, bc1) <= min(ac2, bc2)

        horizontal = row_overlap and (ac2 < bc1 or bc2 < ac1)
        vertical = col_overlap and (ar2 < br1 or br2 < ar1)
        return horizontal or vertical

    def dist(i, j):
        sr1, sc1 = center_key(i)
        sr2, sc2 = center_key(j)
        return abs(sr1 - sr2) + abs(sc1 - sc2)

    # Dynamic programming over the key sequence.
    dp = {}
    for i in by_label.get(key_seq[0], []):
        dp[i] = (0, None)

    for val in key_seq[1:]:
        ndp = {}
        for prev, (cost, _) in dp.items():
            for nxt in by_label.get(val, []):
                if nxt == prev:
                    continue
                if not aligned(prev, nxt):
                    continue
                nc = cost + dist(prev, nxt)
                if nxt not in ndp or nc < ndp[nxt][0]:
                    ndp[nxt] = (nc, prev)
        if not ndp:
            # Fallback for unexpected inputs: allow nearest matching box.
            for prev, (cost, _) in dp.items():
                for nxt in by_label.get(val, []):
                    if nxt == prev:
                        continue
                    nc = cost + dist(prev, nxt)
                    if nxt not in ndp or nc < ndp[nxt][0]:
                        ndp[nxt] = (nc, prev)
        dp = ndp
        if not dp:
            break

    if not dp:
        return g

    end = min(dp.items(), key=lambda kv: kv[1][0])[0]
    path = []
    cur = end
    while cur is not None:
        path.append(cur)
        cur = dp[cur][1]
    path.reverse()

    out = [row[:] for row in g]

    def fill_horizontal(a, b, color):
        ar1, ac1, ar2, ac2 = boxes[a]["rect"]
        br1, bc1, br2, bc2 = boxes[b]["rect"]

        rlo = max(ar1, br1)
        rhi = min(ar2, br2)

        if ac2 < bc1:
            clo = ac2 + 1
            chi = bc1 - 1
        else:
            clo = bc2 + 1
            chi = ac1 - 1

        for r in range(rlo, rhi + 1):
            for c in range(clo, chi + 1):
                if out[r][c] == bg:
                    out[r][c] = color

    def fill_vertical(a, b, color):
        ar1, ac1, ar2, ac2 = boxes[a]["rect"]
        br1, bc1, br2, bc2 = boxes[b]["rect"]

        clo = max(ac1, bc1)
        chi = min(ac2, bc2)

        if ar2 < br1:
            rlo = ar2 + 1
            rhi = br1 - 1
        else:
            rlo = br2 + 1
            rhi = ar1 - 1

        for r in range(rlo, rhi + 1):
            for c in range(clo, chi + 1):
                if out[r][c] == bg:
                    out[r][c] = color

    for a, b in zip(path, path[1:]):
        color = boxes[a]["label"]
        ar1, ac1, ar2, ac2 = boxes[a]["rect"]
        br1, bc1, br2, bc2 = boxes[b]["rect"]

        row_overlap = max(ar1, br1) <= min(ar2, br2)
        col_overlap = max(ac1, bc1) <= min(ac2, bc2)

        if row_overlap and (ac2 < bc1 or bc2 < ac1):
            fill_horizontal(a, b, color)
        elif col_overlap and (ar2 < br1 or br2 < ar1):
            fill_vertical(a, b, color)

    return out

import numpy as np
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Identify the key line: a row/column containing many non-background
    # single-cell markers separated by background.
    bg = int(np.bincount(g.ravel()).argmax())

    def line_score(line):
        vals = [int(x) for x in line if int(x) != bg]
        if len(vals) < 2:
            return -1
        # Prefer lines whose non-background cells are isolated.
        isolated = 0
        for i, v in enumerate(line):
            if int(v) == bg:
                continue
            left = line[i-1] if i > 0 else bg
            right = line[i+1] if i + 1 < len(line) else bg
            if int(left) == bg and int(right) == bg:
                isolated += 1
        return (len(vals), isolated)

    best = None
    for r in range(H):
        s = line_score(g[r])
        if best is None or s > best[0]:
            best = (s, 'row', r)
    for c in range(W):
        s = line_score(g[:, c])
        if best is None or s > best[0]:
            best = (s, 'col', c)

    if best is None or best[0][0] < 2:
        return [list(map(int, row)) for row in g]

    _, kind, idx = best
    if kind == 'row':
        key_vals = [int(x) for x in g[idx] if int(x) != bg]
    else:
        key_vals = [int(x) for x in g[:, idx] if int(x) != bg]

    # Find boxes: connected components of non-background cells that contain
    # at least one "payload" color different from the component's frame color.
    seen = np.zeros((H, W), dtype=bool)
    boxes = []

    for r in range(H):
        for c in range(W):
            if seen[r, c] or g[r, c] == bg:
                continue
            start = (r, c)
            q = deque([start])
            seen[r, c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < H and 0 <= nx < W and not seen[ny, nx] and g[ny, nx] != bg:
                        seen[ny, nx] = True
                        q.append((ny, nx))

            if len(cells) < 4:
                continue

            colors = {}
            for y, x in cells:
                colors[int(g[y, x])] = colors.get(int(g[y, x]), 0) + 1
            if len(colors) < 2:
                continue

            # Frame color is the most common color in the component.
            frame = max(colors, key=lambda k: (colors[k], -k))
            payload_candidates = [col for col in colors if col != frame]
            if not payload_candidates:
                continue

            # Payload is the non-frame color closest to the component center.
            ys = [y for y, _ in cells]
            xs = [x for _, x in cells]
            cy = (min(ys) + max(ys)) / 2.0
            cx = (min(xs) + max(xs)) / 2.0

            def payload_score(col):
                pts = [(y, x) for y, x in cells if g[y, x] == col]
                if not pts:
                    return (1e18, 0)
                d = min((y - cy) ** 2 + (x - cx) ** 2 for y, x in pts)
                return (d, -len(pts))

            payload = min(payload_candidates, key=payload_score)

            # Center of the payload region.
            pts = [(y, x) for y, x in cells if g[y, x] == payload]
            py = sum(y for y, _ in pts) / len(pts)
            px = sum(x for _, x in pts) / len(pts)

            boxes.append({
                'color': int(payload),
                'frame': int(frame),
                'cy': py,
                'cx': px,
                'cells': cells,
            })

    if not boxes:
        return [list(map(int, row)) for row in g]

    # Match the key sequence to boxes.  Consecutive key entries must refer to
    # boxes that are aligned horizontally or vertically.
    n = len(key_vals)
    if n > len(boxes):
        return [list(map(int, row)) for row in g]

    def aligned(a, b):
        return abs(a['cy'] - b['cy']) < 1e-6 or abs(a['cx'] - b['cx']) < 1e-6

    # For each key position, candidate boxes with matching color.
    candidates = []
    for v in key_vals:
        cand = [i for i, b in enumerate(boxes) if b['color'] == v]
        candidates.append(cand)

    # Backtracking assignment.
    assignment = [-1] * n
    used = [False] * len(boxes)

    def ok(pos, box_idx):
        if pos > 0:
            prev = assignment[pos - 1]
            if prev != -1 and not aligned(boxes[prev], boxes[box_idx]):
                return False
        if pos + 1 < n:
            # If next position already assigned, check forward too.
            nxt = assignment[pos + 1]
            if nxt != -1 and not aligned(boxes[box_idx], boxes[nxt]):
                return False
        return True

    def backtrack(pos):
        if pos == n:
            return True
        # Try candidates, preferring boxes that keep future options open.
        order = candidates[pos][:]
        order.sort(key=lambda i: sum(
            1 for j in range(pos + 1, n)
            if not used[j] and boxes[i]['color'] == key_vals[j] and aligned(boxes[i], boxes[j])
        ), reverse=True)
        for bi in order:
            if used[bi] or not ok(pos, bi):
                continue
            assignment[pos] = bi
            used[bi] = True
            if backtrack(pos + 1):
                return True
            used[bi] = False
            assignment[pos] = -1
        return False

    if not backtrack(0):
        # Fallback: assign by reading order for each color.
        by_color = {}
        for i, b in enumerate(boxes):
            by_color.setdefault(b['color'], []).append(i)
        for lst in by_color.values():
            lst.sort(key=lambda i: (boxes[i]['cy'], boxes[i]['cx']))
        ptr = {k: 0 for k in by_color}
        for pos, v in enumerate(key_vals):
            if v in by_color and ptr[v] < len(by_color[v]):
                assignment[pos] = by_color[v][ptr[v]]
                ptr[v] += 1
            else:
                assignment[pos] = -1

    out = g.copy()

    # For each consecutive pair, fill the straight empty corridor between them
    # with the color of the first box.
    for i in range(n - 1):
        a_idx = assignment[i]
        b_idx = assignment[i + 1]
        if a_idx == -1 or b_idx == -1:
            continue
        a = boxes[a_idx]
        b = boxes[b_idx]
        fill_color = a['color']

        if abs(a['cy'] - b['cy']) < 1e-6:
            # Horizontal connection.
            y = int(round(a['cy']))
            x1 = int(round(a['cx']))
            x2 = int(round(b['cx']))
            if x1 > x2:
                x1, x2 = x2, x1
            for x in range(x1 + 1, x2):
                if 0 <= y < H and 0 <= x < W and out[y, x] == bg:
                    out[y, x] = fill_color
        elif abs(a['cx'] - b['cx']) < 1e-6:
            # Vertical connection.
            x = int(round(a['cx']))
            y1 = int(round(a['cy']))
            y2 = int(round(b['cy']))
            if y1 > y2:
                y1, y2 = y2, y1
            for y in range(y1 + 1, y2):
                if 0 <= y < H and 0 <= x < W and out[y, x] == bg:
                    out[y, x] = fill_color

    return [list(map(int, row)) for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Background is the most frequent colour.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # ------------------------------------------------------------------
    # Find the key sequence.
    # It is a row or column containing many isolated non-background cells.
    # ------------------------------------------------------------------
    def isolated_count_line(line):
        cnt = 0
        n = len(line)
        for i, v in enumerate(line):
            if v == bg:
                continue
            ok = True
            if i > 0 and line[i - 1] != bg:
                ok = False
            if i + 1 < n and line[i + 1] != bg:
                ok = False
            if ok:
                cnt += 1
        return cnt

    best = (-1, None, None)  # (count, orientation, index)
    for r in range(H):
        c = isolated_count_line(g[r])
        if c > best[0]:
            best = (c, 'row', r)
    for c in range(W):
        cc = isolated_count_line(g[:, c])
        if cc > best[0]:
            best = (cc, 'col', c)

    if best[1] is None:
        return [list(map(int, row)) for row in g]

    _, orient, idx = best
    if orient == 'row':
        key_vals = [int(x) for x in g[idx] if x != bg]
    else:
        key_vals = [int(x) for x in g[:, idx] if x != bg]

    if len(key_vals) < 2:
        return [list(map(int, row)) for row in g]

    # ------------------------------------------------------------------
    # Find boxes: connected components of non-background cells.
    # Key cells are isolated single-cell components; boxes are larger.
    # ------------------------------------------------------------------
    seen = np.zeros((H, W), dtype=bool)
    boxes = []

    for r in range(H):
        for c in range(W):
            if seen[r, c] or g[r, c] == bg:
                continue

            q = deque([(r, c)])
            seen[r, c] = True
            cells = []

            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < H and 0 <= nx < W and not seen[ny, nx] and g[ny, nx] != bg:
                        seen[ny, nx] = True
                        q.append((ny, nx))

            if len(cells) <= 1:
                continue

            color_counts = {}
            for y, x in cells:
                col = int(g[y, x])
                color_counts[col] = color_counts.get(col, 0) + 1

            if len(color_counts) < 2:
                continue

            # Frame/fill colour is the most common colour in the component.
            frame = max(color_counts, key=lambda k: (color_counts[k], -k))
            payload_colors = [col for col in color_counts if col != frame]
            if not payload_colors:
                continue

            # If there are several non-frame colours, choose the one closest
            # to the component centre.  In the given puzzles there is one.
            ys = [y for y, _ in cells]
            xs = [x for _, x in cells]
            cy = (min(ys) + max(ys)) / 2.0
            cx = (min(xs) + max(xs)) / 2.0

            def payload_score(col):
                pts = [(y, x) for y, x in cells if g[y, x] == col]
                if not pts:
                    return (10**18, 0)
                d = min((y - cy) ** 2 + (x - cx) ** 2 for y, x in pts)
                return (d, -len(pts))

            payload = min(payload_colors, key=payload_score)

            payload_cells = [(y, x) for y, x in cells if g[y, x] == payload]
            pys = [y for y, _ in payload_cells]
            pxs = [x for _, x in payload_cells]

            boxes.append({
                'color': int(payload),
                'frame': int(frame),
                'top': min(y for y, _ in cells),
                'bottom': max(y for y, _ in cells),
                'left': min(x for _, x in cells),
                'right': max(x for _, x in cells),
                'p_top': min(pys),
                'p_bottom': max(pys),
                'p_left': min(pxs),
                'p_right': max(pxs),
                'cy': (min(ys) + max(ys)) / 2.0,
                'cx': (min(xs) + max(xs)) / 2.0,
            })

    if not boxes:
        return [list(map(int, row)) for row in g]

    # ------------------------------------------------------------------
    # Assign key values to boxes.
    # Consecutive boxes must be aligned horizontally or vertically.
    # ------------------------------------------------------------------
    n = len(key_vals)
    if n > len(boxes):
        return [list(map(int, row)) for row in g]

    def aligned(a, b):
        return abs(a['cy'] - b['cy']) < 1e-6 or abs(a['cx'] - b['cx']) < 1e-6

    candidates = []
    for v in key_vals:
        candidates.append([i for i, b in enumerate(boxes) if b['color'] == v])

    assignment = [-1] * n
    used = [False] * len(boxes)

    def ok(pos, bi):
        if pos > 0:
            prev = assignment[pos - 1]
            if prev != -1 and not aligned(boxes[prev], boxes[bi]):
                return False
        if pos + 1 < n:
            nxt = assignment[pos + 1]
            if nxt != -1 and not aligned(boxes[bi], boxes[nxt]):
                return False
        return True

    def backtrack(pos):
        if pos == n:
            return True

        # Prefer choices that leave more aligned options for the next step.
        order = candidates[pos][:]
        order.sort(key=lambda i: sum(
            1 for j in range(pos + 1, n)
            if not used[j] and boxes[i]['color'] == key_vals[j] and aligned(boxes[i], boxes[j])
        ), reverse=True)

        for bi in order:
            if used[bi] or not ok(pos, bi):
                continue
            assignment[pos] = bi
            used[bi] = True
            if backtrack(pos + 1):
                return True
            used[bi] = False
            assignment[pos] = -1
        return False

    if not backtrack(0):
        # Fallback: for each colour, take boxes in reading order.
        by_color = {}
        for i, b in enumerate(boxes):
            by_color.setdefault(b['color'], []).append(i)
        for lst in by_color.values():
            lst.sort(key=lambda i: (boxes[i]['cy'], boxes[i]['cx']))
        ptr = {k: 0 for k in by_color}
        for pos, v in enumerate(key_vals):
            if v in by_color and ptr[v] < len(by_color[v]):
                assignment[pos] = by_color[v][ptr[v]]
                ptr[v] += 1
            else:
                assignment[pos] = -1

    out = g.copy()

    # ------------------------------------------------------------------
    # Draw the path.  For each consecutive pair, fill the straight corridor
    # between the two boxes with the colour of the first box.
    # ------------------------------------------------------------------
    for i in range(n - 1):
        ai = assignment[i]
        bi = assignment[i + 1]
        if ai == -1 or bi == -1:
            continue

        a = boxes[ai]
        b = boxes[bi]
        fill = a['color']

        if abs(a['cy'] - b['cy']) < 1e-6:
            # Horizontal connection.
            if a['cx'] > b['cx']:
                a, b = b, a

            x1 = a['right'] + 1
            x2 = b['left'] - 1

            r1 = max(a['p_top'], b['p_top'])
            r2 = min(a['p_bottom'], b['p_bottom'])

            for y in range(r1, r2 + 1):
                for x in range(x1, x2 + 1):
                    if 0 <= y < H and 0 <= x < W and out[y, x] == bg:
                        out[y, x] = fill

        elif abs(a['cx'] - b['cx']) < 1e-6:
            # Vertical connection.
            if a['cy'] > b['cy']:
                a, b = b, a

            y1 = a['bottom'] + 1
            y2 = b['top'] - 1

            c1 = max(a['p_left'], b['p_left'])
            c2 = min(a['p_right'], b['p_right'])

            for y in range(y1, y2 + 1):
                for x in range(c1, c2 + 1):
                    if 0 <= y < H and 0 <= x < W and out[y, x] == bg:
                        out[y, x] = fill

    return [list(map(int, row)) for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return [row[:] for row in grid]

    h = len(grid)
    w = len(grid[0])
    out = [row[:] for row in grid]

    # For every colour, find vertical "bars":
    # a contiguous non-zero column segment whose top and bottom cells are the
    # same colour c, and whose interior is a single different colour.
    # For each colour, fill the rightmost such bar with c.
    for c in range(1, 10):
        best = None  # (col, top, bottom)

        for col in range(w):
            r = 0
            while r < h:
                if grid[r][col] == 0:
                    r += 1
                    continue

                start = r
                while r < h and grid[r][col] != 0:
                    r += 1
                end = r - 1

                if end - start >= 2 and grid[start][col] == c and grid[end][col] == c:
                    interior = [grid[x][col] for x in range(start + 1, end)]
                    if interior and all(v == interior[0] for v in interior) and interior[0] != c:
                        # Prefer rightmost; deterministic tie-breaks.
                        key = (col, start, end)
                        if best is None or key > best:
                            best = key

        if best is not None:
            col, top, bottom = best
            for x in range(top + 1, bottom):
                out[x][col] = c

    return out

