def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Find the vertical separator line of 5s.
    sep_col = None
    for c in range(w):
        if np.all(g[:, c] == 5):
            sep_col = c
            break

    if sep_col is None:
        return out.tolist()

    # Work only on the region left of the separator.
    left = g[:, :sep_col].copy()
    out_left = left.copy()

    # Shift each 4-row band right so its rightmost 0 touches the separator.
    for r0 in range(0, h, 4):
        r1 = min(r0 + 4, h)
        band = left[r0:r1]

        # Distance from the right edge to the rightmost 0 in this band.
        shift = 0
        for r in range(band.shape[0]):
            row = band[r]
            if 0 in row:
                last_zero = len(row) - 1 - int(np.argmax(row[::-1] == 0))
                shift = max(shift, len(row) - 1 - last_zero)

        if shift > 0:
            for r in range(band.shape[0]):
                out_left[r0 + r, shift:] = band[r, :-shift]
                out_left[r0 + r, :shift] = 6

    out[:, :sep_col] = out_left

    # Mark rows containing enclosed 6-cells in the left region.
    if sep_col > 0:
        left = out[:, :sep_col]
        h2, w2 = left.shape
        visited = np.zeros((h2, w2), dtype=bool)

        for r in range(h2):
            for c in range(w2):
                if left[r, c] != 6 or visited[r, c]:
                    continue

                # Flood-fill a connected component of 6s.
                stack = [(r, c)]
                visited[r, c] = True
                comp = []
                touches_boundary = False

                while stack:
                    y, x = stack.pop()
                    comp.append((y, x))
                    if y == 0 or x == 0 or y == h2 - 1 or x == w2 - 1:
                        touches_boundary = True

                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h2 and 0 <= nx < w2:
                            if not visited[ny, nx] and left[ny, nx] == 6:
                                visited[ny, nx] = True
                                stack.append((ny, nx))

                # If the 6-component is fully enclosed by 0s, mark its rows.
                if not touches_boundary:
                    for y, x in comp:
                        if sep_col < w:
                            out[y, sep_col + 1:] = 2

    return out.tolist()

