def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Locate the vertical separator made of 5s.
    sep = None
    for c in range(w):
        if np.all(g[:, c] == 5):
            sep = c
            break

    if sep is None or sep == 0:
        return out.tolist()

    left_w = sep
    right_edge = left_w - 1

    # Shift each 4-row band in the left region rightwards so that the
    # rightmost 0 in the band reaches the right edge of the left region.
    for r0 in range(0, h, 4):
        r1 = min(r0 + 4, h)
        band = g[r0:r1, :left_w]

        max_zero_col = -1
        for r in range(band.shape[0]):
            zeros = np.where(band[r] == 0)[0]
            if zeros.size:
                max_zero_col = max(max_zero_col, int(zeros[-1]))

        if max_zero_col < 0:
            continue

        shift = right_edge - max_zero_col
        if shift <= 0:
            continue

        for r in range(band.shape[0]):
            out[r0 + r, shift:left_w] = band[r, :left_w - shift]
            out[r0 + r, :shift] = 6

    # Mark rows where a 6 lies inside the final zero cavity:
    # the row ends with 0 and has a 6 after its first 0.
    for r in range(h):
        row = out[r, :left_w]
        if row[right_edge] != 0:
            continue

        first_zero = None
        for c in range(left_w):
            if row[c] == 0:
                first_zero = c
                break

        if first_zero is None:
            continue

        if np.any(row[first_zero + 1:] == 6):
            out[r, sep + 1:] = 2

    return out.tolist()

