    sep_col = None
    for c in range(w):
        if all(grid[r][c] == 5 for r in range(h)):
            sep_col = c
            break

    # Fallback if no full separator is found.
    if sep_col is None:
        best_col, best_count = 0, -1
        for c in range(w):
            cnt = sum(1 for r in range(h) if grid[r][c] == 5)
            if cnt > best_count:
                best_count, best_col = cnt, c
        sep_col = best_col

    out = [row[:] for row in grid]

    # For each row, shift the 0s to the right by the number of 6s
    # immediately to the right of the rightmost 0 in that row.
    for r in range(h):
        row = grid[r]
        rightmost_zero = -1
        for c in range(sep_col):
            if row[c] == 0:
                rightmost_zero = c

        if rightmost_zero == -1:
            continue

        shift = 0
        c = rightmost_zero + 1
        while c < sep_col and row[c] == 6:
            shift += 1
            c += 1

        # Build the transformed left part.
        new_left = [6] * sep_col
        for c in range(sep_col):
            if row[c] == 0:
                nc = c + shift
                if nc < sep_col:
                    new_left[nc] = 0
        for c in range(sep_col):
            out[r][c] = new_left[c]

    # Put 2s on the right side for rows whose transformed left part
    # has a 0 in the last column and a 6 in the second-last column.
    for r in range(h):
        if sep_col >= 2 and out[r][sep_col - 1] == 0 and out[r][sep_col - 2] == 6:
            for c in range(sep_col + 1, w):
                out[r][c] = 2

    return out

