    if sep_col is None:
        best_col, best_count = 0, -1
        for c in range(w):
            cnt = sum(1 for r in range(h) if grid[r][c] == 5)
            if cnt > best_count:
                best_count, best_col = cnt, c
        sep_col = best_col

    out = [row[:] for row in grid]

    # Work only on the left side of the separator.
    left_w = sep_col

    # Split the left side into vertical blocks separated by all-6 rows.
    r = 0
    while r < h:
        # Skip separator rows (all 6 on the left side).
        if left_w == 0 or all(grid[r][c] == 6 for c in range(left_w)):
            r += 1
            continue

        start = r
        while r < h and not (left_w == 0 or all(grid[r][c] == 6 for c in range(left_w))):
            r += 1
        end = r  # exclusive

