        max_zero_col = -1
        for rr in range(start, end):
            for cc in range(left_w):
                if grid[rr][cc] == 0:
                    max_zero_col = max(max_zero_col, cc)

        if max_zero_col != -1:
            shift = (left_w - 1) - max_zero_col

            # Shift all zeros in this block to the right by `shift`.
            for rr in range(start, end):
