def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape

    # The puzzle uses 5x5 blocks separated by 1-cell lines of 6.
    # Detect the block grid dimensions.
    def block_dims(h, w):
        # A line of blocks has size 5*n - 1.
        if (h - 1) % 5 == 0:
            br = (h - 1) // 5 + 1
        else:
            br = 1
        if (w - 1) % 5 == 0:
            bc = (w - 1) // 5 + 1
        else:
            bc = 1
        return br, bc

    br, bc = block_dims(H, W)

    # Extract all 5x5 blocks.
    blocks = []
    for r in range(br):
        for c in range(bc):
            r0 = r * 6
            c0 = c * 6
            blocks.append((r, c, g[r0:r0 + 5, c0:c0 + 5].copy()))

    # Unfolding order:
    # - 1xN or Nx1: natural order.
    # - 2x2: top-left, bottom-right, top-right, bottom-left.
    # This is equivalent to sorting by distance from the main diagonal,
    # then by diagonal offset, then by row.
    def order_key(pos):
        r, c = pos
        return (abs(r - c), r - c, r, c)

    blocks.sort(key=lambda x: order_key((x[0], x[1])))

    # Output is always a single column of 5x5 blocks separated by 6 rows.
    out_rows = []
    for i, (_, _, b) in enumerate(blocks):
        if i > 0:
            out_rows.append(np.full((1, 5), 6, dtype=int))
        out_rows.append(b)

    return np.vstack(out_rows).tolist()

