def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape

    # The grids are made of 5x5 blocks separated by 1-cell lines of 6.
    # Valid block-line dimensions are 5, 11, 17, 23, ... = 6*n - 1.
    def block_count(dim: int) -> int:
        if (dim + 1) % 6 == 0:
            return (dim + 1) // 6
        return 1

    br = block_count(H)
    bc = block_count(W)

    blocks = []
    for r in range(br):
        for c in range(bc):
            r0 = r * 6
            c0 = c * 6
            b = g[r0:r0 + 5, c0:c0 + 5]
            blocks.append((r, c, b))

    # Sort blocks by the vertical center of their non-background pixels,
    # from bottom to top.  Ties are broken by horizontal center left-to-right,
    # then by original position.
    def key(item):
        r, c, b = item
        mask = b != 7
        if not mask.any():
            return (2.0, 2.0, r, c)
        ys, xs = np.nonzero(mask)
        cy = float(ys.mean())
        cx = float(xs.mean())
        return (-cy, cx, r, c)

    blocks.sort(key=key)

    out_parts = []
    for i, (_, _, b) in enumerate(blocks):
        if i > 0:
            out_parts.append(np.full((1, 5), 6, dtype=int))
        out_parts.append(b)

    return np.vstack(out_parts).tolist()

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape

    # The puzzle grids are 29x29: 7x7 macro cells of 3x3 pixels,
    # separated by 1-pixel separator rows/columns.
    macro_n = (h - 1) // 4  # 7 for the given puzzles
    out = g.copy()

    # Extract macro cells.
    cells = []
    for r in range(macro_n):
        row_cells = []
        for c in range(macro_n):
            r0 = 1 + 4 * r
            c0 = 1 + 4 * c
            row_cells.append(g[r0:r0 + 3, c0:c0 + 3])
        cells.append(row_cells)

    # Identify the special 3x3 tile:
    # it is a non-separator tile that is not the uniform normal tile.
    normal = None
    special = None

    # The normal tile is the most common non-separator tile.
    from collections import Counter
    tile_counter = Counter()
    for r in range(macro_n):
        for c in range(macro_n):
            tile = cells[r][c]
            # Ignore separator-only tiles (should not occur in content cells).
            if np.all(tile == g[0, 0]):
                continue
            tile_counter[tuple(tile.flatten())] += 1

    if not tile_counter:
        return out.tolist()

    normal_flat, _ = tile_counter.most_common(1)[0]
    normal = np.array(normal_flat).reshape(3, 3)

    # Find a tile different from normal.
    for r in range(macro_n):
        for c in range(macro_n):
            tile = cells[r][c]
            if not np.array_equal(tile, normal):
                special = tile
                break
        if special is not None:
            break

    if special is None:
        return out.tolist()

    # The special tile encodes a 3x3 binary mask.
    # The foreground is the majority color inside the special tile.
    vals, counts = np.unique(special, return_counts=True)
    fg = vals[np.argmax(counts)]
    mask = (special == fg).astype(int)

    # Find the full row of the mask (the row that is all 1s).
    full_rows = [i for i in range(3) if np.all(mask[i] == 1)]
    if not full_rows:
        return out.tolist()
    anchor_row = full_rows[0]

    # Find horizontal runs of 3 special macro cells.
    # Each run is the anchor row of a 3x3 macro pattern.
    for r in range(macro_n):
        c = 0
        while c < macro_n:
            if np.array_equal(cells[r][c], special):
                start = c
                while c < macro_n and np.array_equal(cells[r][c], special):
                    c += 1
                end = c - 1
                if end - start + 1 == 3:
                    top = r - anchor_row
                    left = start
                    # Apply the 3x3 mask at macro level.
                    for dr in range(3):
                        for dc in range(3):
                            if mask[dr, dc]:
                                rr = top + dr
                                cc = left + dc
                                if 0 <= rr < macro_n and 0 <= cc < macro_n:
                                    r0 = 1 + 4 * rr
                                    c0 = 1 + 4 * cc
                                    out[r0:r0 + 3, c0:c0 + 3] = special
            else:
                c += 1

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    from collections import Counter

    grid = [list(map(int, row)) for row in grid]
    h, w = len(grid), len(grid[0])

    # Background is the dominant border colour (falling back to global mode).
    border = []
    for c in range(w):
        border.append(grid[0][c])
        border.append(grid[-1][c])
    for r in range(1, h - 1):
        border.append(grid[r][0])
        border.append(grid[r][-1])

    if border:
        bcnt = Counter(border)
        bg, bcount = bcnt.most_common(1)[0]
        if bcount * 2 >= len(border):
            pass
        else:
            bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    else:
        bg = Counter(x for row in grid for x in row).most_common(1)[0][0]

    # 8-connected components of non-background cells.
    seen = [[False] * w for _ in range(h)]
    comps = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or seen[r][c]:
                continue

            stack = [(r, c)]
            seen[r][c] = True
            cells = []
            colors = set()

            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                colors.add(grid[y][x])

                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        if dy == 0 and dx == 0:
                            continue
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w:
                            if not seen[ny][nx] and grid[ny][nx] != bg:
                                seen[ny][nx] = True
                                stack.append((ny, nx))

            rmin = min(y for y, _ in cells)
            rmax = max(y for y, _ in cells)
            cmin = min(x for _, x in cells)
            cmax = max(x for _, x in cells)
            comps.append({
                "cells": cells,
                "colors": colors,
                "rmin": rmin,
                "rmax": rmax,
                "cmin": cmin,
                "cmax": cmax,
            })

    if not comps:
        return grid

    # The tile is the component/object with more distinct non-background colours.
    # If there are extra components, treat the most colourful one as the tile
    # and everything else as the mask.
    def comp_key(comp):
        area = (comp["rmax"] - comp["rmin"] + 1) * (comp["cmax"] - comp["cmin"] + 1)
        return (len(comp["colors"]), area, len(comp["cells"]))

    tile = max(comps, key=comp_key)
    mask_comps = [c for c in comps if c is not tile]

    if not mask_comps:
        return grid

    # Build the mask grid from all non-tile components.
    mrmin = min(c["rmin"] for c in mask_comps)
    mrmax = max(c["rmax"] for c in mask_comps)
    mcmin = min(c["cmin"] for c in mask_comps)
    mcmax = max(c["cmax"] for c in mask_comps)

    mask = [[bg] * (mcmax - mcmin + 1) for _ in range(mrmax - mrmin + 1)]
    for comp in mask_comps:
        for y, x in comp["cells"]:
            mask[y - mrmin][x - mcmin] = grid[y][x]

    # Extract the tile grid.
    trmin, trmax = tile["rmin"], tile["rmax"]
    tcmin, tcmax = tile["cmin"], tile["cmax"]
    tile_grid = [
        [grid[y][x] for x in range(tcmin, tcmax + 1)]
        for y in range(trmin, trmax + 1)
    ]

    mh, mw = len(mask), len(mask[0])
    th, tw = len(tile_grid), len(tile_grid[0])

    out = [[bg] * (mw * tw) for _ in range(mh * th)]

    for i in range(mh):
        for j in range(mw):
            if mask[i][j] != bg:
                for a in range(th):
                    for b in range(tw):
                        out[i * th + a][j * tw + b] = tile_grid[a][b]

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    ones = [(r, c) for r in range(h) for c in range(w) if g[r, c] == 1]
    sixes = [(r, c) for r in range(h) for c in range(w) if g[r, c] == 6]

    # Draw diagonal lines of 1s between pairs of 1s that are exactly diagonal.
    for i in range(len(ones)):
        for j in range(i + 1, len(ones)):
            r1, c1 = ones[i]
            r2, c2 = ones[j]
            dr = r2 - r1
            dc = c2 - c1
            if dr == 0 or dc == 0 or abs(dr) != abs(dc):
                continue

            step_r = 1 if dr > 0 else -1
            step_c = 1 if dc > 0 else -1
            r, c = r1, c1
            while (r, c) != (r2, c2):
                if out[r, c] != 6:
                    out[r, c] = 1
                r += step_r
                c += step_c
            if out[r, c] != 6:
                out[r, c] = 1

    # If a 6 lies on a completed 1-line, extend a perpendicular 6-line through it.
    for r6, c6 in sixes:
        on_one_line = False
        for i in range(len(ones)):
            for j in range(i + 1, len(ones)):
                r1, c1 = ones[i]
                r2, c2 = ones[j]
                dr = r2 - r1
                dc = c2 - c1
                if dr == 0 or dc == 0 or abs(dr) != abs(dc):
                    continue

                # Check whether (r6, c6) is on the segment between the two 1s.
                if (r6 - r1) * dc != (c6 - c1) * dr:
                    continue
                if min(r1, r2) <= r6 <= max(r1, r2) and min(c1, c2) <= c6 <= max(c1, c2):
                    on_one_line = True
                    break
            if on_one_line:
                break

        if not on_one_line:
            continue

        # The 1-line direction is (dr, dc) with |dr| == |dc|.
        # Perpendicular diagonal directions are (dr, -dc) and (-dr, dc).
        # Determine the 1-line direction from the pair that contains this 6.
        for i in range(len(ones)):
            for j in range(i + 1, len(ones)):
                r1, c1 = ones[i]
                r2, c2 = ones[j]
                dr = r2 - r1
                dc = c2 - c1
                if dr == 0 or dc == 0 or abs(dr) != abs(dc):
                    continue
                if (r6 - r1) * dc != (c6 - c1) * dr:
                    continue
                if min(r1, r2) <= r6 <= max(r1, r2) and min(c1, c2) <= c6 <= max(c1, c2):
                    # Perpendicular directions:
                    for sr, sc in ((dr, -dc), (-dr, dc)):
                        sr //= abs(dr)
                        sc //= abs(dc)
                        r, c = r6, c6
                        while 0 <= r < h and 0 <= c < w:
                            if out[r, c] != 1:
                                out[r, c] = 6
                            r += sr
                            c += sc
                    break
            else:
                continue
            break

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
