                stack = [(r, c)]
                visited[r][c] = True
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < left_w:
                            if not visited[ny][nx] and grid[ny][nx] == 0:
                                visited[ny][nx] = True
                                stack.append((ny, nx))
                components.append(cells)

    for cells in components:
        max_c = max(c for _, c in cells)
        shift = (left_w - 1) - max_c
        if shift > 0:
            for r, c in cells:
                out[r][c] = 6
                out[r][c + shift] = 0

    # Find enclosed 6-regions (holes) in the transformed left side.
    # A hole is a 4-connected component of 6s that does not touch the left-side boundary.
    seen = [[False] * left_w for _ in range(h)]
    holes = []

    for r in range(h):
        for c in range(left_w):
            if out[r][c] == 6 and not seen[r][c]:
                stack = [(r, c)]
                seen[r][c] = True
                cells = []
                touches_boundary = False

                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))

                    if y == 0 or y == h - 1 or x == 0 or x == left_w - 1:
                        touches_boundary = True

                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
