                            if not seen[ny][nx] and out[ny][nx] == 6:
                                seen[ny][nx] = True
                                stack.append((ny, nx))

                if not touches_boundary:
                    holes.append(cells)

    # For each 0-component, choose its rightmost hole and paint the right side
    # with 2s on the rows spanned by that hole.
    paint_rows = set()

    for cells in components:
        max_c = max(c for _, c in cells)
        shift = (left_w - 1) - max_c

        comp_set = set()
        for r, c in cells:
            comp_set.add((r, c + shift))

