        best_col = -1

        for hole in holes:
            # Hole must be surrounded by this component.
            surrounded = True
            for y, x in hole:
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < left_w:
