                if not surrounded:
                    break

            if not surrounded:
                continue

            # The hole must be inside the bounding box of this component.
            min_r = min(r for r, _ in comp_set)
            max_r = max(r for r, _ in comp_set)
            min_c = min(c for _, c in comp_set)
            max_c2 = max(c for _, c in comp_set)

