    # Paint the right side of the separator for selected rows.
    for r in paint_rows:
        for c in range(sep_col + 1, w):
            out[r][c] = 2

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])

    # The puzzle layout is a 7x25 grid with four 5x5 panels separated
    # by vertical border lines.  The fourth panel is filled from the
    # second and third panels using a diagonal split indicated by the
    # first panel.
    out = [row[:] for row in grid]

    # Panel columns: 1, 7, 13, 19 (width 5)
    panel_cols = [1, 7, 13, 19]
    size = 5

    # Background is the colour inside the empty fourth panel.
    bg = grid[1][panel_cols[3]]

    # Extract the three source panels as binary masks.
    def mask(panel_idx, color):
        c0 = panel_cols[panel_idx]
        m = [[0] * size for _ in range(size)]
        for r in range(size):
            for c in range(size):
                if grid[1 + r][c0 + c] == color:
                    m[r][c] = 1
        return m

    # Determine the foreground colours of panels A, B, C.
    a_color = b_color = c_color = None
    for r in range(size):
        for c in range(size):
            v = grid[1 + r][panel_cols[0] + c]
            if v != bg and v != grid[0][0]:
                a_color = v
                break
        if a_color is not None:
            break

    for r in range(size):
        for c in range(size):
            v = grid[1 + r][panel_cols[1] + c]
            if v != bg and v != grid[0][0]:
                b_color = v
                break
        if b_color is not None:
            break

    for r in range(size):
        for c in range(size):
            v = grid[1 + r][panel_cols[2] + c]
            if v != bg and v != grid[0][0]:
                c_color = v
                break
        if c_color is not None:
            break

    A = mask(0, a_color)
    B = mask(1, b_color)
    C = mask(2, c_color)

    # Decide which diagonal is the split line.
    #
    # If the first panel contains the anti-diagonal (top-right to bottom-left),
    # use that diagonal: B on/above it, C below it.
    # Otherwise use the main diagonal: B below it, C on/above it.
    anti_score = sum(A[r][size - 1 - r] for r in range(size))
    main_score = sum(A[r][r] for r in range(size))
    use_anti = anti_score >= main_score

    d0 = panel_cols[3]
    for r in range(size):
        for c in range(size):
            if use_anti:
                # r + c <= 4 is the B side, r + c > 4 is the C side.
                if r + c <= 4:
                    val = b_color if B[r][c] else bg
                else:
                    val = c_color if C[r][c] else bg
            else:
                # r > c is the B side, r <= c is the C side.
                if r > c:
                    val = b_color if B[r][c] else bg
                else:
                    val = c_color if C[r][c] else bg
            out[1 + r][d0 + c] = val

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    out = [row[:] for row in grid]

    # The four 5x5 panels start at these columns.
    panel_cols = [1, 7, 13, 19]
    size = 5

    # Background is the empty colour of the fourth panel.
    bg = grid[1][panel_cols[3]]

    def panel_cells(idx):
        c0 = panel_cols[idx]
        return [[grid[1 + r][c0 + c] for c in range(size)] for r in range(size)]

    A = panel_cells(0)
    B = panel_cells(1)
    C = panel_cells(2)

    # Find the single non-background colour in the second and third panels.
    def first_non_bg(panel):
        for r in range(size):
            for c in range(size):
                if panel[r][c] != bg:
                    return panel[r][c]
        return bg

    b_color = first_non_bg(B)
    c_color = first_non_bg(C)

    # In the first panel, one colour forms a 5-cell dividing path plus
    # one isolated marker cell.  The marker tells which side uses panel B.
    a_color = first_non_bg(A)
    a_cells = [(r, c) for r in range(size) for c in range(size) if A[r][c] == a_color]

    # The marker is the only cell not 4-adjacent to any other A-cell.
    marker = None
    for r, c in a_cells:
        adj = False
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < size and 0 <= nc < size and A[nr][nc] == a_color:
                adj = True
                break
        if not adj:
            marker = (r, c)
            break

    # If detection fails for some reason, fall back to the first cell.
    if marker is None:
        marker = a_cells[0]

    path = set(a_cells) - {marker}

    # Flood-fill from the marker through non-path cells to find the B side.
    b_side = set()
    stack = [marker]
    while stack:
        r, c = stack.pop()
        if (r, c) in b_side or (r, c) in path:
            continue
        b_side.add((r, c))
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < size and 0 <= nc < size:
                stack.append((nr, nc))

    d0 = panel_cols[3]
    for r in range(size):
        for c in range(size):
            if (r, c) in path:
                # The dividing line is shared; panel B has priority.
                if B[r][c] != bg:
                    out[1 + r][d0 + c] = b_color
                elif C[r][c] != bg:
                    out[1 + r][d0 + c] = c_color
                else:
                    out[1 + r][d0 + c] = bg
            elif (r, c) in b_side:
                out[1 + r][d0 + c] = b_color if B[r][c] != bg else bg
            else:
                out[1 + r][d0 + c] = c_color if C[r][c] != bg else bg

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Find the unique "source" object: a connected component containing >1 color.
    # In the provided examples/tests this is the small multicolored block.
    seen = np.zeros((h, w), dtype=bool)
    source = None
    for i in range(h):
        for j in range(w):
            if g[i, j] != 0 and not seen[i, j]:
                start = (i, j)
                q = deque([start])
                seen[i, j] = True
                cells = []
                colors = set()
                while q:
                    r, c = q.popleft()
                    cells.append((r, c))
                    colors.add(g[r, c])
                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < h and 0 <= nc < w and not seen[nr, nc] and g[nr, nc] != 0:
                            seen[nr, nc] = True
                            q.append((nr, nc))
                if len(colors) > 1:
                    source = cells
                    break
        if source is not None:
            break

    if source is None:
        return out.tolist()

    # Build directed color mapping from adjacent pairs in the source block.
    # If the source is taller than wide, pairs are horizontal left -> right.
    # If wider than tall, pairs are vertical top -> bottom.
    # If square, use both horizontal and vertical pairs.
    mapping = {}
    sr = [r for r, c in source]
    sc = [c for r, c in source]
    sh = max(sr) - min(sr) + 1
    sw = max(sc) - min(sc) + 1

    def add_pair(a, b):
        if a != 0 and b != 0:
            mapping.setdefault(a, b)

    if sh >= sw:
        # horizontal pairs
        for r, c in source:
            if c + 1 < w and g[r, c + 1] != 0:
                add_pair(g[r, c], g[r, c + 1])
    if sw >= sh:
        # vertical pairs
        for r, c in source:
            if r + 1 < h and g[r + 1, c] != 0:
                add_pair(g[r, c], g[r + 1, c])

    # Find all 4-connected background holes.
    visited = np.zeros((h, w), dtype=bool)
    for i in range(h):
        for j in range(w):
            if g[i, j] == 0 and not visited[i, j]:
                q = deque([(i, j)])
                visited[i, j] = True
                comp = []
                touches_border = False
                while q:
                    r, c = q.popleft()
                    comp.append((r, c))
                    if r == 0 or c == 0 or r == h - 1 or c == w - 1:
                        touches_border = True
                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < h and 0 <= nc < w and not visited[nr, nc] and g[nr, nc] == 0:
                            visited[nr, nc] = True
                            q.append((nr, nc))

                if touches_border or not comp:
                    continue

                # Determine the single color surrounding this hole.
                border_colors = set()
                for r, c in comp:
                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < h and 0 <= nc < w and g[nr, nc] != 0:
                            border_colors.add(g[nr, nc])

                if len(border_colors) != 1:
                    continue

                frame_color = next(iter(border_colors))
                fill_color = mapping.get(frame_color)
                if fill_color is None:
                    continue

                for r, c in comp:
                    out[r, c] = fill_color

    return out.tolist()

import numpy as np
from collections import Counter

def transform(grid: list[list[int]]) -> list[list[int]]:
    a = np.array(grid, dtype=int)
    H, W = a.shape

    # Background is the most frequent colour.
    bg = int(Counter(a.flatten()).most_common(1)[0][0])

    # Connected components of non-background cells (4-connectivity).
    seen = np.zeros((H, W), dtype=bool)
    single_pixels = []
    blocks = []

    for r in range(H):
        for c in range(W):
            if seen[r, c] or a[r, c] == bg:
                continue
            color = int(a[r, c])
            stack = [(r, c)]
            seen[r, c] = True
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < H and 0 <= nx < W and not seen[ny, nx] and a[ny, nx] == color:
                        seen[ny, nx] = True
                        stack.append((ny, nx))

            if len(cells) == 1:
                single_pixels.append((cells[0][0], cells[0][1], color))
            else:
                ys = [p[0] for p in cells]
                xs = [p[1] for p in cells]
                y0, y1 = min(ys), max(ys)
                x0, x1 = min(xs), max(xs)
                h = y1 - y0 + 1
                w = x1 - x0 + 1
                # Keep only clean square blocks.
                if h == w and len(cells) == h * h:
                    blocks.append((y0, x0, h, color))

    if not blocks:
        return [list(row) for row in a]

    # Block size and destination columns.
    k = Counter(b[2] for b in blocks).most_common(1)[0][0]
    block_cols = sorted({b[1] for b in blocks})

    # Source single-pixel matrix.
    src_rows = sorted({p[0] for p in single_pixels})
    src_cols = sorted({p[1] for p in single_pixels})
    R = len(src_rows)
    C = len(src_cols)

    if R == 0 or C == 0:
        return [list(row) for row in a]

    row_idx = {r: i for i, r in enumerate(src_rows)}
    col_idx = {c: j for j, c in enumerate(src_cols)}
    src = [[bg] * C for _ in range(R)]
    for r, c, col in single_pixels:
        if r in row_idx and c in col_idx:
            src[row_idx[r]][col_idx[c]] = col

    # Choose an existing block row that has a block in every destination column.
    by_row = {}
    for y0, x0, size, color in blocks:
        by_row.setdefault(y0, {})[x0] = color

    anchor_row = None
    anchor_colors = None
    for r0 in sorted(by_row):
        if all(c in by_row[r0] for c in block_cols):
            anchor_row = r0
            anchor_colors = [by_row[r0][c] for c in block_cols]
            break

    if anchor_row is None:
        # Fallback: use the row with the most blocks.
        r0 = max(sorted(by_row), key=lambda r: len(by_row[r]))
        anchor_row = r0
        anchor_colors = [by_row[r0].get(c, bg) for c in block_cols]

    D = len(block_cols)

    # Find the source row index that matches the anchor row, and the source
    # columns used for each destination column.
    best = None
    for i0 in range(R):
        start = anchor_row - 5 * i0
        end = start + 5 * (R - 1)
        if start < 0 or end >= H:
            continue

        # Enumerate increasing source-column assignments matching anchor colours.
        candidates = []
        def rec(d, last, chosen):
            if d == D:
                candidates.append(tuple(chosen))
                return
            for c in range(last + 1, C):
                if src[i0][c] == anchor_colors[d]:
                    chosen.append(c)
                    rec(d + 1, c, chosen)
                    chosen.pop()

        rec(0, -1, [])
        if not candidates:
            continue

        # Prefer lexicographically smallest, then columns with more non-bg support.
        def score(t):
            support = tuple(sum(1 for j in range(R) if src[j][c] != bg) for c in t)
            return (t, tuple(-x for x in support))

        cand = min(candidates, key=score)
        # A simple deterministic preference: lexicographically smallest.
        cand = min(candidates)

        # Tie-break among valid i0: prefer the one whose anchor row has the most
        # non-background cells in the chosen columns.
        support = sum(1 for c in cand if src[i0][c] != bg)
        if best is None or support > best[2]:
            best = (i0, start, support, cand)

    if best is None:
        return [list(row) for row in a]

    i0, start, _, chosen_cols = best

    out = a.copy()

    def paint(y0, x0, color):
        if color == bg:
            return
        if y0 < 0 or x0 < 0 or y0 + k > H or x0 + k > W:
            return
        out[y0:y0 + k, x0:x0 + k] = color

    for j in range(R):
        y0 = start + 5 * j
        for d, x0 in enumerate(block_cols):
            c = chosen_cols[d]
            paint(y0, x0, src[j][c])

    return [list(row) for row in out]

import numpy as np
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
