def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # The mask is the 13x13 region whose border is all the same non-zero colour
    # and which contains at least one different non-zero colour inside.
    mask = None
    for r in range(h - 12):
        for c in range(w - 12):
            sub = g[r:r + 13, c:c + 13]
            border = np.concatenate([
                sub[0, :], sub[-1, :], sub[:, 0], sub[:, -1]
            ])
            if len(np.unique(border)) == 1:
                border_val = int(border[0])
                if border_val != 0 and len(np.unique(sub)) > 1:
                    mask = (r, c, sub)
                    break
        if mask is not None:
            break

    if mask is None:
        return [list(row) for row in g]

    r0, c0, sub = mask
    border_val = int(sub[0, 0])
    hole_val = int(np.unique(sub)[1])

    out = sub.copy()

    # Connected components of all non-border, non-hole colours.
    seen = np.zeros((h, w), dtype=bool)
    components = []
    for r in range(h):
        for c in range(w):
            if seen[r, c]:
                continue
            val = int(g[r, c])
            if val == border_val or val == hole_val:
                seen[r, c] = True
                continue
            q = deque([(r, c)])
            seen[r, c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and not seen[ny, nx]:
                            if int(g[ny, nx]) == val:
                                seen[ny, nx] = True
                                q.append((ny, nx))
            components.append((val, cells))

    # For each hole in the mask, choose the colour of the nearest component
    # (by minimum cell-to-cell distance).
    for i in range(13):
        for j in range(13):
            if sub[i, j] != hole_val:
                continue
            ar, ac = r0 + i, c0 + j
            best_val = hole_val
            best_dist = 10**9
            for val, cells in components:
                d = min((ar - y) ** 2 + (ac - x) ** 2 for y, x in cells)
                if d < best_dist:
                    best_dist = d
                    best_val = val
            out[i, j] = best_val

    return [list(row) for row in out]

