    r0, c0, sub = template
    border_val = int(sub[0, 0])
    hole_val = int(np.unique(sub)[1])

    # Connected components of all non-template colours in the whole input.
    seen = np.zeros((h, w), dtype=bool)
    components = []
    for r in range(h):
        for c in range(w):
            if seen[r, c]:
                continue
            val = int(g[r, c])
