def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Identify the background colour (most common colour).
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # Identify the separator colour: a non-background colour that forms
    # at least one full vertical line.
    sep = None
    for c in vals:
        if c == bg:
            continue
        for x in range(w):
            if np.all(g[:, x] == c):
                sep = int(c)
                break
        if sep is not None:
            break

    # If there is a full vertical separator, split into panels.
    if sep is not None:
        sep_cols = [x for x in range(w) if np.all(g[:, x] == sep)]
        bounds = [0] + sep_cols + [w]
        panels = []
        for a, b in zip(bounds[:-1], bounds[1:]):
            if b > a:
                panels.append(g[:, a:b])

        # Choose the panel with the fewest non-background pixels.
        best = min(panels, key=lambda p: int(np.sum(p != bg)))
        out = best.copy()

        # If the chosen panel is empty, use the first panel.
        if np.all(out == bg):
            out = panels[0].copy()

        # If there are multiple panels, shift the selected panel down by
        # the number of panels minus two (this matches the examples).
        if len(panels) > 1:
            shift = len(panels) - 2
            if shift > 0:
                shifted = np.full_like(out, bg)
                shifted[shift:, :] = out[:-shift, :]
                out = shifted

        return out.astype(int).tolist()

    # No full vertical separator: treat the whole grid as one panel.
    return g.astype(int).tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Background is the most common colour.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # Find full vertical separator lines (non-background colour).
    sep_cols = []
    for x in range(w):
        col = g[:, x]
        if np.all(col != bg) and np.unique(col).size == 1:
            sep_cols.append(x)

    # Split into panels.
    if sep_cols:
        bounds = [0] + sep_cols + [w]
        panels = []
        for a, b in zip(bounds[:-1], bounds[1:]):
            if b > a:
                panels.append(g[:, a:b])
    else:
        panels = [g]

    def components(panel):
        ph, pw = panel.shape
        seen = np.zeros((ph, pw), dtype=bool)
        comps = []
        for y in range(ph):
            for x in range(pw):
                if panel[y, x] != bg and not seen[y, x]:
                    q = deque([(y, x)])
                    seen[y, x] = True
                    cells = []
                    while q:
                        cy, cx = q.popleft()
                        cells.append((cy, cx))
                        for dy in (-1, 0, 1):
                            for dx in (-1, 0, 1):
                                if dy == 0 and dx == 0:
                                    continue
                                ny, nx = cy + dy, cx + dx
                                if 0 <= ny < ph and 0 <= nx < pw:
                                    if not seen[ny, nx] and panel[ny, nx] != bg:
                                        seen[ny, nx] = True
                                        q.append((ny, nx))
                    comps.append(cells)
        return comps

    def score(cells):
        ys = [y for y, _ in cells]
        xs = [x for _, x in cells]
        hgt = max(ys) - min(ys) + 1
        wid = max(xs) - min(xs) + 1
        if hgt == 2 and wid == 3:
            # Canonical 2x3 patterns.
            # T: top row full, bottom middle.
            if all((min(ys), min(xs) + dx) in cells for dx in range(3)) and (max(ys), min(xs) + 1) in cells:
                return 100
            # V: top middle, bottom left and right.
            if (min(ys), min(xs) + 1) in cells and (max(ys), min(xs)) in cells and (max(ys), min(xs) + 2) in cells:
                return 90
        # Prefer larger components, then more compact bounding boxes.
        return (len(cells), -hgt * wid)

    best_panel = None
    best_comp = None
    best_key = None

    for panel in panels:
        for comp in components(panel):
            key = (score(comp), len(comp))
            if best_key is None or key > best_key:
                best_key = key
                best_panel = panel
                best_comp = comp

    if best_comp is None:
        return [[int(v) for v in row] for row in g]

    # Build output from the chosen panel, keeping only the chosen component.
    out = np.full(best_panel.shape, bg, dtype=int)
    for y, x in best_comp:
        out[y, x] = best_panel[y, x]

    # Move the component so that its 2x3 anchor aligns with the first
    # non-background cell in the same panel that is not part of the component.
    ys = [y for y, _ in best_comp]
    xs = [x for _, x in best_comp]
    hgt = max(ys) - min(ys) + 1
    wid = max(xs) - min(xs) + 1

    if hgt == 2 and wid == 3:
        top = min(ys)
        left = min(xs)
        # Anchor is the single cell in the row that has only one component cell.
        if sum(1 for y, x in best_comp if y == top) == 1:
            anchor = (top, left + 1)
        else:
            anchor = (top + 1, left + 1)

        comp_set = set(best_comp)
        marker = None
        for y in range(best_panel.shape[0]):
            for x in range(best_panel.shape[1]):
                if best_panel[y, x] != bg and (y, x) not in comp_set:
                    marker = (y, x)
                    break
            if marker is not None:
                break

        if marker is not None:
            dy = marker[0] - anchor[0]
            dx = marker[1] - anchor[1]
            shifted = np.full(best_panel.shape, bg, dtype=int)
            for y, x in best_comp:
                ny, nx = y + dy, x + dx
                if 0 <= ny < shifted.shape[0] and 0 <= nx < shifted.shape[1]:
                    shifted[ny, nx] = best_panel[y, x]
            out = shifted

    return out.astype(int).tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Find the 10x10 frame: the only 10x10 window whose border contains
    # at least 10 non-zero cells.
    best = None
    for r in range(H - 9):
        for c in range(W - 9):
            win = g[r:r + 10, c:c + 10]
            border = np.concatenate([
                win[0, :], win[9, :], win[1:9, 0], win[1:9, 9]
            ])
            nz = int(np.count_nonzero(border))
            if nz >= 10:
                best = (r, c)
                break
        if best is not None:
            break

    r0, c0 = best
    win = g[r0:r0 + 10, c0:c0 + 10].copy()

    # Frame colour is the most common non-zero colour on the border.
    border = np.concatenate([
        win[0, :], win[9, :], win[1:9, 0], win[1:9, 9]
    ])
    vals, counts = np.unique(border[border != 0], return_counts=True)
    frame = int(vals[np.argmax(counts)])

    # Complete the checkerboard frame border.
    for i in range(10):
        for j in range(10):
            if i in (0, 9) or j in (0, 9):
                if (i + j) % 2 == 1:
                    win[i, j] = frame

    # Move interior cells into the completed frame.
    interior = [(i, j, int(win[i, j]))
                for i in range(1, 9)
                for j in range(1, 9)
                if win[i, j] != 0]

    for i in range(1, 9):
        for j in range(1, 9):
            win[i, j] = 0

    for i, j, val in interior:
        # Try the four diagonal directions, in the order that matches the
        # examples: up-left, down-left, up-right, down-right.
        placed = False
        for di, dj in ((-1, -1), (1, -1), (-1, 1), (1, 1)):
            ni, nj = i + di, j + dj
            if 1 <= ni <= 8 and 1 <= nj <= 8 and win[ni, nj] == 0:
                win[ni, nj] = val
                placed = True
                break
        if not placed:
            win[i, j] = val

    return win.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Locate the 10x10 working region.
    # It is the only 10x10 window whose border contains at least 10 non-zero cells.
    best = None
    for r in range(H - 9):
        for c in range(W - 9):
            win = g[r:r + 10, c:c + 10]
            border = np.concatenate([
                win[0, :], win[9, :], win[1:9, 0], win[1:9, 9]
            ])
            if int(np.count_nonzero(border)) >= 10:
                best = (r, c)
                break
        if best is not None:
            break

    r0, c0 = best
    win = g[r0:r0 + 10, c0:c0 + 10].copy()

    # Frame colour: most common non-zero colour on the border.
    border = np.concatenate([
        win[0, :], win[9, :], win[1:9, 0], win[1:9, 9]
    ])
    vals, counts = np.unique(border[border != 0], return_counts=True)
    frame = int(vals[np.argmax(counts)])

    # Complete the checkerboard frame border.
    for i in range(10):
        for j in range(10):
            if i in (0, 9) or j in (0, 9):
                if (i + j) % 2 == 1:
                    win[i, j] = frame

    # Collect interior objects.
    interior = [(i, j, int(win[i, j]))
                for i in range(1, 9)
                for j in range(1, 9)
                if win[i, j] != 0]

    # Clear interior.
    for i in range(1, 9):
        for j in range(1, 9):
            win[i, j] = 0

    # Move each object one step diagonally.
    # Direction is chosen by the first empty diagonal neighbour in this order:
    # up-left, down-left, up-right, down-right.
    for i, j, val in interior:
        placed = False
        for di, dj in ((-1, -1), (1, -1), (-1, 1), (1, 1)):
            ni, nj = i + di, j + dj
            if 1 <= ni <= 8 and 1 <= nj <= 8 and win[ni, nj] == 0:
                win[ni, nj] = val
                placed = True
                break
        if not placed:
            win[i, j] = val

    return win.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    a = np.array(grid, dtype=int)
    h, w = a.shape
    out = np.zeros((h, w), dtype=int)

    # Keep only 1-cells that belong to at least one solid 2x2 block of 1s.
    solid = np.zeros((h, w), dtype=bool)
    if h >= 2 and w >= 2:
        block = (
            (a[:-1, :-1] == 1) &
            (a[:-1, 1:] == 1) &
            (a[1:, :-1] == 1) &
            (a[1:, 1:] == 1)
        )
        solid[:-1, :-1] |= block
        solid[:-1, 1:] |= block
        solid[1:, :-1] |= block
        solid[1:, 1:] |= block

    # Keep only 0-cells that are enclosed by the kept 1-region.
    # A 0 is enclosed if it cannot reach the grid border through 0-cells
    # without crossing kept 1-cells.
    enclosed = np.zeros((h, w), dtype=bool)
    if h > 0 and w > 0:
        visited = np.zeros((h, w), dtype=bool)
        stack = []

        for r in range(h):
            for c in (0, w - 1):
                if a[r, c] == 0 and not visited[r, c]:
                    stack.append((r, c))
                    visited[r, c] = True
        for c in range(w):
            for r in (0, h - 1):
                if a[r, c] == 0 and not visited[r, c]:
                    stack.append((r, c))
                    visited[r, c] = True

        while stack:
            r, c = stack.pop()
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w:
                        if not visited[nr, nc] and a[nr, nc] == 0:
                            visited[nr, nc] = True
                            stack.append((nr, nc))

        enclosed = (a == 0) & (~visited)

    # Base output: kept 1s remain 1.
    out[solid & (a == 1)] = 1

    # For every enclosed 0, paint its 3x3 neighborhood with 7,
    # except the center cell itself.
    for r in range(h):
        for c in range(w):
            if enclosed[r, c]:
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < h and 0 <= nc < w:
                            out[nr, nc] = 7

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    a = np.array(grid, dtype=int)
    h, w = a.shape
    out = a.copy()

    # The puzzle uses 1 as the solid colour and 0 as holes/background.
    # For every 0-cell that is locally isolated from other 0-cells
    # (at most one 4-neighbour is also 0), paint its 3x3 neighbourhood
    # with 7, except that the centre cell itself stays 0.
    for r in range(h):
        for c in range(w):
            if a[r, c] != 0:
                continue

            zero_neighbours = 0
            if r > 0 and a[r - 1, c] == 0:
                zero_neighbours += 1
            if r + 1 < h and a[r + 1, c] == 0:
                zero_neighbours += 1
            if c > 0 and a[r, c - 1] == 0:
                zero_neighbours += 1
            if c + 1 < w and a[r, c + 1] == 0:
                zero_neighbours += 1

            if zero_neighbours <= 1:
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        nr = r + dr
                        nc = c + dc
                        if 0 <= nr < h and 0 <= nc < w:
                            if not (dr == 0 and dc == 0):
                                out[nr, nc] = 7

    return out.tolist()

