import numpy as np
from collections import Counter

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Find horizontal separator rows: rows dominated by 5s.
    hsep = []
    for r in range(H):
        if np.count_nonzero(g[r] == 5) >= max(3, W // 3):
            hsep.append(r)
    if len(hsep) < 2:
        return [[0] * W for _ in range(H)]

    r1, r2 = hsep[0], hsep[-1]
    cell_h = r1
    if cell_h <= 0:
        return [[0] * W for _ in range(H)]

    # Find vertical separator columns: columns dominated by 5s.
    vsep = []
    for c in range(W):
        if np.count_nonzero(g[:, c] == 5) >= max(3, H // 3):
            vsep.append(c)
    if len(vsep) < 2:
        return [[0] * W for _ in range(H)]

    # Infer cell width from the first two separator columns.
    cell_w = vsep[1] - vsep[0] - 1
    if cell_w <= 0:
        return [[0] * W for _ in range(H)]

    # Number of macro columns.
    n_cols = (W - vsep[0]) // (cell_w + 1)
    if n_cols < 1:
        return [[0] * W for _ in range(H)]

    def cell(r0, c0):
        return g[r0:r0 + cell_h, c0:c0 + cell_w]

    # Top row: original shapes.
    top_cells = []
    for i in range(n_cols):
        c0 = vsep[0] + i * (cell_w + 1)
        top_cells.append(cell(0, c0))

    # Middle row: placement masks, colored by the original shape color.
    mid_cells = []
    for i in range(n_cols):
        c0 = vsep[0] + i * (cell_w + 1)
        mid_cells.append(cell(r1 + 1, c0))

    # Bottom row: replacement colors, one per column.
    bottom_colors = []
    for i in range(n_cols):
        c0 = vsep[0] + i * (cell_w + 1)
        sub = g[r2 + 1:, c0:c0 + cell_w]
        vals = sub[sub != 0]
        if vals.size == 0:
            bottom_colors.append(0)
        else:
            bottom_colors.append(int(Counter(vals.tolist()).most_common(1)[0][0]))

    # Map original shape color -> (shape mask, replacement color).
    shape_by_color = {}
    for i, sh in enumerate(top_cells):
        vals = sh[sh != 0]
        if vals.size == 0:
            continue
        orig = int(Counter(vals.tolist()).most_common(1)[0][0])
        shape_by_color[orig] = (sh, bottom_colors[i])

    # Build the N x N macro placement matrix.
    N = cell_h
    macro = np.zeros((N, N), dtype=int)
    for mid in mid_cells:
        vals = mid[mid != 0]
        if vals.size == 0:
            continue
        color = int(Counter(vals.tolist()).most_common(1)[0][0])
        if color not in shape_by_color:
            continue
        mask = (mid != 0)
        macro[mask] = color

    # Assemble output: each macro cell is an N x N block.
    out = np.zeros((N * N, N * N), dtype=int)
    for i in range(N):
        for j in range(N):
            color = int(macro[i, j])
            if color == 0 or color not in shape_by_color:
                continue
            sh, new_color = shape_by_color[color]
            block = np.zeros((N, N), dtype=int)
            block[sh != 0] = new_color
            out[i * N:(i + 1) * N, j * N:(j + 1) * N] = block

    return out.tolist()

import numpy as np
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])
    a = np.array(grid, dtype=int)

    # background is the most frequent colour
    vals, counts = np.unique(a, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # connected components of non-background cells (4-connectivity)
    seen = np.zeros((h, w), dtype=bool)
    comps = []
    for r in range(h):
        for c in range(w):
            if a[r, c] != bg and not seen[r, c]:
                q = deque([(r, c)])
                seen[r, c] = True
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w:
                            if not seen[ny, nx] and a[ny, nx] != bg:
                                seen[ny, nx] = True
                                q.append((ny, nx))
                comps.append(cells)

    # For each component, find its key cell:
    # the cell whose colour occurs exactly once in that component.
    # If there is no such cell, the component is not moved.
    moves = []
    for cells in comps:
        if len(cells) == 1:
            continue
        col_counts = {}
        for y, x in cells:
            col_counts[a[y, x]] = col_counts.get(a[y, x], 0) + 1
        key_cells = [(y, x) for y, x in cells if col_counts[a[y, x]] == 1]
        if len(key_cells) == 1:
            moves.append(key_cells[0])

    if not moves:
        return [[int(v) for v in row] for row in a]

    # Determine movement axis from the border side of the key cells.
    # top/bottom border -> horizontal movement, left/right border -> vertical movement.
    top = bottom = left = right = False
    for y, x in moves:
        if y == 0:
            top = True
        if y == h - 1:
            bottom = True
        if x == 0:
            left = True
        if x == w - 1:
            right = True

    if top or bottom:
        axis = 'h'
    elif left or right:
        axis = 'v'
    else:
        # Fallback: choose the axis with more border key cells.
        axis = 'h' if (top + bottom) >= (left + right) else 'v'

    # Target coordinate for each key colour.
    target = {}
    for y, x in moves:
        col = int(a[y, x])
        if axis == 'h':
            target[col] = x
        else:
            target[col] = y

    out = a.copy()

    # Remove all moving components.
    moving_cells = set()
    for cells in comps:
        if len(cells) == 1:
            continue
        col_counts = {}
        for y, x in cells:
            col_counts[a[y, x]] = col_counts.get(a[y, x], 0) + 1
        key_cells = [(y, x) for y, x in cells if col_counts[a[y, x]] == 1]
        if len(key_cells) == 1:
            moving_cells.update(cells)

    for y, x in moving_cells:
        out[y, x] = bg

    # Re-insert moved components.
    for cells in comps:
        if len(cells) == 1:
            continue
        col_counts = {}
        for y, x in cells:
            col_counts[a[y, x]] = col_counts.get(a[y, x], 0) + 1
        key_cells = [(y, x) for y, x in cells if col_counts[a[y, x]] == 1]
        if len(key_cells) != 1:
            continue

        ky, kx = key_cells[0]
        kcol = int(a[ky, kx])
        if kcol not in target:
            continue

        if axis == 'h':
            shift = target[kcol] - kx
            dy, dx = 0, shift
        else:
            shift = target[kcol] - ky
            dy, dx = shift, 0

        for y, x in cells:
            ny, nx = y + dy, x + dx
            if 0 <= ny < h and 0 <= nx < w:
                out[ny, nx] = a[y, x]

    return [[int(v) for v in row] for row in out]

