def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Background is the border colour (also the most frequent colour in the examples).
    bg = g[0, 0]

    # Find the first non-background cell in row-major order.
    start = None
    for r in range(h):
        for c in range(w):
            if g[r, c] != bg:
                start = (r, c)
                break
        if start is not None:
            break

    out = g.copy()

    if start is None:
        return out.tolist()

    # 8-connected component containing that cell.
    sr, sc = start
    seen = np.zeros((h, w), dtype=bool)
    stack = [(sr, sc)]
    seen[sr, sc] = True

    while stack:
        r, c = stack.pop()
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and not seen[nr, nc] and g[nr, nc] != bg:
                    seen[nr, nc] = True
                    stack.append((nr, nc))

    # Recolour the selected component:
    # odd original colours become 3, even original colours become 5.
    for r in range(h):
        for c in range(w):
            if seen[r, c]:
                out[r, c] = 3 if (g[r, c] % 2 == 1) else 5

    return out.tolist()

