        n = len(poly)
        for i in range(n):
            x1, y1 = poly[i]
            x2, y2 = poly[(i + 1) % n]
            if (y1 > y) != (y2 > y):
                xint = x1 + (y - y1) * (x2 - x1) / (y2 - y1)
                if x < xint:
                    inside = not inside
        return inside

    for quad in combinations(pts, 4):
        hull = convex_hull(quad)
        if len(hull) != 4:
            continue

        rmin = min(p[0] for p in hull)
        rmax = max(p[0] for p in hull)
        cmin = min(p[1] for p in hull)
        cmax = max(p[1] for p in hull)

        for r in range(rmin, rmax + 1):
            for c in range(cmin, cmax + 1):
                if g[r, c] == bg and point_in_poly((r, c), hull):
                    out[r, c] = 2

    return [[int(x) for x in row] for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Determine the background colour as the most frequent colour.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # Connected components of non-background cells (8-neighbourhood).
    seen = np.zeros((H, W), dtype=bool)
    comps = []
    for r in range(H):
        for c in range(W):
            if g[r, c] != bg and not seen[r, c]:
                q = deque([(r, c)])
                seen[r, c] = True
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < H and 0 <= nx < W:
                                if not seen[ny, nx] and g[ny, nx] != bg:
                                    seen[ny, nx] = True
                                    q.append((ny, nx))
                comps.append(cells)

    # For each colour, find isolated cells of that colour (single-cell components).
    isolated = {}
    for cells in comps:
        if len(cells) == 1:
            y, x = cells[0]
            col = int(g[y, x])
            isolated.setdefault(col, []).append((y, x))

    # For each component, find a marker colour:
    # a non-background colour that appears exactly once in the component
    # and has at least one isolated cell elsewhere.
    moves = []
    for cells in comps:
        if len(cells) == 1:
            continue
        cnt = {}
        for y, x in cells:
            col = int(g[y, x])
            cnt[col] = cnt.get(col, 0) + 1
        marker = None
        for col, n in cnt.items():
            if n == 1 and col in isolated:
                marker = col
                break
        if marker is None:
            continue

        # Choose the isolated reference of the marker colour.
        # Prefer one on an edge; if several, choose the one that gives
        # the smallest absolute shift for the marker cell.
        marker_pos = next((y, x) for y, x in cells if int(g[y, x]) == marker)
        refs = isolated[marker]
        best_ref = None
        best_score = None
        for ry, rx in refs:
            # Axis:
            # - if reference is on left/right edge, align rows
            # - if reference is on top/bottom edge, align columns
            # - otherwise use the larger coordinate difference.
            on_lr = (rx == 0 or rx == W - 1)
            on_tb = (ry == 0 or ry == H - 1)
            if on_lr and not on_tb:
                axis = 'row'
            elif on_tb and not on_lr:
                axis = 'col'
            else:
                axis = 'row' if abs(ry - marker_pos[0]) >= abs(rx - marker_pos[1]) else 'col'

            if axis == 'row':
                shift = (ry - marker_pos[0], 0)
            else:
                shift = (0, rx - marker_pos[1])

            score = (abs(shift[0]) + abs(shift[1]), abs(shift[0]), abs(shift[1]))
            if best_score is None or score < best_score:
                best_score = score
                best_ref = (ry, rx, axis)

        if best_ref is None:
            continue
        ry, rx, axis = best_ref
        if axis == 'row':
            shift = (ry - marker_pos[0], 0)
        else:
            shift = (0, rx - marker_pos[1])
        if shift != (0, 0):
            moves.append((cells, shift))

    # Apply all moves.  If two moved components overlap, keep the one with
    # the smaller total shift; this matches the examples and avoids ambiguity.
    out = np.full((H, W), bg, dtype=int)

    # Place stationary components first.
    moved_cells = set()
    for cells, shift in moves:
        for y, x in cells:
            moved_cells.add((y, x))

    for cells in comps:
        if any((y, x) in moved_cells for y, x in cells):
            continue
        for y, x in cells:
            out[y, x] = g[y, x]

    # Sort moved components by shift magnitude.
    moves.sort(key=lambda t: abs(t[1][0]) + abs(t[1][1]))
    placed = np.zeros((H, W), dtype=bool)

    for cells, (dy, dx) in moves:
        new_cells = []
        ok = True
        for y, x in cells:
            ny, nx = y + dy, x + dx
            if not (0 <= ny < H and 0 <= nx < W) or placed[ny, nx]:
                ok = False
                break
            new_cells.append((ny, nx))
        if not ok:
            continue
        for ny, nx in new_cells:
            out[ny, nx] = g[ny - dy, nx - dx]
            placed[ny, nx] = True

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Background is the most frequent colour.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # 8-connected components of non-background cells.
    seen = np.zeros((H, W), dtype=bool)
    comps = []
    for r in range(H):
        for c in range(W):
            if g[r, c] != bg and not seen[r, c]:
                q = deque([(r, c)])
                seen[r, c] = True
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < H and 0 <= nx < W:
                                if not seen[ny, nx] and g[ny, nx] != bg:
                                    seen[ny, nx] = True
                                    q.append((ny, nx))
                comps.append(cells)

    # Anchor cells: isolated non-background cells on the border.
    # They define a colour and a line:
    #   left/right border  -> horizontal line (row)
    #   top/bottom border  -> vertical line (column)
    anchors = {}
    for y, x in [(r, c) for r in range(H) for c in range(W)]:
        if g[y, x] == bg:
            continue
        if not (y == 0 or y == H - 1 or x == 0 or x == W - 1):
            continue
        if any(
            0 <= y + dy < H and 0 <= x + dx < W and g[y + dy, x + dx] != bg
            for dy in (-1, 0, 1)
            for dx in (-1, 0, 1)
            if (dy, dx) != (0, 0)
        ):
            continue
        col = int(g[y, x])
        if col not in anchors:
            anchors[col] = (y, x)

    # For every component, find a marker colour:
    # a colour that appears exactly once in the component and has an anchor.
    moves = []
    for cells in comps:
        if len(cells) == 1:
            continue
        cnt = {}
        for y, x in cells:
            col = int(g[y, x])
            cnt[col] = cnt.get(col, 0) + 1

