        if (
            marker_pos[0] * 2 == min_y + max_y
            and marker_pos[1] * 2 == min_x + max_x
        ):
            if shift[0] != 0:
                if ax < marker_pos[1]:
                    shift = (shift[0], -1)
                elif ax > marker_pos[1]:
                    shift = (shift[0], 1)
            else:
                if ay < marker_pos[0]:
                    shift = (-1, shift[1])
                elif ay > marker_pos[0]:
                    shift = (1, shift[1])

        if shift != (0, 0):
            moves.append((cells, shift))

    # Apply moves.  Stationary components are placed first.
    out = np.full((H, W), bg, dtype=int)
    moved_cells = set()
    for cells, _ in moves:
        for y, x in cells:
            moved_cells.add((y, x))

    for cells in comps:
        if any((y, x) in moved_cells for y, x in cells):
            continue
        for y, x in cells:
            out[y, x] = g[y, x]

    # If two moved components overlap, keep the one with the smaller shift.
    moves.sort(key=lambda t: abs(t[1][0]) + abs(t[1][1]))
    placed = np.zeros((H, W), dtype=bool)

    for cells, (dy, dx) in moves:
        new_cells = []
        ok = True
