def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # background is the most frequent colour
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # non-background colours, sorted by frequency (least frequent first)
    nonbg = [int(v) for v in vals if v != bg]
    nonbg.sort(key=lambda c: int(np.sum(g == c)))

    if len(nonbg) < 3:
        return [list(map(int, row)) for row in g]

    keep = nonbg[0]
    paint = set(nonbg[1:])

    # 8-connected components of the two paint colours
    mask = np.isin(g, list(paint))
    seen = np.zeros((h, w), dtype=bool)
    comps = []

    for r in range(h):
        for c in range(w):
            if mask[r, c] and not seen[r, c]:
                q = deque([(r, c)])
                seen[r, c] = True
                comp = []
                while q:
                    y, x = q.popleft()
                    comp.append((y, x))
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            if dy == 0 and dx == 0:
                                continue
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < h and 0 <= nx < w:
                                if mask[ny, nx] and not seen[ny, nx]:
                                    seen[ny, nx] = True
                                    q.append((ny, nx))
                comps.append(comp)

    out = g.copy()

    for comp in comps:
        # component must touch the least-frequent colour (8-neighbourhood)
        touches_keep = False
        for y, x in comp:
            for dy in (-1, 0, 1):
                for dx in (-1, 0, 1):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and g[ny, nx] == keep:
                        touches_keep = True
                        break
                if touches_keep:
                    break
            if touches_keep:
                break

        if not touches_keep:
            continue

        # keep only the part of the component that is 8-connected to the keep colour
        seed = []
        for y, x in comp:
            for dy in (-1, 0, 1):
                for dx in (-1, 0, 1):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and g[ny, nx] == keep:
                        seed.append((y, x))
                        break
                else:
                    continue
                break

        if not seed:
            continue

        comp_set = set(comp)
        reachable = set()
        q = deque(seed)
        for s in seed:
            reachable.add(s)
        while q:
            y, x = q.popleft()
            for dy in (-1, 0, 1):
                for dx in (-1, 0, 1):
                    if dy == 0 and dx == 0:
                        continue
                    ny, nx = y + dy, x + dx
                    if (ny, nx) in comp_set and (ny, nx) not in reachable:
                        reachable.add((ny, nx))
                        q.append((ny, nx))

        for y, x in reachable:
            if g[y, x] == 1:
                out[y, x] = 3
            elif g[y, x] == 6:
                out[y, x] = 5
            elif g[y, x] == 0:
                out[y, x] = 5
            elif g[y, x] == 2:
                out[y, x] = 3
            else:
                # generic fallback: map the two paint colours to 3/5 by frequency order
                if g[y, x] == nonbg[1]:
                    out[y, x] = 3
                elif g[y, x] == nonbg[2]:
                    out[y, x] = 5

    return [list(map(int, row)) for row in out]

