def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Find all solid rectangular frames.
    # A frame is a rectangle whose border is one solid color and whose
    # interior is mostly another solid color.
    frames = []
    for r0 in range(H):
        for c0 in range(W):
            border = g[r0, c0]
            if border == 0:
                continue
            for r1 in range(r0 + 2, H):
                if g[r1, c0] != border:
                    continue
                for c1 in range(c0 + 2, W):
                    if g[r0, c1] != border or g[r1, c1] != border:
                        continue
                    # Check full border
                    ok = True
                    for r in range(r0, r1 + 1):
                        if g[r, c0] != border or g[r, c1] != border:
                            ok = False
                            break
                    if not ok:
                        continue
                    for c in range(c0, c1 + 1):
                        if g[r0, c] != border or g[r1, c] != border:
                            ok = False
                            break
                    if not ok:
                        continue

                    # Interior must be mostly one fill color.
                    interior = g[r0 + 1:r1, c0 + 1:c1]
                    if interior.size == 0:
                        continue
                    vals, counts = np.unique(interior, return_counts=True)
                    fill = int(vals[np.argmax(counts)])
                    if fill == border:
                        continue
                    if counts.max() < 0.75 * interior.size:
                        continue

                    frames.append((r0, c0, r1, c1, border, fill))

    if not frames:
        return [list(map(int, row)) for row in g]

    # Choose the frame that best matches the demonstrated target:
    # border/fill pair sums to 7, and it contains marker 1s.
    def score(f):
        r0, c0, r1, c1, border, fill = f
        s = 0
        if border + fill == 7:
            s += 100
        interior = g[r0 + 1:r1, c0 + 1:c1]
        if np.any(interior == 1):
            s += 50
        # Prefer larger frames slightly.
        s += (r1 - r0 + 1) * (c1 - c0 + 1) / 1000.0
        return s

    frames.sort(key=score, reverse=True)
    r0, c0, r1, c1, border, fill = frames[0]

    out = g[r0:r1 + 1, c0:c1 + 1].copy()

    # For every marker 1 strictly inside the chosen frame, paint a plus
    # of 8s around it, keeping the center 1.
    for r in range(r0 + 1, r1):
        for c in range(c0 + 1, c1):
            if g[r, c] == 1:
                out[r - r0, c - c0] = 1
                for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                    rr, cc = r + dr, c + dc
                    if r0 < rr < r1 and c0 < cc < c1:
                        out[rr - r0, cc - c0] = 8

    return [list(map(int, row)) for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Find the wall color: most frequent non-zero color that is not 4.
    counts = {}
    for r in range(h):
        for c in range(w):
            v = int(g[r, c])
            if v != 0 and v != 4:
                counts[v] = counts.get(v, 0) + 1

    if not counts:
        return [[int(x) for x in row] for row in g]

    wall = max(counts, key=lambda k: counts[k])

    out = g.copy()

    # Collect all 4s first so movement is simultaneous.
    fours = [(r, c) for r in range(h) for c in range(w) if g[r, c] == 4]

    for r, c in fours:
        # Expand horizontally to the full run of non-wall cells containing (r, c).
        left = c
        while left > 0 and out[r, left - 1] != wall:
            left -= 1

        right = c
        while right < w - 1 and out[r, right + 1] != wall:
            right += 1

        # Choose target end based on the wall color.
        if wall == 5:
            target = left
        else:
            target = right

        if target != c:
            out[r, c] = 0
            out[r, target] = 4

    return [[int(x) for x in row] for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Determine the background colour as the most frequent colour.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # Candidate colours are all non-background colours.
    candidates = [int(c) for c in vals if c != bg]

    def neighbors8(r, c):
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w:
                    yield nr, nc

    def component_cells(start, allowed):
        """8-connected component of cells whose colour is in allowed."""
        stack = [start]
        seen = {start}
        cells = []
        while stack:
            r, c = stack.pop()
            cells.append((r, c))
            for nr, nc in neighbors8(r, c):
                if (nr, nc) not in seen and g[nr, nc] in allowed:
                    seen.add((nr, nc))
                    stack.append((nr, nc))
        return cells

    def component_score(cells):
        """
        Score a component by how much it looks like a thin path/line:
        - prefer components with exactly two colours
        - prefer larger components
        - prefer low average 8-neighbour degree
        """
        if not cells:
            return (-1, -1, 10**9)

        colours = {g[r, c] for r, c in cells}
        if len(colours) != 2:
            return (-1, -len(cells), 10**9)

        cell_set = set(cells)
        deg_sum = 0
        for r, c in cells:
            deg = 0
            for nr, nc in neighbors8(r, c):
                if (nr, nc) in cell_set:
                    deg += 1
            deg_sum += deg

        avg_deg = deg_sum / len(cells)
        return (0, len(cells), -avg_deg)

    # Find all 8-connected components of non-background cells.
    visited = set()
    best_cells = None
    best_score = None

    for r in range(h):
        for c in range(w):
            if (r, c) in visited or g[r, c] == bg:
                continue
            cells = component_cells((r, c), set(candidates))
            visited.update(cells)

            score = component_score(cells)
            if best_score is None or score > best_score:
                best_score = score
                best_cells = cells

    # If no suitable two-colour component is found, return unchanged.
    if not best_cells:
        return [[int(x) for x in row] for row in g]

    # The two colours in the selected component are mapped to 5 and 3.
    # In the examples, the smaller original colour becomes 5 and the larger becomes 3.
    colours = sorted({int(g[r, c]) for r, c in best_cells})
    mapping = {colours[0]: 5, colours[1]: 3}

    out = g.copy()
    for r, c in best_cells:
        out[r, c] = mapping[int(g[r, c])]

    return [[int(x) for x in row] for row in out]

