            # find right
            c1 = c0
            while c1 + 1 < w and g[r0, c1 + 1] == border:
                c1 += 1
            if c1 == c0:
                continue
            # verify full border
            ok = True
            for c in range(c0, c1 + 1):
                if g[r0, c] != border or g[r1, c] != border:
                    ok = False
                    break
            if not ok:
                continue
            for r in range(r0, r1 + 1):
                if g[r, c0] != border or g[r, c1] != border:
                    ok = False
                    break
            if not ok:
                continue
            # interior must not be border color
            interior = g[r0 + 1:r1, c0 + 1:c1]
            if interior.size == 0 or np.all(interior == border):
                continue
            frames.append((r0, c0, r1, c1, border))

    if not frames:
        return [list(map(int, row)) for row in g]

    # Choose the target frame: the one whose interior contains the marker 8
    # but no 2s. If multiple, choose the largest.
    target = None
    for fr in frames:
        r0, c0, r1, c1, _ = fr
        interior = g[r0 + 1:r1, c0 + 1:c1]
        if interior.size == 0:
            continue
        has8 = np.any(interior == 8)
        has2 = np.any(interior == 2)
        if has8 and not has2:
            area = (r1 - r0 + 1) * (c1 - c0 + 1)
            if target is None or area > target[0]:
                target = (area, fr)

    if target is None:
        # Fallback: largest frame containing 8.
        best = None
        for fr in frames:
            r0, c0, r1, c1, _ = fr
            interior = g[r0 + 1:r1, c0 + 1:c1]
            if interior.size and np.any(interior == 8):
                area = (r1 - r0 + 1) * (c1 - c0 + 1)
                if best is None or area > best[0]:
                    best = (area, fr)
        if best is None:
            return [list(map(int, row)) for row in g]
        target = best

    _, (tr0, tc0, tr1, tc1, tborder) = target
    out = g[tr0:tr1 + 1, tc0:tc1 + 1].copy()

    # Find a source frame that contains both 2 and 8.
    source = None
    for fr in frames:
        r0, c0, r1, c1, _ = fr
        if (r0, c0, r1, c1) == (tr0, tc0, tr1, tc1):
            continue
        interior = g[r0 + 1:r1, c0 + 1:c1]
        if interior.size and np.any(interior == 2) and np.any(interior == 8):
            area = (r1 - r0 + 1) * (c1 - c0 + 1)
            if source is None or area > source[0]:
                source = (area, fr)

    if source is not None:
        sr0, sc0, sr1, sc1, _ = source[1]
        sinterior = g[sr0 + 1:sr1, sc0 + 1:sc1]
        sh, sw = sinterior.shape

        # Learn the relative pattern of 2s around each 8 in the source.
        offsets = set()
        for r in range(sh):
            for c in range(sw):
                if sinterior[r, c] == 8:
                    for dr in range(-2, 3):
                        for dc in range(-2, 3):
                            rr, cc = r + dr, c + dc
                            if 0 <= rr < sh and 0 <= cc < sw and sinterior[rr, cc] == 2:
                                offsets.add((dr, dc))

        # Apply the learned 2-pattern around every 8 in the target interior.
        tinterior = out[1:-1, 1:-1]
        th, tw = tinterior.shape
        for r in range(th):
            for c in range(tw):
                if tinterior[r, c] == 8:
                    for dr, dc in offsets:
                        rr, cc = r + dr, c + dc
                        if 0 <= rr < th and 0 <= cc < tw:
                            tinterior[rr, cc] = 2

    return [list(map(int, row)) for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Fixed line colours used by the generated lines.
    H_COLORS = (6, 5, 1)   # for vertical 7x2 / 9x2 markers
    V_COLORS = (1, 5, 6)   # for horizontal 2x7 / 2x9 markers

    # ------------------------------------------------------------------
    # 1) Vertical markers: 7x2 or 9x2 blocks.
    #    They generate three horizontal lines on the side containing 2s.
    # ------------------------------------------------------------------
    for r in range(h):
        for c in range(w - 1):
            block = g[r:r + 9, c:c + 2]
            if block.shape != (9, 2):
                continue

            # Must be a compact non-background block.
            if not np.all(block != 8):
                continue

            # The side with 2s determines the direction.
            left_has_2 = np.any(block[:, 0] == 2)
            right_has_2 = np.any(block[:, 1] == 2)
            if left_has_2 == right_has_2:
                continue

            # The other side must be the 4/3/1 pattern.
            if left_has_2:
                other = block[:, 1]
            else:
                other = block[:, 0]

            if not np.all((other == 4) | (other == 3) | (other == 1)):
                continue

            # Rows 1, 4, 5 of the marker produce the three lines.
            line_rows = (1, 4, 5)

            if left_has_2:
                # Draw to the left of the marker.
                for dr, col in zip(line_rows, H_COLORS):
                    rr = r + dr
                    if 0 <= rr < h:
                        out[rr, 0:c] = col
            else:
                # Draw to the right of the marker.
                for dr, col in zip(line_rows, H_COLORS):
                    rr = r + dr
                    if 0 <= rr < h:
                        out[rr, c + 2:w] = col

    # ------------------------------------------------------------------
    # 2) Horizontal markers: 2x7 or 2x9 blocks.
    #    They generate three vertical lines downward.
    # ------------------------------------------------------------------
    for r in range(h):
        for c in range(w - 8):
            for width in (7, 9):
                block = g[r:r + 2, c:c + width]
                if block.shape != (2, width):
                    continue

                if not np.all(block != 8):
                    continue

                # The side with 2s determines the vertical line positions.
                top_has_2 = np.any(block[0, :] == 2)
                bottom_has_2 = np.any(block[1, :] == 2)
                if top_has_2 == bottom_has_2:
                    continue

                # The other side must be the 4/3/1 pattern.
                if top_has_2:
                    other = block[1, :]
                else:
                    other = block[0, :]

                if not np.all((other == 4) | (other == 3) | (other == 1)):
                    continue

                # Columns 1, 2, 5 of the marker produce the three lines.
                line_cols = (1, 2, 5)

                for dc, col in zip(line_cols, V_COLORS):
                    cc = c + dc
                    if 0 <= cc < w:
                        out[r + 2:h, cc] = col

                break

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # ------------------------------------------------------------------
    # Vertical emitters: 7x2 or 9x2 blocks.
    #
    # The side containing 2s determines the direction:
    #   2s on left  -> draw horizontal lines to the left
    #   2s on right -> draw horizontal lines to the right
    #
    # Line rows and colours are fixed:
    #   7x2: rows 1, 4, 5 with colours 6, 5, 1
    #   9x2: rows 1, 4, 7 with colours 6, 5, 1
    # ------------------------------------------------------------------
    for r in range(h):
        for c in range(w - 1):
            for height in (7, 9):
                if r + height > h:
                    continue

                block = g[r:r + height, c:c + 2]

                # The emitter must be a solid non-background 2-column block.
                if not np.all(block != 8):
                    continue

                left = block[:, 0]
                right = block[:, 1]

                left_has_2 = np.any(left == 2)
                right_has_2 = np.any(right == 2)

                # Exactly one side is the 2-side.
                if left_has_2 == right_has_2:
                    continue

                # The other side must be made only of the pattern colours.
                if left_has_2:
                    other = right
                else:
                    other = left

                if not np.all((other == 1) | (other == 3) | (other == 4)):
                    continue

                if height == 7:
                    line_rows = (1, 4, 5)
                else:
                    line_rows = (1, 4, 7)

                line_cols = (6, 5, 1)

                if left_has_2:
                    # Draw to the left of the emitter.
                    for dr, col in zip(line_rows, line_cols):
                        rr = r + dr
                        if 0 <= rr < h:
                            out[rr, 0:c] = col
                else:
                    # Draw to the right of the emitter.
                    for dr, col in zip(line_rows, line_cols):
                        rr = r + dr
                        if 0 <= rr < h:
                            out[rr, c + 2:w] = col

                break

    # ------------------------------------------------------------------
    # Horizontal emitters: 2x7 or 2x9 blocks.
    #
    # The side containing 2s determines the direction:
    #   2s on bottom -> draw vertical lines downward
    #   2s on top    -> draw vertical lines upward
    #
    # Line columns and colours are fixed:
    #   2x7: columns 1, 2, 5 with colours 1, 5, 6
    #   2x9: columns 1, 2, 7 with colours 1, 5, 6
    # ------------------------------------------------------------------
    for r in range(h):
        for c in range(w - 8):
            for width in (7, 9):
                if c + width > w:
                    continue

                block = g[r:r + 2, c:c + width]

                # The emitter must be a solid non-background 2-row block.
                if not np.all(block != 8):
                    continue

                top = block[0, :]
                bottom = block[1, :]

                top_has_2 = np.any(top == 2)
                bottom_has_2 = np.any(bottom == 2)

                # Exactly one side is the 2-side.
                if top_has_2 == bottom_has_2:
                    continue

                # The other side must be made only of the pattern colours.
                if top_has_2:
                    other = bottom
                else:
                    other = top

                if not np.all((other == 1) | (other == 3) | (other == 4)):
                    continue

                if width == 7:
                    line_cols = (1, 2, 5)
                else:
                    line_cols = (1, 2, 7)

                line_colors = (1, 5, 6)

                if bottom_has_2:
                    # Draw downward from below the emitter.
                    for dc, col in zip(line_cols, line_colors):
                        cc = c + dc
                        if 0 <= cc < w:
                            out[r + 2:h, cc] = col
                else:
                    # Draw upward from above the emitter.
                    for dc, col in zip(line_cols, line_colors):
                        cc = c + dc
                        if 0 <= cc < w:
                            out[0:r, cc] = col

                break

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Find the frame colour: the non-zero colour that forms the largest
    # connected component (8-connected) in the input.
    colors = [c for c in range(1, 10) if np.any(g == c)]
    if not colors:
        return []

    def component_size(color):
        mask = (g == color)
        seen = np.zeros_like(mask, dtype=bool)
        best = 0
        for i in range(H):
            for j in range(W):
                if mask[i, j] and not seen[i, j]:
                    stack = [(i, j)]
                    seen[i, j] = True
                    size = 0
                    while stack:
                        y, x = stack.pop()
                        size += 1
                        for dy in (-1, 0, 1):
                            for dx in (-1, 0, 1):
                                ny, nx = y + dy, x + dx
                                if 0 <= ny < H and 0 <= nx < W:
                                    if mask[ny, nx] and not seen[ny, nx]:
                                        seen[ny, nx] = True
                                        stack.append((ny, nx))
                    if size > best:
                        best = size
        return best

    frame_color = max(colors, key=component_size)

    # Bounding box of the main frame component.
    mask = (g == frame_color)
    seen = np.zeros_like(mask, dtype=bool)
    comp = None
    for i in range(H):
        for j in range(W):
            if mask[i, j] and not seen[i, j]:
                stack = [(i, j)]
                seen[i, j] = True
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < H and 0 <= nx < W:
                                if mask[ny, nx] and not seen[ny, nx]:
                                    seen[ny, nx] = True
                                    stack.append((ny, nx))
                if comp is None or len(cells) > len(comp):
                    comp = cells

    ys = [p[0] for p in comp]
    xs = [p[1] for p in comp]
    r0, r1 = min(ys), max(ys)
    c0, c1 = min(xs), max(xs)
    h = r1 - r0 + 1
    w = c1 - c0 + 1

    # The output is a square of side max(height, width).
    # The frame is centred in this square; the interior is taken from the
    # corresponding centred part of the input bounding box.
    n = max(h, w)
    out = np.zeros((n, n), dtype=int)

    # Place the frame colour exactly where it appears in the input bbox,
    # shifted so that the bbox is centred in the output square.
    dr = (n - h) // 2
    dc = (n - w) // 2
    for y in range(r0, r1 + 1):
        for x in range(c0, c1 + 1):
            if g[y, x] == frame_color:
                out[y - r0 + dr, x - c0 + dc] = frame_color

    # Copy all non-frame, non-zero pixels from the input bbox into the
    # centred output square.
    for y in range(r0, r1 + 1):
        for x in range(c0, c1 + 1):
            v = g[y, x]
            if v != 0 and v != frame_color:
                out[y - r0 + dr, x - c0 + dc] = v

    return out.tolist()

