def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Walls are the non-zero, non-4 colours that form the maze/frame.
    wall = (g != 0) & (g != 4)

    # For every wall cell, find the nearest 4 in each of the four directions.
    # If a wall cell is the first wall encountered from a 4 in that direction,
    # the 4 is pushed to the empty cell immediately before that wall.
    targets = {}

    for r in range(h):
        for c in range(w):
            if not wall[r, c]:
                continue

            # Up
            rr, cc = r - 1, c
            while rr >= 0 and not wall[rr, cc]:
                if g[rr, cc] == 4:
                    targets[(rr, cc)] = (rr + 1, cc)
                    break
                rr -= 1

            # Down
            rr, cc = r + 1, c
            while rr < h and not wall[rr, cc]:
                if g[rr, cc] == 4:
                    targets[(rr, cc)] = (rr - 1, cc)
                    break
                rr += 1

            # Left
            rr, cc = r, c - 1
            while cc >= 0 and not wall[rr, cc]:
                if g[rr, cc] == 4:
                    targets[(rr, cc)] = (rr, cc + 1)
                    break
                cc -= 1

            # Right
            rr, cc = r, c + 1
            while cc < w and not wall[rr, cc]:
                if g[rr, cc] == 4:
                    targets[(rr, cc)] = (rr, cc - 1)
                    break
                cc += 1

    out = g.copy()

    # Remove all original 4s.
    out[g == 4] = 0

    # Place each 4 at its resolved target.
    for (r, c), (tr, tc) in targets.items():
        out[tr, tc] = 4

    return out.tolist()

