def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # The fill colour is the unique colour in the input.
    # If there is more than one, prefer the one that is not used as a
    # surrounding wall colour for any fillable zero component.
    counts = {}
    for r in range(h):
        for c in range(w):
            v = int(g[r, c])
            if v != 0:
                counts[v] = counts.get(v, 0) + 1

    unique_colours = [v for v, n in counts.items() if n == 1]

    # Find all 4-connected zero components.
    seen = np.zeros((h, w), dtype=bool)
    components = []

    for r in range(h):
        for c in range(w):
            if g[r, c] != 0 or seen[r, c]:
                continue

            q = deque([(r, c)])
            seen[r, c] = True
            cells = []
            boundary_colours = set()

            while q:
                y, x = q.popleft()
                cells.append((y, x))

                for dy, dx in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w:
                        v = int(g[ny, nx])
                        if v == 0:
                            if not seen[ny, nx]:
                                seen[ny, nx] = True
                                q.append((ny, nx))
                        else:
                            boundary_colours.add(v)

            components.append((cells, boundary_colours))

    # A component is fillable if all its non-zero neighbours are the same colour.
    fillable = []
    for cells, boundary_colours in components:
        if len(boundary_colours) == 1:
            fillable.append((cells, boundary_colours.pop()))

    # Choose the fill colour.
    fill_colour = 4
    if unique_colours:
        # Prefer a unique colour that is not itself a wall colour of a fillable component.
        wall_colours = set(wall for _, wall in fillable)
        good = [v for v in unique_colours if v not in wall_colours]
        if good:
            fill_colour = good[0]
        else:
            fill_colour = unique_colours[0]

    # Fill all fillable components.
    for cells, wall in fillable:
        for y, x in cells:
            out[y, x] = fill_colour

    return out.tolist()

