from collections import Counter

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Find all 6x6 "frames": a 6x6 square whose border is one non-8 color
    # and whose interior contains at least one different non-8 color.
    frames = []
    for r in range(H - 5):
        for c in range(W - 5):
            sub = g[r:r+6, c:c+6]
            border = sub[0, 0]
            if border == 8:
                continue
            if not np.all(sub[0, :] == border) or not np.all(sub[5, :] == border):
                continue
            if not np.all(sub[:, 0] == border) or not np.all(sub[:, 5] == border):
                continue
            inner = sub[1:5, 1:5]
            inner_vals = inner[inner != 8]
            if inner_vals.size == 0:
                continue
            if np.all(inner_vals == border):
                continue
            frames.append((r, c, int(border)))

    # Keep only maximal frames: discard a frame if it is fully contained
    # in another frame with the same border color.
    def contained(a, b):
        ar, ac, _ = a
        br, bc, _ = b
        return br <= ar and bc <= ac and br + 6 >= ar + 6 and bc + 6 >= ac + 6

    maximal = []
    for f in frames:
        if not any(f2 != f and f2[2] == f[2] and contained(f, f2) for f2 in frames):
            maximal.append(f)

    if not maximal:
        return []

    # For each maximal frame, find the nearest other maximal frame.
    # The nearest frame's border color is used to fill 8s inside this frame.
    tiles = []
    for f in maximal:
        r, c, border = f
        best = None
        best_d = None
        for f2 in maximal:
            if f2 is f:
                continue
            r2, c2, _ = f2
            d = (r - r2) ** 2 + (c - c2) ** 2
            if best_d is None or d < best_d:
                best_d = d
                best = f2

        if best is None:
            continue

        fill_color = best[2]
        sub = g[r:r+6, c:c+6].copy()
        sub[sub == 8] = fill_color
        tiles.append((r, c, sub))

    # Arrange tiles in a compact grid preserving their relative positions.
    rows = sorted({r for r, _, _ in tiles})
    cols = sorted({c for _, c, _ in tiles})

    # Cluster nearby coordinates so that tiles that are visually in the same
    # row/column are placed in the same output row/column.
    def cluster(vals, tol=6):
        vals = sorted(vals)
        groups = []
        for v in vals:
            if not groups or v - groups[-1][-1] > tol:
                groups.append([v])
            else:
                groups[-1].append(v)
        return [sum(grp) / len(grp) for grp in groups]

    row_clusters = cluster(rows)
    col_clusters = cluster(cols)

    def nearest_idx(v, clusters):
        return min(range(len(clusters)), key=lambda i: abs(clusters[i] - v))

    out = np.zeros((len(row_clusters) * 6, len(col_clusters) * 6), dtype=int)
    for r, c, tile in tiles:
        ri = nearest_idx(r, row_clusters)
        ci = nearest_idx(c, col_clusters)
        out[ri * 6:(ri + 1) * 6, ci * 6:(ci + 1) * 6] = tile

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    a = np.array(grid, dtype=int)
    h, w = a.shape

    # The non-background colour is the one that is not the most common colour.
    vals, counts = np.unique(a, return_counts=True)
    if len(vals) == 1:
        return [[int(x) for x in row] for row in a]
    bg = int(vals[np.argmax(counts)])
    fg = int(vals[np.argmin(counts)])

    out = a.copy()

    # Fill gaps in horizontal lines.
    for r in range(h):
        cols = np.where(a[r] == fg)[0]
        if len(cols) < 2:
            continue
        for i in range(len(cols) - 1):
            c1, c2 = int(cols[i]), int(cols[i + 1])
            gap = c2 - c1 - 1
            if 1 <= gap <= 3:
                # Fill only if the gap is "supported" by foreground pixels
                # immediately above or below the gap.
                if r > 0 and np.any(a[r - 1, c1 + 1:c2] == fg):
                    out[r, c1 + 1:c2] = fg
                if r + 1 < h and np.any(a[r + 1, c1 + 1:c2] == fg):
                    out[r, c1 + 1:c2] = fg

    # Fill gaps in vertical lines.
    for c in range(w):
        rows = np.where(a[:, c] == fg)[0]
        if len(rows) < 2:
            continue
        for i in range(len(rows) - 1):
            r1, r2 = int(rows[i]), int(rows[i + 1])
            gap = r2 - r1 - 1
            if 1 <= gap <= 3:
                # Fill only if the gap is "supported" by foreground pixels
                # immediately to the left or right of the gap.
                if c > 0 and np.any(a[r1 + 1:r2, c - 1] == fg):
                    out[r1 + 1:r2, c] = fg
                if c + 1 < w and np.any(a[r1 + 1:r2, c + 1] == fg):
                    out[r1 + 1:r2, c] = fg

    # Remove foreground pixels that are not part of a sufficiently long
    # horizontal or vertical run in the original grid.
    keep = np.zeros((h, w), dtype=bool)

    # Horizontal runs.
    for r in range(h):
        c = 0
        while c < w:
            if a[r, c] == fg:
                c2 = c
                while c2 + 1 < w and a[r, c2 + 1] == fg:
                    c2 += 1
                if c2 - c + 1 >= 3:
                    keep[r, c:c2 + 1] = True
                c = c2 + 1
            else:
                c += 1

    # Vertical runs.
    for c in range(w):
        r = 0
        while r < h:
            if a[r, c] == fg:
                r2 = r
                while r2 + 1 < h and a[r2 + 1, c] == fg:
                    r2 += 1
                if r2 - r + 1 >= 3:
                    keep[r:r2 + 1, c] = True
                r = r2 + 1
            else:
                r += 1

    # Keep filled cells and original cells that belong to long runs.
    final = np.where((a == fg) & keep, fg, bg)
    final = np.where(out == fg, fg, final)

    return [[int(x) for x in row] for row in final]

