            continue
        for i in range(len(rows) - 1):
            r1, r2 = int(rows[i]), int(rows[i + 1])
            gap = r2 - r1 - 1
            if 1 <= gap <= 3:
                # Fill only if the gap is supported by foreground pixels
                # immediately to the left or right of the gap.
                if c > 0 and np.any(a[r1 + 1:r2, c - 1] == fg):
                    out[r1 + 1:r2, c] = fg
                if c + 1 < w and np.any(a[r1 + 1:r2, c + 1] == fg):
                    out[r1 + 1:r2, c] = fg

    # Keep only foreground pixels that belong to a sufficiently long
    # horizontal or vertical run in the original grid, plus filled cells.
    keep = np.zeros((h, w), dtype=bool)

    # Horizontal runs of length at least 3.
    for r in range(h):
        c = 0
        while c < w:
            if a[r, c] == fg:
                c2 = c
                while c2 + 1 < w and a[r, c2 + 1] == fg:
                    c2 += 1
                if c2 - c + 1 >= 3:
