                while r2 + 1 < h and a[r2 + 1, c] == fg:
                    r2 += 1
                if r2 - r + 1 >= 3:
                    keep[r:r2 + 1, c] = True
                r = r2 + 1
            else:
                r += 1

    # Final grid: background, then original kept pixels, then filled pixels.
    final = np.full((h, w), bg, dtype=int)
    final[(a == fg) & keep] = fg
    final[out == fg] = fg

