def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Find the three "key" colors: non-background colors that are not 1, 2, or 4.
    # In the examples these are 3, 6, 9.  Sort them ascending so the rule is
    # deterministic and matches the observed color order.
    keys = sorted({int(v) for v in g.flat if v not in (0, 1, 2, 4, 8)})
    if len(keys) < 3:
        return out.tolist()
    c1, c2, c3 = keys[0], keys[1], keys[2]

    # Identify the three wire objects.
    # A vertical object is a 2-column block whose two columns are filled with
    # only 1/2/4 for at least 7 consecutive rows.
    # A horizontal object is a 2-row block whose two rows are filled with only
    # 1/2/4 for at least 7 consecutive columns.
    wire = np.isin(g, [1, 2, 4])

    verticals = []
    for r in range(h):
        for c in range(w - 1):
            if wire[r, c] and wire[r, c + 1]:
                rr = r
                while rr + 1 < h and wire[rr + 1, c] and wire[rr + 1, c + 1]:
                    rr += 1
                length = rr - r + 1
                if length >= 7:
                    verticals.append((r, c, rr, c + 1))

    horizontals = []
    for r in range(h - 1):
        for c in range(w):
            if wire[r, c] and wire[r + 1, c]:
                cc = c
                while cc + 1 < w and wire[r, cc + 1] and wire[r + 1, cc + 1]:
                    cc += 1
                length = cc - c + 1
                if length >= 7:
                    horizontals.append((r, c, r + 1, cc))

    # Merge overlapping bounding boxes.
    def merge(boxes):
        boxes = list(boxes)
        changed = True
        while changed:
            changed = False
            merged = []
            used = [False] * len(boxes)
            for i, b in enumerate(boxes):
                if used[i]:
                    continue
                r1, c1, r2, c2 = b
                for j in range(i + 1, len(boxes)):
                    if used[j]:
                        continue
                    a1, b1, a2, b2 = boxes[j]
                    if r1 <= a2 and a1 <= r2 and c1 <= b2 and b1 <= c2:
                        r1, c1 = min(r1, a1), min(c1, b1)
                        r2, c2 = max(r2, a2), max(c2, b2)
                        used[j] = True
                        changed = True
                used[i] = True
                merged.append((r1, c1, r2, c2))
            boxes = merged
        return boxes

    vboxes = merge(verticals)
    hboxes = merge(horizontals)

    # Keep the three largest objects of each orientation.
    vboxes.sort(key=lambda b: (b[2] - b[0] + 1) * (b[3] - b[1] + 1), reverse=True)
    hboxes.sort(key=lambda b: (b[2] - b[0] + 1) * (b[3] - b[1] + 1), reverse=True)
    vboxes = vboxes[:3]
    hboxes = hboxes[:3]

    # Paint vertical objects.
    for (r1, c1, r2, c2) in vboxes:
        # The 1-column is the "spine"; the other column is the side.
        col1_count = int(np.sum(wire[r1:r2 + 1, c1] & (g[r1:r2 + 1, c1] == 1)))
        col2_count = int(np.sum(wire[r1:r2 + 1, c2] & (g[r1:r2 + 1, c2] == 1)))
        spine = c1 if col1_count >= col2_count else c2
        side = c2 if spine == c1 else c1

        # Paint to the side opposite the 2/4 side.
        if side > spine:
            paint_left = True
        else:
            paint_left = False

        for k, color in enumerate((c1, c2, c3)):
            r = r1 + 1 + 2 * k
            if r > r2:
                break
            if paint_left:
                for cc in range(0, spine):
                    if out[r, cc] == 8:
                        out[r, cc] = color
            else:
                for cc in range(spine + 1, w):
                    if out[r, cc] == 8:
                        out[r, cc] = color

    # Paint horizontal objects.
    for (r1, c1, r2, c2) in hboxes:
        # The 1-row is the "spine"; the other row is the side.
        row1_count = int(np.sum(wire[r1, c1:c2 + 1] & (g[r1, c1:c2 + 1] == 1)))
        row2_count = int(np.sum(wire[r2, c1:c2 + 1] & (g[r2, c1:c2 + 1] == 1)))
        spine = r1 if row1_count >= row2_count else r2
        side = r2 if spine == r1 else r1

        # Paint to the side opposite the 2/4 side.
        if side > spine:
            paint_up = True
        else:
            paint_up = False

        # The horizontal object emits three spaced cells, starting four columns
        # from its left edge and stepping by two, with colors in reverse order.
        for k, color in enumerate((c3, c2, c1)):
            c = c1 + 4 + 2 * k
            if c > c2 + 1:
                break
            if paint_up:
                for rr in range(0, spine):
                    if out[rr, c] == 8:
                        out[rr, c] = color
            else:
                for rr in range(spine + 1, h):
                    if out[rr, c] == 8:
                        out[rr, c] = color

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Structural colors are the “wire” colors.  In the examples these are 1, 2, 4.
    # Other non-background colors are the palette colors that get drawn.
    wire = np.isin(g, [1, 2, 4])

    # Palette: all non-background, non-wire colors, sorted ascending.
    palette = sorted({int(v) for v in g.flat if v not in (0, 8) and not wire.flat})
    if not palette:
        return out.tolist()

    # Find vertical 2-column wire objects.
    verticals = []
    for r in range(h):
        for c in range(w - 1):
            if wire[r, c] and wire[r, c + 1]:
                rr = r
                while rr + 1 < h and wire[rr + 1, c] and wire[rr + 1, c + 1]:
                    rr += 1
                if rr - r + 1 >= 5:
                    verticals.append((r, c, rr, c + 1))

    # Find horizontal 2-row wire objects.
    horizontals = []
    for r in range(h - 1):
        for c in range(w):
            if wire[r, c] and wire[r + 1, c]:
                cc = c
                while cc + 1 < w and wire[r, cc + 1] and wire[r + 1, cc + 1]:
                    cc += 1
                if cc - c + 1 >= 5:
                    horizontals.append((r, c, r + 1, cc))

    # Merge overlapping bounding boxes.
    def merge(boxes):
        boxes = list(boxes)
        changed = True
        while changed:
            changed = False
            merged = []
            used = [False] * len(boxes)
            for i, b in enumerate(boxes):
                if used[i]:
                    continue
                r1, c1, r2, c2 = b
                for j in range(i + 1, len(boxes)):
                    if used[j]:
                        continue
                    a1, b1, a2, b2 = boxes[j]
                    if r1 <= a2 and a1 <= r2 and c1 <= b2 and b1 <= c2:
                        r1, c1 = min(r1, a1), min(c1, b1)
                        r2, c2 = max(r2, a2), max(c2, b2)
                        used[j] = True
                        changed = True
                used[i] = True
                merged.append((r1, c1, r2, c2))
            boxes = merged
        return boxes

    vboxes = merge(verticals)
    hboxes = merge(horizontals)

    # Keep the largest objects.
    vboxes.sort(key=lambda b: (b[2] - b[0] + 1) * (b[3] - b[1] + 1), reverse=True)
    hboxes.sort(key=lambda b: (b[2] - b[0] + 1) * (b[3] - b[1] + 1), reverse=True)

    def paint_line(r, c, color, direction):
        # direction: 'L', 'R', 'U', 'D'
        if direction == 'L':
            for cc in range(c - 1, -1, -1):
                if out[r, cc] == 8:
                    out[r, cc] = color
                else:
                    break
        elif direction == 'R':
            for cc in range(c + 1, w):
                if out[r, cc] == 8:
                    out[r, cc] = color
                else:
                    break
        elif direction == 'U':
            for rr in range(r - 1, -1, -1):
                if out[rr, c] == 8:
                    out[rr, c] = color
                else:
                    break
        elif direction == 'D':
            for rr in range(r + 1, h):
                if out[rr, c] == 8:
                    out[rr, c] = color
                else:
                    break

    # For each object, draw up to three lines using the palette.
    # The example uses the first three palette colors in order.
    colors = palette[:3]

    for (r1, c1, r2, c2) in vboxes:
        # Determine which column is the 2/4 side.
        left_24 = int(np.sum((g[r1:r2 + 1, c1] == 2) | (g[r1:r2 + 1, c1] == 4)))
        right_24 = int(np.sum((g[r1:r2 + 1, c2] == 2) | (g[r1:r2 + 1, c2] == 4)))
        if left_24 >= right_24:
            side_col = c1
            direction = 'R'
        else:
            side_col = c2
            direction = 'L'

        # Three ports: one row below the top, then every second row.
        for i, color in enumerate(colors):
            r = r1 + 1 + 2 * i
            if r > r2:
                break
            paint_line(r, side_col, color, direction)

    for (r1, c1, r2, c2) in hboxes:
        # Determine which row is the 2/4 side.
        top_24 = int(np.sum((g[r1, c1:c2 + 1] == 2) | (g[r1, c1:c2 + 1] == 4)))
        bottom_24 = int(np.sum((g[r2, c1:c2 + 1] == 2) | (g[r2, c1:c2 + 1] == 4)))
        if top_24 >= bottom_24:
            side_row = r1
            direction = 'D'
        else:
            side_row = r2
            direction = 'U'

        # Three ports: one column right of the left edge, then every second column.
        for i, color in enumerate(colors):
            c = c1 + 1 + 2 * i
            if c > c2:
                break
            paint_line(side_row, c, color, direction)

    return out.tolist()

import numpy as np
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape
    seen = np.zeros((h, w), dtype=bool)
    comps = []

    # 8-connected components of non-zero cells
    for r in range(h):
        for c in range(w):
            if g[r, c] != 0 and not seen[r, c]:
                q = deque([(r, c)])
                seen[r, c] = True
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < h and 0 <= nx < w:
                                if not seen[ny, nx] and g[ny, nx] != 0:
                                    seen[ny, nx] = True
                                    q.append((ny, nx))

                ys = [y for y, _ in cells]
                xs = [x for _, x in cells]
                r0, r1 = min(ys), max(ys)
                c0, c1 = min(xs), max(xs)
                pat = g[r0:r1 + 1, c0:c1 + 1].copy()
                comps.append({
                    "pat": pat,
                    "has5": bool((pat == 5).any()),
                })

    if len(comps) != 4:
        return [list(map(int, row)) for row in g]

    n = max(max(p["pat"].shape) for p in comps) + 1

    def rotations(pat):
        p = pat
        return [p, np.rot90(p, 1), np.rot90(p, 2), np.rot90(p, 3)]

    def place(out, pat, corner):
        ph, pw = pat.shape
        if corner == "tl":
            out[:ph, :pw] = np.where(pat != 0, pat, out[:ph, :pw])
        elif corner == "tr":
            out[:ph, n - pw:] = np.where(pat != 0, pat, out[:ph, n - pw:])
        elif corner == "bl":
            out[n - ph:, :pw] = np.where(pat != 0, pat, out[n - ph:, :pw])
        else:
            out[n - ph:, n - pw:] = np.where(pat != 0, pat, out[n - ph:, n - pw:])

    # The component with color 5 is always top-left.
    # Rotate it so the 5 pixel is at the top-left corner of its bounding box.
    five_comp = next(c for c in comps if c["has5"])
    five_rot = None
    for rot in rotations(five_comp["pat"]):
        if rot[0, 0] == 5:
            five_rot = rot
            break
    if five_rot is None:
        five_rot = five_comp["pat"]

    out = np.zeros((n, n), dtype=int)
    place(out, five_rot, "tl")

    remaining = [c for c in comps if not c["has5"]]
    corners = ["tr", "bl", "br"]

    # Try all assignments and rotations for the remaining three components.
    # Score by how many non-zero cells of each placed component are visible
    # in the final output after applying the fixed overlap priority.
    best = None
    best_score = -1

    for perm in [(0, 1, 2), (0, 2, 1), (1, 0, 2), (1, 2, 0), (2, 0, 1), (2, 1, 0)]:
        a, b, c = remaining[perm[0]], remaining[perm[1]], remaining[perm[2]]
        for ra in rotations(a["pat"]):
            for rb in rotations(b["pat"]):
                for rc in rotations(c["pat"]):
                    trial = np.zeros((n, n), dtype=int)
                    place(trial, five_rot, "tl")
                    place(trial, ra, corners[0])
                    place(trial, rb, corners[1])
                    place(trial, rc, corners[2])

                    score = 0
                    for pat in (five_rot, ra, rb, rc):
                        score += int((pat != 0).sum())
                    # Prefer solutions where more original non-zero cells survive.
                    score += int((trial != 0).sum())

                    if score > best_score:
                        best_score = score
                        best = trial

    if best is None:
        return [list(map(int, row)) for row in g]

    return [list(map(int, row)) for row in best]

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # The fill colour is the colour that appears exactly once in the input.
    fill_color = None
    for c in range(1, 10):
        if np.count_nonzero(g == c) == 1:
            fill_color = c
            break

    if fill_color is None:
        return [list(row) for row in g]

    # Flood-fill all background (0) cells that are connected to the border.
    outside = np.zeros((h, w), dtype=bool)
    q = deque()

    for r in range(h):
        for c in (0, w - 1):
            if g[r, c] == 0 and not outside[r, c]:
                outside[r, c] = True
                q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if g[r, c] == 0 and not outside[r, c]:
                outside[r, c] = True
                q.append((r, c))

    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
                if g[nr, nc] == 0 and not outside[nr, nc]:
                    outside[nr, nc] = True
                    q.append((nr, nc))

    # Fill enclosed background cells with the unique colour.
    out = g.copy()
    enclosed = (g == 0) & (~outside)
    out[enclosed] = fill_color

    return [list(row) for row in out]

