        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
                if g[nr, nc] == 0 and not outside[nr, nc]:
                    outside[nr, nc] = True
                    q.append((nr, nc))

    # Enclosed background cells are holes.
    holes = (g == 0) & (~outside)

    # For each hole, find the colour of its boundary.
    # Fill the hole only if that boundary colour is adjacent to a 1.
    out = g.copy()
    seen_hole = np.zeros((h, w), dtype=bool)

    for r in range(h):
        for c in range(w):
            if holes[r, c] and not seen_hole[r, c]:
                # BFS over this hole.
                hq = deque([(r, c)])
                seen_hole[r, c] = True
                cells = [(r, c)]
                boundary_colors = set()

                while hq:
                    cr, cc = hq.popleft()
                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < h and 0 <= nc < w:
                            if holes[nr, nc] and not seen_hole[nr, nc]:
                                seen_hole[nr, nc] = True
                                hq.append((nr, nc))
                                cells.append((nr, nc))
                            elif g[nr, nc] != 0:
                                boundary_colors.add(int(g[nr, nc]))

                # Check whether any boundary colour touches a 1.
                fill_this_hole = False
                for color in boundary_colors:
                    mask = (g == color)
                    # Dilate by one cell and test for 1.
                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        shifted = np.zeros_like(mask)
                        r0, r1 = max(0, dr), min(h, h + dr)
                        c0, c1 = max(0, dc), min(w, w + dc)
                        shifted[r0:r1, c0:c1] = mask[r0 - dr:r1 - dr, c0 - dc:c1 - dc]
                        if np.any(shifted & (g == 1)):
                            fill_this_hole = True
                            break
                    if fill_this_hole:
                        break

                if fill_this_hole:
                    for rr, cc in cells:
                        out[rr, cc] = fill_color

    return [list(row) for row in out]

