def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Identify the three relevant colors:
    # - background: most frequent color
    # - line: second most frequent color
    # - foreground: the remaining color
    vals, counts = np.unique(g, return_counts=True)
    order = np.argsort(-counts)
    bg = int(vals[order[0]])
    line = int(vals[order[1]])
    fg = int(vals[order[2]])

    out = g.copy()

    # Find all line cells.
    line_cells = [(r, c) for r in range(h) for c in range(w) if g[r, c] == line]
    if not line_cells:
        return out.tolist()

    line_set = set(line_cells)

    # Build 4-neighbor graph on line cells.
    adj = {cell: [] for cell in line_cells}
    for r, c in line_cells:
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nb = (r + dr, c + dc)
            if nb in line_set:
                adj[(r, c)].append(nb)

    # Find the unique 3x3 ring of line cells that remains unchanged.
    # It is a 3x3 square whose border is all line and whose center is line.
    ring = None
    for r in range(h - 2):
        for c in range(w - 2):
            border = [
                (r, c), (r, c + 1), (r, c + 2),
                (r + 1, c), (r + 1, c + 2),
                (r + 2, c), (r + 2, c + 1), (r + 2, c + 2),
            ]
            center = (r + 1, c + 1)
            if all(cell in line_set for cell in border) and center in line_set:
                ring = border + [center]
                break
        if ring is not None:
            break

    # If no ring is found, fall back to leaving all line cells unchanged.
    if ring is None:
        return out.tolist()

    ring_set = set(ring)
    center = (ring[7][0], ring[7][1])

    # Remove the ring from the line graph and color each remaining component
    # by the foreground color adjacent to its boundary.
    remaining = [cell for cell in line_cells if cell not in ring_set]
    seen = set()

    for start in remaining:
        if start in seen:
            continue

        # BFS component.
        comp = []
        q = deque([start])
        seen.add(start)
        while q:
            cell = q.popleft()
            comp.append(cell)
            for nb in adj[cell]:
                if nb in ring_set:
                    continue
                if nb not in seen:
                    seen.add(nb)
                    q.append(nb)

        # Find foreground colors adjacent to this component.
        colors = set()
        for r, c in comp:
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and g[nr, nc] == fg:
                    colors.add(fg)

        # In these puzzles there is exactly one foreground color.
        fill = fg if colors else fg

        for r, c in comp:
            out[r, c] = fill

    # Fill the center of the ring with the foreground color.
    out[center[0], center[1]] = fg

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Colors: background is most frequent, line is second most frequent,
    # the remaining color is the other foreground color.
    vals, counts = np.unique(g, return_counts=True)
    order = np.argsort(-counts)
    bg = int(vals[order[0]])
    line = int(vals[order[1]])
    fg = int(vals[order[2]])

    out = g.copy()

    # Find the unique 3x3 block whose border is all line color.
    ring = None
    for r in range(h - 2):
        for c in range(w - 2):
            border = [
                (r, c), (r, c + 1), (r, c + 2),
                (r + 1, c), (r + 1, c + 2),
                (r + 2, c), (r + 2, c + 1), (r + 2, c + 2),
            ]
            if all(g[x, y] == line for x, y in border):
                ring = border
                break
        if ring is not None:
            break

    if ring is None:
        return out.tolist()

    ring_set = set(ring)
    center = (ring[7][0], ring[7][1])

    # Build graph of line cells, excluding the ring border.
    line_cells = [(r, c) for r in range(h) for c in range(w)
                  if g[r, c] == line and (r, c) not in ring_set]
    line_set = set(line_cells)
    adj = {cell: [] for cell in line_cells}
    for r, c in line_cells:
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nb = (r + dr, c + dc)
            if nb in line_set:
                adj[(r, c)].append(nb)

    # For each line component, determine which foreground color it should become.
    # The component is assigned the foreground color that appears in the
    # 3x3 neighborhood of the ring side it attaches to.  If it does not attach
    # to the ring, use the foreground color nearest to the component.
    seen = set()
    for start in line_cells:
        if start in seen:
            continue

        comp = []
        q = deque([start])
        seen.add(start)
        while q:
            cell = q.popleft()
            comp.append(cell)
            for nb in adj[cell]:
                if nb not in seen:
                    seen.add(nb)
                    q.append(nb)

        # Check attachment to the ring border.
        attached_side = None
        for r, c in comp:
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nb = (r + dr, c + dc)
                if nb in ring_set:
                    # Determine which side of the ring this attachment is on.
                    rr, cc = nb
                    cr, cc0 = center
                    if rr < cr:
                        attached_side = 'top'
                    elif rr > cr:
                        attached_side = 'bottom'
                    elif cc < cc0:
                        attached_side = 'left'
                    elif cc > cc0:
                        attached_side = 'right'
                    break
            if attached_side:
                break

        if attached_side:
            # Look at the 3x3 area just outside the ring on that side.
            cr, cc0 = center
            if attached_side == 'top':
                area = [(cr - 2, cc0 - 1), (cr - 2, cc0), (cr - 2, cc0 + 1),
                        (cr - 1, cc0 - 1), (cr - 1, cc0 + 1)]
            elif attached_side == 'bottom':
                area = [(cr + 2, cc0 - 1), (cr + 2, cc0), (cr + 2, cc0 + 1),
                        (cr + 1, cc0 - 1), (cr + 1, cc0 + 1)]
            elif attached_side == 'left':
                area = [(cr - 1, cc0 - 2), (cr, cc0 - 2), (cr + 1, cc0 - 2),
                        (cr - 1, cc0 - 1), (cr + 1, cc0 - 1)]
            else:  # right
                area = [(cr - 1, cc0 + 2), (cr, cc0 + 2), (cr + 1, cc0 + 2),
                        (cr - 1, cc0 + 1), (cr + 1, cc0 + 1)]

            color = None
            for r, c in area:
                if 0 <= r < h and 0 <= c < w and g[r, c] != bg and g[r, c] != line:
                    color = int(g[r, c])
                    break

            if color is None:
                color = fg
        else:
            # Fallback: nearest non-background, non-line color to the component.
            best_color = fg
            best_dist = 10**9
            for r, c in comp:
                for rr in range(max(0, r - 3), min(h, r + 4)):
                    for cc in range(max(0, c - 3), min(w, c + 4)):
                        val = int(g[rr, cc])
                        if val != bg and val != line:
                            d = abs(r - rr) + abs(c - cc)
                            if d < best_dist:
                                best_dist = d
                                best_color = val
            color = best_color

        for r, c in comp:
            out[r, c] = color

    # The center of the ring takes the color of the component attached to the
    # side with the larger foreground region; in the given puzzles this is the
    # color found in the 3x3 neighborhood just outside the ring's right side.
    cr, cc0 = center
    center_color = fg
    for r, c in [(cr, cc0 + 2), (cr - 1, cc0 + 2), (cr + 1, cc0 + 2),
                 (cr - 1, cc0 + 1), (cr + 1, cc0 + 1)]:
        if 0 <= r < h and 0 <= c < w and g[r, c] != bg and g[r, c] != line:
            center_color = int(g[r, c])
            break

    out[center] = center_color
    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Find connected non-zero components (4-connectivity).
    seen = np.zeros((h, w), dtype=bool)
    comps = []
    for r in range(h):
        for c in range(w):
            if g[r, c] != 0 and not seen[r, c]:
                q = deque([(r, c)])
                seen[r, c] = True
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and not seen[ny, nx] and g[ny, nx] != 0:
                            seen[ny, nx] = True
                            q.append((ny, nx))
                ys = [p[0] for p in cells]
                xs = [p[1] for p in cells]
                r0, r1 = min(ys), max(ys)
                c0, c1 = min(xs), max(xs)
                colors = {}
                for y, x in cells:
                    colors[g[y, x]] = colors.get(g[y, x], 0) + 1
                main = max(colors, key=lambda k: (colors[k], -k))
                comps.append({
                    "cells": cells,
                    "r0": r0, "r1": r1, "c0": c0, "c1": c1,
                    "h": r1 - r0 + 1,
                    "w": c1 - c0 + 1,
                    "main": main,
                    "cy": (r0 + r1) / 2.0,
                    "cx": (c0 + c1) / 2.0,
                })

    if not comps:
        return []

    # The component containing color 5 is the anchor.
    anchor = None
    for comp in comps:
        if any(g[y, x] == 5 for y, x in comp["cells"]):
            anchor = comp
            break
    if anchor is None:
        anchor = comps[0]

    # Output block size: minimum bounding-box side among all components.
    s = min(min(comp["h"], comp["w"]) for comp in comps)
    out = np.zeros((2 * s, 2 * s), dtype=int)

    # Assign each component to one of the four output quadrants.
    # Anchor is top-left. Others are placed by relative position to anchor,
    # with top-left reserved for the anchor.
    assigned = {id(anchor): (0, 0)}
    for comp in comps:
        if comp is anchor:
            continue
        dy = comp["cy"] - anchor["cy"]
        dx = comp["cx"] - anchor["cx"]
        if dy <= 0:
            row = 0
        else:
            row = 1
        if dx <= 0:
            col = 0
        else:
            col = 1
        if (row, col) == (0, 0):
            # If another component also falls into the anchor quadrant,
            # push it to the nearest free top/bottom slot.
            if row == 0:
                col = 1
            else:
                row = 1
        assigned[id(comp)] = (row, col)

    # Fill each quadrant with the component's main color.
    for comp in comps:
        qr, qc = assigned[id(comp)]
        out[qr * s:(qr + 1) * s, qc * s:(qc + 1) * s] = comp["main"]

    # Preserve non-main pixels from each component, mapped into its quadrant.
    for comp in comps:
        qr, qc = assigned[id(comp)]
        r0, c0 = comp["r0"], comp["c0"]
        ch, cw = comp["h"], comp["w"]
        for y, x in comp["cells"]:
            v = g[y, x]
            if v == comp["main"]:
                continue
            # Map the pixel from the component bbox into the s x s quadrant.
            if ch == 1:
                ny = 0
            else:
                ny = int(round((y - r0) * (s - 1) / (ch - 1)))
            if cw == 1:
                nx = 0
            else:
                nx = int(round((x - c0) * (s - 1) / (cw - 1)))
            out[qr * s + ny, qc * s + nx] = v

    return out.tolist()

