    # Flood-fill all background cells that are not enclosed by non-background cells.
    # Enclosed background cells are then filled with 4.
    visited = np.zeros((h, w), dtype=bool)
    q = deque()

    # Seed from all border background cells.
    for r in range(h):
        for c in (0, w - 1):
            if a[r, c] == bg and not visited[r, c]:
                visited[r, c] = True
                q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if a[r, c] == bg and not visited[r, c]:
                visited[r, c] = True
                q.append((r, c))

    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
                if not visited[nr, nc] and a[nr, nc] == bg:
                    visited[nr, nc] = True
                    q.append((nr, nc))

    # Any background cell not reached from the border is an enclosed hole.
    holes = (a == bg) & (~visited)
    out[holes] = 4

    return out.tolist()

