from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    a = np.array(grid, dtype=int)
    h, w = a.shape
    out = a.copy()

    # Background is the most frequent colour (ties broken by smaller value).
    vals, counts = np.unique(a, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # Connected components of non-background cells (4-connectivity).
    comp = np.full((h, w), -1, dtype=int)
    comp_id = 0
    for r in range(h):
        for c in range(w):
            if a[r, c] != bg and comp[r, c] == -1:
                q = deque([(r, c)])
                comp[r, c] = comp_id
                while q:
                    y, x = q.popleft()
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w:
                            if a[ny, nx] != bg and comp[ny, nx] == -1:
                                comp[ny, nx] = comp_id
                                q.append((ny, nx))
                comp_id += 1

    # A component is "active" if it contains a 4.
    active = np.zeros(comp_id, dtype=bool)
    for r in range(h):
        for c in range(w):
            if a[r, c] == 4:
                active[comp[r, c]] = True

    # Fill every 2x2 background block whose four side-neighbouring cells
    # are all non-background and belong to active components.
    for r in range(h - 1):
        for c in range(w - 1):
            if a[r, c] == bg and a[r + 1, c] == bg and \
               a[r, c + 1] == bg and a[r + 1, c + 1] == bg:

                # Top side
                if r == 0 or a[r - 1, c] == bg or a[r - 1, c + 1] == bg:
                    continue
                # Bottom side
                if r + 2 >= h or a[r + 2, c] == bg or a[r + 2, c + 1] == bg:
                    continue
                # Left side
                if c == 0 or a[r, c - 1] == bg or a[r + 1, c - 1] == bg:
                    continue
                # Right side
                if c + 2 >= w or a[r, c + 2] == bg or a[r + 1, c + 2] == bg:
                    continue

                side_comps = {
                    comp[r - 1, c], comp[r - 1, c + 1],
                    comp[r + 2, c], comp[r + 2, c + 1],
                    comp[r, c - 1], comp[r + 1, c - 1],
                    comp[r, c + 2], comp[r + 1, c + 2],
                }

                if all(active[k] for k in side_comps):
                    out[r, c] = 4
                    out[r, c + 1] = 4
                    out[r + 1, c] = 4
                    out[r + 1, c + 1] = 4

    return out.tolist()

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Find the 2x2 arrangement of 8x8 "frame" blocks.
    frame_tops = []
    for r in range(H - 7):
        for c in range(W - 7):
            block = g[r:r + 8, c:c + 8]
            vals, counts = np.unique(block, return_counts=True)
            if len(vals) == 2:
                bg = vals[np.argmax(counts)]
                fg = vals[np.argmin(counts)]
                if counts.max() >= 56 and counts.min() <= 8:
                    frame_tops.append((r, c, int(fg)))

    if len(frame_tops) < 4:
        return [list(row) for row in g]

    # Keep the top-left 2x2 set of frames.
    min_r = min(r for r, c, _ in frame_tops)
    min_c = min(c for r, c, _ in frame_tops)
    frames = [
        (min_r, min_c),
        (min_r, min_c + 8),
        (min_r + 8, min_c),
        (min_r + 8, min_c + 8),
    ]
    frame_colors = [int(g[r, c]) for r, c in frames]

    # Find 6x6 "pattern" blocks: one foreground color on a background color.
    patterns = []
    for r in range(H - 5):
        for c in range(W - 5):
            block = g[r:r + 6, c:c + 6]
            vals, counts = np.unique(block, return_counts=True)
            if len(vals) == 2:
                bg = vals[np.argmax(counts)]
                fg = vals[np.argmin(counts)]
                if counts.max() >= 20 and counts.min() >= 4:
                    patterns.append((r, c, int(fg), int(bg), block.copy()))

    if len(patterns) < 4:
        return [list(row) for row in g]

    # Pair each frame with a pattern sharing its row or column in the 3x3 macro grid.
    def macro(r, c):
        return (r // 10, c // 10)

    frame_macros = [macro(r, c) for r, c in frames]
    pat_macros = [macro(r, c) for r, c, _, _, _ in patterns]

    used = [False] * len(patterns)
    assignments = [None] * 4

    # Prefer exact row/column matches, then nearest unused compatible pattern.
    for i, (fr, fc) in enumerate(frame_macros):
        candidates = []
        for j, (pr, pc) in enumerate(pat_macros):
            if used[j]:
                continue
            if pr == fr or pc == fc:
                candidates.append(j)
        if candidates:
            # Choose the one with smallest macro distance.
            best = min(candidates, key=lambda j: abs(pat_macros[j][0] - fr) + abs(pat_macros[j][1] - fc))
            assignments[i] = best
            used[best] = True

    # Fallback: assign remaining by nearest unused pattern.
    for i in range(4):
        if assignments[i] is None:
            best = min((j for j in range(len(patterns)) if not used[j]),
                       key=lambda j: abs(pat_macros[j][0] - frame_macros[i][0]) +
                                     abs(pat_macros[j][1] - frame_macros[i][1]))
            assignments[i] = best
            used[best] = True

    # Build 16x16 output.
    out = np.zeros((16, 16), dtype=int)
    for i, (r, c) in enumerate(frames):
        color = frame_colors[i]
        out[r - min_r:r - min_r + 8, c - min_c:c - min_c + 8] = color

        pr, pc, pfg, pbg, pblock = patterns[assignments[i]]
        # Insert pattern at center offset (1,1); replace pattern background by frame color.
        for dr in range(6):
            for dc in range(6):
                val = pblock[dr, dc]
                if val == pbg:
                    val = color
                out[r - min_r + 1 + dr, c - min_c + 1 + dc] = int(val)

    return [list(row) for row in out]

