def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # The non-background colour is the one that is not the most common colour.
    vals, counts = np.unique(g, return_counts=True)
    if len(vals) == 1:
        return [[int(x) for x in row] for row in g]
    bg = int(vals[np.argmax(counts)])
    fg = int(vals[np.argmin(counts)])

    fg_mask = (g == fg)

    # Candidate straight segments: maximal horizontal/vertical runs of fg.
    # A segment is useful if it is long enough or touches a border.
    def useful(r, c, length, horizontal):
        if length >= 3:
            return True
        if horizontal:
            return c == 0 or c + length - 1 == w - 1
        else:
            return r == 0 or r + length - 1 == h - 1

    segments = []
    for r in range(h):
        c = 0
        while c < w:
            if fg_mask[r, c]:
                c2 = c
                while c2 + 1 < w and fg_mask[r, c2 + 1]:
                    c2 += 1
                if useful(r, c, c2 - c + 1, True):
                    segments.append((r, c, r, c2))
                c = c2 + 1
            else:
                c += 1

    for c in range(w):
        r = 0
        while r < h:
            if fg_mask[r, c]:
                r2 = r
                while r2 + 1 < h and fg_mask[r2 + 1, c]:
                    r2 += 1
                if useful(r, c, r2 - r + 1, False):
                    segments.append((r, c, r2, c))
                r = r2 + 1
            else:
                r += 1

    if not segments:
        return [[int(x) for x in row] for row in g]

    # Build a graph of segments.  Two segments are connected if they share a
    # point, or if they are parallel and close enough to be the same intended
    # line with a small gap / jitter.
    n = len(segments)
    adj = [set() for _ in range(n)]

    def segs_connected(a, b):
        r1, c1, r2, c2 = a
        r3, c3, r4, c4 = b

        # Same horizontal line
        if r1 == r3:
            if c1 <= c4 and c3 <= c2:
                return True
            gap = max(0, max(c1, c3) - min(c2, c4) - 1)
            if gap <= 2:
                return True

        # Same vertical line
        if c1 == c3:
            if r1 <= r4 and r3 <= r2:
                return True
            gap = max(0, max(r1, r3) - min(r2, r4) - 1)
            if gap <= 2:
                return True

        # Perpendicular intersection / near intersection
        if r1 <= r4 and r3 <= r2 and c1 <= c4 and c3 <= c2:
            return True

        # Near perpendicular touch (small jitter)
        if r1 <= r4 + 2 and r3 <= r2 + 2 and c1 <= c4 + 2 and c3 <= c2 + 2:
            # Ensure they are not far apart in both directions.
            dr = 0
            if r2 < r3:
                dr = r3 - r2
            elif r4 < r1:
                dr = r1 - r4
            dc = 0
            if c2 < c3:
                dc = c3 - c2
            elif c4 < c1:
                dc = c1 - c4
            if dr <= 2 and dc <= 2:
                return True

        return False

    for i in range(n):
        for j in range(i + 1, n):
            if segs_connected(segments[i], segments[j]):
                adj[i].add(j)
                adj[j].add(i)

    # Connected components of segments.
    comp_id = [-1] * n
    comps = []
    for i in range(n):
        if comp_id[i] != -1:
            continue
        cid = len(comps)
        stack = [i]
        comp_id[i] = cid
        members = []
        while stack:
            x = stack.pop()
            members.append(x)
            for y in adj[x]:
                if comp_id[y] == -1:
                    comp_id[y] = cid
                    stack.append(y)
        comps.append(members)

    # Score each component: prefer components that touch the border and have
    # substantial total length.
    def comp_score(members):
        border = 0
        length = 0
        for idx in members:
            r1, c1, r2, c2 = segments[idx]
            length += max(r2 - r1, c2 - c1) + 1
            if r1 == 0 or r2 == h - 1 or c1 == 0 or c2 == w - 1:
                border += 1
        return (border, length)

    best = max(comps, key=comp_score)

    # Draw only the selected component.
    out = np.full((h, w), bg, dtype=int)
    for idx in best:
        r1, c1, r2, c2 = segments[idx]
        out[r1:r2 + 1, c1:c2 + 1] = fg

    return [[int(x) for x in row] for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Background is the most common colour; foreground is the other colour.
    vals, counts = np.unique(g, return_counts=True)
    if len(vals) == 1:
        return [[int(x) for x in row] for row in g]

    bg = int(vals[np.argmax(counts)])
    fg = int(vals[np.argmin(counts)])
    mask = (g == fg)

    # Maximal horizontal and vertical foreground runs.
    hsegs = []
    for r in range(h):
        c = 0
        while c < w:
            if mask[r, c]:
                c2 = c
                while c2 + 1 < w and mask[r, c2 + 1]:
                    c2 += 1
                hsegs.append((r, c, c2))
                c = c2 + 1
            else:
                c += 1

    vsegs = []
    for c in range(w):
        r = 0
        while r < h:
            if mask[r, c]:
                r2 = r
                while r2 + 1 < h and mask[r2 + 1, c]:
                    r2 += 1
                vsegs.append((c, r, r2))
                r = r2 + 1
            else:
                r += 1

    # A run is a "line" if it is long enough, or if it is part of a column/row
    # that contains several runs (a broken line).
    h_by_row = {}
    for r, c1, c2 in hsegs:
        h_by_row.setdefault(r, []).append((c1, c2))
    v_by_col = {}
    for c, r1, r2 in vsegs:
        v_by_col.setdefault(c, []).append((r1, r2))

    def is_h_line(r, c1, c2):
        length = c2 - c1 + 1
        if length >= 3:
            return True
        return len(h_by_row.get(r, [])) >= 2

    def is_v_line(c, r1, r2):
        length = r2 - r1 + 1
        if length >= 3:
            return True
        return len(v_by_col.get(c, [])) >= 2

    # Candidate line segments.
    lines = []
    for r, c1, c2 in hsegs:
        if is_h_line(r, c1, c2):
            lines.append((r, c1, c2, True))
    for c, r1, r2 in vsegs:
        if is_v_line(c, r1, r2):
            lines.append((c, r1, r2, False))

    if not lines:
        return [[int(x) for x in row] for row in g]

    # Group collinear segments that are close enough to be the same intended line.
    def same_line(a, b):
        r1, c1, c2, hor1 = a
        r2, c2b, c3, hor2 = b
        if hor1 != hor2:
            return False
        if hor1:
            if r1 != r2:
                return False
            gap = max(0, max(c1, c2b) - min(c2, c3) - 1)
            return gap <= 3
        else:
            if c1 != c2b:
                return False
            gap = max(0, max(c2, c3) - min(c2b, c2) - 1)
            return gap <= 3

    n = len(lines)
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx != ry:
            parent[ry] = rx

    for i in range(n):
        for j in range(i + 1, n):
            if same_line(lines[i], lines[j]):
                union(i, j)

    groups = {}
    for i in range(n):
        groups.setdefault(find(i), []).append(i)

    # Score each collinear group.  Prefer groups that touch a border and have
    # substantial total length.
    def group_score(members):
        border = 0
        length = 0
        for idx in members:
            r, c1, c2, hor = lines[idx]
            if hor:
                length += c2 - c1 + 1
                if c1 == 0 or c2 == w - 1:
                    border += 1
            else:
                length += c2 - c1 + 1
                if c1 == 0 or c2 == h - 1:
                    border += 1
        return (border, length)

    best = max(groups.values(), key=group_score)

    # Merge the selected group into one continuous segment.
    out = np.full((h, w), bg, dtype=int)

    for idx in best:
        r, c1, c2, hor = lines[idx]
        if hor:
            out[r, c1:c2 + 1] = fg
        else:
            out[c1:c2 + 1, r] = fg

    # Keep any original foreground pixels that are already on a valid line
    # (this preserves unrelated broken lines that are not noise).
    for r, c1, c2 in hsegs:
        if is_h_line(r, c1, c2):
            out[r, c1:c2 + 1] = fg
    for c, r1, r2 in vsegs:
        if is_v_line(c, r1, r2):
            out[r1:r2 + 1, c] = fg

    return [[int(x) for x in row] for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])

    # Find the special 6 cell (always present in the examples/tests).
    sr, sc = 0, 0
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 6:
                sr, sc = r, c
                break
        else:
            continue
        break

    # Collect all 1 cells.
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]

    # A cell becomes 7 if it is an 8 cell and is adjacent (8-neighbourhood)
    # to at least one 1 cell that is "visible" from the 6 cell.
    # Visibility is defined by an unobstructed 8-neighbour line:
    # every intermediate cell on the line must not be a 1.
    def visible(r1: int, c1: int, r2: int, c2: int) -> bool:
        dr = r2 - r1
        dc = c2 - c1
        steps = max(abs(dr), abs(dc))
        if steps == 0:
            return True
        for i in range(1, steps):
            r = r1 + dr * i // steps
            c = c1 + dc * i // steps
            if grid[r][c] == 1:
                return False
        return True

    visible_ones = set()
    for r, c in ones:
        if visible(sr, sc, r, c):
            visible_ones.add((r, c))

    out = [row[:] for row in grid]

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 8:
                continue

            # Check 8-neighbourhood for a visible 1.
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and (nr, nc) in visible_ones:
                        out[r][c] = 7
                        break
                else:
                    continue
                break

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])

    # Locate the special 6 cell.
    sr = sc = None
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 6:
                sr, sc = r, c
                break
        if sr is not None:
            break

    # All 1 cells.
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]

    # A 1-cell is "visible" from 6 if the straight 8-neighbour line from 6 to it
    # does not pass through any other 1-cell.
    def visible_one(r1: int, c1: int, r2: int, c2: int) -> bool:
        dr = r2 - r1
        dc = c2 - c1
        steps = max(abs(dr), abs(dc))
        if steps == 0:
            return True
        for i in range(1, steps):
            r = r1 + dr * i // steps
            c = c1 + dc * i // steps
            if grid[r][c] == 1:
                return False
        return True

    visible = set()
    for r, c in ones:
        if visible_one(sr, sc, r, c):
            visible.add((r, c))

    # For every visible 1, mark the 8-neighbour line from 6 to that 1.
    # Only original 8-cells become 7.
    out = [row[:] for row in grid]

    for r1, c1 in visible:
        dr = r1 - sr
        dc = c1 - sc
        steps = max(abs(dr), abs(dc))
        for i in range(1, steps):
            r = sr + dr * i // steps
            c = sc + dc * i // steps
            if grid[r][c] == 8:
                out[r][c] = 7

    return out

