import numpy as np
from collections import defaultdict, deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Find the two most frequent colors.
    vals, counts = np.unique(g, return_counts=True)
    order = np.argsort(-counts)
    c1, c2 = int(vals[order[0]]), int(vals[order[1]])

    def components(mask):
        h, w = mask.shape
        seen = np.zeros((h, w), dtype=bool)
        comps = []
        for r in range(h):
            for c in range(w):
                if mask[r, c] and not seen[r, c]:
                    q = deque([(r, c)])
                    seen[r, c] = True
                    cells = []
                    min_r = max_r = r
                    min_c = max_c = c
                    while q:
                        cr, cc = q.popleft()
                        cells.append((cr, cc))
                        min_r = min(min_r, cr)
                        max_r = max(max_r, cr)
                        min_c = min(min_c, cc)
                        max_c = max(max_c, cc)
                        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < h and 0 <= nc < w and mask[nr, nc] and not seen[nr, nc]:
                                seen[nr, nc] = True
                                q.append((nr, nc))
                    comps.append(((min_r, min_c, max_r, max_c), cells))
        return comps

    def try_orientation(src_bg, tgt_bg):
        best = None

        # Horizontal split: top source / bottom target or vice versa.
        for s in range(1, H):
            top = g[:s, :]
            bot = g[s:, :]
            for src_board, tgt_board in ((top, bot), (bot, top)):
                if not np.any(tgt_board == src_bg):
                    continue
                if not np.any(src_board != src_bg):
                    continue

                src_comps = components(src_board != src_bg)
                tgt_comps = components(tgt_board == src_bg)

                src_by_size = defaultdict(list)
                for bbox, cells in src_comps:
                    h = bbox[2] - bbox[0] + 1
                    w = bbox[3] - bbox[1] + 1
                    src_by_size[(h, w)].append((bbox, cells))

