                    tgt_by_size[(h, w)].append((bbox, cells))

                ok = True
                for size, lst in src_by_size.items():
                    if len(tgt_by_size.get(size, [])) < len(lst):
                        ok = False
                        break
                if not ok:
                    continue

                out = tgt_board.copy()
                for size, src_lst in src_by_size.items():
