                    tgt_lst = tgt_by_size.get(size, [])
                    src_lst.sort(key=lambda x: (x[0][0], x[0][1]))
                    tgt_lst.sort(key=lambda x: (x[0][0], x[0][1]))
                    for (s_bbox, s_cells), (t_bbox, t_cells) in zip(src_lst, tgt_lst):
                        sr, sc, _, _ = s_bbox
                        tr, tc, _, _ = t_bbox
                        for (r, c) in s_cells:
                            nr = tr + (r - sr)
                            nc = tc + (c - sc)
                            if 0 <= nr < out.shape[0] and 0 <= nc < out.shape[1]:
                                out[nr, nc] = src_board[r, c]

                if np.any(out == src_bg):
                    continue

                filled = int(np.sum(out != tgt_board))
                if best is None or filled > best[0]:
                    best = (filled, out)

        if best is None:
            return None
        return best[1]

    # Try both assignments of the two dominant colors.
    for src_bg, tgt_bg in ((c1, c2), (c2, c1)):
        res = try_orientation(src_bg, tgt_bg)
        if res is not None:
            return [list(map(int, row)) for row in res]

    # Fallback: return original grid (should not happen for valid ARC inputs).
    return [list(map(int, row)) for row in g]

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Identify the two most frequent colors as the frame/background.
    vals, counts = np.unique(g, return_counts=True)
    order = np.argsort(-counts)
    frame_colors = set(vals[order[:2]].tolist())

    # Interior cells are non-frame cells.
    interior = ~np.isin(g, list(frame_colors))

    # Connected components (8-connected) of interior cells.
    seen = np.zeros((H, W), dtype=bool)
    comps = []
    for r in range(H):
        for c in range(W):
            if interior[r, c] and not seen[r, c]:
                q = deque([(r, c)])
                seen[r, c] = True
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < H and 0 <= nx < W:
                                if interior[ny, nx] and not seen[ny, nx]:
                                    seen[ny, nx] = True
                                    q.append((ny, nx))
                comps.append(cells)

    # Keep only non-trivial objects.
    comps = [cells for cells in comps if len(cells) >= 4]

    # If there are no objects, return unchanged.
    if not comps:
        return [list(row) for row in g]

    # Determine the main axis of the frame:
    # the axis along which the two frame colors appear as long parallel bands.
    def band_score(axis):
        # axis=0: horizontal bands (top/bottom), axis=1: vertical bands (left/right)
        if axis == 0:
            # count rows that are almost entirely one frame color
            score = 0
            for r in range(H):
                row = g[r]
                for fc in frame_colors:
                    if np.sum(row == fc) >= max(1, W * 0.5):
                        score += 1
                        break
            return score
        else:
            score = 0
            for c in range(W):
                col = g[:, c]
                for fc in frame_colors:
                    if np.sum(col == fc) >= max(1, H * 0.5):
                        score += 1
                        break
            return score

    axis = 0 if band_score(0) >= band_score(1) else 1

    # For each component, extract its minimal bounding box pattern.
    def extract(cells):
        ys = [p[0] for p in cells]
        xs = [p[1] for p in cells]
        y0, y1 = min(ys), max(ys)
        x0, x1 = min(xs), max(xs)
        h = y1 - y0 + 1
        w = x1 - x0 + 1
        pat = np.zeros((h, w), dtype=int)
        for y, x in cells:
            pat[y - y0, x - x0] = g[y, x]
        return pat, (y0, x0)

    # Transform a pattern so that its "special" colors face the correct frame sides.
    # We try all 8 dihedral transformations and choose the one that best aligns
    # frame-colored boundary pixels with the corresponding frame side.
    def transforms(pat):
        p = pat
        res = []
        for _ in range(4):
            res.append(p)
            res.append(np.fliplr(p))
            p = np.rot90(p)
        # remove duplicates
        uniq = []
        for t in res:
            if not any(np.array_equal(t, u) for u in uniq):
                uniq.append(t)
        return uniq

    def side_score(t):
        # t is transformed pattern. Score how well frame colors are on matching sides.
        h, w = t.shape
        score = 0
        # top side
        top = t[0, :]
        # bottom side
        bot = t[-1, :]
        # left side
        left = t[:, 0]
        # right side
        right = t[:, -1]

        # Determine which frame color is associated with each side in the original grid.
        # Use the dominant frame color near each outer side.
        top_color = None
        bot_color = None
        left_color = None
        right_color = None

        # top/bottom
        if H > 0:
            top_row = g[0]
            bot_row = g[-1]
            for fc in frame_colors:
                if np.sum(top_row == fc) > np.sum(top_row == [f for f in frame_colors if f != fc][0] if len(frame_colors) > 1 else -1):
                    top_color = fc
            for fc in frame_colors:
                if np.sum(bot_row == fc) > np.sum(bot_row == [f for f in frame_colors if f != fc][0] if len(frame_colors) > 1 else -1):
                    bot_color = fc

        if W > 0:
            left_col = g[:, 0]
            right_col = g[:, -1]
            for fc in frame_colors:
                if np.sum(left_col == fc) > np.sum(left_col == [f for f in frame_colors if f != fc][0] if len(frame_colors) > 1 else -1):
                    left_color = fc
            for fc in frame_colors:
                if np.sum(right_col == fc) > np.sum(right_col == [f for f in frame_colors if f != fc][0] if len(frame_colors) > 1 else -1):
                    right_color = fc

        if top_color is not None:
            score += np.sum(top == top_color)
        if bot_color is not None:
            score += np.sum(bot == bot_color)
        if left_color is not None:
            score += np.sum(left == left_color)
        if right_color is not None:
            score += np.sum(right == right_color)
        return score

    # Choose the best transformation for each component.
    transformed = []
    for cells in comps:
        pat, _ = extract(cells)
        best = None
        best_score = -1
        for t in transforms(pat):
            s = side_score(t)
            if s > best_score:
                best_score = s
                best = t
        transformed.append(best)

    # Sort components by their original vertical center (top to bottom).
    def center_y(cells):
        return sum(p[0] for p in cells) / len(cells)

    indexed = sorted(enumerate(comps), key=lambda kv: center_y(kv[1]))
    ordered_transformed = [transformed[i] for i, _ in indexed]

    # Place transformed objects in the interior, preserving relative horizontal order
    # and stacking them vertically with a small gap.
    out = g.copy()

    # Determine interior bounds (exclude frame bands).
    # Use the first/last rows/cols that are not mostly frame color.
    def is_frame_row(r):
        row = g[r]
        for fc in frame_colors:
            if np.sum(row == fc) >= max(1, W * 0.5):
                return True
        return False

    def is_frame_col(c):
        col = g[:, c]
        for fc in frame_colors:
            if np.sum(col == fc) >= max(1, H * 0.5):
                return True
        return False

    top = 0
    while top < H and is_frame_row(top):
        top += 1
    bottom = H - 1
    while bottom >= 0 and is_frame_row(bottom):
        bottom -= 1
    left = 0
    while left < W and is_frame_col(left):
        left += 1
    right = W - 1
    while right >= 0 and is_frame_col(right):
        right -= 1

    # If interior is too small, just return the grid with objects cleared and reinserted at top-left.
    if bottom - top + 1 < 2 or right - left + 1 < 2:
        return [list(row) for row in out]

    # Clear original object cells.
    for cells in comps:
        for y, x in cells:
            out[y, x] = 0 if 0 not in frame_colors else 1  # use a neutral background if 0 is frame

    # Determine a neutral background color: the most frequent non-frame color in interior.
    interior_vals, interior_counts = np.unique(g[interior], return_counts=True)
    if len(interior_vals) == 0:
        bg = 0
    else:
        bg = int(interior_vals[np.argmax(interior_counts)])

    # Re-clear with actual background.
    for cells in comps:
        for y, x in cells:
            out[y, x] = bg

    # Place objects: keep original horizontal order, stack vertically.
    # Compute original x-centers to preserve left-right order.
    def center_x(cells):
        return sum(p[1] for p in cells) / len(cells)

    ordered_by_x = sorted(ordered_transformed, key=lambda t: 0)  # already top-to-bottom; keep as is

    # Simple layout: place each object one after another vertically, centered horizontally
    # in the interior, with a gap of 1 row.
    y = top
    for t in ordered_by_x:
        h, w = t.shape
        if y + h > bottom + 1:
            y = top
        x = left + max(0, (right - left + 1 - w) // 2)
        # If it would overflow horizontally, clamp.
        if x + w > right + 1:
            x = right - w + 1
        if x < left:
            x = left
        out[y:y+h, x:x+w] = t
        y += h + 1

    return [list(row) for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import Counter, defaultdict

    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Connected components (4-connected) for every non-zero colour.
    labels = np.zeros((H, W), dtype=int)
    comp_id = 0
    comps = []
    for r in range(H):
        for c in range(W):
            if g[r, c] != 0 and labels[r, c] == 0:
                comp_id += 1
                color = int(g[r, c])
                stack = [(r, c)]
                labels[r, c] = comp_id
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < H and 0 <= nx < W:
                            if labels[ny, nx] == 0 and g[ny, nx] == color:
                                labels[ny, nx] = comp_id
                                stack.append((ny, nx))
                ys = [p[0] for p in cells]
                xs = [p[1] for p in cells]
                comps.append({
                    "id": comp_id,
                    "color": color,
                    "cells": cells,
                    "size": len(cells),
                    "r0": min(ys), "r1": max(ys),
                    "c0": min(xs), "c1": max(xs),
                    "h": max(ys) - min(ys) + 1,
                    "w": max(xs) - min(xs) + 1,
                    "cy": (min(ys) + max(ys)) / 2.0,
                    "cx": (min(xs) + max(xs)) / 2.0,
                })

    if not comps:
        return [[0] * W for _ in range(H)]

    # The marker colour is the non-zero colour whose components are all single pixels.
    marker_color = None
    for color in set(int(v) for v in g.flat if v != 0):
        color_comps = [c for c in comps if c["color"] == color]
        if color_comps and all(c["size"] == 1 for c in color_comps):
            marker_color = color
            break

    # Background colour: the most frequent non-marker colour.
    if marker_color is not None:
        counts = Counter(int(v) for v in g.flat if v != 0 and v != marker_color)
    else:
        counts = Counter(int(v) for v in g.flat if v != 0)
    bg_color = counts.most_common(1)[0][0]

    # Keep all components except the marker colour and the background colour.
    objects = [c for c in comps if c["color"] != marker_color and c["color"] != bg_color]

    # For each object, choose the transformation indicated by the nearest marker.
    # Directions: 0=up, 1=right, 2=down, 3=left.
    # up -> rotate 90 clockwise, right -> rotate 90 counter-clockwise,
    # down -> rotate 180, left -> unchanged.
    def crop(comp):
        sub = g[comp["r0"]:comp["r1"] + 1, comp["c0"]:comp["c1"] + 1]
        return (sub == comp["color"]).astype(int)

    def rotate90cw(a):
        return np.rot90(a, k=-1)

    def rotate90ccw(a):
        return np.rot90(a, k=1)

    def rotate180(a):
        return np.rot90(a, k=2)

    marker_cells = [c["cells"][0] for c in comps if c["color"] == marker_color]

    transformed = []
    for comp in objects:
        base = crop(comp)
        if marker_cells:
            best = None
            best_d = None
            for (mr, mc) in marker_cells:
                dr = mr - comp["cy"]
                dc = mc - comp["cx"]
                d = dr * dr + dc * dc
                if best_d is None or d < best_d:
                    best_d = d
                    best = (dr, dc)
            dr, dc = best
            if abs(dr) > abs(dc):
                direction = 0 if dr < 0 else 2
            else:
                direction = 1 if dc > 0 else 3
        else:
            direction = 3

        if direction == 0:
            shape = rotate90cw(base)
        elif direction == 1:
            shape = rotate90ccw(base)
        elif direction == 2:
            shape = rotate180(base)
        else:
            shape = base

        transformed.append((comp["color"], shape))

    # Pack objects in a 2x2 grid of quadrants, preserving input order.
    # Each quadrant has a 2-cell margin.
    if not transformed:
        return [[bg_color] * W for _ in range(H)]

    qh = max(s.shape[0] for _, s in transformed) + 4
    qw = max(s.shape[1] for _, s in transformed) + 4
    out_h = 2 * qh
    out_w = 2 * qw
    out = np.full((out_h, out_w), bg_color, dtype=int)

    for idx, (color, shape) in enumerate(transformed):
        q = idx % 4
        qr, qc = divmod(q, 2)
        r0 = qr * qh + 2
        c0 = qc * qw + 2
        h, w = shape.shape
        out[r0:r0 + h, c0:c0 + w] = np.where(shape == 1, color, bg_color)

    return out.tolist()

