def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Background is the most common colour.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # Non-background colours that are not the moving marker colour 2.
    shape_mask = (g != bg) & (g != 2)
    shape_colours = set(int(c) for c in np.unique(g) if c != bg and c != 2)

    # Connected components of shape cells (4-neighbourhood).
    comp_id = -np.ones((H, W), dtype=int)
    comps = []
    for r in range(H):
        for c in range(W):
            if shape_mask[r, c] and comp_id[r, c] == -1:
                cid = len(comps)
                stack = [(r, c)]
                comp_id[r, c] = cid
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < H and 0 <= nx < W:
                            if shape_mask[ny, nx] and comp_id[ny, nx] == -1:
                                comp_id[ny, nx] = cid
                                stack.append((ny, nx))
                comps.append(cells)

    # For each shape component, find straight "tunnels" that are open on one
    # side and blocked on the other by the same component.
    tunnels = []  # (r, c, dr, dc, comp_id)

    def add_tunnel(r, c, dr, dc, cid):
        # Check that the cell is background and the next cell is in the component.
        if not (0 <= r < H and 0 <= c < W):
            return
        if g[r, c] != bg:
            return
        nr, nc = r + dr, c + dc
        if not (0 <= nr < H and 0 <= nc < W):
            return
        if comp_id[nr, nc] != cid:
            return
        # Walk backwards from (r, c) while background.
        y, x = r, c
        while 0 <= y < H and 0 <= x < W and g[y, x] == bg:
            y -= dr
            x -= dc
        # The backward walk must stop at a shape cell of the same component.
        if 0 <= y < H and 0 <= x < W and comp_id[y, x] == cid:
            tunnels.append((r, c, dr, dc, cid))

    for cid, cells in enumerate(comps):
        for r, c in cells:
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                add_tunnel(r, c, dr, dc, cid)

    # Connected components of 2s (8-neighbourhood, so rectangular blocks move together).
    marker_id = -np.ones((H, W), dtype=int)
    markers = []
    for r in range(H):
        for c in range(W):
            if g[r, c] == 2 and marker_id[r, c] == -1:
                mid = len(markers)
                stack = [(r, c)]
                marker_id[r, c] = mid
                cells = []
                while stack:
