    out[g == 2] = bg

    # Move each marker if every cell can slide along the same tunnel direction
    # until it is adjacent to the blocking shape cell.
    for cells in markers:
        best = None
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
