        if len(cells) < 2:
            return False
        rs = {r for r, _ in cells}
        cs = {c for _, c in cells}
        if len(rs) == 1:
            return len(cs) == len(cells)
        if len(cs) == 1:
            return len(rs) == len(cells)
        return False

    def is_dot(cells):
        return len(cells) == 1

    def neighbors8(p):
        r, c = p
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < H and 0 <= nc < W:
                    yield (nr, nc)

    def connected8(cells):
        if not cells:
            return True
        seen = {cells[0]}
        q = deque([cells[0]])
        s = set(cells)
        while q:
            cur = q.popleft()
            for nb in neighbors8(cur):
                if nb in s and nb not in seen:
                    seen.add(nb)
                    q.append(nb)
        return len(seen) == len(cells)

    def touches(a, b):
        sa, sb = set(a), set(b)
        for p in sa:
            for nb in neighbors8(p):
                if nb in sb:
                    return True
        return False

    # Identify the moving colour:
    # - it must be a connected 8-neighbour component
    # - it must touch at least one of the other two colours
    # - the other two colours should be "anchors" (line or dot)
    moving = None
    anchors = None
    for m in colors:
        mc = cells_of(m)
        if not connected8(mc):
            continue
        others = [c for c in colors if c != m]
        if len(others) != 2:
            continue
        a1, a2 = others
        c1, c2 = cells_of(a1), cells_of(a2)
        if not (is_line(c1) or is_dot(c1)):
            continue
        if not (is_line(c2) or is_dot(c2)):
            continue
        if touches(mc, c1) or touches(mc, c2):
            moving = m
            anchors = (a1, a2)
            break

    if moving is None:
        return out.tolist()

    mc = cells_of(moving)
    a1, a2 = anchors
    c1, c2 = cells_of(a1), cells_of(a2)

