    if len(endpoints) < 2:
        # fallback: use extreme cells
        endpoints = [min(mset), max(mset)]

    fixed_end = None
    for p in endpoints:
        if touches([p], c1) or touches([p], c2):
            fixed_end = p
            break
    if fixed_end is None:
        fixed_end = endpoints[0]

    # Determine which anchor is the "target" (the one not touched by fixed_end,
    # or if both are touched, choose the one farther from fixed_end).
    def dist_to_anchor(p, cells):
        return min(abs(p[0] - r) + abs(p[1] - c) for r, c in cells)

