    if not touches([fixed_end], c1):
        target = c1
    elif not touches([fixed_end], c2):
        target = c2
    else:
        target = c1 if dist_to_anchor(fixed_end, c1) >= dist_to_anchor(fixed_end, c2) else c2

    # Build a simple 8-direction path from fixed_end to a cell adjacent to target.
    # Prefer paths that are straight/diagonal and do not overlap anchors.
    blocked = set(c1) | set(c2)

