    target_adj = []
    for p in target:
        for nb in neighbors8(p):
            if nb not in blocked and nb != fixed_end:
                target_adj.append(nb)
    # also allow target cells themselves if not blocked? no, cannot overlap anchors
    target_adj = list(dict.fromkeys(target_adj))

    def path_cost(path):
        # prefer shorter, then fewer direction changes, then lexicographic
        if not path:
            return (10**9, 10**9, path)
        turns = 0
        last = None
        for i in range(1, len(path)):
            d = (path[i][0] - path[i-1][0], path[i][1] - path[i-1][1])
            if last is not None and d != last:
                turns += 1
            last = d
        return (len(path), turns, path)

    best_path = None
    # BFS over 8-neighbour grid, avoiding anchors and moving cells except start
    start = fixed_end
    goal_set = set(target_adj)
    q = deque([(start, [start])])
    seen = {start}
    while q:
        cur, path = q.popleft()
        if cur in goal_set:
            cost = path_cost(path)
            if best_path is None or cost < best_path[0]:
                best_path = (cost, path)
            continue
        for nb in neighbors8(cur):
            if nb in blocked:
                continue
            if nb in seen:
                continue
            # do not reuse moving cells except start, to keep a simple path
            if nb in mset and nb != start:
                continue
            seen.add(nb)
            q.append((nb, path + [nb]))

    if best_path is None:
        # fallback: straight line to nearest target-adjacent cell
        if target_adj:
            goal = min(target_adj, key=lambda p: abs(p[0]-start[0]) + abs(p[1]-start[1]))
            path = [start]
            r, c = start
            gr, gc = goal
            while (r, c) != (gr, gc):
                dr = 0 if r == gr else (1 if gr > r else -1)
                dc = 0 if c == gc else (1 if gc > c else -1)
                r += dr
                c += dc
                path.append((r, c))
            best_path = (path_cost(path), path)
        else:
            best_path = (path_cost([start]), [start])

    new_path = best_path[1]

    # Clear old moving colour
    for r, c in mc:
        out[r, c] = bg

    # Place new path
    for r, c in new_path:
        out[r, c] = moving

    return out.tolist()

