    for r in range(h):
        for c in range(w):
            if g[r, c] == 6:
                start = (r, c)
                break
        if start is not None:
            break

    if start is None:
        return [[int(x) for x in row] for row in g]

    # Flood-fill the 8-region reachable from the 6 using 4-connectivity.
    flood = np.zeros((h, w), dtype=bool)
    stack = [start]
    flood[start[0], start[1]] = True

    while stack:
        r, c = stack.pop()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and not flood[nr, nc] and g[nr, nc] == 8:
                flood[nr, nc] = True
                stack.append((nr, nc))

    # Non-flood cells that are connected to the grid border using 8-connectivity
    # are considered "external".  This distinguishes outside obstacles from
    # internal holes.
    external = np.zeros((h, w), dtype=bool)
    stack = []

    for r in range(h):
        for c in range(w):
            if not flood[r, c] and (r == 0 or r == h - 1 or c == 0 or c == w - 1):
                external[r, c] = True
                stack.append((r, c))

    while stack:
        r, c = stack.pop()
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and not flood[nr, nc] and not external[nr, nc]:
                    external[nr, nc] = True
                    stack.append((nr, nc))

    # Keep 1-cells that touch the flooded region (8-neighbourhood).
    keep_ones = np.zeros((h, w), dtype=bool)
    for r in range(h):
        for c in range(w):
            if g[r, c] != 1:
                continue
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and flood[nr, nc]:
                        keep_ones[r, c] = True
                        break
                if keep_ones[r, c]:
                    break

    # Build output:
    # - flooded 8-cells become 7 if they are on the grid border or 8-adjacent
    #   to an external non-flood cell;
    # - kept 1-cells remain 1;
    # - the 6 remains 6;
    # - everything else becomes 8.
    out = np.full((h, w), 8, dtype=int)

    for r in range(h):
        for c in range(w):
            if not flood[r, c] or g[r, c] != 8:
                continue

            is_border = (r == 0 or r == h - 1 or c == 0 or c == w - 1)
            if is_border:
                out[r, c] = 7
                continue

            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and external[nr, nc]:
                        out[r, c] = 7
                        break
                if out[r, c] == 7:
                    break

    out[keep_ones] = 1
    out[start] = 6

    return out.tolist()

