            if g[r, c] != bg and comp_id[r, c] == -1:
                color = int(g[r, c])
                q = deque([(r, c)])
                comp_id[r, c] = len(comps)
                cells = [(r, c)]
                while q:
                    y, x = q.popleft()
                    for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny, nx = y+dy, x+dx
                        if 0 <= ny < h and 0 <= nx < w:
                            if comp_id[ny, nx] == -1 and g[ny, nx] == color:
                                comp_id[ny, nx] = len(comps)
                                q.append((ny, nx))
                                cells.append((ny, nx))
                rs = [p[0] for p in cells]
                cs = [p[1] for p in cells]
                comps.append({
                    'color': color,
                    'cells': cells,
                    'r0': min(rs), 'r1': max(rs),
                    'c0': min(cs), 'c1': max(cs),
                    'area': len(cells)
                })

    def bbox_area(a, b):
        return (max(a['r1'], b['r1']) - min(a['r0'], b['r0']) + 1) * \
               (max(a['c1'], b['c1']) - min(a['c0'], b['c0']) + 1)

    def fill_rect(r0, r1, c0, c1, color):
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if out[r, c] == bg:
                    out[r, c] = color

    # For each colour, if there are at least two components, fill the
    # bounding box of the pair with the largest area.
    by_color = {}
    for comp in comps:
        by_color.setdefault(comp['color'], []).append(comp)

    for color, lst in by_color.items():
        if len(lst) < 2:
