        best = None
        best_area = -1
        for i in range(len(lst)):
            for j in range(i + 1, len(lst)):
                a, b = lst[i], lst[j]
                ar = bbox_area(a, b)
                if ar > best_area:
                    best_area = ar
                    best = (a, b)
        if best is None:
            continue
        a, b = best
        r0 = min(a['r0'], b['r0'])
        r1 = max(a['r1'], b['r1'])
        c0 = min(a['c0'], b['c0'])
        c1 = max(a['c1'], b['c1'])
