def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])

    # Find the special marker 5.
    sr = sc = None
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 5:
                sr, sc = r, c
                break
        if sr is not None:
            break

    # Determine the side length of the reference square anchored at 5.
    # It is the largest square containing 5 whose non-zero cells are all 5 or 7.
    max_s = 1
    for s in range(1, min(h, w) + 1):
        ok = True
        for dr in range(-s + 1, 1):
            for dc in range(-s + 1, 1):
                r = sr + dr
                c = sc + dc
                if 0 <= r < h and 0 <= c < w:
                    v = grid[r][c]
                    if v != 0 and v not in (5, 7):
                        ok = False
                        break
                else:
                    ok = False
                    break
            if not ok:
                break
        if ok:
            max_s = s
        else:
            break
    s = max_s

    # Choose the SxS reference square containing 5.
    # Prefer the square where 5 is at the top-left; otherwise use the square
    # that extends upward/rightward from 5 as in the examples.
    best = None
    for dr in range(-s + 1, 1):
        for dc in range(-s + 1, 1):
            r0 = sr + dr
            c0 = sc + dc
            if 0 <= r0 and 0 <= c0 and r0 + s <= h and c0 + s <= w:
                ok = True
                for r in range(r0, r0 + s):
                    for c in range(c0, c0 + s):
                        v = grid[r][c]
                        if v != 0 and v not in (5, 7):
                            ok = False
                            break
                    if not ok:
                        break
                if ok:
                    # score: 5 at top-left is best, then smaller offset
                    score = (0 if (dr == 0 and dc == 0) else 1, abs(dr) + abs(dc))
                    if best is None or score < best[0]:
                        best = (score, r0, c0)
    r0, c0 = best[1], best[2]

    # Extract and orient the reference square so that 5 is at its top-left.
    ref = [[grid[r0 + i][c0 + j] for j in range(s)] for i in range(s)]
    if ref[0][0] != 5:
        # Rotate 90 degrees clockwise until 5 is at top-left.
        for _ in range(3):
            ref = [list(row) for row in zip(*ref[::-1])]
            if ref[0][0] == 5:
                break

    # Find all SxS squares of a single non-zero color (other than 5/7 reference).
    squares = []
    for r in range(h - s + 1):
        for c in range(w - s + 1):
            colors = set()
            for i in range(s):
                for j in range(s):
                    v = grid[r + i][c + j]
                    if v != 0:
                        colors.add(v)
            if len(colors) == 1:
                col = colors.pop()
                if col == 5:
                    continue
                # Ignore the reference 7 square itself.
                if col == 7 and r == r0 and c == c0:
                    continue
                squares.append((r, c, col))

    # Keep the square with the most cells of that color (the intended object core).
    def score_sq(item):
        r, c, col = item
        cnt = 0
        for i in range(s):
            for j in range(s):
                if grid[r + i][c + j] == col:
                    cnt += 1
        return cnt

    # For each color, keep the best square.
    best_by_color = {}
    for item in squares:
        col = item[2]
        sc = score_sq(item)
        if col not in best_by_color or sc > best_by_color[col][0]:
            best_by_color[col] = (sc, item)

    others = [item for _, item in best_by_color.values()]

    # Assign the three other colors to TR, BL, BR.
    # Use their positions relative to the reference square, with a stable
    # fallback to row-major order if necessary.
    ref_r, ref_c = r0, c0

    def rel(item):
        r, c, col = item
        return (r - ref_r, c - ref_c, col)

    # In the examples, the intended assignment is:
    # - the object closest to the top-right relative direction -> TR
    # - the object closest to the bottom-left relative direction -> BL
    # - the remaining object -> BR
    # We implement this by scoring each object for each quadrant.
    def quadrant_score(item, quadrant):
        r, c, col = item
        dr = r - ref_r
        dc = c - ref_c
        if quadrant == "TR":
            # prefer above/right, but in ex2 all are above; use rightness then row
            return (0 if dc > 0 else 1, 0 if dr < 0 else 1, -dc, dr)
        if quadrant == "BL":
            return (0 if dc < 0 else 1, 0 if dr > 0 else 1, dc, -dr)
        if quadrant == "BR":
            return (0 if dc > 0 else 1, 0 if dr > 0 else 1, -dc, -dr)
        return (0, 0, 0, 0)

    tr = min(others, key=lambda x: quadrant_score(x, "TR"))
    remaining = [x for x in others if x is not tr]
    bl = min(remaining, key=lambda x: quadrant_score(x, "BL"))
    br = [x for x in remaining if x is not bl][0]

    # Build output canvas of size 2S x 2S.
    out = [[0] * (2 * s) for _ in range(2 * s)]

    def place_square(square, top_left, color):
        r, c, col = square
        for i in range(s):
            for j in range(s):
                v = grid[r + i][c + j]
                if v == 0:
                    v = col
                out[top_left[0] + i][top_left[1] + j] = v

    # Place reference first.
    for i in range(s):
        for j in range(s):
            v = ref[i][j]
            if v == 0:
                v = 7
            out[i][j] = v

    # Place others.  The examples show that later placements can overwrite
    # earlier ones in overlapping cells.  Use the order: BR, BL, TR.
    place_square(br, (s, s), br[2])
    place_square(bl, (s, 0), bl[2])
    place_square(tr, (0, s), tr[2])

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])

    # Locate the marker 5.
    sr = sc = None
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 5:
                sr, sc = r, c
                break
        if sr is not None:
            break

    # Determine S: the size of the square core around the marker object.
    # It is the largest square containing the marker whose non-zero cells
    # are only 5 or 7.
    S = 1
    for s in range(1, min(h, w) + 1):
        ok = True
        for dr in range(-s + 1, 1):
            for dc in range(-s + 1, 1):
                r = sr + dr
                c = sc + dc
                if 0 <= r < h and 0 <= c < w:
                    v = grid[r][c]
                    if v != 0 and v not in (5, 7):
                        ok = False
                        break
                else:
                    ok = False
                    break
            if not ok:
                break
        if ok:
            S = s
        else:
            break

    # Find the SxS core for the marker object: the SxS window containing 5
    # with the maximum number of non-zero cells (5/7).
    best = None
    for r0 in range(max(0, sr - S + 1), min(h - S + 1, sr + 1)):
        for c0 in range(max(0, sc - S + 1), min(w - S + 1, sc + 1)):
            cnt = 0
            for r in range(r0, r0 + S):
                for c in range(c0, c0 + S):
                    if grid[r][c] != 0:
                        cnt += 1
            key = (-cnt, r0, c0)
            if best is None or key < best[0]:
                best = (key, r0, c0)
    mr0, mc0 = best[1], best[2]

    # Rotate the marker object so that 5 is at the top-left of its core.
    def rotate90(cells):
        # cells: list of (r, c)
        return [(c, S - 1 - r) for r, c in cells]

    marker_cells = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] in (5, 7):
                marker_cells.append((r - mr0, c - mc0))

    while True:
        # Find position of 5 in current relative coordinates.
        pos5 = None
        for r, c in marker_cells:
            if mr0 + r == sr and mc0 + c == sc:
                pos5 = (r, c)
                break
        if pos5 == (0, 0):
            break
        marker_cells = rotate90(marker_cells)

    # Collect all other colors.
    colors = set()
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v not in (0, 5, 7):
                colors.add(v)

    objects = []
    for col in colors:
        cells = []
        for r in range(h):
            for c in range(w):
                if grid[r][c] == col:
                    cells.append((r, c))
        if not cells:
            continue

        # Choose the SxS core with the maximum number of this color.
        best_core = None
        for r0 in range(h - S + 1):
            for c0 in range(w - S + 1):
                cnt = 0
                for r, c in cells:
                    if r0 <= r < r0 + S and c0 <= c < c0 + S:
                        cnt += 1
                if cnt == 0:
                    continue
                key = (-cnt, r0, c0)
                if best_core is None or key < best_core[0]:
                    best_core = (key, r0, c0)

        r0, c0 = best_core[1], best_core[2]
        rel_cells = [(r - r0, c - c0) for r, c in cells]
        objects.append((col, r0, c0, rel_cells))

    # Assign the three non-marker objects to TR, BL, BR.
    # Use their core positions relative to the marker core.
    def rel_pos(obj):
        col, r0, c0, _ = obj
        return (r0 - mr0, c0 - mc0)

    # In the examples, the intended assignment is:
    # - TR: object most to the right / above-right
    # - BL: object most to the left / below-left
    # - BR: remaining object
    # This stable heuristic matches both provided examples.
    def tr_score(obj):
        dr, dc = rel_pos(obj)
        return (0 if dc > 0 else 1, 0 if dr < 0 else 1, -dc, dr)

    def bl_score(obj):
        dr, dc = rel_pos(obj)
        return (0 if dc < 0 else 1, 0 if dr > 0 else 1, dc, -dr)

    tr_obj = min(objects, key=tr_score)
    remaining = [o for o in objects if o is not tr_obj]
    bl_obj = min(remaining, key=bl_score)
    br_obj = [o for o in remaining if o is not bl_obj][0]

    # Build output canvas.
    out = [[0] * (2 * S) for _ in range(2 * S)]

    def paint_core(col, top_left, is_marker=False):
        r0, c0 = top_left
        for i in range(S):
            for j in range(S):
                if is_marker:
                    # Core is solid 7, with 5 at top-left.
                    out[r0 + i][c0 + j] = 7
                else:
                    out[r0 + i][c0 + j] = col
        if is_marker:
            out[r0][c0] = 5

    # Paint in an order that reproduces the examples:
    # marker first, then BR, BL, TR.  Later objects overwrite earlier ones.
    paint_core(7, (0, 0), True)
    paint_core(br_obj[0], (S, S))
    paint_core(bl_obj[0], (S, 0))
    paint_core(tr_obj[0], (0, S))

    # Paint marker protrusions (cells outside its core) after the core.
    for r, c in marker_cells:
        rr = r
        cc = c
        if 0 <= rr < 2 * S and 0 <= cc < 2 * S:
            out[rr][cc] = 7
    out[0][0] = 5

    # Paint other object protrusions.  Use the same order as cores.
    for obj in (br_obj, bl_obj, tr_obj):
        col, _, _, rel_cells = obj
        # Determine its quadrant top-left.
        if obj is br_obj:
            top = (S, S)
        elif obj is bl_obj:
            top = (S, 0)
        else:
            top = (0, S)
        tr0, tc0 = top
        for r, c in rel_cells:
            rr = tr0 + r
            cc = tc0 + c
            if 0 <= rr < 2 * S and 0 <= cc < 2 * S:
                out[rr][cc] = col

    return out

