        bw = cmax - cmin + 1

        best = None
        for fr in frames:
            fr_min, fr_max, fc_min, fc_max, direction = fr
            if direction == 'down':
                # Frame opens downward; block must be below it and horizontally inside.
                if rmin <= fr_max:
                    continue
                if cmin < fc_min + 1 or cmax > fc_max - 1:
                    continue
                # Stop just below the first non-background cell above the block.
                stop = rmin - 1
                for r in range(rmin - 1, fr_min - 1, -1):
                    if any(g[r, c] != bg for c in range(cmin, cmax + 1)):
                        stop = r + 1
                        break
                if stop < rmin:
                    continue
                dist = rmin - stop
                if best is None or dist < best[0]:
                    best = (dist, stop, direction)
            else:  # direction == 'up'
                # Frame opens upward; block must be above it and horizontally inside.
                if rmax >= fr_min:
                    continue
                if cmin < fc_min + 1 or cmax > fc_max - 1:
                    continue
                # Stop just above the first non-background cell below the block.
                stop = rmax + 1
                for r in range(rmax + 1, fr_max + 1):
                    if any(g[r, c] != bg for c in range(cmin, cmax + 1)):
                        stop = r - 1
                        break
                if stop > rmax:
                    continue
                dist = stop - rmax
                if best is None or dist < best[0]:
                    best = (dist, stop, direction)

        if best is None:
            # No compatible frame: erase the 2-block.
            for r, c in cells:
                out[r, c] = bg
            continue

        dist, stop, direction = best
        if direction == 'down':
            new_rmin = stop - bh + 1
            new_rmax = stop
        else:
            new_rmin = stop
            new_rmax = stop + bh - 1

        # Erase original 2-block.
        for r, c in cells:
            out[r, c] = bg

        # Draw 0 trail from original block to just before the new block.
        if direction == 'down':
            for r in range(rmin, new_rmin):
                for c in range(cmin, cmax + 1):
                    out[r, c] = 0
        else:
            for r in range(new_rmax + 1, rmax + 1):
                for c in range(cmin, cmax + 1):
                    out[r, c] = 0

        # Place moved 2-block.
        for r in range(new_rmin, new_rmax + 1):
            for c in range(cmin, cmax + 1):
                out[r, c] = 2

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    H, W = g.shape
    out = g.copy()

    # Background is the most frequent colour.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # Connected components of 2s.
    visited = np.zeros((H, W), dtype=bool)
    twos = []
    for r in range(H):
        for c in range(W):
            if g[r, c] == 2 and not visited[r, c]:
                stack = [(r, c)]
                visited[r, c] = True
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < H and 0 <= nx < W:
                            if not visited[ny, nx] and g[ny, nx] == 2:
                                visited[ny, nx] = True
                                stack.append((ny, nx))
                twos.append(cells)

    # For each 2-component, try to move it vertically toward a solid
    # non-background, non-2 horizontal segment that covers its columns.
    # It stops immediately before that segment and leaves a 0 trail.
    # If no such segment exists, erase the component.
    for cells in twos:
        rs = [r for r, _ in cells]
        cs = [c for _, c in cells]
        rmin, rmax = min(rs), max(rs)
        cmin, cmax = min(cs), max(cs)
        h = rmax - rmin + 1
        w = cmax - cmin + 1

        def clear_vertical(r0, r1, direction):
            # Check that all cells between current block and target are background.
            if direction == 'up':
                for r in range(r1 + 1, rmin):
                    if any(g[r, c] != bg for c in range(cmin, cmax + 1)):
                        return False
            else:
                for r in range(rmax + 1, r0):
                    if any(g[r, c] != bg for c in range(cmin, cmax + 1)):
                        return False
            return True

        def target_row_up():
            # Nearest row above rmin where every column cmin..cmax is solid.
            for r in range(rmin - 1, -1, -1):
                if all(g[r, c] != bg and g[r, c] != 2 for c in range(cmin, cmax + 1)):
                    return r
            return None

        def target_row_down():
            # Nearest row below rmax where every column cmin..cmax is solid.
            for r in range(rmax + 1, H):
                if all(g[r, c] != bg and g[r, c] != 2 for c in range(cmin, cmax + 1)):
                    return r
            return None

        best = None

        tr = target_row_up()
        if tr is not None and clear_vertical(tr, rmin, 'up'):
            new_rmin = tr + 1
            new_rmax = tr + h
            if new_rmax < H:
                dist = rmin - new_rmin
                if best is None or dist < best[0]:
                    best = (dist, new_rmin, new_rmax, 'up')

        tr = target_row_down()
        if tr is not None and clear_vertical(tr, rmax, 'down'):
            new_rmax = tr - 1
            new_rmin = tr - h
            if new_rmin >= 0:
                dist = new_rmax - rmax
                if best is None or dist < best[0]:
                    best = (dist, new_rmin, new_rmax, 'down')

        # Erase original 2s.
        for r, c in cells:
            out[r, c] = bg

        if best is None:
            continue

        _, new_rmin, new_rmax, direction = best

        # Leave a 0 trail from the original block to the new block.
        if direction == 'up':
            for r in range(new_rmax + 1, rmax + 1):
                for c in range(cmin, cmax + 1):
                    out[r, c] = 0
        else:
            for r in range(rmin, new_rmin):
                for c in range(cmin, cmax + 1):
                    out[r, c] = 0

        # Place moved 2-block.
        for r in range(new_rmin, new_rmax + 1):
            for c in range(cmin, cmax + 1):
                out[r, c] = 2

    return out.tolist()

import numpy as np
from collections import deque

def _components(mask):
    h, w = mask.shape
    seen = np.zeros((h, w), dtype=bool)
    comps = []
    for i in range(h):
        for j in range(w):
            if mask[i, j] and not seen[i, j]:
                q = deque([(i, j)])
                seen[i, j] = True
                cells = []
                while q:
                    r, c = q.popleft()
                    cells.append((r, c))
                    for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        nr, nc = r+dr, c+dc
                        if 0 <= nr < h and 0 <= nc < w and mask[nr, nc] and not seen[nr, nc]:
                            seen[nr, nc] = True
                            q.append((nr, nc))
                comps.append(cells)
    return comps

def _block_pattern(cells):
    if not cells:
        return None
    rmin = min(r for r, c in cells)
    rmax = max(r for r, c in cells)
    cmin = min(c for r, c in cells)
    cmax = max(c for r, c in cells)
    h = rmax - rmin + 1
    w = cmax - cmin + 1
    if h % 2 or w % 2:
        return None
    bh, bw = h // 2, w // 2
    pat = np.zeros((bh, bw), dtype=int)
    for r, c in cells:
        br = (r - rmin) // 2
        bc = (c - cmin) // 2
        # A valid object block must be a full 2x2 block.
        if (mask := np.all([
            (r - rmin) % 2 == 0 or True,
            (c - cmin) % 2 == 0 or True
        ])):
            pass
        # Check full 2x2:
        ok = True
        for dr in (0, 1):
            for dc in (0, 1):
                if (r - rmin + dr, c - cmin + dc) not in cells:
                    ok = False
                    break
            if not ok:
                break
        if ok:
            pat[br, bc] = 1
    if pat.sum() == 0:
        return None
    return pat

def _anti_diag(pat):
    # transpose then rotate 180
    return np.rot90(pat.T, 2)

def _place_pattern(canvas, pat, top_left):
    r0, c0 = top_left
    ph, pw = pat.shape
    for i in range(ph):
        for j in range(pw):
            if pat[i, j]:
                canvas[r0 + i, c0 + j] = 1

def _find_matching_placement(hole_pat, obj_pat):
    # hole_pat and obj_pat are binary arrays; obj_pat is already transformed.
    # Return top-left (r,c) where obj_pat fits exactly into a subset of hole_pat,
    # and the number of filled holes equals obj_pat.sum().
    hh, hw = hole_pat.shape
    oh, ow = obj_pat.shape
    if oh > hh or ow > hw:
        return None
    best = None
    for r in range(hh - oh + 1):
        for c in range(hw - ow + 1):
            sub = hole_pat[r:r+oh, c:c+ow]
            if np.array_equal(sub, obj_pat):
                return (r, c)
    return None

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Remove obvious single-pixel noise: keep only colors that have at least one
    # connected component of size >= 4 and even bounding box.
    color_cells = {}
    for color in range(1, 10):
        mask = (g == color)
        if not mask.any():
            continue
        comps = _components(mask)
        good = []
        for cells in comps:
            if len(cells) < 4:
                continue
            rmin = min(r for r, c in cells)
            rmax = max(r for r, c in cells)
            cmin = min(c for r, c in cells)
            cmax = max(c for r, c in cells)
            if (rmax - rmin + 1) % 2 == 0 and (cmax - cmin + 1) % 2 == 0:
                good.append(cells)
        if good:
            color_cells[color] = good

    if not color_cells:
        return [[0 for _ in range(W)] for _ in range(H)]

    # Candidate template: a color with a component whose holes can be partitioned
    # into components matching transformed block patterns of other colors.
    # In practice, choose the largest even component that contains holes.
    candidates = []
    for color, comps in color_cells.items():
        for cells in comps:
            rmin = min(r for r, c in cells)
            rmax = max(r for r, c in cells)
            cmin = min(c for r, c in cells)
            cmax = max(c for r, c in cells)
            h = rmax - rmin + 1
            w = cmax - cmin + 1
            if h % 2 or w % 2:
                continue
            # Build component mask
            comp_mask = np.zeros((h, w), dtype=bool)
            for r, c in cells:
                comp_mask[r - rmin, c - cmin] = True
            hole_mask = ~comp_mask
            if not hole_mask.any():
                continue
            # Template must be at least 2x2 blocks
            if h < 2 or w < 2:
                continue
            candidates.append((len(cells), color, rmin, cmin, h, w, comp_mask, hole_mask))

    if not candidates:
        # Fallback: return original grid
        return [[int(x) for x in row] for row in g]

    # Sort by area descending
    candidates.sort(key=lambda x: x[0], reverse=True)

    # Precompute transformed block patterns for all non-template components.
    def object_patterns(exclude_color):
        pats = []
        for color, comps in color_cells.items():
            if color == exclude_color:
                continue
            for cells in comps:
                pat = _block_pattern(cells)
                if pat is None:
                    continue
                tpat = _anti_diag(pat)
                pats.append((color, tpat, cells))
        return pats

    for area, tcolor, r0, c0, th, tw, comp_mask, hole_mask in candidates:
        # Scale template by 2
        out = np.full((th * 2, tw * 2), tcolor, dtype=int)

        # Hole block pattern: each 2x2 block in output corresponds to one cell in template.
        hole_block = np.zeros((th // 2, tw // 2), dtype=int)
        for i in range(th // 2):
            for j in range(tw // 2):
                # If any pixel in this 2x2 template cell is a hole, mark block hole.
                if hole_mask[2*i:2*i+2, 2*j:2*j+2].any():
                    hole_block[i, j] = 1

        # Find connected components of hole blocks
        hole_comps = _components(hole_block.astype(bool))
        if not hole_comps:
            continue

        # For each hole component, try to match an object pattern.
        used_objects = set()
        placements = []
        ok = True
        for hcells in hole_comps:
            hrmin = min(r for r, c in hcells)
            hrmax = max(r for r, c in hcells)
            hcmin = min(c for r, c in hcells)
            hcmax = max(c for r, c in hcells)
            hpat = np.zeros((hrmax - hrmin + 1, hcmax - hcmin + 1), dtype=int)
            for r, c in hcells:
                hpat[r - hrmin, c - hcmin] = 1

            matched = False
            for idx, (color, tpat, cells) in enumerate(object_patterns(tcolor)):
                if idx in used_objects:
                    continue
                # Try to place tpat exactly into hpat
                ph, pw = tpat.shape
                hh, hw = hpat.shape
                if ph > hh or pw > hw:
                    continue
                for r in range(hh - ph + 1):
                    for c in range(hw - pw + 1):
                        if np.array_equal(hpat[r:r+ph, c:c+pw], tpat):
                            # Place in output at block coordinates (hrmin+r, hcmin+c)
                            out_r = (hrmin + r) * 2
                            out_c = (hcmin + c) * 2
                            for i in range(ph):
                                for j in range(pw):
                                    if tpat[i, j]:
                                        out[out_r + 2*i:out_r + 2*i + 2,
                                            out_c + 2*j:out_c + 2*j + 2] = color
                            used_objects.add(idx)
                            matched = True
                            break
                    if matched:
                        break
                if matched:
                    break
            if not matched:
                ok = False
                break

        if ok:
            # Ensure all hole blocks are filled (no leftover holes)
            filled = np.zeros_like(hole_block, dtype=bool)
            for hcells in hole_comps:
                hrmin = min(r for r, c in hcells)
                hrmax = max(r for r, c in hcells)
                hcmin = min(c for r, c in hcells)
                hcmax = max(c for r, c in hcells)
                hpat = np.zeros((hrmax - hrmin + 1, hcmax - hcmin + 1), dtype=int)
                for r, c in hcells:
                    hpat[r - hrmin, c - hcmin] = 1
                # We don't track exact fill here; rely on matching exact components.
            return [[int(x) for x in row] for row in out]

    # Fallback: if no perfect match, return original grid
    return [[int(x) for x in row] for row in g]

import numpy as np
from collections import deque

def _components(mask):
    """Return list of connected components (4-neighbor) as lists of (r,c)."""
    h, w = mask.shape
    seen = np.zeros((h, w), dtype=bool)
    comps = []
    for r in range(h):
        for c in range(w):
            if mask[r, c] and not seen[r, c]:
                q = deque([(r, c)])
                seen[r, c] = True
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny, nx = y+dy, x+dx
                        if 0 <= ny < h and 0 <= nx < w and mask[ny, nx] and not seen[ny, nx]:
                            seen[ny, nx] = True
                            q.append((ny, nx))
                comps.append(cells)
    return comps

def _bbox(cells):
    rs = [r for r, c in cells]
    cs = [c for r, c in cells]
    return min(rs), max(rs), min(cs), max(cs)

def _mask_from_cells(cells, r0, c0, h, w):
    m = np.zeros((h, w), dtype=bool)
    for r, c in cells:
        m[r-r0, c-c0] = True
    return m

def _anti_diag(mask):
    """Reflect across anti-diagonal: new[i,j] = old[H-1-j, W-1-i]."""
    H, W = mask.shape
    out = np.zeros((W, H), dtype=bool)
    for i in range(H):
        for j in range(W):
            if mask[i, j]:
                out[W-1-j, H-1-i] = True
    return out

def _scale2(mask):
    H, W = mask.shape
    out = np.zeros((2*H, 2*W), dtype=bool)
    for i in range(H):
        for j in range(W):
            if mask[i, j]:
                out[2*i:2*i+2, 2*j:2*j+2] = True
    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Collect all non-zero connected components.
    comps_by_color = {}
    for color in range(1, 10):
        mask = (g == color)
        if not mask.any():
            continue
        comps = _components(mask)
        if comps:
            comps_by_color[color] = comps

    if not comps_by_color:
        return [[0]*W for _ in range(H)]

    # Candidate container: a component with at least one enclosed hole.
    # Holes are zero components inside its bounding box that do not touch the bbox border.
    candidates = []
    for color, comps in comps_by_color.items():
        for cells in comps:
            r0, r1, c0, c1 = _bbox(cells)
            h = r1 - r0 + 1
            w = c1 - c0 + 1
            if h < 2 or w < 2:
                continue
            comp_mask = _mask_from_cells(cells, r0, c0, h, w)
            # zero mask inside bbox
            zero_mask = ~comp_mask
            # remove zeros touching bbox border
            border_zero = np.zeros_like(zero_mask)
            border_zero[0, :] = True
            border_zero[-1, :] = True
            border_zero[:, 0] = True
            border_zero[:, -1] = True
            # flood from border zeros
            seen = np.zeros_like(zero_mask)
            q = deque()
            for r in range(h):
                for c in range(w):
                    if zero_mask[r, c] and border_zero[r, c]:
                        seen[r, c] = True
                        q.append((r, c))
            while q:
                y, x = q.popleft()
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and zero_mask[ny, nx] and not seen[ny, nx]:
                        seen[ny, nx] = True
                        q.append((ny, nx))
            hole_mask = zero_mask & ~seen
            if not hole_mask.any():
                continue
            hole_comps = _components(hole_mask)
            if not hole_comps:
                continue
            candidates.append((color, cells, r0, c0, h, w, comp_mask, hole_comps))

    if not candidates:
        return [[int(x) for x in row] for row in g]

    # For each candidate container, try to match every scaled hole with a distinct
    # anti-diagonal-reflected component of another color.
    all_other_comps = []
    for color, comps in comps_by_color.items():
        for cells in comps:
            all_other_comps.append((color, cells))

    best = None
    for color, cells, r0, c0, h, w, comp_mask, hole_comps in candidates:
        # Precompute transformed masks for all other components.
        transformed = []
        for ocolor, ocells in all_other_comps:
            if ocolor == color:
                continue
            or0, or1, oc0, oc1 = _bbox(ocells)
            oh = or1 - or0 + 1
            ow = oc1 - oc0 + 1
            omask = _mask_from_cells(ocells, or0, oc0, oh, ow)
            tmask = _anti_diag(omask)
            transformed.append((ocolor, ocells, tmask))

        used = set()
        placements = []
        ok = True

        for hcells in hole_comps:
            hr0, hr1, hc0, hc1 = _bbox(hcells)
            hh = hr1 - hr0 + 1
            hw = hc1 - hc0 + 1
            hmask = _mask_from_cells(hcells, hr0, hc0, hh, hw)
            target = _scale2(hmask)
            th, tw = target.shape

            found = False
            for idx, (ocolor, ocells, tmask) in enumerate(transformed):
                if idx in used:
                    continue
                if tmask.shape != target.shape:
                    continue
                if not np.array_equal(tmask, target):
                    continue
                # Place this piece into the output at the scaled hole location.
                # Output coordinates: container bbox scaled by 2.
                out_r = (hr0) * 2
                out_c = (hc0) * 2
                placements.append((ocolor, out_r, out_c, tmask))
                used.add(idx)
                found = True
                break
            if not found:
                ok = False
                break

        if ok:
            # Prefer the container with the largest output area / most holes.
            score = (h * w, len(hole_comps), -color)
            if best is None or score > best[0]:
                best = (score, color, h, w, placements)

    if best is None:
        # Fallback: return original grid (should not happen for valid puzzles).
        return [[int(x) for x in row] for row in g]

    _, color, h, w, placements = best
    out = np.full((2*h, 2*w), color, dtype=int)

    for ocolor, out_r, out_c, tmask in placements:
        th, tw = tmask.shape
        for i in range(th):
            for j in range(tw):
                if tmask[i, j]:
                    out[out_r + i, out_c + j] = ocolor

    return [[int(x) for x in row] for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Identify background as the most frequent colour.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # Non-background colours.
    nonbg = [int(v) for v in vals if v != bg]

    # The two terminal colours are the two most frequent non-background colours.
    # The path colour is the remaining one.
    freq = {c: int(np.sum(g == c)) for c in nonbg}
    sorted_colors = sorted(freq, key=lambda c: (-freq[c], c))
    if len(sorted_colors) == 3:
        t1, t2, path = sorted_colors
    else:
        # Fallback: choose the two colours with the largest bounding boxes as terminals.
        def bbox_area(c):
            ys, xs = np.where(g == c)
            if len(ys) == 0:
                return 0
            return (ys.max() - ys.min() + 1) * (xs.max() - xs.min() + 1)
        by_area = sorted(nonbg, key=lambda c: (-bbox_area(c), -freq[c], c))
        t1, t2 = by_area[0], by_area[1]
        path = [c for c in nonbg if c not in (t1, t2)][0]

    # Collect terminal cells.
    term1 = list(zip(*np.where(g == t1)))
    term2 = list(zip(*np.where(g == t2)))

    # Collect path cells and find the path component attached to a terminal.
    path_cells = set(zip(*np.where(g == path)))

    def neighbors8(r, c):
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < H and 0 <= nc < W:
                    yield nr, nc

    # Find the connected component of path cells (8-connected) that touches a terminal.
    start = None
    for cell in path_cells:
        r, c = cell
        for nr, nc in neighbors8(r, c):
            if (nr, nc) in term1 or (nr, nc) in term2:
                start = cell
                break
        if start is not None:
            break

    if start is None:
        # If no direct adjacency, take the whole path set.
        comp = path_cells
    else:
        seen = {start}
        q = deque([start])
        while q:
            r, c = q.popleft()
            for nr, nc in neighbors8(r, c):
                if (nr, nc) in path_cells and (nr, nc) not in seen:
                    seen.add((nr, nc))
                    q.append((nr, nc))
        comp = seen

    # Determine which terminal the path is attached to in the input.
    def touches(cell_set, term):
        for r, c in cell_set:
            for nr, nc in neighbors8(r, c):
                if (nr, nc) in term:
                    return True
        return False

    attached_to_1 = touches(comp, term1)
    attached_to_2 = touches(comp, term2)

    # The path will be re-routed between the two terminals.
    # Build a shortest 8-connected path between the two terminal sets,
    # then extend it from the far terminal in the direction suggested by the
    # original path's far endpoint, preserving as many original path cells as possible.
    term1_set = set(term1)
    term2_set = set(term2)

    # BFS from all cells of term1 to all cells of term2 over non-terminal, non-background cells.
    # We allow path cells and background; terminals are obstacles except as endpoints.
    blocked = set()
    for r, c in term1_set:
        blocked.add((r, c))
    for r, c in term2_set:
        blocked.add((r, c))

    # Multi-source BFS from term1 cells.
    parent = {}
    q = deque()
    for r, c in term1_set:
        parent[(r, c)] = None
        q.append((r, c))

    target = None
    while q:
        r, c = q.popleft()
        for nr, nc in neighbors8(r, c):
            if (nr, nc) in parent:
                continue
            if (nr, nc) in blocked and (nr, nc) not in term2_set:
                continue
            parent[(nr, nc)] = (r, c)
            if (nr, nc) in term2_set:
                target = (nr, nc)
                q.clear()
                break
            q.append((nr, nc))

    # Reconstruct path from term1 to term2 (excluding terminals).
    core = []
    if target is not None:
        cur = target
        while cur is not None and parent.get(cur) is not None:
            prev = parent[cur]
            if prev is not None:
                core.append(prev)
            cur = prev
        core.reverse()
    else:
        # Fallback: straight 8-neighbor interpolation between closest terminal cells.
        best = None
        for a in term1:
            for b in term2:
                d = abs(a[0] - b[0]) + abs(a[1] - b[1])
                if best is None or d < best[0]:
                    best = (d, a, b)
        _, a, b = best
        dr = b[0] - a[0]
        dc = b[1] - a[1]
        steps = max(abs(dr), abs(dc))
        for i in range(1, steps):
            r = a[0] + round(dr * i / steps)
            c = a[1] + round(dc * i / steps)
            core.append((r, c))

    # Determine the original path's far endpoint (the path cell farthest from the attached terminal).
    def far_endpoint(comp, term):
        term_set = set(term)
        best = None
        for cell in comp:
            d = min(abs(cell[0] - tr) + abs(cell[1] - tc) for tr, tc in term_set)
            if best is None or d > best[0]:
                best = (d, cell)
        return best[1] if best else None

    if attached_to_1 and not attached_to_2:
        anchor_term = term1
        other_term = term2
        far = far_endpoint(comp, term1)
    elif attached_to_2 and not attached_to_1:
        anchor_term = term2
        other_term = term1
        far = far_endpoint(comp, term2)
    else:
        # Default: anchor to the terminal closer to the path's centroid.
        pts = list(comp)
        cr = sum(r for r, c in pts) / len(pts)
        cc = sum(c for r, c in pts) / len(pts)
        d1 = min(abs(cr - r) + abs(cc - c) for r, c in term1)
        d2 = min(abs(cr - r) + abs(cc - c) for r, c in term2)
        if d1 <= d2:
            anchor_term, other_term = term1, term2
            far = far_endpoint(comp, term1)
        else:
            anchor_term, other_term = term2, term1
            far = far_endpoint(comp, term2)

    # Extend the core path beyond the other terminal in the direction from the
    # other terminal toward the original far endpoint, up to the original path length.
    original_len = len(comp)
    core_len = len(core)
    extra_needed = max(0, original_len - core_len)

    # Choose the terminal cell in other_term closest to the last core cell.
    if core:
        last = core[-1]
    else:
        last = None

    if last is not None and other_term:
        best_other = min(other_term, key=lambda p: abs(p[0] - last[0]) + abs(p[1] - last[1]))
    else:
        best_other = other_term[0] if other_term else (0, 0)

    # Direction to extend: from best_other toward the original far endpoint.
    if far is not None:
        dr = far[0] - best_other[0]
        dc = far[1] - best_other[1]
        # Normalize to 8-neighbor step.
        sdr = (dr > 0) - (dr < 0)
        sdc = (dc > 0) - (dc < 0)
    else:
        sdr, sdc = -1, 0

    # Add extension cells, avoiding terminals and already used cells.
    used = set(core)
    used.update(term1_set)
    used.update(term2_set)
    cur = best_other
    for _ in range(extra_needed):
        nr, nc = cur[0] + sdr, cur[1] + sdc
        if not (0 <= nr < H and 0 <= nc < W) or (nr, nc) in used:
            # Try small detours.
            found = False
            for ddr in (0, 1, -1):
                for ddc in (0, 1, -1):
                    if ddr == 0 and ddc == 0:
                        continue
                    nr2, nc2 = cur[0] + sdr + ddr, cur[1] + sdc + ddc
                    if 0 <= nr2 < H and 0 <= nc2 < W and (nr2, nc2) not in used:
                        nr, nc = nr2, nc2
                        found = True
                        break
                if found:
                    break
            if not found:
                break
        core.append((nr, nc))
        used.add((nr, nc))
        cur = (nr, nc)

    # Build output.
    out = g.copy()
    # Remove original path cells.
    for r, c in comp:
        out[r, c] = bg

    # Place new path cells.
    for r, c in core:
        if 0 <= r < H and 0 <= c < W and out[r, c] == bg:
            out[r, c] = path

    return out.tolist()

import numpy as np
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Background is the most frequent color.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # Non-background colors.
    colors = [int(c) for c in vals if c != bg]

    # Identify the two terminal colors:
    # they are the colors whose cells form straight vertical/horizontal lines.
    def is_line(cells):
        if len(cells) < 2:
            return False
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        return (len(set(rs)) == 1) or (len(set(cs)) == 1)

    line_colors = []
    for col in colors:
        cells = [(r, c) for r in range(H) for c in range(W) if g[r, c] == col]
        if is_line(cells):
            line_colors.append(col)

    # If there are exactly two line colors, use them.
    # Otherwise fall back to the two most common non-background colors.
    if len(line_colors) >= 2:
        # Prefer the two longest line colors.
        line_colors.sort(key=lambda col: -sum(1 for r in range(H) for c in range(W) if g[r, c] == col))
        terminals = line_colors[:2]
    else:
        freq = {}
        for col in colors:
            freq[col] = int((g == col).sum())
        terminals = [c for c, _ in sorted(freq.items(), key=lambda x: -x[1])[:2]]

    # The wire color is the remaining non-background color.
    wire = None
    for col in colors:
        if col not in terminals:
            wire = col
            break
    if wire is None:
        return g.tolist()

    # Collect cells.
    def cells_of(col):
        return [(r, c) for r in range(H) for c in range(W) if g[r, c] == col]

    wire_cells = cells_of(wire)
    term1_cells = cells_of(terminals[0])
    term2_cells = cells_of(terminals[1])

    # If the wire is not connected to either terminal, do nothing.
    def neighbors8(r, c):
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < H and 0 <= nc < W:
                    yield nr, nc

    def touches(cells, term):
        tset = set(term)
        for r, c in cells:
            for nr, nc in neighbors8(r, c):
                if (nr, nc) in tset:
                    return True
        return False

    if not (touches(wire_cells, term1_cells) or touches(wire_cells, term2_cells)):
        return g.tolist()

    # Determine which terminal the wire is attached to.
    attached_to_1 = touches(wire_cells, term1_cells)
    attached_to_2 = touches(wire_cells, term2_cells)

    if attached_to_1 and not attached_to_2:
        anchor_term = term1_cells
        other_term = term2_cells
    elif attached_to_2 and not attached_to_1:
        anchor_term = term2_cells
        other_term = term1_cells
    else:
        # Default: attach to the closer terminal to the wire centroid.
        cr = sum(r for r, c in wire_cells) / len(wire_cells)
        cc = sum(c for r, c in wire_cells) / len(wire_cells)
        d1 = min(abs(cr - r) + abs(cc - c) for r, c in term1_cells)
        d2 = min(abs(cr - r) + abs(cc - c) for r, c in term2_cells)
        if d1 <= d2:
            anchor_term, other_term = term1_cells, term2_cells
        else:
            anchor_term, other_term = term2_cells, term1_cells

    # Find the anchor cell: the wire cell adjacent to the anchor terminal.
    anchor = None
    aset = set(anchor_term)
    for r, c in wire_cells:
        for nr, nc in neighbors8(r, c):
            if (nr, nc) in aset:
                anchor = (r, c)
                break
        if anchor:
            break

    if anchor is None:
        return g.tolist()

    # Estimate the wire length.
    # If the wire component is a simple path, use its cell count.
    # If it has cycles/branches, use the longest simple path length from the anchor.
    wire_set = set(wire_cells)

    # Build adjacency within the wire component.
    adj = {cell: [] for cell in wire_set}
    for r, c in wire_set:
        for nr, nc in neighbors8(r, c):
            if (nr, nc) in wire_set:
                adj[(r, c)].append((nr, nc))

    # Longest simple path from anchor in this small graph (DFS with memo is not trivial,
    # but components are tiny in ARC; use DFS with visited).
    def longest_path(start):
        best = 0
        def dfs(u, visited, length):
            nonlocal best
            best = max(best, length)
            for v in adj[u]:
                if v not in visited:
                    visited.add(v)
                    dfs(v, visited, length + 1)
                    visited.remove(v)
        dfs(start, {start}, 1)
        return best

    L = longest_path(anchor)

    # We need to draw a new wire of length L starting at anchor,
    # touching the other terminal, and ending as far as possible in the
    # direction from anchor toward the other terminal.
    #
    # Strategy:
    # 1. Find all cells at Chebyshev distance L-1 from anchor that are reachable
    #    by a shortest 8-neighbor path of exactly L-1 steps.
    # 2. Among those, choose one for which there exists a shortest path from anchor
    #    to it that touches the other terminal.
    # 3. Prefer endpoints that are farthest in the direction toward the other terminal,
    #    then closest to the other terminal, then lexicographically.

    other_set = set(other_term)

    def cheb(a, b):
        return max(abs(a[0] - b[0]), abs(a[1] - b[1]))

    # BFS from anchor to get shortest distances and parents.
    dist = {anchor: 0}
    parent = {anchor: None}
    q = deque([anchor])
    while q:
        u = q.popleft()
        for v in neighbors8(*u):
            if v in dist:
                continue
            dist[v] = dist[u] + 1
            parent[v] = u
            q.append(v)

    # Candidate endpoints at distance L-1.
    target_dist = L - 1
    candidates = [cell for cell, d in dist.items() if d == target_dist]

    # For each candidate, check if there is a shortest path from anchor to it
    # that touches the other terminal.
    # We do a DP over shortest-path DAG: can_touch[u] = True if there is a shortest
    # path from anchor to u that touches other terminal.
    can_touch = {anchor: False}
    # Process nodes in increasing distance.
    nodes_by_dist = sorted(dist.keys(), key=lambda x: dist[x])
    for u in nodes_by_dist:
        # If u itself is adjacent to other terminal, then any shortest path to u touches.
        if any((nr, nc) in other_set for nr, nc in neighbors8(*u)):
            can_touch[u] = True
            continue
        # Otherwise, can_touch[u] is True if any predecessor p on a shortest path
        # has can_touch[p] True.
        for p in neighbors8(*u):
            if p in dist and dist[p] == dist[u] - 1 and can_touch.get(p, False):
                can_touch[u] = True
                break

    valid = [cell for cell in candidates if can_touch.get(cell, False)]

    if not valid:
        # Fallback: choose the closest reachable cell to the other terminal.
        valid = candidates if candidates else [anchor]

    # Choose endpoint.
    # Direction from anchor toward the other terminal: use the closest other terminal cell.
    closest_other = min(other_term, key=lambda p: cheb(anchor, p))
    dir_r = (closest_other[0] > anchor[0]) - (closest_other[0] < anchor[0])
    dir_c = (closest_other[1] > anchor[1]) - (closest_other[1] < anchor[1])

    def score(cell):
        # Prefer larger projection in the direction toward the other terminal.
        proj = (cell[0] - anchor[0]) * dir_r + (cell[1] - anchor[1]) * dir_c
        # Prefer closer to the other terminal.
        d_other = min(cheb(cell, p) for p in other_term)
        # Prefer lexicographically smaller for determinism.
        return (-proj, d_other, cell[0], cell[1])

    endpoint = min(valid, key=score)

    # Reconstruct a shortest path from anchor to endpoint.
    path = []
    cur = endpoint
    while cur is not None:
        path.append(cur)
        cur = parent[cur]
    path.reverse()

    # If the reconstructed path is shorter than L (should not happen), pad it
    # by continuing in the direction from anchor to endpoint.
    if len(path) < L:
        last = path[-1]
        dr = (endpoint[0] > anchor[0]) - (endpoint[0] < anchor[0])
        dc = (endpoint[1] > anchor[1]) - (endpoint[1] < anchor[1])
        used = set(path)
        while len(path) < L:
            nr, nc = last[0] + dr, last[1] + dc
            if 0 <= nr < H and 0 <= nc < W and (nr, nc) not in used:
                path.append((nr, nc))
                used.add((nr, nc))
                last = (nr, nc)
            else:
                # Try small detours.
                found = False
                for ddr in (0, 1, -1):
                    for ddc in (0, 1, -1):
                        if ddr == 0 and ddc == 0:
                            continue
                        nr2, nc2 = last[0] + dr + ddr, last[1] + dc + ddc
                        if 0 <= nr2 < H and 0 <= nc2 < W and (nr2, nc2) not in used:
                            path.append((nr2, nc2))
                            used.add((nr2, nc2))
                            last = (nr2, nc2)
                            found = True
                            break
                    if found:
                        break
                if not found:
                    break

    # Build output.
    out = g.copy()
    # Remove original wire cells.
    for r, c in wire_cells:
        out[r, c] = bg

    # Place new wire cells.
    for r, c in path:
        if 0 <= r < H and 0 <= c < W and out[r, c] == bg:
            out[r, c] = wire

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    n = len(grid)
    out = [row[:] for row in grid]

    # The hidden complete pattern is symmetric under the 32x32 reflection
    # (r, c) <-> (31-r, 31-c).  The visible 30x30 grid is a crop of that
    # pattern, so only cells whose reflected partner is also inside the
    # 30x30 grid can be recovered.
    for r in range(n):
        rr = 31 - r
        if rr < 0 or rr >= n:
            continue
        for c in range(n):
            cc = 31 - c
            if cc < 0 or cc >= n:
                continue
            if out[r][c] == 0 and out[rr][cc] != 0:
                out[r][c] = out[rr][cc]

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    n = len(grid)
    out = [row[:] for row in grid]

    # The visible 30x30 grid is a crop of a larger pattern that is symmetric
    # under 180-degree rotation.  The crop is offset by one cell from the
    # full pattern, so the in-crop partner of (r, c) is (31-r, 31-c).
    # Fill every missing 0 from its rotated partner when that partner is
    # visible and non-zero.
    for r in range(n):
        rr = 31 - r
        if rr < 0 or rr >= n:
            continue
        for c in range(n):
            cc = 31 - c
            if cc < 0 or cc >= n:
                continue
            if out[r][c] == 0 and out[rr][cc] != 0:
                out[r][c] = out[rr][cc]

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Background is the border colour (also the dominant colour in these tasks).
    bg = g[0, 0]

    out = np.full((h, w), bg, dtype=int)

    # Find 4-connected components of non-background colours.
    visited = np.zeros((h, w), dtype=bool)

    for r in range(h):
        for c in range(w):
            if visited[r, c] or g[r, c] == bg:
                continue

            color = g[r, c]
            stack = [(r, c)]
            visited[r, c] = True
            cells = []

            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w:
                        if not visited[ny, nx] and g[ny, nx] == color:
                            visited[ny, nx] = True
                            stack.append((ny, nx))

            min_r = min(y for y, _ in cells)
            max_r = max(y for y, _ in cells)

            # Odd colours go to the top, even colours go to the bottom.
            if color % 2 == 1:
                shift = -min_r
            else:
                shift = (h - 1) - max_r

            for y, x in cells:
                out[y + shift, x] = color

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    a = np.array(grid, dtype=int)
    h, w = a.shape
    out = a.copy()

    # The meaningful symmetric region is the bottom-right 28x28 subgrid.
    # It is symmetric about its own center:
    #   out[2+i, 2+j] == out[2+(27-i), 2+j]
    #   out[2+i, 2+j] == out[2+i, 2+(27-j)]
    # Fill zeros in this region using the mirrored non-zero values.
    for i in range(28):
        for j in range(28):
            r, c = 2 + i, 2 + j
            if out[r, c] != 0:
                continue

            candidates = []
            for rr, cc in (
                (2 + (27 - i), 2 + j),
                (2 + i, 2 + (27 - j)),
                (2 + (27 - i), 2 + (27 - j)),
            ):
                if out[rr, cc] != 0:
                    candidates.append(out[rr, cc])

            if candidates:
                # All valid mirrors should agree; take the first non-zero.
                out[r, c] = candidates[0]

    # The top two rows and left two columns are not part of the 28x28 core,
    # but in the examples they are completed by the same row/column symmetry
    # of the core. Fill any remaining zeros using the nearest mirrored value
    # in the same row or column when available.
    for r in range(h):
        for c in range(w):
            if out[r, c] != 0:
                continue

            # Try horizontal mirror within the row, using the core axis c=15.5
            # for columns 2..29. For c < 2, mirror to c = 31 - c if valid.
            mc = 31 - c
            if 0 <= mc < w and out[r, mc] != 0:
                out[r, c] = out[r, mc]
                continue

            # Try vertical mirror within the column, using the core axis r=15.5
            # for rows 2..29. For r < 2, mirror to r = 31 - r if valid.
            mr = 31 - r
            if 0 <= mr < h and out[mr, c] != 0:
                out[r, c] = out[mr, c]
                continue

            # Fallback: copy from the same row/column in the core if possible.
            if 2 <= c < w:
                mc = 31 - c
                if 0 <= mc < w and out[r, mc] != 0:
                    out[r, c] = out[r, mc]
                    continue
            if 2 <= r < h:
                mr = 31 - r
                if 0 <= mr < h and out[mr, c] != 0:
                    out[r, c] = out[mr, c]
                    continue

    return out.tolist()

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape
    out = g.copy()

    # Determine the background colour as the most frequent colour.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # Find all 3-cell L-trominoes.  For each L, store its corner cell.
    # An L is three cells of the same non-background colour occupying a 2x2
    # block with one cell missing; the corner is the cell adjacent to both arms.
    corners = []
    for r in range(H - 1):
        for c in range(W - 1):
            block = g[r:r + 2, c:c + 2]
            for color in range(1, 10):
                if color == bg:
                    continue
                mask = (block == color)
                if mask.sum() != 3:
                    continue
                # The missing cell is the one that is not part of the L.
                # The corner is the cell diagonally opposite the missing cell.
                missing = np.argwhere(~mask)
                if len(missing) != 1:
                    continue
                mr, mc = missing[0]
                cr, cc = 1 - mr, 1 - mc
                corners.append((r + cr, c + cc, color))

    # Group L-corners by colour.  We expect pairs of same-coloured Ls.
    by_color = {}
    for r, c, color in corners:
        by_color.setdefault(color, []).append((r, c))

    # Candidate rectangle pairs: two L-corners of the same colour.
    pairs = []
    for color, pts in by_color.items():
        if len(pts) >= 2:
            # Use the first two corners found; in the puzzles this is the intended pair.
            (r1, c1), (r2, c2) = pts[0], pts[1]
            rmin, rmax = min(r1, r2), max(r1, r2)
            cmin, cmax = min(c1, c2), max(c1, c2)
            pairs.append((rmin, rmax, cmin, cmax, color))

    # Sort rectangles by area (largest first) so outer rectangles are filled first.
    pairs.sort(key=lambda p: (p[1] - p[0] + 1) * (p[3] - p[2] + 1), reverse=True)

    # Choose fill colours: non-background colours that are not L-pair colours.
    # In the examples these are the singleton/marker colours.  If there are
    # two, the first is used for the outer rectangle and the second for the inner.
    l_colors = set(by_color.keys())
    fill_colors = []
    for color in range(1, 10):
        if color == bg or color in l_colors:
            continue
        if np.any(g == color):
            fill_colors.append(color)

    # If no explicit fill colour is available, fall back to 0.
    if not fill_colors:
        fill_colors = [0]

    # Fill each rectangle with the corresponding fill colour, but never overwrite
    # original non-background cells.  Later (smaller) rectangles overwrite earlier
    # fill cells, producing the nested effect.
    for idx, (rmin, rmax, cmin, cmax, color) in enumerate(pairs):
        if idx >= len(fill_colors):
            break
        fill = fill_colors[idx]
        for r in range(rmin, rmax + 1):
            for c in range(cmin, cmax + 1):
                if g[r, c] == bg:
                    out[r, c] = fill

    return out.tolist()

import numpy as np
from collections import defaultdict

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape
    out = g.copy()

    # Background is the most frequent colour.
