    corners_by_color = defaultdict(list)
    for r in range(H - 1):
        for c in range(W - 1):
            block = g[r:r + 2, c:c + 2]
            for color in range(1, 10):
                if color == bg:
                    continue
                mask = (block == color)
                if mask.sum() != 3:
                    continue
                missing = np.argwhere(~mask)
                if len(missing) != 1:
                    continue
                mr, mc = missing[0]
                cr, cc = 1 - mr, 1 - mc
                corners_by_color[color].append((r + cr, c + cc))

    # Build a legend from horizontal adjacent pairs:
    #   left colour -> right colour
    # Only non-background right colours are used as fill colours.
    legend = {}
    for r in range(H):
        for c in range(W - 1):
            left = int(g[r, c])
            right = int(g[r, c + 1])
            if left != bg and right != bg and left != right:
                # If there are multiple entries, keep the first one.
                legend.setdefault(left, right)

    # For each colour that has exactly two L-corners and a legend entry,
    # fill the rectangle between the two corners with the legend colour.
    # Original non-background cells are never overwritten.
    #
    # Fill larger rectangles first, then smaller ones, so that smaller
    # rectangles can overwrite larger ones in overlapping areas.
    jobs = []
    for color, pts in corners_by_color.items():
        if len(pts) != 2 or color not in legend:
            continue
        fill = legend[color]
        if fill == bg:
            continue
        (r1, c1), (r2, c2) = pts
        rmin, rmax = min(r1, r2), max(r1, r2)
        cmin, cmax = min(c1, c2), max(c1, c2)
        area = (rmax - rmin + 1) * (cmax - cmin + 1)
        jobs.append((area, rmin, rmax, cmin, cmax, fill))

    jobs.sort(reverse=True)

    for _, rmin, rmax, cmin, cmax, fill in jobs:
        for r in range(rmin, rmax + 1):
            for c in range(cmin, cmax + 1):
                if g[r, c] == bg:
                    out[r, c] = fill

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0]) if h else 0
    out = [row[:] for row in grid]

    # Open the left border (6 -> 7) where a 7-row lies between two rows
    # that have the same non-border color in the same column.
    for r in range(1, h - 1):
        if out[r][0] != 6:
            continue
        for c in range(1, w):
            a = grid[r - 1][c]
            b = grid[r + 1][c]
            if a == b and a not in (6, 7) and grid[r][c] == 7:
                out[r][0] = 7
                break

    # Close 7 cells (7 -> 6) that are the rightmost 7 in their row and
    # are vertically adjacent to a non-border color.
    for r in range(h):
        c = w - 1
        while c >= 0 and grid[r][c] != 7:
            c -= 1
        if c < 0:
            continue
        if r > 0 and grid[r - 1][c] not in (6, 7):
            out[r][c] = 6
        elif r < h - 1 and grid[r + 1][c] not in (6, 7):
            out[r][c] = 6

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    H, W = g.shape
    out = np.full((H, W), 8, dtype=int)

    # Find the 4 marker and the direction of the initial beam.
    fours = np.argwhere(g == 4)
    if len(fours) == 0:
        return out.tolist()

    r4, c4 = int(fours[0][0]), int(fours[0][1])

    # The 2s are on one side of the 4; the beam goes away from them.
    dr, dc = 0, 0
    if r4 + 1 < H and g[r4 + 1, c4] == 2:
        dr, dc = -1, 0
    elif r4 - 1 >= 0 and g[r4 - 1, c4] == 2:
        dr, dc = 1, 0
    elif c4 + 1 < W and g[r4, c4 + 1] == 2:
        dr, dc = 0, -1
    elif c4 - 1 >= 0 and g[r4, c4 - 1] == 2:
        dr, dc = 0, 1
    else:
        # Fallback: upward, as in all provided cases.
        dr, dc = -1, 0

    # Connected components of non-background cells (1 or 3).
    comp_id = -np.ones((H, W), dtype=int)
    comps = []
    for r in range(H):
        for c in range(W):
            if g[r, c] in (1, 3) and comp_id[r, c] == -1:
                cid = len(comps)
                q = deque([(r, c)])
                comp_id[r, c] = cid
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < H and 0 <= nx < W:
                            if g[ny, nx] in (1, 3) and comp_id[ny, nx] == -1:
                                comp_id[ny, nx] = cid
                                q.append((ny, nx))
                comps.append(cells)

    # For each component, determine the outward direction of each 3 cell.
    comp_dirs = []
    for cells in comps:
        cell_set = set(cells)
        dirs = []
        for (r, c) in cells:
            if g[r, c] != 3:
                continue
            d = None
            if (r + 1, c) in cell_set and (r - 1, c) not in cell_set:
                d = (-1, 0)  # top side -> up
            elif (r - 1, c) in cell_set and (r + 1, c) not in cell_set:
                d = (1, 0)   # bottom side -> down
            elif (r, c + 1) in cell_set and (r, c - 1) not in cell_set:
                d = (0, -1)  # left side -> left
            elif (r, c - 1) in cell_set and (r, c + 1) not in cell_set:
                d = (0, 1)   # right side -> right
            if d is not None:
                dirs.append((r, c, d))
        comp_dirs.append(dirs)

    def trace_beam(sr, sc, dr, dc, activated):
        """Trace a straight beam. Returns (stop_r, stop_c, hit_component)."""
        r, c = sr, sc
        while True:
            nr, nc = r + dr, c + dc
            if not (0 <= nr < H and 0 <= nc < W):
                return r, c, -1
            cid = comp_id[nr, nc]
            if cid != -1:
                # Stop at the outer boundary of the component in this direction.
                if dr == -1:
                    top = min(y for y, x in comps[cid] if x == nc)
                    return top, nc, cid
                if dr == 1:
                    bot = max(y for y, x in comps[cid] if x == nc)
                    return bot, nc, cid
                if dc == -1:
                    left = min(x for y, x in comps[cid] if y == nr)
                    return nr, left, cid
                if dc == 1:
                    right = max(x for y, x in comps[cid] if y == nr)
                    return nr, right, cid
            r, c = nr, nc

    def paint_line(r1, c1, r2, c2):
        if r1 == r2:
            a, b = sorted((c1, c2))
            out[r1, a:b + 1] = 2
        else:
            a, b = sorted((r1, r2))
            out[a:b + 1, c1] = 2

    def paint_component(cid):
        for r, c in comps[cid]:
            out[r, c] = 2

    activated = set()
    queue = []

    # Initial beam from the 4 marker.
    r, c = r4, c4
    paint_line(r4, c4, r4, c4)
    hit = trace_beam(r4, c4, dr, dc, activated)
    stop_r, stop_c, cid = hit
    paint_line(r4, c4, stop_r, stop_c)
    if cid != -1 and cid not in activated:
        activated.add(cid)
        queue.append(cid)
        paint_component(cid)

    # Propagate beams from 3s in activated components.
    while queue:
        cid = queue.pop()
        for (r, c, d) in comp_dirs[cid]:
            stop_r, stop_c, hit_cid = trace_beam(r, c, d[0], d[1], activated)
            paint_line(r, c, stop_r, stop_c)
            if hit_cid != -1 and hit_cid not in activated:
                activated.add(hit_cid)
                queue.append(hit_cid)
                paint_component(hit_cid)

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Output starts as background.  The original 2/4 marker is kept as 2.
    out = np.full((H, W), 8, dtype=int)
    out[g == 2] = 2
    out[g == 4] = 2

    # Find the initial emitter (4) and its direction.
    fours = np.argwhere(g == 4)
    if len(fours) == 0:
        return out.tolist()

    r4, c4 = int(fours[0][0]), int(fours[0][1])

    # The 2s form the tail; the beam goes away from the tail.
    dr, dc = -1, 0  # fallback: upward
    if r4 + 1 < H and g[r4 + 1, c4] == 2:
        dr, dc = -1, 0
    elif r4 - 1 >= 0 and g[r4 - 1, c4] == 2:
        dr, dc = 1, 0
    elif c4 + 1 < W and g[r4, c4 + 1] == 2:
        dr, dc = 0, -1
    elif c4 - 1 >= 0 and g[r4, c4 - 1] == 2:
        dr, dc = 0, 1

    # Connected components of 1s and 3s.
    comp_id = -np.ones((H, W), dtype=int)
    comps = []
    for r in range(H):
        for c in range(W):
            if g[r, c] in (1, 3) and comp_id[r, c] == -1:
                cid = len(comps)
                q = deque([(r, c)])
                comp_id[r, c] = cid
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < H and 0 <= nx < W:
                            if g[ny, nx] in (1, 3) and comp_id[ny, nx] == -1:
                                comp_id[ny, nx] = cid
                                q.append((ny, nx))
                comps.append(cells)

    # For each component, find the outward direction of each 3.
    # A 3 emits in the direction where the opposite side is a 1 and the
    # forward side is outside the component.  Fallback: away from centroid.
    comp_emitters = []
    for cells in comps:
        cell_set = set(cells)
        avg_r = sum(r for r, _ in cells) / len(cells)
        avg_c = sum(c for _, c in cells) / len(cells)
        emitters = []

        for r, c in cells:
            if g[r, c] != 3:
                continue

            candidates = []
            for d in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                dr2, dc2 = d
                br, bc = r - dr2, c - dc2
                fr, fc = r + dr2, c + dc2

                back_is_1 = (
                    0 <= br < H and 0 <= bc < W and g[br, bc] == 1
                )
                forward_outside = (
                    not (0 <= fr < H and 0 <= fc < W and (fr, fc) in cell_set)
                )

                if back_is_1 and forward_outside:
                    candidates.append(d)

            if candidates:
                if len(candidates) == 1:
                    d = candidates[0]
                else:
                    # Choose the candidate pointing most away from centroid.
                    best = max(
                        candidates,
                        key=lambda d: d[0] * (r - avg_r) + d[1] * (c - avg_c),
                    )
                    d = best
            else:
                # Fallback: dominant direction from centroid to this 3.
                if abs(r - avg_r) >= abs(c - avg_c):
                    d = (-1, 0) if r < avg_r else (1, 0)
                else:
                    d = (0, -1) if c < avg_c else (0, 1)

            emitters.append((r, c, d))

        comp_emitters.append(emitters)

    def paint_line(r1, c1, r2, c2):
        if r1 == r2:
            a, b = sorted((c1, c2))
            out[r1, a:b + 1] = 2
        else:
            a, b = sorted((r1, r2))
            out[a:b + 1, c1] = 2

    def paint_component(cid):
        for r, c in comps[cid]:
            out[r, c] = 2

    def trace_beam(sr, sc, dr, dc):
        """
        Trace a beam from (sr, sc) in direction (dr, dc).
        Paints the beam and returns the id of the first component hit,
        or -1 if it reaches the grid boundary.
        """
        r, c = sr, sc
        while True:
            nr, nc = r + dr, c + dc
            if not (0 <= nr < H and 0 <= nc < W):
                return -1
            cid = comp_id[nr, nc]
            if cid != -1:
                paint_line(sr, sc, nr, nc)
                return cid
            r, c = nr, nc

    activated = set()
    queue = []

    # Initial beam from the 4 marker.
    hit = trace_beam(r4, c4, dr, dc)
    if hit != -1 and hit not in activated:
        activated.add(hit)
        queue.append(hit)
        paint_component(hit)

    # Propagate beams from activated components.
    while queue:
        cid = queue.pop()
        for r, c, d in comp_emitters[cid]:
            hit = trace_beam(r, c, d[0], d[1])
            if hit != -1 and hit not in activated:
                activated.add(hit)
                queue.append(hit)
                paint_component(hit)

    return out.tolist()

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Start from the checkerboard background (1 on even row+col, 0 otherwise).
    out = np.zeros((h, w), dtype=int)
    for r in range(h):
        for c in range(w):
            if (r + c) % 2 == 0:
                out[r, c] = 1

    # Preserve all non-background input cells.
    mask = (g != 0) & (g != 1)
    out[mask] = g[mask]

    # For every 8, extend its two diagonal rays until hitting a non-background
    # cell or the grid boundary.
    for r in range(h):
        for c in range(w):
            if g[r, c] != 8:
                continue
            for dr, dc in ((-1, -1), (-1, 1), (1, -1), (1, 1)):
                rr, cc = r + dr, c + dc
                while 0 <= rr < h and 0 <= cc < w and g[rr, cc] in (0, 1):
                    out[rr, cc] = 8
                    rr += dr
                    cc += dc

    return out.tolist()

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Preserve the checkerboard background and all input objects.
    out = np.array(grid, dtype=int)

    # Diagonal directions.
    dirs = [(-1, -1), (-1, 1), (1, -1), (1, 1)]

    # For every non-background cell, extend its color along all four diagonals
    # until the grid boundary or another non-background cell is reached.
    for r in range(h):
        for c in range(w):
            if g[r, c] in (0, 1):
                continue
            color = g[r, c]
            for dr, dc in dirs:
                rr, cc = r + dr, c + dc
                while 0 <= rr < h and 0 <= cc < w and g[rr, cc] in (0, 1):
                    out[rr, cc] = color
                    rr += dr
                    cc += dc

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    out = [row[:] for row in grid]
    h = len(grid)
    w = len(grid[0])

    # The puzzle uses a 7x25 grid with a 1-cell border and four 5x5 panels.
    # The rightmost panel is filled from the other three panels.
    if h != 7 or w != 25:
        return out

    # Border color is the color of the outer frame.
    border = grid[0][0]

    # Interior background color is the most common color inside the frame.
    from collections import Counter
    cnt = Counter()
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            cnt[grid[r][c]] += 1
    bg = cnt.most_common(1)[0][0]

    # Panel origins:
    # A: cols 1-5, B: cols 7-11, C: cols 13-17, D: cols 19-23
    origins = [(1, 1), (1, 7), (1, 13), (1, 19)]

    def panel(origin):
        r0, c0 = origin
        return [[grid[r0 + i][c0 + j] for j in range(5)] for i in range(5)]

    A = panel(origins[0])
    B = panel(origins[1])
    C = panel(origins[2])

    # Identify the three non-background panel colors.
    a_color = next(v for row in A for v in row if v != bg)
    b_color = next(v for row in B for v in row if v != bg)
    c_color = next(v for row in C for v in row if v != bg)

    # Binary masks for the three source panels.
    mA = [[1 if A[i][j] == a_color else 0 for j in range(5)] for i in range(5)]
    mB = [[1 if B[i][j] == b_color else 0 for j in range(5)] for i in range(5)]
    mC = [[1 if C[i][j] == c_color else 0 for j in range(5)] for i in range(5)]

    # Determine the partition line from panel A.
    # A contains a 5-cell line plus one or two marker cells.
    # The line can be vertical, horizontal, main diagonal, or anti-diagonal.
    line_type = None
    line_pos = None

    # Vertical line: one column has 5 A cells.
    for j in range(5):
        if all(mA[i][j] for i in range(5)):
            line_type = 'v'
            line_pos = j
            break

    # Horizontal line: one row has 5 A cells.
    if line_type is None:
        for i in range(5):
            if all(mA[i][j] for j in range(5)):
                line_type = 'h'
                line_pos = i
                break

    # Main diagonal.
    if line_type is None:
        if all(mA[i][i] for i in range(5)):
            line_type = 'd'

    # Anti-diagonal.
    if line_type is None:
        if all(mA[i][4 - i] for i in range(5)):
            line_type = 'a'

    # Fallback: choose the line with the most A cells.
    if line_type is None:
        best = ('v', 0, 0)
        for j in range(5):
            s = sum(mA[i][j] for i in range(5))
            if s > best[2]:
                best = ('v', j, s)
        for i in range(5):
            s = sum(mA[i][j] for j in range(5))
            if s > best[2]:
                best = ('h', i, s)
        s = sum(mA[i][i] for i in range(5))
        if s > best[2]:
            best = ('d', 0, s)
        s = sum(mA[i][4 - i] for i in range(5))
        if s > best[2]:
            best = ('a', 0, s)
        line_type, line_pos = best[0], best[1]

    # Decide which side of the line belongs to B and which to C.
    # Marker cells of A that are not on the line indicate the B side.
    def on_line(i, j):
        if line_type == 'v':
            return j == line_pos
        if line_type == 'h':
            return i == line_pos
        if line_type == 'd':
            return i == j
        if line_type == 'a':
            return i + j == 4
        return False

    b_side = None
    for i in range(5):
        for j in range(5):
            if mA[i][j] and not on_line(i, j):
                if line_type == 'v':
                    b_side = 'left' if j < line_pos else 'right'
                elif line_type == 'h':
                    b_side = 'top' if i < line_pos else 'bottom'
                elif line_type == 'd':
                    b_side = 'below' if i > j else 'above'
                elif line_type == 'a':
                    b_side = 'below' if i + j > 4 else 'above'
                break
        if b_side:
            break

    # If no marker is found, default to the side containing more A cells.
    if b_side is None:
        if line_type == 'v':
            left = sum(mA[i][j] for i in range(5) for j in range(line_pos))
            right = sum(mA[i][j] for i in range(5) for j in range(line_pos + 1, 5))
            b_side = 'left' if left >= right else 'right'
        elif line_type == 'h':
            top = sum(mA[i][j] for i in range(line_pos) for j in range(5))
            bottom = sum(mA[i][j] for i in range(line_pos + 1, 5) for j in range(5))
            b_side = 'top' if top >= bottom else 'bottom'
        elif line_type == 'd':
            below = sum(mA[i][j] for i in range(5) for j in range(5) if i > j)
            above = sum(mA[i][j] for i in range(5) for j in range(5) if i < j)
            b_side = 'below' if below >= above else 'above'
        else:
            below = sum(mA[i][j] for i in range(5) for j in range(5) if i + j > 4)
            above = sum(mA[i][j] for i in range(5) for j in range(5) if i + j < 4)
            b_side = 'below' if below >= above else 'above'

    # Fill the rightmost panel.
    r0, c0 = origins[3]
    for i in range(5):
        for j in range(5):
            val = bg
            if mB[i][j]:
                if line_type == 'v':
                    in_b = (j < line_pos) if b_side == 'left' else (j > line_pos)
                elif line_type == 'h':
                    in_b = (i < line_pos) if b_side == 'top' else (i > line_pos)
                elif line_type == 'd':
                    in_b = (i > j) if b_side == 'below' else (i < j)
                else:  # anti-diagonal
                    in_b = (i + j > 4) if b_side == 'below' else (i + j < 4)
                if in_b:
                    val = b_color
            elif mC[i][j]:
                if line_type == 'v':
                    in_c = (j > line_pos) if b_side == 'left' else (j < line_pos)
                elif line_type == 'h':
                    in_c = (i > line_pos) if b_side == 'top' else (i < line_pos)
                elif line_type == 'd':
                    in_c = (i < j) if b_side == 'below' else (i > j)
                else:  # anti-diagonal
                    in_c = (i + j < 4) if b_side == 'below' else (i + j > 4)
                if in_c:
                    val = c_color
            out[r0 + i][c0 + j] = val

    return out

