            line_type = 'd'

    if line_type is None:
        if all(mA[i][4 - i] for i in range(5)):
            line_type = 'a'

    # Fallback: choose the most populated line.
    if line_type is None:
        best = ('v', 0, 0)
        for j in range(5):
            s = sum(mA[i][j] for i in range(5))
            if s > best[2]:
                best = ('v', j, s)
        for i in range(5):
            s = sum(mA[i][j] for j in range(5))
            if s > best[2]:
                best = ('h', i, s)
        s = sum(mA[i][i] for i in range(5))
        if s > best[2]:
            best = ('d', 0, s)
        s = sum(mA[i][4 - i] for i in range(5))
        if s > best[2]:
            best = ('a', 0, s)
        line_type, line_pos = best[0], best[1]

    def on_line(i, j):
        if line_type == 'v':
            return j == line_pos
        if line_type == 'h':
            return i == line_pos
        if line_type == 'd':
            return i == j
        if line_type == 'a':
            return i + j == 4
        return False

    # The side of the line indicated by A's extra marker cell.
    b_side = None
    for i in range(5):
        for j in range(5):
            if mA[i][j] and not on_line(i, j):
                if line_type == 'v':
                    b_side = 'left' if j < line_pos else 'right'
                elif line_type == 'h':
                    b_side = 'top' if i < line_pos else 'bottom'
                elif line_type == 'd':
                    b_side = 'below' if i > j else 'above'
                else:  # anti-diagonal
                    b_side = 'below' if i + j > 4 else 'above'
                break
        if b_side:
            break

    # If no marker is found, choose the side with more A cells.
    if b_side is None:
        if line_type == 'v':
            left = sum(mA[i][j] for i in range(5) for j in range(line_pos))
            right = sum(mA[i][j] for i in range(5) for j in range(line_pos + 1, 5))
            b_side = 'left' if left >= right else 'right'
        elif line_type == 'h':
            top = sum(mA[i][j] for i in range(line_pos) for j in range(5))
            bottom = sum(mA[i][j] for i in range(line_pos + 1, 5) for j in range(5))
            b_side = 'top' if top >= bottom else 'bottom'
        elif line_type == 'd':
            below = sum(mA[i][j] for i in range(5) for j in range(5) if i > j)
            above = sum(mA[i][j] for i in range(5) for j in range(5) if i < j)
            b_side = 'below' if below >= above else 'above'
        else:
            below = sum(mA[i][j] for i in range(5) for j in range(5) if i + j > 4)
            above = sum(mA[i][j] for i in range(5) for j in range(5) if i + j < 4)
            b_side = 'below' if below >= above else 'above'

    def in_b_side(i, j):
        if line_type == 'v':
            if b_side == 'left':
                return j <= line_pos
            else:
                return j >= line_pos
        if line_type == 'h':
            if b_side == 'top':
                return i <= line_pos
            else:
                return i >= line_pos
        if line_type == 'd':
            if b_side == 'below':
                return i >= j
            else:
                return i <= j
        else:  # anti-diagonal
            if b_side == 'below':
                return i + j >= 4
            else:
                return i + j <= 4

    def in_c_side(i, j):
        if line_type == 'v':
            if b_side == 'left':
                return j >= line_pos
            else:
                return j <= line_pos
        if line_type == 'h':
            if b_side == 'top':
                return i >= line_pos
            else:
                return i <= line_pos
        if line_type == 'd':
            if b_side == 'below':
                return i <= j
            else:
                return i >= j
        else:  # anti-diagonal
            if b_side == 'below':
                return i + j <= 4
            else:
                return i + j >= 4

    # Build the output grid.
    out = [row[:] for row in grid]
    r0, c0 = origins[3]

    for i in range(5):
        for j in range(5):
            val = bg

            # B colour: keep B cells on the marker side of A's line.
            if mB[i][j] and in_b_side(i, j):
                val = b_color

            # C colour: keep C cells on the opposite side of A's line.
            elif mC[i][j] and in_c_side(i, j):
                val = c_color

            out[r0 + i][c0 + j] = val

    return out

import numpy as np
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Background is the border colour (also usually the most frequent colour).
    bg = int(g[0, 0])

    def cells_of_color(c):
        return [(r, cc) for r in range(h) for cc in range(w) if g[r, cc] == c]

    def component(cells, diag=False):
        """Return a list of connected components of the given cell set."""
        cell_set = set(cells)
        seen = set()
        comps = []
        for start in cell_set:
            if start in seen:
                continue
            q = deque([start])
            seen.add(start)
            comp = []
            while q:
                r, c = q.popleft()
                comp.append((r, c))
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        if dr == 0 and dc == 0:
                            continue
                        if not diag and abs(dr) + abs(dc) != 1:
                            continue
                        nb = (r + dr, c + dc)
                        if nb in cell_set and nb not in seen:
                            seen.add(nb)
                            q.append(nb)
            comps.append(comp)
        return comps

    # Colour 2 is the mirror/axis colour.
    axis_comps = component(cells_of_color(2), diag=True)

    # All non-background, non-2 cells are source shapes.
    source_cells = [(r, c) for r in range(h) for c in range(w)
                    if g[r, c] != bg and g[r, c] != 2]
    source_comps = component(source_cells, diag=False)

    def nearest_component(comp, target):
        best = None
        best_d = None
        for r, c in comp:
            d = abs(r - target[0]) + abs(c - target[1])
            if best_d is None or d < best_d:
                best_d = d
                best = (r, c)
        return best

    def reflect_point(p, axis):
        """Reflect point p across the axis component."""
        if len(axis) == 1:
            ar, ac = axis[0]
            return (2 * ar - p[0], 2 * ac - p[1])

        # If the axis is a straight line, reflect across that line.
        # Try horizontal, vertical, and the two diagonal orientations.
        # Horizontal: all rows equal.
        if all(r == axis[0][0] for r, c in axis):
            ar = axis[0][0]
            return (2 * ar - p[0], p[1])

        # Vertical: all cols equal.
        if all(c == axis[0][1] for r, c in axis):
            ac = axis[0][1]
            return (p[0], 2 * ac - p[1])

        # Diagonal slope +1: r - c constant.
        k = axis[0][0] - axis[0][1]
        if all(r - c == k for r, c in axis):
            # Reflect across r - c = k:
            # (r, c) -> (c + k, r - k)
            return (p[1] + k, p[0] - k)

        # Diagonal slope -1: r + c constant.
        s = axis[0][0] + axis[0][1]
        if all(r + c == s for r, c in axis):
            # Reflect across r + c = s:
            # (r, c) -> (s - c, s - r)
            return (s - p[1], s - p[0])

        # Fallback: point reflection through the axis centroid.
        ar = sum(r for r, c in axis) / len(axis)
        ac = sum(c for r, c in axis) / len(axis)
        return (2 * ar - p[0], 2 * ac - p[1])

    out = g.copy()

    for axis in axis_comps:
        # Find the source component closest to this axis.
        best_src = None
        best_dist = None
        for src in source_comps:
            # Use minimum Manhattan distance between any cells.
            for ar, ac in axis:
                for sr, sc in src:
                    d = abs(ar - sr) + abs(ac - sc)
                    if best_dist is None or d < best_dist:
                        best_dist = d
                        best_src = src
            if best_dist == 1:
                break

        if best_src is None:
            continue

        # Reflect every cell of the source component across the axis.
        for r, c in best_src:
            nr, nc = reflect_point((r, c), axis)
            if 0 <= nr < h and 0 <= nc < w:
                out[nr, nc] = g[r, c]

    return out.tolist()

