from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Background is the border colour.
    bg = int(g[0, 0])

    def cells_of_color(c):
        return [(r, cc) for r in range(h) for cc in range(w) if g[r, cc] == c]

    def component(cells, diag=False):
        cell_set = set(cells)
        seen = set()
        comps = []
        for start in cell_set:
            if start in seen:
                continue
            q = deque([start])
            seen.add(start)
            comp = []
            while q:
                r, c = q.popleft()
                comp.append((r, c))
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        if dr == 0 and dc == 0:
                            continue
                        if not diag and abs(dr) + abs(dc) != 1:
                            continue
                        nb = (r + dr, c + dc)
                        if nb in cell_set and nb not in seen:
                            seen.add(nb)
                            q.append(nb)
            comps.append(comp)
        return comps

    # Colour 2 components are symmetry axes / centres.
    axis_comps = component(cells_of_color(2), diag=True)

    # All non-background, non-2 cells are source shapes.
    source_cells = [(r, c) for r in range(h) for c in range(w)
                    if g[r, c] != bg and g[r, c] != 2]
    source_comps = component(source_cells, diag=False)

    def comp_distance(a, b):
        best = None
        for ar, ac in a:
            for br, bc in b:
                d = abs(ar - br) + abs(ac - bc)
                if best is None or d < best:
                    best = d
        return best

    def reflect_point(p, axis):
        """Reflect point p across the axis component."""
        if len(axis) == 1:
            ar, ac = axis[0]
            return (2 * ar - p[0], 2 * ac - p[1])

        # Horizontal line.
        if all(r == axis[0][0] for r, c in axis):
            ar = axis[0][0]
            return (2 * ar - p[0], p[1])

        # Vertical line.
        if all(c == axis[0][1] for r, c in axis):
            ac = axis[0][1]
            return (p[0], 2 * ac - p[1])

        # Diagonal slope +1: r - c constant.
        k = axis[0][0] - axis[0][1]
        if all(r - c == k for r, c in axis):
            return (p[1] + k, p[0] - k)

        # Diagonal slope -1: r + c constant.
        s = axis[0][0] + axis[0][1]
        if all(r + c == s for r, c in axis):
            return (s - p[1], s - p[0])

        # Fallback: point reflection through the axis centroid.
        ar = sum(r for r, c in axis) / len(axis)
        ac = sum(c for r, c in axis) / len(axis)
        return (2 * ar - p[0], 2 * ac - p[1])

    out = g.copy()

    # Pair each source component with its nearest 2-axis component.
    used_axes = set()
    assignments = []
    for src in source_comps:
        best_axis = None
        best_dist = None
        for i, axis in enumerate(axis_comps):
            if i in used_axes:
                continue
            d = comp_distance(src, axis)
            if best_dist is None or d < best_dist:
                best_dist = d
                best_axis = i
        if best_axis is not None:
            used_axes.add(best_axis)
            assignments.append((src, axis_comps[best_axis]))

    for src, axis in assignments:
        for r, c in src:
            nr, nc = reflect_point((r, c), axis)
            if 0 <= nr < h and 0 <= nc < w:
                out[nr, nc] = g[r, c]

    return out.tolist()

import numpy as np
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape
    out = np.full((H, W), 8, dtype=int)

    def neighbors4(r, c):
        for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr, nc = r+dr, c+dc
            if 0 <= nr < H and 0 <= nc < W:
                yield nr, nc

    # Components of node cells (1 and 3)
    node_mask = (g == 1) | (g == 3)
    node_id = np.zeros((H, W), dtype=int)
    nodes = []
    for r in range(H):
        for c in range(W):
            if node_mask[r, c] and node_id[r, c] == 0:
                cid = len(nodes) + 1
                q = deque([(r, c)])
                node_id[r, c] = cid
                cells = []
                while q:
                    cr, cc = q.popleft()
                    cells.append((cr, cc))
                    for nr, nc in neighbors4(cr, cc):
                        if node_mask[nr, nc] and node_id[nr, nc] == 0:
                            node_id[nr, nc] = cid
                            q.append((nr, nc))
                nodes.append(cells)

    def node_direction(cells):
        rmin = min(r for r, _ in cells)
        rmax = max(r for r, _ in cells)
        cmin = min(c for _, c in cells)
        cmax = max(c for _, c in cells)
        threes = [(r, c) for r, c in cells if g[r, c] == 3]
        if not threes:
            return None, []
        top = sum(1 for r, c in threes if r == rmin)
        bottom = sum(1 for r, c in threes if r == rmax)
        left = sum(1 for r, c in threes if c == cmin)
        right = sum(1 for r, c in threes if c == cmax)
        best = max((top, 'U'), (bottom, 'D'), (left, 'L'), (right, 'R'), key=lambda x: x[0])
        if best[0] == 0:
            return None, threes
        return best[1], threes

    for cells in nodes:
        d, threes = node_direction(cells)
        if d is None:
            continue
        if d == 'U':
            rows = [r for r, c in threes]
            cols = [c for r, c in threes]
            start_r = min(rows)
            for c in cols:
                for r in range(start_r, -1, -1):
                    out[r, c] = 2
        elif d == 'D':
            rows = [r for r, c in threes]
            cols = [c for r, c in threes]
            start_r = max(rows)
            for c in cols:
                for r in range(start_r, H):
                    out[r, c] = 2
        elif d == 'L':
            rows = [r for r, c in threes]
            cols = [c for r, c in threes]
            start_c = min(cols)
            for r in rows:
                for c in range(start_c, -1, -1):
                    out[r, c] = 2
        elif d == 'R':
            rows = [r for r, c in threes]
            cols = [c for r, c in threes]
            start_c = max(cols)
            for r in rows:
                for c in range(start_c, W):
                    out[r, c] = 2

    # Components of wire cells (2 and 4)
    wire_mask = (g == 2) | (g == 4)
    wire_id = np.zeros((H, W), dtype=int)
    wires = []
    for r in range(H):
        for c in range(W):
            if wire_mask[r, c] and wire_id[r, c] == 0:
                cid = len(wires) + 1
                q = deque([(r, c)])
                wire_id[r, c] = cid
                cells = []
                while q:
                    cr, cc = q.popleft()
                    cells.append((cr, cc))
                    for nr, nc in neighbors4(cr, cc):
                        if wire_mask[nr, nc] and wire_id[nr, nc] == 0:
                            wire_id[nr, nc] = cid
                            q.append((nr, nc))
                wires.append(cells)

    for cells in wires:
        for r, c in cells:
            out[r, c] = 2

        fours = [(r, c) for r, c in cells if g[r, c] == 4]
        if not fours:
            continue

        rmin = min(r for r, _ in cells)
        rmax = max(r for r, _ in cells)
        cmin = min(c for _, c in cells)
        cmax = max(c for _, c in cells)

        for fr, fc in fours:
            if rmax - rmin >= cmax - cmin:
                if fr == rmin:
                    dr, dc = -1, 0
                elif fr == rmax:
                    dr, dc = 1, 0
                else:
                    continue
            else:
                if fc == cmin:
                    dr, dc = 0, -1
                elif fc == cmax:
                    dr, dc = 0, 1
                else:
                    continue

            r, c = fr + dr, fc + dc
            while 0 <= r < H and 0 <= c < W:
                if node_mask[r, c]:
                    break
                out[r, c] = 2
                r += dr
                c += dc

    return out.tolist()

import sys
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    # Accept either list of lists of ints or list of strings.
    if grid and isinstance(grid[0], str):
        g = [[int(ch) for ch in row] for row in grid]
    else:
        g = [[int(v) for v in row] for row in grid]

    H = len(g)
    W = len(g[0]) if H else 0
    out = [[8] * W for _ in range(H)]

    def in_bounds(r, c):
        return 0 <= r < H and 0 <= c < W

    def cells4(r, c):
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if in_bounds(nr, nc):
                yield nr, nc

    # ---------- node components: colors 1 and 3 ----------
    node_id = [[0] * W for _ in range(H)]
    node_info = [None]  # 1-based ids

    for r in range(H):
        for c in range(W):
            if g[r][c] in (1, 3) and node_id[r][c] == 0:
                nid = len(node_info)
                q = deque([(r, c)])
                node_id[r][c] = nid
                cells = []
                while q:
                    cr, cc = q.popleft()
                    cells.append((cr, cc))
                    for nr, nc in cells4(cr, cc):
                        if g[nr][nc] in (1, 3) and node_id[nr][nc] == 0:
                            node_id[nr][nc] = nid
                            q.append((nr, nc))

                threes = [(cr, cc) for cr, cc in cells if g[cr][cc] == 3]
                rmin = min(cr for cr, _ in cells)
                rmax = max(cr for cr, _ in cells)
                cmin = min(cc for _, cc in cells)
                cmax = max(cc for _, cc in cells)

                side_counts = {
                    'U': sum(1 for cr, cc in threes if cr == rmin),
                    'D': sum(1 for cr, cc in threes if cr == rmax),
                    'L': sum(1 for cr, cc in threes if cc == cmin),
                    'R': sum(1 for cr, cc in threes if cc == cmax),
                }
                best = max(side_counts.values())
                direction = None
                if best > 0:
                    candidates = [d for d, v in side_counts.items() if v == best]
                    if len(candidates) == 1:
                        direction = candidates[0]
                    else:
                        # Tie-break by centroid of 1-cells vs centroid of 3-cells.
                        ones = [(cr, cc) for cr, cc in cells if g[cr][cc] == 1] or cells
                        or_ = sum(cr for cr, _ in ones) / len(ones)
                        oc = sum(cc for _, cc in ones) / len(ones)
                        tr = sum(cr for cr, _ in threes) / len(threes)
                        tc = sum(cc for _, cc in threes) / len(threes)
                        scores = {
                            'U': max(0.0, or_ - tr),
                            'D': max(0.0, tr - or_),
                            'L': max(0.0, oc - tc),
                            'R': max(0.0, tc - oc),
                        }
                        direction = max(candidates, key=lambda d: scores[d])

                if direction == 'U':
                    side_threes = [(cr, cc) for cr, cc in threes if cr == rmin] or threes
                    frontier = [(cr - 1, cc) for cr, cc in side_threes]
                    dvec = (-1, 0)
                elif direction == 'D':
                    side_threes = [(cr, cc) for cr, cc in threes if cr == rmax] or threes
                    frontier = [(cr + 1, cc) for cr, cc in side_threes]
                    dvec = (1, 0)
                elif direction == 'L':
                    side_threes = [(cr, cc) for cr, cc in threes if cc == cmin] or threes
                    frontier = [(cr, cc - 1) for cr, cc in side_threes]
                    dvec = (0, -1)
                elif direction == 'R':
                    side_threes = [(cr, cc) for cr, cc in threes if cc == cmax] or threes
                    frontier = [(cr, cc + 1) for cr, cc in side_threes]
                    dvec = (0, 1)
                else:
                    frontier = []
                    dvec = None

                node_info.append({
                    'cells': cells,
                    'direction': direction,
                    'frontier': frontier,
                    'dvec': dvec,
                })

    # ---------- wire components: colors 2 and 4 ----------
    wire_id = [[0] * W for _ in range(H)]
    wires = []

    for r in range(H):
        for c in range(W):
            if g[r][c] in (2, 4) and wire_id[r][c] == 0:
                wid = len(wires)
                q = deque([(r, c)])
                wire_id[r][c] = wid
                cells = []
                while q:
                    cr, cc = q.popleft()
                    cells.append((cr, cc))
                    for nr, nc in cells4(cr, cc):
                        if g[nr][nc] in (2, 4) and wire_id[nr][nc] == 0:
                            wire_id[nr][nc] = wid
                            q.append((nr, nc))
                wires.append(cells)

    def start_direction_for_four(four, comp_cells):
        fr, fc = four
        adj2 = []
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = fr + dr, fc + dc
            if in_bounds(nr, nc) and g[nr][nc] == 2:
                adj2.append((nr, nc))

        if len(adj2) == 1:
            ar, ac = adj2[0]
            return (fr - ar, fc - ac)

        if adj2:
            # If multiple adjacent 2s, use the direction in which the 4 is extreme.
            rmin = min(r for r, _ in comp_cells)
            rmax = max(r for r, _ in comp_cells)
            cmin = min(c for _, c in comp_cells)
            cmax = max(c for _, c in comp_cells)
            if fr == rmin:
                return (-1, 0)
            if fr == rmax:
                return (1, 0)
            if fc == cmin:
                return (0, -1)
            if fc == cmax:
                return (0, 1)

        # Fallback: away from component centroid.
        cr = sum(r for r, _ in comp_cells) / len(comp_cells)
        cc = sum(c for _, c in comp_cells) / len(comp_cells)
        dr = fr - cr
        dc = fc - cc
        if abs(dr) >= abs(dc):
            return (1 if dr >= 0 else -1, 0)
        else:
            return (0, 1 if dc >= 0 else -1)

    visited_nodes = set()
    frontier = []

    for comp in wires:
        fours = [(r, c) for r, c in comp if g[r][c] == 4]
        if not fours:
            continue

        # Existing wire cells become 2.
        for r, c in comp:
            out[r][c] = 2

        for four in fours:
            d = start_direction_for_four(four, comp)
            if d is None:
                continue
            frontier.append((four[0] + d[0], four[1] + d[1], d[0], d[1]))

    # ---------- propagate rays ----------
    while frontier:
        next_frontier = []
        hit_nodes = set()

        for r, c, dr, dc in frontier:
            if not in_bounds(r, c):
                continue

            v = g[r][c]
            if v == 8:
                out[r][c] = 2
                next_frontier.append((r + dr, c + dc, dr, dc))
            elif v in (1, 3):
                nid = node_id[r][c]
                if nid not in visited_nodes:
                    hit_nodes.add(nid)
            elif v in (2, 4):
                # Pass through already-drawn / other wire cells.
                out[r][c] = 2
                next_frontier.append((r + dr, c + dc, dr, dc))
            else:
                # Unknown color: stop this ray.
                pass

        # If any part of a beam hits a node, treat the whole beam as interacting
        # with that node: stop the incoming beam and emit the node's exit beam.
        if hit_nodes:
            # Remove all incoming frontier cells that are in the same beam group.
            # A simple robust way: discard all current next_frontier cells that
            # would have continued from the same direction as a hit node.
            # In these puzzles beams are aligned, so this prevents stray parallel rays.
            hit_dirs = set()
            for r, c, dr, dc in frontier:
                if in_bounds(r, c) and g[r][c] in (1, 3) and node_id[r][c] in hit_nodes:
                    hit_dirs.add((dr, dc))

            if hit_dirs:
                next_frontier = [
                    (nr, nc, ndr, ndc)
                    for (nr, nc, ndr, ndc) in next_frontier
                    if (ndr, ndc) not in hit_dirs
                ]

            for nid in hit_nodes:
                visited_nodes.add(nid)
                info = node_info[nid]
                for rr, cc in info['cells']:
                    out[rr][cc] = 2

                if info['dvec'] is not None:
                    dr, dc = info['dvec']
                    for rr, cc in info['frontier']:
                        next_frontier.append((rr, cc, dr, dc))

        frontier = next_frontier

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # The background is the colour that fills the border.
    border = np.concatenate([
        g[0, :], g[-1, :], g[:, 0], g[:, -1]
    ])
    vals, counts = np.unique(border, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    out = g.copy()

    # Non-background cells.
    mask = g != bg

    # Connected components of non-background cells (8-neighbourhood).
    seen = np.zeros_like(mask, dtype=bool)
    comps = []
    for r in range(h):
        for c in range(w):
            if mask[r, c] and not seen[r, c]:
                stack = [(r, c)]
                seen[r, c] = True
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < h and 0 <= nx < w:
                                if mask[ny, nx] and not seen[ny, nx]:
                                    seen[ny, nx] = True
                                    stack.append((ny, nx))
                comps.append(cells)

    def reflect(cells, axis):
        """
        axis is one of:
          ('v', col)  vertical mirror line at col
          ('h', row)  horizontal mirror line at row
          ('p', r, c) point mirror at (r, c)
        Returns a list of (new_r, new_c, value) for cells that are not on the axis.
        """
        res = []
        if axis[0] == 'v':
            col = axis[1]
            for r, c, v in cells:
                if c == col:
                    continue
                nc = 2 * col - c
                if 0 <= nc < w:
                    res.append((r, nc, v))
        elif axis[0] == 'h':
            row = axis[1]
            for r, c, v in cells:
                if r == row:
                    continue
                nr = 2 * row - r
                if 0 <= nr < h:
                    res.append((nr, c, v))
        else:
            r0, c0 = axis[1], axis[2]
            for r, c, v in cells:
                if r == r0 and c == c0:
                    continue
                nr = 2 * r0 - r
                nc = 2 * c0 - c
                if 0 <= nr < h and 0 <= nc < w:
                    res.append((nr, nc, v))
        return res

    for cells in comps:
        # Only components containing the special axis colour 2 are transformed.
        twos = [(r, c) for r, c in cells if g[r, c] == 2]
        if not twos:
            continue

        # If the 2s form a straight line, use that line as the mirror axis.
        if len(twos) >= 2:
            rows = {r for r, c in twos}
            cols = {c for r, c in twos}
            if len(rows) == 1:
                axis = ('h', next(iter(rows)))
            elif len(cols) == 1:
                axis = ('v', next(iter(cols)))
            else:
                # Fallback: point reflection about the centroid of the 2s.
                r0 = sum(r for r, c in twos) / len(twos)
                c0 = sum(c for r, c in twos) / len(twos)
                axis = ('p', int(round(r0)), int(round(c0)))
        else:
            # A single 2 is a point mirror.
            r0, c0 = twos[0]
            axis = ('p', r0, c0)

        for nr, nc, v in reflect(cells, axis):
            # Do not overwrite existing non-background cells.
            if out[nr, nc] == bg:
                out[nr, nc] = v

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Background is the most common border colour.
    border = np.concatenate([g[0, :], g[-1, :], g[:, 0], g[:, -1]])
    vals, counts = np.unique(border, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    out = g.copy()

    # Connected components of non-background cells (8-neighbourhood).
    mask = g != bg
    seen = np.zeros_like(mask, dtype=bool)
    comps = []

    for r in range(h):
        for c in range(w):
            if mask[r, c] and not seen[r, c]:
                stack = [(r, c)]
                seen[r, c] = True
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < h and 0 <= nx < w:
                                if mask[ny, nx] and not seen[ny, nx]:
                                    seen[ny, nx] = True
                                    stack.append((ny, nx))
                comps.append(cells)

    for cells in comps:
        twos = [(r, c) for r, c in cells if g[r, c] == 2]
        if not twos:
            continue

        # For every non-2 cell in this component, reflect it about the
        # closest 2 in the same row if possible, otherwise the closest 2
        # in the same column.  Ties are broken by preferring the row mirror.
        for r, c in cells:
            if g[r, c] == 2:
                continue

            best = None  # (distance, priority, mirror_r, mirror_c)

            # Same-row mirrors.
            for mr, mc in twos:
                if mr == r:
                    d = abs(mc - c)
                    if d > 0:
                        best = (d, 0, mr, mc)
                        break  # twos are not sorted; keep first, but we need min below

            # Properly choose minimum distance in row.
            row_best = None
            for mr, mc in twos:
                if mr == r:
                    d = abs(mc - c)
                    if d > 0 and (row_best is None or d < row_best[0]):
                        row_best = (d, mc)
            if row_best is not None:
                d, mc = row_best
                best = (d, 0, r, mc)

            # Same-column mirrors.
            col_best = None
            for mr, mc in twos:
                if mc == c:
                    d = abs(mr - r)
                    if d > 0 and (col_best is None or d < col_best[0]):
                        col_best = (d, mr)
            if col_best is not None:
                d, mr = col_best
                # Prefer row mirror on ties.
                if best is None or d < best[0] or (d == best[0] and best[1] > 1):
                    best = (d, 1, mr, c)

            if best is not None:
                _, _, mr, mc = best
                nr = 2 * mr - r
                nc = 2 * mc - c
                if 0 <= nr < h and 0 <= nc < w and out[nr, nc] == bg:
                    out[nr, nc] = g[r, c]

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Find the central 3-ring (the only 3s in the examples/tests).
    ys, xs = np.where(g == 3)
    if len(ys) == 0:
        return g.tolist()

    cy = int(ys.mean())
    cx = int(xs.mean())

    # Collect the non-background, non-3 object pixels.
    obj = [(r, c, int(g[r, c])) for r in range(h) for c in range(w)
           if g[r, c] not in (0, 1, 3)]

    # Determine the two main diagonals (slope +1) and two anti-diagonals
    # (slope -1) that pass through the outer object pixels.
    main_consts = set()
    anti_consts = set()
    for r, c, _ in obj:
        main_consts.add(c - r)
        anti_consts.add(r + c)

    # Keep the two most central diagonals of each orientation.
    def two_closest(vals, center):
        return sorted(vals, key=lambda v: (abs(v - center), v))[:2]

    main_lines = two_closest(main_consts, cx - cy)
    anti_lines = two_closest(anti_consts, cy + cx)

    # Determine which colour belongs to each diagonal family.
    main_colours = {}
    anti_colours = {}
    for r, c, v in obj:
        if c - r in main_lines:
            main_colours.setdefault(c - r, v)
        if r + c in anti_lines:
            anti_colours.setdefault(r + c, v)

    out = g.copy()

    # Draw the selected diagonals across the whole grid.
    for k in main_lines:
        col = main_colours.get(k)
        if col is None:
            continue
        for r in range(h):
            c = r + k
            if 0 <= c < w:
                out[r, c] = col

    for s in anti_lines:
        col = anti_colours.get(s)
        if col is None:
            continue
        for r in range(h):
            c = s - r
            if 0 <= c < w:
                out[r, c] = col

    # The central 3-ring has priority over the drawn diagonals.
    for r, c in zip(ys, xs):
        out[r, c] = 3

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # The central marker is a diamond/ring of 3s.
    ys, xs = np.where(g == 3)
    if len(ys) == 0:
        return g.tolist()

    cy = int(ys.mean())
    cx = int(xs.mean())

    # The four short diagonal arms use the two non-background colours
    # other than 3 (in the examples/tests: 2 and 4).
    colours = sorted({int(v) for v in g.flat if v not in (0, 1, 3)})
    if len(colours) != 2:
        return g.tolist()
    c1, c2 = colours

    # For each colour, find the two diagonal lines (one with slope +1,
    # one with slope -1) that contain its arm pixels.
    def line_constants(color):
        main = set()
        anti = set()
        for r in range(h):
            for c in range(w):
                if g[r, c] == color:
                    main.add(c - r)
                    anti.add(r + c)
        # Keep the two most central lines of each orientation.
        main = sorted(main, key=lambda k: (abs(k - (cx - cy)), k))[:2]
        anti = sorted(anti, key=lambda s: (abs(s - (cy + cx)), s))[:2]
        return main, anti

    out = g.copy()

    for color in (c1, c2):
        main_lines, anti_lines = line_constants(color)

        for k in main_lines:
            for r in range(h):
                c = r + k
                if 0 <= c < w:
                    out[r, c] = color

        for s in anti_lines:
            for r in range(h):
                c = s - r
                if 0 <= c < w:
                    out[r, c] = color

    # The original 3-diamond has priority over the extended diagonals.
    for r, c in zip(ys, xs):
        out[r, c] = 3

    return out.tolist()

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Most common colour is treated as the background.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # Find full-width horizontal bands:
    # rows whose first and last cells are the same non-background colour.
    bands = []
    r = 0
    while r < H:
        if g[r, 0] != bg and g[r, 0] == g[r, -1]:
            b = int(g[r, 0])
            r0 = r
            while r < H and g[r, 0] == b and g[r, -1] == b:
                r += 1
            r1 = r - 1
            # interior colour is the most common non-border colour inside the band
            inner = g[r0:r1 + 1, 1:-1]
            inner_vals, inner_counts = np.unique(inner, return_counts=True)
            fill = int(inner_vals[np.argmax(inner_counts)])
            bands.append((r0, r1, b, fill))
        else:
            r += 1

    # Start from the input, then erase all non-background cells outside bands.
    out = g.copy()
    for r in range(H):
        in_band = False
        for r0, r1, b, fill in bands:
            if r0 <= r <= r1:
                in_band = True
                break
        if not in_band:
            out[r, :] = bg

    # Find connected components of non-background cells in the original input.
    visited = np.zeros((H, W), dtype=bool)
    components = []
    for sr in range(H):
        for sc in range(W):
            if visited[sr, sc] or g[sr, sc] == bg:
                continue
            color = int(g[sr, sc])
            stack = [(sr, sc)]
            visited[sr, sc] = True
            cells = []
            while stack:
                r, c = stack.pop()
                cells.append((r, c))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < H and 0 <= nc < W:
                        if not visited[nr, nc] and g[nr, nc] == color:
                            visited[nr, nc] = True
                            stack.append((nr, nc))
            components.append(cells)

    def bbox(cells):
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        return min(rs), max(rs), min(cs), max(cs)

    def is_band_row(row):
        return any(r0 <= row <= r1 for r0, r1, _, _ in bands)

    # Small objects are components not touching a band row.
    objects = []
    for cells in components:
        if any(is_band_row(r) for r, c in cells):
            continue
        r0, r1, c0, c1 = bbox(cells)
        h = r1 - r0 + 1
        w = c1 - c0 + 1
        if h < 2 or w < 2:
            continue
        # The object's key colour is its border colour if it has a border,
        # otherwise its solid colour.
        border = int(g[r0, c0])
        if (g[r0, c1] == border and g[r1, c0] == border and g[r1, c1] == border):
            key = border
        else:
            vals, counts = np.unique([int(g[r, c]) for r, c in cells], return_counts=True)
            key = int(vals[np.argmax(counts)])
        objects.append((r0, r1, c0, c1, key))

    # Stamp each small object into the band whose fill colour matches its key colour.
    for r0, r1, c0, c1, key in objects:
        target = None
        for band in bands:
            if band[3] == key:
                target = band
                break
        if target is None:
            continue
        br0, br1, bborder, bfill = target

        h = r1 - r0 + 1
        w = c1 - c0 + 1

        # Prefer placing the object in the lower part of the band,
        # preserving its relative horizontal position when possible.
        tr0 = br1 - h + 1
        if tr0 < br0:
            tr0 = br0
        tc0 = c0
        if tc0 + w > W:
            tc0 = W - w
        if tc0 < 0:
            tc0 = 0

        for i in range(h):
            for j in range(w):
                col = int(g[r0 + i, c0 + j])
                if col == key:
                    new_col = bborder
                else:
                    new_col = bfill
                out[tr0 + i, tc0 + j] = new_col

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # For every colour c, find vertical runs of another colour d that are
    # directly between two c cells in the same column.
    # If there are several such runs for the same (c, d), recolor the one
    # whose column is closest to the side where c first appears in the grid.
    for c in range(1, 10):
        # Determine side preference for colour c from its first occurrence.
        first = None
        for r in range(h):
            for col in range(w):
                if g[r, col] == c:
                    first = (r, col)
                    break
            if first is not None:
                break
        if first is None:
            continue
        side = "left" if first[1] < w / 2 else "right"

        candidates = []
        for d in range(1, 10):
            if d == c:
                continue
            for col in range(w):
                r = 0
                while r < h:
                    if g[r, col] == d:
                        start = r
                        while r < h and g[r, col] == d:
                            r += 1
                        end = r - 1
                        if start > 0 and end + 1 < h:
                            if g[start - 1, col] == c and g[end + 1, col] == c:
                                candidates.append((col, start, end, d))
                    else:
                        r += 1

        if not candidates:
            continue

        if side == "left":
            candidates.sort(key=lambda x: x[0])
        else:
            candidates.sort(key=lambda x: -x[0])

        # Recolor the selected run(s).  In the provided cases this is one run.
        for col, start, end, d in candidates:
            out[start:end + 1, col] = c

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Find all maximal vertical segments whose top and bottom cells have the
    # same color and whose interior is a single different color.
    segments = []
    for c in range(w):
        r = 0
        while r < h:
            if g[r, c] == 0:
                r += 1
                continue

            r2 = r
            while r2 + 1 < h and g[r2 + 1, c] != 0:
                r2 += 1

            top = g[r, c]
            bottom = g[r2, c]
            if top == bottom and r2 > r:
                interior = g[r + 1:r2, c]
                if len(np.unique(interior)) == 1:
                    fill = int(interior[0])
                    if fill != top:
                        segments.append((r, r2, c, top, fill))
            r = r2 + 1

    if not segments:
        return out.tolist()

    # For each endpoint color, choose the segment to "solidify".
    # The examples show that the chosen segment is the one whose top endpoint
    # is closest to the top of the grid; ties are broken by the leftmost column.
    best = {}
    for seg in segments:
        r1, r2, c, endpoint, fill = seg
        key = endpoint
        # Smaller top row first; if equal, smaller column first.
        if key not in best or (r1, c) < (best[key][0], best[key][2]):
            best[key] = seg

    for seg in best.values():
        r1, r2, c, endpoint, fill = seg
        out[r1 + 1:r2, c] = endpoint

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Find vertical "hollow bars":
    # a maximal non-zero column run whose top and bottom cells have the same
    # color, and whose interior is a single different color.
    segments = []
    for c in range(w):
        r = 0
        while r < h:
            if g[r, c] == 0:
                r += 1
                continue

            r2 = r
            while r2 + 1 < h and g[r2 + 1, c] != 0:
                r2 += 1

            top = g[r, c]
            bottom = g[r2, c]

            if top == bottom and r2 > r:
                interior = g[r + 1:r2, c]
                if len(np.unique(interior)) == 1:
                    fill = int(interior[0])
                    if fill != top:
                        segments.append((r, r2, c, int(top), fill))

            r = r2 + 1

    if not segments:
        return out.tolist()

    # Solidify only the leftmost and rightmost such bars.
    min_col = min(seg[2] for seg in segments)
    max_col = max(seg[2] for seg in segments)

    for r1, r2, c, endpoint, _ in segments:
        if c == min_col or c == max_col:
            out[r1 + 1:r2, c] = endpoint

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0]) if h else 0
    out = [row[:] for row in grid]

    # A cell is traversable if it is 7, or is the starting 6 in column 0.
    def open_cell(r, c):
        if r < 0 or r >= h or c < 0 or c >= w:
            return False
        v = grid[r][c]
        return v == 7 or (c == 0 and v == 6)

    # For each starting 6 in the left border, find the furthest reachable
    # traversable cell using only right/down moves.  If that cell is not the
    # start, move the 6 there.
    for r in range(h):
        if grid[r][0] != 6:
            continue

        best = (r, 0)
        stack = [(r, 0)]
        seen = set(stack)

        while stack:
            cr, cc = stack.pop()
            if (cr, cc) > best:
                best = (cr, cc)

            for nr, nc in ((cr, cc + 1), (cr + 1, cc)):
                if (nr, nc) not in seen and open_cell(nr, nc):
                    seen.add((nr, nc))
                    stack.append((nr, nc))

        if best != (r, 0):
            out[r][0] = 7
            out[best[0]][best[1]] = 6

    return out

