import numpy as np
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Find the unique "key" color: a non-zero color appearing exactly once.
    key_color = None
    for c in range(1, 10):
        cnt = int(np.count_nonzero(g == c))
        if cnt == 1:
            key_color = c
            break

    if key_color is None:
        return [[int(x) for x in row] for row in g]

    # Flood-fill all 0-regions.
    visited = np.zeros((h, w), dtype=bool)
    regions = []

    for r in range(h):
        for c in range(w):
            if g[r, c] == 0 and not visited[r, c]:
                q = deque([(r, c)])
                visited[r, c] = True
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w:
                            if not visited[ny, nx] and g[ny, nx] == 0:
                                visited[ny, nx] = True
                                q.append((ny, nx))
                regions.append(cells)

    out = g.copy()

    for cells in regions:
        # Boundary cells are non-zero cells adjacent to this 0-region.
        boundary = set()
        for y, x in cells:
            for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                ny, nx = y + dy, x + dx
                if 0 <= ny < h and 0 <= nx < w:
                    v = int(g[ny, nx])
                    if v != 0:
                        boundary.add(v)

        # Fill only regions whose boundary is a single color.
        if len(boundary) == 1:
            for y, x in cells:
                out[y, x] = key_color

    return [[int(x) for x in row] for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # A row is a horizontal "gap" row if it starts with 6 and is otherwise
    # only 7s or a single non-7 colour at the right edge.
    def is_gap_row(r: int) -> bool:
        if r < 0 or r >= h or g[r, 0] != 6:
            return False
        row = g[r, 1:]
        if np.all(row == 7):
            return True
        # allow one trailing non-7 colour
        if row[-1] != 7 and np.all(row[:-1] == 7):
            return True
        return False

    # The colour represented by a non-gap row is the first non-6/non-7 colour
    # in the row, if present.
    def row_colour(r: int):
        if r < 0 or r >= h:
            return None
        for c in range(w):
            v = g[r, c]
            if v not in (6, 7):
                return int(v)
        return None

    # For each gap row between two rows of the same colour, move its 6 right.
    for r in range(h):
        if not is_gap_row(r):
            continue
        above = row_colour(r - 1)
        below = row_colour(r + 1)
        if above is None or above != below:
            continue

        # Find the rightmost 7 in this row.
        c = w - 1
        while c >= 1 and g[r, c] != 7:
            c -= 1
        if c < 1:
            continue

        # Remove the original 6.
        out[r, 0] = 7

        # If the gap row is immediately adjacent to a non-7 cell of the
        # matching colour, the 6 is absorbed.
        if c + 1 < w and g[r, c + 1] == above:
            continue

        # Otherwise place it on the rightmost 7.
        out[r, c] = 6

    # Vertical analogue: a column of 7s between two columns of the same colour.
    # The 6 is placed at the top or bottom end of the 7-run when that end is
    # on the grid boundary.
    def is_gap_col(c: int) -> bool:
        if c < 0 or c >= w:
            return False
        col = g[:, c]
        if np.all(col == 7):
            return True
        if col[0] != 7 and np.all(col[1:] == 7):
            return True
        if col[-1] != 7 and np.all(col[:-1] == 7):
            return True
        return False

    def col_colour(c: int):
        if c < 0 or c >= w:
            return None
        for r in range(h):
            v = g[r, c]
            if v not in (6, 7):
                return int(v)
        return None

    for c in range(w):
        if not is_gap_col(c):
            continue
        left = col_colour(c - 1)
        right = col_colour(c + 1)
        if left is None or left != right:
            continue

        # Top boundary end.
        if g[0, c] == 7:
            out[0, c] = 6
        # Bottom boundary end.
        if g[h - 1, c] == 7:
            out[h - 1, c] = 6

    return out.tolist()

