import numpy as np
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape
    out = g.copy()

    # Find the 2-column legend/key block.
    # It is a maximal vertical run of rows where two adjacent columns are
    # non-background and form a consistent pair list.
    best = None
    for c in range(W - 1):
        for r in range(H):
            if g[r, c] == 0 or g[r, c + 1] == 0:
                continue
            r2 = r
            while r2 + 1 < H and g[r2 + 1, c] != 0 and g[r2 + 1, c + 1] != 0:
                r2 += 1
            h = r2 - r + 1
            if h >= 2:
                if best is None or h > best[0]:
                    best = (h, r, r2, c)
    if best is None:
        return out.tolist()

    _, kr0, kr1, kc = best
    key_cells = set()
    mapping = {}
    for r in range(kr0, kr1 + 1):
        a, b = int(g[r, kc]), int(g[r, kc + 1])
        key_cells.add((r, kc))
        key_cells.add((r, kc + 1))
        if b != 0:
            mapping[a] = b

    def components(color):
        seen = np.zeros((H, W), dtype=bool)
        comps = []
        for i in range(H):
            for j in range(W):
                if g[i, j] == color and not seen[i, j]:
                    q = deque([(i, j)])
                    seen[i, j] = True
                    cells = []
                    while q:
                        x, y = q.popleft()
                        cells.append((x, y))
                        for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                            nx, ny = x + dx, y + dy
                            if 0 <= nx < H and 0 <= ny < W:
                                if not seen[nx, ny] and g[nx, ny] == color:
                                    seen[nx, ny] = True
                                    q.append((nx, ny))
                    comps.append(cells)
        return comps

    # Draw all rectangles.  Later mappings overwrite earlier ones, but original
    # non-zero cells are preserved.
    for a, b in mapping.items():
        comps = [c for c in components(a) if all(p not in key_cells for p in c)]
        if len(comps) < 2:
            continue

        # Use only components large enough to be real objects.
        big = [c for c in comps if len(c) >= 2]
        if len(big) >= 2:
            cells = [p for c in big for p in c]
        else:
            cells = [p for c in comps for p in c]

        rmin = min(p[0] for p in cells)
        rmax = max(p[0] for p in cells)
        cmin = min(p[1] for p in cells)
        cmax = max(p[1] for p in cells)

        for r in range(rmin, rmax + 1):
            for c in range(cmin, cmax + 1):
                if out[r, c] == 0:
                    out[r, c] = b

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    n = len(grid)
    a = [row[:] for row in grid]

    # First pass: fill any off-diagonal zero from its transpose.
    for i in range(n):
        for j in range(i + 1, n):
            if a[i][j] == 0 and a[j][i] != 0:
                a[i][j] = a[j][i]
            elif a[j][i] == 0 and a[i][j] != 0:
                a[j][i] = a[i][j]

    # Second pass: fill remaining off-diagonal zeros using the nearest
    # non-zero value in the same row or column.
    for i in range(n):
        for j in range(i + 1, n):
            if a[i][j] != 0:
                continue

            val = 0

            # Search left in row i.
            for k in range(j - 1, -1, -1):
                if a[i][k] != 0:
                    val = a[i][k]
                    break
            if val == 0:
                # Search right in row i.
                for k in range(j + 1, n):
                    if a[i][k] != 0:
                        val = a[i][k]
                        break

            # Search up in column j.
            if val == 0:
                for k in range(i - 1, -1, -1):
                    if a[k][j] != 0:
                        val = a[k][j]
                        break
            if val == 0:
                # Search down in column j.
                for k in range(i + 1, n):
                    if a[k][j] != 0:
                        val = a[k][j]
                        break

            if val != 0:
                a[i][j] = val
                a[j][i] = val

    # Fill diagonal zeros using the nearest non-zero value in the same row.
    for i in range(n):
        if a[i][i] != 0:
            continue

        val = 0
        for k in range(i - 1, -1, -1):
            if a[i][k] != 0:
                val = a[i][k]
                break
        if val == 0:
            for k in range(i + 1, n):
                if a[i][k] != 0:
                    val = a[i][k]
                    break

        if val != 0:
            a[i][i] = val

    return a

from collections import Counter

def transform(grid: list[list[int]]) -> list[list[int]]:
    n = len(grid)
    result = [row[:] for row in grid]

    # Step 1: Make symmetric - fill from transpose
    for i in range(n):
        for j in range(i+1, n):
            if result[i][j] == 0 and result[j][i] != 0:
                result[i][j] = result[j][i]
            elif result[j][i] == 0 and result[i][j] != 0:
                result[j][i] = result[i][j]

    # Step 2: Fill remaining zeros
    for i in range(n):
        for j in range(n):
            if result[i][j] == 0:
                # Collect candidate values from row, column, and neighbors
                candidates = []

                # From row
                for k in range(n):
                    if k != j and result[i][k] != 0:
                        candidates.append(result[i][k])

                # From column
                for k in range(n):
                    if k != i and result[k][j] != 0:
                        candidates.append(result[k][j])

                # From 4-neighbors (give them higher weight)
                if i > 0 and result[i-1][j] != 0:
                    candidates.append(result[i-1][j])
                    candidates.append(result[i-1][j])
                if i < n-1 and result[i+1][j] != 0:
                    candidates.append(result[i+1][j])
                    candidates.append(result[i+1][j])
                if j > 0 and result[i][j-1] != 0:
                    candidates.append(result[i][j-1])
                    candidates.append(result[i][j-1])
                if j < n-1 and result[i][j+1] != 0:
                    candidates.append(result[i][j+1])
                    candidates.append(result[i][j+1])

                if candidates:
                    result[i][j] = Counter(candidates).most_common(1)[0][0]

    return result

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Find all maximal hollow rectangular frames.
    # A frame has a 1-cell border of one non-background color and a uniform
    # background interior.
    frames = []
    for r in range(h):
        for c in range(w):
            color = int(g[r, c])
            if color == 0:
                continue

            for fh in range(3, h - r + 1):
                r2 = r + fh - 1
                if r2 >= h:
                    break

                for fw in range(3, w - c + 1):
                    c2 = c + fw - 1
                    if c2 >= w:
                        break

                    top = g[r, c:c2 + 1]
                    bottom = g[r2, c:c2 + 1]
                    left = g[r:r2 + 1, c]
                    right = g[r:r2 + 1, c2]

                    if not (np.all(top == color) and
                            np.all(bottom == color) and
                            np.all(left == color) and
                            np.all(right == color)):
                        continue

                    interior = g[r + 1:r2, c + 1:c2]
                    if interior.size == 0:
                        continue

                    bg = int(interior[0, 0])
                    if not np.all(interior == bg):
                        continue

                    frames.append((r, c, r2, c2, color, bg))
                    break
                break

    # Keep only maximal frames.
    maximal_frames = []
    for f in frames:
        r1, c1, r2, c2, col, bg = f
        contained = False
        for o in frames:
            if o == f:
                continue
            or1, oc1, or2, oc2, ocol, obg = o
            if or1 <= r1 and oc1 <= c1 and or2 >= r2 and oc2 >= c2:
                contained = True
                break
        if not contained:
            maximal_frames.append(f)

    # Mark frame border cells.
    frame_mask = np.zeros((h, w), dtype=bool)
    for r1, c1, r2, c2, col, bg in maximal_frames:
        frame_mask[r1, c1:c2 + 1] = True
        frame_mask[r2, c1:c2 + 1] = True
        frame_mask[r1:r2 + 1, c1] = True
        frame_mask[r1:r2 + 1, c2] = True

    # Remove every non-background pixel that is not part of a frame.
    for r in range(h):
        for c in range(w):
            if not frame_mask[r, c] and g[r, c] != 0:
                out[r, c] = 0

    # Count connected components of each color outside the frames.
    visited = np.zeros((h, w), dtype=bool)
    comp_count = {}

    for r in range(h):
        for c in range(w):
            color = int(g[r, c])
            if color == 0 or frame_mask[r, c] or visited[r, c]:
                continue

            stack = [(r, c)]
            visited[r, c] = True
            while stack:
                y, x = stack.pop()
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w:
                        if (g[ny, nx] == color and
                                not frame_mask[ny, nx] and
                                not visited[ny, nx]):
                            visited[ny, nx] = True
                            stack.append((ny, nx))

            comp_count[color] = comp_count.get(color, 0) + 1

    # For each frame, write that many marks of the frame color in the middle
    # row, starting from the rightmost odd interior columns.
    for r1, c1, r2, c2, col, bg in maximal_frames:
        count = comp_count.get(col, 0)
        count = max(0, min(4, count))

        mid_r = (r1 + r2) // 2
        cols = []
        for c in range(c2 - 1, c1, -1):
            if c % 2 == 1:
                cols.append(c)
            if len(cols) == 4:
                break

        for i in range(count):
            out[mid_r, cols[i]] = col

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # The background is the colour of the top-left cell in all provided cases.
    bg = g[0, 0]

    # The instruction row is the last row. It contains 1x5 middle-row markers
    # of colour 2 or 3.
    instr_row = h - 1

    # Find marker columns. A marker is a run of 5 equal non-background cells
    # in the last row.
    marker_cols = []
    c = 0
    while c < w:
        if g[instr_row, c] != bg:
            d = c
            while d < w and g[instr_row, d] == g[instr_row, c]:
                d += 1
            if d - c == 5:
                marker_cols.append((c + 2, int(g[instr_row, c])))
            c = d
        else:
            c += 1

    # Clear the instruction row.
    g[instr_row, :] = bg

    # Possible vertical slots for the 3-row objects.
    slot_rows = [5, 9, 13, 17, 21, 25]

    def slot_color(col_center: int, slot_top: int) -> int:
        # Check the centre cell of the 3x5 object.
        r = slot_top + 1
        c = col_center
        if 0 <= r < h and 0 <= c < w:
            return int(g[r, c])
        return bg

    def draw_object(col_center: int, slot_top: int, color: int) -> None:
        if color == bg:
            return
        # 3x5 object:
        # top:    cols center-2 .. center
        # middle: cols center-3 .. center+1
        # bottom: cols center-2 .. center
        for dr, dc0, dc1 in ((0, -2, 0), (1, -3, 1), (2, -2, 0)):
            r = slot_top + dr
            if 0 <= r < h:
                for dc in range(dc0, dc1 + 1):
                    c = col_center + dc
                    if 0 <= c < w:
                        g[r, c] = color

    for col_center, op in marker_cols:
        # Read the current vertical pattern in this column.
        pattern = [slot_color(col_center, r) for r in slot_rows]

        # Remove the original objects in this column.
        for r in slot_rows:
            draw_object(col_center, r, bg)

        if op == 2:
            # Recolour every existing object in this column to 5.
            for r, col in zip(slot_rows, pattern):
                if col != bg:
                    draw_object(col_center, r, 5)

        elif op == 3:
            # Repeat the existing vertical pattern three times, anchored at
            # the bottom, then keep only the part that fits in the grid.
            if any(col != bg for col in pattern):
                repeated = (pattern * 3)[-len(slot_rows):]
                for r, col in zip(slot_rows, repeated):
                    if col != bg:
                        draw_object(col_center, r, col)

    return g.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape
    bg = int(g[0, 0])

    # The six possible vertical positions for the 3-row objects.
    slot_tops = [5, 9, 13, 17, 21, 25]

    # Find instruction markers in the last row: runs of exactly 5 non-bg cells.
    markers = []
    c = 0
    while c < w:
        if g[h - 1, c] != bg:
            d = c
            while d < w and g[h - 1, d] == g[h - 1, c]:
                d += 1
            if d - c == 5:
                markers.append((c + 2, int(g[h - 1, c])))
            c = d
        else:
            c += 1

    # Remove the instruction row.
    g[h - 1, :] = bg

    def slot_color(center_col: int, top: int) -> int:
        r = top + 1
        c = center_col
        if 0 <= r < h and 0 <= c < w:
            return int(g[r, c])
        return bg

    def draw_object(center_col: int, top: int, color: int) -> None:
        if color == bg:
            return
        # 3x5 object:
        # top:    center-2 .. center
        # middle: center-3 .. center+1
        # bottom: center-2 .. center
        for dr, dc0, dc1 in ((0, -2, 0), (1, -3, 1), (2, -2, 0)):
            r = top + dr
            if 0 <= r < h:
                for dc in range(dc0, dc1 + 1):
                    c = center_col + dc
                    if 0 <= c < w:
                        g[r, c] = color

    for center_col, op in markers:
        # Read the current column pattern.
        pattern = [slot_color(center_col, top) for top in slot_tops]

        # Clear this column's object slots.
        for top in slot_tops:
            draw_object(center_col, top, bg)

        if op == 2:
            # Recolour every existing object in this column to 5.
            for top, col in zip(slot_tops, pattern):
                if col != bg:
                    draw_object(center_col, top, 5)

        elif op == 3:
            # Take the contiguous non-background block at the bottom of the
            # column and repeat it three times, anchored at the bottom.
            if any(col != bg for col in pattern):
                # Length of the bottom contiguous block.
                block_len = 0
                for col in reversed(pattern):
                    if col != bg:
                        block_len += 1
                    else:
                        break

                # The block colour is the colour of the bottom object.
                block_color = pattern[-1]

                # New block length is tripled, capped by the available slots.
                new_len = min(3 * block_len, len(slot_tops))

                # Draw the new block in the bottom `new_len` slots.
                for i in range(new_len):
                    top = slot_tops[-1 - i]
                    draw_object(center_col, top, block_color)

