    out = g.copy()
    for r, c, col in bottom_bars:
        out[r, c - 2:c + 3] = bg

    # For each bottom bar, apply the rule to the plus shapes in that column.
    for _, bar_c, bar_col in bottom_bars:
        # Plus shapes directly above this bar column.
        col_shapes = [(r, c, col) for (r, c, col) in plus_shapes if c == bar_c]
        if not col_shapes:
            continue

        # Remove the original plus shapes in this column.
        for r, c, col in col_shapes:
            out[r - 1, c - 1:c + 2] = bg
            out[r, c - 2:c + 3] = bg
            out[r + 1, c - 1:c + 2] = bg

        def draw_plus(r, c, col):
            out[r - 1, c - 1:c + 2] = col
            out[r, c - 2:c + 3] = col
            out[r + 1, c - 1:c + 2] = col

        if bar_col == 2:
            # Bar colour 2: recolor the column's plus shapes to 5.
            for r, c, _ in col_shapes:
                draw_plus(r, c, 5)

        elif bar_col == 3:
            # Bar colour 3: extend the column upward.
            # The number of upward steps is plus_colour + 1.
            # If the plus colour is 0, the whole column shifts up by one step.
            # Otherwise, copies are added above while keeping the original shapes.
            plus_col = col_shapes[0][2]
            rows = sorted(r for r, _, _ in col_shapes)
            top = rows[0]
            steps = plus_col + 1

            if plus_col == 0:
                new_rows = [r - 4 * steps for r in rows]
            else:
                new_rows = [top - 4 * k for k in range(1, steps + 1)] + rows

            for r in new_rows:
                if 1 <= r < h - 1:
                    draw_plus(r, bar_c, plus_col)

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
