    plus_shapes = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            col = int(g[r, c])
            if col == bg:
                continue

            if (
                g[r - 1, c - 1] == col and g[r - 1, c] == col and g[r - 1, c + 1] == col and
                g[r, c - 2] == col and g[r, c - 1] == col and g[r, c] == col and
                g[r, c + 1] == col and g[r, c + 2] == col and
                g[r + 1, c - 1] == col and g[r + 1, c] == col and g[r + 1, c + 1] == col
            ):
                plus_shapes.append((r, c, col))

    # Find and erase 5-cell command bars on the bottom row.
    bars = []
    if h > 0:
        r = h - 1
        c = 0
        while c < w:
            col = int(g[r, c])
            if col != bg:
                start = c
                while c < w and int(g[r, c]) == col:
                    c += 1
                if c - start == 5:
                    bars.append((r, start + 2, col))
                    out[r, start:c] = bg
            else:
                c += 1

    def draw_plus(r, c, col):
        if 1 <= r <= h - 2 and 1 <= c <= w - 2:
            out[r - 1, c - 1:c + 2] = col
            out[r, c - 2:c + 3] = col
            out[r + 1, c - 1:c + 2] = col

    # Group plus shapes by column.
    by_col = defaultdict(list)
    for r, c, col in plus_shapes:
        by_col[c].append((r, col))

    # Apply commands.
    for _, bar_c, bar_col in bars:
        shapes = by_col.get(bar_c, [])
        if not shapes:
            continue

        if bar_col == 2:
            # Recolor every plus shape in this column to 5.
            for r, _ in shapes:
                draw_plus(r, bar_c, 5)

        elif bar_col == 3:
            # Extend the column upward by (plus_color + 1) periods of 4 rows.
            shapes_sorted = sorted(shapes, key=lambda x: x[0])
            top_r, plus_col = shapes_sorted[0]
            steps = plus_col + 1

            for k in range(1, steps + 1):
                draw_plus(top_r - 4 * k, bar_c, plus_col)

    return out.tolist()

