def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape

    # The examples use a 7x7 macro grid of 3x3 tiles separated by 1-cell lines.
    # Detect the separator line positions from the first row/column.
    def line_positions(line):
        pos = [0]
        for i in range(1, len(line)):
            if line[i] != line[i - 1]:
                pos.append(i)
        return pos

    row_lines = line_positions(g[0])
    col_lines = line_positions(g[:, 0])

    # Macro cells are the 3x3 regions between consecutive separator lines.
    macro_r = len(row_lines) - 1
    macro_c = len(col_lines) - 1

    # Identify the normal tile pattern from the first macro cell.
    r0, r1 = row_lines[0] + 1, row_lines[1]
    c0, c1 = col_lines[0] + 1, col_lines[1]
    normal_tile = g[r0:r1, c0:c1].copy()

    # A macro cell is "special" if it differs from the normal tile.
    special = np.zeros((macro_r, macro_c), dtype=bool)
    for i in range(macro_r):
        rr0, rr1 = row_lines[i] + 1, row_lines[i + 1]
        for j in range(macro_c):
            cc0, cc1 = col_lines[j] + 1, col_lines[j + 1]
            if not np.array_equal(g[rr0:rr1, cc0:cc1], normal_tile):
                special[i, j] = True

    # Use the first special tile as the tile pattern to stamp everywhere.
    special_tile = None
    for i in range(macro_r):
        for j in range(macro_c):
            if special[i, j]:
                rr0, rr1 = row_lines[i] + 1, row_lines[i + 1]
                cc0, cc1 = col_lines[j] + 1, col_lines[j + 1]
                special_tile = g[rr0:rr1, cc0:cc1].copy()
                break
        if special_tile is not None:
            break

    # Rule inferred from examples:
    # For every horizontal run of exactly three special macro cells,
    # add special macro cells at the four diagonal corners around the run.
    out_special = special.copy()
    for i in range(macro_r):
        j = 0
        while j < macro_c:
            if special[i, j]:
                k = j
                while k + 1 < macro_c and special[i, k + 1]:
                    k += 1
                if k - j + 1 == 3:
                    for di in (-1, 1):
                        for dj in (-1, 1):
                            ni, nj = i + di, j + dj
                            if 0 <= ni < macro_r and 0 <= nj < macro_c:
                                out_special[ni, nj] = True
                            ni, nj = i + di, k + dj
                            if 0 <= ni < macro_r and 0 <= nj < macro_c:
                                out_special[ni, nj] = True
                j = k + 1
            else:
                j += 1

    # Build output: start from input, then stamp special tiles where required.
    out = g.copy()
    if special_tile is not None:
        for i in range(macro_r):
            rr0, rr1 = row_lines[i] + 1, row_lines[i + 1]
            for j in range(macro_c):
                if out_special[i, j]:
                    cc0, cc1 = col_lines[j] + 1, col_lines[j + 1]
                    out[rr0:rr1, cc0:cc1] = special_tile

    return out.tolist()

