def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape

    # The grids are 7x7 macro cells of 3x3 pixels, separated by 1-cell lines.
    # Detect the separator lines from the border colour.
    border = g[0, 0]

    def line_positions(line):
        pos = [0]
        for i in range(1, len(line)):
            if line[i] == border:
                pos.append(i)
        return pos

    row_lines = line_positions(g[0])
    col_lines = line_positions(g[:, 0])

    macro_r = len(row_lines) - 1
    macro_c = len(col_lines) - 1

    # Normal tile is the first macro cell.
    r0, r1 = row_lines[0] + 1, row_lines[1]
    c0, c1 = col_lines[0] + 1, col_lines[1]
    normal_tile = g[r0:r1, c0:c1].copy()

    # Find all special macro cells and the special tile pattern.
    special = np.zeros((macro_r, macro_c), dtype=bool)
    special_tile = None

    for i in range(macro_r):
        rr0, rr1 = row_lines[i] + 1, row_lines[i + 1]
        for j in range(macro_c):
            cc0, cc1 = col_lines[j] + 1, col_lines[j + 1]
            tile = g[rr0:rr1, cc0:cc1]
            if not np.array_equal(tile, normal_tile):
                special[i, j] = True
                if special_tile is None:
                    special_tile = tile.copy()

    if special_tile is None:
        return g.tolist()

    # The 3x3 special tile encodes the target 3x3 macro pattern:
    # a pixel is "on" if it differs from the normal tile.
    mask = (special_tile != normal_tile).astype(int)

    # For every 3x3 macro block, if the input special cells are a non-empty
    # subset of the encoded mask, complete the block to the full mask.
    out_special = special.copy()

    for i in range(macro_r - 2):
        for j in range(macro_c - 2):
            block = special[i:i + 3, j:j + 3]
            if not block.any():
                continue

            # The block must be explainable as a partial version of the mask.
            if np.all(block <= mask):
                out_special[i:i + 3, j:j + 3] |= (mask == 1)

    # Build the output grid.
    out = g.copy()
    for i in range(macro_r):
        rr0, rr1 = row_lines[i] + 1, row_lines[i + 1]
        for j in range(macro_c):
            if out_special[i, j]:
                cc0, cc1 = col_lines[j] + 1, col_lines[j + 1]
                out[rr0:rr1, cc0:cc1] = special_tile

    return out.tolist()

