    comp_id = -np.ones((h, w), dtype=int)
    comps = []
    for r in range(h):
        for c in range(w):
            if a[r, c] == FG and comp_id[r, c] == -1:
                cid = len(comps)
                q = deque([(r, c)])
                comp_id[r, c] = cid
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w:
                            if a[ny, nx] == FG and comp_id[ny, nx] == -1:
                                comp_id[ny, nx] = cid
                                q.append((ny, nx))
                comps.append(cells)

    # 2) Find background regions (4s) using 4-connectivity.
    #    A background region that does not touch the border is a hole.
    bg_id = -np.ones((h, w), dtype=int)
    holes = []
    for r in range(h):
        for c in range(w):
            if a[r, c] == BG and bg_id[r, c] == -1:
                rid = len(holes)
                q = deque([(r, c)])
                bg_id[r, c] = rid
                touches_border = (r == 0 or c == 0 or r == h - 1 or c == w - 1)
                while q:
                    y, x = q.popleft()
                    if y == 0 or x == 0 or y == h - 1 or x == w - 1:
                        touches_border = True
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w:
                            if a[ny, nx] == BG and bg_id[ny, nx] == -1:
                                bg_id[ny, nx] = rid
                                q.append((ny, nx))
                holes.append(touches_border)

    # 3) A component is "hollow" if it borders at least one enclosed background region.
    hollow = [False] * len(comps)
    for r in range(h):
