            if a[r, c] == BG and not holes[bg_id[r, c]]:
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = r + dy, c + dx
                    if 0 <= ny < h and 0 <= nx < w and a[ny, nx] == FG:
                        hollow[comp_id[ny, nx]] = True

    # 4) Build output.
    out = np.full((h, w), BG, dtype=int)

    # Original object pixels: 8 if its component is hollow, otherwise 1.
    for cid, cells in enumerate(comps):
        val = 8 if hollow[cid] else 1
        for y, x in cells:
            out[y, x] = val

    # Enclosed background pixels become 6.
    for r in range(h):
        for c in range(w):
            if a[r, c] == BG and not holes[bg_id[r, c]]:
                out[r, c] = 6

    # 2-pixel outline: every background pixel 8-adjacent to an original 1.
    for r in range(h):
