            for cc in range(visited.shape[1]):
                if not visited[rr, cc] and (rr + min_r, cc + min_c) not in cell_set:
                    holes.add((rr + min_r, cc + min_c))
        return holes

    for cells in components:
        cell_set = set(cells)
        holes = component_holes(cells)
        has_hole = len(holes) > 0

        # 8-neighbor border of the original component.
        border = set()
        for r, c in cells:
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w:
                        border.add((nr, nc))

        # Body color: 8 if the component encloses a hole, otherwise keep 1.
        body_color = 8 if has_hole else 1

        # Draw border first, then body/holes so they take priority.
        for r, c in border:
            if out[r, c] == 4:
                out[r, c] = 2

        for r, c in cells:
            out[r, c] = body_color

        for r, c in holes:
            out[r, c] = 6

    return out.tolist()

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Split into blocks using full separator lines of 1s.
    row_seps = [i for i in range(h) if np.all(g[i] == 1)]
    if row_seps:
        bounds = [0] + row_seps + [h]
        blocks = []
        for a, b in zip(bounds[:-1], bounds[1:]):
            if b > a:
                blocks.append(g[a:b, :])
    else:
        col_seps = [j for j in range(w) if np.all(g[:, j] == 1)]
        bounds = [0] + col_seps + [w]
        blocks = []
        for a, b in zip(bounds[:-1], bounds[1:]):
            if b > a:
                blocks.append(g[:, a:b])

    # First block is the 4-pattern.
    p4 = blocks[0]

    # Collect solid colors from the remaining blocks.
    colors = []
    for block in blocks[1:]:
        vals = np.unique(block)
        vals = vals[vals != 0]
        if len(vals) == 1:
            c = int(vals[0])
            if c not in colors:
                colors.append(c)

    # Fallback if something unexpected happens.
    if len(colors) < 2:
        all_vals = np.unique(g)
        all_vals = all_vals[(all_vals != 0) & (all_vals != 1)]
        for c in all_vals:
            c = int(c)
            if c not in colors:
                colors.append(c)
        if len(colors) < 2:
            colors = [2, 8]

    color1 = colors[0]
    color2 = colors[1]

    # Binary pattern from 4s.
    pat = (p4 == 4).astype(int)

    # Remove one zero border if present.
    if pat.shape[0] >= 2 and pat.shape[1] >= 2:
        if not np.any(pat[0]) and not np.any(pat[-1]) and not np.any(pat[:, 0]) and not np.any(pat[:, -1]):
            pat = pat[1:-1, 1:-1]

    # If still empty, use tight bounding box.
    if not np.any(pat):
        return [[color2] * w for _ in range(h)]

    rows = np.any(pat != 0, axis=1)
    cols = np.any(pat != 0, axis=0)
    r0, r1 = np.where(rows)[0][[0, -1]]
    c0, c1 = np.where(cols)[0][[0, -1]]
    pat = pat[r0:r1 + 1, c0:c1 + 1]

    ph, pw = pat.shape

    # Repeat pattern ph times horizontally with one zero column between copies.
    out = []
    for i in range(ph):
        row = []
        for rep in range(ph):
            if rep > 0:
                row.append(0)
            row.extend(pat[i].tolist())
        out.append(row)

    out_arr = np.array(out, dtype=int)
    result = np.where(out_arr == 1, color1, color2).astype(int)
    return result.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape
    bg = int(g[0, 0])

    # Detect 3x5 blocks.
    blocks = []
    for r in range(1, h - 1):
        for c in range(2, w - 2):
            col = int(g[r, c])
            if col == bg:
                continue
            if (
                g[r - 1, c - 1] == col and g[r - 1, c] == col and g[r - 1, c + 1] == col
                and g[r, c - 2] == col and g[r, c - 1] == col and g[r, c] == col
                and g[r, c + 1] == col and g[r, c + 2] == col
                and g[r + 1, c - 1] == col and g[r + 1, c] == col and g[r + 1, c + 1] == col
            ):
                blocks.append((r, c, col))

    if not blocks:
        return [[int(x) for x in row] for row in g]

    # Detect 1x5 command bars, excluding block middle rows.
    bars = []
    for r in range(h):
        c = 0
        while c < w:
            if g[r, c] != bg:
                c2 = c
                while c2 < w and g[r, c2] == g[r, c]:
                    c2 += 1
                if c2 - c == 5:
                    center = (c + c2 - 1) // 2
                    col = int(g[r, c])
                    is_block_middle = False
                    if 0 < r < h - 1:
                        is_block_middle = (
                            g[r - 1, center - 1] == col
                            and g[r - 1, center] == col
                            and g[r - 1, center + 1] == col
                            and g[r + 1, center - 1] == col
                            and g[r + 1, center] == col
                            and g[r + 1, center + 1] == col
                        )
                    if not is_block_middle:
                        bars.append((r, center, col))
                c = c2
            else:
                c += 1

    # Infer the regular vertical spacing of block rows.
    row_centers = sorted({r for r, _, _ in blocks})
    if len(row_centers) >= 2:
        spacing = min(row_centers[i + 1] - row_centers[i] for i in range(len(row_centers) - 1))
    else:
        spacing = 4

    bottom_row = max(row_centers)

    def same_col(c1, c2):
        return abs(c1 - c2) <= 1

    def occupied_in_col(c, r):
        return any(same_col(bc, c) and abs(br - r) <= 1 for br, bc, _ in blocks)

    # Apply command 3:
    # copy the lowest block in the column to row 3 from the bottom;
    # if that row is occupied, use row 4 from the bottom.
    for _, bc, bcol in bars:
        if bcol != 3:
            continue

        src = None
        for br, bc2, bcolor in blocks:
            if same_col(bc2, bc):
                if src is None or br > src[0]:
                    src = (br, bc2, bcolor)

        if src is None:
            continue

        target_r = bottom_row - 2 * spacing
        if target_r < 1:
            continue
        if occupied_in_col(bc, target_r):
            target_r -= spacing
            if target_r < 1:
                continue

        blocks.append((target_r, bc, src[2]))

    # Apply command 2:
    # recolor every block in the column to 5.
    new_blocks = []
    for br, bc, bcol in blocks:
        for _, bar_c, bar_col in bars:
            if bar_col == 2 and same_col(bar_c, bc):
                bcol = 5
                break
        new_blocks.append((br, bc, bcol))

    # Rebuild output.
    out = np.full((h, w), bg, dtype=int)
    for r, c, col in new_blocks:
        for dr, dc in [
            (-1, -1), (-1, 0), (-1, 1),
            (0, -2), (0, -1), (0, 0), (0, 1), (0, 2),
            (1, -1), (1, 0), (1, 1),
        ]:
            rr, cc = r + dr, c + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr, cc] = col

    return [[int(x) for x in row] for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Find all 3x3 "objects": a center with four orthogonal neighbours
    # of the same non-zero colour.  Corners may be the same colour or 0.
    objects = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            center = g[r, c]
            if center == 0:
                continue
            arms = [g[r - 1, c], g[r + 1, c], g[r, c - 1], g[r, c + 1]]
            if all(a == arms[0] and a != 0 for a in arms):
                frame = arms[0]
                objects.append((r, c, frame, center))

    if not objects:
        return out.tolist()

    # Build a graph over object colours:
    # edge frame -> center for every object.
    edges = {}
    for _, _, frame, center in objects:
        edges.setdefault(frame, center)

    # Keep an object if its center colour is the frame colour of another object.
    # Its center is replaced by the center of that other object.
    # All other objects are erased.
    for r, c, frame, center in objects:
        if center in edges:
            out[r, c] = edges[center]
        else:
            # Erase the 3x3 bounding box of the object.
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    rr, cc = r + dr, c + dc
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr, cc] = 0

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Detect "cross" objects:
    # a non-zero center whose four orthogonal neighbours are all the same
    # non-zero colour, different from the center colour.
    objects = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            center = g[r, c]
            if center == 0:
                continue
            up = g[r - 1, c]
            down = g[r + 1, c]
            left = g[r, c - 1]
            right = g[r, c + 1]
            if (
                up != 0
                and up == down == left == right
                and up != center
            ):
                objects.append((r, c, up, center))

    if not objects:
        return out.tolist()

    # Map frame colour -> object.  In the supplied puzzles frame colours are
    # unique; if not, keep the first occurrence.
    frame_to_obj = {}
    for obj in objects:
        frame = obj[2]
        if frame not in frame_to_obj:
            frame_to_obj[frame] = obj

    center_colors = {obj[3] for obj in objects}

    # Build chains: object A points to object B if A.center == B.frame.
    next_obj = {}
    for obj in objects:
        center = obj[3]
        if center in frame_to_obj:
            next_obj[obj] = frame_to_obj[center]

    # Sources are objects whose frame colour is not used as a center colour.
    visited = set()
    chains = []

    for obj in objects:
        if obj in visited:
            continue
        if obj[2] in center_colors:
            continue

        chain = []
        cur = obj
        while cur is not None and cur not in visited:
            visited.add(cur)
            chain.append(cur)
            cur = next_obj.get(cur)

        if chain:
            chains.append(chain)

    # Fallback for any unvisited objects (e.g. cycles): leave them unchanged.
    # The given examples/tests do not contain cycles.

    # Apply the chain rule:
    # - keep objects at even positions if they have a next object;
    # - recolor their center with the center colour of the next object;
    # - erase all other objects in the chain.
    def erase(obj):
        r, c, frame, center = obj
        for rr, cc in ((r, c), (r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if 0 <= rr < h and 0 <= cc < w:
                out[rr, cc] = 0

    for chain in chains:
        for i, obj in enumerate(chain):
            if i % 2 == 0 and i + 1 < len(chain):
                # Keep this object and copy the next object's center colour.
                out[obj[0], obj[1]] = chain[i + 1][3]
            else:
                erase(obj)

    return out.tolist()

