    h = len(grid)
    w = len(grid[0])
    out = [row[:] for row in grid]

    # Locate the 3x3 target: 3s with a 2 in the center.
    center = None
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 2:
                ok = True
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        if dr == 0 and dc == 0:
                            continue
                        if grid[r + dr][c + dc] != 3:
                            ok = False
                            break
                    if not ok:
                        break
                if ok:
                    center = (r, c)
                    break
        if center:
            break

    if center is None:
        return out

    cr, cc = center

    # The 9 cells of the target, in a fixed order.
    target_cells = [
        (cr - 1, cc - 1), (cr - 1, cc), (cr - 1, cc + 1),
        (cr, cc - 1), (cr, cc), (cr, cc + 1),
        (cr + 1, cc - 1), (cr + 1, cc), (cr + 1, cc + 1),
    ]

    # All 9s outside the target.
    sources = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 9 and (r, c) not in target_cells:
                sources.append((r, c))

    # For each target cell, choose the nearest source 9.
    # Ties are broken by the fixed target order, then source order.
    used = set()
    for tr, tc in target_cells:
        best = None
        best_key = None
        for idx, (sr, sc) in enumerate(sources):
            if idx in used:
                continue
            d = abs(sr - tr) + abs(sc - tc)
            key = (d, idx)
            if best_key is None or key < best_key:
                best_key = key
                best = idx
        if best is not None:
            used.add(best)
            out[tr][tc] = 9
            sr, sc = sources[best]
            out[sr][sc] = 7

    return out

