def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # 8-connected components of 1s
    seen = np.zeros((h, w), dtype=bool)
    comps = []
    for r in range(h):
        for c in range(w):
            if g[r, c] == 1 and not seen[r, c]:
                q = deque([(r, c)])
                seen[r, c] = True
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < h and 0 <= nx < w and not seen[ny, nx] and g[ny, nx] == 1:
                                seen[ny, nx] = True
                                q.append((ny, nx))
                comps.append(cells)

    # Background components (4-connected)
    bg_seen = np.zeros((h, w), dtype=bool)
    bg_comps = []
    for r in range(h):
        for c in range(w):
            if g[r, c] == 4 and not bg_seen[r, c]:
                q = deque([(r, c)])
                bg_seen[r, c] = True
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy, dx in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and not bg_seen[ny, nx] and g[ny, nx] == 4:
                            bg_seen[ny, nx] = True
                            q.append((ny, nx))
                bg_comps.append(cells)

    # Outside background is any background component touching the border
    outside = set()
    for cells in bg_comps:
        if any(y == 0 or y == h - 1 or x == 0 or x == w - 1 for y, x in cells):
            outside.update(cells)

    # For each 1-component, find enclosed background holes (4-connected, not outside)
    for cells in comps:
        comp_set = set(cells)
        # background cells adjacent (8-neighbor) to this component
        adj_bg = set()
        for y, x in comp_set:
            for dy in (-1, 0, 1):
                for dx in (-1, 0, 1):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and g[ny, nx] == 4:
                        adj_bg.add((ny, nx))

        # flood-fill background from adjacent cells that are outside
        visited = set()
        q = deque([p for p in adj_bg if p in outside])
        for p in q:
            visited.add(p)
        while q:
            y, x = q.popleft()
            for dy, dx in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                ny, nx = y + dy, x + dx
                if (ny, nx) in adj_bg and (ny, nx) not in visited:
                    visited.add((ny, nx))
                    q.append((ny, nx))

        holes = adj_bg - visited
        if holes:
            # 2 = outer boundary of the 1-component (component cells adjacent to outside)
            for y, x in comp_set:
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and (ny, nx) in outside:
                            out[y, x] = 2
                            break
                    else:
                        continue
                    break

            # 8 = component cells not on outer boundary
            for y, x in comp_set:
                if out[y, x] != 2:
                    out[y, x] = 8

            # 6 = enclosed background holes
            for y, x in holes:
                out[y, x] = 6

    # Components without holes: draw a one-cell 8-neighbor outline in 2, keep 1s inside
    for cells in comps:
        comp_set = set(cells)
        # If this component already got 8/6 treatment, skip
        if any(out[y, x] in (6, 8) for y, x in comp_set):
            continue

        for y, x in comp_set:
            for dy in (-1, 0, 1):
                for dx in (-1, 0, 1):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in comp_set:
                        out[ny, nx] = 2

    return out.tolist()

