import numpy as np
from math import gcd

def _line_cells(p, q):
    r1, c1 = p
    r2, c2 = q
    cells = set()
    dr = r2 - r1
    dc = c2 - c1
    g = gcd(abs(dr), abs(dc))
    if g == 0:
        return {(r1, c1)}
    sr = dr // g
    sc = dc // g
    for i in range(g + 1):
        cells.add((r1 + i * sr, c1 + i * sc))
    return cells

def _perp_line(p, h, w):
    r, c = p
    cells = set()
    for dr, dc in ((1, 1), (1, -1)):
        rr, cc = r, c
        while 0 <= rr < h and 0 <= cc < w:
            cells.add((rr, cc))
