from math import gcd

def _segment_cells(p, q):
    r1, c1 = p
    r2, c2 = q
    dr = r2 - r1
    dc = c2 - c1
    g = gcd(abs(dr), abs(dc))
    if g == 0:
        return {(r1, c1)}
    sr = dr // g
    sc = dc // g
    return {(r1 + i * sr, c1 + i * sc) for i in range(g + 1)}

def _perp_border_cells(p, direction, h, w):
    r, c = p
    dr, dc = direction
    cells = set()
    rr, cc = r, c
    while 0 <= rr < h and 0 <= cc < w:
        cells.add((rr, cc))
        rr += dr
        cc += dc
    return cells

