    out = a.copy()

    # Draw all straight segments between pairs of 1s.
    one_segments = []
    for i in range(len(ones)):
        for j in range(i + 1, len(ones)):
            cells = _segment_cells(ones[i], ones[j])
            one_segments.append((ones[i], ones[j], cells))
            for (r, c) in cells:
                out[r, c] = 1

    # For every 6 lying on a 1-segment, draw the perpendicular line through it.
    for s in sixes:
        for p, q, cells in one_segments:
            if s in cells:
                dr = q[0] - p[0]
                dc = q[1] - p[1]
                g = gcd(abs(dr), abs(dc))
                if g == 0:
                    continue
                sr = dr // g
                sc = dc // g

                # Perpendicular directions to (sr, sc).
                for pr, pc in ((-sc, sr), (sc, -sr)):
                    for (r, c) in _perp_border_cells(s, (pr, pc), h, w):
                        out[r, c] = 6

    # Preserve original 6 pixels.
    for (r, c) in sixes:
        out[r, c] = 6

    return out.tolist()

