import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Background is the most common colour (also the border colour in these tasks).
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # Collect all 1s.
    ones = [(r, c) for r in range(h) for c in range(w) if g[r, c] == 1]

    # For each diagonal direction, if there are at least two 1s on it,
    # fill the segment between the extreme 1s with 1s.
    # Do not overwrite existing 6s.
    def fill_segment(p1, p2, color):
        r1, c1 = p1
        r2, c2 = p2
        dr = 0 if r1 == r2 else (1 if r2 > r1 else -1)
        dc = 0 if c1 == c2 else (1 if c2 > c1 else -1)
        r, c = r1, c1
        while True:
            if out[r, c] != 6:
                out[r, c] = color
            if (r, c) == (r2, c2):
                break
            r += dr
            c += dc

    # Main diagonals: r - c constant
    by_main = {}
    for r, c in ones:
        by_main.setdefault(r - c, []).append((r, c))
    for pts in by_main.values():
        if len(pts) >= 2:
            pts.sort()
            fill_segment(pts[0], pts[-1], 1)

    # Anti-diagonals: r + c constant
    by_anti = {}
    for r, c in ones:
        by_anti.setdefault(r + c, []).append((r, c))
    for pts in by_anti.values():
        if len(pts) >= 2:
            pts.sort()
            fill_segment(pts[0], pts[-1], 1)

    # For every 6 that lies on a drawn 1-segment, draw the full perpendicular
    # diagonal through it with 6s.  Existing 1s are preserved.
    def fill_perp(r0, c0):
        # If the 6 is on a main diagonal (r-c constant), perpendicular is anti-diagonal.
        # If it is on an anti-diagonal (r+c constant), perpendicular is main diagonal.
        # In practice a 6 can be on both; draw both perpendiculars only if needed.
        # We determine which 1-lines actually pass through it.
        on_main = False
        on_anti = False

        # Check main diagonal segment containing this 6.
        key = r0 - c0
        pts = by_main.get(key, [])
        if len(pts) >= 2:
            pts.sort()
            r1, c1 = pts[0]
            r2, c2 = pts[-1]
            if min(r1, r2) <= r0 <= max(r1, r2) and min(c1, c2) <= c0 <= max(c1, c2):
                on_main = True

        # Check anti-diagonal segment containing this 6.
        key = r0 + c0
        pts = by_anti.get(key, [])
        if len(pts) >= 2:
            pts.sort()
            r1, c1 = pts[0]
            r2, c2 = pts[-1]
            if min(r1, r2) <= r0 <= max(r1, r2) and min(c1, c2) <= c0 <= max(c1, c2):
                on_anti = True

        if on_main:
            # perpendicular: anti-diagonal r + c = const
            s = r0 + c0
            r = max(0, s - (w - 1))
            c = s - r
            while r < h and c < w:
                if out[r, c] != 1:
                    out[r, c] = 6
                r += 1
                c -= 1

        if on_anti:
            # perpendicular: main diagonal r - c = const
            d = r0 - c0
            if d >= 0:
                r, c = d, 0
            else:
                r, c = 0, -d
            while r < h and c < w:
                if out[r, c] != 1:
                    out[r, c] = 6
                r += 1
                c += 1

    for r in range(h):
        for c in range(w):
            if g[r, c] == 6:
                fill_perp(r, c)

    return out.tolist()

