def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Collect all 1s.
    ones = [(r, c) for r in range(h) for c in range(w) if g[r, c] == 1]

    def fill_segment(p1, p2, color):
        r1, c1 = p1
        r2, c2 = p2
        dr = 0 if r1 == r2 else (1 if r2 > r1 else -1)
        dc = 0 if c1 == c2 else (1 if c2 > c1 else -1)
        r, c = r1, c1
        while True:
            if out[r, c] != 6:
                out[r, c] = color
            if (r, c) == (r2, c2):
                break
            r += dr
            c += dc

    # Connect 1s that lie on the same main diagonal (r - c constant).
    by_main = {}
    for r, c in ones:
        by_main.setdefault(r - c, []).append((r, c))

    for pts in by_main.values():
        if len(pts) >= 2:
            pts.sort()
            fill_segment(pts[0], pts[-1], 1)

    # Connect 1s that lie on the same anti-diagonal (r + c constant).
    by_anti = {}
    for r, c in ones:
        by_anti.setdefault(r + c, []).append((r, c))

    for pts in by_anti.values():
        if len(pts) >= 2:
            pts.sort()
            fill_segment(pts[0], pts[-1], 1)

    # For every original 6 that lies on a drawn 1-segment, draw the full
    # perpendicular diagonal through it with 6s. Existing 1s are preserved.
    def on_main_segment(r0, c0):
        pts = by_main.get(r0 - c0, [])
        if len(pts) < 2:
            return False
        pts.sort()
        r1, c1 = pts[0]
        r2, c2 = pts[-1]
        return min(r1, r2) <= r0 <= max(r1, r2) and min(c1, c2) <= c0 <= max(c1, c2)

    def on_anti_segment(r0, c0):
        pts = by_anti.get(r0 + c0, [])
        if len(pts) < 2:
            return False
        pts.sort()
        r1, c1 = pts[0]
        r2, c2 = pts[-1]
        return min(r1, r2) <= r0 <= max(r1, r2) and min(c1, c2) <= c0 <= max(c1, c2)

    for r in range(h):
        for c in range(w):
            if g[r, c] != 6:
                continue

            if on_main_segment(r, c):
                # Perpendicular to main diagonal is anti-diagonal: r + c = const.
                s = r + c
                rr = max(0, s - (w - 1))
                cc = s - rr
                while rr < h and cc < w:
                    if out[rr, cc] != 1:
                        out[rr, cc] = 6
                    rr += 1
                    cc -= 1

            if on_anti_segment(r, c):
                # Perpendicular to anti-diagonal is main diagonal: r - c = const.
                d = r - c
                if d >= 0:
                    rr, cc = d, 0
                else:
                    rr, cc = 0, -d
                while rr < h and cc < w:
                    if out[rr, cc] != 1:
                        out[rr, cc] = 6
                    rr += 1
                    cc += 1

    return out.tolist()

