    # Locate the 3x3 target block containing the central 2.
    center = None
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2:
                center = (r, c)
                break
        if center is not None:
            break

    if center is None:
        return [row[:] for row in grid]

    cr, cc = center
    r0, c0 = cr - 1, cc - 1

    # Count 9s that are not part of the top-right "safe" cluster.
    # The safe cluster is the connected component of 9s that touches
    # the top row and the rightmost column.
    safe = set()
    stack = []
    for c in range(w):
        if grid[0][c] == 9:
            stack.append((0, c))
    for r in range(h):
        if grid[r][w - 1] == 9:
            stack.append((r, w - 1))

    while stack:
        r, c = stack.pop()
        if (r, c) in safe or grid[r][c] != 9:
            continue
        safe.add((r, c))
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 9:
                stack.append((nr, nc))

    count = 0
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 9 and (r, c) not in safe:
                count += 1

    out = [row[:] for row in grid]

    # Remove the counted 9s.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 9 and (r, c) not in safe:
                out[r][c] = 7

    # Fill the 3x3 block row-major with 9s, up to the counted amount.
    filled = 0
    for dr in range(3):
        for dc in range(3):
            if filled >= count:
                break
            out[r0 + dr][c0 + dc] = 9
            filled += 1

    return out

