def transform(grid: list[list[int]]) -> list[list[int]]:
    # The 6x6 input is a 6x6 set of grid-line intersections.
    # The 16x16 output is a 5x5 lattice of 3x3 cells:
    #   intersections are at coordinates 0, 3, 6, 9, 12, 15.
    #
    # For every input cell:
    #   - if it is not 7, the corresponding intersection in the output is 9.
    #   - if it is 7, the intersection is 0.
    #
    # The four diagonal neighbours of a non-7 input cell are "activated".
    # For each activated diagonal neighbour, the 3x3 cell between the two
    # intersections is filled with 9.  All other cells are 0.
    #
    # The 7s are the lattice lines:
    #   - vertical line segments are drawn when the two adjacent input
    #     intersections in the same column are both 7.
    #   - horizontal line segments are drawn when the two adjacent input
    #     intersections in the same row are both 7.
    # Intersections themselves are never 7.

    n = len(grid)
    m = len(grid[0])
    out = [[0] * (3 * (m - 1) + 1) for _ in range(3 * (n - 1) + 1)]

    # Intersections.
    for i in range(n):
        for j in range(m):
            if grid[i][j] != 7:
                out[3 * i][3 * j] = 9

    # Fill 3x3 cells activated by diagonal neighbours of non-7 cells.
    for i in range(n):
        for j in range(m):
            if grid[i][j] != 7:
                for di, dj in ((-1, -1), (-1, 1), (1, -1), (1, 1)):
                    ni, nj = i + di, j + dj
                    if 0 <= ni < n and 0 <= nj < m:
                        r0 = 3 * min(i, ni) + 1
                        c0 = 3 * min(j, nj) + 1
                        for r in range(r0, r0 + 3):
                            for c in range(c0, c0 + 3):
                                out[r][c] = 9

    # Vertical lattice segments: between rows i and i+1 in column j.
    for i in range(n - 1):
        for j in range(m):
            if grid[i][j] == 7 and grid[i + 1][j] == 7:
                r0 = 3 * i + 1
                for r in range(r0, r0 + 3):
                    out[r][3 * j] = 7

    # Horizontal lattice segments: between columns j and j+1 in row i.
    for i in range(n):
        for j in range(m - 1):
            if grid[i][j] == 7 and grid[i][j + 1] == 7:
                c0 = 3 * j + 1
                for c in range(c0, c0 + 3):
                    out[3 * i][c] = 7

    return out

