                if abs(r1 - r2) != abs(c1 - c2):
                    continue
                # The 1-segment is diagonal.  A point (r,c) is on it iff
                # it has the same diagonal invariant and lies between endpoints.
                if r1 == r2:
                    continue
                if c1 == c2:
                    continue
                if (r1 - c1) == (r - c) and (r2 - c2) == (r - c):
                    if min(r1, r2) <= r <= max(r1, r2) and min(c1, c2) <= c <= max(c1, c2):
                        on_one_segment = True
                        break
            if on_one_segment:
                break

        if not on_one_segment:
            continue

        # The 1-segment through this 6 has slope +1, so perpendicular is slope -1.
        # If the 1-segment had slope -1, perpendicular is slope +1.
        # Determine the slope of the 1-segment containing this 6.
        slope_plus = False
        for i in range(len(ones)):
            r1, c1 = ones[i]
            for j in range(i + 1, len(ones)):
                r2, c2 = ones[j]
                if abs(r1 - r2) != abs(c1 - c2):
                    continue
                if (r1 - c1) == (r - c) and (r2 - c2) == (r - c):
                    if min(r1, r2) <= r <= max(r1, r2) and min(c1, c2) <= c <= max(c1, c2):
                        slope_plus = True
                        break
            if slope_plus:
                break

        if slope_plus:
            # Perpendicular: r + c constant.
            s = r + c
            for rr in range(h):
                cc = s - rr
                if 0 <= cc < w:
                    out[rr, cc] = 6
        else:
            # Perpendicular: r - c constant.
            d = r - c
            for rr in range(h):
                cc = rr - d
                if 0 <= cc < w:
                    out[rr, cc] = 6

    return out.tolist()

