    # regular grid origin. Otherwise infer the origin from the first marker.
    if len(markers) >= 2:
        rows = sorted({r for r, _, _ in markers})
        cols = sorted({c for _, c, _ in markers})
        regular = False
        if len(rows) > 1 and len(cols) > 1:
