                          all((c - cols[0]) % dc == 0 for c in cols)
        if regular:
            origin_r, origin_c = rows[0], cols[0]
        else:
            origin_r, origin_c = markers[0][0], markers[0][1]
    else:
        origin_r, origin_c = (markers[0][0], markers[0][1]) if markers else (0, 0)

    # Draw patterns. Later markers overwrite earlier ones if they overlap.
