    for r, c in cells:
        rr = r - rmin
        cc = c - cmin
        if 0 <= rr < 3 and 0 <= cc < 3:
            shape[rr][cc] = 1

    # Build the 16x16 background.
    # The 3x3 background tile is the shape shifted up-left by one cell
    # (with wrap-around): a 0 appears where the shifted shape has a 1.
    out = [[0] * 16 for _ in range(16)]
    for r in range(16):
        for c in range(16):
            if shape[(r + 1) % 3][(c + 1) % 3] == 1:
                out[r][c] = 0
            else:
                out[r][c] = 7

    # Overlay the 3x3 shape, repeated 2x2, in the central 6x6 area.
    # The central area starts at row 5, column 5.
    for r in range(5, 11):
        for c in range(5, 11):
            if shape[(r - 5) % 3][(c - 5) % 3] == 1:
                out[r][c] = 9

    return out

