def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = np.zeros((h, w), dtype=int)

    # Find 3x3 "boxes": the four edge-centres are the same non-zero colour,
    # and the centre is a different non-zero colour.
    boxes = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            frame = g[r - 1, c]
            if frame == 0:
                continue
            if (g[r + 1, c] == frame and
                g[r, c - 1] == frame and
                g[r, c + 1] == frame):
                center = g[r, c]
                if center != 0 and center != frame:
                    boxes.append((r, c, frame, center))

    # Keep all 5s.
    out[g == 5] = 5

    if not boxes:
        return out.tolist()

    # Build a graph of boxes.  Two boxes are connected if their 3x3
    # neighbourhoods are close enough to be linked by a short 5-path.
    n = len(boxes)
    adj = [set() for _ in range(n)]

    def box_cells(i):
        r, c, _, _ = boxes[i]
        cells = set()
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w:
                    cells.add((rr, cc))
        return cells

    def five_reachable(a, b, limit=4):
        # BFS through 5-cells from a to b, allowing at most `limit`
        # non-5 steps (the box cells themselves).
        start = (a[0], a[1])
        target = (b[0], b[1])
        if start == target:
            return True
        seen = {start: 0}
        stack = [start]
        while stack:
            x, y = stack.pop()
            cost = seen[(x, y)]
            if cost >= limit:
                continue
            for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nx, ny = x + dx, y + dy
                if 0 <= nx < h and 0 <= ny < w:
                    ncost = cost + (0 if g[nx, ny] == 5 else 1)
                    if ncost <= limit and (nx, ny) not in seen:
                        seen[(nx, ny)] = ncost
                        if (nx, ny) == target:
                            return True
                        stack.append((nx, ny))
        return False

    for i in range(n):
        for j in range(i + 1, n):
            ri, ci, _, _ = boxes[i]
            rj, cj, _, _ = boxes[j]
            # Only consider boxes that are reasonably close.
            if abs(ri - rj) > 5 or abs(ci - cj) > 5:
                continue
            # Direct adjacency of their 3x3 areas.
            cells_i = box_cells(i)
            cells_j = box_cells(j)
            if cells_i & cells_j:
                adj[i].add(j)
                adj[j].add(i)
                continue
            # Otherwise require a short path through 5s.
            if five_reachable((ri, ci), (rj, cj), limit=4):
                adj[i].add(j)
                adj[j].add(i)

    # Connected components of boxes.
    comp = [-1] * n
    cid = 0
    for i in range(n):
        if comp[i] != -1:
            continue
        stack = [i]
        comp[i] = cid
        while stack:
            x = stack.pop()
            for y in adj[x]:
                if comp[y] == -1:
                    comp[y] = cid
                    stack.append(y)
        cid += 1

    # In each component, the two boxes with the largest centre values are
    # the active boxes; they exchange centre colours.  All other boxes are
    # erased.
    active = set()
    new_center = {}
    for k in range(cid):
        members = [i for i in range(n) if comp[i] == k]
        if len(members) < 2:
            continue
        # Sort by centre value descending; ties broken by position for determinism.
        members.sort(key=lambda i: (boxes[i][3], boxes[i][0], boxes[i][1]), reverse=True)
        a, b = members[0], members[1]
        active.add(a)
        active.add(b)
        new_center[a] = boxes[b][3]
        new_center[b] = boxes[a][3]

    # Draw active boxes.
    for i in active:
        r, c, frame, _ = boxes[i]
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w:
                    if dr == 0 and dc == 0:
                        out[rr, cc] = new_center[i]
                    else:
                        # Keep the frame colour on the full 3x3 square.
                        out[rr, cc] = frame

    return out.tolist()

