                q = deque([(r, c)])
                comp5[r, c] = comp_id
                while q:
                    x, y = q.popleft()
                    for dx in (-1, 0, 1):
                        for dy in (-1, 0, 1):
                            if dx == 0 and dy == 0:
                                continue
                            nx, ny = x + dx, y + dy
                            if 0 <= nx < h and 0 <= ny < w:
                                if g[nx, ny] == 5 and comp5[nx, ny] == -1:
                                    comp5[nx, ny] = comp_id
                                    q.append((nx, ny))
                comp_id += 1

    # For each box, find the 5-component(s) touching its 3x3 area.
    box_5comps = [set() for _ in range(n)]
    for i, (r, c, _, _) in enumerate(boxes):
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w:
                    if g[rr, cc] == 5:
                        box_5comps[i].add(comp5[rr, cc])

    # Union boxes sharing a 5-component.
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[rb] = ra

    for i in range(n):
        for j in range(i + 1, n):
            if box_5comps[i] & box_5comps[j]:
                union(i, j)

    # Directed links: box A can send its centre to box B if A's frame colour
    # equals B's centre colour and they are in the same 5-connected component.
    links = []
    for i in range(n):
        for j in range(n):
            if i == j:
                continue
            if find(i) != find(j):
                continue
            if boxes[i][2] == boxes[j][3]:
                links.append((i, j))

    # In each connected component, follow the directed links.  The boxes that
    # are final targets of a chain keep their frame and receive the centre of
    # the box that sent to them.  All other boxes are erased.
    indeg = [0] * n
    outdeg = [0] * n
    sender = [-1] * n
    for i, j in links:
        outdeg[i] += 1
        indeg[j] += 1
        sender[j] = i

    # Keep sinks (indegree > 0, outdegree == 0).  If a component has no sink,
    # keep the node with maximum indegree as a fallback.
    keep = [False] * n
    new_center = [None] * n

    comps = {}
    for i in range(n):
        comps.setdefault(find(i), []).append(i)

    for nodes in comps.values():
        sinks = [i for i in nodes if indeg[i] > 0 and outdeg[i] == 0]
        if sinks:
            for i in sinks:
                keep[i] = True
                if sender[i] != -1:
                    new_center[i] = boxes[sender[i]][3]
        else:
            # Fallback: keep the most targeted box.
            best = max(nodes, key=lambda i: (indeg[i], boxes[i][3]))
            keep[best] = True
            if sender[best] != -1:
                new_center[best] = boxes[sender[best]][3]

    # Draw kept boxes.
    for i in range(n):
        if not keep[i]:
            continue
        r, c, frame, _ = boxes[i]
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w:
                    if dr == 0 and dc == 0:
                        out[rr, cc] = new_center[i] if new_center[i] is not None else boxes[i][3]
                    else:
                        # Preserve original frame cells; do not overwrite 5s.
                        if g[rr, cc] == frame:
                            out[rr, cc] = frame

    return out.tolist()

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape
    out = np.zeros((H, W), dtype=int)

    # marker color -> (output color, pattern type)
    # 2: full 4x4 square
    # 3: 4x4 square without corners
    # 5: two diagonal 2x2 blocks
    # 8: 4x4 square with only the two middle cells of each side
    mapping = {
        2: (4, "full"),
        3: (1, "nocorner"),
        5: (6, "diag"),
        8: (7, "mid"),
    }

    def pattern_cells(color, ptype, r, c):
        cells = []
        if ptype == "full":
            for dr in range(4):
                for dc in range(4):
                    if dr == 0 or dr == 3 or dc == 0 or dc == 3:
                        cells.append((r + dr, c + dc, color))
        elif ptype == "nocorner":
            for dr in range(4):
                for dc in range(4):
                    if (dr == 0 or dr == 3) and dc in (1, 2):
                        cells.append((r + dr, c + dc, color))
                    if (dc == 0 or dc == 3) and dr in (1, 2):
                        cells.append((r + dr, c + dc, color))
        elif ptype == "diag":
            for dr in (0, 1):
                for dc in (0, 1):
                    cells.append((r + dr, c + dc, color))
                    cells.append((r + 2 + dr, c + 2 + dc, color))
        elif ptype == "mid":
            for dr in range(4):
                for dc in range(4):
                    if (dr == 0 or dr == 3) and dc in (1, 2):
                        cells.append((r + dr, c + dc, color))
                    if (dc == 0 or dc == 3) and dr in (1, 2):
                        cells.append((r + dr, c + dc, color))
        return cells

    # Process markers in deterministic top-to-bottom, left-to-right order.
    markers = []
    for r in range(H):
        for c in range(W):
            if g[r, c] in mapping:
                markers.append((r, c, int(g[r, c])))

    placed = []  # list of (r, c, color, ptype)

    for r, c, mcolor in markers:
        ocolor, ptype = mapping[mcolor]
        placed_any = False

        # Try the marker position, then shift right until non-overlapping.
        for cc in range(c, W - 3):
            cells = pattern_cells(ocolor, ptype, r, cc)
            if any(rr < 0 or rr >= H or cc2 < 0 or cc2 >= W for rr, cc2, _ in cells):
                continue

            ok = True
            for rr, cc2, _ in cells:
                if out[rr, cc2] != 0:
                    ok = False
                    break
            if ok:
                for rr, cc2, col in cells:
                    out[rr, cc2] = col
                placed.append((r, cc, ocolor, ptype))
                placed_any = True
                break

        # If no horizontal position works, skip this marker.
        if not placed_any:
            continue

    return out.tolist()

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape

    # marker color -> (output color, pattern name)
    mapping = {
        2: (4, "border"),
        3: (1, "side"),
        5: (6, "diag"),
        8: (7, "corner_center"),
    }

    def pattern_cells(color, name, r, c):
        cells = []
        if name == "border":
            for dr in range(4):
                for dc in range(4):
                    if dr == 0 or dr == 3 or dc == 0 or dc == 3:
                        cells.append((r + dr, c + dc, color))
        elif name == "side":
            for dr in range(4):
                for dc in range(4):
                    if (dr == 0 or dr == 3) and dc in (1, 2):
                        cells.append((r + dr, c + dc, color))
                    if (dc == 0 or dc == 3) and dr in (1, 2):
                        cells.append((r + dr, c + dc, color))
        elif name == "diag":
            for dr in (0, 1):
                for dc in (0, 1):
                    cells.append((r + dr, c + dc, color))
                    cells.append((r + 2 + dr, c + 2 + dc, color))
        elif name == "corner_center":
            for dr in range(4):
                for dc in range(4):
                    if (dr in (0, 3) and dc in (0, 3)) or (dr in (1, 2) and dc in (1, 2)):
                        cells.append((r + dr, c + dc, color))
        return cells

    # Collect markers.
    markers = []
    for r in range(H):
        for c in range(W):
            if g[r, c] in mapping:
                markers.append((r, c, int(g[r, c])))

    # Process from bottom to top, left to right.  This gives the observed
    # priority when candidate 4x4 patterns overlap.
    markers.sort(key=lambda x: (-x[0], x[1]))

    out = np.zeros((H, W), dtype=int)

    for r, c, mcolor in markers:
        ocolor, pname = mapping[mcolor]
        cells = pattern_cells(ocolor, pname, r, c)

        # Ignore patterns that leave the grid.
        if any(rr < 0 or rr >= H or cc < 0 or cc >= W for rr, cc, _ in cells):
            continue

        # Ignore patterns that overlap any already placed pattern.
        if any(out[rr, cc] != 0 for rr, cc, _ in cells):
            continue

        for rr, cc, col in cells:
            out[rr, cc] = col

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    def is_rect_frame(r0, c0, r1, c1, color):
        if r1 - r0 < 2 or c1 - c0 < 2:
            return False
        for c in range(c0, c1 + 1):
            if g[r0, c] != color or g[r1, c] != color:
                return False
        for r in range(r0, r1 + 1):
            if g[r, c0] != color or g[r, c1] != color:
                return False
        return True

    def frame_color(r0, c0, r1, c1):
        return int(g[r0, c0])

    # Find all maximal rectangular frames.
    frames = []
    for r0 in range(h):
        for c0 in range(w):
            color = g[r0, c0]
            if color == 0:
                continue
            for r1 in range(r0 + 2, h):
                for c1 in range(c0 + 2, w):
                    if is_rect_frame(r0, c0, r1, c1, color):
                        # maximal in both directions
                        max_r1 = r1
                        while max_r1 + 1 < h and is_rect_frame(r0, c0, max_r1 + 1, c1, color):
                            max_r1 += 1
                        max_c1 = c1
                        while max_c1 + 1 < w and is_rect_frame(r0, c0, r1, max_c1 + 1, color):
                            max_c1 += 1
                        if max_r1 == r1 and max_c1 == c1:
                            frames.append((r0, c0, r1, c1, int(color)))
    # Remove duplicates
    frames = list(set(frames))

    # Find candidate key blocks: small dense non-zero rectangles.
    keys = []
    for r0 in range(h):
        for c0 in range(w):
            for r1 in range(r0, min(h, r0 + 4) + 1):
                for c1 in range(c0, min(w, c0 + 6) + 1):
                    sub = g[r0:r1 + 1, c0:c1 + 1]
                    if sub.size < 4:
                        continue
                    if np.count_nonzero(sub) >= max(4, int(0.7 * sub.size)):
                        # avoid frames themselves
                        if is_rect_frame(r0, c0, r1, c1, int(sub[0, 0])):
                            continue
                        keys.append((r0, c0, r1, c1))
    keys = list(set(keys))

    # For each frame, choose a fill color from a key block.
    for (r0, c0, r1, c1, color) in frames:
        fill = None
        best = None
        for (kr0, kc0, kr1, kc1) in keys:
            sub = g[kr0:kr1 + 1, kc0:kc1 + 1]
            positions = np.argwhere(sub == color)
            if len(positions) == 0:
                continue
            # Prefer the occurrence closest to the frame.
            positions = sorted(
                positions,
                key=lambda p: (
                    abs((kr0 + p[0]) - (r0 + r1) / 2) +
                    abs((kc0 + p[1]) - (c0 + c1) / 2)
                )
            )
            for pr, pc in positions:
                rr, cc = kr0 + pr, kc0 + pc
                # Direction from key occurrence to frame center.
                dr = 0 if (r0 + r1) / 2 == rr else (1 if (r0 + r1) / 2 > rr else -1)
                dc = 0 if (c0 + c1) / 2 == cc else (1 if (c0 + c1) / 2 > cc else -1)

                cand = None
                # Try primary horizontal/vertical directions, then fallbacks.
                dirs = []
                if dc != 0:
                    dirs.append((0, dc))
                if dr != 0:
                    dirs.append((dr, 0))
                dirs.extend([(0, 1), (0, -1), (1, 0), (-1, 0)])

                for drr, dcc in dirs:
                    nr, nc = rr + drr, cc + dcc
                    if 0 <= nr < h and 0 <= nc < w:
                        val = int(g[nr, nc])
                        if val != 0 and val != color:
                            cand = val
                            break
                if cand is not None:
                    score = (
                        abs((kr0 + kr1) / 2 - (r0 + r1) / 2) +
                        abs((kc0 + kc1) / 2 - (c0 + c1) / 2)
                    )
                    if best is None or score < best[0]:
                        best = (score, cand)
            if best is not None:
                fill = best[1]
                break

        if fill is not None:
            for r in range(r0 + 1, r1):
                for c in range(c0 + 1, c1):
                    if out[r, c] == 0:
                        out[r, c] = fill

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    def is_frame(r0, c0, r1, c1):
        if r1 - r0 < 2 or c1 - c0 < 2:
            return False
        color = g[r0, c0]
        if color == 0:
            return False
        for c in range(c0, c1 + 1):
            if g[r0, c] != color or g[r1, c] != color:
                return False
        for r in range(r0, r1 + 1):
            if g[r, c0] != color or g[r, c1] != color:
                return False
        return True

    # Find all maximal rectangular frames.
    frames = []
    for r0 in range(h):
        for c0 in range(w):
            if g[r0, c0] == 0:
                continue
            for r1 in range(r0 + 2, h):
                for c1 in range(c0 + 2, w):
                    if not is_frame(r0, c0, r1, c1):
                        continue
                    # Make it maximal in both directions.
                    while r1 + 1 < h and is_frame(r0, c0, r1 + 1, c1):
                        r1 += 1
                    while c1 + 1 < w and is_frame(r0, c0, r1, c1 + 1):
                        c1 += 1
                    frames.append((r0, c0, r1, c1, int(g[r0, c0])))
    frames = list(set(frames))

    # Find the palette: a connected non-zero component containing >1 color.
    seen = np.zeros((h, w), dtype=bool)
    palette = None
    for r in range(h):
        for c in range(w):
            if g[r, c] == 0 or seen[r, c]:
                continue
            q = deque([(r, c)])
            seen[r, c] = True
            cells = []
            colors = set()
            while q:
                rr, cc = q.popleft()
                cells.append((rr, cc))
                colors.add(int(g[rr, cc]))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = rr + dr, cc + dc
                    if 0 <= nr < h and 0 <= nc < w and not seen[nr, nc] and g[nr, nc] != 0:
                        seen[nr, nc] = True
                        q.append((nr, nc))
            if len(colors) > 1:
                palette = cells
                break

    mapping = {}
    if palette:
        rs = [r for r, c in palette]
        cs = [c for r, c in palette]
        r0, r1 = min(rs), max(rs)
        c0, c1 = min(cs), max(cs)
        ph, pw = r1 - r0 + 1, c1 - c0 + 1

        # The palette is a 2-thick strip.  Map across the thin dimension.
        # Direction is from the side touching the grid border toward the inside.
        if pw == 2 and ph >= 2:
            if c0 == 0:
                src, dst = c0, c1
            elif c1 == w - 1:
                src, dst = c1, c0
            else:
                src, dst = c0, c1
            for r in range(r0, r1 + 1):
                a, b = int(g[r, src]), int(g[r, dst])
                if a != 0 and b != 0:
                    mapping[a] = b
        elif ph == 2 and pw >= 2:
            if r0 == 0:
                src, dst = r0, r1
            elif r1 == h - 1:
                src, dst = r1, r0
            else:
                src, dst = r0, r1
            for c in range(c0, c1 + 1):
                a, b = int(g[src, c]), int(g[dst, c])
                if a != 0 and b != 0:
                    mapping[a] = b
        else:
            # Fallback for unusual palette shapes: use all adjacent pairs.
            for r, c in palette:
                col = int(g[r, c])
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and g[nr, nc] != 0:
                        other = int(g[nr, nc])
                        if other != col:
                            mapping.setdefault(col, other)

    # Fill zero cells inside frames whose border color has a palette mapping.
    for r0, c0, r1, c1, color in frames:
        fill = mapping.get(color)
        if fill is None:
            continue
        for r in range(r0 + 1, r1):
            for c in range(c0 + 1, c1):
                if out[r, c] == 0:
                    out[r, c] = fill

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    H, W = g.shape
    out = g.copy()

    # Connected components of non-zero cells (4-connectivity)
    comp_id = -np.ones((H, W), dtype=int)
    comps = []
    for r in range(H):
        for c in range(W):
            if g[r, c] != 0 and comp_id[r, c] == -1:
                cid = len(comps)
                color = int(g[r, c])
                cells = []
                q = deque([(r, c)])
                comp_id[r, c] = cid
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < H and 0 <= nx < W:
                            if g[ny, nx] != 0 and comp_id[ny, nx] == -1:
                                comp_id[ny, nx] = cid
                                q.append((ny, nx))
                comps.append((color, cells))

    # Identify the "legend" component:
    # a small, compact, non-rectangular component that is not a frame/outline.
    def bbox(cells):
        ys = [y for y, _ in cells]
        xs = [x for _, x in cells]
        return min(ys), max(ys), min(xs), max(xs)

    def is_rectangular_frame(cells, color):
        y0, y1, x0, x1 = bbox(cells)
        h = y1 - y0 + 1
        w = x1 - x0 + 1
        if h < 3 or w < 3:
            return False
        # All border cells must be this color.
        for y in range(y0, y1 + 1):
            for x in range(x0, x1 + 1):
                if (y == y0 or y == y1 or x == x0 or x == x1):
                    if g[y, x] != color:
                        return False
        # At least one interior zero (a hole)
        for y in range(y0 + 1, y1):
            for x in range(x0 + 1, x1):
                if g[y, x] == 0:
                    return True
        return False

    legend_cid = -1
    best_score = -1
    for cid, (color, cells) in enumerate(comps):
        if len(cells) < 4:
            continue
        y0, y1, x0, x1 = bbox(cells)
        h = y1 - y0 + 1
        w = x1 - x0 + 1
        area = h * w
        # Legend is compact but not a full rectangle, and not a frame.
        if area > 12:
            continue
        if is_rectangular_frame(cells, color):
            continue
        if len(cells) == area:
            continue
        # Prefer small components with several vertical adjacencies.
        vert = 0
        for y, x in cells:
            if y + 1 < H and g[y + 1, x] != 0:
                vert += 1
        score = vert * 10 - area
        if score > best_score:
            best_score = score
            legend_cid = cid

    mapping = {}
    if legend_cid != -1:
        color, cells = comps[legend_cid]
        cell_set = set(cells)
        # If the legend is a 2-row table, map top row to bottom row.
        y0, y1, x0, x1 = bbox(cells)
        if y1 - y0 == 1:
            for x in range(x0, x1 + 1):
                top = int(g[y0, x])
                bot = int(g[y1, x])
                if top != 0 and bot != 0:
                    mapping[top] = bot
        else:
            # Fallback: map each legend cell to the non-zero cell directly below it.
            for y, x in cells:
                if y + 1 < H and (y + 1, x) in cell_set:
                    a = int(g[y, x])
                    b = int(g[y + 1, x])
                    if a != 0 and b != 0:
                        mapping[a] = b

    # Fill enclosed zero holes for components whose color has a mapping.
    for cid, (color, cells) in enumerate(comps):
        if color not in mapping:
            continue
        fill_color = mapping[color]
        if fill_color == 0:
            continue

        # Find zero cells enclosed by this component.
        # Flood fill from outside; any zero not reached is enclosed.
        visited = np.zeros((H, W), dtype=bool)
        q = deque()
        for r in range(H):
            for c in (0, W - 1):
                if g[r, c] == 0 and not visited[r, c]:
                    visited[r, c] = True
                    q.append((r, c))
        for c in range(W):
            for r in (0, H - 1):
                if g[r, c] == 0 and not visited[r, c]:
                    visited[r, c] = True
                    q.append((r, c))

        while q:
            y, x = q.popleft()
            for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                ny, nx = y + dy, x + dx
                if 0 <= ny < H and 0 <= nx < W:
                    if g[ny, nx] == 0 and not visited[ny, nx]:
                        visited[ny, nx] = True
                        q.append((ny, nx))

        # A zero is a hole for this component if it is enclosed and adjacent
        # (4-neighbor) to at least one cell of this component.
        comp_set = set(cells)
        for y, x in comp_set:
            for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                ny, nx = y + dy, x + dx
                if 0 <= ny < H and 0 <= nx < W:
                    if g[ny, nx] == 0 and not visited[ny, nx]:
                        out[ny, nx] = fill_color

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    H, W = g.shape
    out = g.copy()

