                    cells.append((y, x))
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            if dy == 0 and dx == 0:
                                continue
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < H and 0 <= nx < W:
                                if g[ny, nx] != 0 and comp_id[ny, nx] == -1:
                                    comp_id[ny, nx] = cid
                                    q.append((ny, nx))
