        y0, y1, x0, x1 = bbox(cells)
        h = y1 - y0 + 1
        w = x1 - x0 + 1
        if min(h, w) != 2:
            continue
        # Must be completely filled.
        if len(cells) != h * w:
            continue
        # Prefer the largest such solid strip if there are several.
        if len(cells) > len(table_cells):
            table_cells = set(cells)
            if h == 2:
                # top row -> bottom row
                for x in range(x0, x1 + 1):
                    a = int(g[y0, x])
                    b = int(g[y1, x])
                    if a != 0:
                        mapping[a] = b
            else:
                # left column -> right column
                for y in range(y0, y1 + 1):
                    a = int(g[y, x0])
                    b = int(g[y, x1])
                    if a != 0:
                        mapping[a] = b

    if not mapping:
        return out.tolist()

    # Flood-fill outside zero cells using 4-connectivity, treating all
    # non-zero cells as walls.
    outside = np.zeros((H, W), dtype=bool)
    q = deque()

    for r in range(H):
        for c in (0, W - 1):
            if g[r, c] == 0 and not outside[r, c]:
                outside[r, c] = True
                q.append((r, c))
    for c in range(W):
        for r in (0, H - 1):
            if g[r, c] == 0 and not outside[r, c]:
                outside[r, c] = True
                q.append((r, c))

    while q:
        y, x = q.popleft()
        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            ny, nx = y + dy, x + dx
            if 0 <= ny < H and 0 <= nx < W:
                if g[ny, nx] == 0 and not outside[ny, nx]:
                    outside[ny, nx] = True
                    q.append((ny, nx))

    # Each enclosed zero region is filled according to the source color
    # adjacent to it.
    visited = np.zeros((H, W), dtype=bool)
    for r in range(H):
        for c in range(W):
            if g[r, c] == 0 and not outside[r, c] and not visited[r, c]:
                # Collect this enclosed zero region.
                region = []
                dq = deque([(r, c)])
                visited[r, c] = True
                while dq:
                    y, x = dq.popleft()
                    region.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < H and 0 <= nx < W:
                            if g[ny, nx] == 0 and not outside[ny, nx] and not visited[ny, nx]:
                                visited[ny, nx] = True
                                dq.append((ny, nx))

                # Count adjacent source colors (ignore table cells).
                counts = {}
                for y, x in region:
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            if dy == 0 and dx == 0:
                                continue
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < H and 0 <= nx < W:
                                if (ny, nx) in table_cells:
                                    continue
                                col = int(g[ny, nx])
                                if col in mapping:
                                    counts[col] = counts.get(col, 0) + 1

                if counts:
                    # Choose the most frequent adjacent source color.
                    best = max(counts.items(), key=lambda kv: (kv[1], -kv[0]))[0]
                    fill = int(mapping[best])
                    for y, x in region:
                        out[y, x] = fill

    return out.tolist()

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Background is the border colour.
    bg = int(g[0, 0])

    # Find all maximal square blocks of a single non-background colour.
    blocks = []
    for r in range(H):
        for c in range(W):
            if g[r, c] == bg:
                continue
            color = int(g[r, c])
            # Try to grow a square block starting at (r, c).
            max_size = min(H - r, W - c)
            size = 0
            for s in range(1, max_size + 1):
                sub = g[r:r + s, c:c + s]
                if np.all(sub == color):
                    size = s
                else:
                    break
            if size > 0:
                # Keep only maximal blocks: not contained in a larger same-colour square.
                contained = False
                for br, bc, bs, bcol in blocks:
                    if bcol == color and br <= r and bc <= c and br + bs >= r + size and bc + bs >= c + size:
                        contained = True
                        break
                if not contained:
                    # Remove any blocks contained in this new one.
                    blocks = [
                        (br, bc, bs, bcol)
                        for br, bc, bs, bcol in blocks
                        if not (color == bcol and r <= br and c <= bc and r + size >= br + bs and c + size >= bc + bs)
                    ]
                    blocks.append((r, c, size, color))

    if not blocks:
        return [list(map(int, row)) for row in g]

    # The target block size is the size of the largest square block present.
    block_size = max(b[2] for b in blocks)

    # Existing target blocks are those with this size.
    target_blocks = [(r, c, col) for (r, c, s, col) in blocks if s == block_size]

    # Determine the grid of target block top-left positions from existing blocks.
    rows = sorted({r for r, c, col in target_blocks})
    cols = sorted({c for r, c, col in target_blocks})

    # If only one row/col is known, infer the full grid from the 1x1 source dots.
    # Source dots are non-background 1x1 cells not part of any larger square block.
    in_block = np.zeros((H, W), dtype=bool)
    for r, c, s, col in blocks:
        in_block[r:r + s, c:c + s] = True

    dots = []
    for r in range(H):
        for c in range(W):
            if g[r, c] != bg and not in_block[r, c]:
                dots.append((r, c, int(g[r, c])))

    dot_rows = sorted({r for r, c, col in dots})
    dot_cols = sorted({c for r, c, col in dots})

    # If existing target blocks do not define a full grid, use dot grid dimensions.
    if len(rows) == 1 and len(dot_rows) > 1:
        # Anchor the target grid so that the known row aligns with the matching dot row.
        # Find which dot row matches the known target row's colours.
        known_r = rows[0]
        known_cols = cols
        known_colors = {}
        for r, c, col in target_blocks:
            if r == known_r:
                known_colors[c] = col

        # Build dot matrix values at dot_rows x dot_cols.
        dot_val = {}
        for r, c, col in dots:
            dot_val[(r, c)] = col

        # Choose the dot row whose values best match known target row.
        best_dr = dot_rows[0]
        best_score = -1
        for dr in dot_rows:
            score = 0
            for tc in known_cols:
                # Map target column index to dot column index by order.
                if len(dot_cols) >= len(known_cols):
                    dc = dot_cols[known_cols.index(tc) if tc in known_cols else 0]
                else:
                    dc = dot_cols[0]
                if dot_val.get((dr, dc)) == known_colors.get(tc):
                    score += 1
            if score > best_score:
                best_score = score
                best_dr = dr

        # Vertical spacing: use existing block spacing if multiple rows, else block_size + 1.
        if len(rows) > 1:
            v_spacing = rows[1] - rows[0]
        else:
            v_spacing = block_size + 1

        idx = dot_rows.index(best_dr)
        rows = [known_r + (i - idx) * v_spacing for i in range(len(dot_rows))]
        # Keep rows inside grid; if not, shift.
        if rows[0] < 0:
            shift = -rows[0]
            rows = [r + shift for r in rows]
        if rows[-1] + block_size > H:
            shift = H - block_size - rows[-1]
            rows = [r + shift for r in rows]

    if len(cols) == 1 and len(dot_cols) > 1:
        if len(cols) > 1:
            h_spacing = cols[1] - cols[0]
        else:
            h_spacing = block_size + 1
        cols = [cols[0] + i * h_spacing for i in range(len(dot_cols))]
        if cols[0] < 0:
            shift = -cols[0]
            cols = [c + shift for c in cols]
        if cols[-1] + block_size > W:
            shift = W - block_size - cols[-1]
            cols = [c + shift for c in cols]

    # Build the source dot matrix.
    dot_val = {}
    for r, c, col in dots:
        dot_val[(r, c)] = col

    # For each target block position, choose the colour from the corresponding dot.
    # Correspondence is by order of rows and columns.
    out = g.copy()

    for i, tr in enumerate(rows):
        for j, tc in enumerate(cols):
            # If this block already exists, leave it.
            existing = None
            for r, c, col in target_blocks:
                if r == tr and c == tc:
                    existing = col
                    break
            if existing is not None:
                continue

            # Find dot colour: use the i-th dot row and j-th dot column if available.
            color = None
            if i < len(dot_rows) and j < len(dot_cols):
                color = dot_val.get((dot_rows[i], dot_cols[j]))

            # Fallback: nearest dot in the same dot row, then same dot column, then any dot.
            if color is None and i < len(dot_rows):
                dr = dot_rows[i]
                best_d = None
                for dc in dot_cols:
                    if (dr, dc) in dot_val:
                        d = abs(dc - (tc if tc < W else 0))
                        if best_d is None or d < best_d[0]:
                            best_d = (d, dot_val[(dr, dc)])
                if best_d:
                    color = best_d[1]

            if color is None and j < len(dot_cols):
                dc = dot_cols[j]
                best_d = None
                for dr in dot_rows:
                    if (dr, dc) in dot_val:
                        d = abs(dr - (tr if tr < H else 0))
                        if best_d is None or d < best_d[0]:
                            best_d = (d, dot_val[(dr, dc)])
                if best_d:
                    color = best_d[1]

            if color is None and dots:
                # Use the most frequent non-background dot colour.
                from collections import Counter
                cnt = Counter(col for _, _, col in dots)
                color = cnt.most_common(1)[0][0]

            if color is not None and 0 <= tr and 0 <= tc and tr + block_size <= H and tc + block_size <= W:
                out[tr:tr + block_size, tc:tc + block_size] = color

    return [list(map(int, row)) for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Find all 3x3 blocks with a uniform border and a different center.
    blocks = []
    for r in range(h - 2):
        for c in range(w - 2):
            sub = g[r:r + 3, c:c + 3]
            border = sub[0, 0]
            if border == 0:
                continue
            if (sub[0, 1] == border and sub[0, 2] == border and
                sub[1, 0] == border and sub[1, 2] == border and
                sub[2, 0] == border and sub[2, 1] == border and
                sub[2, 2] == border):
                center = sub[1, 1]
                if center != border:
                    blocks.append((r, c, border, center))

    if not blocks:
        return out.tolist()

    # The 5-colored shape is a path.  Its endpoints are the two 5-cells
    # with exactly one 5-neighbor (8-connected).
    five = (g == 5)
    endpoints = []
    for r in range(h):
        for c in range(w):
            if not five[r, c]:
                continue
            cnt = 0
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and five[nr, nc]:
                        cnt += 1
            if cnt == 1:
                endpoints.append((r, c))

    if len(endpoints) == 2:
        (r1, c1), (r2, c2) = endpoints
        # The two blocks closest to the two endpoints are the ones to keep.
        def dist(b, p):
            br, bc, _, _ = b
            return (br + 1 - p[0]) ** 2 + (bc + 1 - p[1]) ** 2

        keep = set()
        keep.add(min(blocks, key=lambda b: dist(b, (r1, c1))))
        keep.add(min(blocks, key=lambda b: dist(b, (r2, c2))))
    else:
        # Fallback: keep the two blocks with the smallest border+center sum.
        keep = set(sorted(blocks, key=lambda b: b[2] + b[3])[:2])

    # Remove all non-kept blocks.
    for (r, c, border, center) in blocks:
        if (r, c, border, center) not in keep:
            out[r:r + 3, c:c + 3] = 0

    # For kept blocks, replace the center by the border color of the other
    # kept block.
    kept_blocks = [b for b in blocks if b in keep]
    if len(kept_blocks) == 2:
        (r1, c1, b1, _), (r2, c2, b2, _) = kept_blocks
        out[r1 + 1, c1 + 1] = b2
        out[r2 + 1, c2 + 1] = b1

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Determine background as the most frequent colour.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # Connected components of non-background cells (4-connectivity).
    seen = np.zeros((H, W), dtype=bool)
    comps = []
    for r in range(H):
        for c in range(W):
            if g[r, c] != bg and not seen[r, c]:
                color = int(g[r, c])
                q = deque([(r, c)])
                seen[r, c] = True
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < H and 0 <= nx < W:
                            if not seen[ny, nx] and g[ny, nx] == color:
                                seen[ny, nx] = True
                                q.append((ny, nx))
                comps.append((color, cells))

    if not comps:
        return [list(row) for row in grid]

    # Keep only the largest connected component.
    comps.sort(key=lambda x: len(x[1]), reverse=True)
    color, cells = comps[0]

    # Bounding box of the component.
    min_r = min(r for r, _ in cells)
    max_r = max(r for r, _ in cells)
    min_c = min(c for _, c in cells)
    max_c = max(c for _, c in cells)
    h = max_r - min_r + 1
    w = max_c - min_c + 1

    # Extract the component as a binary mask.
    mask = np.zeros((h, w), dtype=bool)
    for r, c in cells:
        mask[r - min_r, c - min_c] = True

    # Find the largest square that can be tiled by the component mask.
    best_k = 1
    best_t = 0
    for k in range(1, min(h, w) + 1):
        if (h % k) or (w % k):
            continue
        if (h // k) * (w // k) * k * k != h * w:
            continue
        # Try all translations of the mask inside a k x k tile.
        for tr in range(k):
            for tc in range(k):
                ok = True
                for i in range(h):
                    for j in range(w):
                        if mask[i, j]:
                            if (i + tr) % k >= k or (j + tc) % k >= k:
                                ok = False
                                break
                    if not ok:
                        break
                if ok:
                    best_k = k
                    best_t = (tr, tc)
                    break
            if best_k == k:
                break

    # Build the output by tiling the component mask.
    out = np.full((H, W), bg, dtype=int)
    for i in range(h):
        for j in range(w):
            if mask[i, j]:
                for a in range(0, H, best_k):
                    for b in range(0, W, best_k):
                        rr = a + (i + best_t[0]) % best_k
                        cc = b + (j + best_t[1]) % best_k
                        if rr < H and cc < W:
                            out[rr, cc] = color

    return out.tolist()

