import numpy as np
from collections import defaultdict

def _segments(grid, dr, dc):
    """Maximal straight segments in direction (dr, dc)."""
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    segs = []
    for r in range(h):
        for c in range(w):
            if seen[r][c] or grid[r][c] == 7:
                continue
            # start only if previous cell in opposite direction is not same color
            pr, pc = r - dr, c - dc
            if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == grid[r][c]:
                continue
            color = grid[r][c]
            cells = []
            rr, cc = r, c
            while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                cells.append((rr, cc))
                seen[rr][cc] = True
                rr += dr
                cc += dc
            if len(cells) > 1:
                segs.append((color, cells))
    return segs

def _base_key(cells, dr, dc):
    """
    For a segment, return the key of the perpendicular base line on which
    one endpoint lies, and the endpoint on that base.
    """
    r0, c0 = cells[0]
    r1, c1 = cells[-1]
    # Direction vector of segment
    if dr == 0:  # horizontal
        # base is vertical line through left or right end
        if c0 <= c1:
            return ('v', c0), (r0, c0)
        else:
            return ('v', c1), (r1, c1)
    elif dc == 0:  # vertical
        if r0 <= r1:
            return ('h', r0), (r0, c0)
        else:
            return ('h', r1), (r1, c1)
    else:
        # diagonal: perpendicular base has constant r-c or r+c
        # choose the endpoint whose r-c is more consistent? We'll test both later.
        # For down-left/up-right segments, base is usually the endpoint with smaller r-c? 
        # We'll return both possibilities and let grouping decide.
        return None, None

def _group_by_base(segs, dr, dc):
    """
    Group segments by a common perpendicular base line.
    Returns list of groups, each group is list of (color, cells, base_endpoint).
    """
    groups = []
    if dr == 0:
        keymap = defaultdict(list)
        for color, cells in segs:
            r0, c0 = cells[0]
            r1, c1 = cells[-1]
            # horizontal: base vertical line at min col or max col
            if c0 <= c1:
                key = ('v', c0)
                base = (r0, c0)
            else:
                key = ('v', c1)
                base = (r1, c1)
            keymap[key].append((color, cells, base))
        for key, lst in keymap.items():
            if len(lst) >= 2:
                groups.append(lst)
    elif dc == 0:
        keymap = defaultdict(list)
        for color, cells in segs:
            r0, c0 = cells[0]
            r1, c1 = cells[-1]
            if r0 <= r1:
                key = ('h', r0)
                base = (r0, c0)
            else:
                key = ('h', r1)
                base = (r1, c1)
            keymap[key].append((color, cells, base))
        for key, lst in keymap.items():
            if len(lst) >= 2:
                groups.append(lst)
    else:
        # diagonal: try both endpoints as base; choose grouping that yields largest group
        best = []
        for use_first in (True, False):
            keymap = defaultdict(list)
            for color, cells in segs:
                if use_first:
                    r, c = cells[0]
                else:
                    r, c = cells[-1]
                # perpendicular diagonal base: constant r-c
                key = ('d', r - c)
                keymap[key].append((color, cells, (r, c)))
            for key, lst in keymap.items():
                if len(lst) > len(best):
                    best = lst
        if len(best) >= 2:
            groups.append(best)
    return groups

def _order_key(base, dr, dc):
    """Order along the base line."""
    r, c = base
    if dr == 0:  # vertical base, order by row
        return r
    if dc == 0:  # horizontal base, order by col
        return c
    # diagonal base r-c constant, order by r (or c)
    return r

def _resize(cells, target_len, base, dr, dc):
    """
    Resize segment to target_len, keeping the base endpoint fixed.
    Direction from base into segment is determined by original cells.
    """
    br, bc = base
    # Determine direction from base to the other end
    if len(cells) == 1:
        # not used for len>1 segments
        return [(br, bc)]
    # find direction sign
    if dr == 0:
        # horizontal
        if cells[0][1] <= cells[-1][1]:
            d = (0, 1)
        else:
            d = (0, -1)
    elif dc == 0:
        if cells[0][0] <= cells[-1][0]:
            d = (1, 0)
        else:
            d = (-1, 0)
    else:
        # diagonal: direction from base to other endpoint
        other = cells[-1] if cells[0] == base else cells[0]
        d = (1 if other[0] > br else -1, 1 if other[1] > bc else -1)
    out = []
    r, c = br, bc
    for _ in range(target_len):
        out.append((r, c))
        r += d[0]
        c += d[1]
    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    out = [row[:] for row in grid]
