def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Find the vertical separator made of 6s.
    sep = None
    for c in range(W):
        if np.all(g[:, c] == 6):
            sep = c
            break
    if sep is None:
        return [list(map(int, row)) for row in g]

    left = g[:, :sep]
    right = g[:, sep + 1:]
    out = right.copy()
    Lh, Lw = left.shape
    Rh, Rw = right.shape

    # Find the first non-6, non-zero pattern in the left side.
    pat = None
    for r in range(Lh):
        for c in range(Lw):
            if left[r, c] not in (0, 6):
                r0, c0 = r, c
                r1, c1 = r, c
                while r1 + 1 < Lh and left[r1 + 1, c0] not in (0, 6):
                    r1 += 1
                while c1 + 1 < Lw and left[r0, c1 + 1] not in (0, 6):
                    c1 += 1
                pat = left[r0:r1 + 1, c0:c1 + 1].copy()
                break
        if pat is not None:
            break

    if pat is None:
        return [list(map(int, row)) for row in out]

    ph, pw = pat.shape
    colors = sorted(set(pat.flatten().tolist()))
    if len(colors) == 2:
        a, b = colors
        pat = np.where(pat == a, b, a)

    # Build the stamp mask from the 6-bordered boxes below the pattern.
    mask = np.zeros((Lh, Lw), dtype=bool)
    r = r1 + 1
    while r < Lh:
        if np.any(left[r] == 6):
            r0 = r
            while r < Lh and np.any(left[r] == 6):
                r += 1
            r1b = r - 1
            c0 = None
            c1 = None
            for c in range(Lw):
                if np.any(left[r0:r1b + 1, c] == 6):
                    if c0 is None:
                        c0 = c
                    c1 = c
            if c0 is not None:
                for rr in range(r0, r1b + 1):
                    for cc in range(c0, c1 + 1):
                        if left[rr, cc] not in (0, 6):
                            mask[rr, cc] = True
        else:
            r += 1

    # Stamp the pattern onto the right side using the mask.
    for i in range(Rh):
        for j in range(Rw):
            if i < Lh and j < Lw and mask[i, j]:
                out[i, j] = pat[i % ph, j % pw]

    return [list(map(int, row)) for row in out]

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Locate the vertical separator made of 6s.
    sep = None
    for c in range(W):
        if np.all(g[:, c] == 6):
            sep = c
            break
    if sep is None:
        return [list(map(int, row)) for row in g]

    left = g[:, :sep]
    right = g[:, sep + 1:]
    out = right.copy()
    Lh, Lw = left.shape
    Rh, Rw = right.shape

    # Find the first non-6, non-zero 3x3 pattern in the left side.
    pat = None
    for r in range(Lh - 2):
        for c in range(Lw - 2):
            block = left[r:r + 3, c:c + 3]
            vals = set(block.flatten().tolist())
            if len(vals) == 2 and 0 not in vals and 6 not in vals:
                pat = block.copy()
                break
        if pat is not None:
            break

    if pat is None:
        return [list(map(int, row)) for row in out]

    # Swap the two colours in the pattern.
    a, b = sorted(set(pat.flatten().tolist()))
    pat = np.where(pat == a, b, a)

    # Find the mask: the first non-6, non-zero region below the pattern.
    mask = None
    for r in range(Lh):
        for c in range(Lw):
            if left[r, c] not in (0, 6):
                r0, c0 = r, c
                r1, c1 = r, c
                while r1 + 1 < Lh and left[r1 + 1, c0] not in (0, 6):
                    r1 += 1
                while c1 + 1 < Lw and left[r0, c1 + 1] not in (0, 6):
                    c1 += 1
                mask = left[r0:r1 + 1, c0:c1 + 1]
                break
        if mask is not None:
            break

    if mask is None:
        return [list(map(int, row)) for row in out]

    mh, mw = mask.shape
    mask_bin = (mask != 0)

    # Stamp the 3x3 pattern into every mask cell on the right side.
    for i in range(Rh):
        for j in range(Rw):
            if i < mh and j < mw and mask_bin[i, j]:
                out[i, j] = pat[i % 3, j % 3]

    return [list(map(int, row)) for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Locate the vertical separator column of 6s.
    sep = None
    for c in range(W):
        if np.all(g[:, c] == 6):
            sep = c
            break
    if sep is None:
        # Fallback: first column that is mostly 6.
        counts = (g == 6).sum(axis=0)
        sep = int(np.argmax(counts))

    left = g[:, :sep]
    right = g[:, sep + 1:].copy()
    h, w = right.shape

    # Find the 3x3 pattern in the left control area.
    # It is the first 3x3 window containing exactly two non-zero colours.
    pattern = None
    for r in range(h - 2):
        for c in range(sep - 2):
            win = left[r:r + 3, c:c + 3]
            vals = set(win.flatten().tolist())
            vals.discard(0)
            if len(vals) == 2:
                pattern = win
                break
        if pattern is not None:
            break

    if pattern is None:
        return right.tolist()

    # Swap the two colours in the pattern.
    a, b = sorted(set(pattern.flatten().tolist()) - {0})
    swap = {a: b, b: a}
    tile = np.vectorize(lambda x: swap.get(x, x))(pattern)

    # Build the placement mask from the left area:
    # non-zero cells outside the 3x3 pattern window indicate where the tile is placed.
    mask = (left != 0)
    # Remove the pattern window itself.
    pr, pc = None, None
    for r in range(h - 2):
        for c in range(sep - 2):
            win = left[r:r + 3, c:c + 3]
            vals = set(win.flatten().tolist())
            vals.discard(0)
            if len(vals) == 2:
                pr, pc = r, c
                break
        if pr is not None:
            break
    if pr is not None:
        mask[pr:pr + 3, pc:pc + 3] = False

    # The mask is a 5x5 (or similar) binary template.  Tile it over the right
    # canvas with a 3x3 step.  Where the template is 1, overwrite the 3x3 block
    # with the swapped pattern.
    for r in range(0, h, 3):
        for c in range(0, w, 3):
            # Corresponding template position in the left mask.
            tr = r % max(1, mask.shape[0])
            tc = c % max(1, mask.shape[1])
            if mask[tr, tc]:
                block = right[r:r + 3, c:c + 3]
                if block.shape == tile.shape:
                    right[r:r + 3, c:c + 3] = tile
                else:
                    # If the canvas edge is smaller, copy the overlapping part.
                    rh, rw = block.shape
                    right[r:r + rh, c:c + rw] = tile[:rh, :rw]

    return right.tolist()

