def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Find the vertical separator line made of 6s.
    sep = None
    for c in range(W):
        if np.all(g[:, c] == 6):
            sep = c
            break
    if sep is None:
        return [list(map(int, row)) for row in g]

    canvas = g[:, sep + 1:].copy()
    ch, cw = canvas.shape

    # Extract the first 5x5 control block from the left side.
    left = g[:5, :5]
    vals = [v for v in np.unique(left) if v != 0]
    if len(vals) < 2:
        return [list(map(int, row)) for row in canvas]

    a, b = sorted(vals)
    # Swap the two non-zero colors to form the 3x3 tile.
    tile = np.empty((3, 3), dtype=int)
    for i in range(3):
        for j in range(3):
            v = left[i + 1, j + 1]
            if v == a:
                tile[i, j] = b
            elif v == b:
                tile[i, j] = a
            else:
                tile[i, j] = 0

    # Determine the 6x6 placement mask from the bottom-left 6x6 block.
    mask = np.zeros((6, 6), dtype=bool)
    for r in range(H - 6, H):
        for c in range(6):
            if g[r, c] != 6:
                mask[r - (H - 6), c] = True

    # Tile the 3x3 pattern over the canvas according to the 6x6 mask.
    for br in range(0, ch, 6):
        for bc in range(0, cw, 6):
            mr = br // 6
            mc = bc // 6
            if not mask[mr, mc]:
                continue
            r0, c0 = br, bc
            r1, c1 = min(br + 3, ch), min(bc + 3, cw)
            canvas[r0:r1, c0:c1] = tile[:r1 - r0, :c1 - c0]

    return [list(map(int, row)) for row in canvas]

