def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Find the vertical separator made of 6s.
    sep = None
    for c in range(W):
        if np.all(g[:, c] == 6):
            sep = c
            break
    if sep is None:
        return [list(map(int, row)) for row in g]

    canvas = g[:, sep + 1:].copy()
    ch, cw = canvas.shape

    # The 3x3 stamp is the inner 3x3 of the top-left 5x5,
    # with its two non-zero colours swapped.
    top = g[:5, :5]
    vals = [v for v in np.unique(top) if v != 0]
    if len(vals) < 2:
        return [list(map(int, row)) for row in canvas]

    a, b = sorted(vals)
    stamp = np.empty((3, 3), dtype=int)
    for i in range(3):
        for j in range(3):
            v = top[i + 1, j + 1]
            if v == a:
                stamp[i, j] = b
            elif v == b:
                stamp[i, j] = a
            else:
                stamp[i, j] = 0

    # The 6x3 placement mask is the first 6x3 block below the top 5x5
    # that contains a non-zero colour other than the stamp colours.
    mask = None
    for r0 in range(5, H - 5):
        block = g[r0:r0 + 6, 1:4]
        block_vals = [v for v in np.unique(block) if v != 0 and v not in (a, b)]
        if block_vals:
            mask = (block != 0)
            break

    if mask is None:
        return [list(map(int, row)) for row in canvas]

    # The bottom-left 6x6 block gives the vertical offset of the 6x3 mask.
    # Count non-6 cells in its left 5 columns; 0 -> top, 1 -> middle, 2 -> bottom.
    bottom = g[H - 6:H, :5]
    non6 = int(np.sum(bottom != 6))
    if non6 == 0:
        row_offset = 0
    elif non6 == 1:
        row_offset = 2
    else:
        row_offset = 4

    # The horizontal offset is the column of the first non-6 cell in the
    # bottom-left 6x6 block, multiplied by 3.
    col_offset = 0
    found = False
    for c in range(6):
        if np.any(g[H - 6:H, c] != 6):
            col_offset = c * 3
            found = True
            break
    if not found:
        col_offset = 0

    # Stamp the 3x3 pattern at every active 3x3 cell of the 6x3 mask.
    for mr in range(6):
        for mc in range(3):
            if not mask[mr, mc]:
                continue
            r0 = row_offset + 3 * mr
            c0 = col_offset + 3 * mc
            r1 = min(r0 + 3, ch)
            c1 = min(c0 + 3, cw)
            if r0 < ch and c0 < cw:
                canvas[r0:r1, c0:c1] = stamp[:r1 - r0, :c1 - c0]

    return [list(map(int, row)) for row in canvas]

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])

    # Collect all non-background cells.
    cells = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != 0]

    # If there are no non-background cells, return an empty grid of the same size.
    if not cells:
        return [[0] * w for _ in range(h)]

    # Determine the two most frequent non-zero colors.
    # These are the "source" colors that will be propagated.
    freq = {}
    for _, _, v in cells:
        freq[v] = freq.get(v, 0) + 1

    # Sort by frequency descending, then by color value for determinism.
    sorted_colors = sorted(freq.items(), key=lambda x: (-x[1], x[0]))
    if len(sorted_colors) < 2:
        # Fallback: if only one color exists, use it twice (should not happen in valid tests).
        main_colors = [sorted_colors[0][0], sorted_colors[0][0]]
    else:
        main_colors = [sorted_colors[0][0], sorted_colors[1][0]]

    # Build a set of source coordinates for each main color.
    sources = {main_colors[0]: set(), main_colors[1]: set()}
    for r, c, v in cells:
        if v in sources:
            sources[v].add((r, c))

    # For each cell, compute the minimum Manhattan distance to the nearest source
    # of each main color.
    def min_dist_to_set(pt, src_set):
        r, c = pt
        best = float('inf')
        for sr, sc in src_set:
            d = abs(r - sr) + abs(c - sc)
            if d < best:
                best = d
        return best

    out = [[0] * w for _ in range(h)]

    for r in range(h):
        for c in range(w):
            d0 = min_dist_to_set((r, c), sources[main_colors[0]])
            d1 = min_dist_to_set((r, c), sources[main_colors[1]])

            # If the cell is closer to color0's sources, paint it color0.
            # If closer to color1's sources, paint it color1.
            # If equidistant (including both infinite), leave as 0.
            if d0 < d1:
                out[r][c] = main_colors[0]
            elif d1 < d0:
                out[r][c] = main_colors[1]

    return out

