    # Collect non-background cells.
    cells = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != 0]
    if not cells:
        return [[0] * w for _ in range(h)]

    # Count colors.
    freq = {}
    for _, _, v in cells:
        freq[v] = freq.get(v, 0) + 1

    # The two output colors are the two least frequent colors.
    # Ties are broken by smaller color value.
    colors = sorted(freq.items(), key=lambda x: (x[1], x[0]))
    out_colors = [colors[0][0], colors[1][0]]

    # Source colors are the two most frequent colors.
    # Ties are broken by smaller color value.
    src_colors = [colors[-1][0], colors[-2][0]]

    # Build source coordinate sets.
    src_sets = {src_colors[0]: set(), src_colors[1]: set()}
    for r, c, v in cells:
        if v in src_sets:
            src_sets[v].add((r, c))

    # For each cell, compute minimum Manhattan distance to each source color.
    def min_dist(pt, src_set):
        r, c = pt
        best = 10**9
        for sr, sc in src_set:
            d = abs(r - sr) + abs(c - sc)
            if d < best:
                best = d
        return best

    out = [[0] * w for _ in range(h)]

    for r in range(h):
        for c in range(w):
            d0 = min_dist((r, c), src_sets[src_colors[0]])
            d1 = min_dist((r, c), src_sets[src_colors[1]])

            # Paint with the output color whose source color is closer.
            # If exactly tied, leave background.
            if d0 < d1:
                out[r][c] = out_colors[0]
            elif d1 < d0:
                out[r][c] = out_colors[1]

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = np.zeros((h, w), dtype=int)

    # Directional T-expansion rules observed in the examples.
    # For a source color, paint the three orthogonal neighbours except one
    # direction, using the paired output color.
    rules = {
        1: (2, [(0, 0), (-1, 0), (0, -1), (0, 1)]),  # except down
        2: (4, [(-1, 0), (1, 0), (0, -1)]),          # except right
        4: (2, [(-1, 0), (1, 0), (0, 1)]),           # except left
        6: (7, [(-1, 0), (0, -1), (0, 1)]),          # except down
        7: (6, [(1, 0), (0, -1), (0, 1)]),           # except up
    }

    # A cell is active if it is on the border, or if it is one cell inside
    # the border and its color points toward that border.
    def active(r, c, v):
        if r == 0 or r == h - 1 or c == 0 or c == w - 1:
            return True
        if r == 1 and v == 6:
            return True
        if r == h - 2 and v == 7:
            return True
        if c == 1 and v == 2:
            return True
        if c == w - 2 and v == 4:
            return True
        return False

    for r in range(h):
        for c in range(w):
            v = int(g[r, c])
            if v in rules and active(r, c, v):
                color, deltas = rules[v]
                for dr, dc in deltas:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w:
                        out[nr, nc] = color

    return out.tolist()

