                    target = 6 if c == 7 else 7
                for x in range(x_min, x_max + 1):
                    if g[y, x] != c:
                        continue
                    for dx in dxs:
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w:
                            out[ny, nx] = target

        # Vertical line
        if len(np.unique(xs)) == 1:
            x = int(xs[0])
            y_min, y_max = int(ys.min()), int(ys.max())
            if y_max - y_min + 1 <= len(ys) + 1:
                if x < w // 2:
                    dx, dys = -1, (-1, 0, 1)
                    target = 4 if c == 2 else 2
                else:
