                    target = 2 if c == 4 else 4
                for y in range(y_min, y_max + 1):
                    if g[y, x] != c:
                        continue
                    for dy in dys:
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w:
                            out[ny, nx] = target

