    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Identify colors.
    nz = g[g != 0]
    if nz.size == 0:
        return [list(map(int, row)) for row in g]

    colors, counts = np.unique(nz, return_counts=True)
    color_count = {int(c): int(n) for c, n in zip(colors, counts)}

    # The line color is the most frequent non-zero color.
    line_color = max(color_count, key=lambda c: color_count[c])

    # The fill color is the most frequent non-zero color that is not the line color.
    fill_color = None
    best = -1
    for c, n in color_count.items():
        if c != line_color and n > best:
            best = n
            fill_color = c

    if fill_color is None:
        return [list(map(int, row)) for row in g]

    # Obstacles are all other non-zero colors.
    obstacle = (g != 0) & (g != line_color) & (g != fill_color)

    # Flood fill from existing fill-color cells through background cells.
    # Line cells and obstacle cells are walls.
    walls = (g == line_color) | obstacle
    start = (g == fill_color)

    out = g.copy()
    q = deque()
    for r in range(h):
        for c in range(w):
            if start[r, c]:
                q.append((r, c))

    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
                if not walls[nr, nc] and out[nr, nc] != fill_color:
                    out[nr, nc] = fill_color
                    q.append((nr, nc))

    return [list(map(int, row)) for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Background is the most common colour.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # Non-background colours.
    non_bg = [int(v) for v in vals if v != bg]
    if len(non_bg) < 2:
        return [list(map(int, row)) for row in g]

    # The "template" colour is the one that also appears as the centre
    # of the marker object.  The marker colour is the other one.
    def cells_of(colour):
        return [(r, c) for r in range(h) for c in range(w) if g[r, c] == colour]

    def bounding_box(cells):
        rs = [r for r, _ in cells]
        cs = [c for _, c in cells]
        return min(rs), max(rs), min(cs), max(cs)

    def shape_signature(cells, colour):
        r0, r1, c0, c1 = bounding_box(cells)
        sig = []
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                sig.append(1 if g[r, c] == colour else 0)
        return tuple(sig), (r1 - r0 + 1, c1 - c0 + 1)

    # Identify marker colour: the non-background colour whose object has
    # a centre cell of the other non-background colour.
    marker = None
    template = None
    for a in non_bg:
        for b in non_bg:
            if a == b:
                continue
            ca = cells_of(a)
            cb = cells_of(b)
            if not ca or not cb:
                continue
            r0, r1, c0, c1 = bounding_box(ca)
            # Check if the centre of a's bounding box is colour b.
            mr = (r0 + r1) // 2
            mc = (c0 + c1) // 2
            if 0 <= mr < h and 0 <= mc < w and g[mr, mc] == b:
                marker = a
                template = b
                break
        if marker is not None:
            break

    if marker is None:
        # Fallback: use the less frequent non-background colour as marker.
        freq = {c: len(cells_of(c)) for c in non_bg}
        marker = min(non_bg, key=lambda c: freq[c])
        template = [c for c in non_bg if c != marker][0]

    # Extract the template shape (all cells of template colour in its object).
    t_cells = cells_of(template)
    tr0, tr1, tc0, tc1 = bounding_box(t_cells)
    th = tr1 - tr0 + 1
    tw = tc1 - tc0 + 1
    template_shape = np.zeros((th, tw), dtype=int)
    for r, c in t_cells:
        template_shape[r - tr0, c - tc0] = 1

    # Extract marker cells.
    m_cells = cells_of(marker)
    mr0, mr1, mc0, mc1 = bounding_box(m_cells)
    mh = mr1 - mr0 + 1
    mw = mc1 - mc0 + 1
    marker_shape = np.zeros((mh, mw), dtype=int)
    for r, c in m_cells:
        marker_shape[r - mr0, c - mc0] = 1

    # The marker centre is the template-coloured cell inside the marker object.
    centre = None
    for r in range(mr0, mr1 + 1):
        for c in range(mc0, mc1 + 1):
            if g[r, c] == template:
                centre = (r, c)
                break
        if centre is not None:
            break
    if centre is None:
        centre = ((mr0 + mr1) // 2, (mc0 + mc1) // 2)

    # The template centre is the centre of its bounding box.
    t_centre = ((tr0 + tr1) // 2, (tc0 + tc1) // 2)

    out = g.copy()

    # For every marker cell, stamp the template shape with its centre at
    # template_centre + (marker_cell - marker_centre).
    for r, c in m_cells:
        dr = r - centre[0]
        dc = c - centre[1]
        nr0 = t_centre[0] + dr - (th // 2)
        nc0 = t_centre[1] + dc - (tw // 2)
        for i in range(th):
            for j in range(tw):
                if template_shape[i, j]:
                    rr = nr0 + i
                    cc = nc0 + j
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr, cc] = template

    # Replace the original marker object by the template shape in marker colour,
    # centred at the marker centre.
    for r in range(mr0, mr1 + 1):
        for c in range(mc0, mc1 + 1):
            if marker_shape[r - mr0, c - mc0]:
                out[r, c] = marker

    # Finally, restore the original template object in template colour.
    for r, c in t_cells:
        out[r, c] = template

    return [list(map(int, row)) for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Background is the most frequent colour.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # The two non-background colours.
    non_bg = [int(v) for v in vals if v != bg]
    if len(non_bg) != 2:
        return [list(map(int, row)) for row in g]

    a, b = non_bg

    def cells_of(colour):
        return [(r, c) for r in range(h) for c in range(w) if g[r, c] == colour]

    def bbox(cells):
        rs = [r for r, _ in cells]
        cs = [c for _, c in cells]
        return min(rs), max(rs), min(cs), max(cs)

    # The marker is the colour whose object contains a cell of the other colour.
    marker = None
    other = None
    for x, y in ((a, b), (b, a)):
        cx = cells_of(x)
        if not cx:
            continue
        r0, r1, c0, c1 = bbox(cx)
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if g[r, c] == y:
                    marker = x
                    other = y
                    break
            if marker is not None:
                break
        if marker is not None:
            break

    if marker is None:
        return [list(map(int, row)) for row in g]

    # Centre of the marker object is the cell of the other colour.
    m_cells = cells_of(marker)
    r0, r1, c0, c1 = bbox(m_cells)
    centre = None
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            if g[r, c] == other:
                centre = (r, c)
                break
        if centre is not None:
            break
    if centre is None:
        centre = ((r0 + r1) // 2, (c0 + c1) // 2)

    # The other colour's object is a 3x3 hollow square.
    o_cells = cells_of(other)
    or0, or1, oc0, oc1 = bbox(o_cells)
    square_centre = ((or0 + or1) // 2, (oc0 + oc1) // 2)

    # Relative positions of the marker cells from its centre.
    rels = [(r - centre[0], c - centre[1]) for r, c in m_cells]

    out = g.copy()

    # For every marker cell, place a 3x3 hollow square of the other colour
    # at the corresponding relative offset from the original square centre.
    for dr, dc in rels:
        sr = square_centre[0] + dr
        sc = square_centre[1] + dc
        for rr in range(sr - 1, sr + 2):
            for cc in range(sc - 1, sc + 2):
                if 0 <= rr < h and 0 <= cc < w:
                    if rr == sr or cc == sc:
                        out[rr, cc] = other

    # The marker centre becomes a single cell of the marker colour.
    out[centre[0], centre[1]] = marker

    return [list(map(int, row)) for row in out]

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape
    d = int(g[0, 0])

    # Remove the "key" colour everywhere except the top-left marker.
    out = g.copy()
    out[d == d] = 0
    out[0, 0] = d

    # For every other colour, slide each maximal vertical run downward
    # until it hits the bottom or another non-zero cell.
    for c in range(1, 10):
        if c == d:
            continue
        for col in range(w):
            row = 0
            while row < h:
                if out[row, col] == c:
                    start = row
                    while row < h and out[row, col] == c:
                        row += 1
                    length = row - start
                    # maximum downward shift without leaving the grid
                    max_shift = h - (start + length)
                    # stop if the cell below the shifted run is occupied
                    shift = max_shift
                    while shift > 0 and out[start + length + shift - 1, col] != 0:
                        shift -= 1
                    if shift:
                        out[start + shift:start + length + shift, col] = c
                        out[start:start + length, col] = 0
                else:
                    row += 1

    return out.tolist()

import numpy as np
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape
    key = int(g[0, 0])

    # Remove the key colour everywhere except the top-left marker.
    out = g.copy()
    out[out == key] = 0
    out[0, 0] = key

    # Connected components of non-key colours.
    seen = np.zeros((h, w), dtype=bool)
    comps = []
    for r in range(h):
        for c in range(w):
            if out[r, c] != 0 and not seen[r, c]:
                col = out[r, c]
                q = deque([(r, c)])
                seen[r, c] = True
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w:
                            if not seen[ny, nx] and out[ny, nx] == col:
                                seen[ny, nx] = True
                                q.append((ny, nx))
                comps.append((col, cells))

    # For each component, find the largest downward shift that does not
    # overlap any other component's original cells or leave the grid.
    occupied = np.zeros((h, w), dtype=bool)
    for _, cells in comps:
        for y, x in cells:
            occupied[y, x] = True

    moves = []
    for col, cells in comps:
        own = np.zeros((h, w), dtype=bool)
        for y, x in cells:
            own[y, x] = True

        max_shift = 0
        for y, x in cells:
            max_shift = max(max_shift, h - 1 - y)

        best = 0
        for s in range(max_shift + 1):
            ok = True
            for y, x in cells:
                ny = y + s
                if occupied[ny, x] and not own[ny, x]:
                    ok = False
                    break
            if ok:
                best = s
            else:
                break
        moves.append((best, col, cells))

    # Apply moves from bottom to top so lower objects are placed first.
    moves.sort(key=lambda t: (t[2][0][0], t[2][0][1]), reverse=True)
    for s, col, cells in moves:
        for y, x in cells:
            out[y, x] = 0
        for y, x in cells:
            out[y + s, x] = col

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # 7 is the fill/background colour.
    # Work with connected components of non-7 cells (4-neighbourhood).
    # A component is erased (set to 7) iff:
    #   1) it is a solid rectangle (its cells exactly fill its bounding box), and
    #   2) it is not "anchored" to the top or left border.
    # In the examples, anchored solid rectangles are kept; unanchored solid
    # rectangles are erased.  Non-rectangular components are always kept.
    seen = np.zeros((h, w), dtype=bool)

    for r in range(h):
        for c in range(w):
            if seen[r, c] or g[r, c] == 7:
                continue

            q = deque([(r, c)])
            seen[r, c] = True
            cells = [(r, c)]
            min_r = max_r = r
            min_c = max_c = c

            while q:
                y, x = q.popleft()
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w:
                        if not seen[ny, nx] and g[ny, nx] != 7:
                            seen[ny, nx] = True
                            cells.append((ny, nx))
                            if ny < min_r:
                                min_r = ny
                            if ny > max_r:
                                max_r = ny
                            if nx < min_c:
                                min_c = nx
                            if nx > max_c:
                                max_c = nx

            bbox_area = (max_r - min_r + 1) * (max_c - min_c + 1)
            is_solid_rectangle = (len(cells) == bbox_area)

            # Erase only unanchored solid rectangles.
            if is_solid_rectangle and min_r > 0 and min_c > 0:
                for y, x in cells:
                    out[y, x] = 7

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])

    # The input contains a small connected 8-shape.  The output is the
    # XOR-superposition of a 2D Sierpinski/Pascal triangle generated from
    # every input 8-cell.  For a source at (sr, sc), a cell (r, c) is lit
    # iff, with a = |r - sr| and b = |c - sc|, the binomial coefficient
    # C(a + b, a) is odd.  By Lucas' theorem this is equivalent to
    # (a & b) == 0.
    out = [[0] * w for _ in range(h)]

    for r in range(h):
        for c in range(w):
            parity = 0
            for sr in range(h):
                for sc in range(w):
                    if grid[sr][sc] == 8:
                        a = abs(r - sr)
                        b = abs(c - sc)
                        if (a & b) == 0:
                            parity ^= 1
            out[r][c] = 8 if parity else 0

    return out

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    def is_pattern_block(r, c, color, kind):
        # kind 0: plus/edge-mid, kind 1: checkerboard/corners+center
        if r < 0 or c < 0 or r + 3 > h or c + 3 > w:
            return False
        if color in (0, 8, 9):
            return False
        for dr in range(3):
            for dc in range(3):
                if (dr + dc) % 2 == 0:
                    expected = color if kind == 1 else 0
                else:
                    expected = color if kind == 0 else 0
                if g[r + dr][c + dc] != expected:
                    return False
        return True

    def is_solid_block(r, c, color):
        if r < 0 or c < 0 or r + 3 > h or c + 3 > w:
            return False
        if color in (0, 8, 9):
            return False
        for dr in range(3):
            for dc in range(3):
                if g[r + dr][c + dc] != color:
                    return False
        return True

    def is_empty_block(r, c):
        if r < 0 or c < 0 or r + 3 > h or c + 3 > w:
            return False
        return bool(np.all(g[r:r + 3, c:c + 3] == 0))

    def set_pattern(r, c, color, kind):
        for dr in range(3):
            for dc in range(3):
                if (dr + dc) % 2 == 0:
                    out[r + dr][c + dc] = color if kind == 1 else 0
                else:
                    out[r + dr][c + dc] = color if kind == 0 else 0

    # Convert every solid 3x3 block into the plus pattern.
    for r in range(h - 2):
        for c in range(w - 2):
            for color in range(1, 10):
                if is_solid_block(r, c, color):
                    set_pattern(r, c, color, 0)
                    break

    # Find all 3x3 slots that are adjacent to the 8-wire network.
    wire = (g == 8)
    slots = []
    for r in range(h - 2):
        for c in range(w - 2):
            if not (is_empty_block(r, c) or
                    is_pattern_block(r, c, 0, 0) or
                    is_pattern_block(r, c, 0, 1)):
                continue
            # Check the 12 boundary cells around the 3x3 block.
            adj = False
            for dr in range(3):
                for dc in range(3):
                    rr, cc = r + dr, c + dc
                    for nr, nc in ((rr - 1, cc), (rr + 1, cc), (rr, cc - 1), (rr, cc + 1)):
                        if 0 <= nr < h and 0 <= nc < w and wire[nr, nc]:
                            adj = True
                            break
                    if adj:
                        break
                if adj:
                    break
            if adj:
                slots.append((r, c))

    # Pair slots by nearest compatible empty/pattern slot.
    used = set()
    for i, (r1, c1) in enumerate(slots):
        if i in used:
            continue
        best = None
        best_d = None
        for j, (r2, c2) in enumerate(slots):
            if j == i or j in used:
                continue
            d = abs(r1 - r2) + abs(c1 - c2)
            if best_d is None or d < best_d:
                best_d = d
                best = j
        if best is None:
            continue
        used.add(i)
        used.add(best)
        r2, c2 = slots[best]

        # Determine color and pattern kinds.
        color = None
        kind1 = None
        kind2 = None

        for k in (0, 1):
            if is_pattern_block(r1, c1, 0, k):
                color = g[r1 + 1][c1 + 1] if k == 1 else g[r1][c1 + 1]
                kind1 = k
                break
        for k in (0, 1):
            if is_pattern_block(r2, c2, 0, k):
                color = g[r2 + 1][c2 + 1] if k == 1 else g[r2][r2 + 1] if False else g[r2][c2 + 1]
                kind2 = k
                break

        if color is None:
            # If one side is empty, use the other side's color.
            for k in (0, 1):
                if is_pattern_block(r1, c1, 0, k):
                    color = g[r1 + 1][c1 + 1] if k == 1 else g[r1][c1 + 1]
                    kind1 = k
                    break
            for k in (0, 1):
                if is_pattern_block(r2, c2, 0, k):
                    color = g[r2 + 1][c2 + 1] if k == 1 else g[r2][c2 + 1]
                    kind2 = k
                    break

        if color is None:
            continue

        if kind1 is None:
            kind1 = 1 - kind2 if kind2 is not None else 0
        if kind2 is None:
            kind2 = 1 - kind1

        set_pattern(r1, c1, color, kind1)
        set_pattern(r2, c2, color, kind2)

    return out.tolist()

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    def is_solid(r, c, color):
        if r < 0 or c < 0 or r + 3 > h or c + 3 > w:
            return False
        if color in (0, 5, 8, 9):
            return False
        return bool(np.all(g[r:r + 3, c:c + 3] == color))

    def is_plus(r, c, color):
        if r < 0 or c < 0 or r + 3 > h or c + 3 > w:
            return False
        if color in (0, 5, 8, 9):
            return False
        return (g[r][c + 1] == color and
                g[r + 1][c] == color and
                g[r + 1][c + 2] == color and
                g[r + 2][c + 1] == color and
                g[r][c] == 0 and g[r][c + 2] == 0 and
                g[r + 1][c + 1] == 0 and
                g[r + 2][c] == 0 and g[r + 2][c + 2] == 0)

    def is_checker(r, c, color):
        if r < 0 or c < 0 or r + 3 > h or c + 3 > w:
            return False
        if color in (0, 5, 8, 9):
            return False
        return (g[r][c] == color and g[r][c + 2] == color and
                g[r + 1][c + 1] == color and
                g[r + 2][c] == color and g[r + 2][c + 2] == color and
                g[r][c + 1] == 0 and g[r + 1][c] == 0 and
                g[r + 1][c + 2] == 0 and g[r + 2][c + 1] == 0)

    def set_plus(r, c, color):
        out[r][c] = 0
        out[r][c + 1] = color
        out[r][c + 2] = 0
        out[r + 1][c] = color
        out[r + 1][c + 1] = 0
        out[r + 1][c + 2] = color
        out[r + 2][c] = 0
        out[r + 2][c + 1] = color
        out[r + 2][c + 2] = 0

    def set_checker(r, c, color):
        out[r][c] = color
        out[r][c + 1] = 0
        out[r][c + 2] = color
        out[r + 1][c] = 0
        out[r + 1][c + 1] = color
        out[r + 1][c + 2] = 0
        out[r + 2][c] = color
        out[r + 2][c + 1] = 0
        out[r + 2][c + 2] = color

    # Convert every solid 3x3 block into a plus block.
    for r in range(h - 2):
        for c in range(w - 2):
            for color in range(1, 10):
                if is_solid(r, c, color):
                    set_plus(r, c, color)
                    break

    # Find all 3x3 slots that are empty or already plus/checker.
    slots = []
    for r in range(h - 2):
        for c in range(w - 2):
            block = g[r:r + 3, c:c + 3]
            if bool(np.all(block == 0)):
                slots.append((r, c, None, None))
                continue
            for color in range(1, 10):
                if is_plus(r, c, color):
                    slots.append((r, c, color, 'plus'))
                    break
                if is_checker(r, c, color):
                    slots.append((r, c, color, 'checker'))
