    # Keep only slots adjacent to the 8-wire network.
    wire = (g == 8)
    adj_slots = []
    for r, c, color, kind in slots:
        adj = False
        for dr in range(3):
            for dc in range(3):
                rr, cc = r + dr, c + dc
                for nr, nc in ((rr - 1, cc), (rr + 1, cc), (rr, cc - 1), (rr, cc + 1)):
                    if 0 <= nr < h and 0 <= nc < w and wire[nr, nc]:
                        adj = True
                        break
                if adj:
                    break
            if adj:
                break
        if adj:
            adj_slots.append((r, c, color, kind))

    # Pair adjacent slots by nearest compatible slot.
    used = set()
    pairs = []
    for i, (r1, c1, col1, kind1) in enumerate(adj_slots):
