            continue
        best = None
        best_d = None
        for j, (r2, c2, col2, kind2) in enumerate(adj_slots):
            if j == i or j in used:
                continue
            d = abs(r1 - r2) + abs(c1 - c2)
            if best_d is None or d < best_d:
                best_d = d
                best = j
        if best is None:
            continue
        used.add(i)
        used.add(best)
        r2, c2, col2, kind2 = adj_slots[best]
        pairs.append((r1, c1, col1, kind1, r2, c2, col2, kind2))

    # For each pair, propagate the known color and set complementary patterns.
    for r1, c1, col1, kind1, r2, c2, col2, kind2 in pairs:
        color = col1 if col1 is not None else col2
        if color is None:
            continue

        # Decide which endpoint is plus and which is checker.
        # In all examples, the endpoint that is higher or, if same row, left is plus.
        if r1 < r2 or (r1 == r2 and c1 < c2):
            rp, cp = r1, c1
            rc, cc = r2, c2
        else:
            rp, cp = r2, c2
            rc, cc = r1, c1

        set_plus(rp, cp, color)
        set_checker(rc, cc, color)

    return out.tolist()

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Identify rectangular frame objects.
    # In all examples/tests, frames have border color 2 or 8.
    # Direction: border 8 moves left, border 2 moves right.
    objects = []
    for r in range(h):
        for c in range(w):
            if g[r, c] not in (2, 8):
                continue
            border = int(g[r, c])
            # Find connected component of this border color.
            stack = [(r, c)]
            comp = set()
            while stack:
                y, x = stack.pop()
                if (y, x) in comp:
                    continue
                if not (0 <= y < h and 0 <= x < w):
                    continue
                if g[y, x] != border:
                    continue
                comp.add((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    stack.append((y + dy, x + dx))

            ys = [y for y, x in comp]
            xs = [x for y, x in comp]
            y0, y1 = min(ys), max(ys)
            x0, x1 = min(xs), max(xs)
            hh = y1 - y0 + 1
            ww = x1 - x0 + 1

            # Keep only clean rectangular frames:
            # all border cells are the border color, and the component is exactly the perimeter.
            if hh < 3 or ww < 3:
                continue
            if len(comp) != 2 * (hh + ww) - 4:
                continue
            ok = True
            for y in range(y0, y1 + 1):
                for x in range(x0, x1 + 1):
                    is_border = (y == y0 or y == y1 or x == x0 or x == x1)
                    if is_border:
                        if g[y, x] != border:
                            ok = False
                            break
                    else:
                        if g[y, x] == border:
                            ok = False
                            break
                if not ok:
                    break
            if not ok:
                continue

            objects.append({
                'y0': y0,
                'y1': y1,
                'x0': x0,
                'x1': x1,
                'w': ww,
                'h': hh,
                'border': border,
                'dir': -1 if border == 8 else 1,
                'cells': comp,
            })

    # If no objects are found, return unchanged.
    if not objects:
        return [[int(v) for v in row] for row in g]

    # Compute final x positions by sliding each object in its direction
    # until it is blocked by the grid edge or by another object.
    # Iterate to a fixed point; the puzzle instances are small and stable.
    final_x = {i: obj['x0'] for i, obj in enumerate(objects)}

    def overlaps(i, j, xi, xj):
        a, b = objects[i], objects[j]
        if a['y1'] < b['y0'] or b['y1'] < a['y0']:
            return False
        return not (xi + a['w'] <= xj or xj + b['w'] <= xi)

    changed = True
    while changed:
        changed = False
        for i, obj in enumerate(objects):
            d = obj['dir']
            x = final_x[i]
            if d == -1:
                # Move left as far as possible.
                while x > 0:
                    nx = x - 1
                    blocked = False
                    for j, other in enumerate(objects):
                        if i == j:
                            continue
                        if overlaps(i, j, nx, final_x[j]):
                            blocked = True
                            break
                    if blocked:
                        break
                    x = nx
            else:
                # Move right as far as possible.
                while x + obj['w'] < w:
                    nx = x + 1
                    blocked = False
                    for j, other in enumerate(objects):
                        if i == j:
                            continue
                        if overlaps(i, j, nx, final_x[j]):
                            blocked = True
                            break
                    if blocked:
                        break
                    x = nx
            if x != final_x[i]:
                final_x[i] = x
                changed = True

    # Build output.
    out = np.zeros((h, w), dtype=int)

    # Copy all non-frame pixels from the input.
    frame_cells = set()
    for obj in objects:
        frame_cells.update(obj['cells'])
    for y in range(h):
        for x in range(w):
            if (y, x) not in frame_cells:
                out[y, x] = g[y, x]

    # Paste each object at its final position.
    for i, obj in enumerate(objects):
        x = final_x[i]
        y0, y1 = obj['y0'], obj['y1']
        wobj = obj['w']
        border = obj['border']

        # Copy interior from original object.
        for y in range(y0 + 1, y1):
            for dx in range(1, wobj - 1):
                out[y, x + dx] = g[y, obj['x0'] + dx]

        # Draw border.
        for dx in range(wobj):
            out[y0, x + dx] = border
            out[y1, x + dx] = border
        for dy in range(obj['h']):
            out[y0 + dy, x] = border
            out[y0 + dy, x + wobj - 1] = border

    return [[int(v) for v in row] for row in out]

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
