    # Frames have border color 2 or 8 and a rectangular perimeter.
    objects = []
    for r in range(h):
        for c in range(w):
            if g[r, c] not in (2, 8):
                continue
            border = int(g[r, c])

            # Connected component of this border color.
            stack = [(r, c)]
