                comp.add((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    stack.append((y + dy, x + dx))

            ys = [y for y, _ in comp]
            xs = [x for _, x in comp]
            y0, y1 = min(ys), max(ys)
            x0, x1 = min(xs), max(xs)
            hh = y1 - y0 + 1
            ww = x1 - x0 + 1

            if hh < 3 or ww < 3:
                continue

