            if len(comp) != 2 * (hh + ww) - 4:
                continue

            ok = True
            for y in range(y0, y1 + 1):
                for x in range(x0, x1 + 1):
                    is_border = (y == y0 or y == y1 or x == x0 or x == x1)
                    if is_border:
                        if g[y, x] != border:
                            ok = False
                            break
                    else:
                        if g[y, x] == border:
                            ok = False
                            break
                if not ok:
                    break
            if not ok:
                continue

            objects.append({
                'y0': y0,
                'y1': y1,
                'x0': x0,
                'x1': x1,
                'w': ww,
                'h': hh,
                'border': border,
                'dir': -1 if border == 8 else 1,
                'cells': comp,
            })

    if not objects:
        return [[int(v) for v in row] for row in g]

    # Pack border-8 objects to the left, border-2 objects to the right.
    # Objects of the same border color may not overlap.
    # Objects of different border colors do not block each other.
    final_x = {i: obj['x0'] for i, obj in enumerate(objects)}

    def same_group(i, j):
        return objects[i]['border'] == objects[j]['border']

    def overlaps(i, j, xi, xj):
        a, b = objects[i], objects[j]
        if a['y1'] < b['y0'] or b['y1'] < a['y0']:
            return False
        return not (xi + a['w'] <= xj or xj + b['w'] <= xi)

    changed = True
    while changed:
        changed = False
        for i, obj in enumerate(objects):
            d = obj['dir']
            x = final_x[i]

            if d == -1:
