                        if overlaps(i, j, nx, final_x[j]):
                            blocked = True
                            break
                    if blocked:
                        break
                    x = nx
            else:
                # Move right as far as possible.
                while x + obj['w'] < w:
                    nx = x + 1
                    blocked = False
                    for j, other in enumerate(objects):
                        if i == j or not same_group(i, j):
                            continue
                        if overlaps(i, j, nx, final_x[j]):
                            blocked = True
                            break
                    if blocked:
                        break
                    x = nx

            if x != final_x[i]:
                final_x[i] = x
                changed = True

    # Build output.
    out = np.zeros((h, w), dtype=int)

    # Copy all non-frame pixels from the input.
    frame_cells = set()
    for obj in objects:
        frame_cells.update(obj['cells'])

    for y in range(h):
        for x in range(w):
            if (y, x) not in frame_cells:
                out[y, x] = g[y, x]

    # Paste each object at its final position.
    for i, obj in enumerate(objects):
        x = final_x[i]
        y0, y1 = obj['y0'], obj['y1']
        wobj = obj['w']
        border = obj['border']

        # Copy interior from original object.
        for y in range(y0 + 1, y1):
            for dx in range(1, wobj - 1):
                out[y, x + dx] = g[y, obj['x0'] + dx]

        # Draw border.
        for dx in range(wobj):
            out[y0, x + dx] = border
            out[y1, x + dx] = border
        for dy in range(obj['h']):
            out[y0 + dy, x] = border
            out[y0 + dy, x + wobj - 1] = border

    return [[int(v) for v in row] for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    import sys
    from collections import deque

    sys.setrecursionlimit(1000000)

    h = len(grid)
    w = len(grid[0])
    out = [row[:] for row in grid]

    # The fill colour is the colour that forms the walls.
    # In all examples/tests it is 7.
    wall = 7

    # Treat the outside of the grid as one extra background component.
    # A non-wall component is filled iff it is enclosed by wall cells
    # (i.e. it does not touch the outside component).
    visited = [[False] * w for _ in range(h)]
    outside = [[False] * w for _ in range(h)]

    def neighbors(r, c):
        if r - 1 >= 0:
            yield r - 1, c
        if r + 1 < h:
            yield r + 1, c
        if c - 1 >= 0:
            yield r, c - 1
        if c + 1 < w:
            yield r, c + 1

    # BFS over all non-wall cells, including a virtual outside node.
    # The virtual outside is connected to all non-wall border cells.
    q = deque()
    q.append((-1, -1))  # virtual outside
    outside_visited = True

    # Start from all border non-wall cells as part of the outside component.
    for r in range(h):
        for c in (0, w - 1):
            if not visited[r][c] and grid[r][c] != wall:
                visited[r][c] = True
                outside[r][c] = True
                q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if not visited[r][c] and grid[r][c] != wall:
                visited[r][c] = True
                outside[r][c] = True
                q.append((r, c))

    while q:
        r, c = q.popleft()
        for nr, nc in neighbors(r, c):
            if 0 <= nr < h and 0 <= nc < w:
                if not visited[nr][nc] and grid[nr][nc] != wall:
                    visited[nr][nc] = True
                    outside[nr][nc] = True
                    q.append((nr, nc))

    # Fill every enclosed non-wall component with the wall colour.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != wall and not outside[r][c]:
                out[r][c] = wall

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])
    out = [row[:] for row in grid]

    WALL = 7
    visited = [[False] * w for _ in range(h)]

    def neighbors(r, c):
        if r > 0:
            yield r - 1, c
        if r + 1 < h:
            yield r + 1, c
        if c > 0:
            yield r, c - 1
        if c + 1 < w:
            yield r, c + 1

    for r in range(h):
        for c in range(w):
            if visited[r][c] or grid[r][c] == WALL:
                continue

            # Flood-fill one non-wall component.
            cells = []
            stack = [(r, c)]
            visited[r][c] = True

            while stack:
                cr, cc = stack.pop()
                cells.append((cr, cc))
                for nr, nc in neighbors(cr, cc):
                    if not visited[nr][nc] and grid[nr][nc] != WALL:
                        visited[nr][nc] = True
                        stack.append((nr, nc))

            # Keep only components that form a full rectangle.
            rmin = min(r0 for r0, _ in cells)
            rmax = max(r0 for r0, _ in cells)
            cmin = min(c0 for _, c0 in cells)
            cmax = max(c0 for _, c0 in cells)

            height = rmax - rmin + 1
            width = cmax - cmin + 1
            if len(cells) != height * width:
                continue

            # Fill landscape (or square) rectangular rooms that contain both 6 and 8.
            if width >= height:
                vals = {grid[cr][cc] for cr, cc in cells}
                if 6 in vals and 8 in vals:
                    for cr, cc in cells:
                        out[cr][cc] = WALL

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    out = g.copy()

    band_rows = [1, 8, 13, 18, 23]
    slot_cols = [2, 7, 12, 17]

    def slot_key(br, sc):
        block = g[br:br + 3, sc:sc + 3]
        mask = (block != 8) & (block != 3)
        if not mask.any():
            return None
        color = int(block[mask][0])
        return (tuple(map(tuple, mask.astype(int))), color)

    # Keys from the first band.
    keys = []
    for sc in slot_cols:
        k = slot_key(band_rows[0], sc)
        if k is not None:
            keys.append(k)

    active = [[False] * 4 for _ in range(5)]

    # Activate matching slots in bands 1..4.
    for b in range(1, 5):
        for s in range(4):
            k = slot_key(band_rows[b], slot_cols[s])
            if k is not None and k in keys:
                active[b][s] = True

    # If 3 appears in the input, activate the whole first band.
    if (g == 3).any():
        for s in range(4):
            active[0][s] = True

    # Paint 5x5 neighborhoods of active slots with 3s.
    for b, br in enumerate(band_rows):
        for s, sc in enumerate(slot_cols):
            if not active[b][s]:
                continue
            r0, r1 = br - 1, br + 3
            c0, c1 = sc - 1, sc + 3
            r0 = max(0, r0)
            r1 = min(out.shape[0], r1)
            c0 = max(0, c0)
            c1 = min(out.shape[1], c1)
            region = out[r0:r1, c0:c1]
            region[region == 8] = 3

    # Fill the bottom two rows.
    bottom_color = 3 if (g == 3).any() else 2
    out[-2:, :] = bottom_color

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    H, W = g.shape

    # background is the most common colour
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # find the main object: the largest connected component of non-background cells
    nonbg = g != bg
    seen = np.zeros_like(nonbg, dtype=bool)
    best = None
    best_size = -1

    for r in range(H):
        for c in range(W):
            if nonbg[r, c] and not seen[r, c]:
                stack = [(r, c)]
                seen[r, c] = True
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < H and 0 <= nx < W and nonbg[ny, nx] and not seen[ny, nx]:
                                seen[ny, nx] = True
                                stack.append((ny, nx))
                if len(cells) > best_size:
                    best_size = len(cells)
                    best = cells

    if best is None:
        return [list(row) for row in g]

    ys = [p[0] for p in best]
    xs = [p[1] for p in best]
    r0, r1 = min(ys), max(ys)
    c0, c1 = min(xs), max(xs)
    h = r1 - r0 + 1
    w = c1 - c0 + 1

    # main shape mask and colour
    shape = np.zeros((h, w), dtype=int)
    for y, x in best:
        shape[y - r0, x - c0] = 1
    main_color = int(g[r0, c0])

    # scattered pixels: all non-background cells not in the main component
    scattered = []
    for r in range(H):
        for c in range(W):
            if nonbg[r, c] and not seen[r, c]:
                scattered.append((r, c, int(g[r, c])))

    out = np.full((H, W), bg, dtype=int)

    # If there are scattered pixels, use them as a sparse instruction pattern.
    if scattered:
        sr = [p[0] for p in scattered]
        sc = [p[1] for p in scattered]
        sr0, sr1 = min(sr), max(sr)
        sc0, sc1 = min(sc), max(sc)
        sh = sr1 - sr0 + 1
        sw = sc1 - sc0 + 1

        # The instruction pattern is a 4x3 template in the examples.
        # Place the main shape at the top-left of the instruction bounding box,
        # recoloured to the colour of the scattered centre/first pixel.
        # Then place a second copy shifted by the instruction height.
        # The large pattern is generated by tiling the main shape horizontally
        # according to the instruction width, with background gaps where the
        # instruction pattern has no pixels.
        inst_color = scattered[0][2]

        # Build a 4x3 instruction mask from scattered pixels, normalised to
        # the 4x3 grid used by the puzzle.
        inst = np.zeros((4, 3), dtype=int)
        for r, c, col in scattered:
            # map to 4x3 by proportional position
            ir = min(3, max(0, int((r - sr0) * 4 / max(1, sh))))
            ic = min(2, max(0, int((c - sc0) * 3 / max(1, sw))))
            inst[ir, ic] = col

        # Determine the dominant non-background instruction colour
        inst_colors = inst[inst != 0]
        if len(inst_colors):
            inst_color = int(np.bincount(inst_colors).argmax())

        # Place recoloured main shape at original location
        for i in range(h):
            for j in range(w):
                if shape[i, j]:
                    out[r0 + i, c0 + j] = inst_color

        # Place a second copy shifted down by 4
        for i in range(h):
            for j in range(w):
                if shape[i, j]:
                    nr, nc = r0 + i + 4, c0 + j
                    if 0 <= nr < H and 0 <= nc < W:
                        out[nr, nc] = main_color

        # Large pattern: 4 rows by 3*w columns, starting above/left of main shape
        pr0 = max(0, r0 - 4)
        pc0 = max(0, c0 - 3)
        for i in range(4):
            for block in range(3):
                # if instruction row has any pixel in this block, fill with main_color
                if np.any(inst[i, block:block + 1]):
                    for j in range(w):
                        if shape[i % h, j]:
                            nr = pr0 + i
                            nc = pc0 + block * w + j
                            if 0 <= nr < H and 0 <= nc < W:
                                out[nr, nc] = main_color
    else:
        # Fallback: copy main shape unchanged
        for i in range(h):
            for j in range(w):
                if shape[i, j]:
                    out[r0 + i, c0 + j] = main_color

    return [list(row) for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape
    key = int(g[0, 0])

    # Find all maximal rectangular frames.
    # A frame is a rectangle whose border cells are non-zero and whose
    # interior cells are all zero.
    frames = []
    for r0 in range(h):
        for c0 in range(w):
            if g[r0, c0] == 0:
                continue
            for r1 in range(r0, h):
                for c1 in range(c0, w):
                    if (g[r0, c1] != 0 and
                        g[r1, c0] != 0 and
                        g[r1, c1] != 0):
                        ok = True
                        # top and bottom borders
                        for c in range(c0, c1 + 1):
                            if g[r0, c] == 0 or g[r1, c] == 0:
                                ok = False
                                break
                        if not ok:
                            continue
                        # left and right borders
                        for r in range(r0, r1 + 1):
                            if g[r, c0] == 0 or g[r, c1] == 0:
                                ok = False
                                break
                        if not ok:
                            continue
                        # interior must be empty
                        if r1 > r0 + 1 and c1 > c0 + 1:
                            interior = g[r0 + 1:r1, c0 + 1:c1]
                            if np.any(interior != 0):
                                continue
                        frames.append((r0, c0, r1, c1))

    # Keep only maximal frames: remove any frame fully contained in another.
    maximal = []
    for f in frames:
        r0, c0, r1, c1 = f
        contained = False
        for o in frames:
            if o == f:
                continue
            or0, oc0, or1, oc1 = o
            if or0 <= r0 and oc0 <= c0 and or1 >= r1 and oc1 >= c1:
                contained = True
                break
        if not contained:
            maximal.append(f)

    # If the key color is not present anywhere except the top-left marker,
    # nothing changes.
    if not np.any(g[1:, :] == key) and not np.any(g[:, 1:] == key):
        return [[int(x) for x in row] for row in g]

    # Determine the vertical shift.
    # In the examples, when the key color is present, the shift is 3.
    shift = 3

    out = np.zeros((h, w), dtype=int)
    out[0, 0] = key

    # Draw all maximal frames after shifting them down by `shift`.
    # Cells that fall outside the grid are discarded.
    for r0, c0, r1, c1 in maximal:
        nr0 = r0 + shift
        nr1 = r1 + shift
        if nr1 < 0 or nr0 >= h:
            continue
        # Clip to grid.
        dr0 = max(0, nr0)
        dr1 = min(h - 1, nr1)
        if dr0 > dr1:
            continue

        # Top border: only if the original top row is visible after shift.
        if nr0 >= 0 and nr0 <= h - 1:
            for c in range(c0, c1 + 1):
                out[nr0, c] = g[r0, c]

        # Bottom border: only if the original bottom row is visible after shift.
        if nr1 >= 0 and nr1 <= h - 1:
            for c in range(c0, c1 + 1):
                out[nr1, c] = g[r1, c]

        # Left border: rows between top and bottom, clipped.
        for r in range(max(r0 + 1, nr0), min(r1, nr1) + 1):
            out[r, c0] = g[r - shift, c0]

        # Right border: rows between top and bottom, clipped.
        for r in range(max(r0 + 1, nr0), min(r1, nr1) + 1):
            out[r, c1] = g[r - shift, c1]

    # Remove all cells of the key color except the top-left marker.
    out[out == key] = 0
    out[0, 0] = key

    return [[int(x) for x in row] for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # 7 is the fill/wall colour.  Work on non-7 cells.
    non7 = g != 7

    # Connected components of non-7 cells (4-neighbourhood).
    comp = np.zeros((h, w), dtype=int)
    cid = 0
    for r in range(h):
        for c in range(w):
            if non7[r, c] and comp[r, c] == 0:
                cid += 1
                stack = [(r, c)]
                comp[r, c] = cid
                while stack:
                    y, x = stack.pop()
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w:
                            if non7[ny, nx] and comp[ny, nx] == 0:
                                comp[ny, nx] = cid
                                stack.append((ny, nx))

    # For each component, find its bounding box.
    boxes = {}
    for r in range(h):
        for c in range(w):
            if non7[r, c]:
                k = comp[r, c]
                if k not in boxes:
                    boxes[k] = [r, r, c, c]
                else:
                    b = boxes[k]
                    if r < b[0]: b[0] = r
                    if r > b[1]: b[1] = r
                    if c < b[2]: b[2] = c
                    if c > b[3]: b[3] = c

    # A component is kept if its bounding box is "anchored" to the top or left
    # border, or if it is a 1-cell-wide vertical strip anchored to the bottom.
    keep = set()
    for k, (r0, r1, c0, c1) in boxes.items():
        if r0 == 0 or c0 == 0:
            keep.add(k)
        elif c1 - c0 == 0 and r1 == h - 1:
            keep.add(k)

    out = g.copy()
    for r in range(h):
        for c in range(w):
            if non7[r, c] and comp[r, c] not in keep:
                out[r, c] = 7

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Non-7 cells are the "objects". 7 is the fill colour.
    obj = g != 7

    # 4-connected components of non-7 cells.
    comp = np.zeros((h, w), dtype=int)
    cid = 0
    for r in range(h):
        for c in range(w):
            if obj[r, c] and comp[r, c] == 0:
                cid += 1
                stack = [(r, c)]
                comp[r, c] = cid
                while stack:
                    y, x = stack.pop()
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w:
                            if obj[ny, nx] and comp[ny, nx] == 0:
                                comp[ny, nx] = cid
                                stack.append((ny, nx))

    # Bounding boxes of each component.
    boxes = {}
    for r in range(h):
        for c in range(w):
            if obj[r, c]:
                k = comp[r, c]
                if k not in boxes:
                    boxes[k] = [r, r, c, c]
                else:
                    b = boxes[k]
                    if r < b[0]:
                        b[0] = r
                    if r > b[1]:
                        b[1] = r
                    if c < b[2]:
                        b[2] = c
                    if c > b[3]:
                        b[3] = c

    # Keep components that touch the top or bottom border.
    keep = set()
    for k, (r0, r1, c0, c1) in boxes.items():
        if r0 == 0 or r1 == h - 1:
            keep.add(k)

    # Also keep fully enclosed rectangular components that are taller than wide.
    for k, (r0, r1, c0, c1) in boxes.items():
        if k in keep:
            continue
        height = r1 - r0 + 1
        width = c1 - c0 + 1
        if height > width:
            sub = obj[r0:r1 + 1, c0:c1 + 1]
            if sub.all():
                keep.add(k)

    out = g.copy()
    for r in range(h):
        for c in range(w):
            if obj[r, c] and comp[r, c] not in keep:
                out[r, c] = 7

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    H, W = g.shape
    out = g.copy()

    def is_slot_color(v):
        return v not in (0, 5, 8, 9)

    def cross_cells(r, c):
        return [(r, c), (r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)]

    def set_cross(r, c, color):
        for rr, cc in cross_cells(r, c):
            if 0 <= rr < H and 0 <= cc < W:
                out[rr, cc] = color

    # Find top solid 3x3 blocks and bottom 3x3 crosses.
    top_inputs = {}
    bottom_inputs = {}
    top_centers = []
    bottom_centers = []

    for r in range(H - 2):
        for c in range(W - 2):
            block = g[r:r + 3, c:c + 3]
            if block.size and np.all(block == block[0, 0]) and is_slot_color(block[0, 0]):
                top_inputs[(r + 1, c + 1)] = int(block[0, 0])
                top_centers.append((r + 1, c + 1))

    for r in range(1, H - 1):
        for c in range(1, W - 1):
            if is_slot_color(g[r, c]) and g[r - 1, c] == 0 and g[r + 1, c] == 0 and g[r, c - 1] == 0 and g[r, c + 1] == 0:
                bottom_inputs[(r, c)] = int(g[r, c])
                bottom_centers.append((r, c))

    # If no top blocks were found, treat top crosses as top inputs.
    if not top_inputs:
        for (r, c), col in bottom_inputs.items():
            if r < H // 2:
                top_inputs[(r, c)] = col
                top_centers.append((r, c))
                del bottom_inputs[(r, c)]
                bottom_centers.remove((r, c))

    # Determine the four vertical slot columns from top/bottom centers.
    cols = sorted({c for _, c in top_centers + bottom_centers})
    if len(cols) >= 4:
        # Keep the four most evenly spaced columns if there are extras.
        best = None
        for i in range(len(cols) - 3):
            cand = cols[i:i + 4]
            gaps = [cand[j + 1] - cand[j] for j in range(3)]
            score = max(gaps) - min(gaps)
            if best is None or score < best[0]:
                best = (score, cand)
        cols = best[1]
    elif len(cols) == 3:
        # Infer missing column from regular spacing.
        diffs = [cols[1] - cols[0], cols[2] - cols[1]]
        d = diffs[0] if diffs[0] == diffs[1] else (diffs[0] + diffs[1]) // 2
        if d > 0:
            if cols[0] - d >= 0:
                cols = [cols[0] - d] + cols
            else:
                cols = cols + [cols[2] + d]
    elif len(cols) == 2:
        d = cols[1] - cols[0]
        if d > 0:
            if cols[0] - d >= 0:
                cols = [cols[0] - d, cols[0], cols[1], cols[1] + d]
            else:
                cols = [cols[0] - 2 * d, cols[0] - d, cols[0], cols[1]]
    else:
        return out.tolist()

    # Find top and bottom endpoint rows for the central 8-network.
    top_row = None
    bottom_row = None
    for r in range(H):
        if all(0 <= c < W and g[r, c] == 8 for c in cols):
            top_row = r
            break
    for r in range(H - 1, -1, -1):
        if all(0 <= c < W and g[r, c] == 8 for c in cols):
            bottom_row = r
            break

    if top_row is None or bottom_row is None or bottom_row <= top_row:
        # Fallback: no central network; just convert solid blocks to crosses.
        for (r, c), col in top_inputs.items():
            set_cross(r, c, col)
        for (r, c), col in bottom_inputs.items():
            set_cross(r, c, col)
        return out.tolist()

    # Build graph of the central network. 8 is wire; 5/9 are passable markers.
    wire = np.zeros((H, W), dtype=bool)
    wire[top_row:bottom_row + 1, :] = (g[top_row:bottom_row + 1, :] == 8) | (g[top_row:bottom_row + 1, :] == 5) | (g[top_row:bottom_row + 1, :] == 9)

    adj = {}
    for r in range(top_row, bottom_row + 1):
        for c in range(W):
            if not wire[r, c]:
                continue
            nb = []
            for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                rr, cc = r + dr, c + dc
                if top_row <= rr <= bottom_row and 0 <= cc < W and wire[rr, cc]:
                    nb.append((rr, cc))
            adj[(r, c)] = nb

    def bfs(start):
        seen = {start}
        q = deque([start])
        while q:
            cur = q.popleft()
            for nb in adj.get(cur, []):
                if nb not in seen:
                    seen.add(nb)
                    q.append(nb)
        return seen

    # Map each top slot to the bottom slot in its connected component.
    top_to_bottom = {}
    for i, c in enumerate(cols):
        comp = bfs((top_row, c))
        for j, cb in enumerate(cols):
            if (bottom_row, cb) in comp:
                top_to_bottom[i] = j
                break

    # If the network is not a clean permutation, fall back to identity.
    if len(top_to_bottom) != len(cols) or len(set(top_to_bottom.values())) != len(cols):
        top_to_bottom = {i: i for i in range(len(cols))}

    # Convert all top solid blocks to crosses in place.
    for (r, c), col in top_inputs.items():
        set_cross(r, c, col)

    # Keep bottom input crosses in place.
    for (r, c), col in bottom_inputs.items():
        set_cross(r, c, col)

    # Route top inputs to bottom slots.
    for (r, c), col in top_inputs.items():
        # Find nearest slot index by column.
        i = min(range(len(cols)), key=lambda k: abs(cols[k] - c))
        j = top_to_bottom[i]
        set_cross(bottom_row + 1, cols[j], col)

    # Route bottom inputs to top slots using inverse mapping.
    bottom_to_top = {v: k for k, v in top_to_bottom.items()}
    for (r, c), col in bottom_inputs.items():
        j = min(range(len(cols)), key=lambda k: abs(cols[k] - c))
        i = bottom_to_top.get(j, j)
        set_cross(top_row - 1, cols[i], col)

    return out.tolist()

