    bottom_sources = []
    for r in range(1, H - 1):
        for c in range(1, W - 1):
            v = g[r, c]
            if (is_source_color(v)
                    and g[r - 1, c] == 0 and g[r + 1, c] == 0
                    and g[r, c - 1] == 0 and g[r, c + 1] == 0):
                bottom_sources.append((r, c, int(v)))

