        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            rr, cc = r + dr, c + dc
            if 0 <= rr < H and 0 <= cc < W and passable[rr, cc]:
                yield rr, cc

    def bfs(start):
        seen = {start}
        q = deque([start])
        while q:
            cur = q.popleft()
            for nb in neighbors(*cur):
                if nb not in seen:
                    seen.add(nb)
                    q.append(nb)
        return seen

    # Entry point for a top source: first passable cell below its center.
    def top_entry(r, c):
        for rr in range(r + 1, H):
            if passable[rr, c]:
                return (rr, c)
        return None

    # Entry point for a bottom source: first passable cell above its center.
    def bottom_entry(r, c):
        for rr in range(r - 1, -1, -1):
            if passable[rr, c]:
                return (rr, c)
        return None

    # Exit column for a component on the opposite side.
    def exit_col(comp, side):
        if side == 'bottom':
            cells = [p for p in comp if p[0] == bottom_row]
        else:
            cells = [p for p in comp if p[0] == top_row]
        if not cells:
            return None
        # Prefer the column closest to the source column if multiple exist.
        return min(cells, key=lambda p: abs(p[1] - src_col))[1]

    # Route top sources to bottom.
    for r, c, v in top_sources:
        entry = top_entry(r, c)
        if entry is None:
            continue
        comp = bfs(entry)
        col = exit_col(comp, 'bottom')
        if col is not None:
            set_cross(bottom_row + 2, col, v)

    # Route bottom sources to top.
    for r, c, v in bottom_sources:
        entry = bottom_entry(r, c)
        if entry is None:
            continue
        comp = bfs(entry)
        col = exit_col(comp, 'top')
        if col is not None:
