    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Background is the most frequent colour.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # Non-background colours, ordered by first appearance in row-major order.
    active = []
    for r in range(h):
        for c in range(w):
            v = int(g[r, c])
            if v != bg and v not in active:
                active.append(v)

    # Connected components of non-background cells (4-connectivity).
    seen = np.zeros((h, w), dtype=bool)
    comps = []
    for r in range(h):
        for c in range(w):
            if g[r, c] != bg and not seen[r, c]:
                stack = [(r, c)]
                seen[r, c] = True
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w:
                            if not seen[ny, nx] and g[ny, nx] != bg:
                                seen[ny, nx] = True
                                stack.append((ny, nx))
                comps.append(cells)

    out = g.copy()

    for cells in comps:
        if len(cells) < 3:
            continue

        ys = [r for r, _ in cells]
        xs = [c for _, c in cells]
        rmin, rmax = min(ys), max(ys)
        cmin, cmax = min(xs), max(xs)

        # The "cap" is the top part of the object, up to the last row
        # that contains colour 1.
        cap_last = rmin
        for r in range(rmin, rmax + 1):
            if any(g[r, c] == 1 for c in range(cmin, cmax + 1)):
                cap_last = r

        # Core colour: non-1 colour inside the cap.
        core = None
        for r in range(rmin, cap_last + 1):
            for c in range(cmin, cmax + 1):
                v = int(g[r, c])
                if v != bg and v != 1:
                    core = v
                    break
            if core is not None:
                break

        # Tail: non-background cells below the cap.
        tail = [(r, c) for r, c in cells if r > cap_last]
        if core is None or not tail:
            continue

        # Choose the replacement colour:
        # - if the tail already contains the core colour, use the first
        #   active colour not present in the component;
        # - otherwise use the first active colour not equal to the core.
        comp_colors = {int(g[r, c]) for r, c in cells}
        tail_colors = {int(g[r, c]) for r, c in tail}

        if core in tail_colors:
            repl = None
            for v in active:
                if v not in comp_colors:
                    repl = v
                    break
            if repl is None:
                repl = core
        else:
            repl = None
            for v in active:
                if v != core:
                    repl = v
                    break
            if repl is None:
                repl = core

        for r, c in tail:
            out[r, c] = repl

    return out.tolist()

