def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Find the unique starting 3.
    starts = np.argwhere(g == 3)
    if len(starts) != 1:
        return g.tolist()
    sr, sc = map(int, starts[0])

    # Find all 1/2 line cells.
    line_cells = np.argwhere((g == 1) | (g == 2))
    if len(line_cells) == 0:
        return g.tolist()

    # Determine whether the non-8/3 line cells are mostly vertical or horizontal.
    rows = line_cells[:, 0]
    cols = line_cells[:, 1]
    vertical = (rows.max() - rows.min()) >= (cols.max() - cols.min())

    # Build the 3-path.
    out = g.copy()
    out[sr, sc] = 3

    if vertical:
        # Two vertical line segments.
        # Group by column.
        col_groups = {}
        for r, c in line_cells:
            col_groups.setdefault(int(c), []).append(int(r))

        # Sort groups by column.
        c1 = min(col_groups)
        c2 = max(col_groups)
        if c1 == c2:
            return out.tolist()

        r1s = sorted(col_groups[c1])
        r2s = sorted(col_groups[c2])
        r1_min, r1_max = r1s[0], r1s[-1]
        r2_min, r2_max = r2s[0], r2s[-1]

        # The path starts at the 3 and goes horizontally to the right edge,
        # with a rectangular detour between the two vertical lines.
        # Left detour column: just left of the first vertical line.
        # Right detour column: just left of the second vertical line.
        # Bottom row: below the first line and above/inside the second line.
        left_col = max(0, c1 - 2)
        right_col = max(left_col + 1, c2 - 2)
        bottom_row = min(h - 1, max(r1_max + 2, r2_min + 1))

        # Draw path:
        # start -> right to left_col
        for c in range(sc, left_col + 1):
            out[sr, c] = 3
        # down to bottom_row
        for r in range(sr, bottom_row + 1):
            out[r, left_col] = 3
        # right to right_col
        for c in range(left_col, right_col + 1):
            out[bottom_row, c] = 3
        # up to start row
        for r in range(bottom_row, sr - 1, -1):
            out[r, right_col] = 3
        # right to edge
        for c in range(right_col, w):
            out[sr, c] = 3

    else:
        # Horizontal line segment(s).
        # Group by row.
        row_groups = {}
        for r, c in line_cells:
            row_groups.setdefault(int(r), []).append(int(c))

        # Choose the row closest to the start row (or the only row).
        target_row = min(row_groups, key=lambda r: abs(r - sr))
        cs = sorted(row_groups[target_row])
        c_min, c_max = cs[0], cs[-1]

        # The path goes from the start down/up to a row above/below the line,
        # then horizontally to a column left of the line, then to the line row.
        # In the examples, the horizontal connector is 2 rows away from the line.
        if target_row > sr:
            mid_row = max(sr, target_row - 5)
        else:
            mid_row = min(h - 1, target_row + 5)

        left_col = max(0, c_min - 5)

        # Draw vertical from start to mid_row at start column.
        if mid_row >= sr:
            for r in range(sr, mid_row + 1):
                out[r, sc] = 3
        else:
            for r in range(sr, mid_row - 1, -1):
                out[r, sc] = 3

        # Draw horizontal from start column to left_col at mid_row.
        if left_col <= sc:
            for c in range(left_col, sc + 1):
                out[mid_row, c] = 3
        else:
            for c in range(sc, left_col + 1):
                out[mid_row, c] = 3

        # Draw vertical from mid_row to target_row at left_col.
        if target_row >= mid_row:
            for r in range(mid_row, target_row + 1):
                out[r, left_col] = 3
        else:
            for r in range(mid_row, target_row - 1, -1):
                out[r, left_col] = 3

    # Convert all 1s to 2s, except if a 1 is directly adjacent to the new 3 path
    # in the horizontal-line case (matching Example 2's leftmost 1 erasure).
    if not vertical:
        # Erase a 1 if it is immediately to the right of the final 3 endpoint
        # and was the leftmost 1 in its row.
        endpoint_r = target_row
        endpoint_c = left_col
        for r, c in line_cells:
            r, c = int(r), int(c)
            if g[r, c] == 1 and r == endpoint_r and c == endpoint_c + 1:
                out[r, c] = 8
                break

    out[out == 1] = 2

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Locate the unique 3.
    starts = np.argwhere(g == 3)
    if len(starts) != 1:
        return g.tolist()
    sr, sc = int(starts[0][0]), int(starts[0][1])

    # All 1/2 cells are obstacles for the 3-path.
    blocked = (g == 1) | (g == 2)

    # Determine the target border: the border opposite the one containing the 3.
    if sr == 0:
        target = lambda r, c: r == h - 1
    elif sr == h - 1:
        target = lambda r, c: r == 0
    elif sc == 0:
        target = lambda r, c: c == w - 1
    elif sc == w - 1:
        target = lambda r, c: c == 0
    else:
        # Fallback: nearest border.
        target = lambda r, c: r in (0, h - 1) or c in (0, w - 1)

    # BFS with a small clearance from 1/2 cells.
    # The examples require the path to stay at least 2 cells away from obstacles
    # in the Chebyshev sense.
    def clear(r, c):
        if r < 0 or r >= h or c < 0 or c >= w:
            return False
        if blocked[r, c]:
            return False
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w and blocked[rr, cc]:
                    return False
        return True

    # If the start itself is not clear under the strict rule, relax locally.
    if not clear(sr, sc):
        def clear(r, c):
            if r < 0 or r >= h or c < 0 or c >= w:
                return False
            if blocked[r, c]:
                return False
            # Only forbid direct adjacency, not diagonal, as a fallback.
            for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w and blocked[rr, cc]:
                    return False
            return True

    # BFS from start to any target-border cell.
    q = deque([(sr, sc)])
    parent = {(sr, sc): None}
    found = None

    while q:
        r, c = q.popleft()
        if target(r, c) and (r, c) != (sr, sc):
            found = (r, c)
            break
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in parent and clear(nr, nc):
                parent[(nr, nc)] = (r, c)
                q.append((nr, nc))

    out = g.copy()

    # Reconstruct and draw the 3-path.
    if found is not None:
        path = []
        cur = found
        while cur is not None:
            path.append(cur)
            cur = parent[cur]
        path.reverse()
        for r, c in path:
            out[r, c] = 3

    # Normalize all 1s to 2s.
    out[out == 1] = 2

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Identify the background colour (most common colour).
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # The outline colour is the most common non-background colour.
    nonbg_counts = {}
    for v in vals:
        if int(v) != bg:
            nonbg_counts[int(v)] = int(counts[np.where(vals == v)[0][0]])
    outline = max(nonbg_counts, key=nonbg_counts.get)

    # The fill colour is the least common non-background colour.
    fill = min(nonbg_counts, key=nonbg_counts.get)

    # Flood-fill the background component that contains the fill seed(s).
    # The outline colour acts as a wall; all other non-background colours
    # are treated as passable but are not overwritten.
    out = g.copy()
    seen = np.zeros((H, W), dtype=bool)
    q = deque()

    for r in range(H):
        for c in range(W):
            if g[r, c] == fill:
                q.append((r, c))
                seen[r, c] = True

    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < H and 0 <= nc < W and not seen[nr, nc]:
                if g[nr, nc] == bg:
                    seen[nr, nc] = True
                    out[nr, nc] = fill
                    q.append((nr, nc))

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Background is the most common colour.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # Outline colour: most common non-background colour.
    # Fill colour: least common non-background colour.
    nonbg = {}
    for v, c in zip(vals, counts):
        v = int(v)
        if v != bg:
            nonbg[v] = int(c)

    outline = max(nonbg, key=nonbg.get)
    fill = min(nonbg, key=nonbg.get)

    # Collect outline cells.
    outline_cells = set()
    for r in range(H):
        for c in range(W):
            if g[r, c] == outline:
                outline_cells.add((r, c))

    if not outline_cells:
        return g.tolist()

    # 8-neighbourhood for the outline path.
    def neighbors8(p):
        r, c = p
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                q = (r + dr, c + dc)
                if 0 <= q[0] < H and 0 <= q[1] < W and q in outline_cells:
                    yield q

    # Find endpoints of the outline path (degree 1 in the 8-connected graph).
    endpoints = [p for p in outline_cells if len(list(neighbors8(p))) == 1]

    # If the outline is not a simple open path, fall back to flood fill
    # from the fill seed through non-outline cells.
    if len(endpoints) != 2:
        out = g.copy()
        seen = np.zeros((H, W), dtype=bool)
        q = deque()
        for r in range(H):
            for c in range(W):
                if g[r, c] == fill:
                    q.append((r, c))
                    seen[r, c] = True
        while q:
            r, c = q.popleft()
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < H and 0 <= nc < W and not seen[nr, nc]:
                    if g[nr, nc] != outline:
                        seen[nr, nc] = True
                        out[nr, nc] = fill
                        q.append((nr, nc))
        return out.tolist()

    # Order the path from one endpoint to the other.
    start, end = endpoints
    path = [start]
    prev = None
    cur = start
    while cur != end:
        nxt = None
        for nb in neighbors8(cur):
            if nb != prev:
                nxt = nb
                break
        if nxt is None:
            break
        prev, cur = cur, nxt
        path.append(cur)

    # Extend each endpoint outward along the reverse of its first step
    # until it hits the grid boundary.
    def extend_endpoint(p, nxt):
        dr = p[0] - nxt[0]
        dc = p[1] - nxt[1]
        pts = [p]
        r, c = p
        while True:
            nr, nc = r + dr, c + dc
            if not (0 <= nr < H and 0 <= nc < W):
                break
            r, c = nr, nc
            pts.append((r, c))
        return pts

    ext1 = extend_endpoint(path[0], path[1])
    ext2 = extend_endpoint(path[-1], path[-2])

    # Closed polygon: extended start -> path -> extended end -> boundary back to start.
    poly = ext1 + path[1:-1] + ext2

    # Add boundary segments connecting the two boundary endpoints.
    a = ext1[-1]
    b = ext2[-1]
    if a[0] == b[0]:
        r = a[0]
        c1, c2 = sorted((a[1], b[1]))
        for c in range(c1, c2 + 1):
            poly.append((r, c))
    elif a[1] == b[1]:
        c = a[1]
        r1, r2 = sorted((a[0], b[0]))
        for r in range(r1, r2 + 1):
            poly.append((r, c))
    else:
        # Should not happen for the intended puzzles; connect by a simple L-shape.
        poly.append((a[0], b[1]))
        poly.append(b)

    # Point-in-polygon test for cell centres using even-odd ray casting.
    def inside(r, c):
        x = c + 0.5
        y = r + 0.5
        ans = False
        n = len(poly)
        for i in range(n):
            x1, y1 = poly[i][1] + 0.5, poly[i][0] + 0.5
            x2, y2 = poly[(i + 1) % n][1] + 0.5, poly[(i + 1) % n][0] + 0.5
            if ((y1 > y) != (y2 > y)):
                xint = (x2 - x1) * (y - y1) / (y2 - y1) + x1
                if x < xint:
                    ans = not ans
        return ans

    out = g.copy()
    for r in range(H):
        for c in range(W):
            if g[r, c] == bg and inside(r, c):
                out[r, c] = fill

    return out.tolist()

