            elif dc == -1:
                sr, sc = r + (0 if dr == 0 else (0 if dr < 0 else 1)), c - 1
            else:
                sr, sc = r + (0 if dr == 0 else (0 if dr < 0 else 1)), c + 2

            rr, cc = sr, sc
            while 0 <= rr < H and 0 <= cc < W:
                if out[rr, cc] != bg:
                    break
                out[rr, cc] = v
                rr += dr
                cc += dc

    return out.tolist()

