def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Find the central 9x9 pattern: the 9x9 window containing the most non-8 cells.
    best = (-1, 0, 0)
    for r in range(h - 8):
        for c in range(w - 8):
            cnt = int(np.sum(g[r:r+9, c:c+9] != 8))
            if cnt > best[0]:
                best = (cnt, r, c)
    _, r0, c0 = best

    out = g.copy()

    # Extract the 8 non-center 3x3 blocks of the central 9x9.
    blocks = {}
    for i in range(3):
        for j in range(3):
            if i == 1 and j == 1:
                continue
            blocks[(i, j)] = g[r0 + 3*i:r0 + 3*i + 3,
                               c0 + 3*j:c0 + 3*j + 3].copy()

    # Determine the special color: the non-8 color appearing at the inner
    # corner/edge cells of the 8 blocks.
    special = None
    for (i, j), b in blocks.items():
        if i == 0:
            if j == 0:
                special = int(b[2, 2])
            elif j == 1:
                special = int(b[2, 1])
            else:
                special = int(b[2, 0])
        elif i == 1:
            if j == 0:
                special = int(b[1, 2])
            else:
                special = int(b[1, 0])
        else:
            if j == 0:
                special = int(b[0, 2])
            elif j == 1:
                special = int(b[0, 1])
            else:
                special = int(b[0, 0])

    # Determine the center fill color: the most frequent non-8, non-special
    # color in the central 9x9.
    central = g[r0:r0+9, c0:c0+9]
    vals, counts = np.unique(central[central != 8], return_counts=True)
    vals = vals[(vals != special)]
    center_color = int(vals[np.argmax(counts)])

    # Fill the central 3x3 hole.
    out[r0+3:r0+6, c0+3:c0+6] = special
    out[r0+4, c0+4] = center_color

    # Place 180-degree rotated copies of the 8 blocks around the central 9x9.
    for (i, j), b in blocks.items():
        rb = b[::-1, ::-1]
        if i == 0:
            nr = r0 - 3
        elif i == 1:
            nr = r0 + 3
        else:
            nr = r0 + 9

        if j == 0:
            nc = c0 - 3
        elif j == 1:
            nc = c0 + 3
        else:
            nc = c0 + 9

        out[nr:nr+3, nc:nc+3] = rb

    return out.tolist()

