def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Background is the most frequent colour.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # Candidate 2x2 payload blocks.
    blocks = []
    for r in range(h - 1):
        for c in range(w - 1):
            v = g[r, c]
            if v == bg:
                continue
            if g[r, c + 1] == v and g[r + 1, c] == v and g[r + 1, c + 1] == v:
                blocks.append((r, c, v))

    # For each block, find the wall colour in its 12-cell surrounding ring.
    # A valid object has at least one wall cell and no other non-background
    # colours in that ring.
    objects = []
    for r, c, v in blocks:
        ring = []
        for rr in range(r - 1, r + 2):
            for cc in range(c - 1, c + 2):
                if r - 1 <= rr <= r + 1 and c - 1 <= cc <= c + 1:
                    continue
                if 0 <= rr < h and 0 <= cc < w:
                    ring.append(g[rr, cc])

        nonbg = [x for x in ring if x != bg]
        if not nonbg:
            continue
        wall = nonbg[0]
        if any(x != wall for x in nonbg):
            continue
        if wall == v:
            continue

        objects.append((r, c, v, wall))

    # Directions and the ring cell(s) that start a ray in that direction.
    # For cardinal directions, each open side cell emits its own ray.
    # For diagonal directions, the open corner cell emits a diagonal ray.
    dirs = [
        (-1, 0), (0, -1), (0, 1), (1, 0),
        (-1, -1), (-1, 1), (1, -1), (1, 1),
    ]

    for r, c, v, wall in objects:
        starts = [
            [(r - 1, c), (r - 1, c + 1)],   # up
            [(r, c - 1), (r + 1, c - 1)],   # left
            [(r, c + 2), (r + 1, c + 2)],   # right
            [(r + 2, c), (r + 2, c + 1)],   # down
            [(r - 1, c - 1)],               # up-left
            [(r - 1, c + 2)],               # up-right
            [(r + 2, c - 1)],               # down-left
            [(r + 2, c + 2)],               # down-right
        ]

        for (dr, dc), cells in zip(dirs, starts):
