    # Stamp a 3x3 block of the opposite colour around each hole, with 8 in the centre.
    for y, x in holes:
        # Determine the surrounding colour for this hole.
        adj = set()
        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
