        fill = repl(c)

        for dy in (-1, 0, 1):
            for dx in (-1, 0, 1):
                ny, nx = y + dy, x + dx
                if 0 <= ny < h and 0 <= nx < w:
                    out[ny, nx] = 8 if (dy == 0 and dx == 0) else fill

    return out.tolist()

import numpy as np
from collections import Counter

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Determine the two main non-zero colours.
    vals, counts = np.unique(g[g != 0], return_counts=True)
    if len(vals) >= 2:
        order = np.argsort(-counts)
        c1, c2 = int(vals[order[0]]), int(vals[order[1]])
    elif len(vals) == 1:
        c1 = int(vals[0])
        c2 = 0
    else:
        c1 = c2 = 0

    def other(c: int) -> int:
        if c == c1:
            return c2
        if c == c2:
            return c1
        return 0

    out = g.copy()

    # 1) Remove thin / isolated non-zero pixels:
    #    if a non-zero cell has at most one orthogonal neighbour of its own colour,
    #    replace it by the majority colour among its in-bounds orthogonal neighbours.
    for r in range(h):
        for c in range(w):
            v = int(g[r, c])
            if v == 0:
                continue

            neigh = []
            for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w:
                    neigh.append(int(g[nr, nc]))

            cnt = Counter(neigh)
            own = cnt.get(v, 0)
            if own <= 1 and neigh:
                # Majority neighbour colour; ties prefer 0.
                best = max(cnt.items(), key=lambda x: (x[1], x[0] == 0))
                out[r, c] = best[0]

    # 2) Fill zero "holes" with a 3x3 motif:
    #    a zero cell whose in-bounds orthogonal neighbours are all the same non-zero
    #    colour becomes 8, and its in-bounds 8-neighbours become the other main colour.
    for r in range(h):
        for c in range(w):
            if g[r, c] != 0:
                continue

            neigh = []
            for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w:
                    neigh.append(int(g[nr, nc]))

            if not neigh:
                continue

            if len(set(neigh)) == 1:
                col = neigh[0]
                if col != 0:
                    fill = other(col)
                    for dr in (-1, 0, 1):
                        for dc in (-1, 0, 1):
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < h and 0 <= nc < w:
                                if dr == 0 and dc == 0:
                                    out[nr, nc] = 8
                                else:
                                    out[nr, nc] = fill

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    a = np.array(grid, dtype=int)
    h, w = a.shape

    # Work on a copy; only cells that are 5 may change.
    out = a.copy()

    # 8-connected components of 5s.
    seen = np.zeros((h, w), dtype=bool)
    for sr in range(h):
        for sc in range(w):
            if a[sr, sc] != 5 or seen[sr, sc]:
                continue

            # Collect component cells.
            stack = [(sr, sc)]
            seen[sr, sc] = True
            cells = []
            while stack:
                r, c = stack.pop()
                cells.append((r, c))
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < h and 0 <= nc < w:
                            if not seen[nr, nc] and a[nr, nc] == 5:
                                seen[nr, nc] = True
                                stack.append((nr, nc))

            # If the component has at least one enclosed background hole,
            # recolor it to 3; otherwise recolor it to 2.
            has_hole = False
            for r, c in cells:
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < h and 0 <= nc < w and a[nr, nc] == 0:
                            # Flood-fill this background region using 8-connectivity.
                            # If it cannot reach the border, it is a hole.
                            if not seen[nr, nc]:
                                seen[nr, nc] = True
                                bstack = [(nr, nc)]
                                reaches_border = False
                                while bstack:
                                    br, bc = bstack.pop()
                                    if br == 0 or bc == 0 or br == h - 1 or bc == w - 1:
                                        reaches_border = True
                                        break
                                    for bdr in (-1, 0, 1):
                                        for bdc in (-1, 0, 1):
                                            if bdr == 0 and bdc == 0:
                                                continue
                                            nbr, nbc = br + bdr, bc + bdc
                                            if 0 <= nbr < h and 0 <= nbc < w:
                                                if not seen[nbr, nbc] and a[nbr, nbc] == 0:
                                                    seen[nbr, nbc] = True
                                                    bstack.append((nbr, nbc))
                                if not reaches_border:
                                    has_hole = True
                                    break
                if has_hole:
                    break

            color = 3 if has_hole else 2
            for r, c in cells:
                out[r, c] = color

    return out.tolist()

