import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape
    out = g.copy()

    # Find all 4x4 objects:
    # - exactly one interior 2x2 block of a single non-3, non-background colour
    # - at least one 3 on the border
    # - no other non-background cells inside the 4x4
    objects = []
    for r in range(H - 3):
        for c in range(W - 3):
            block = g[r:r+4, c:c+4]
            interior = block[1:3, 1:3]
            vals = set(interior.flatten().tolist())
            if len(vals) != 1:
                continue
            color = vals.pop()
            if color == 3:
                continue
            border = np.concatenate([
                block[0, :].flatten(),
                block[3, :].flatten(),
                block[:, 0].flatten(),
                block[:, 3].flatten()
            ])
            if 3 not in set(border.tolist()):
                continue
            # All non-background cells must be either 3 or the interior colour.
            if not np.all((block == 3) | (block == color)):
                continue
            objects.append((r, c, color))

    # Draw rays from every missing border cell of every object.
    # Missing border cell = background cell on the 4x4 border.
    # Direction is outward:
    #   top edge -> up, bottom edge -> down,
    #   left edge -> left, right edge -> right,
    #   corners -> diagonal outward.
    for r0, c0, color in objects:
        for dr in range(4):
            for dc in range(4):
                if not (dr in (0, 3) or dc in (0, 3)):
                    continue
                if g[r0 + dr, c0 + dc] != 0:
                    continue

                # Determine outward direction.
                if dr == 0 and dc == 0:
                    step = (-1, -1)
                elif dr == 0 and dc == 3:
                    step = (-1, 1)
                elif dr == 3 and dc == 0:
                    step = (1, -1)
                elif dr == 3 and dc == 3:
                    step = (1, 1)
                elif dr == 0:
                    step = (-1, 0)
                elif dr == 3:
                    step = (1, 0)
                elif dc == 0:
                    step = (0, -1)
                else:
                    step = (0, 1)

                r, c = r0 + dr, c0 + dc
                while 0 <= r < H and 0 <= c < W:
                    if out[r, c] == 0:
                        out[r, c] = color
                    r += step[0]
                    c += step[1]

    return out.tolist()

