    # Background is the most frequent color.
    bg = Counter(g.flatten().tolist()).most_common(1)[0][0]

    # Find all 4x4 objects.
    objects = []
    for r in range(H - 3):
        for c in range(W - 3):
            block = g[r:r + 4, c:c + 4]
            interior = block[1:3, 1:3]
            vals = set(interior.flatten().tolist())

            if len(vals) != 1:
                continue

            color = vals.pop()
            if color == bg or color == 3:
                continue

            # Border must contain at least one 3.
            border = np.concatenate([
                block[0, :].flatten(),
                block[3, :].flatten(),
                block[:, 0].flatten(),
                block[:, 3].flatten()
            ])
            if 3 not in set(border.tolist()):
                continue

            # All non-background cells inside the 4x4 must be 3 or the interior color.
            if not np.all((block == bg) | (block == 3) | (block == color)):
                continue

            objects.append((r, c, color))

    # Draw rays from missing border cells.
    for r0, c0, color in objects:
        for dr in range(4):
            for dc in range(4):
                # Only border cells.
                if not (dr in (0, 3) or dc in (0, 3)):
                    continue

                # Only background cells on the border.
                if g[r0 + dr, c0 + dc] != bg:
                    continue

                # Outward direction.
                if dr == 0 and dc == 0:
                    step = (-1, -1)
                elif dr == 0 and dc == 3:
                    step = (-1, 1)
                elif dr == 3 and dc == 0:
                    step = (1, -1)
                elif dr == 3 and dc == 3:
                    step = (1, 1)
                elif dr == 0:
                    step = (-1, 0)
                elif dr == 3:
                    step = (1, 0)
                elif dc == 0:
                    step = (0, -1)
                else:
                    step = (0, 1)

                r, c = r0 + dr, c0 + dc
                while 0 <= r < H and 0 <= c < W:
                    if out[r, c] == bg:
                        out[r, c] = color
                    r += step[0]
                    c += step[1]

    return out.tolist()

