def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    H, W = g.shape
    out = g.copy()

    # The only cells that are recolored are the 5s.
    mask = (g == 5)
    if not mask.any():
        return out.tolist()

    # Connected components of 5s (4-connectivity).
    comp_id = -np.ones((H, W), dtype=int)
    comps = []
    for r in range(H):
        for c in range(W):
            if mask[r, c] and comp_id[r, c] == -1:
                cid = len(comps)
                q = deque([(r, c)])
                comp_id[r, c] = cid
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < H and 0 <= nx < W:
                            if mask[ny, nx] and comp_id[ny, nx] == -1:
                                comp_id[ny, nx] = cid
                                q.append((ny, nx))
                comps.append(cells)

    # Reference patterns are all non-zero, non-5 cells.
    ref_mask = (g != 0) & (g != 5)
    ref_id = -np.ones((H, W), dtype=int)
    refs = []
    for r in range(H):
        for c in range(W):
            if ref_mask[r, c] and ref_id[r, c] == -1:
                rid = len(refs)
                q = deque([(r, c)])
                ref_id[r, c] = rid
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < H and 0 <= nx < W:
                            if ref_mask[ny, nx] and ref_id[ny, nx] == -1:
                                ref_id[ny, nx] = rid
                                q.append((ny, nx))
                refs.append(cells)

    def norm(cells):
        if not cells:
            return None
        ys = [p[0] for p in cells]
        xs = [p[1] for p in cells]
        y0, x0 = min(ys), min(xs)
        return frozenset((y - y0, x - x0) for y, x in cells)

    ref_shapes = []
    for cells in refs:
        s = norm(cells)
        if s is not None:
            ref_shapes.append((s, g[cells[0][0], cells[0][1]]))

    # Match each 5-component to the reference shape with the best overlap.
    # In these puzzles the shapes are exact; the overlap score is a robust
    # fallback for tiny anti-aliasing/edge differences.
    for cells in comps:
        s = norm(cells)
        best_color = 0
        best_score = -1
        for rs, color in ref_shapes:
            inter = len(s & rs)
            union = len(s | rs)
            score = inter / union if union else 0
            if score > best_score:
                best_score = score
                best_color = color
        for y, x in cells:
            out[y, x] = best_color

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    H, W = g.shape
    out = g.copy()

    # Only 5-cells are recolored.
    mask = (g == 5)
    if not mask.any():
        return out.tolist()

    # Connected components of 5s (4-connectivity).
    comp_id = -np.ones((H, W), dtype=int)
    comps = []
    for r in range(H):
        for c in range(W):
            if mask[r, c] and comp_id[r, c] == -1:
                cid = len(comps)
                q = deque([(r, c)])
                comp_id[r, c] = cid
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < H and 0 <= nx < W:
                            if mask[ny, nx] and comp_id[ny, nx] == -1:
                                comp_id[ny, nx] = cid
                                q.append((ny, nx))
                comps.append(cells)

    # Reference components: all non-zero, non-5 cells.
    ref_mask = (g != 0) & (g != 5)
    ref_id = -np.ones((H, W), dtype=int)
    refs = []
    for r in range(H):
        for c in range(W):
            if ref_mask[r, c] and ref_id[r, c] == -1:
                rid = len(refs)
                q = deque([(r, c)])
                ref_id[r, c] = rid
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < H and 0 <= nx < W:
                            if ref_mask[ny, nx] and ref_id[ny, nx] == -1:
                                ref_id[ny, nx] = rid
                                q.append((ny, nx))
                refs.append(cells)

    def count_holes(cells):
        """Count background components fully enclosed by this component."""
        if not cells:
            return 0

        ys = [p[0] for p in cells]
        xs = [p[1] for p in cells]
        y0, y1 = min(ys), max(ys)
        x0, x1 = min(xs), max(xs)

        # If the component touches the bounding-box border, any background
        # touching that border is not enclosed.
        border = set()
        for y in range(y0, y1 + 1):
            border.add((y, x0))
            border.add((y, x1))
        for x in range(x0, x1 + 1):
            border.add((y0, x))
            border.add((y1, x))

        comp_set = set(cells)
        holes = 0
        seen = set()

        for y in range(y0, y1 + 1):
            for x in range(x0, x1 + 1):
                if (y, x) in comp_set or (y, x) in seen:
                    continue
                # Flood-fill a background region inside the bounding box.
                q = deque([(y, x)])
                seen.add((y, x))
                touches_border = (y, x) in border
                while q:
                    cy, cx = q.popleft()
                    if (cy, cx) in border:
                        touches_border = True
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = cy + dy, cx + dx
                        if (
                            y0 <= ny <= y1
                            and x0 <= nx <= x1
                            and (ny, nx) not in comp_set
                            and (ny, nx) not in seen
                        ):
                            seen.add((ny, nx))
                            q.append((ny, nx))
                if not touches_border:
                    holes += 1
        return holes

    # Map hole count -> color using reference components.
    # If a color appears with multiple hole counts, prefer the non-trivial
    # reference shape (the one that is not a long separator line).
    color_by_holes = {}
    for cells in refs:
        h = count_holes(cells)
        color = g[cells[0][0], cells[0][1]]
        ys = [p[0] for p in cells]
        xs = [p[1] for p in cells]
        hgt = max(ys) - min(ys) + 1
        wid = max(xs) - min(xs) + 1
        is_line = (hgt == 1 or wid == 1) and len(cells) >= 5

        if h not in color_by_holes:
            color_by_holes[h] = (color, is_line)
        else:
            old_color, old_is_line = color_by_holes[h]
            # Prefer a compact reference over a separator line.
            if old_is_line and not is_line:
                color_by_holes[h] = (color, is_line)

    # Recolor each 5-component by its number of enclosed holes.
    for cells in comps:
        h = count_holes(cells)
        if h in color_by_holes:
            color = color_by_holes[h][0]
        else:
            # Fallback: nearest available hole count.
            nearest = min(color_by_holes.keys(), key=lambda k: abs(k - h))
            color = color_by_holes[nearest][0]
        for y, x in cells:
            out[y, x] = color

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # 1 becomes 2
    g[g == 1] = 2

    # Find the single 3
    ys, xs = np.where(g == 3)
    if len(ys) == 0:
        return g.tolist()
    sy, sx = int(ys[0]), int(xs[0])

    # Find all maximal straight 2-segments
    segs = []
    used = np.zeros((h, w), dtype=bool)

    # Horizontal segments
    for r in range(h):
        c = 0
        while c < w:
            if g[r, c] == 2 and not used[r, c]:
                c2 = c
                while c2 + 1 < w and g[r, c2 + 1] == 2:
                    c2 += 1
                if c2 > c:
                    segs.append((r, c, r, c2))
                    for cc in range(c, c2 + 1):
                        used[r, cc] = True
                c = c2 + 1
            else:
                c += 1

    # Vertical segments
    for c in range(w):
        r = 0
        while r < h:
            if g[r, c] == 2 and not used[r, c]:
                r2 = r
                while r2 + 1 < h and g[r2 + 1, c] == 2:
                    r2 += 1
                if r2 > r:
                    segs.append((r, c, r2, c))
                    for rr in range(r, r2 + 1):
                        used[rr, c] = True
                r = r2 + 1
            else:
                r += 1

    # If there are no 2-segments, just return the recolored grid.
    if not segs:
        return g.tolist()

    # Choose the dominant orientation:
    # horizontal if total horizontal length >= vertical length, else vertical.
    hlen = sum(abs(x2 - x1) for (y1, x1, y2, x2) in segs if y1 == y2)
    vlen = sum(abs(y2 - y1) for (y1, x1, y2, x2) in segs if x1 == x2)
    horizontal_mode = hlen >= vlen

    def draw_line(a, b):
        if a[0] == b[0]:
            y = a[0]
            x1, x2 = sorted((a[1], b[1]))
            for x in range(x1, x2 + 1):
                g[y, x] = 3
        else:
            x = a[1]
            y1, y2 = sorted((a[0], b[0]))
            for y in range(y1, y2 + 1):
                g[y, x] = 3

    if horizontal_mode:
        # Sort horizontal segments by row.
        hsegs = sorted([s for s in segs if s[0] == s[2]], key=lambda s: s[0])
        if not hsegs:
            return g.tolist()

        # Build a sequence of horizontal "barriers":
        # top edge, horizontal segments, bottom edge.
        barriers = [(0, 0, w - 1)]
        for (y1, x1, y2, x2) in hsegs:
            barriers.append((y1, x1, x2))
        barriers.append((h - 1, 0, w - 1))

        # Start point is the 3.
        cur = (sy, sx)
        path = [cur]

        # For each gap between consecutive barriers, move to the middle row
        # and choose a column in the gap of the next barrier.
        for i in range(len(barriers) - 1):
            y_top, xl_top, xr_top = barriers[i]
            y_bot, xl_bot, xr_bot = barriers[i + 1]

            if y_bot <= y_top:
                continue

            mid_y = (y_top + y_bot) // 2

            # If the current point is already below this gap, skip.
            if cur[0] > mid_y:
                continue

            # Move vertically to mid_y.
            if cur[0] != mid_y:
                nxt = (mid_y, cur[1])
                draw_line(cur, nxt)
                path.append(nxt)
                cur = nxt

            # Choose a column in the gap of the next barrier.
            # Prefer a gap closest to the current column; if current column
            # is inside the barrier, choose the nearest outside gap.
            x = cur[1]
            if xl_bot <= x <= xr_bot:
                # Inside the barrier: choose the nearer side gap.
                left_gap = (xl_bot - 1, 0)
                right_gap = (w - 1, xr_bot + 1)
                candidates = []
                if left_gap[0] >= left_gap[1]:
                    candidates.append((abs(x - (left_gap[0] + left_gap[1]) // 2), (left_gap[0] + left_gap[1]) // 2))
                if right_gap[0] >= right_gap[1]:
                    candidates.append((abs(x - (right_gap[0] + right_gap[1]) // 2), (right_gap[0] + right_gap[1]) // 2))
                if candidates:
                    candidates.sort()
                    x = candidates[0][1]
                else:
                    x = 0 if xl_bot > 0 else w - 1
            else:
                # Already in a gap; keep current column.
                x = x

            # Move horizontally to chosen column.
            if cur[1] != x:
                nxt = (cur[0], x)
                draw_line(cur, nxt)
                path.append(nxt)
                cur = nxt

        # Finish to the bottom edge.
        if cur[0] != h - 1:
            nxt = (h - 1, cur[1])
            draw_line(cur, nxt)
            path.append(nxt)

    else:
        # Sort vertical segments by column.
        vsegs = sorted([s for s in segs if s[1] == s[3]], key=lambda s: s[1])
        if not vsegs:
            return g.tolist()

        # Build a sequence of vertical "barriers":
        # left edge, vertical segments, right edge.
        barriers = [(0, 0, h - 1)]
        for (y1, x1, y2, x2) in vsegs:
            barriers.append((x1, y1, y2))
        barriers.append((w - 1, 0, h - 1))

        cur = (sy, sx)
        path = [cur]

        for i in range(len(barriers) - 1):
            x_left, yt_left, yb_left = barriers[i]
            x_right, yt_right, yb_right = barriers[i + 1]

            if x_right <= x_left:
                continue

            mid_x = (x_left + x_right) // 2

            if cur[1] > mid_x:
                continue

            # Move horizontally to mid_x.
            if cur[1] != mid_x:
                nxt = (cur[0], mid_x)
                draw_line(cur, nxt)
                path.append(nxt)
                cur = nxt

            # Choose a row in the gap of the next barrier.
            y = cur[0]
            if yt_right <= y <= yb_right:
                top_gap = (0, yt_right - 1)
                bot_gap = (yb_right + 1, h - 1)
                candidates = []
                if top_gap[0] <= top_gap[1]:
                    candidates.append((abs(y - (top_gap[0] + top_gap[1]) // 2), (top_gap[0] + top_gap[1]) // 2))
                if bot_gap[0] <= bot_gap[1]:
                    candidates.append((abs(y - (bot_gap[0] + bot_gap[1]) // 2), (bot_gap[0] + bot_gap[1]) // 2))
                if candidates:
                    candidates.sort()
                    y = candidates[0][1]
                else:
                    y = 0 if yt_right > 0 else h - 1
            else:
                y = y

            # Move vertically to chosen row.
            if cur[0] != y:
                nxt = (y, cur[1])
                draw_line(cur, nxt)
                path.append(nxt)
                cur = nxt

        # Finish to the right edge.
        if cur[1] != w - 1:
            nxt = (cur[0], w - 1)
            draw_line(cur, nxt)
            path.append(nxt)

    return g.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Fixed 5x4 board of 5x5 cells.
    # Rows: 0..4, 6..10, 12..16, 17..21, 22..26
    # Cols: 1..5, 6..10, 11..15, 16..20
    row_bounds = [(0, 5), (6, 11), (12, 17), (17, 22), (22, 27)]
    col_bounds = [(1, 6), (6, 11), (11, 16), (16, 21)]

    def cell_color(r, c):
        r0, r1 = row_bounds[r]
        c0, c1 = col_bounds[c]
        sub = g[r0:r1, c0:c1]
        vals = sub[sub != 8]
        if vals.size == 0:
            return None
        # The non-8 colour in the 3x3 object.
        return int(np.bincount(vals).argmax())

    # Build 5x4 colour board.
    board = [[cell_color(r, c) for c in range(4)] for r in range(5)]

    # Find all simple paths from any top cell to any bottom cell.
    # Moves: orthogonal or knight-like (dr, dc) with |dr|<=2, |dc|<=2,
    # not both zero, and not diagonal (|dr|==1 and |dc|==1).
    moves = []
    for dr in (-2, -1, 0, 1, 2):
        for dc in (-2, -1, 0, 1, 2):
            if dr == 0 and dc == 0:
                continue
            if abs(dr) == 1 and abs(dc) == 1:
                continue
            moves.append((dr, dc))

    paths = []

    def dfs(r, c, visited, path):
        if r == 4:
            paths.append(path[:])
            return
        for dr, dc in moves:
            nr, nc = r + dr, c + dc
            if 0 <= nr < 5 and 0 <= nc < 4 and (nr, nc) not in visited:
                visited.add((nr, nc))
                path.append((nr, nc))
                dfs(nr, nc, visited, path)
                path.pop()
                visited.remove((nr, nc))

    for c in range(4):
        if board[0][c] is not None:
            dfs(0, c, {(0, c)}, [(0, c)])

    # Choose the path with the fewest cells; ties by lexicographic order.
    if not paths:
        return out.tolist()

    best = min(paths, key=lambda p: (len(p), p))

    # Fill selected cells with 3, preserving original non-8 pixels.
    for r, c in best:
        r0, r1 = row_bounds[r]
        c0, c1 = col_bounds[c]
        for i in range(r0, r1):
            for j in range(c0, c1):
                if out[i, j] == 8:
                    out[i, j] = 3

    # Bottom two rows: fill with the colour of the last path cell,
    # or 3 if that cell is empty.
    bottom_color = board[best[-1][0]][best[-1][1]]
    if bottom_color is None:
        bottom_color = 3
    out[28:30, :] = bottom_color

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # 5x4 cell grid; cell (r,c) object at rows 5r+1..5r+3, cols 5c+2..5c+4
    def cell_color(r, c):
        r0, r1 = 5 * r + 1, 5 * r + 4
        c0, c1 = 5 * c + 2, 5 * c + 5
        sub = g[r0:r1, c0:c1]
        vals = sub[sub != 8]
        if vals.size == 0:
            return None
        return int(np.bincount(vals).argmax())

    board = [[cell_color(r, c) for c in range(4)] for r in range(5)]

    # Moves: |dr|<=2, |dc|<=2, not (0,0), not diagonal (|dr|==1 and |dc|==1)
    moves = []
    for dr in (-2, -1, 0, 1, 2):
        for dc in (-2, -1, 0, 1, 2):
            if dr == 0 and dc == 0:
                continue
            if abs(dr) == 1 and abs(dc) == 1:
                continue
            moves.append((dr, dc))

    # BFS from all top-row cells to find shortest path to any bottom-row cell
    # State: (r, c, frozenset_of_visited)
    # To keep it tractable, use BFS with visited set per path (Dijkstra-like)
    # Since grid is only 5x4=20 cells, we can use BFS over (r,c,visited_mask)

    best_path = None
    best_len = float('inf')

    # BFS: state = (r, c, visited_mask)
    # visited_mask is a 20-bit integer
    start_states = []
    for c in range(4):
        mask = 1 << c  # cell (0,c) is bit c
        start_states.append((0, c, mask, [(0, c)]))

    visited_states = set()
    queue = deque(start_states)

    while queue:
        r, c, mask, path = queue.popleft()
        state = (r, c, mask)
        if state in visited_states:
            continue
        visited_states.add(state)

        if r == 4:
            if len(path) < best_len:
                best_len = len(path)
                best_path = path[:]
            continue

        for dr, dc in moves:
            nr, nc = r + dr, c + dc
            if 0 <= nr < 5 and 0 <= nc < 4:
                nmask = mask | (1 << (nr * 4 + nc))
                if nmask != mask:  # not already visited
                    nstate = (nr, nc, nmask)
                    if nstate not in visited_states:
                        queue.append((nr, nc, nmask, path + [(nr, nc)]))

    if best_path is None:
        return out.tolist()

    # Fill 5x5 regions for each cell in the path
    for r, c in best_path:
        r0, r1 = 5 * r, 5 * r + 5
        c0, c1 = 5 * c + 1, 5 * c + 6
        r0 = max(0, r0)
        r1 = min(h, r1)
        c0 = max(0, c0)
        c1 = min(w, c1)
        for i in range(r0, r1):
            for j in range(c0, c1):
                if out[i, j] == 8:
                    out[i, j] = 3

    # Bottom 2 rows: fill with color of last path cell, or 3 if None
    last_r, last_c = best_path[-1]
    bottom_color = board[last_r][last_c]
    if bottom_color is None:
        bottom_color = 3
    out[h-2:h, :] = bottom_color

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Start cell is the unique 3.
    starts = np.argwhere(g == 3)
    if len(starts) == 0:
        return [[int(x) for x in row] for row in g]
    sr, sc = starts[0]

    # Walls are connected components of 1/2.
    wall = (g == 1) | (g == 2)
    comp = -np.ones((h, w), dtype=int)
    comps = []
    for r in range(h):
        for c in range(w):
            if wall[r, c] and comp[r, c] == -1:
                cid = len(comps)
                stack = [(r, c)]
                comp[r, c] = cid
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and wall[ny, nx] and comp[ny, nx] == -1:
                            comp[ny, nx] = cid
                            stack.append((ny, nx))
                ys = [y for y, _ in cells]
                xs = [x for _, x in cells]
                ones = sum(1 for y, x in cells if g[y, x] == 1)
                comps.append({
                    "cells": cells,
                    "rmin": min(ys), "rmax": max(ys),
                    "cmin": min(xs), "cmax": max(xs),
                    "ones": ones,
                })

    # Determine the direction in which the 3 must travel.
    def dist_to_border(r, c, direction):
        if direction == "right":
            return w - 1 - c
        if direction == "left":
            return c
        if direction == "down":
            return h - 1 - r
        if direction == "up":
            return r
        return 10**9

    # Choose the border direction that is not immediately blocked and is closest.
    best_dir = None
    best_d = 10**9
    for d in ("right", "left", "down", "up"):
        if d == "right" and sc + 1 < w and wall[sr, sc + 1]:
            continue
        if d == "left" and sc - 1 >= 0 and wall[sr, sc - 1]:
            continue
        if d == "down" and sr + 1 < h and wall[sr + 1, sc]:
            continue
        if d == "up" and sr - 1 >= 0 and wall[sr - 1, sc]:
            continue
        dd = dist_to_border(sr, sc, d)
        if dd < best_d:
            best_d = dd
            best_dir = d

    if best_dir is None:
        # Fallback: any unblocked direction.
        for d in ("right", "left", "down", "up"):
            if d == "right" and sc + 1 < w and not wall[sr, sc + 1]:
                best_dir = d; break
            if d == "left" and sc - 1 >= 0 and not wall[sr, sc - 1]:
                best_dir = d; break
            if d == "down" and sr + 1 < h and not wall[sr + 1, sc]:
                best_dir = d; break
            if d == "up" and sr - 1 >= 0 and not wall[sr - 1, sc]:
                best_dir = d; break

    if best_dir is None:
        return [[int(x) for x in row] for row in g]

    # For each wall, compute the clearance needed when passing it.
    # Clearance is one plus the number of 1s in the wall component.
    def clearance(comp_id):
        return comps[comp_id]["ones"] + 1

    # Build a path from the start to the chosen border, going around walls.
    # The path is a sequence of axis-aligned segments.  It always keeps the
    # required clearance from the wall it is bypassing.
    path = [(sr, sc)]
    r, c = sr, sc

    if best_dir in ("right", "left"):
        # Move horizontally to the border, detouring vertically around vertical walls.
        step = 1 if best_dir == "right" else -1
        target_c = w - 1 if best_dir == "right" else 0
        while c != target_c:
            # Find the next vertical wall blocking the current row ahead.
            block_c = None
            block_comp = None
            for cc in range(c + step, target_c + step, step):
                if 0 <= cc < w and wall[r, cc]:
                    block_c = cc
                    block_comp = comp[r, cc]
                    break
            if block_c is None:
                c = target_c
                path.append((r, c))
                break

            comp_info = comps[block_comp]
            clr = clearance(block_comp)

            # Choose whether to go above or below the wall.
            # Prefer the side with more room; if tied, prefer the side away from the start.
            above_ok = comp_info["rmin"] - clr >= 0
            below_ok = comp_info["rmax"] + clr < h
            if above_ok and below_ok:
                # Prefer the side that gives a shorter vertical detour.
                above_dist = abs(r - (comp_info["rmin"] - clr))
                below_dist = abs((comp_info["rmax"] + clr) - r)
                if above_dist < below_dist:
                    go = "above"
                elif below_dist < above_dist:
                    go = "below"
                else:
                    # Tie: go away from the start row.
                    go = "above" if r >= (comp_info["rmin"] + comp_info["rmax"]) // 2 else "below"
            elif above_ok:
                go = "above"
            elif below_ok:
                go = "below"
            else:
                # Should not happen for valid puzzles; just stop.
                break

            # Move horizontally to the clearance column before the wall.
            if best_dir == "right":
                turn_c = block_c - clr
            else:
                turn_c = block_c + clr
            if turn_c != c:
                c = turn_c
                path.append((r, c))

            # Move vertically to the clearance row.
            if go == "above":
                turn_r = comp_info["rmin"] - clr
            else:
                turn_r = comp_info["rmax"] + clr
            if turn_r != r:
                r = turn_r
                path.append((r, c))

            # Move horizontally past the wall to the clearance column on the other side.
            if best_dir == "right":
                past_c = block_c + clr
            else:
                past_c = block_c - clr
            if past_c != c:
                c = past_c
                path.append((r, c))

            # Move vertically back to the original row.
            if r != sr:
                r = sr
                path.append((r, c))

    else:
        # Move vertically to the border, detouring horizontally around horizontal walls.
        step = 1 if best_dir == "down" else -1
        target_r = h - 1 if best_dir == "down" else 0
        while r != target_r:
            block_r = None
            block_comp = None
            for rr in range(r + step, target_r + step, step):
                if 0 <= rr < h and wall[rr, c]:
                    block_r = rr
                    block_comp = comp[rr, c]
                    break
            if block_r is None:
                r = target_r
                path.append((r, c))
                break

            comp_info = comps[block_comp]
            clr = clearance(block_comp)

            left_ok = comp_info["cmin"] - clr >= 0
            right_ok = comp_info["cmax"] + clr < w
            if left_ok and right_ok:
                left_dist = abs(c - (comp_info["cmin"] - clr))
                right_dist = abs((comp_info["cmax"] + clr) - c)
                if left_dist < right_dist:
                    go = "left"
                elif right_dist < left_dist:
                    go = "right"
                else:
                    go = "left" if c >= (comp_info["cmin"] + comp_info["cmax"]) // 2 else "right"
            elif left_ok:
                go = "left"
            elif right_ok:
                go = "right"
            else:
                break

            if best_dir == "down":
                turn_r = block_r - clr
            else:
                turn_r = block_r + clr
            if turn_r != r:
                r = turn_r
                path.append((r, c))

            if go == "left":
                turn_c = comp_info["cmin"] - clr
            else:
                turn_c = comp_info["cmax"] + clr
            if turn_c != c:
                c = turn_c
                path.append((r, c))

            if best_dir == "down":
                past_r = block_r + clr
            else:
                past_r = block_r - clr
            if past_r != r:
                r = past_r
                path.append((r, c))

            if c != sc:
                c = sc
                path.append((r, c))

    # Draw the path.
    out = g.copy()
    # First normalize all 1s to 2s.
    out[out == 1] = 2

    # Draw 3s along the path.
    for i in range(len(path) - 1):
        r1, c1 = path[i]
        r2, c2 = path[i + 1]
        if r1 == r2:
            c_start, c_end = sorted((c1, c2))
            out[r1, c_start:c_end + 1] = 3
        else:
            r_start, r_end = sorted((r1, r2))
            out[r_start:r_end + 1, c1] = 3

    return [[int(x) for x in row] for row in out]

import sys
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return []

    h = len(grid)
    w = len(grid[0])
    g = [[int(x) for x in row] for row in grid]

    # Find the unique 3.
    start = None
    for r in range(h):
        for c in range(w):
            if g[r][c] == 3:
                start = (r, c)
                break
        if start is not None:
            break

    if start is None:
        return g

    sr, sc = start

    # Connected components of 1/2.
    seen = [[False] * w for _ in range(h)]
    walls = []

    for r in range(h):
        for c in range(w):
            if g[r][c] in (1, 2) and not seen[r][c]:
                q = deque([(r, c)])
                seen[r][c] = True
                cells = []
                ones = 0
                while q:
                    rr, cc = q.popleft()
                    cells.append((rr, cc))
                    if g[rr][cc] == 1:
                        ones += 1
                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nr, nc = rr + dr, cc + dc
                        if 0 <= nr < h and 0 <= nc < w and not seen[nr][nc] and g[nr][nc] in (1, 2):
                            seen[nr][nc] = True
                            q.append((nr, nc))

                rows = [r0 for r0, c0 in cells]
                cols = [c0 for r0, c0 in cells]
                rmin, rmax = min(rows), max(rows)
                cmin, cmax = min(cols), max(cols)

                # The puzzle walls are straight horizontal or vertical segments.
                if rmin == rmax:
                    orient = 'h'
                elif cmin == cmax:
                    orient = 'v'
                else:
                    # Fallback: treat as horizontal if wider, otherwise vertical.
                    orient = 'h' if (cmax - cmin) >= (rmax - rmin) else 'v'

                walls.append({
                    'orient': orient,
                    'rmin': rmin,
                    'rmax': rmax,
                    'cmin': cmin,
                    'cmax': cmax,
                    'd': ones + 1,
                })

    # Choose the initial direction: away from the border on which the 3 lies.
    if sr == 0:
        dr, dc = 1, 0
    elif sr == h - 1:
        dr, dc = -1, 0
    elif sc == 0:
        dr, dc = 0, 1
    elif sc == w - 1:
        dr, dc = 0, -1
    else:
        # Fallback: move toward the nearest border.
        dists = [
            (sr, 'up'),
            (h - 1 - sr, 'down'),
            (sc, 'left'),
            (w - 1 - sc, 'right'),
        ]
        dists.sort()
        if dists[0][1] == 'up':
            dr, dc = -1, 0
        elif dists[0][1] == 'down':
            dr, dc = 1, 0
        elif dists[0][1] == 'left':
            dr, dc = 0, -1
        else:
            dr, dc = 0, 1

    path = [(sr, sc)]
    r, c = sr, sc

    # Simulate the corridor path.
    while True:
        # Stop if already on a border.
        if r == 0 or r == h - 1 or c == 0 or c == w - 1:
            break

        # Find the first wall that blocks the current straight ray.
        best = None
        best_stop = None

        for wall in walls:
            d = wall['d']
            if dr == 1:  # moving down
                if wall['orient'] != 'h':
                    continue
                if not (wall['cmin'] - (d - 1) <= c <= wall['cmax'] + (d - 1)):
                    continue
                if wall['rmin'] <= r:
                    continue
                stop = wall['rmin'] - d
                if stop <= r:
                    continue
                if best_stop is None or stop < best_stop:
                    best_stop = stop
                    best = wall
            elif dr == -1:  # moving up
                if wall['orient'] != 'h':
                    continue
                if not (wall['cmin'] - (d - 1) <= c <= wall['cmax'] + (d - 1)):
                    continue
                if wall['rmax'] >= r:
                    continue
                stop = wall['rmax'] + d
                if stop >= r:
                    continue
                if best_stop is None or stop > best_stop:
                    best_stop = stop
                    best = wall
            elif dc == 1:  # moving right
                if wall['orient'] != 'v':
                    continue
                if not (wall['rmin'] - (d - 1) <= r <= wall['rmax'] + (d - 1)):
                    continue
                if wall['cmin'] <= c:
                    continue
                stop = wall['cmin'] - d
                if stop <= c:
                    continue
                if best_stop is None or stop < best_stop:
                    best_stop = stop
                    best = wall
            elif dc == -1:  # moving left
                if wall['orient'] != 'v':
                    continue
                if not (wall['rmin'] - (d - 1) <= r <= wall['rmax'] + (d - 1)):
                    continue
                if wall['cmax'] >= c:
                    continue
                stop = wall['cmax'] + d
                if stop >= c:
                    continue
                if best_stop is None or stop > best_stop:
                    best_stop = stop
                    best = wall

        if best is None:
            # No wall blocks the ray; go straight to the border.
            if dr == 1:
                r = h - 1
            elif dr == -1:
                r = 0
            elif dc == 1:
                c = w - 1
            else:
                c = 0
            path.append((r, c))
            break

        # Move to the clearance boundary of the blocking wall.
        if dr == 1 or dr == -1:
            r = best_stop
        else:
            c = best_stop
        path.append((r, c))

        # Choose which end of the wall to go around.
        d = best['d']
        if best['orient'] == 'h':
            # Horizontal wall: go left or right of its ends.
            left_ok = best['cmin'] - d >= 0
            right_ok = best['cmax'] + d < w

            if left_ok and right_ok:
                # Prefer the side that is closer to the current column.
                left_dist = abs(c - (best['cmin'] - d))
                right_dist = abs((best['cmax'] + d) - c)
                if left_dist < right_dist:
                    side = 'left'
                elif right_dist < left_dist:
                    side = 'right'
                else:
                    # Tie: go away from the wall's center.
                    center = (best['cmin'] + best['cmax']) // 2
                    side = 'left' if c <= center else 'right'
            elif left_ok:
                side = 'left'
            elif right_ok:
                side = 'right'
            else:
                # Should not happen in valid puzzles; stop.
                break

            if side == 'left':
                c = best['cmin'] - d
            else:
                c = best['cmax'] + d
        else:
            # Vertical wall: go above or below its ends.
            up_ok = best['rmin'] - d >= 0
            down_ok = best['rmax'] + d < h

            if up_ok and down_ok:
                up_dist = abs(r - (best['rmin'] - d))
                down_dist = abs((best['rmax'] + d) - r)
                if up_dist < down_dist:
                    side = 'up'
                elif down_dist < up_dist:
                    side = 'down'
                else:
                    center = (best['rmin'] + best['rmax']) // 2
                    side = 'up' if r <= center else 'down'
            elif up_ok:
                side = 'up'
            elif down_ok:
                side = 'down'
            else:
                break

            if side == 'up':
                r = best['rmin'] - d
            else:
                r = best['rmax'] + d

        path.append((r, c))

    # Build output: 1 -> 2, then draw the path as 3.
    out = [[2 if g[r][c] == 1 else g[r][c] for c in range(w)] for r in range(h)]

    for i in range(len(path) - 1):
        r1, c1 = path[i]
        r2, c2 = path[i + 1]
        if r1 == r2:
            c_lo, c_hi = sorted((c1, c2))
            for cc in range(c_lo, c_hi + 1):
                out[r1][cc] = 3
        else:
            r_lo, r_hi = sorted((r1, r2))
            for rr in range(r_lo, r_hi + 1):
                out[rr][c1] = 3

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Connected components of non-background cells.
    # 2 is treated as part of the component, but is not a "body" colour.
    comp_id = -np.ones((H, W), dtype=int)
    comps = []
    for r in range(H):
        for c in range(W):
            if g[r, c] != 0 and comp_id[r, c] == -1:
                cid = len(comps)
                q = deque([(r, c)])
                comp_id[r, c] = cid
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < H and 0 <= nx < W:
                                if g[ny, nx] != 0 and comp_id[ny, nx] == -1:
                                    comp_id[ny, nx] = cid
                                    q.append((ny, nx))
                comps.append(cells)

    if not comps:
        return [list(map(int, row)) for row in g]

    # For each component, find its dominant non-2 colour.
    def dominant_color(cells):
        counts = {}
        for y, x in cells:
            v = int(g[y, x])
            if v != 2:
                counts[v] = counts.get(v, 0) + 1
        if not counts:
            return 2
        return max(counts.items(), key=lambda kv: (kv[1], -kv[0]))[0]

    # Anchor: the component with colour 4 if present, otherwise the largest component.
    anchor = None
    for i, cells in enumerate(comps):
        if dominant_color(cells) == 4:
            anchor = i
            break
    if anchor is None:
        anchor = max(range(len(comps)), key=lambda i: len(comps[i]))

    # Build a graph of possible attachments.
    # A component A can attach to B if, after translating A so that one of A's
    # 2-cells coincides with one of B's 2-cells or touches a body cell of B,
    # the body cells of A do not overlap any body cell of B.
    def body_cells(cells):
        return [(y, x) for y, x in cells if g[y, x] != 2]

    def two_cells(cells):
        return [(y, x) for y, x in cells if g[y, x] == 2]

    def can_attach(a, b, placed):
        # placed: dict comp_id -> (dy, dx)
        if a in placed:
            return None
        ba = body_cells(comps[a])
        ta = two_cells(comps[a])
        bb = body_cells(comps[b])
        tb = two_cells(comps[b])
        if b in placed:
            dyb, dxb = placed[b]
        else:
            dyb, dxb = 0, 0

        candidates = []
        # Try aligning each 2 of A with each 2 of B.
        for ay, ax in ta:
            for by, bx in tb:
                dy = (by + dyb) - ay
                dx = (bx + dxb) - ax
                candidates.append((dy, dx))
        # Try placing each 2 of A adjacent to each body cell of B.
        for ay, ax in ta:
            for by, bx in bb:
                for dy0, dx0 in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                    dy = (by + dyb + dy0) - ay
                    dx = (bx + dxb + dx0) - ax
                    candidates.append((dy, dx))

        seen = set()
        for dy, dx in candidates:
            if (dy, dx) in seen:
                continue
            seen.add((dy, dx))

            # Check body overlap with all already placed components.
            ok = True
            for pid, (dy2, dx2) in placed.items():
                if pid == a:
                    continue
                for py, px in body_cells(comps[pid]):
                    if (py + dy2, px + dx2) in {(y + dy, x + dx) for y, x in ba}:
                        ok = False
                        break
                if not ok:
                    break
            if not ok:
                continue

            # Check that at least one 2 of A is adjacent to or coincident with
            # a body/2 cell of B after translation.
            good = False
            for ay, ax in ta:
                ny, nx = ay + dy, ax + dx
                for by, bx in bb:
                    if abs((by + dyb) - ny) + abs((bx + dxb) - nx) <= 1:
                        good = True
                        break
                if good:
                    break
                for by, bx in tb:
                    if (by + dyb, bx + dxb) == (ny, nx):
                        good = True
                        break
                if good:
                    break
            if not good:
                continue

            # Prefer translations that keep the component near the anchor cluster.
            score = abs(dy) + abs(dx)
            candidates_score = (score, dy, dx)
            return candidates_score

        return None

    # Greedily attach components to the growing assembly.
    placed = {anchor: (0, 0)}
    remaining = [i for i in range(len(comps)) if i != anchor]

    # Order by distance from anchor, then by size, to make the result stable.
    def anchor_center(cells):
        ys = [y for y, x in cells]
        xs = [x for x, y in cells]
        return (sum(ys) / len(ys), sum(xs) / len(xs))

    ac = anchor_center(comps[anchor])
    remaining.sort(key=lambda i: (
        abs(anchor_center(comps[i])[0] - ac[0]) + abs(anchor_center(comps[i])[1] - ac[1]),
        -len(comps[i]),
        i
    ))

    while remaining:
        progressed = False
        for i in list(remaining):
            # Try attaching to every already placed component.
            best = None
            for j in list(placed.keys()):
                res = can_attach(i, j, placed)
                if res is not None:
                    if best is None or res < best:
                        best = res
            if best is not None:
                _, dy, dx = best
                placed[i] = (dy, dx)
                remaining.remove(i)
                progressed = True
                break
        if not progressed:
            # Fallback: place any remaining component near the current cluster
            # without body overlap.
            for i in list(remaining):
                ba = body_cells(comps[i])
                placed_bodies = set()
                for pid, (dy2, dx2) in placed.items():
                    for py, px in body_cells(comps[pid]):
                        placed_bodies.add((py + dy2, px + dx2))
                # Search a small window around the current bounding box.
                ys = [y for y, x in placed_bodies]
                xs = [x for x, y in placed_bodies]
                miny, maxy = min(ys), max(ys)
                minx, maxx = min(xs), max(xs)
                found = False
                for dy in range(miny - 20, maxy + 20):
                    for dx in range(minx - 20, maxx + 20):
                        if any((y + dy, x + dx) in placed_bodies for y, x in ba):
                            continue
                        placed[i] = (dy, dx)
                        remaining.remove(i)
                        found = True
                        progressed = True
                        break
                    if found:
                        break
                if found:
                    break
            if not progressed:
                # Last resort: put it far away.
                for i in list(remaining):
                    placed[i] = (1000 + i, 1000 + i)
                    remaining.remove(i)
                break

    # Determine output canvas size.
    all_cells = []
    for cid, (dy, dx) in placed.items():
        for y, x in comps[cid]:
            all_cells.append((y + dy, x + dx))
    miny = min(y for y, x in all_cells)
    minx = min(x for x, y in all_cells)
    maxy = max(y for y, x in all_cells)
    maxx = max(x for x, y in all_cells)

    # Keep the same grid size as input if possible; otherwise expand.
    out_h = max(H, maxy - miny + 1)
    out_w = max(W, maxx - minx + 1)

    # Center the assembled cluster in the output canvas.
    off_y = (out_h - (maxy - miny + 1)) // 2 - miny
    off_x = (out_w - (maxx - minx + 1)) // 2 - minx

    out = np.zeros((out_h, out_w), dtype=int)
    for cid, (dy, dx) in placed.items():
        for y, x in comps[cid]:
            ny = y + dy + off_y
            nx = x + dx + off_x
            if 0 <= ny < out_h and 0 <= nx < out_w:
                v = int(g[y, x])
                # Body colours overwrite 2; 2 only remains if no body colour is there.
                if v != 2 or out[ny, nx] == 0:
                    out[ny, nx] = v

    return [list(map(int, row)) for row in out]

import numpy as np
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Connected components of non-2 cells.
    labels = np.zeros((H, W), dtype=int)
    comp_id = 0
    comps = []
    for y in range(H):
        for x in range(W):
            if g[y, x] != 0 and g[y, x] != 2 and labels[y, x] == 0:
                comp_id += 1
                q = deque([(y, x)])
                labels[y, x] = comp_id
                cells = []
                while q:
                    cy, cx = q.popleft()
                    cells.append((cy, cx))
                    for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny, nx = cy+dy, cx+dx
                        if 0 <= ny < H and 0 <= nx < W:
                            if labels[ny, nx] == 0 and g[ny, nx] != 0 and g[ny, nx] != 2:
                                labels[ny, nx] = comp_id
                                q.append((ny, nx))
                comps.append(cells)

    if not comps:
        return [list(map(int, row)) for row in g]

    # For each component, find its 2-cells that are adjacent to it.
    comp_twos = []
    for cells in comps:
        cellset = set(cells)
        twos = set()
        for y, x in cells:
            for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                ny, nx = y+dy, x+dx
                if 0 <= ny < H and 0 <= nx < W and g[ny, nx] == 2:
                    twos.add((ny, nx))
        comp_twos.append(twos)

    # Build a graph of components that can be connected by a single 2-cell.
    # Edge if a 2-cell of A is adjacent to a cell of B, or a 2-cell of B is adjacent to A.
    n = len(comps)
    adj = [set() for _ in range(n)]
    for i in range(n):
        for j in range(i+1, n):
            ci = set(comps[i])
            cj = set(comps[j])
            ok = False
            for y, x in comp_twos[i]:
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    if (y+dy, x+dx) in cj:
                        ok = True
                        break
                if ok:
                    break
            if not ok:
                for y, x in comp_twos[j]:
                    for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        if (y+dy, x+dx) in ci:
                            ok = True
                            break
                    if ok:
                        break
            if ok:
                adj[i].add(j)
                adj[j].add(i)

    # Choose a root: component with fewest connections, then smallest bbox area.
    def bbox_area(cells):
        ys = [y for y, _ in cells]
        xs = [x for _, x in cells]
        return (max(ys)-min(ys)+1) * (max(xs)-min(xs)+1)

    root = min(range(n), key=lambda i: (len(adj[i]), bbox_area(comps[i]), i))

    # BFS order from root.
    order = [root]
    seen = {root}
    q = deque([root])
    while q:
        u = q.popleft()
        for v in sorted(adj[u]):
            if v not in seen:
                seen.add(v)
                order.append(v)
                q.append(v)
    for v in range(n):
        if v not in seen:
            order.append(v)

    # Place components greedily.
    placed = {}
    placed_cells = set()
    placed_twos = set()

    # Place root at its original position.
    for y, x in comps[root]:
        placed_cells.add((y, x))
    for y, x in comp_twos[root]:
        placed_twos.add((y, x))
    placed[root] = (0, 0)

    for cid in order:
        if cid == root:
            continue
        cells = comps[cid]
        twos = comp_twos[cid]
        best = None

        # Candidate translations: align each 2 of this component with each placed cell
        # in the four directions, and also align each cell of this component with placed 2s.
        candidates = set()
        for py, px in placed_cells:
            for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                # If a 2 of cid is at (py,px) after translation, then translation is (py - ty, px - tx)
                for ty, tx in twos:
                    candidates.add((py - ty, px - tx))
        for py, px in placed_twos:
            for cy, cx in cells:
                candidates.add((py - cy, px - cx))

        # Also try small offsets around existing cluster.
        if placed_cells:
            ys = [y for y, _ in placed_cells]
            xs = [x for _, x in placed_cells]
            miny, maxy = min(ys), max(ys)
            minx, maxx = min(xs), max(xs)
            for dy in range(miny - 10, maxy + 11):
                for dx in range(minx - 10, maxx + 11):
                    candidates.add((dy, dx))

        for dy, dx in candidates:
            # Non-2 cells must not overlap.
            new_cells = [(y+dy, x+dx) for y, x in cells]
            if any(c in placed_cells for c in new_cells):
                continue
            # 2-cells may overlap with placed 2-cells, but not with non-2 cells.
            new_twos = [(y+dy, x+dx) for y, x in twos]
            if any(t in placed_cells for t in new_twos):
                continue
            # Must be connected to the current assembly.
            connected = False
            for ny, nx in new_cells:
                for ddy, ddx in ((1,0),(-1,0),(0,1),(0,-1)):
                    if (ny+ddy, nx+ddx) in placed_cells or (ny+ddy, nx+ddx) in placed_twos:
                        connected = True
                        break
                if connected:
                    break
            if not connected:
                for ny, nx in new_twos:
                for ddy, ddx in ((1,0),(-1,0),(0,1),(0,-1)):
                    if (ny+ddy, nx+ddx) in placed_cells or (ny+ddy, nx+ddx) in placed_twos:
                        connected = True
                        break
                if connected:
                    break
            if not connected:
                continue

            # Prefer translations that use 2-connections and are close to the cluster.
            score = abs(dy) + abs(dx)
            if best is None or score < best[0]:
                best = (score, dy, dx)

        if best is None:
            # Fallback: place far away.
            dy = 1000 + cid
            dx = 1000 + cid
        else:
            _, dy, dx = best

        placed[cid] = (dy, dx)
        for y, x in cells:
            placed_cells.add((y+dy, x+dx))
        for y, x in twos:
            placed_twos.add((y+dy, x+dx))

    # Build output canvas.
    all_cells = list(placed_cells)
    if not all_cells:
        return [list(map(int, row)) for row in g]
    miny = min(y for y, _ in all_cells)
    minx = min(x for _, x in all_cells)
    maxy = max(y for y, _ in all_cells)
    maxx = max(x for _, x in all_cells)

    out_h = max(H, maxy - miny + 1)
    out_w = max(W, maxx - minx + 1)
    off_y = (out_h - (maxy - miny + 1)) // 2 - miny
    off_x = (out_w - (maxx - minx + 1)) // 2 - minx

    out = np.zeros((out_h, out_w), dtype=int)

    # Place colored cells.
    for cid, (dy, dx) in placed.items():
        for y, x in comps[cid]:
            ny = y + dy + off_y
            nx = x + dx + off_x
            if 0 <= ny < out_h and 0 <= nx < out_w:
                out[ny, nx] = g[y, x]

    # Recompute 2-cells: a cell is 2 if it is adjacent to colored cells on two opposite sides.
    colored = out != 0
    for y in range(out_h):
        for x in range(out_w):
            if out[y, x] != 0:
                continue
            up = y > 0 and colored[y-1, x]
            down = y + 1 < out_h and colored[y+1, x]
            left = x > 0 and colored[y, x-1]
            right = x + 1 < out_w and colored[y, x+1]
            if (up and down) or (left and right):
                out[y, x] = 2

    return [list(map(int, row)) for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    H, W = g.shape

    # The top instruction block is always 6 rows high in the provided cases.
    # The transformed area is everything below it.
    top_h = 6
    area = g[top_h:].copy()
    ah, aw = area.shape

    # Parse the four 6-column instruction cells.
    # Each cell has a 4x4 interior; a non-zero digit marks a vertical line.
    instr = {}
    for cell in range(4):
        c0 = cell * 6
        for r in range(1, 5):
            for c in range(c0 + 1, c0 + 5):
                v = g[r, c]
                if v != 0 and v != 5:
                    instr[v] = c - (c0 + 1)  # 0..3
                    break
            else:
                continue
            break

    # Find the central 2x2 8 block.
    center = None
    for r in range(ah - 1):
        for c in range(aw - 1):
            if (area[r, c] == 8 and area[r, c + 1] == 8 and
                area[r + 1, c] == 8 and area[r + 1, c + 1] == 8):
                center = (r, c)
                break
        if center:
            break

    if center is None:
        return area.tolist()

    cr, cc = center

    # Find rectangular blocks for the instruction colors.
    blocks = {}
    for color in instr:
        mask = (area == color)
        if not mask.any():
            continue
        rows = np.where(mask.any(axis=1))[0]
        cols = np.where(mask.any(axis=0))[0]
        r0, r1 = int(rows.min()), int(rows.max())
        c0, c1 = int(cols.min()), int(cols.max())
        blocks[color] = (r0, r1, c0, c1)

    def rect(r0, r1, c0, c1):
        r0 = max(0, min(r0, ah - 1))
        r1 = max(0, min(r1, ah - 1))
        c0 = max(0, min(c0, aw - 1))
        c1 = max(0, min(c1, aw - 1))
        if r0 <= r1 and c0 <= c1:
            area[r0:r1 + 1, c0:c1 + 1] = 8

    # The central 2x2 block is already 8.
    rect(cr, cr + 1, cc, cc + 1)

    # For each present instructed block, connect it to the central block
    # with 2-cell-wide corridors.
    for color, (r0, r1, c0, c1) in blocks.items():
        # Choose the side of the block facing the center.
        if cr < r0:
            # center above block: connect from block top
            rect(cr, r0, min(cc, c0), max(cc + 1, c1))
            rect(cr, r0, cc, cc + 1)
        elif cr + 1 > r1:
            # center below block: connect from block bottom
            rect(r1, cr + 1, min(cc, c0), max(cc + 1, c1))
            rect(r1, cr + 1, cc, cc + 1)
        elif cc < c0:
            # center left of block: connect from block left
            rect(min(cr, r0), max(cr + 1, r1), cc, c0)
            rect(cr, cr + 1, cc, c0)
        elif cc + 1 > c1:
            # center right of block: connect from block right
            rect(min(cr, r0), max(cr + 1, r1), c1, cc + 1)
            rect(cr, cr + 1, c1, cc + 1)
        else:
            # Overlapping projection: connect by the smaller gap.
            if min(abs(cr - r0), abs(cr - r1)) <= min(abs(cc - c0), abs(cc - c1)):
                if cr < r0:
                    rect(cr, r0, min(cc, c0), max(cc + 1, c1))
                else:
                    rect(r1, cr + 1, min(cc, c0), max(cc + 1, c1))
            else:
                if cc < c0:
                    rect(min(cr, r0), max(cr + 1, r1), cc, c0)
                else:
                    rect(min(cr, r0), max(cr + 1, r1), c1, cc + 1)

    return area.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    H, W = g.shape

    # The instruction header is always the first 6 rows.
    area = g[6:].copy()
    ah, aw = area.shape

    # Parse the four 6x6 instruction cells.
    # A non-5 digit in the 4x4 interior gives the target colour.
    # Its interior column (0..3) gives the horizontal offset of the
    # 2-cell-wide connector relative to the central 2x2 block.
    instr = {}
    for cell in range(4):
        c0 = cell * 6
        for r in range(1, 5):
            for c in range(c0 + 1, c0 + 5):
                v = g[r, c]
                if v != 0 and v != 5:
                    instr[v] = c - (c0 + 1)
                    break
            else:
                continue
            break

    # Find the central 2x2 block of 8s.
    center = None
    for r in range(ah - 1):
        for c in range(aw - 1):
            if (area[r, c] == 8 and area[r, c + 1] == 8 and
                area[r + 1, c] == 8 and area[r + 1, c + 1] == 8):
                center = (r, c)
                break
        if center:
            break

    if center is None:
        return area.tolist()

    cr, cc = center

    def fill(r0, r1, c0, c1):
        r0 = max(0, min(r0, ah - 1))
        r1 = max(0, min(r1, ah - 1))
        c0 = max(0, min(c0, aw - 1))
        c1 = max(0, min(c1, aw - 1))
        if r0 <= r1 and c0 <= c1:
            area[r0:r1 + 1, c0:c1 + 1] = 8

    # The central 2x2 block.
    fill(cr, cr + 1, cc, cc + 1)

    # For each instructed colour, find its rectangular block and connect
    # it to the central block with a 2-cell-wide orthogonal corridor.
    for color, off in instr.items():
        mask = (area == color)
        if not mask.any():
            continue

        rows = np.where(mask.any(axis=1))[0]
        cols = np.where(mask.any(axis=0))[0]
        r0, r1 = int(rows.min()), int(rows.max())
        c0, c1 = int(cols.min()), int(cols.max())

        # The connector column is aligned with the central block by the
        # offset encoded in the instruction cell.
        k = cc + off
        k = max(0, min(k, aw - 2))

        if r1 < cr:
            # Target is above the centre: vertical connector up to the block.
            fill(r1, cr, k, k + 1)
        elif r0 > cr + 1:
            # Target is below the centre: vertical connector down to the block.
            fill(cr + 1, r0, k, k + 1)
        elif c1 < cc:
            # Target is left of the centre: horizontal connector to the block.
            fill(cr, cr + 1, c1, cc)
        elif c0 > cc + 1:
            # Target is right of the centre: horizontal connector to the block.
            fill(cr, cr + 1, cc + 1, c0)
        else:
            # Overlapping projection: use the smaller gap.
            if min(abs(cr - r0), abs(cr - r1)) <= min(abs(cc - c0), abs(cc - c1)):
                if cr < r0:
                    fill(cr, r0, k, k + 1)
                else:
                    fill(r1, cr + 1, k, k + 1)
            else:
                if cc < c0:
                    fill(cr, cr + 1, cc, c0)
                else:
                    fill(cr, cr + 1, c1, cc + 1)

    return area.tolist()

import numpy as np
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    a = np.array(grid, dtype=int)
    h, w = a.shape

    # Background is the most frequent colour.
    vals, counts = np.unique(a, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # Connected components of non-background cells (4-connected).
    seen = np.zeros((h, w), dtype=bool)
    comps = []
    for y in range(h):
        for x in range(w):
            if seen[y, x] or a[y, x] == bg:
                continue
            color = int(a[y, x])
            q = deque([(y, x)])
            seen[y, x] = True
            cells = []
            while q:
                cy, cx = q.popleft()
                cells.append((cy, cx))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = cy + dy, cx + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny, nx] and a[ny, nx] != bg:
                        seen[ny, nx] = True
                        q.append((ny, nx))
            ys = [p[0] for p in cells]
            xs = [p[1] for p in cells]
            r0, r1 = min(ys), max(ys)
            c0, c1 = min(xs), max(xs)
            ph, pw = r1 - r0 + 1, c1 - c0 + 1
            mask = np.zeros((ph, pw), dtype=bool)
            for yy, xx in cells:
                mask[yy - r0, xx - c0] = True
            comps.append({
                "cells": cells,
                "color": color,
                "r0": r0, "r1": r1, "c0": c0, "c1": c1,
                "h": ph, "w": pw,
                "mask": mask,
                "size": len(cells),
            })

    if not comps:
        return [[int(v) for v in row] for row in a]

    # The frame is the largest non-background component.
    frame = max(comps, key=lambda c: c["size"])
    fr0, fr1, fc0, fc1 = frame["r0"], frame["r1"], frame["c0"], frame["c1"]
    fh, fw = fr1 - fr0 + 1, fc1 - fc0 + 1

    out = np.zeros((fh, fw), dtype=int)
    for yy, xx in frame["cells"]:
        out[yy - fr0, xx - fc0] = a[yy, xx]

    # Empty cells inside the frame bounding box.
    empty = (out == 0)
    empty_seen = np.zeros((fh, fw), dtype=bool)
    holes = []
    for y in range(fh):
        for x in range(fw):
            if not empty[y, x] or empty_seen[y, x]:
                continue
            q = deque([(y, x)])
            empty_seen[y, x] = True
            cells = []
            while q:
                cy, cx = q.popleft()
                cells.append((cy, cx))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = cy + dy, cx + dx
                    if 0 <= ny < fh and 0 <= nx < fw and empty[ny, nx] and not empty_seen[ny, nx]:
                        empty_seen[ny, nx] = True
                        q.append((ny, nx))
            ys = [p[0] for p in cells]
            xs = [p[1] for p in cells]
            hr0, hr1 = min(ys), max(ys)
            hc0, hc1 = min(xs), max(xs)
            hh, hw = hr1 - hr0 + 1, hc1 - hc0 + 1
            hmask = np.zeros((hh, hw), dtype=bool)
            for yy, xx in cells:
                hmask[yy - hr0, xx - hc0] = True
            holes.append({
                "cells": cells,
                "r0": hr0, "r1": hr1, "c0": hc0, "c1": hc1,
                "h": hh, "w": hw,
                "mask": hmask,
                "size": len(cells),
            })

    # Pieces are all non-frame components.
    pieces = [c for c in comps if c is not frame]

    # For each piece, generate all placements inside the frame bbox that cover
    # only currently empty cells.  Prefer placements that fill the largest
    # connected empty region, then the largest number of cells.
    placements = []
    for idx, p in enumerate(pieces):
        pm = p["mask"]
        ph, pw = p["h"], p["w"]
        for oy in range(fh - ph + 1):
            for ox in range(fw - pw + 1):
                ok = True
                for yy in range(ph):
                    row = pm[yy]
                    for xx in range(pw):
                        if row[xx] and not empty[oy + yy, ox + xx]:
                            ok = False
                            break
                    if not ok:
                        break
                if not ok:
                    continue
                # Score by how many cells of the placement lie in each hole.
                hole_counts = {}
                for yy in range(ph):
                    for xx in range(pw):
                        if pm[yy, xx]:
                            cy, cx = oy + yy, ox + xx
                            # Find hole id by scanning holes (small grids).
                            for hid, hole in enumerate(holes):
                                if hole["r0"] <= cy <= hole["r1"] and hole["c0"] <= cx <= hole["c1"] and hole["mask"][cy - hole["r0"], cx - hole["c0"]]:
                                    hole_counts[hid] = hole_counts.get(hid, 0) + 1
                                    break
                max_hole = max(hole_counts.values()) if hole_counts else 0
                placements.append((max_hole, p["size"], idx, oy, ox))

    # Apply placements greedily.  This is safe for the intended puzzles because
    # the pieces tile the empty region without conflicts.
    placements.sort(key=lambda t: (-t[0], -t[1], t[2], t[3], t[4]))
    for _, _, idx, oy, ox in placements:
        p = pieces[idx]
        pm = p["mask"]
        ph, pw = p["h"], p["w"]
        can = True
        for yy in range(ph):
            for xx in range(pw):
                if pm[yy, xx] and out[oy + yy, ox + xx] != 0:
                    can = False
                    break
            if not can:
                break
        if can:
            for yy in range(ph):
                for xx in range(pw):
                    if pm[yy, xx]:
                        out[oy + yy, ox + xx] = p["color"]

    # If any empty cells remain, fill them with the most common piece colour.
    if np.any(out == 0):
        from collections import Counter
        cnt = Counter(p["color"] for p in pieces)
        fill = cnt.most_common(1)[0][0] if cnt else 0
        out[out == 0] = fill

    return [[int(v) for v in row] for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Background is the most common colour.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # Collect all non-background pixels.
    ys, xs = np.where(g != bg)
    if len(ys) == 0:
        return out.tolist()

    # Determine the dominant line direction from the input pixels.
    # We only need to handle horizontal, vertical, and the two diagonal
    # directions that appear in this puzzle family.
    def score_dir(dy, dx):
        # For each pixel, count how many other pixels lie on the same
        # infinite line in this direction.  The direction with the largest
        # total collinearity is the object direction.
        total = 0
        for y, x in zip(ys, xs):
            cnt = 0
            yy, xx = y, x
            while 0 <= yy < h and 0 <= xx < w:
                if g[yy, xx] != bg:
                    cnt += 1
                yy += dy
                xx += dx
            yy, xx = y, x
            while 0 <= yy < h and 0 <= xx < w:
                if g[yy, xx] != bg:
                    cnt += 1
                yy -= dy
                xx -= dx
            total += cnt
        return total

    dirs = [(0, 1), (1, 0), (1, 1), (1, -1)]
    best = max(dirs, key=lambda d: score_dir(*d))
    dy, dx = best

    # A line is identified by its invariant coordinate.
    if dy == 0:
        def line_id(y, x):
            return y
    elif dx == 0:
        def line_id(y, x):
            return x
    elif dy == 1 and dx == 1:
        def line_id(y, x):
            return x - y
    else:  # dy == 1, dx == -1
        def line_id(y, x):
            return x + y

    # Group pixels by line and colour.
    lines = {}
    for y, x in zip(ys, xs):
        key = (line_id(y, x), int(g[y, x]))
        lines.setdefault(key, []).append((int(y), int(x)))

    # For each line, keep its colour and the set of occupied coordinates.
    line_info = []
    for (lid, color), pts in lines.items():
        line_info.append((lid, color, set(pts)))

    # The target length is the length of the line closest to the grid centre.
    # If several lines tie, prefer the one whose colour is most frequent.
    color_counts = {}
    for _, color, pts in line_info:
        color_counts[color] = color_counts.get(color, 0) + len(pts)

    cy, cx = (h - 1) / 2.0, (w - 1) / 2.0

    def line_center(pts):
        ys_ = [p[0] for p in pts]
        xs_ = [p[1] for p in pts]
        return sum(ys_) / len(ys_), sum(xs_) / len(xs_)

    def line_key(info):
        lid, color, pts = info
        y0, x0 = line_center(pts)
        dist = (y0 - cy) ** 2 + (x0 - cx) ** 2
        return (dist, -color_counts[color], -len(pts))

    ref_lid, ref_color, ref_pts = min(line_info, key=line_key)
    target_len = len(ref_pts)

    # For each line, produce a contiguous segment of length target_len.
    # The segment is aligned to the reference line's position along the
    # line direction, clipped to the grid.
    #
    # We parameterise each line by an integer t along (dy, dx).
    # For a point (y, x), t is chosen so that the line's points are
    # consecutive integers.
    def t_of(y, x):
        if dy == 0:
            return x
        if dx == 0:
            return y
        if dy == 1 and dx == 1:
            return y
        return y  # dy == 1, dx == -1

    # Reference t interval.
    ref_ts = sorted(t_of(y, x) for y, x in ref_pts)
    ref_start = ref_ts[0]
    ref_end = ref_ts[-1]

    # For each line, choose the target t interval of length target_len that
    # is closest to the reference interval, then clip to grid bounds.
    for lid, color, pts in line_info:
        ts = sorted(t_of(y, x) for y, x in pts)
        start = ts[0]
        end = ts[-1]

        # Desired interval: same length as reference, centred as close as
        # possible to the reference interval.
        desired_start = ref_start
        desired_end = ref_start + target_len - 1

        # If the line is already longer, keep the part closest to reference.
        if end - start + 1 > target_len:
            # Choose a window of length target_len inside [start, end]
            # whose centre is closest to the reference centre.
            ref_c = (ref_start + ref_end) / 2.0
            best_window = None
            best_score = None
            for s in range(start, end - target_len + 2):
                e = s + target_len - 1
                c = (s + e) / 2.0
                score = abs(c - ref_c)
                if best_score is None or score < best_score:
                    best_score = score
                    best_window = (s, e)
            desired_start, desired_end = best_window

        # Clip to valid grid coordinates for this line.
        def valid_t(t):
            if dy == 0:
                y = lid
                x = t
            elif dx == 0:
                y = t
                x = lid
            elif dy == 1 and dx == 1:
                y = t
                x = t + lid
            else:  # dy == 1, dx == -1
                y = t
                x = lid - t
            return 0 <= y < h and 0 <= x < w

        # Expand/shrink the desired interval to valid t values.
        s = desired_start
        while s <= desired_end and not valid_t(s):
            s += 1
        e = desired_end
        while e >= s and not valid_t(e):
            e -= 1

        # If clipping made it too short, try to recover length by extending
        # from the side that is closer to the reference interval.
        if e - s + 1 < target_len:
            ref_c = (ref_start + ref_end) / 2.0
            c = (s + e) / 2.0
            if c < ref_c:
                # Extend to the right first.
                while e - s + 1 < target_len:
                    if e + 1 <= desired_end + 100 and valid_t(e + 1):
                        e += 1
                    elif s - 1 >= desired_start - 100 and valid_t(s - 1):
                        s -= 1
                    else:
                        break
            else:
                # Extend to the left first.
                while e - s + 1 < target_len:
                    if s - 1 >= desired_start - 100 and valid_t(s - 1):
                        s -= 1
                    elif e + 1 <= desired_end + 100 and valid_t(e + 1):
                        e += 1
                    else:
                        break

        # Clear old pixels of this line/colour, then draw the new segment.
        for y, x in pts:
            out[y, x] = bg

        for t in range(s, e + 1):
            if dy == 0:
                y = lid
                x = t
            elif dx == 0:
                y = t
                x = lid
            elif dy == 1 and dx == 1:
                y = t
                x = t + lid
            else:
                y = t
                x = lid - t
            if 0 <= y < h and 0 <= x < w:
                out[y, x] = color

    return out.tolist()

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Background is the most common colour.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # Collect all non-background pixels.
    ys, xs = np.where(g != bg)
    if len(ys) == 0:
        return [[int(v) for v in row] for row in g]

    # Candidate line directions.
    dirs = [(0, 1), (1, 0), (1, 1), (1, -1)]

    # For a direction, score how well the non-background pixels lie on lines
    # parallel to that direction.  A good direction has few distinct line
    # invariants and each line is dense/contiguous.
    def direction_score(dy, dx):
        if dy == 0:
            def line_id(y, x):
                return y
        elif dx == 0:
            def line_id(y, x):
                return x
        elif dy == 1 and dx == 1:
            def line_id(y, x):
                return x - y
        else:  # dy == 1, dx == -1
            def line_id(y, x):
                return x + y

        lines = {}
        for y, x in zip(ys, xs):
            lines.setdefault(line_id(int(y), int(x)), []).append((int(y), int(x)))

        if not lines:
            return -1

        # Prefer directions with fewer lines, then longer average line.
        lens = [len(v) for v in lines.values()]
        return (len(lens), -sum(lens) / len(lens))

    # Choose the best direction.  Ties are broken deterministically.
    best_dir = max(dirs, key=lambda d: direction_score(*d))
    dy, dx = best_dir

    if dy == 0:
        def line_id(y, x):
            return y
    elif dx == 0:
        def line_id(y, x):
            return x
    elif dy == 1 and dx == 1:
        def line_id(y, x):
            return x - y
    else:  # dy == 1, dx == -1
        def line_id(y, x):
            return x + y

    # Group pixels by line and colour.
    lines = {}
    for y, x in zip(ys, xs):
        key = (line_id(int(y), int(x)), int(g[y, x]))
        lines.setdefault(key, []).append((int(y), int(x)))

    # For each line, keep its colour and occupied coordinates.
    line_info = []
    for (lid, color), pts in lines.items():
        line_info.append((lid, color, set(pts)))

    # The target length is the median line length.  If there is an even number
    # of lines, use the upper median.  This matches the examples:
    # lengths 2,6,12 -> 6; lengths 3,2,6,9,4 -> 6.
    lengths = sorted(len(pts) for _, _, pts in line_info)
    target_len = lengths[(len(lengths) - 1) // 2]

    # Parameterise each line by t along the chosen direction.
    def t_of(y, x):
        if dy == 0:
            return x
        if dx == 0:
            return y
        return y  # for both diagonals, y increases by 1 per step

    def point_from_t(lid, t):
        if dy == 0:
            return lid, t
        if dx == 0:
            return t, lid
        if dy == 1 and dx == 1:
            return t, t + lid
        # dy == 1, dx == -1
        return t, lid - t

    def valid_point(y, x):
        return 0 <= y < h and 0 <= x < w

    out = g.copy()

    # For every line, replace it by a contiguous segment of length target_len.
    # The segment is chosen to overlap the original line as much as possible.
    for lid, color, pts in line_info:
        ts = sorted(t_of(y, x) for y, x in pts)
        start, end = ts[0], ts[-1]
        original_len = end - start + 1

        # Choose a window of length target_len inside the original span if
        # possible; otherwise extend from the end that keeps the centre closest
        # to the original centre.
        if original_len >= target_len:
            # Pick the window whose centre is closest to the original centre.
            orig_c = (start + end) / 2.0
            best_s = start
            best_score = None
            for s in range(start, end - target_len + 2):
                e = s + target_len - 1
                c = (s + e) / 2.0
                score = abs(c - orig_c)
                if best_score is None or score < best_score:
                    best_score = score
                    best_s = s
            s, e = best_s, best_s + target_len - 1
        else:
            # Extend to reach target_len.  Prefer extending from the side that
            # keeps the new centre closest to the original centre.
            orig_c = (start + end) / 2.0
            need = target_len - original_len

            # Try all possible extensions of total length target_len that
            # contain the original interval.
            best_s, best_e = start, end
            best_score = None
            for left in range(need + 1):
                right = need - left
                s = start - left
                e = end + right
                c = (s + e) / 2.0
                score = abs(c - orig_c)
                if best_score is None or score < best_score:
                    best_score = score
                    best_s, best_e = s, e
            s, e = best_s, best_e

        # Clear the old pixels of this line/colour.
        for y, x in pts:
            out[y, x] = bg

        # Draw the new contiguous segment.
        for t in range(s, e + 1):
            y, x = point_from_t(lid, t)
            if valid_point(y, x):
                out[y, x] = color

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0]) if h else 0

    # For each colour, find the largest connected component (8-connected).
    # Only the largest component of each colour is kept; all other cells are ignored.
    best = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or color in best:
                continue
            stack = [(r, c)]
            seen = {(r, c)}
            while stack:
                y, x = stack.pop()
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        if dy == 0 and dx == 0:
                            continue
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w:
                            if (ny, nx) not in seen and grid[ny][nx] == color:
                                seen.add((ny, nx))
                                stack.append((ny, nx))
            if color not in best or len(seen) > len(best[color][0]):
                best[color] = (seen, (r, c))

    # Directional rule:
    # 1 -> 7, 2 -> 4, 4 -> 2, 6 -> 7, 7 -> 6
    # Each kept cell paints its opposite colour in the three orthogonal
    # directions except the direction it "points" to.
    mapping = {1: 7, 2: 4, 4: 2, 6: 7, 7: 6}
    excluded = {1: (1, 1), 2: (0, 1), 4: (0, -1), 6: (1, 0), 7: (-1, 0)}
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    out = [[0] * w for _ in range(h)]

    for color, (cells, _) in best.items():
        if color not in mapping:
            continue
        new_color = mapping[color]
        ex = excluded[color]
        for (r, c) in cells:
            for dr, dc in dirs:
                if (dr, dc) == ex:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w:
                    out[nr][nc] = new_color

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Find the 2x2 block of four distinct non-zero colors.
    core = None
    for r in range(h - 1):
        for c in range(w - 1):
            vals = [g[r, c], g[r, c + 1], g[r + 1, c], g[r + 1, c + 1]]
            if all(v != 0 for v in vals) and len(set(vals)) == 4:
                core = vals
                break
        if core is not None:
            break

    if core is None:
        # Fallback: should not happen for valid ARC inputs.
        return [[0] * w for _ in range(h)]

    a, b, c, d = core  # top-left, top-right, bottom-left, bottom-right

    # The hidden rule produces an 8x8 image from the 2x2 core:
    # - top-left color fills the upper-left triangle i + j <= 4
    # - top-right color fills the upper-right 4x3 rectangle
    # - bottom-left color fills the lower-left 3x5 rectangle
    # - bottom-right color fills the remaining cells
    out = [[d] * 8 for _ in range(8)]

    for i in range(8):
        for j in range(8):
            if i + j <= 4:
                out[i][j] = a
            elif i < 4 and j >= 5:
                out[i][j] = b
            elif i >= 5 and j <= 2:
                out[i][j] = c
            else:
                out[i][j] = d

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import defaultdict

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # background = most frequent colour
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # collect connected components (4-connectivity)
    comp_id = -np.ones((h, w), dtype=int)
    comps = []
    for r in range(h):
        for c in range(w):
            if g[r, c] != bg and comp_id[r, c] == -1:
                color = int(g[r, c])
                stack = [(r, c)]
                comp_id[r, c] = len(comps)
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w:
                            if g[ny, nx] == color and comp_id[ny, nx] == -1:
                                comp_id[ny, nx] = len(comps)
                                stack.append((ny, nx))
                ys = [p[0] for p in cells]
                xs = [p[1] for p in cells]
                comps.append({
                    "color": color,
                    "cells": cells,
                    "r0": min(ys), "r1": max(ys),
                    "c0": min(xs), "c1": max(xs),
                    "h": max(ys) - min(ys) + 1,
                    "w": max(xs) - min(xs) + 1,
                    "area": len(cells),
                })

    if not comps:
        return []

    # choose the largest component as the container
    container = max(comps, key=lambda c: (c["area"], c["h"] * c["w"], c["color"]))
    r0, r1, c0, c1 = container["r0"], container["r1"], container["c0"], container["c1"]
    H, W = r1 - r0 + 1, c1 - c0 + 1

    out = [[0] * W for _ in range(H)]

    # place container cells
    for y, x in container["cells"]:
        out[y - r0][x - c0] = container["color"]

    # other components, sorted by size (larger pieces first)
    others = [c for c in comps if c is not container]
    others.sort(key=lambda c: (-c["area"], -c["h"] * c["w"], c["color"]))

    # empty cells in the container bounding box
    empty = [(i, j) for i in range(H) for j in range(W) if out[i][j] == 0]

    # try to place each other component into an empty region of the same shape
    for comp in others:
        ch, cw = comp["h"], comp["w"]
        if ch > H or cw > W:
            continue

        # relative pattern of this component
        pattern = set((y - comp["r0"], x - comp["c0"]) for y, x in comp["cells"])

        best = None
        best_score = -1
        for i in range(H - ch + 1):
            for j in range(W - cw + 1):
                ok = True
                for dy, dx in pattern:
                    if out[i + dy][j + dx] != 0:
                        ok = False
                        break
                if not ok:
                    continue
                # prefer placements that use more currently empty cells
                score = 0
                for dy, dx in pattern:
                    if out[i + dy][j + dx] == 0:
                        score += 1
                if score > best_score:
                    best_score = score
                    best = (i, j)

        if best is not None:
            i, j = best
            for dy, dx in pattern:
                out[i + dy][j + dx] = comp["color"]

    # if any empty cells remain, fill them with the most common remaining colour
    if any(out[i][j] == 0 for i in range(H) for j in range(W)):
        used_colors = set()
        for row in out:
            for v in row:
                if v != 0:
                    used_colors.add(v)
        remaining = [c for c in comps if c["color"] not in used_colors]
        if remaining:
            fill_color = max(remaining, key=lambda c: c["area"])["color"]
        else:
            fill_color = container["color"]
        for i in range(H):
            for j in range(W):
                if out[i][j] == 0:
                    out[i][j] = fill_color

    return out

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape

    # background is the most frequent colour
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # find the container: a hollow rectangle whose border colour is not bg
    # and whose interior is filled with a single non-border colour
    best = None
    for r1 in range(H):
        for r2 in range(r1 + 2, H):
            for c1 in range(W):
                for c2 in range(c1 + 2, W):
                    border = g[r1, c1:c2 + 1]
                    if not np.all(border == border[0]):
                        continue
                    border = g[r2, c1:c2 + 1]
                    if not np.all(border == border[0]):
                        continue
                    border = g[r1:r2 + 1, c1]
                    if not np.all(border == border[0]):
                        continue
                    border = g[r1:r2 + 1, c2]
                    if not np.all(border == border[0]):
                        continue
                    bcol = int(g[r1, c1])
                    if bcol == bg:
                        continue
                    interior = g[r1 + 1:r2, c1 + 1:c2]
                    if interior.size == 0:
                        continue
                    iv, ic = np.unique(interior, return_counts=True)
                    if len(iv) == 1:
                        fill = int(iv[0])
                        if fill == bcol:
                            continue
                        area = (r2 - r1 + 1) * (c2 - c1 + 1)
                        if best is None or area > best[0]:
                            best = (area, r1, c1, r2, c2, bcol, fill)

    if best is None:
        return [[int(x) for x in row] for row in g]

    _, R1, C1, R2, C2, bcol, fill = best
    out = np.full((R2 - R1 - 1, C2 - C1 - 1), fill, dtype=int)

    # collect all other non-background pixels
    mask = (g != bg) & (g != bcol) & (g != fill)
    ys, xs = np.nonzero(mask)

    # group pixels into connected components (8-connected)
    parent = list(range(len(ys)))

    def find(a):
        while parent[a] != a:
            parent[a] = parent[parent[a]]
            a = parent[a]
        return a

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[rb] = ra

    # simple O(n^2) union is fine for ARC-sized grids
    for i in range(len(ys)):
        for j in range(i + 1, len(ys)):
            if abs(ys[i] - ys[j]) <= 1 and abs(xs[i] - xs[j]) <= 1:
                union(i, j)

    comps = {}
    for i in range(len(ys)):
        comps.setdefault(find(i), []).append(i)

    # For each component, infer its full rectangular border pattern.
    # The component is a (possibly partially hidden) rectangle border.
    # We reconstruct the border by taking the visible bounding box and
    # filling the border with the component's colour pattern if it is
    # uniform, otherwise with the visible border pixels where available.
    for idx in comps.values():
        if not idx:
            continue
        cy = [ys[i] for i in idx]
        cx = [xs[i] for i in idx]
        y0, y1 = min(cy), max(cy)
        x0, x1 = min(cx), max(cx)

        # If the component is too small or not rectangular enough, skip.
        if y1 - y0 < 1 or x1 - x0 < 1:
            continue

        # Reconstruct a full rectangle border of the same size.
        # Use the most common colour in the component as the border colour.
        cols = [g[ys[i], xs[i]] for i in idx]
        cv, cc = np.unique(cols, return_counts=True)
        col = int(cv[np.argmax(cc)])

        # Build border pattern: if visible border pixels are consistent,
        # use them; otherwise use the single colour.
        border = np.zeros((y1 - y0 + 1, x1 - x0 + 1), dtype=int)
        for i in idx:
            y, x = ys[i], xs[i]
            if y == y0 or y == y1 or x == x0 or x == x1:
                border[y - y0, x - x0] = g[y, x]

        # Fill any missing border cells with the component colour.
        for yy in range(border.shape[0]):
            for xx in range(border.shape[1]):
                if yy == 0 or yy == border.shape[0] - 1 or xx == 0 or xx == border.shape[1] - 1:
                    if border[yy, xx] == 0:
                        border[yy, xx] = col

        # Project this reconstructed border into the container interior.
        # The translation is chosen so that the component's bounding box
        # is aligned with the container's bounding box in the same relative
        # way as in the input: we use the offset from the container's
        # top-left to the component's top-left, but clipped to the interior.
        # In practice, the hidden part of the component that lies inside
        # the container interior is exactly what should be shown.
        # Therefore, we simply copy the part of the reconstructed border
        # that overlaps the container interior.
        for yy in range(border.shape[0]):
            gy = y0 + yy
            if R1 < gy < R2:
                oy = gy - R1 - 1
                for xx in range(border.shape[1]):
                    gx = x0 + xx
                    if C1 < gx < C2:
                        ox = gx - C1 - 1
                        val = border[yy, xx]
                        if val != 0:
                            out[oy, ox] = val

    return out.tolist()

