def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Remove the 6-row header.
    scene = g[6:].copy()
    sh, sw = scene.shape

    # Background is the most common colour in the scene.
    vals, counts = np.unique(scene, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # Marker is the 2x2 block of colour 8.
    marker_cells = np.argwhere(scene == 8)
    mr0 = int(marker_cells[:, 0].min())
    mr1 = int(marker_cells[:, 0].max())
    mc0 = int(marker_cells[:, 1].min())
    mc1 = int(marker_cells[:, 1].max())

    # Find all non-background, non-marker rectangles.
    rects = []
    for c in np.unique(scene):
        if c == bg or c == 8:
            continue
        ys, xs = np.where(scene == c)
        r0, r1 = int(ys.min()), int(ys.max())
        c0, c1 = int(xs.min()), int(xs.max())
        # Keep only solid rectangular blocks.
        if np.all(scene[r0:r1 + 1, c0:c1 + 1] == c):
            rects.append((r0, r1, c0, c1, int(c)))

    # For each rectangle, choose the side closest to the marker.
    # The side is encoded by the position of its colour in the header:
    # left half of its 4-column cell -> left/top side, right half -> right/bottom side.
    def header_side(colour: int) -> str:
        # Header rows 1-4 contain the colour somewhere in one of four 4-column cells.
        for r in range(1, 5):
            row = g[r]
            for c in range(W):
                if row[c] == colour:
                    # Four cells: columns 1-4, 7-10, 13-16, 19-22.
                    if 1 <= c <= 4:
                        cell = 0
                    elif 7 <= c <= 10:
                        cell = 1
                    elif 13 <= c <= 16:
                        cell = 2
                    elif 19 <= c <= 22:
                        cell = 3
                    else:
                        continue
                    # Left/right inside the cell.
                    if c <= cell * 6 + 2:  # left half of the cell
                        return "L"
                    else:
                        return "R"
        return "L"

    def add_line(out, r0, r1, c0, c1):
        for r in range(max(0, r0), min(sh, r1 + 1)):
            for c in range(max(0, c0), min(sw, c1 + 1)):
                if out[r, c] == bg:
                    out[r, c] = 8

    out = scene.copy()

    # Marker cross: vertical and horizontal lines through the marker.
    add_line(out, 0, sh - 1, mc0, mc1)
    add_line(out, mr0, mr1, 0, sw - 1)

    for r0, r1, c0, c1, col in rects:
        side = header_side(col)

        # Determine the closest side of the rectangle to the marker.
        # Horizontal distance to left/right sides.
        dl = max(0, mc0 - c1)
        dr = max(0, c0 - mc1)
        # Vertical distance to top/bottom sides.
        dt = max(0, mr0 - r1)
        db = max(0, r0 - mr1)

        # If the marker is horizontally aligned, prefer horizontal side.
        if mr0 <= r1 and mr1 >= r0:
            if dl <= dr:
                chosen = "left"
            else:
                chosen = "right"
        elif mc0 <= c1 and mc1 >= c0:
            if dt <= db:
                chosen = "top"
            else:
                chosen = "bottom"
        else:
            # Otherwise choose the nearest of the four sides.
            candidates = [
                (dl, "left"),
                (dr, "right"),
                (dt, "top"),
                (db, "bottom"),
            ]
            candidates.sort()
            chosen = candidates[0][1]

        # The header side can flip the chosen side to the opposite one.
        if side == "L":
            if chosen == "right":
                chosen = "left"
            elif chosen == "bottom":
                chosen = "top"
        else:  # R
            if chosen == "left":
                chosen = "right"
            elif chosen == "top":
                chosen = "bottom"

        # Draw a 2-cell-wide line of 8s from that side toward the marker,
        # stopping at the marker or the grid edge.
        if chosen == "left":
            # Vertical line just to the right of the rectangle.
            add_line(out, r0, r1, c1 + 1, c1 + 2)
            # Horizontal connector at marker rows if aligned.
            if mr0 <= r1 and mr1 >= r0:
                add_line(out, mr0, mr1, c1 + 1, mc0)
        elif chosen == "right":
            add_line(out, r0, r1, c0 - 2, c0 - 1)
            if mr0 <= r1 and mr1 >= r0:
                add_line(out, mr0, mr1, mc1, c0 - 1)
        elif chosen == "top":
            add_line(out, r1 + 1, r1 + 2, c0, c1)
            if mc0 <= c1 and mc1 >= c0:
                add_line(out, r1 + 1, mr0, mc0, mc1)
        elif chosen == "bottom":
            add_line(out, r0 - 2, r0 - 1, c0, c1)
            if mc0 <= c1 and mc1 >= c0:
                add_line(out, mr1, r0 - 1, mc0, mc1)

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Find the 5-bordered rectangle.
    rows = [r for r in range(H) if np.any(g[r] == 5)]
    cols = [c for c in range(W) if np.any(g[:, c] == 5)]
    r0, r1 = min(rows), max(rows)
    c0, c1 = min(cols), max(cols)

    # Crop to the rectangle including its border.
    rect = g[r0:r1 + 1, c0:c1 + 1].copy()
    h, w = rect.shape

    # Interior (without the 5 border).
    inner = rect[1:-1, 1:-1]
    ih, iw = inner.shape

    # Background / separator color is the most common color in the interior.
    vals, counts = np.unique(inner, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # Determine block size from the first non-background run in the interior.
    block = 1
    for r in range(ih):
        for c in range(iw):
            if inner[r, c] != bg:
                d = 1
                while c + d < iw and inner[r, c + d] != bg:
                    d += 1
                block = d
                break
        if block > 1:
            break

    # Build a lookup from the "legend" outside the 5 rectangle.
    # Each legend block has the same size as the interior blocks and contains
    # exactly two colors: the block color and an accent color.
    legend = {}
    for r in range(0, H - block + 1):
        for c in range(0, W - block + 1):
            # Do not use blocks inside the target rectangle.
            if r + block - 1 >= r0 and r <= r1 and c + block - 1 >= c0 and c <= c1:
                continue
            sub = g[r:r + block, c:c + block]
            vals, counts = np.unique(sub, return_counts=True)
            if len(vals) != 2:
                continue
            main, accent = (int(vals[0]), int(vals[1])) if counts[0] >= counts[1] else (int(vals[1]), int(vals[0]))
            if main not in legend:
                legend[main] = (accent, sub)

    def output_block(color: int) -> np.ndarray:
        # Fallback if a color is not present in the legend.
        if color not in legend:
            return np.full((block, block), color, dtype=int)

        accent, sub = legend[color]
        out = np.full((block, block), accent, dtype=int)

        # Cells that are the main color in the legend become background.
        out[sub == color] = bg

        # If the legend is not symmetric, mirror it horizontally.
        if not np.array_equal(sub, sub[:, ::-1]):
            out = out[:, ::-1]

        return out

    # Replace each interior block.
    for br in range(0, ih, block + 1):
        for bc in range(0, iw, block + 1):
            sub = inner[br:br + block, bc:bc + block]
            vals, counts = np.unique(sub, return_counts=True)
            if len(vals) == 1:
                color = int(vals[0])
            else:
                color = int(vals[np.argmax(counts)])
            if color == bg:
                continue
            rect[br + 1:br + 1 + block, bc + 1:bc + 1 + block] = output_block(color)

    return rect.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Locate the 5-bordered rectangle.
    rows5 = [r for r in range(H) if np.any(g[r] == 5)]
    cols5 = [c for c in range(W) if np.any(g[:, c] == 5)]
    r0, r1 = min(rows5), max(rows5)
    c0, c1 = min(cols5), max(cols5)

    rect = g[r0:r1 + 1, c0:c1 + 1].copy()
    inner = rect[1:-1, 1:-1]
    ih, iw = inner.shape

    # Background/separator color inside the rectangle.
    vals, counts = np.unique(inner, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # Determine block size from the first non-background run in the interior.
    B = 1
    for r in range(ih):
        for c in range(iw):
            if inner[r, c] != bg:
                d = 1
                while c + d < iw and inner[r, c + d] != bg:
                    d += 1
                B = d
                break
        if B > 1:
            break

    # Collect candidate BxB blocks outside the 5-rectangle.
    candidates = []
    for r in range(0, H - B + 1):
        for c in range(0, W - B + 1):
            if r + B - 1 >= r0 and r <= r1 and c + B - 1 >= c0 and c <= c1:
                continue
            sub = g[r:r + B, c:c + B]
            u, cnt = np.unique(sub, return_counts=True)
            if len(u) < 2:
                continue
            main = int(u[np.argmax(cnt)])
            if main == 5:
                continue
            # Keep blocks that are mostly one color and contain at most one
            # other non-background color.
            others = [int(x) for x in u if x != main]
            if len(others) > 2:
                continue
            nonbg_others = [x for x in others if x != bg]
            if len(nonbg_others) > 1:
                continue
            candidates.append((main, sub, nonbg_others))

    # For each interior color, find:
    # - output color: accent color from a legend block of that main color
    # - pattern: a legend block of that main color whose accent is background
    color_map = {}
    pattern_map = {}

    interior_colors = set(int(x) for x in np.unique(inner) if x != bg)

    for color in interior_colors:
        same = [item for item in candidates if item[0] == color]
        if not same:
            color_map[color] = color
            pattern_map[color] = np.ones((B, B), dtype=int)
            continue

        # Output color from non-background accent.
        out_color = color
        for _, sub, nonbg in same:
            if nonbg:
                out_color = nonbg[0]
                break
        color_map[color] = out_color

        # Pattern from background-accent block.
        best = None
        best_score = -1
        for _, sub, nonbg in same:
            if bg in sub and color in sub:
                # Prefer blocks where background is the only non-main color.
                score = 0
                if not nonbg:
                    score += 10
                # Prefer more background cells (clearer shape).
                score += int(np.sum(sub == bg))
                if score > best_score:
                    best_score = score
                    best = sub
        if best is None:
            pattern_map[color] = np.ones((B, B), dtype=int)
        else:
            pat = np.full((B, B), out_color, dtype=int)
            pat[best == bg] = bg
            pattern_map[color] = pat

    # Replace each interior block.
    for br in range(0, ih, B + 1):
        for bc in range(0, iw, B + 1):
            if br + B > ih or bc + B > iw:
                continue
            sub = inner[br:br + B, bc:bc + B]
            u, cnt = np.unique(sub, return_counts=True)
            if len(u) == 1:
                color = int(u[0])
            else:
                color = int(u[np.argmax(cnt)])
            if color == bg:
                continue
            rect[br + 1:br + 1 + B, bc + 1:bc + 1 + B] = pattern_map[color]

    return rect.tolist()

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Find the rectangular frame whose border is a single non-background colour.
    # In the examples this is the 5-frame that is cropped in the output.
    best = None
    for r0 in range(H):
        for r1 in range(r0 + 2, H):
            for c0 in range(W):
                for c1 in range(c0 + 2, W):
                    border = set()
                    border.update(g[r0, c0:c1 + 1].tolist())
                    border.update(g[r1, c0:c1 + 1].tolist())
                    border.update(g[r0:r1 + 1, c0].tolist())
                    border.update(g[r0:r1 + 1, c1].tolist())
                    if len(border) == 1:
                        col = border.pop()
                        if col == 0:
                            continue
                        area = (r1 - r0 + 1) * (c1 - c0 + 1)
                        if best is None or area > best[0]:
                            best = (area, r0, r1, c0, c1, col)

    if best is None:
        return [list(row) for row in g]

    _, r0, r1, c0, c1, frame_col = best
    frame = g[r0:r1 + 1, c0:c1 + 1].copy()
    fh, fw = frame.shape

    # The frame interior is a grid of uniform square blocks separated by
    # one-cell separator lines.  Determine the block size and layout.
    def is_uniform_block(sub):
        vals = set(sub.tolist())
        vals.discard(0)
        return len(vals) == 1

    block_size = None
    for s in range(1, min(fh, fw) // 2 + 1):
        ok = True
        for br in range(1, fh - 1, s + 1):
            for bc in range(1, fw - 1, s + 1):
                if br + s >= fh or bc + s >= fw:
                    continue
                if not is_uniform_block(frame[br:br + s, bc:bc + s]):
                    ok = False
                    break
            if not ok:
                break
        if ok:
            block_size = s
            break

    if block_size is None:
        return [list(row) for row in frame]

    s = block_size
    rows = []
    for br in range(1, fh - 1, s + 1):
        if br + s < fh:
            rows.append(br)
    cols = []
    for bc in range(1, fw - 1, s + 1):
        if bc + s < fw:
            cols.append(bc)

    # Collect all non-frame, non-zero colours outside the frame.
    outside = np.zeros_like(g)
    outside[:r0, :] = g[:r0, :]
    outside[r1 + 1:, :] = g[r1 + 1:, :]
    outside[r0:r1 + 1, :c0] = g[r0:r1 + 1, :c0]
    outside[r0:r1 + 1, c1 + 1:] = g[r0:r1 + 1, c1 + 1:]

    outside_colors = set(np.unique(outside).tolist())
    outside_colors.discard(0)
    outside_colors.discard(frame_col)

    # For each colour, find the best matching s x s pattern outside the frame.
    # A pattern is a binary mask of that colour; the output block is filled
    # with the colour that appears in the corresponding input block.
    def mask_for_color(col):
        return (outside == col)

    def score_mask(mask, col):
        # Count how many s x s windows of the mask look like a plausible
        # pattern: mostly the colour, with some background holes.
        best_score = -1
        best_mask = None
        for rr in range(H - s + 1):
            for cc in range(W - s + 1):
                win = mask[rr:rr + s, cc:cc + s]
                if not win.any():
                    continue
                filled = int(win.sum())
                # Prefer dense blocks, but allow holes.
                if filled < s * s // 2:
                    continue
                # Penalise windows that touch other colours or frame colour.
                sub = g[rr:rr + s, cc:cc + s]
                bad = int(np.sum((sub != col) & (sub != 0) & (sub != frame_col)))
                score = filled * 10 - bad * 100
                if score > best_score:
                    best_score = score
                    best_mask = win.copy()
        return best_mask

    # If the above is too weak, fall back to the first dense window.
    def first_dense_mask(col):
        m = (g == col)
        for rr in range(H - s + 1):
            for cc in range(W - s + 1):
                win = m[rr:rr + s, cc:cc + s]
                if win.sum() >= s * s // 2:
                    return win.copy()
        return None

    pattern_by_color = {}
    for col in outside_colors:
        m = score_mask(mask_for_color(col), col)
        if m is None:
            m = first_dense_mask(col)
        if m is not None:
            pattern_by_color[col] = m

    # Build output: same frame, but replace each uniform block by the pattern
    # associated with the colour that appears in that block.
    out = frame.copy()
    for br in rows:
        for bc in cols:
            block = frame[br:br + s, bc:bc + s]
            vals = set(block.tolist())
            vals.discard(0)
            if len(vals) != 1:
                continue
            col = vals.pop()
            if col == frame_col:
                continue
            pat = pattern_by_color.get(col)
            if pat is None:
                continue
            # If the pattern colour differs from the block colour, recolor it.
            out[br:br + s, bc:bc + s] = np.where(pat, col, 0)

    # In the examples, holes are the separator/background colour inside the
    # frame, not 0.  Use the dominant non-frame colour inside the frame as
    # the hole colour.
    inner = frame[1:-1, 1:-1]
    inner_vals = [v for v in np.unique(inner).tolist() if v != frame_col]
    if inner_vals:
        hole = max(set(inner_vals), key=inner_vals.count)
        out = np.where(out == 0, hole, out)

    return [list(row) for row in out]

