def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])

    # Background is the most frequent colour.
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=lambda k: counts[k])

    # Find the unique solid-colour rectangular frame (the "mask" frame).
    frame = None
    for c in counts:
        if c == bg:
            continue
        cells = [(r, cc) for r in range(h) for cc in range(w) if grid[r][cc] == c]
        if not cells:
            continue
        rmin = min(r for r, _ in cells)
        rmax = max(r for r, _ in cells)
        cmin = min(cc for _, cc in cells)
        cmax = max(cc for _, cc in cells)
        if rmax - rmin < 2 or cmax - cmin < 2:
            continue
        expected = 2 * (rmax - rmin + 1) + 2 * (cmax - cmin + 1) - 4
        if len(cells) != expected:
            continue
        ok = True
        for r in range(rmin, rmax + 1):
            for cc in range(cmin, cmax + 1):
                is_border = (r == rmin or r == rmax or cc == cmin or cc == cmax)
                if (grid[r][cc] == c) != is_border:
                    ok = False
                    break
            if not ok:
                break
        if ok:
            frame = (rmin, rmax, cmin, cmax, c)
            break

    if frame is None:
        return [row[:] for row in grid]

    frmin, frmax, fcmin, fcmax, fcolor = frame

    # Collect all non-background, non-frame cells.
    others = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
              if grid[r][c] != bg and grid[r][c] != fcolor]

    # For each colour, keep the connected component that touches the frame.
    def touches_frame(cells):
        for r, c in cells:
            if (r == frmin - 1 and fcmin <= c <= fcmax) or \
               (r == frmax + 1 and fcmin <= c <= fcmax) or \
               (c == fcmin - 1 and frmin <= r <= frmax) or \
               (c == fcmax + 1 and frmin <= r <= frmax):
                return True
        return False

    def component(cells, start):
        stack = [start]
        seen = {start}
        comp = []
        while stack:
            r, c = stack.pop()
            comp.append((r, c))
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if (nr, nc) not in seen and (nr, nc) in cells:
                    seen.add((nr, nc))
                    stack.append((nr, nc))
        return comp

    kept = []
    by_color = {}
    for r, c, v in others:
        by_color.setdefault(v, set()).add((r, c))

    for v, cells in by_color.items():
        cells = set(cells)
        seen = set()
        best = None
        for s in cells:
            if s in seen:
                continue
            comp = component(cells, s)
            seen.update(comp)
            if touches_frame(comp):
                if best is None or len(comp) > len(best):
                    best = comp
        if best:
            for r, c in best:
                kept.append((r, c, v))

    if not kept:
        return [row[:] for row in grid]

    rmin = min(r for r, _, _ in kept)
    rmax = max(r for r, _, _ in kept)
    cmin = min(c for _, c, _ in kept)
    cmax = max(c for _, c, _ in kept)

    out = [[bg] * (cmax - cmin + 1) for _ in range(rmax - rmin + 1)]
    for r, c, v in kept:
        out[r - rmin][c - cmin] = v

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Find the largest solid-color rectangle (ignoring 0).
    best = None
    for r0 in range(H):
        for r1 in range(r0, H):
            for c0 in range(W):
                for c1 in range(c0, W):
                    sub = g[r0:r1 + 1, c0:c1 + 1]
                    vals = np.unique(sub)
                    if len(vals) == 1 and vals[0] != 0:
                        area = (r1 - r0 + 1) * (c1 - c0 + 1)
                        if best is None or area > best[0]:
                            best = (area, int(vals[0]), r0, r1, c0, c1)

    if best is None:
        return [[int(x) for x in row] for row in g]

    _, fill_color, fr0, fr1, fc0, fc1 = best
    fh = fr1 - fr0 + 1
    fw = fc1 - fc0 + 1

    # Find the largest non-zero rectangle that is not completely solid.
    pat_best = None
    for r0 in range(H):
        for r1 in range(r0, H):
            for c0 in range(W):
                for c1 in range(c0, W):
                    sub = g[r0:r1 + 1, c0:c1 + 1]
                    nz = sub[sub != 0]
                    if nz.size == 0:
                        continue
                    if len(np.unique(nz)) > 1:
                        area = (r1 - r0 + 1) * (c1 - c0 + 1)
                        if pat_best is None or area > pat_best[0]:
                            pat_best = (area, r0, r1, c0, c1)

    if pat_best is None:
        return [[int(x) for x in row] for row in g]

    _, pr0, pr1, pc0, pc1 = pat_best
    ph = pr1 - pr0 + 1
    pw = pc1 - pc0 + 1

    # Fill zeros in the pattern with the solid color.
    pattern = g[pr0:pr1 + 1, pc0:pc1 + 1].copy()
    pattern[pattern == 0] = fill_color

    # Output size: pattern size plus the solid rectangle's dimensions.
    out_h = ph + fh
    out_w = pw + fw

    # Top-left crop of the periodic tiling of the pattern.
    out = np.empty((out_h, out_w), dtype=int)
    for i in range(out_h):
        for j in range(out_w):
            out[i, j] = pattern[i % ph, j % pw]

    return out.tolist()

