        for r1 in range(r0, H):
            for c0 in range(W):
                for c1 in range(c0, W):
                    sub = g[r0:r1 + 1, c0:c1 + 1]
                    vals = np.unique(sub)
                    if len(vals) == 1 and vals[0] != 0:
                        area = (r1 - r0 + 1) * (c1 - c0 + 1)
                        if solid is None or area > solid[0]:
                            solid = (area, int(vals[0]), r0, r1, c0, c1)

    if solid is None:
        return [[int(x) for x in row] for row in g]

    _, fill, sr0, sr1, sc0, sc1 = solid
    sh = sr1 - sr0 + 1
    sw = sc1 - sc0 + 1

    # Find the largest non-solid non-zero rectangle.
    pat = None
    for r0 in range(H):
        for r1 in range(r0, H):
            for c0 in range(W):
                for c1 in range(c0, W):
                    sub = g[r0:r1 + 1, c0:c1 + 1]
                    nz = sub[sub != 0]
                    if nz.size == 0:
                        continue
                    if len(np.unique(nz)) > 1:
                        area = (r1 - r0 + 1) * (c1 - c0 + 1)
                        if pat is None or area > pat[0]:
                            pat = (area, r0, r1, c0, c1)

    if pat is None:
        return [[int(x) for x in row] for row in g]

    _, pr0, pr1, pc0, pc1 = pat
    ph = pr1 - pr0 + 1
    pw = pc1 - pc0 + 1

    # Fill zeros in the pattern with the solid colour.
    pattern = g[pr0:pr1 + 1, pc0:pc1 + 1].copy()
    pattern[pattern == 0] = fill

    # Output is the top-left crop of the periodic tiling of the pattern
    # to the size (pattern height + solid height, pattern width + solid width).
    out_h = ph + sh
    out_w = pw + sw

    out = np.empty((out_h, out_w), dtype=int)
    for i in range(out_h):
        for j in range(out_w):
            out[i, j] = pattern[i % ph, j % pw]

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Find the non-background color.
    # Background is the most frequent color in the grid.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # Collect all non-background colors.
    colors = [int(c) for c in vals if c != bg]

    # For each color, find its line segments.
    # In the examples, segments are either vertical or diagonal (down-left).
    # We infer the orientation from the set of non-background cells.
    for color in colors:
        mask = (g == color)
        cells = np.argwhere(mask)
        if len(cells) == 0:
            continue

        # Determine orientation:
        # If all cells share the same column -> vertical.
        # If all cells share the same r+c -> diagonal down-left.
        cols = cells[:, 1]
        sums = cells[:, 0] + cells[:, 1]

        if len(np.unique(cols)) == 1:
            orientation = "vertical"
        elif len(np.unique(sums)) == 1:
            orientation = "diagonal"
        else:
            # Group by column if mostly vertical, else by anti-diagonal.
            # This fallback is not expected for the given tasks.
            if len(np.unique(cols)) <= len(np.unique(sums)):
                orientation = "vertical"
            else:
                orientation = "diagonal"

        # Build segments.
        segments = []  # list of (key, [cells])
        if orientation == "vertical":
            by_key = {}
            for r, c in cells:
                by_key.setdefault(int(c), []).append((int(r), int(c)))
            for c, pts in by_key.items():
                pts.sort()
                # Split into contiguous vertical runs.
                run = [pts[0]]
                for p in pts[1:]:
                    if p[0] == run[-1][0] + 1:
                        run.append(p)
                    else:
                        segments.append((c, run))
                        run = [p]
                segments.append((c, run))
        else:
            by_key = {}
            for r, c in cells:
                by_key.setdefault(int(r + c), []).append((int(r), int(c)))
            for s, pts in by_key.items():
                pts.sort()
                # Split into contiguous diagonal runs (r increases by 1, c decreases by 1).
                run = [pts[0]]
                for p in pts[1:]:
                    if p[0] == run[-1][0] + 1 and p[1] == run[-1][1] - 1:
                        run.append(p)
                    else:
                        segments.append((s, run))
                        run = [p]
                segments.append((s, run))

        if not segments:
            continue

        lengths = [len(seg) for _, seg in segments]

        # Choose target length:
        # - If there is a unique most frequent length, use it.
        # - Otherwise, use the second largest length if it exists.
        # - Otherwise, use the largest length.
        from collections import Counter
        cnt = Counter(lengths)
        max_count = max(cnt.values())
        modes = [L for L, n in cnt.items() if n == max_count]

        if len(modes) == 1:
            target = modes[0]
        else:
            unique_lengths = sorted(set(lengths), reverse=True)
            if len(unique_lengths) >= 2:
                target = unique_lengths[1]
            else:
                target = unique_lengths[0]

        # Rewrite each segment to have exactly `target` cells.
        # Keep the original starting cell; extend in the natural direction.
        # If the segment is longer than target, keep its first `target` cells.
        for key, seg in segments:
            start = seg[0]
            # Remove old cells of this segment.
            for r, c in seg:
                out[r, c] = bg

            # Generate new cells.
            for i in range(target):
                if orientation == "vertical":
                    r = start[0] + i
                    c = start[1]
                else:
                    r = start[0] + i
                    c = start[1] - i
                if 0 <= r < h and 0 <= c < w:
                    out[r, c] = color

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    H, W = g.shape
    out = np.zeros((H, W), dtype=int)

    # Colours 2 and 4 are used in the examples as temporary markers.
    # They are never present in the output.
    marker_cols = {2, 4}
    final_cols = [c for c in range(1, 10) if c not in marker_cols and np.any(g == c)]

    # Lower colour numbers are drawn on top of higher colour numbers.
    final_cols.sort()

    for c in final_cols:
        # Anchors are the visible pixels of this colour plus marker pixels.
        # Markers are used only to extend/complete the line of this colour.
        anchors = np.argwhere((g == c) | (g == 2) | (g == 4))
        if len(anchors) == 0:
            continue

        # For every row, fill between the leftmost and rightmost anchor.
        # For every column, fill between the topmost and bottommost anchor.
        # This reconstructs the axis-aligned line segments.
        for r in range(H):
            cols = anchors[anchors[:, 0] == r, 1]
            if len(cols) >= 2:
                out[r, cols.min():cols.max() + 1] = c

        for col in range(W):
            rows = anchors[anchors[:, 1] == col, 0]
            if len(rows) >= 2:
                out[rows.min():rows.max() + 1, col] = c

    return out.tolist()

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Candidate "marker" colors: non-zero colors that are not used as final line colors.
    # In the examples this is the color that disappears in the output.
    nonzero = [c for c in range(1, 10) if np.any(g == c)]
    marker = None
    for c in nonzero:
        # A marker color is rare and not part of long straight runs.
        cnt = int(np.sum(g == c))
        if cnt <= 6:
            marker = c
            break
    if marker is None:
        return out.tolist()

    # For every other color, complete horizontal/vertical line segments.
    # A segment is completed between the two extreme relevant cells in that row/column,
    # where relevant cells are the color itself plus marker cells that lie on the same
    # row/column and are adjacent to the color's intended line.
    for c in nonzero:
        if c == marker:
            continue

        mask = (g == c) | (g == marker)

        # Horizontal completion
        for r in range(h):
            cols = np.where(mask[r])[0]
            if len(cols) < 2:
                continue
            # Only complete if the row contains at least two actual color-c cells
            # or a marker adjacent to color-c in this row.
            actual = np.where(g[r] == c)[0]
            if len(actual) < 2:
                # allow if marker is adjacent to an actual cell
                ok = False
                for mcol in cols:
                    if g[r, mcol] == marker:
                        if (mcol > 0 and g[r, mcol - 1] == c) or (mcol < w - 1 and g[r, mcol + 1] == c):
                            ok = True
                            break
                if not ok:
                    continue
            lo, hi = int(cols.min()), int(cols.max())
            out[r, lo:hi + 1] = c

        # Vertical completion
        for col in range(w):
            rows = np.where(mask[:, col])[0]
            if len(rows) < 2:
                continue
            actual = np.where(g[:, col] == c)[0]
            if len(actual) < 2:
                ok = False
                for mrow in rows:
                    if g[mrow, col] == marker:
                        if (mrow > 0 and g[mrow - 1, col] == c) or (mrow < h - 1 and g[mrow + 1, col] == c):
                            ok = True
                            break
                if not ok:
                    continue
            lo, hi = int(rows.min()), int(rows.max())
            out[lo:hi + 1, col] = c

    # Remove marker color if it was used only as a placeholder.
    if marker is not None:
        out[out == marker] = 0

    return out.tolist()

import numpy as np
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # The marker color is the non-zero color that disappears in the output.
    # In these puzzles it is the rare color used to mark missing line cells.
    marker = None
    for c in range(1, 10):
        if np.any(g == c) and int(np.sum(g == c)) <= 6:
            marker = c
            break

    if marker is None:
        return out.tolist()

    # Work with a mask that treats marker cells as possible line cells.
    mask = (g != 0) & (g != marker)

    # For each color, find connected components of (color | marker) cells.
    # Each component is completed into the minimal orthogonal polyline that
    # connects its extreme cells in the dominant row/column directions.
    for c in range(1, 10):
        if c == marker:
            continue
        if not np.any(g == c):
            continue

        comp_mask = (g == c) | (g == marker)
        visited = np.zeros((h, w), dtype=bool)

        for r in range(h):
            for col in range(w):
                if not comp_mask[r, col] or visited[r, col]:
                    continue

                # BFS component
                q = deque([(r, col)])
                visited[r, col] = True
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and comp_mask[ny, nx] and not visited[ny, nx]:
                            visited[ny, nx] = True
                            q.append((ny, nx))

                # Only complete components that contain at least one real color cell.
                real = [(y, x) for (y, x) in cells if g[y, x] == c]
                if not real:
                    continue

                # Determine the set of cells to draw for this component.
                draw = set(real)

                # If the component has a clear horizontal extent, draw the row span
                # between the leftmost and rightmost real cells at the row that
                # contains the most real cells.
                rows = {}
                cols = {}
                for y, x in real:
                    rows.setdefault(y, []).append(x)
                    cols.setdefault(x, []).append(y)

                # Horizontal segments: for each row with at least two real cells,
                # fill between min and max.
                for y, xs in rows.items():
                    if len(xs) >= 2:
                        lo, hi = min(xs), max(xs)
                        for x in range(lo, hi + 1):
                            draw.add((y, x))

                # Vertical segments: for each column with at least two real cells,
                # fill between min and max.
                for x, ys in cols.items():
                    if len(ys) >= 2:
                        lo, hi = min(ys), max(ys)
                        for y in range(lo, hi + 1):
                            draw.add((y, x))

                # If marker cells are present, extend from the nearest real cell
                # in the direction of the marker to the component boundary.
                markers = [(y, x) for (y, x) in cells if g[y, x] == marker]
                for my, mx in markers:
                    # Find nearest real cell in the same row or column.
                    best = None
                    best_d = 10**9
                    for y, x in real:
                        if y == my:
                            d = abs(x - mx)
                            if d < best_d:
                                best_d = d
                                best = (y, x, 'h')
                        if x == mx:
                            d = abs(y - my)
                            if d < best_d:
                                best_d = d
                                best = (y, x, 'v')
                    if best is None:
                        continue
                    by, bx, orient = best
                    if orient == 'h':
                        if mx > bx:
                            for x in range(bx, mx + 1):
                                draw.add((my, x))
                        else:
                            for x in range(mx, bx + 1):
                                draw.add((my, x))
                    else:
                        if my > by:
                            for y in range(by, my + 1):
                                draw.add((y, mx))
                        else:
                            for y in range(my, by + 1):
                                draw.add((y, mx))

                # Paint this component's color, but do not overwrite other real colors
                # unless the cell is currently background or marker.
                for y, x in draw:
                    if 0 <= y < h and 0 <= x < w:
                        if g[y, x] == 0 or g[y, x] == marker or g[y, x] == c:
                            out[y, x] = c

    # Remove marker color.
    out[out == marker] = 0
    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Candidate line colors are non-background colors that are not the
    # endpoint/corner marker colors seen in the examples (2 and 4).
    line_colors = [c for c in range(1, 10) if c not in (2, 4)]

    def line_cells(r, c, dr, dc, color):
        """
        Return the full straight line of `color` that passes through (r, c),
        if (r, c) is a valid endpoint of such a line.
        """
        if not (0 <= r < h and 0 <= c < w):
            return None
        if g[r, c] != color:
            return None

        # The cell in the outward direction must be background or a marker.
        or_, oc = r - dr, c - dc
        if 0 <= or_ < h and 0 <= oc < w and g[or_, oc] not in (0, 2, 4):
            return None

        # Walk inward while cells are the line color or markers.
        cells = [(r, c)]
        rr, cc = r + dr, c + dc
        while 0 <= rr < h and 0 <= cc < w and g[rr, cc] in (color, 2, 4):
            cells.append((rr, cc))
            rr += dr
            cc += dc

        # The cell beyond the far end must be background or a marker.
        if 0 <= rr < h and 0 <= cc < w and g[rr, cc] not in (0, 2, 4):
            return None

        # Require at least two cells and at least one actual line-color cell.
        if len(cells) < 2:
            return None
        if not any(g[x, y] == color for x, y in cells):
            return None

        return cells

    # Collect all valid line segments.
    segments = []
    for color in line_colors:
        for r in range(h):
            for c in range(w):
                if g[r, c] != color:
                    continue
                for dr, dc in ((0, 1), (1, 0)):
                    cells = line_cells(r, c, dr, dc, color)
                    if cells:
                        segments.append((color, cells))

    # If a cell is covered by multiple segments, choose the color of the
    # longest segment; ties are broken by smaller color value.
    best = {}
    for color, cells in segments:
        length = len(cells)
        for cell in cells:
            key = (-length, color)
            if cell not in best or key < best[cell][0]:
                best[cell] = (key, color)

    for (r, c), (_, color) in best.items():
        out[r, c] = color

    return out.tolist()

