def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Candidate path colors: non-zero colors that are not the small "marker" colors
    # seen in the examples (2 and 4 are used as temporary obstruction markers).
    colors = sorted({int(c) for c in g.flat if c != 0} - {2, 4})

    def neighbors(r, c):
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < H and 0 <= nc < W:
                yield nr, nc

    def bfs_dist(start, blocked):
        dist = np.full((H, W), 10**9, dtype=int)
        sr, sc = start
        dist[sr, sc] = 0
        q = deque([start])
        while q:
            r, c = q.popleft()
            for nr, nc in neighbors(r, c):
                if dist[nr, nc] != 10**9:
                    continue
                if blocked[nr, nc]:
                    continue
                dist[nr, nc] = dist[r, c] + 1
                q.append((nr, nc))
        return dist

    def path_cells(a, b, blocked):
        """Return cells on a shortest path from a to b avoiding blocked cells."""
        da = bfs_dist(a, blocked)
        db = bfs_dist(b, blocked)
        if da[b] == 10**9:
            return None
        cells = set()
        for r in range(H):
            for c in range(W):
                if da[r, c] + db[r, c] == da[b]:
                    cells.add((r, c))
        return cells

    def is_simple_path(cells):
        if not cells:
            return False
        deg = {}
        for r, c in cells:
            d = 0
            for nr, nc in neighbors(r, c):
                if (nr, nc) in cells:
                    d += 1
            deg[(r, c)] = d
        endpoints = [p for p, d in deg.items() if d == 1]
        if len(endpoints) != 2:
            return False
        if any(d > 2 for d in deg.values()):
            return False
        # connected
        start = endpoints[0]
        seen = {start}
        q = deque([start])
        while q:
            r, c = q.popleft()
            for nr, nc in neighbors(r, c):
                if (nr, nc) in cells and (nr, nc) not in seen:
                    seen.add((nr, nc))
                    q.append((nr, nc))
        return len(seen) == len(cells)

    def score_path(cells, color):
        if not is_simple_path(cells):
            return None
        # Prefer paths that keep existing cells of this color and avoid markers.
        keep = sum(1 for (r, c) in cells if g[r, c] == color)
        marker_penalty = sum(1 for (r, c) in cells if g[r, c] in (2, 4))
        # Slight preference for shorter paths among valid candidates.
        return (keep, -marker_penalty, -len(cells))

    # For each color, find the best simple path that can be formed by filling
    # zeros and replacing marker cells, while not overwriting other path colors.
    final = np.zeros((H, W), dtype=int)

    for color in colors:
        mask = (g == color)
        pts = [(r, c) for r in range(H) for c in range(W) if mask[r, c]]
        if not pts:
            continue

        # Candidate endpoints: existing cells of this color, plus nearby marker cells
        # that may be part of the intended path.
        candidates = set(pts)
        for r, c in pts:
            for nr, nc in neighbors(r, c):
                if g[nr, nc] in (2, 4):
                    candidates.add((nr, nc))
            # Also allow immediate zero extensions for short endpoint completion.
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < H and 0 <= nc < W and g[nr, nc] == 0:
                    candidates.add((nr, nc))

        best = None
        best_cells = None

        # Try pairs of candidate endpoints.  The grid is small, so this is fine.
        cand_list = list(candidates)
        for i, a in enumerate(cand_list):
            for b in cand_list[i + 1:]:
                # Blocked cells are other path colors (not this color, not markers, not zero).
                blocked = np.zeros((H, W), dtype=bool)
                for r in range(H):
                    for c in range(W):
                        v = g[r, c]
                        if v != 0 and v != color and v not in (2, 4):
                            blocked[r, c] = True
                cells = path_cells(a, b, blocked)
                if cells is None:
                    continue
                sc = score_path(cells, color)
                if sc is None:
                    continue
                if best is None or sc > best:
                    best = sc
                    best_cells = cells

        if best_cells is not None:
            for r, c in best_cells:
                final[r, c] = color

    # Resolve overlaps by lower color priority (1 over 3 over 6 over 7, etc.).
    for color in colors:
        mask = (final == color)
        if not np.any(mask):
            continue
        # If a cell was assigned to a higher color but a lower color also wants it,
        # lower color wins.  The loop order is ascending, so overwrite only if current
        # final value is 0 or greater than color.
        for r, c in zip(*np.where(mask)):
            if final[r, c] == 0 or final[r, c] > color:
                final[r, c] = color

    return final.tolist()

