            d = 0
            for nr, nc in neighbors(r, c):
                if (nr, nc) in cells:
                    d += 1
            deg[(r, c)] = d

        endpoints = [p for p, d in deg.items() if d == 1]
        if len(endpoints) != 2:
            return False
        if any(d > 2 for d in deg.values()):
            return False

        start = endpoints[0]
        seen = {start}
        q = deque([start])
        while q:
            r, c = q.popleft()
            for nr, nc in neighbors(r, c):
                if (nr, nc) in cells and (nr, nc) not in seen:
                    seen.add((nr, nc))
                    q.append((nr, nc))
        return len(seen) == len(cells)

    def path_score(cells, color):
        """
        Prefer paths that:
        1) keep many existing cells of this color,
        2) use marker cells when they are clearly part of the path,
        3) are shorter,
        4) are more straight / less turning.
        """
        if not is_simple_path(cells):
            return None

        keep = sum(1 for (r, c) in cells if g[r, c] == color)
        markers = sum(1 for (r, c) in cells if g[r, c] in MARKERS)
        length = len(cells)

        # Count turns by degree-2 cells whose two path neighbors are perpendicular.
        turns = 0
        for r, c in cells:
            nbrs = [(nr, nc) for nr, nc in neighbors(r, c) if (nr, nc) in cells]
            if len(nbrs) == 2:
                (r1, c1), (r2, c2) = nbrs
                if (r1 == r2) != (c1 == c2):
                    turns += 1

        # Strongly prefer keeping existing cells.  Markers are useful but less
        # important than real cells.  Among near-ties, prefer shorter and straighter.
        return (keep, markers, -length, -turns)

    def best_path_for_color(color):
        """
        Find the best simple path for this color.

        Candidate endpoints are:
        - existing cells of this color,
        - marker cells adjacent to this color,
        - zero cells adjacent to this color (to allow short endpoint completion).
        """
        pts = [(r, c) for r in range(H) for c in range(W) if g[r, c] == color]
        if not pts:
            return None

        candidates = set(pts)
        for r, c in pts:
            for nr, nc in neighbors(r, c):
                v = g[nr, nc]
                if v in MARKERS or v == 0:
                    candidates.add((nr, nc))

        # Cells that cannot be overwritten by this color:
        # smaller main colors have priority.  Larger main colors and markers may be
        # overwritten if they lie on the chosen path.
        blocked = np.zeros((H, W), dtype=bool)
        for r in range(H):
            for c in range(W):
                v = g[r, c]
                if v in main_colors and v < color:
                    blocked[r, c] = True

        def bfs_dist(start):
            dist = np.full((H, W), 10**9, dtype=int)
            sr, sc = start
            dist[sr, sc] = 0
            q = deque([start])
            while q:
                r, c = q.popleft()
                for nr, nc in neighbors(r, c):
                    if dist[nr, nc] != 10**9 or blocked[nr, nc]:
                        continue
                    dist[nr, nc] = dist[r, c] + 1
                    q.append((nr, nc))
            return dist

        cand = list(candidates)
        best_score = None
        best_cells = None

        # Try all candidate endpoint pairs.  Grids are small (12x12 in examples/tests).
        for i, a in enumerate(cand):
            da = bfs_dist(a)
            for b in cand[i + 1:]:
                if da[b] == 10**9:
                    continue
                db = bfs_dist(b)
                cells = set()
                for r in range(H):
                    for c in range(W):
                        if da[r, c] + db[r, c] == da[b]:
                            cells.add((r, c))
                sc = path_score(cells, color)
                if sc is not None and (best_score is None or sc > best_score):
                    best_score = sc
                    best_cells = cells

        return best_cells

    # Build the output by drawing each color's chosen path.
    # Smaller colors are drawn last so they win at intersections.
    out = np.zeros((H, W), dtype=int)

    for color in reversed(main_colors):
        cells = best_path_for_color(color)
        if cells:
            for r, c in cells:
                out[r, c] = color

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import Counter

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # The useful rectangle is the largest axis-aligned rectangle whose
    # interior is dominated by one non-zero colour.  The border of that
    # rectangle is ignored; only the interior is extracted.
    best = None
    best_score = -1

    for r1 in range(h):
        for r2 in range(r1 + 2, h):
            for c1 in range(w):
                for c2 in range(c1 + 2, w):
                    inner = g[r1 + 1:r2, c1 + 1:c2]
                    if inner.size == 0:
                        continue

                    cnt = Counter(inner.flat)
                    if not cnt:
                        continue

                    dom, dom_count = max(cnt.items(), key=lambda kv: kv[1])
                    if dom == 0:
                        continue

                    # Require a clear dominant interior colour.
                    if dom_count * 2 <= inner.size:
                        continue

                    # Prefer larger rectangles, then stronger dominance.
                    score = (inner.size, dom_count)
                    if score > best_score:
                        best_score = score
                        best = (r1, r2, c1, c2, dom)

    r1, r2, c1, c2, dom = best
    inner = g[r1 + 1:r2, c1 + 1:c2]

    # Rotate the extracted interior 90 degrees counter-clockwise.
    out = np.rot90(inner, k=1)
    return out.tolist()

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Find the main rectangular object: the largest connected component
    # of non-border, non-zero cells.
    def is_border(r, c):
        return r == 0 or c == 0 or r == H - 1 or c == W - 1

    visited = np.zeros((H, W), dtype=bool)
    best = None
    best_size = -1

    for r in range(H):
        for c in range(W):
            if visited[r, c] or is_border(r, c) or g[r, c] == 0:
                continue
            color = g[r, c]
            stack = [(r, c)]
            visited[r, c] = True
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < H and 0 <= nx < W:
                        if not visited[ny, nx] and not is_border(ny, nx) and g[ny, nx] == color:
                            visited[ny, nx] = True
                            stack.append((ny, nx))
            if len(cells) > best_size:
                best_size = len(cells)
                best = cells

    if best is None:
        return []

    ys = [r for r, _ in best]
    xs = [c for _, c in best]
    r0, r1 = min(ys), max(ys)
    c0, c1 = min(xs), max(xs)
    h, w = r1 - r0 + 1, c1 - c0 + 1

    # The output is the object's bounding box transposed.
    out = np.zeros((w, h), dtype=int)
    for i in range(h):
        for j in range(w):
            out[j, i] = g[r0 + i, c0 + j]

    return out.tolist()

import sys
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return []

    h = len(grid)
    w = len(grid[0])

    # Find the rectangular "canvas" made of 0-cells.
    zero_cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 0]
    if not zero_cells:
        return [row[:] for row in grid]

    r0 = min(r for r, _ in zero_cells)
    r1 = max(r for r, _ in zero_cells)
    c0 = min(c for _, c in zero_cells)
    c1 = max(c for _, c in zero_cells)

    out_h = r1 - r0 + 1
    out_w = c1 - c0 + 1
    out = [[0] * out_w for _ in range(out_h)]

    def in_canvas(r: int, c: int) -> bool:
        return r0 <= r <= r1 and c0 <= c <= c1

    def count_components(color: int) -> int:
        seen = [[False] * w for _ in range(h)]
        count = 0

        for r in range(h):
            for c in range(w):
                if grid[r][c] != color or seen[r][c] or in_canvas(r, c):
                    continue

                count += 1
                q = deque([(r, c)])
                seen[r][c] = True

                while q:
                    cr, cc = q.popleft()
                    for dr in (-1, 0, 1):
                        for dc in (-1, 0, 1):
                            if dr == 0 and dc == 0:
                                continue
                            nr, nc = cr + dr, cc + dc
                            if (
                                0 <= nr < h
                                and 0 <= nc < w
                                and not seen[nr][nc]
                                and not in_canvas(nr, nc)
                                and grid[nr][nc] == color
                            ):
                                seen[nr][nc] = True
                                q.append((nr, nc))

        return count

    # For each label inside the canvas, repeat it count(color) times
    # starting at the label's column, every second cell.
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            val = grid[r][c]
            if val == 0:
                continue

            rr = r - r0
            cc = c - c0
            n = count_components(val)

            for k in range(n):
                nc = cc + 2 * k
                if 0 <= nc < out_w:
                    out[rr][nc] = val

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    # Allow string rows just in case.
    if grid and isinstance(grid[0], str):
        grid = [[int(ch) for ch in row] for row in grid]

    if not grid or not grid[0]:
        return []

    h, w = len(grid), len(grid[0])
    hollow = []
    solid = []

    # Find all 4x4 filled or hollow squares.
    for r in range(h - 3):
        for c in range(w - 3):
            color = grid[r][c]
            if color == 0:
                continue

            # All non-zero cells in this 4x4 window must be the same color.
            ok = True
            for i in range(4):
                for j in range(4):
                    v = grid[r + i][c + j]
                    if v != 0 and v != color:
                        ok = False
                        break
                if not ok:
                    break
            if not ok:
                continue

            is_solid = True
            is_hollow = True

            for i in range(4):
                for j in range(4):
                    v = grid[r + i][c + j]

                    if v != color:
                        is_solid = False

                    if i == 0 or i == 3 or j == 0 or j == 3:
                        if v != color:
                            is_hollow = False
                    else:
                        if v != 0:
                            is_hollow = False

            if is_solid:
                solid.append((r, c, color))
            elif is_hollow:
                hollow.append((r, c, color))

    # Sort each type top-to-bottom, then left-to-right.
    hollow.sort(key=lambda x: (x[0], x[1]))
    solid.sort(key=lambda x: (x[0], x[1]))

    n = max(len(hollow), len(solid))
    if n == 0:
        return []

    out = [[0] * 8 for _ in range(4 * n)]

    # Left column: hollow squares.
    for idx, (_, _, color) in enumerate(hollow):
        base = 4 * idx
        for i in range(4):
            for j in range(4):
                if i == 0 or i == 3 or j == 0 or j == 3:
                    out[base + i][j] = color

    # Right column: solid squares.
    for idx, (_, _, color) in enumerate(solid):
        base = 4 * idx
        for i in range(4):
            for j in range(4):
                out[base + i][4 + j] = color

    return out

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Find the zero rectangle (the only place where 0 appears in the examples).
    zero_rows, zero_cols = np.where(g == 0)
    r0, r1 = int(zero_rows.min()), int(zero_rows.max())
    c0, c1 = int(zero_cols.min()), int(zero_cols.max())

    out = np.zeros((r1 - r0 + 1, c1 - c0 + 1), dtype=int)

    # Mask for cells inside the zero rectangle.
    inside = np.zeros((h, w), dtype=bool)
    inside[r0:r1 + 1, c0:c1 + 1] = True

    # For each nonzero digit inside the zero rectangle, find all 8-connected
    # components of that color outside the rectangle.
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            d = int(g[r, c])
            if d == 0:
                continue

            # 8-connected component labeling for color d outside the zero box.
            seen = np.zeros((h, w), dtype=bool)
            comps = []

            for sr in range(h):
                for sc in range(w):
                    if seen[sr, sc] or g[sr, sc] != d or inside[sr, sc]:
                        continue

                    stack = [(sr, sc)]
                    seen[sr, sc] = True
                    cells = []

                    while stack:
                        cr, cc = stack.pop()
                        cells.append((cr, cc))
                        for dr in (-1, 0, 1):
                            for dc in (-1, 0, 1):
                                if dr == 0 and dc == 0:
                                    continue
                                nr, nc = cr + dr, cc + dc
                                if 0 <= nr < h and 0 <= nc < w:
                                    if not seen[nr, nc] and not inside[nr, nc] and g[nr, nc] == d:
                                        seen[nr, nc] = True
                                        stack.append((nr, nc))

                    if cells:
                        cols = [cc for _, cc in cells]
                        # Sort left-to-right by the component's horizontal center.
                        center = (min(cols) + max(cols)) / 2.0
                        comps.append((center, min(cols), min(rows for rows, _ in cells)))

            # Place the digit in odd columns 1, 3, 5, ... in left-to-right order.
            comps.sort()
            for i, _ in enumerate(comps):
                col = 2 * i + 1
                if col < out.shape[1]:
                    out[r - r0, col] = d

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Identify the background color as the most frequent color.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # Find all non-background connected components (4-connectivity).
    seen = np.zeros((h, w), dtype=bool)
    comps = []
    for r in range(h):
        for c in range(w):
            if g[r, c] != bg and not seen[r, c]:
                color = int(g[r, c])
                q = deque([(r, c)])
                seen[r, c] = True
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w:
                            if not seen[ny, nx] and g[ny, nx] == color:
                                seen[ny, nx] = True
                                q.append((ny, nx))
                comps.append((color, cells))

    if not comps:
        return []

    # Build adjacency between components: two components are adjacent if any
    # of their cells are 4-neighbor cells.
    n = len(comps)
    adj = [set() for _ in range(n)]
    for i in range(n):
        si = set(comps[i][1])
        for y, x in si:
            for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                ny, nx = y + dy, x + dx
                if 0 <= ny < h and 0 <= nx < w:
                    v = int(g[ny, nx])
                    if v != bg and v != comps[i][0]:
                        for j in range(n):
                            if comps[j][0] == v and (ny, nx) in comps[j][1]:
                                adj[i].add(j)
                                adj[j].add(i)

    # The components form a chain. Start from an endpoint of the chain.
    start = 0
    for i in range(n):
        if len(adj[i]) == 1:
            start = i
            break

    order = [start]
    visited = {start}
    cur = start
    while len(order) < n:
        nxt = None
        for j in adj[cur]:
            if j not in visited:
                nxt = j
                break
        if nxt is None:
            # Fallback: choose any unvisited adjacent component.
            for j in range(n):
                if j not in visited:
                    nxt = j
                    break
        order.append(nxt)
        visited.add(nxt)
        cur = nxt

    # Output is a vertical column. For each component in chain order,
    # repeat its color by the number of cells in that component.
    out = []
    for idx in order:
        color, cells = comps[idx]
        out.extend([color] * len(cells))

    return [[v] for v in out]

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape
    out = g.copy()

    # Find the vertical separator line:
    # a column containing only one non-zero colour (plus zeros), with the
    # largest possible count of that colour.
    best_col = -1
    best_color = -1
    best_count = 0

    for c in range(W):
        col = g[:, c]
        nz = col[col != 0]
        if len(nz) == 0:
            continue
        if len(np.unique(nz)) != 1:
            continue
        color = int(nz[0])
        count = int(np.sum(col == color))
        if count > best_count:
            best_count = count
            best_col = c
            best_color = color

    if best_col == -1:
        return out.tolist()

    sep = best_col

    # Decide which side is the source side: the side containing non-zero cells.
    left_nz = int(np.sum(g[:, :sep] != 0))
    right_nz = int(np.sum(g[:, sep + 1:] != 0))

    if left_nz == 0 and right_nz == 0:
        return out.tolist()

    source_left = left_nz >= right_nz

    # For each row, extract horizontal runs on the source side.
    # Process runs from closest to the separator outward.
    # A run of length L paints target cells at distances 1, 1+L, 1+2L, ...
    # Closer runs have priority over farther runs.
    for r in range(H):
        if source_left:
            seg = g[r, :sep]
            runs = []
            c = 0
            while c < len(seg):
                if seg[c] != 0:
                    color = int(seg[c])
                    start = c
                    while c < len(seg) and seg[c] == color:
                        c += 1
                    length = c - start
                    # distance from the separator to the run's right end
                    dist_to_sep = sep - c
                    runs.append((dist_to_sep, color, length))
                else:
                    c += 1

            # closest to separator first
            runs.sort(key=lambda x: x[0])

            for _, color, length in runs:
                d = 1
                while sep + d < W:
                    if out[r, sep + d] == 0:
                        out[r, sep + d] = color
                    d += length
        else:
            seg = g[r, sep + 1:]
            runs = []
            c = 0
            while c < len(seg):
                if seg[c] != 0:
                    color = int(seg[c])
                    start = c
                    while c < len(seg) and seg[c] == color:
                        c += 1
                    length = c - start
                    # distance from the separator to the run's left end
                    dist_to_sep = c
                    runs.append((dist_to_sep, color, length))
                else:
                    c += 1

            # closest to separator first
            runs.sort(key=lambda x: x[0])

            for _, color, length in runs:
                d = 1
                while sep - d >= 0:
                    if out[r, sep - d] == 0:
                        out[r, sep - d] = color
                    d += length

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return []

    H, W = len(grid), len(grid[0])
    visited = [[False] * W for _ in range(H)]
    blocks = []
    dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))

    # Find square colored blocks:
    # - filled: every cell in the square is the block color
    # - hollow: border is the block color and interior is 0
    for color in range(1, 10):
        for r in range(H):
            for c in range(W):
                if grid[r][c] != color or visited[r][c]:
                    continue

                stack = [(r, c)]
                visited[r][c] = True
                min_r = max_r = r
                min_c = max_c = c
                count = 0

                while stack:
                    cr, cc = stack.pop()
                    count += 1

                    if cr < min_r:
                        min_r = cr
                    if cr > max_r:
                        max_r = cr
                    if cc < min_c:
                        min_c = cc
                    if cc > max_c:
                        max_c = cc

                    for dr, dc in dirs:
                        nr, nc = cr + dr, cc + dc
                        if (
                            0 <= nr < H
                            and 0 <= nc < W
                            and not visited[nr][nc]
                            and grid[nr][nc] == color
                        ):
                            visited[nr][nc] = True
                            stack.append((nr, nc))

                h = max_r - min_r + 1
                w = max_c - min_c + 1

                # Only square blocks are used in this task.
                if h != w or h < 2:
                    continue

                filled = (count == h * w)
                hollow = False

                if not filled and h >= 3:
                    ok = True
                    for rr in range(min_r, max_r + 1):
                        for cc in range(min_c, max_c + 1):
                            if rr == min_r or rr == max_r or cc == min_c or cc == max_c:
                                if grid[rr][cc] != color:
                                    ok = False
                                    break
                            else:
                                if grid[rr][cc] != 0:
                                    ok = False
                                    break
                        if not ok:
                            break
                    hollow = ok

                if not (filled or hollow):
                    continue

                crop = [
                    [grid[rr][cc] for cc in range(min_c, max_c + 1)]
                    for rr in range(min_r, max_r + 1)
                ]
                blocks.append((min_r, min_c, h, w, crop, filled))

    if not blocks:
        return []

    hollow_blocks = [b for b in blocks if not b[5]]
    filled_blocks = [b for b in blocks if b[5]]

    # Preserve original top-to-bottom order within each category.
    hollow_blocks.sort(key=lambda b: (b[0], b[1]))
    filled_blocks.sort(key=lambda b: (b[0], b[1]))

    tile_h = max(b[2] for b in blocks)
    tile_w = max(b[3] for b in blocks)
    rows = max(len(hollow_blocks), len(filled_blocks))

    out = [[0] * (2 * tile_w) for _ in range(rows * tile_h)]

    # Left column: hollow blocks.
    for i, (_, _, h, w, crop, _) in enumerate(hollow_blocks):
        for rr in range(h):
            for cc in range(w):
                out[i * tile_h + rr][cc] = crop[rr][cc]

    # Right column: filled blocks.
    for i, (_, _, h, w, crop, _) in enumerate(filled_blocks):
        for rr in range(h):
            for cc in range(w):
                out[i * tile_h + rr][tile_w + cc] = crop[rr][cc]

    return out

import numpy as np
from collections import Counter, deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    a = np.array(grid, dtype=int)
    H, W = a.shape

    # Background is the most frequent colour.
    bg = int(Counter(a.flatten()).most_common(1)[0][0])

    # Connected components of non-background cells (4-connectivity).
    seen = np.zeros((H, W), dtype=bool)
    comps = []
    for r in range(H):
        for c in range(W):
            if seen[r, c] or a[r, c] == bg:
                continue
            q = deque([(r, c)])
            seen[r, c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < H and 0 <= nx < W and not seen[ny, nx] and a[ny, nx] != bg:
                        seen[ny, nx] = True
                        q.append((ny, nx))
            ys = [p[0] for p in cells]
            xs = [p[1] for p in cells]
            r0, r1 = min(ys), max(ys)
            c0, c1 = min(xs), max(xs)
            h = r1 - r0 + 1
            w = c1 - c0 + 1
            color = int(a[r0, c0])
            solid = (len(cells) == h * w)
            comps.append({
                "r0": r0, "c0": c0, "h": h, "w": w,
                "color": color, "solid": solid
            })

    # Existing target blocks are solid squares larger than 1x1.
    blocks = [cp for cp in comps if cp["solid"] and cp["h"] > 1 and cp["h"] == cp["w"]]
    if not blocks:
        return [list(row) for row in a]

    B = blocks[0]["h"]

    # Source pattern: isolated 1x1 non-background pixels on the odd/odd lattice.
    ones = [cp for cp in comps if cp["solid"] and cp["h"] == 1 and cp["w"] == 1]
    src_ones = [cp for cp in ones if cp["r0"] % 2 == 1 and cp["c0"] % 2 == 1]
    if not src_ones:
        return [list(row) for row in a]

    sh = max((cp["r0"] - 1) // 2 for cp in src_ones) + 1
    sw = max((cp["c0"] - 1) // 2 for cp in src_ones) + 1
    src = [[bg] * sw for _ in range(sh)]
    for cp in src_ones:
        i = (cp["r0"] - 1) // 2
        j = (cp["c0"] - 1) // 2
        src[i][j] = cp["color"]

    # Infer spacing from existing blocks.
    S = None
    rows = {}
    cols = {}
    for cp in blocks:
        rows.setdefault(cp["r0"], []).append(cp["c0"])
        cols.setdefault(cp["c0"], []).append(cp["r0"])
    for v in rows.values():
        if len(v) > 1:
            diffs = [abs(x - y) for x in v for y in v if x != y]
            if diffs:
                S = min(diffs)
                break
    if S is None:
        for v in cols.values():
            if len(v) > 1:
                diffs = [abs(x - y) for x in v for y in v if x != y]
                if diffs:
                    S = min(diffs)
                    break
    if S is None:
        S = B + 1

    # Find the unique target-grid origin consistent with all existing blocks.
    best = None
    for R0 in range(0, H - (sh - 1) * S - B + 1):
        for C0 in range(0, W - (sw - 1) * S - B + 1):
            ok = True
            for cp in blocks:
                dr = cp["r0"] - R0
                dc = cp["c0"] - C0
                if dr < 0 or dc < 0 or dr % S != 0 or dc % S != 0:
                    ok = False
                    break
                i = dr // S
                j = dc // S
                if i >= sh or j >= sw or src[i][j] != cp["color"]:
                    ok = False
                    break
            if ok:
                best = (R0, C0)
                break
        if best is not None:
            break

    if best is None:
        return [list(row) for row in a]

    R0, C0 = best
    out = a.copy()

    # Fill every target block from the source pattern.
    for i in range(sh):
        for j in range(sw):
            r = R0 + i * S
            c = C0 + j * S
            color = src[i][j]
            if color != bg:
                out[r:r + B, c:c + B] = color

    return [list(row) for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    if h == 0:
        return []
    if h == 1:
        return [[int(grid[0][0])]]

    # Use all rows except the last one as the layer colors.
    seq = [int(row[0]) for row in grid[:-1]]
    L = len(seq)
    n = 2 * L

    out = [[0] * n for _ in range(n)]

    for d, color in enumerate(seq):
        # Fill the d-th concentric square border.
        for c in range(n):
            out[d][c] = color
            out[n - 1 - d][c] = color
        for r in range(n):
            out[r][d] = color
            out[r][n - 1 - d] = color

    return out

