                nc = c + shift
                if 0 <= nc < w:
                    out[r, nc] = 5

    # Clear the outside 5-pattern.
    for r in range(h):
        for c in range(left):
            if g[r, c] == 5:
                out[r, c] = 0

    # Shift the interior contents upward by one row.
    for r in range(bottom, top, -1):
        out[r, left + 1:right + 1] = out[r - 1, left + 1:right + 1]
    out[top, left + 1:right + 1] = 0

    return out.tolist()

