    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # If there is no marker, return the grid unchanged.
    if not np.any(g == 4):
        return g.tolist()

    # Background: most common colour on the border.
    border = np.concatenate([
        g[0, :],
        g[-1, :],
        g[:, 0],
        g[:, -1]
    ])
    vals, counts = np.unique(border, return_counts=True)
    background = int(vals[np.argmax(counts)])

    # Object colour: most common non-background, non-marker colour.
    all_vals, all_counts = np.unique(g, return_counts=True)
    object_color = None
    best = -1
    for v, c in zip(all_vals, all_counts):
        v = int(v)
        if v == background or v == 4:
            continue
        if int(c) > best:
            best = int(c)
            object_color = v

    marker = np.argwhere(g == 4)
    marker_rows = marker[:, 0]
    marker_cols = marker[:, 1]

    out = g.copy()

    # Horizontal marker: project vertically.
    if len(np.unique(marker_rows)) == 1:
        marker_row = int(marker_rows[0])
        c0 = int(marker_cols.min())
        c1 = int(marker_cols.max())

        for r in range(h):
            d = abs(r - marker_row)
            m = d % 6

            if m in (0, 2):
                out[r, c0:c1 + 1] = 4
            elif m == 4:
                out[r, c0:c1 + 1] = 3
                if object_color is not None:
                    out[r, g[r] == object_color] = 3
            else:
                out[r, c0:c1 + 1] = background

    # Vertical marker: project horizontally.
    elif len(np.unique(marker_cols)) == 1:
        marker_col = int(marker_cols[0])
        r0 = int(marker_rows.min())
        r1 = int(marker_rows.max())

        for c in range(w):
            d = abs(c - marker_col)
            m = d % 6

            if m in (0, 2):
                out[r0:r1 + 1, c] = 4
            elif m == 4:
                out[r0:r1 + 1, c] = 3
                if object_color is not None:
                    out[g[:, c] == object_color, c] = 3
            else:
                out[r0:r1 + 1, c] = background

    # Fallback for unexpected marker shapes: treat as horizontal if wider,
    # otherwise vertical.
    else:
        if (marker_rows.max() - marker_rows.min()) <= (marker_cols.max() - marker_cols.min()):
            marker_row = int((marker_rows.min() + marker_rows.max()) // 2)
            c0 = int(marker_cols.min())
            c1 = int(marker_cols.max())

            for r in range(h):
                d = abs(r - marker_row)
                m = d % 6

                if m in (0, 2):
                    out[r, c0:c1 + 1] = 4
                elif m == 4:
                    out[r, c0:c1 + 1] = 3
                    if object_color is not None:
                        out[r, g[r] == object_color] = 3
                else:
                    out[r, c0:c1 + 1] = background
        else:
            marker_col = int((marker_cols.min() + marker_cols.max()) // 2)
            r0 = int(marker_rows.min())
            r1 = int(marker_rows.max())

            for c in range(w):
                d = abs(c - marker_col)
                m = d % 6

                if m in (0, 2):
                    out[r0:r1 + 1, c] = 4
                elif m == 4:
                    out[r0:r1 + 1, c] = 3
                    if object_color is not None:
                        out[g[:, c] == object_color, c] = 3
                else:
                    out[r0:r1 + 1, c] = background

    return out.tolist()

