from collections import Counter

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Background is the most common colour.
    bg = Counter(g.flatten().tolist()).most_common(1)[0][0]

    # The marker is the colour 4 segment.
    marker_cells = np.argwhere(g == 4)
    if len(marker_cells) == 0:
        return g.tolist()

    rows = marker_cells[:, 0]
    cols = marker_cells[:, 1]
    rmin, rmax = rows.min(), rows.max()
    cmin, cmax = cols.min(), cols.max()

    # Determine marker orientation.
    horizontal = (rmax == rmin)
    if not horizontal and (cmax == cmin):
        vertical = True
    else:
        # Fallback: choose the axis with the larger span.
        vertical = (cmax - cmin) > (rmax - rmin)

    out = g.copy()

    # Pattern along the beam, starting at the marker and moving inward:
    # offset 0 -> 4, 1 -> background, 2 -> 4, 3 -> background,
    # 4 -> 3, 5 -> background, then repeat.
    def state(offset: int) -> int:
        m = offset % 6
        if m == 0 or m == 2:
            return 4
        if m == 4:
            return 3
        return bg

    if horizontal:
        marker_row = rmin
        # Move inward: down if marker is on top, up if marker is on bottom.
        if marker_row <= h // 2:
            direction = 1
        else:
            direction = -1

        for r in range(h):
            offset = (r - marker_row) * direction
            if offset < 0:
                continue
            st = state(offset)
            if st == 3:
                # Recolour the whole line's non-background, non-marker cells to 3.
                line = out[r]
                mask = (line != bg) & (line != 4)
                out[r, mask] = 3
            elif st == 4:
                out[r, cmin:cmax + 1] = 4
            else:
                out[r, cmin:cmax + 1] = bg
    else:
        marker_col = cmin
        # Move inward: right if marker is on left, left if marker is on right.
        if marker_col <= w // 2:
            direction = 1
        else:
            direction = -1

        for c in range(w):
            offset = (c - marker_col) * direction
            if offset < 0:
                continue
            st = state(offset)
            if st == 3:
                # Recolour the whole column's non-background, non-marker cells to 3.
                col = out[:, c]
                mask = (col != bg) & (col != 4)
                out[mask, c] = 3
            elif st == 4:
                out[rmin:rmax + 1, c] = 4
            else:
                out[rmin:rmax + 1, c] = bg

    return out.tolist()

