def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Find all 5x5 boxes: border is 2 or 8, interior is a single non-border colour.
    boxes = []
    for r in range(H - 4):
        for c in range(W - 4):
            sub = g[r:r + 5, c:c + 5]
            border = sub[0, 0]
            if border not in (2, 8):
                continue
            if not np.all(sub[0, :] == border) or not np.all(sub[4, :] == border):
                continue
            if not np.all(sub[:, 0] == border) or not np.all(sub[:, 4] == border):
                continue
            interior = sub[1:4, 1:4]
            if interior.size == 0:
                continue
            if np.all(interior == interior[0, 0]) and interior[0, 0] != border:
                boxes.append((r, c, border))

    # Remove duplicate detections (should not happen for valid inputs, but safe).
    unique_boxes = []
    seen = set()
    for b in boxes:
        if b not in seen:
            seen.add(b)
            unique_boxes.append(b)
    boxes = unique_boxes

    # Preferred horizontal direction: border 8 moves left, border 2 moves right.
    def direction(border):
        return -1 if border == 8 else 1

    def overlaps(a, b):
        r1, c1, _ = a
        r2, c2, _ = b
        return not (r1 + 4 < r2 or r2 + 4 < r1 or c1 + 4 < c2 or c2 + 4 < c1)

    # Move each box as far as possible in its preferred direction.
    # If blocked by another box, try to slide vertically by 1 to pass around it.
    # This reproduces the single vertical adjustment seen in the examples.
    for i, (r, c, border) in enumerate(boxes):
        d = direction(border)
        while True:
            nc = c + d
            if nc < 0 or nc + 4 >= W:
                break

            # Check whether the box can move horizontally at its current row.
            blocked = False
            for j, (r2, c2, b2) in enumerate(boxes):
                if i == j:
                    continue
                if not (r + 4 < r2 or r2 + 4 < r):
                    continue
                if not (nc + 4 < c2 or c2 + 4 < nc):
                    blocked = True
                    break

            if not blocked:
                c = nc
                continue

            # If blocked, try a one-row vertical slide to go around the blocker.
            moved = False
            for dr in (1, -1):
                nr = r + dr
                if nr < 0 or nr + 4 >= H:
                    continue
                ok = True
                for j, (r2, c2, b2) in enumerate(boxes):
                    if i == j:
                        continue
                    if not (nr + 4 < r2 or r2 + 4 < nr):
                        continue
                    if not (nc + 4 < c2 or c2 + 4 < nc):
                        ok = False
                        break
                if ok:
                    r = nr
                    c = nc
                    moved = True
                    break

            if not moved:
                break

    # Rebuild output.
    out = np.zeros((H, W), dtype=int)
    for r, c, border in boxes:
        out[r:r + 5, c:c + 5] = border
        interior = g[r + 1:r + 4, c + 1:c + 4]
        out[r + 1:r + 4, c + 1:c + 4] = interior

    return out.tolist()

