def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Find all maximal straight line segments of 2s.
    segments = []
    used = np.zeros((h, w), dtype=bool)

    # Horizontal segments
    for r in range(h):
        c = 0
        while c < w:
            if g[r, c] == 2 and not used[r, c]:
                c2 = c
                while c2 + 1 < w and g[r, c2 + 1] == 2:
                    c2 += 1
                if c2 > c:  # length at least 2
                    for cc in range(c, c2 + 1):
                        used[r, cc] = True
                    segments.append((r, c, r, c2))
                c = c2 + 1
            else:
                c += 1

    # Vertical segments
    for c in range(w):
        r = 0
        while r < h:
            if g[r, c] == 2 and not used[r, c]:
                r2 = r
                while r2 + 1 < h and g[r2 + 1, c] == 2:
                    r2 += 1
                if r2 > r:  # length at least 2
                    for rr in range(r, r2 + 1):
                        used[rr, c] = True
                    segments.append((r, c, r2, c))
                r = r2 + 1
            else:
                r += 1

    # For each mirror segment, reflect nearby non-background, non-2 pixels
    # across the segment if they lie on one side and the reflected cell is empty.
    for r1, c1, r2, c2 in segments:
        if r1 == r2:  # horizontal mirror
            r = r1
            for c in range(w):
                if g[r, c] == 2:
                    continue
                # pixels above
                for rr in range(r - 1, -1, -1):
                    if g[rr, c] != 0 and g[rr, c] != 2:
                        dist = r - rr
                        rr2 = r + dist
                        if rr2 < h and out[rr2, c] == 0:
                            out[rr2, c] = g[rr, c]
                        break
                # pixels below
                for rr in range(r + 1, h):
                    if g[rr, c] != 0 and g[rr, c] != 2:
                        dist = rr - r
                        rr2 = r - dist
                        if rr2 >= 0 and out[rr2, c] == 0:
                            out[rr2, c] = g[rr, c]
                        break
        else:  # vertical mirror
            c = c1
            for r in range(h):
                if g[r, c] == 2:
                    continue
                # pixels left
                for cc in range(c - 1, -1, -1):
                    if g[r, cc] != 0 and g[r, cc] != 2:
                        dist = c - cc
                        cc2 = c + dist
                        if cc2 < w and out[r, cc2] == 0:
                            out[r, cc2] = g[r, cc]
                        break
                # pixels right
                for cc in range(c + 1, w):
                    if g[r, cc] != 0 and g[r, cc] != 2:
                        dist = cc - c
                        cc2 = c - dist
                        if cc2 >= 0 and out[r, cc2] == 0:
                            out[r, cc2] = g[r, cc]
                        break

    return out.tolist()

