def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Identify connected components of 2s (8-connected).
    seen = np.zeros((h, w), dtype=bool)
    components = []

    for r in range(h):
        for c in range(w):
            if g[r, c] == 2 and not seen[r, c]:
                q = deque([(r, c)])
                seen[r, c] = True
                comp = []
                while q:
                    cr, cc = q.popleft()
                    comp.append((cr, cc))
                    for dr in (-1, 0, 1):
                        for dc in (-1, 0, 1):
                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < h and 0 <= nc < w:
                                if not seen[nr, nc] and g[nr, nc] == 2:
                                    seen[nr, nc] = True
                                    q.append((nr, nc))
                components.append(comp)

    def is_straight_line(comp):
        if len(comp) < 2:
            return False
        rows = {r for r, c in comp}
        cols = {c for r, c in comp}
        if len(rows) == 1:
            r = next(iter(rows))
            return all(c == r for r, c in comp) or all(c == r for r, c in comp) or True
        if len(cols) == 1:
            c = next(iter(cols))
            return True
        # main diagonal: r - c constant
        if all(r - c == comp[0][0] - comp[0][1] for r, c in comp):
            return True
        # anti-diagonal: r + c constant
        if all(r + c == comp[0][0] + comp[0][1] for r, c in comp):
            return True
        return False

    def reflect_across_line(r, c, comp):
        rows = {rr for rr, cc in comp}
        cols = {cc for rr, cc in comp}
        if len(rows) == 1:
            mr = next(iter(rows))
            return 2 * mr - r, c
        if len(cols) == 1:
            mc = next(iter(cols))
            return r, 2 * mc - c
        if all(rr - cc == comp[0][0] - comp[0][1] for rr, cc in comp):
            k = comp[0][0] - comp[0][1]
            return c + k, r - k
        if all(rr + cc == comp[0][0] + comp[0][1] for rr, cc in comp):
            s = comp[0][0] + comp[0][1]
            return s - c, s - r
        return None

    for comp in components:
        if len(comp) == 1:
            mr, mc = comp[0]
            for r in range(h):
                for c in range(w):
                    if g[r, c] == 2:
                        continue
                    nr, nc = 2 * mr - r, 2 * mc - c
                    if 0 <= nr < h and 0 <= nc < w and out[nr, nc] == 0:
                        out[nr, nc] = g[r, c]
        elif is_straight_line(comp):
            for r in range(h):
                for c in range(w):
                    if g[r, c] == 2:
                        continue
                    res = reflect_across_line(r, c, comp)
                    if res is None:
                        continue
                    nr, nc = res
                    if 0 <= nr < h and 0 <= nc < w and out[nr, nc] == 0:
                        out[nr, nc] = g[r, c]

    return out.tolist()

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Background is the most frequent colour.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    ones = [(r, c) for r in range(h) for c in range(w) if g[r, c] == 1]
    sixes = [(r, c) for r in range(h) for c in range(w) if g[r, c] == 6]

    out = g.copy()

    def in_bounds(r, c):
        return 0 <= r < h and 0 <= c < w

    def draw_line(p, q, color):
        r1, c1 = p
        r2, c2 = q
        dr = 1 if r2 > r1 else (-1 if r2 < r1 else 0)
        dc = 1 if c2 > c1 else (-1 if c2 < c1 else 0)
        steps = max(abs(r2 - r1), abs(c2 - c1))
        for k in range(steps + 1):
            r = r1 + dr * k
            c = c1 + dc * k
            if in_bounds(r, c):
                out[r, c] = color

    def draw_full_diagonal(p, slope, color):
        r, c = p
        if slope == 1:
            dirs = [(-1, -1), (1, 1)]
        else:
            dirs = [(-1, 1), (1, -1)]
        for dr, dc in dirs:
            rr, cc = r, c
            while in_bounds(rr, cc):
                out[rr, cc] = color
                rr += dr
                cc += dc

    # Draw the 1-path first.
    if len(ones) == 2:
        (r1, c1), (r2, c2) = ones
        if abs(r1 - r2) == abs(c1 - c2):
            draw_line((r1, c1), (r2, c2), 1)
        else:
            # Move diagonally from the first 1 toward the second until
            # either row or column matches, whichever happens first.
            dr = 1 if r2 > r1 else -1
            dc = 1 if c2 > c1 else -1
            steps = min(abs(r2 - r1), abs(c2 - c1))
            for k in range(steps + 1):
                out[r1 + dr * k, c1 + dc * k] = 1

    # Any 6 lying on a drawn 1-cell emits a full perpendicular diagonal.
    for r, c in sixes:
        if out[r, c] == 1:
            # Determine the slope of the local 1-line.
            slope = None
            for dr, dc in ((1, 1), (1, -1), (-1, 1), (-1, -1)):
                r2, c2 = r + dr, c + dc
                if in_bounds(r2, c2) and out[r2, c2] == 1:
                    slope = 1 if dc == dr else -1
                    break
            if slope is not None:
                draw_full_diagonal((r, c), -slope, 6)

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # The examples use 22x22 grids with four 5-wide horizontal slots:
    # columns 0-4, 5-9, 12-16, 17-21.
    # Border colour 8 objects are placed in the left two slots.
    # Border colour 2 objects are placed in the right two slots.
    slots = [0, 5, 12, 17]

    # Detect complete 5x5 framed objects.
    objects = []
    for r in range(h - 4):
        for c in range(w - 4):
            block = g[r:r + 5, c:c + 5]
            border = int(block[0, 0])
            if border == 0:
                continue
            if not (
                np.all(block[0, :] == border) and
                np.all(block[4, :] == border) and
                np.all(block[:, 0] == border) and
                np.all(block[:, 4] == border)
            ):
                continue
            interior = block[1:4, 1:4]
            if not np.all(interior == interior[0, 0]):
                continue
            if int(interior[0, 0]) == border:
                continue
            objects.append((r, c, border, int(interior[0, 0])))

    # Detect incomplete 5x5 framed objects that are cut off vertically.
    # In the supplied cases these are top + 3 interior rows, missing bottom.
    for r in range(h - 3):
        for c in range(w - 4):
            block = g[r:r + 4, c:c + 5]
            border = int(block[0, 0])
            if border == 0:
                continue
            if not (
                np.all(block[0, :] == border) and
                np.all(block[:, 0] == border) and
                np.all(block[:, 4] == border)
            ):
                continue
            interior = block[1:4, 1:4]
            if not np.all(interior == interior[0, 0]):
                continue
            if int(interior[0, 0]) == border:
                continue

            # Make sure this is not the top part of a complete 5x5 object.
            if r + 5 < h:
                next_row = g[r + 5, c:c + 5]
                if np.all(next_row == border):
                    continue

            objects.append((r, c, border, int(interior[0, 0])))

    # Background is the most frequent colour in the input.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])
    out = np.full((h, w), bg, dtype=int)

    # Assign objects to slots.
    # For each border group, sort by original vertical order, then horizontal order.
    # The first object in the group goes to the first slot of that group.
    # Later objects go to the first slot where they do not vertically overlap
    # with an already placed object.
    placed = {0: [], 5: [], 12: [], 17: []}

    def overlaps(r, c_slot, placed_list):
        for pr, pc in placed_list:
            if pc == c_slot and r < pr + 5 and pr < r + 5:
                return True
        return False

    for border, group_slots in ((8, [0, 5]), (2, [12, 17])):
        group = [obj for obj in objects if obj[2] == border]
        group.sort(key=lambda x: (x[0], x[1]))

        for r, c, _, _ in group:
            chosen = None
            for s in group_slots:
                if not overlaps(r, s, placed[s]):
                    chosen = s
                    break
            if chosen is None:
                # Fallback: choose the slot with the least vertical movement.
                chosen = min(group_slots, key=lambda s: abs(s - c))

            # Copy the object. If it was incomplete, reconstruct the missing
            # bottom border row.
            if r + 5 < h:
                block = g[r:r + 5, c:c + 5]
                if (
                    np.all(block[0, :] == border) and
                    np.all(block[4, :] == border) and
                    np.all(block[:, 0] == border) and
                    np.all(block[:, 4] == border)
                ):
                    out[r:r + 5, chosen:chosen + 5] = block
                else:
                    # Incomplete: top + 3 interior rows.
                    out[r, chosen:chosen + 5] = border
                    out[r + 1:r + 4, chosen:chosen + 5] = g[r + 1:r + 4, c:c + 5]
                    out[r + 4, chosen:chosen + 5] = border
            else:
                # Should not happen for valid inputs, but keep safe.
                out[r:r + 5, chosen:chosen + 5] = g[r:r + 5, c:c + 5]

            placed[chosen].append((r, c))

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Determine the background colour as the most frequent colour.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # Collect non-background pixels.
    special = [(r, c, int(g[r, c])) for r in range(h) for c in range(w) if g[r, c] != bg]

    # If there are no special pixels, nothing changes.
    if not special:
        return [[int(x) for x in row] for row in g]

    # The primary "line" colour is the non-background colour that appears
    # at least twice and has at least one diagonal pair.  In the examples this
    # is colour 1.  If no such colour exists, fall back to the most common
    # non-background colour.
    def diagonal_pairs(color):
        pts = [(r, c) for (r, c, col) in special if col == color]
        pairs = []
        for i in range(len(pts)):
            for j in range(i + 1, len(pts)):
                r1, c1 = pts[i]
                r2, c2 = pts[j]
                if abs(r1 - r2) == abs(c1 - c2) and r1 != r2:
                    pairs.append((pts[i], pts[j]))
        return pairs

    primary_color = None
    for col in sorted({col for (_, _, col) in special}, key=lambda x: -sum(1 for (_, _, c) in special if c == x)):
        if sum(1 for (_, _, c) in special if c == c) >= 2 and diagonal_pairs(col):
            primary_color = col
            break
    if primary_color is None:
        primary_color = max({col for (_, _, col) in special}, key=lambda x: sum(1 for (_, _, c) in special if c == x))

    # Draw all diagonal lines between pairs of primary-colour pixels.
    out = g.copy()
    primary_pts = [(r, c) for (r, c, col) in special if col == primary_color]

    def draw_line(p1, p2, color):
        r1, c1 = p1
        r2, c2 = p2
        dr = 1 if r2 > r1 else (-1 if r2 < r1 else 0)
        dc = 1 if c2 > c1 else (-1 if c2 < c1 else 0)
        r, c = r1, c1
        while True:
            out[r, c] = color
            if (r, c) == (r2, c2):
                break
            r += dr
            c += dc

    for i in range(len(primary_pts)):
        for j in range(i + 1, len(primary_pts)):
            p1, p2 = primary_pts[i], primary_pts[j]
            if abs(p1[0] - p2[0]) == abs(p1[1] - p2[1]) and p1[0] != p2[0]:
                draw_line(p1, p2, primary_color)

    # For every non-primary special pixel that lies on a drawn primary line,
    # draw the full perpendicular diagonal through it.
    perp_color = None
    for (r, c, col) in special:
        if col != primary_color:
            perp_color = col
            break
    if perp_color is None:
        return [[int(x) for x in row] for row in out]

    # Determine the primary line direction from any diagonal pair.
    primary_dir = None
    for i in range(len(primary_pts)):
        for j in range(i + 1, len(primary_pts)):
            r1, c1 = primary_pts[i]
            r2, c2 = primary_pts[j]
            if abs(r1 - r2) == abs(c1 - c2) and r1 != r2:
                dr = 1 if r2 > r1 else -1
                dc = 1 if c2 > c1 else -1
                primary_dir = (dr, dc)
                break
        if primary_dir:
            break

    if primary_dir is not None:
        dr, dc = primary_dir
        # Perpendicular diagonal direction: swap one sign.
        pdr, pdc = dr, -dc

        # A point lies on the primary line if it is collinear with the pair
        # and between the endpoints (inclusive).
        def on_primary_line(r, c):
            for i in range(len(primary_pts)):
                for j in range(i + 1, len(primary_pts)):
                    r1, c1 = primary_pts[i]
                    r2, c2 = primary_pts[j]
                    if abs(r1 - r2) != abs(c1 - c2) or r1 == r2:
                        continue
                    # Cross product zero for collinearity.
                    if (r - r1) * (c2 - c1) != (c - c1) * (r2 - r1):
                        continue
                    if min(r1, r2) <= r <= max(r1, r2) and min(c1, c2) <= c <= max(c1, c2):
                        return True
            return False

        for (r, c, col) in special:
            if col == perp_color and on_primary_line(r, c):
                rr, cc = r, c
                while 0 <= rr < h and 0 <= cc < w:
                    out[rr, cc] = perp_color
                    rr += pdr
                    cc += pdc
                rr, cc = r - pdr, c - pdc
                while 0 <= rr < h and 0 <= cc < w:
                    out[rr, cc] = perp_color
                    rr -= pdr
                    cc -= pdc

    return [[int(x) for x in row] for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    out = [row[:] for row in grid]

    # Clear the left area.
    for r in range(len(out)):
        for c in range(9):
            out[r][c] = 0

    # Fixed 5-shape inside the right box.
    # Coordinates are absolute (row, col).
    shape = [
        (2, 11), (3, 11),
        (3, 13),
        (4, 12), (4, 14), (4, 16), (4, 18),
        (5, 12), (5, 13), (5, 14), (5, 15), (5, 16), (5, 17),
    ]
    for r, c in shape:
        out[r][c] = 5

    # Move each vertical digit column upward, stopping at the fixed shape.
    for c in (11, 13, 15, 17):
        vals = []
        for r in range(1, 6):
            v = grid[r][c]
            if v != 0 and v != 5:
                vals.append(v)

        if not vals:
            continue

        # All cells in a column have the same digit in the examples/tests.
        digit = vals[0]
        count = len(vals)

        placed = 0
        for r in range(1, 6):
            if placed >= count:
                break
            if (r, c) in shape:
                continue
            out[r][c] = digit
            placed += 1

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])

    # Find the non-background colour (the plus is always one non-zero colour).
    color = 0
    for row in grid:
        for v in row:
            if v != 0:
                color = v
                break
        if color:
            break

    # Find the hollow plus.
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    if not cells:
        return [row[:] for row in grid]

    min_r = min(r for r, c in cells)
    max_r = max(r for r, c in cells)
    min_c = min(c for r, c in cells)
    max_c = max(c for r, c in cells)

    # Arm length of the input plus.
    arm = (max_r - min_r) // 2

    # The output is a recursive square-spiral pattern whose size is
    # 4 * arm + 8, anchored at the top-left corner.
    n = 4 * arm + 8

    out = [[0] * w for _ in range(h)]

    def set_cell(r, c):
        if 0 <= r < h and 0 <= c < w:
            out[r][c] = color

    def draw(r, c, size, rot):
        # rot:
        # 0: start at top-left, initial direction right
        # 1: start at top-right, initial direction down
        # 2: start at bottom-right, initial direction left
        # 3: start at bottom-left, initial direction up
        if size <= 0:
            return

        if size == 1:
            set_cell(r, c)
            return

        # Draw the outer U-shaped border.
        if rot == 0:
            for i in range(size):
                set_cell(r, c + i)
            for i in range(1, size):
                set_cell(r + i, c + size - 1)
            for i in range(1, size):
                set_cell(r + size - 1, c + size - 1 - i)
        elif rot == 1:
            for i in range(size):
                set_cell(r + i, c)
            for i in range(1, size):
                set_cell(r + size - 1, c - i)
            for i in range(1, size):
                set_cell(r + size - 1 - i, c - size + 1)
        elif rot == 2:
            for i in range(size):
                set_cell(r, c - i)
            for i in range(1, size):
                set_cell(r - i, c - size + 1)
            for i in range(1, size):
                set_cell(r - size + 1, c - size + 1 + i)
        else:  # rot == 3
            for i in range(size):
                set_cell(r - i, c)
            for i in range(1, size):
                set_cell(r - size + 1, c + i)
            for i in range(1, size):
                set_cell(r - size + 1 + i, c + size - 1)

        # Recurse into the inner square.
        inner = size - 2
        if inner > 0:
            if rot == 0:
                draw(r + 1, c + inner, inner, 1)
            elif rot == 1:
                draw(r + inner, c - 1, inner, 2)
            elif rot == 2:
                draw(r - 1, c - inner, inner, 3)
            else:
                draw(r - inner, c + 1, inner, 0)

    draw(0, n - 1, n, 0)
    return out

import numpy as np
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]):
    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Find the legend/key: a maximal all-nonzero rectangle of size at least 2x2
    # that is not monochromatic.  In the examples it is always 2 x N or N x 2.
    mapping = {}
    best = None

    for r in range(h):
        for c in range(w):
            if g[r, c] == 0:
                continue
            # expand maximal rectangle of nonzero cells starting at (r, c)
            max_h = 1
            while r + max_h < h and g[r + max_h, c] != 0:
                max_h += 1
            max_w = 1
            while c + max_w < w and g[r, c + max_w] != 0:
                max_w += 1

            # check full rectangle
            full_h = max_h
            for rr in range(1, max_h):
                row = g[r + rr, c:c + max_w]
                if np.any(row == 0):
                    full_h = rr
                    break
            full_w = max_w
            for cc in range(1, max_w):
                col = g[r:r + full_h, c + cc]
                if np.any(col == 0):
                    full_w = cc
                    break

            if full_h >= 2 and full_w >= 2:
                block = g[r:r + full_h, c:c + full_w]
                if len(np.unique(block)) > 1:
                    # Prefer the largest such rectangle; ties are not expected.
                    area = full_h * full_w
                    if best is None or area > best[0]:
                        best = (area, r, c, full_h, full_w)

    if best is not None:
        _, r, c, rh, rw = best
        block = g[r:r + rh, c:c + rw]

        # Determine orientation:
        # 2 rows -> top maps to bottom
        # 2 columns -> left maps to right
        # 2x2 -> top maps to bottom (as in Example 3)
        if rh == 2 or (rh == 2 and rw == 2):
            for j in range(rw):
                src = int(block[0, j])
                dst = int(block[1, j])
                mapping[src] = dst
        elif rw == 2:
            for i in range(rh):
                src = int(block[i, 0])
                dst = int(block[i, 1])
                mapping[src] = dst
        else:
            # Fallback: treat first row as sources and second row as targets.
            for j in range(rw):
                mapping[int(block[0, j])] = int(block[1, j])

    # Find all 0-components not connected to the border (4-connectivity).
    visited = np.zeros((h, w), dtype=bool)
    out = g.copy()

    for r in range(h):
        for c in range(w):
            if g[r, c] != 0 or visited[r, c]:
                continue

            # BFS over this zero component
            q = deque([(r, c)])
            visited[r, c] = True
            comp = []
            touches_border = False
            boundary_colors = set()

            while q:
                y, x = q.popleft()
                comp.append((y, x))
                if y == 0 or x == 0 or y == h - 1 or x == w - 1:
                    touches_border = True

                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not visited[ny, nx]:
                        val = g[ny, nx]
                        if val == 0:
                            visited[ny, nx] = True
                            q.append((ny, nx))
                        elif val != 0:
                            boundary_colors.add(int(val))

            if touches_border:
                continue

            # Fill only if the hole is bounded by exactly one mapped color.
            if len(boundary_colors) == 1:
                color = next(iter(boundary_colors))
                if color in mapping:
                    fill = mapping[color]
                    for y, x in comp:
                        out[y, x] = fill

    return out.tolist()

from collections import deque

def transform(grid):
    h = len(grid)
    w = len(grid[0]) if h else 0

    # Find the color-mapping key:
    # a non-zero, non-monochrome rectangle, preferably with one side of length 2.
    best = None  # (priority, area, r, c, rh, rw)

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0:
                continue

            max_h = 1
            while r + max_h < h and grid[r + max_h][c] != 0:
                max_h += 1

            max_w = 1
            while c + max_w < w and grid[r][c + max_w] != 0:
                max_w += 1

            full_h = max_h
            for rr in range(1, max_h):
                if any(grid[r + rr][cc] == 0 for cc in range(c, c + max_w)):
                    full_h = rr
                    break

            full_w = max_w
            for cc in range(1, max_w):
                if any(grid[rr][c + cc] == 0 for rr in range(r, r + full_h)):
                    full_w = cc
                    break

            if full_h >= 2 and full_w >= 2:
                block = [grid[r + i][c:c + full_w] for i in range(full_h)]
                colors = {v for row in block for v in row}
                if len(colors) > 1:
                    area = full_h * full_w
                    priority = 1 if (full_h == 2 or full_w == 2) else 0
                    cand = (priority, area, r, c, full_h, full_w)
                    if best is None or cand[:2] > best[:2]:
                        best = cand

    mapping = {}
    if best is not None:
        _, _, r, c, rh, rw = best

        # If the key is wider than tall (or square), read top row -> bottom row.
        # If it is taller than wide, read left column -> right column.
        if rh <= rw:
            for j in range(rw):
                mapping[grid[r][c + j]] = grid[r + 1][c + j]
        else:
            for i in range(rh):
                mapping[grid[r + i][c]] = grid[r + i][c + 1]

    out = [row[:] for row in grid]
    visited = [[False] * w for _ in range(h)]

    # Fill enclosed zero regions whose boundary is a single mapped color.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or visited[r][c]:
                continue

            q = deque([(r, c)])
            visited[r][c] = True
            comp = []
            touches_border = False
            boundary = set()

            while q:
                y, x = q.popleft()
                comp.append((y, x))

                if y == 0 or x == 0 or y == h - 1 or x == w - 1:
                    touches_border = True

                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w:
                        val = grid[ny][nx]
                        if val == 0:
                            if not visited[ny][nx]:
                                visited[ny][nx] = True
                                q.append((ny, nx))
                        else:
                            boundary.add(val)

            if not touches_border and len(boundary) == 1:
                color = next(iter(boundary))
                if color in mapping:
                    fill = mapping[color]
                    for y, x in comp:
                        out[y][x] = fill

    return out

