def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return [row[:] for row in grid]

    h = len(grid)
    w = len(grid[0])
    out = [row[:] for row in grid]

    # Find the vertical divider: a column whose non-zero cells are all one colour,
    # preferring the longest such vertical run.
    best_col = -1
    best_color = 0
    best_score = (-1, -1)

    for c in range(w):
        colors = {}
        for r in range(h):
            v = grid[r][c]
            if v != 0:
                colors[v] = colors.get(v, 0) + 1

        if len(colors) == 1:
            color, count = next(iter(colors.items()))
            max_run = cur = 0
            for r in range(h):
                if grid[r][c] == color:
                    cur += 1
                    if cur > max_run:
                        max_run = cur
                else:
                    cur = 0
            score = (count, max_run)
            if score > best_score:
                best_score = score
                best_col = c
                best_color = color

    if best_col == -1:
        return out

    line_c = best_col
    line_color = best_color

    # Decide which side contains the source objects.
    left_count = 0
    right_count = 0
    for r in range(h):
        for c in range(line_c):
            if grid[r][c] not in (0, line_color):
                left_count += 1
        for c in range(line_c + 1, w):
            if grid[r][c] not in (0, line_color):
                right_count += 1

    if left_count == 0 and right_count == 0:
        return out

    source_left = left_count >= right_count

    def block_from_left(row, stop_c):
        """Rightmost monochromatic non-background/non-line run left of stop_c."""
        for i in range(stop_c - 1, -1, -1):
            v = row[i]
            if v == 0 or v == line_color:
                continue
            j = i
            while j - 1 >= 0 and row[j - 1] == v:
                j -= 1
            return v, i - j + 1
        return None

    def block_from_right(row, start_c):
        """Leftmost monochromatic non-background/non-line run right of start_c."""
        for i in range(start_c + 1, w):
            v = row[i]
            if v == 0 or v == line_color:
                continue
            j = i
            while j + 1 < w and row[j + 1] == v:
                j += 1
            return v, j - i + 1
        return None

    if source_left:
        for r in range(h):
            blk = block_from_left(out[r], line_c)
            if blk is None:
                continue
            color, period = blk
            for c in range(line_c + 1, w):
                off = c - (line_c + 1)
                out[r][c] = color if off % period == 0 else 0
    else:
        for r in range(h):
            blk = block_from_right(out[r], line_c)
            if blk is None:
                continue
            color, period = blk
            for c in range(line_c - 1, -1, -1):
                off = (line_c - 1) - c
                out[r][c] = color if off % period == 0 else 0

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return [row[:] for row in grid]

    h = len(grid)
    w = len(grid[0])
    out = [row[:] for row in grid]

    # Find the vertical divider.
    # Prefer a column with a long vertical run of one non-zero colour,
    # and especially one that borders an empty side.
    best = None  # (score, col, color)

    for c in range(w):
        counts = {}
        runs = {}
        last = None
        cur = 0

        for r in range(h):
            v = grid[r][c]
            if v == 0:
                last = None
                cur = 0
                continue

            if v not in counts:
                counts[v] = 0
                runs[v] = 0

            counts[v] += 1

            if v == last:
                cur += 1
            else:
                cur = 1
                last = v

            if cur > runs[v]:
                runs[v] = cur

        if not counts:
            continue

        color = max(counts, key=lambda x: (counts[x], runs[x]))
        count = counts[color]
        run = runs[color]

        # The divider is normally a long/full vertical line.
        if run < max(1, h // 2):
            continue

        left_empty = all(grid[r][cc] == 0 for r in range(h) for cc in range(c))
        right_empty = all(grid[r][cc] == 0 for r in range(h) for cc in range(c + 1, w))

        empty_len = -1
        if left_empty:
            empty_len = max(empty_len, c)
        if right_empty:
            empty_len = max(empty_len, w - c - 1)

        score = (empty_len >= 0, empty_len, run, count)
        if best is None or score > best[0]:
            best = (score, c, color)

    if best is None:
        # Fallback: choose the strongest vertical monochrome column.
        for c in range(w):
            counts = {}
            runs = {}
            last = None
            cur = 0

            for r in range(h):
                v = grid[r][c]
                if v == 0:
                    last = None
                    cur = 0
                    continue

                if v not in counts:
                    counts[v] = 0
                    runs[v] = 0

                counts[v] += 1

                if v == last:
                    cur += 1
                else:
                    cur = 1
                    last = v

                if cur > runs[v]:
                    runs[v] = cur

            if not counts:
                continue

            color = max(counts, key=lambda x: (counts[x], runs[x]))
            score = (runs[color], counts[color])
            if best is None or score > best[0]:
                best = (score, c, color)

    if best is None:
        return out

    line_c, line_color = best[1], best[2]

    # Choose the side that contains the source objects.
    left_count = 0
    right_count = 0
    for r in range(h):
        for c in range(line_c):
            if grid[r][c] != 0:
                left_count += 1
        for c in range(line_c + 1, w):
            if grid[r][c] != 0:
                right_count += 1

    if left_count == 0 and right_count == 0:
        return out

    source_left = left_count >= right_count

    for r in range(h):
        runs = []

        if source_left:
            # Scan from the divider outward to the left.
            c = line_c - 1
            while c >= 0:
                v = grid[r][c]
                if v == 0:
                    c -= 1
                    continue

                end = c
                while c - 1 >= 0 and grid[r][c - 1] == v:
                    c -= 1
                start = c
                length = end - start + 1
                distance = line_c - end
                runs.append((distance, v, length))
                c -= 1
        else:
            # Scan from the divider outward to the right.
            c = line_c + 1
            while c < w:
                v = grid[r][c]
                if v == 0:
                    c += 1
                    continue

                start = c
                while c + 1 < w and grid[r][c + 1] == v:
                    c += 1
                end = c
                length = end - start + 1
                distance = start - line_c
                runs.append((distance, v, length))
                c += 1

        if not runs:
            # Clear the target side for this row.
            if source_left:
                for c in range(line_c + 1, w):
                    out[r][c] = 0
            else:
                for c in range(0, line_c):
                    out[r][c] = 0
            continue

        # Closer runs to the divider are drawn on top of farther runs.
        runs.sort(key=lambda x: x[0])

        if source_left:
            target_len = w - line_c - 1
        else:
            target_len = line_c

        target = [0] * target_len

        for _, color, length in runs:
            if length <= 0:
                continue
            for off in range(0, target_len, length):
                if target[off] == 0:
                    target[off] = color

        if source_left:
            for off, val in enumerate(target):
                out[r][line_c + 1 + off] = val
        else:
            for off, val in enumerate(target):
                out[r][line_c - 1 - off] = val

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    H, W = g.shape
    out = np.full((H, W), 8, dtype=int)

    # Keep the vertical 2-line associated with the 4 marker.
    for r in range(H):
        for c in range(W):
            if g[r, c] == 4:
                for rr in range(r, H):
                    if g[rr, c] == 2:
                        out[rr, c] = 2
                    else:
                        break

    # Connected components of 1s.
    comp_id = -np.ones((H, W), dtype=int)
    comps = []
    for r in range(H):
        for c in range(W):
            if g[r, c] == 1 and comp_id[r, c] == -1:
                cid = len(comps)
                stack = [(r, c)]
                comp_id[r, c] = cid
                cells = []
