                        ny, nx = y + dy, x + dx
                        if 0 <= ny < H and 0 <= nx < W:
                            if g[ny, nx] == 1 and comp_id[ny, nx] == -1:
                                comp_id[ny, nx] = cid
                                stack.append((ny, nx))
                comps.append(cells)

