                    out[rr, cc] = 2
                if cid in comp_dirs:
                    d = comp_dirs[cid]
                    # Emit from every 3 attached in that direction.
                    for (rr, cc) in comps[cid]:
                        er, ec = rr + d[0], cc + d[1]
                        if 0 <= er < H and 0 <= ec < W and g[er, ec] == 3:
                            stack.append((er, ec, d))
        elif v == 3:
            # A 3 not attached to an active component is ignored.
            pass

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    H, W = g.shape
    out = np.full((H, W), 8, dtype=int)

    # Find the 4 and determine initial direction from 2s
    start = None
    init_dir = None
    for r in range(H):
        for c in range(W):
            if g[r, c] == 4:
                start = (r, c)
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < H and 0 <= nc < W and g[nr, nc] == 2:
                        init_dir = (dr, dc)
                        break
                break
        if start:
            break

    if start is None or init_dir is None:
        return out.tolist()

    # Find connected components of 1s
    comp_id = -np.ones((H, W), dtype=int)
    comps = []
    for r in range(H):
        for c in range(W):
            if g[r, c] == 1 and comp_id[r, c] == -1:
                cid = len(comps)
                stack = [(r, c)]
                comp_id[r, c] = cid
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy, dx in [(1,0),(-1,0),(0,1),(0,-1)]:
                        ny, nx = y+dy, x+dx
                        if 0 <= ny < H and 0 <= nx < W:
                            if g[ny, nx] == 1 and comp_id[ny, nx] == -1:
                                comp_id[ny, nx] = cid
                                stack.append((ny, nx))
                comps.append(cells)

    # For each component, find 3s and their direction
    comp_3s = {}
    for cid, cells in enumerate(comps):
        cell_set = set(cells)
        threes = []
        for (r, c) in cells:
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < H and 0 <= nc < W and g[nr, nc] == 3:
                    if (nr, nc) not in cell_set:
                        threes.append(((nr, nc), (dr, dc)))
        if threes:
            comp_3s[cid] = threes

    # BFS beam propagation
    visited_comps = set()
    queue = deque()
    queue.append((start[0], start[1], init_dir))

    while queue:
        r, c, (dr, dc) = queue.popleft()
        nr, nc = r + dr, c + dc
        if not (0 <= nr < H and 0 <= nc < W):
            continue

        v = g[nr, nc]
        if v == 8:
            out[nr, nc] = 2
            queue.append((nr, nc, (dr, dc)))
        elif v == 1:
            cid = comp_id[nr, nc]
            if cid not in visited_comps:
                visited_comps.add(cid)
                for (rr, cc) in comps[cid]:
                    out[rr, cc] = 2
                if cid in comp_3s:
                    for (tr, tc), (tdr, tdc) in comp_3s[cid]:
                        out[tr, tc] = 2
                        queue.append((tr, tc, (tdr, tdc)))
        elif v == 3:
            out[nr, nc] = 2

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Find the palette: a solid rectangular block of non-zero cells.
    # In the examples it is the only/all-nonzero rectangle that is not a frame.
    best = None
    for r0 in range(h):
        for c0 in range(w):
            if g[r0, c0] == 0:
                continue
            r1 = r0
            while r1 + 1 < h and all(g[r1 + 1, c0:c0 + (w - c0)] != 0):
                r1 += 1
            c1 = c0
            while c1 + 1 < w and all(g[r0:r1 + 1, c1 + 1] != 0):
                c1 += 1
            sub = g[r0:r1 + 1, c0:c1 + 1]
            if np.all(sub != 0):
                area = (r1 - r0 + 1) * (c1 - c0 + 1)
                # Prefer small, compact palette blocks.
                if best is None or area < best[0]:
                    best = (area, r0, c0, r1, c1)

    if best is None:
        return out.tolist()

    _, pr0, pc0, pr1, pc1 = best
    palette = g[pr0:pr1 + 1, pc0:pc1 + 1]
    ph, pw = palette.shape

    # Build a directed mapping from palette colors.
    # The palette is read column-major; each color maps to the next color
    # in that order.  If a color appears multiple times, keep all possible
    # mappings; later we choose the one that is actually usable.
    mapping = {}
    order = []
    for c in range(pw):
        for r in range(ph):
            order.append(palette[r, c])
    for i, col in enumerate(order):
        nxt = order[(i + 1) % len(order)]
        mapping.setdefault(col, set()).add(nxt)

    # Find all enclosed zero regions (holes).
    visited = np.zeros((h, w), dtype=bool)
    holes = []
    for r in range(h):
        for c in range(w):
            if g[r, c] != 0 or visited[r, c]:
                continue
            q = deque([(r, c)])
            visited[r, c] = True
            cells = []
            touches_border = False
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                if y == 0 or x == 0 or y == h - 1 or x == w - 1:
                    touches_border = True
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not visited[ny, nx] and g[ny, nx] == 0:
                        visited[ny, nx] = True
                        q.append((ny, nx))
            if not touches_border:
                holes.append(cells)

    # For each hole, determine the surrounding frame color.
    # A hole is filled only if it is surrounded by a single non-zero color
    # and that color has a palette mapping to a different color.
    for cells in holes:
        frame_colors = set()
        for y, x in cells:
            for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                ny, nx = y + dy, x + dx
                if 0 <= ny < h and 0 <= nx < w and g[ny, nx] != 0:
                    frame_colors.add(int(g[ny, nx]))
        if len(frame_colors) != 1:
            continue
        frame_color = next(iter(frame_colors))
        if frame_color not in mapping:
            continue
        candidates = [c for c in mapping[frame_color] if c != frame_color]
        if not candidates:
            continue
        # If multiple candidates exist, choose the one that appears in the
        # palette adjacent to the frame color in the column-major direction.
        fill = candidates[0]
        for y, x in cells:
            out[y, x] = fill

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Find the palette: the largest all-nonzero rectangle with height > 1
    # and width > 1.  In the examples this is the small solid key block.
    best = None
    for r0 in range(h):
        for c0 in range(w):
            if g[r0, c0] == 0:
                continue
            for r1 in range(r0 + 1, h):
                if any(g[r1, c0:c0 + w] == 0):
                    break
                for c1 in range(c0 + 1, w):
                    if any(g[r0:r1 + 1, c1] == 0):
                        break
                    area = (r1 - r0 + 1) * (c1 - c0 + 1)
                    if best is None or area > best[0]:
                        best = (area, r0, c0, r1, c1)

    if best is None:
        return out.tolist()

    _, pr0, pc0, pr1, pc1 = best
    palette = g[pr0:pr1 + 1, pc0:pc1 + 1]
    ph, pw = palette.shape

    # Build the colour mapping from the palette.
    # If the palette has two rows, map top -> bottom column-wise.
    # Otherwise, if it has two columns, map left -> right row-wise.
    mapping = {}
    if ph == 2:
        for c in range(pw):
            src = int(palette[0, c])
            dst = int(palette[1, c])
            mapping[src] = dst
    elif pw == 2:
        for r in range(ph):
            src = int(palette[r, 0])
            dst = int(palette[r, 1])
            mapping[src] = dst

    # Mark all zero cells connected to the border as exterior.
    exterior = np.zeros((h, w), dtype=bool)
    q = deque()

    for r in range(h):
        for c in (0, w - 1):
            if g[r, c] == 0 and not exterior[r, c]:
                exterior[r, c] = True
                q.append((r, c))

    for c in range(w):
        for r in (0, h - 1):
            if g[r, c] == 0 and not exterior[r, c]:
                exterior[r, c] = True
                q.append((r, c))

    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
                if g[nr, nc] == 0 and not exterior[nr, nc]:
                    exterior[nr, nc] = True
                    q.append((nr, nc))

    # Find enclosed zero regions (holes).
    visited = exterior.copy()
    for r in range(h):
        for c in range(w):
            if g[r, c] != 0 or visited[r, c]:
                continue

            q = deque([(r, c)])
            visited[r, c] = True
            cells = []
            boundary_colors = set()

            while q:
                y, x = q.popleft()
                cells.append((y, x))

                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w:
                        if g[ny, nx] == 0:
                            if not visited[ny, nx]:
                                visited[ny, nx] = True
                                q.append((ny, nx))
                        else:
                            boundary_colors.add(int(g[ny, nx]))

            # Fill only holes surrounded by a single colour that has a mapping.
            if len(boundary_colors) == 1:
                frame_color = next(iter(boundary_colors))
                if frame_color in mapping:
                    fill_color = mapping[frame_color]
                    for y, x in cells:
                        out[y, x] = fill_color

    return out.tolist()

import numpy as np
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # 8-connected components of 1s
    seen = np.zeros((h, w), dtype=bool)
    comps = []
    for r in range(h):
        for c in range(w):
            if g[r, c] == 1 and not seen[r, c]:
                q = deque([(r, c)])
                seen[r, c] = True
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            if dy == 0 and dx == 0:
                                continue
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < h and 0 <= nx < w and not seen[ny, nx] and g[ny, nx] == 1:
                                seen[ny, nx] = True
                                q.append((ny, nx))
                comps.append(cells)

    for cells in comps:
        ys = [r for r, _ in cells]
        xs = [c for _, c in cells]
        r0, r1 = min(ys), max(ys)
        c0, c1 = min(xs), max(xs)

        # Is the component hollow?  A 4-connected background region inside
        # the bounding box that does not touch the bounding-box border.
        inside = np.zeros((r1 - r0 + 1, c1 - c0 + 1), dtype=bool)
        for r, c in cells:
            inside[r - r0, c - c0] = True

        hole = False
        for i in range(inside.shape[0]):
            for j in range(inside.shape[1]):
                if inside[i, j] or i == 0 or i == inside.shape[0] - 1 or j == 0 or j == inside.shape[1] - 1:
                    continue
                q = deque([(i, j)])
                vis = np.zeros(inside.shape, dtype=bool)
                vis[i, j] = True
                while q:
                    y, x = q.popleft()
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < inside.shape[0] and 0 <= nx < inside.shape[1] and not vis[ny, nx] and not inside[ny, nx]:
                            vis[ny, nx] = True
                            q.append((ny, nx))
                hole = True
                break
            if hole:
                break

        if not hole:
            # Solid component: put a 2-border around its bounding box.
            for r in range(max(0, r0 - 1), min(h, r1 + 2)):
                for c in range(max(0, c0 - 1), min(w, c1 + 2)):
                    if r == r0 - 1 or r == r1 + 1 or c == c0 - 1 or c == c1 + 1:
                        out[r, c] = 2
        else:
            # Hollow component: fill the bounding box with 8,
            # fill the interior (excluding the outer 8-frame) with 6,
            # then put a 2-border around the filled box.
            for r in range(r0, r1 + 1):
                for c in range(c0, c1 + 1):
                    out[r, c] = 8
            for r in range(r0 + 1, r1):
                for c in range(c0 + 1, c1):
                    out[r, c] = 6
            for r in range(max(0, r0 - 1), min(h, r1 + 2)):
                for c in range(max(0, c0 - 1), min(w, c1 + 2)):
                    if r == r0 - 1 or r == r1 + 1 or c == c0 - 1 or c == c1 + 1:
                        out[r, c] = 2

    return out.tolist()

import numpy as np
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # 8-connected components of 1s
    seen = np.zeros((h, w), dtype=bool)
    comps = []
    for r in range(h):
        for c in range(w):
            if g[r, c] == 1 and not seen[r, c]:
                q = deque([(r, c)])
                seen[r, c] = True
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            if dy == 0 and dx == 0:
                                continue
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < h and 0 <= nx < w and not seen[ny, nx] and g[ny, nx] == 1:
                                seen[ny, nx] = True
                                q.append((ny, nx))
                comps.append(cells)

    # 4-connected background regions (0/4)
    bg_seen = np.zeros((h, w), dtype=bool)
    bg_regions = []
    for r in range(h):
        for c in range(w):
            if g[r, c] != 1 and not bg_seen[r, c]:
                q = deque([(r, c)])
                bg_seen[r, c] = True
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and not bg_seen[ny, nx] and g[ny, nx] != 1:
                            bg_seen[ny, nx] = True
                            q.append((ny, nx))
                bg_regions.append(cells)

    # For each background region, find which 1-components touch it (8-neighbor)
    region_comps = []
    for cells in bg_regions:
        comp_ids = set()
        for y, x in cells:
            for dy in (-1, 0, 1):
                for dx in (-1, 0, 1):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and g[ny, nx] == 1:
                        comp_ids.add((ny, nx))
        # map touched cells to component id by recomputing component id array
        region_comps.append(comp_ids)

    # component id array
    comp_id = np.full((h, w), -1, dtype=int)
    for i, cells in enumerate(comps):
        for y, x in cells:
            comp_id[y, x] = i

    # Determine which components have at least one enclosed hole:
    # a background region not touching grid border and touching exactly one component.
    has_hole = [False] * len(comps)
    hole_cells = [set() for _ in comps]
    for cells, touched in zip(bg_regions, region_comps):
        touches_border = any(y == 0 or y == h - 1 or x == 0 or x == w - 1 for y, x in cells)
        if touches_border:
            continue
        # unique component ids actually adjacent
        ids = set()
        for y, x in cells:
            for dy in (-1, 0, 1):
                for dx in (-1, 0, 1):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and g[ny, nx] == 1:
                        ids.add(comp_id[ny, nx])
        if len(ids) == 1:
            cid = next(iter(ids))
            has_hole[cid] = True
            for y, x in cells:
                hole_cells[cid].add((y, x))

    # For each component:
    for cid, cells in enumerate(comps):
        # 8-neighbor dilation of the component
        dil = set()
        for y, x in cells:
            for dy in (-1, 0, 1):
                for dx in (-1, 0, 1):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w:
                        dil.add((ny, nx))

        if has_hole[cid]:
            # all original 1s in this component become 8
            for y, x in cells:
                out[y, x] = 8
            # enclosed hole cells become 6
            for y, x in hole_cells[cid]:
                out[y, x] = 6
            # outside border: dilated cells that are not original 1s and not holes -> 2
            for y, x in dil:
                if (y, x) not in hole_cells[cid] and g[y, x] != 1:
                    out[y, x] = 2
        else:
            # solid component: keep 1s, add 2 border on background cells
            for y, x in dil:
                if g[y, x] != 1:
                    out[y, x] = 2

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.array(grid, dtype=int)
    H, W = g.shape
    out = g.copy()

    # Determine the global background colour (most common on the border).
    border_vals = np.concatenate([g[0, :], g[-1, :], g[:, 0], g[:, -1]])
    bg = int(np.bincount(border_vals).argmax())

    # Find full-width horizontal bands:
    # first/last cell are the band border colour, all interior cells are one fill colour.
    bands = []
    r = 0
    while r < H:
        if g[r, 0] != g[r, -1] or g[r, 0] == bg:
            r += 1
            continue
        border_c = int(g[r, 0])
        fill_c = int(g[r, 1])
        if fill_c == border_c or fill_c == bg:
            r += 1
            continue
        r2 = r
        while (
            r2 + 1 < H
            and g[r2 + 1, 0] == border_c
            and g[r2 + 1, -1] == border_c
            and np.all(g[r2 + 1, 1:-1] == fill_c)
        ):
            r2 += 1
        bands.append((r, r2, border_c, fill_c))
        r = r2 + 1

    # Mask out the bands so they are not treated as source shapes.
    band_mask = np.zeros((H, W), dtype=bool)
    for r1, r2, _, _ in bands:
        band_mask[r1:r2 + 1, :] = True

    # Connected components of non-background, non-band cells.
    seen = np.zeros((H, W), dtype=bool)
    shapes = []
    for i in range(H):
        for j in range(W):
            if seen[i, j] or band_mask[i, j] or g[i, j] == bg:
                continue
            q = deque([(i, j)])
            seen[i, j] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < H and 0 <= nx < W:
                        if not seen[ny, nx] and not band_mask[ny, nx] and g[ny, nx] != bg:
                            seen[ny, nx] = True
                            q.append((ny, nx))
            shapes.append(cells)

    # For each shape, find the band whose fill colour is one of the shape's colours.
    # That colour is the shape's "outer" colour and becomes the band border colour.
    # All other shape colours become the band fill colour.
    for cells in shapes:
        cols = {int(g[y, x]) for y, x in cells}
        target = None
        for r1, r2, border_c, fill_c in bands:
            if fill_c in cols:
                target = (r1, r2, border_c, fill_c)
                break
        if target is None:
            continue

        r1, r2, border_c, fill_c = target
        h = max(y for y, _ in cells) - min(y for y, _ in cells) + 1
        top = r2 - h + 1  # bottom-align inside the band

        for y, x in cells:
            ny = top + (y - min(yy for yy, _ in cells))
            if 0 <= ny < H and 0 <= x < W:
                if int(g[y, x]) == fill_c:
                    out[ny, x] = border_c
                else:
                    out[ny, x] = fill_c

    # Remove all original source shapes.
    for cells in shapes:
        for y, x in cells:
            out[y, x] = bg

    return out.tolist()

