        cols = {int(g[y, x]) for y, x in cells}
        target = None
        for r1, r2, border_c, fill_c in bands:
            if fill_c in cols:
                target = (r1, r2, border_c, fill_c)
                break
        if target is None:
            continue

        r1, r2, border_c, fill_c = target
        min_y = min(y for y, _ in cells)
        h = max(y for y, _ in cells) - min_y + 1
        top = r2 - h + 1  # bottom-align

        for y, x in cells:
            ny = top + (y - min_y)
            if 0 <= ny < H and 0 <= x < W:
                if int(g[y, x]) == fill_c:
                    out[ny, x] = border_c
                else:
                    out[ny, x] = fill_c

    # Erase original shapes
    for cells in shapes:
        for y, x in cells:
            out[y, x] = bg

    return out.tolist()

import numpy as np
from collections import defaultdict

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Background is the most frequent colour.
    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # Find the compact "code" in the top-left: non-background cells on
    # alternating rows/columns.
    nonbg = np.argwhere(g != bg)
    if len(nonbg) == 0:
        return [list(map(int, row)) for row in g]

    # Restrict to the top-left code region: rows/cols with odd indices
    # and before the first large empty gap.
    code_cells = []
    for r, c in nonbg:
        if r % 2 == 1 and c % 2 == 1:
            code_cells.append((int(r), int(c)))

    if not code_cells:
        return [list(map(int, row)) for row in g]

    code_rows = sorted({r for r, c in code_cells})
    code_cols = sorted({c for r, c in code_cells})

    # Keep only the first contiguous group of code rows/cols (spacing 2).
    def first_contiguous_group(indices):
        if not indices:
            return []
        group = [indices[0]]
        for x in indices[1:]:
            if x - group[-1] == 2:
                group.append(x)
            else:
                break
        return group

    code_rows = first_contiguous_group(code_rows)
    code_cols = first_contiguous_group(code_cols)

    if not code_rows or not code_cols:
        return [list(map(int, row)) for row in g]

    R = len(code_rows)
    C = len(code_cols)

    code = [[bg] * C for _ in range(R)]
    for r, c in code_cells:
        if r in code_rows and c in code_cols:
            code[code_rows.index(r)][code_cols.index(c)] = int(g[r, c])

    # Find all solid rectangular blocks of non-background colour outside
    # the code region.
    def is_code_cell(r, c):
        return r in code_rows and c in code_cols

    blocks = []
    visited = np.zeros((H, W), dtype=bool)

    for r in range(H):
        for c in range(W):
            if visited[r, c] or g[r, c] == bg or is_code_cell(r, c):
                continue

            color = int(g[r, c])

            # Grow a maximal solid rectangle of this colour.
            r2 = r
            while r2 + 1 < H and g[r2 + 1, c] == color:
                r2 += 1
            c2 = c
            while c2 + 1 < W and g[r, c2 + 1] == color:
                c2 += 1

            # Verify rectangle is solid.
            ok = True
            for rr in range(r, r2 + 1):
                for cc in range(c, c2 + 1):
                    if g[rr, cc] != color:
                        ok = False
                        break
                if not ok:
                    break

            if not ok:
                continue

            h = r2 - r + 1
            w = c2 - c + 1

            # Accept reasonably compact blocks.
            if h <= 10 and w <= 10:
                blocks.append((r, c, h, w, color))
                for rr in range(r, r2 + 1):
                    for cc in range(c, c2 + 1):
                        visited[rr, cc] = True

    if not blocks:
        return [list(map(int, row)) for row in g]

    # Infer block size from the most common block dimensions.
    size_counts = defaultdict(int)
    for _, _, h, w, _ in blocks:
        size_counts[(h, w)] += 1
    bh, bw = max(size_counts.items(), key=lambda kv: kv[1])[0]

    # Keep blocks of that size.
    blocks = [b for b in blocks if b[2] == bh and b[3] == bw]
    if not blocks:
        return [list(map(int, row)) for row in g]

    # Infer vertical and horizontal periods from block top-left positions.
    def infer_period(positions):
        positions = sorted(set(positions))
        if len(positions) < 2:
            return None
        diffs = [positions[i + 1] - positions[i] for i in range(len(positions) - 1)]
        # Use the smallest positive difference that is at least the block size.
        valid = [d for d in diffs if d >= 1]
        if not valid:
            return None
        return min(valid)

    v_period = infer_period([b[0] for b in blocks])
    h_period = infer_period([b[1] for b in blocks])

    # If only one row/column of blocks is present, estimate period from
    # block size plus a small gap.  The examples use gap 1 or 2; choose
    # the smallest period that does not overlap and fits the grid.
    if v_period is None:
        v_period = bh + 1
    if h_period is None:
        h_period = bw + 1

    # Choose an origin so that all existing blocks align to the grid.
    # For each block, its grid row/col index is (pos - origin) / period.
    # We try origins congruent to block positions modulo period.
    def best_origin(positions, period, size, limit):
        candidates = []
        for pos in positions:
            # origin can be pos - k*period for k >= 0, within reasonable range
            for k in range(0, 20):
                origin = pos - k * period
                if origin < -limit:
                    break
                candidates.append(origin)
        best = None
        best_score = -1
        for origin in set(candidates):
            score = 0
            for pos in positions:
                if (pos - origin) % period == 0 and (pos - origin) >= 0:
                    idx = (pos - origin) // period
                    if 0 <= idx < 20:
                        score += 1
            if score > best_score:
                best_score = score
                best = origin
        return best

    v_origin = best_origin([b[0] for b in blocks], v_period, bh, 50)
    h_origin = best_origin([b[1] for b in blocks], h_period, bw, 50)

    if v_origin is None:
        v_origin = min(b[0] for b in blocks)
    if h_origin is None:
        h_origin = min(b[1] for b in blocks)

    # Map existing blocks to code cells.
    # A block at grid (i,j) should match code[i][j] if that code cell is non-bg.
    # If multiple blocks map to the same cell, keep the one whose colour matches.
    existing = {}
    for r, c, h, w, color in blocks:
        if (r - v_origin) % v_period != 0 or (c - h_origin) % h_period != 0:
            continue
        i = (r - v_origin) // v_period
        j = (c - h_origin) // h_period
        if 0 <= i < R and 0 <= j < C:
            # Prefer matching colour; otherwise store first.
            if (i, j) not in existing or code[i][j] == color:
                existing[(i, j)] = (r, c, h, w, color)

    # If no existing block aligned, try shifting origin to align at least one.
    if not existing:
        for r, c, h, w, color in blocks:
            for i in range(R):
                for j in range(C):
                    if code[i][j] == color:
                        v_origin = r - i * v_period
                        h_origin = c - j * h_period
                        existing[(i, j)] = (r, c, h, w, color)
                        break
                if existing:
                    break
            if existing:
                break

    # Build output.
    out = g.copy()

    def place_block(i, j, color):
        if not (0 <= i < R and 0 <= j < C):
            return
        if code[i][j] == bg:
            return
        r = v_origin + i * v_period
        c = h_origin + j * h_period
        if r < 0 or c < 0 or r + bh > H or c + bw > W:
            return
        # Do not overwrite code cells or existing different blocks.
        for rr in range(r, r + bh):
            for cc in range(c, c + bw):
                if is_code_cell(rr, cc):
                    return
        out[r:r + bh, c:c + bw] = color

    # Fill all non-background code cells.
    for i in range(R):
        for j in range(C):
            if code[i][j] != bg:
                place_block(i, j, int(code[i][j]))

    return [list(map(int, row)) for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    from collections import Counter
    import math

    H = len(grid)
    W = len(grid[0]) if H else 0
    out = [row[:] for row in grid]

    if H == 0 or W == 0:
        return out

    # Background is the most frequent colour.
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Connected components of non-background cells (4-neighbour, same colour).
    visited = [[False] * W for _ in range(H)]
    components = []

    for r in range(H):
        for c in range(W):
            if visited[r][c] or grid[r][c] == bg:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            visited[r][c] = True
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = rr + dr, cc + dc
                    if 0 <= nr < H and 0 <= nc < W:
                        if not visited[nr][nc] and grid[nr][nc] == color:
                            visited[nr][nc] = True
                            stack.append((nr, nc))
            components.append(cells)

    source_cells = []
    target_blocks = []

    for cells in components:
        if len(cells) == 1:
            r, c = cells[0]
            source_cells.append((r, c, grid[r][c]))
            continue

        rs = [r for r, _ in cells]
        cs = [c for _, c in cells]
        r0, r1 = min(rs), max(rs)
        c0, c1 = min(cs), max(cs)
        h = r1 - r0 + 1
        w = c1 - c0 + 1
        color = grid[r0][c0]

        solid = all(grid[rr][cc] == color
                    for rr in range(r0, r1 + 1)
                    for cc in range(c0, c1 + 1))

        if solid and h == w:
            target_blocks.append((r0, c0, h, color))

    if not target_blocks or not source_cells:
        return out

    # Block size.
    S = Counter(b[2] for b in target_blocks).most_common(1)[0][0]
    target_blocks = [b for b in target_blocks if b[2] == S]
    if not target_blocks:
        return out

    # Source pattern: single cells on a sparse lattice.
    src_rows = sorted({r for r, _, _ in source_cells})
    src_cols = sorted({c for _, c, _ in source_cells})
    R = len(src_rows)
    C = len(src_cols)

    row_id = {r: i for i, r in enumerate(src_rows)}
    col_id = {c: j for j, c in enumerate(src_cols)}

    src = [[bg] * C for _ in range(R)]
    for r, c, color in source_cells:
        if r in row_id and c in col_id:
            src[row_id[r]][col_id[c]] = color

    # Infer target lattice period from existing blocks.
    def infer_period(positions):
        if len(positions) < 2:
            return None
        g = 0
        for i in range(1, len(positions)):
            g = math.gcd(g, positions[i] - positions[i - 1])
        return g if g > 0 else None

    P_row = infer_period({b[0] for b in target_blocks})
    P_col = infer_period({b[1] for b in target_blocks})

    if P_row is None and P_col is None:
        # Fallback: try plausible periods.
        periods = list(range(S + 1, max(H, W) + 1))
    elif P_row is None:
        P_row = P_col
        periods = [P_row]
    elif P_col is None:
        P_col = P_row
        periods = [P_col]
    else:
        periods = [P_row, P_col]

    def valid_origin(pr, pc, origin_r, origin_c):
        if pr <= 0 or pc <= 0:
            return False
        for r, c, _, color in target_blocks:
            if (r - origin_r) % pr != 0 or (c - origin_c) % pc != 0:
                return False
            i = (r - origin_r) // pr
            j = (c - origin_c) // pc
            if not (0 <= i < R and 0 <= j < C):
                return False
            if src[i][j] != color:
                return False
        return True

    best = None
    best_score = -1

    for pr in periods:
        for pc in periods:
            # Candidate origins implied by each existing block and each
            # matching source cell.
            cand = set()
            for r, c, _, color in target_blocks:
                for i in range(R):
                    for j in range(C):
                        if src[i][j] == color:
                            cand.add((r - i * pr, c - j * pc))

            for origin_r, origin_c in cand:
                if not valid_origin(pr, pc, origin_r, origin_c):
                    continue

                # Prefer origins that keep the whole target grid inside the
                # canvas, and otherwise smaller absolute offsets.
                inside = True
                for i in range(R):
                    rr = origin_r + i * pr
                    if rr < 0 or rr + S > H:
                        inside = False
                        break
                if inside:
                    for j in range(C):
                        cc = origin_c + j * pc
                        if cc < 0 or cc + S > W:
                            inside = False
                            break

                score = (
                    1 if inside else 0,
                    -abs(origin_r),
                    -abs(origin_c),
                )
                if score > best_score:
                    best_score = score
                    best = (pr, pc, origin_r, origin_c)

    if best is None:
        return out

    P_row, P_col, origin_r, origin_c = best

    # Fill every non-background source cell as an S x S block.
    for i in range(R):
        for j in range(C):
            color = src[i][j]
            if color == bg:
                continue

            r = origin_r + i * P_row
            c = origin_c + j * P_col

            if r < 0 or c < 0 or r + S > H or c + S > W:
                continue

            for rr in range(r, r + S):
                for cc in range(c, c + S):
                    out[rr][cc] = color

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])

    # Background is the most frequent colour.
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=lambda c: counts[c])

    # Find connected components of non-background cells (4-connectivity).
    seen = [[False] * w for _ in range(h)]
    components = []

    for r in range(h):
        for c in range(w):
            if seen[r][c] or grid[r][c] == bg:
                continue

            cells = []
            stack = [(r, c)]
            seen[r][c] = True

            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w:
                        if not seen[ny][nx] and grid[ny][nx] != bg:
                            seen[ny][nx] = True
                            stack.append((ny, nx))

            colors = {grid[y][x] for y, x in cells}
            components.append((cells, colors))

    # The tile is the component containing more than one colour.
    tile_cells = None
    tile_colors = None
    for cells, colors in components:
        if len(colors) > 1:
            if tile_cells is None or len(cells) > len(tile_cells):
                tile_cells = cells
                tile_colors = colors

    # Fallback: if no multi-colour component is found, use the largest component.
    if tile_cells is None:
        tile_cells, tile_colors = max(components, key=lambda item: len(item[0]))

    # The mask is the remaining single-colour object.
    mask_cells = []
    mask_color = None
    for cells, colors in components:
        if cells is tile_cells:
            continue
        if len(colors) == 1:
            if mask_color is None or len(cells) > len(mask_cells):
                mask_cells = cells
                mask_color = next(iter(colors))

    # Fallback: use all non-background cells not in the tile.
    if mask_color is None:
        mask_cells = []
        for cells, colors in components:
            if cells is tile_cells:
                continue
            mask_cells.extend(cells)
        if mask_cells:
            mc = {}
            for y, x in mask_cells:
                v = grid[y][x]
                mc[v] = mc.get(v, 0) + 1
            mask_color = max(mc, key=lambda c: mc[c])
            mask_cells = [(y, x) for y, x in mask_cells if grid[y][x] == mask_color]

    # Bounding box of the tile.
    tmin_r = min(y for y, _ in tile_cells)
    tmax_r = max(y for y, _ in tile_cells)
    tmin_c = min(x for _, x in tile_cells)
    tmax_c = max(x for _, x in tile_cells)
    th = tmax_r - tmin_r + 1
    tw = tmax_c - tmin_c + 1

    tile = [
        [grid[tmin_r + i][tmin_c + j] for j in range(tw)]
        for i in range(th)
    ]

    # Bounding box of the mask.
    mmin_r = min(y for y, _ in mask_cells)
    mmax_r = max(y for y, _ in mask_cells)
    mmin_c = min(x for _, x in mask_cells)
    mmax_c = max(x for _, x in mask_cells)
    mh = mmax_r - mmin_r + 1
    mw = mmax_c - mmin_c + 1

    mask = [
        [1 if grid[mmin_r + i][mmin_c + j] == mask_color else 0 for j in range(mw)]
        for i in range(mh)
    ]

    # Build output: each mask pixel becomes either the tile or background.
    out = [[bg] * (mw * tw) for _ in range(mh * th)]

    for i in range(mh):
        for j in range(mw):
            if mask[i][j]:
                for a in range(th):
                    for b in range(tw):
                        out[i * th + a][j * tw + b] = tile[a][b]

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])

    # Background is the most frequent colour.
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=lambda c: counts[c])

    # Collect all non-background cells by colour.
    cells_by_color = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v != bg:
                cells_by_color.setdefault(v, []).append((r, c))

    if not cells_by_color:
        return [[bg] * w for _ in range(h)]

    def bbox(cells):
        rmin = min(r for r, _ in cells)
        rmax = max(r for r, _ in cells)
        cmin = min(c for _, c in cells)
        cmax = max(c for _, c in cells)
        return rmin, rmax, cmin, cmax

    def bbox_contains_other_color(rmin, rmax, cmin, cmax, color):
        for r in range(rmin, rmax + 1):
            for c in range(cmin, cmax + 1):
                v = grid[r][c]
                if v != bg and v != color:
                    return True
        return False

    def bbox_contains_color(rmin, rmax, cmin, cmax, color):
        for r in range(rmin, rmax + 1):
            for c in range(cmin, cmax + 1):
                if grid[r][c] == color:
                    return True
        return False

    # Primary rule:
    # The mask is a single colour whose bounding box does not contain other
    # non-background colours, and whose colour does not appear inside the
    # bounding box of the remaining non-background colours.
    best = None
    for color, cells in cells_by_color.items():
        rmin, rmax, cmin, cmax = bbox(cells)

        if bbox_contains_other_color(rmin, rmax, cmin, cmax, color):
            continue

        remaining = []
        for other, other_cells in cells_by_color.items():
            if other != color:
                remaining.extend(other_cells)

        if not remaining:
            continue

        rrmin, rrmax, ccmin, ccmax = bbox(remaining)

        if bbox_contains_color(rrmin, rrmax, ccmin, ccmax, color):
            continue

        row_gap = max(0, rrmin - rmax, rmin - rrmax)
        col_gap = max(0, ccmin - cmax, cmin - ccmax)
        gap = max(row_gap, col_gap)
        area = (rmax - rmin + 1) * (cmax - cmin + 1)
        score = (gap, area, len(cells))

        if best is None or score > best[0]:
            best = (score, color)

    if best is not None:
        mask_color = best[1]
        mask_cells = cells_by_color[mask_color]

        tile_cells = []
        for color, cells in cells_by_color.items():
            if color != mask_color:
                tile_cells.extend(cells)

        if not tile_cells:
            return [[bg] * w for _ in range(h)]
    else:
        # Fallback: use the largest multi-colour connected component as tile.
        seen = [[False] * w for _ in range(h)]
        components = []

        for r in range(h):
            for c in range(w):
                if seen[r][c] or grid[r][c] == bg:
                    continue

                stack = [(r, c)]
                seen[r][c] = True
                cells = []

                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w:
                            if not seen[ny][nx] and grid[ny][nx] != bg:
                                seen[ny][nx] = True
                                stack.append((ny, nx))

                colors = {grid[y][x] for y, x in cells}
                components.append((cells, colors))

        tile_cells = None
        best_tile_score = None
        for cells, colors in components:
            rmin, rmax, cmin, cmax = bbox(cells)
            area = (rmax - rmin + 1) * (cmax - cmin + 1)
            score = (len(colors), area, len(cells))
            if best_tile_score is None or score > best_tile_score:
                best_tile_score = score
                tile_cells = cells

        if tile_cells is None:
            return [[bg] * w for _ in range(h)]

        tile_set = set(tile_cells)
        remaining = [(r, c) for r, c in sum(cells_by_color.values(), []) if (r, c) not in tile_set]

        if not remaining:
            return [[bg] * w for _ in range(h)]

        rem_counts = {}
        for r, c in remaining:
            v = grid[r][c]
            rem_counts[v] = rem_counts.get(v, 0) + 1
        mask_color = max(rem_counts, key=lambda v: rem_counts[v])
        mask_cells = [(r, c) for r, c in remaining if grid[r][c] == mask_color]

    # Bounding boxes.
    trmin, trmax, tcmin, tcmax = bbox(tile_cells)
    th = trmax - trmin + 1
    tw = tcmax - tcmin + 1

    tile = [
        [grid[trmin + i][tcmin + j] for j in range(tw)]
        for i in range(th)
    ]

    mrmin, mrmax, mcmin, mcmax = bbox(mask_cells)
    mh = mrmax - mrmin + 1
    mw = mcmax - mcmin + 1

    mask_set = set(mask_cells)

    # Build output: each mask pixel becomes the tile, otherwise background.
    out = [[bg] * (mw * tw) for _ in range(mh * th)]

    for i in range(mh):
        for j in range(mw):
            if (mrmin + i, mcmin + j) in mask_set:
                for a in range(th):
                    for b in range(tw):
                        out[i * th + a][j * tw + b] = tile[a][b]

    return out

import sys
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return []

    H = len(grid)
    W = len(grid[0])
    out = [[8] * W for _ in range(H)]

    def neighbors(r, c):
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < H and 0 <= nc < W:
                yield nr, nc

    # Connected components of node cells (1 and 3)
    node_id = [[-1] * W for _ in range(H)]
    nodes = []
    for r in range(H):
        for c in range(W):
            if grid[r][c] in (1, 3) and node_id[r][c] == -1:
                q = deque([(r, c)])
                node_id[r][c] = len(nodes)
                cells = []
                while q:
                    cr, cc = q.popleft()
                    cells.append((cr, cc))
                    for nr, nc in neighbors(cr, cc):
                        if node_id[nr][nc] == -1 and grid[nr][nc] in (1, 3):
                            node_id[nr][nc] = len(nodes)
                            q.append((nr, nc))
                nodes.append(cells)

    # Connected components of marker cells (2 and 4)
    marker_id = [[-1] * W for _ in range(H)]
    markers = []
    for r in range(H):
        for c in range(W):
            if grid[r][c] in (2, 4) and marker_id[r][c] == -1:
                q = deque([(r, c)])
                marker_id[r][c] = len(markers)
                cells = []
                while q:
                    cr, cc = q.popleft()
                    cells.append((cr, cc))
                    for nr, nc in neighbors(cr, cc):
                        if marker_id[nr][nc] == -1 and grid[nr][nc] in (2, 4):
                            marker_id[nr][nc] = len(markers)
                            q.append((nr, nc))
                markers.append(cells)

    if not markers:
        return out

    # Use the marker containing a 4 if present; otherwise the largest marker.
    marker_cells = None
    for cells in markers:
        if any(grid[r][c] == 4 for r, c in cells):
            marker_cells = cells
            break
    if marker_cells is None:
        marker_cells = max(markers, key=len)

    # Determine marker direction from the 4 relative to the 2s.
    twos = [(r, c) for r, c in marker_cells if grid[r][c] == 2]
    fours = [(r, c) for r, c in marker_cells if grid[r][c] == 4]
    if twos and fours:
        fr, fc = fours[0]
        rmin = min(r for r, _ in twos)
        rmax = max(r for r, _ in twos)
        cmin = min(c for _, c in twos)
        cmax = max(c for _, c in twos)
        if fr < rmin:
            mdir = "up"
        elif fr > rmax:
            mdir = "down"
        elif fc < cmin:
            mdir = "left"
        elif fc > cmax:
            mdir = "right"
        else:
            mdir = "up"
    else:
        mdir = "up"

    # Marker port segment
    if mdir == "up":
        m_rows = [min(r for r, _ in marker_cells)]
        m_cols = sorted(set(c for _, c in marker_cells))
    elif mdir == "down":
        m_rows = [max(r for r, _ in marker_cells)]
        m_cols = sorted(set(c for _, c in marker_cells))
    elif mdir == "left":
        m_rows = sorted(set(r for r, _ in marker_cells))
        m_cols = [min(c for _, c in marker_cells)]
    else:
        m_rows = sorted(set(r for r, _ in marker_cells))
        m_cols = [max(c for _, c in marker_cells)]

    def find_target(direction, rows, cols, start_r, start_c, exclude_id=None):
        """Scan outward along the port line and return the first node hit."""
        best = None
        best_dist = None

        if direction == "right":
            for r in rows:
                for c in range(start_c, W):
                    if 0 <= r < H and node_id[r][c] != -1 and node_id[r][c] != exclude_id:
                        dist = c - start_c
                        if best_dist is None or dist < best_dist:
                            best_dist = dist
                            best = node_id[r][c]
                        break
        elif direction == "left":
            for r in rows:
                for c in range(start_c, -1, -1):
                    if 0 <= r < H and node_id[r][c] != -1 and node_id[r][c] != exclude_id:
                        dist = start_c - c
                        if best_dist is None or dist < best_dist:
                            best_dist = dist
                            best = node_id[r][c]
                        break
        elif direction == "up":
            for c in cols:
                for r in range(start_r, -1, -1):
                    if 0 <= c < W and node_id[r][c] != -1 and node_id[r][c] != exclude_id:
                        dist = start_r - r
                        if best_dist is None or dist < best_dist:
                            best_dist = dist
                            best = node_id[r][c]
                        break
        elif direction == "down":
            for c in cols:
                for r in range(start_r, H):
                    if 0 <= c < W and node_id[r][c] != -1 and node_id[r][c] != exclude_id:
                        dist = r - start_r
                        if best_dist is None or dist < best_dist:
                            best_dist = dist
                            best = node_id[r][c]
                        break
        return best

    # Parse node ports.
    node_ports = [[] for _ in nodes]
    for idx, cells in enumerate(nodes):
        ones = [(r, c) for r, c in cells if grid[r][c] == 1]
        threes = [(r, c) for r, c in cells if grid[r][c] == 3]
        if not ones:
            continue

        rmin = min(r for r, _ in ones)
        rmax = max(r for r, _ in ones)
        cmin = min(c for _, c in ones)
        cmax = max(c for _, c in ones)

        groups = {"up": [], "down": [], "left": [], "right": []}
        for r, c in threes:
            if r < rmin:
                groups["up"].append((r, c))
            elif r > rmax:
                groups["down"].append((r, c))
            elif c < cmin:
                groups["left"].append((r, c))
            elif c > cmax:
                groups["right"].append((r, c))

        for d, pts in groups.items():
            if not pts:
                continue
            if d == "up":
                rows = [min(r for r, _ in pts)]
                cols = sorted(set(c for _, c in pts))
                start_r = rows[0] - 1
                start_c = None
            elif d == "down":
                rows = [max(r for r, _ in pts)]
                cols = sorted(set(c for _, c in pts))
                start_r = rows[0] + 1
                start_c = None
            elif d == "left":
                rows = sorted(set(r for r, _ in pts))
                cols = [min(c for _, c in pts)]
                start_r = None
                start_c = cols[0] - 1
            else:
                rows = sorted(set(r for r, _ in pts))
                cols = [max(c for _, c in pts)]
                start_r = None
                start_c = cols[0] + 1
            node_ports[idx].append((d, rows, cols, start_r, start_c))

    # Reachability from marker.
    selected_nodes = set()
    connections = []

    # Marker connection(s)
    target = find_target(mdir, m_rows, m_cols,
                         m_rows[0] if mdir in ("up", "down") else None,
                         m_cols[0] if mdir in ("left", "right") else None,
                         exclude_id=None)
    if target is not None:
        selected_nodes.add(target)
        connections.append(("marker", mdir, m_rows, m_cols, target))

    # Follow directed ports from selected nodes.
    q = deque(selected_nodes)
    while q:
        cur = q.popleft()
        for d, rows, cols, sr, sc in node_ports[cur]:
            t = find_target(d, rows, cols, sr, sc, exclude_id=cur)
            if t is not None:
                connections.append(("node", d, rows, cols, t))
                if t not in selected_nodes:
                    selected_nodes.add(t)
                    q.append(t)
            else:
                connections.append(("node", d, rows, cols, None))

    def paint_cells(cells):
        for r, c in cells:
            out[r][c] = 2

    def paint_rect(r1, r2, c1, c2):
        for r in range(min(r1, r2), max(r1, r2) + 1):
            for c in range(min(c1, c2), max(c1, c2) + 1):
                if 0 <= r < H and 0 <= c < W:
                    out[r][c] = 2

    # Paint selected nodes and marker.
    for idx in selected_nodes:
        paint_cells(nodes[idx])
    paint_cells(marker_cells)

    # Paint connections.
    for kind, d, rows, cols, target in connections:
        if kind == "marker":
            if target is None:
                if d == "up":
                    paint_rect(0, m_rows[0], m_cols[0], m_cols[-1])
                elif d == "down":
                    paint_rect(m_rows[0], H - 1, m_cols[0], m_cols[-1])
                elif d == "left":
                    paint_rect(m_rows[0], m_rows[-1], 0, m_cols[0])
                else:
                    paint_rect(m_rows[0], m_rows[-1], m_cols[0], W - 1)
            else:
                tcells = nodes[target]
                if d == "up":
                    tr = max(r for r, _ in tcells)
                    paint_rect(tr, m_rows[0], m_cols[0], m_cols[-1])
                elif d == "down":
                    tr = min(r for r, _ in tcells)
                    paint_rect(m_rows[0], tr, m_cols[0], m_cols[-1])
                elif d == "left":
                    tc = max(c for _, c in tcells)
                    paint_rect(m_rows[0], m_rows[-1], m_cols[0], tc)
                else:
                    tc = min(c for _, c in tcells)
                    paint_rect(m_rows[0], m_rows[-1], m_cols[0], tc)
        else:
            if target is None:
                if d == "up":
                    paint_rect(0, rows[0], cols[0], cols[-1])
                elif d == "down":
                    paint_rect(rows[0], H - 1, cols[0], cols[-1])
                elif d == "left":
                    paint_rect(rows[0], rows[-1], 0, cols[0])
                else:
                    paint_rect(rows[0], rows[-1], cols[0], W - 1)
            else:
                tcells = nodes[target]
                if d == "up":
                    tr = max(r for r, _ in tcells)
                    paint_rect(tr, rows[0], cols[0], cols[-1])
                elif d == "down":
                    tr = min(r for r, _ in tcells)
                    paint_rect(rows[0], tr, cols[0], cols[-1])
                elif d == "left":
                    tc = max(c for _, c in tcells)
                    paint_rect(rows[0], rows[-1], cols[0], tc)
                else:
                    tc = min(c for _, c in tcells)
                    paint_rect(rows[0], rows[-1], cols[0], tc)

    return out

import sys
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    W = len(grid[0]) if H else 0
    out = [[8] * W for _ in range(H)]

    # ---------- marker ----------
    head = None
    tail = []
    for r in range(H):
        for c in range(W):
            if grid[r][c] == 4:
                head = (r, c)
            elif grid[r][c] == 2:
                tail.append((r, c))

    if head is None:
        return out

    hr, hc = head
    if tail:
        tr = sum(r for r, _ in tail) / len(tail)
        tc = sum(c for _, c in tail) / len(tail)
        dr = hr - tr
        dc = hc - tc
        if abs(dr) >= abs(dc):
            mdir = "up" if dr < 0 else "down"
        else:
            mdir = "left" if dc < 0 else "right"
    else:
        mdir = "up"

    # ---------- nodes: connected components of 1 ----------
    node_id = [[-1] * W for _ in range(H)]
    nodes = []
    for r in range(H):
        for c in range(W):
            if grid[r][c] == 1 and node_id[r][c] == -1:
                q = deque([(r, c)])
                node_id[r][c] = len(nodes)
                cells = []
                while q:
                    x, y = q.popleft()
                    cells.append((x, y))
                    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < H and 0 <= ny < W and grid[nx][ny] == 1 and node_id[nx][ny] == -1:
                            node_id[nx][ny] = len(nodes)
                            q.append((nx, ny))
                rmin = min(x for x, _ in cells)
                rmax = max(x for x, _ in cells)
                cmin = min(y for _, y in cells)
                cmax = max(y for _, y in cells)
                nodes.append({
                    "cells": cells,
                    "rmin": rmin,
                    "rmax": rmax,
                    "cmin": cmin,
                    "cmax": cmax,
                    "ports": []
                })

    # ---------- assign 3s to nodes and build ports ----------
    for r in range(H):
        for c in range(W):
            if grid[r][c] != 3:
                continue

            owner = -1
            # direct adjacency to a 1-cell
            for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dx, c + dy
                if 0 <= nr < H and 0 <= nc < W and node_id[nr][nc] != -1:
                    owner = node_id[nr][nc]
                    break

            # fallback: nearest node whose bounding box is adjacent in one direction
            if owner == -1:
                best_d = None
                for idx, nd in enumerate(nodes):
                    d = None
                    if r < nd["rmin"] and nd["cmin"] <= c <= nd["cmax"]:
                        d = nd["rmin"] - r
                    elif r > nd["rmax"] and nd["cmin"] <= c <= nd["cmax"]:
                        d = r - nd["rmax"]
                    elif c < nd["cmin"] and nd["rmin"] <= r <= nd["rmax"]:
                        d = nd["cmin"] - c
                    elif c > nd["cmax"] and nd["rmin"] <= r <= nd["rmax"]:
                        d = c - nd["cmax"]
                    if d is not None and (best_d is None or d < best_d):
                        best_d = d
                        owner = idx

            if owner == -1:
                continue

            nd = nodes[owner]
            if r < nd["rmin"]:
                d = "up"
            elif r > nd["rmax"]:
                d = "down"
            elif c < nd["cmin"]:
                d = "left"
            elif c > nd["cmax"]:
                d = "right"
            else:
                continue

            for p in nd["ports"]:
                if p[0] == d:
                    p[1].append((r, c))
                    break
            else:
                nd["ports"].append([d, [(r, c)]])

    # normalize ports: direction, rows, cols, start row/col just outside port
    for nd in nodes:
        new_ports = []
        for d, pts in nd["ports"]:
            if not pts:
                continue
            rows = sorted(set(r for r, _ in pts))
            cols = sorted(set(c for _, c in pts))
            if d == "up":
                start_r = min(rows) - 1
                start_c = None
            elif d == "down":
                start_r = max(rows) + 1
                start_c = None
            elif d == "left":
                start_r = None
                start_c = min(cols) - 1
            else:
                start_r = None
                start_c = max(cols) + 1
            new_ports.append((d, rows, cols, start_r, start_c))
        nd["ports"] = new_ports

    # ---------- target finding ----------
    def find_target(direction, rows, cols, start_r, start_c, exclude_id):
        best = -1
        best_dist = None

        if direction == "up":
            for c in cols:
                for r in range(start_r, -1, -1):
                    if 0 <= c < W and node_id[r][c] != -1 and node_id[r][c] != exclude_id:
                        dist = start_r - r
                        if best_dist is None or dist < best_dist:
                            best_dist = dist
                            best = node_id[r][c]
                        break
        elif direction == "down":
            for c in cols:
                for r in range(start_r, H):
                    if 0 <= c < W and node_id[r][c] != -1 and node_id[r][c] != exclude_id:
                        dist = r - start_r
                        if best_dist is None or dist < best_dist:
                            best_dist = dist
                            best = node_id[r][c]
                        break
        elif direction == "left":
            for r in rows:
                for c in range(start_c, -1, -1):
                    if 0 <= r < H and node_id[r][c] != -1 and node_id[r][c] != exclude_id:
                        dist = start_c - c
                        if best_dist is None or dist < best_dist:
                            best_dist = dist
                            best = node_id[r][c]
                        break
        else:  # right
            for r in rows:
                for c in range(start_c, W):
                    if 0 <= r < H and node_id[r][c] != -1 and node_id[r][c] != exclude_id:
                        dist = c - start_c
                        if best_dist is None or dist < best_dist:
                            best_dist = dist
                            best = node_id[r][c]
                        break
        return best

    # ---------- reachability from marker ----------
    selected = set()
    connections = []

    if mdir in ("up", "down"):
        m_rows = [hr]
        m_cols = [hc]
        start_r = hr - 1 if mdir == "up" else hr + 1
        start_c = None
    else:
        m_rows = [hr]
        m_cols = [hc]
        start_r = None
        start_c = hc - 1 if mdir == "left" else hc + 1

    target = find_target(mdir, m_rows, m_cols, start_r, start_c, None)
    if target is not None:
        selected.add(target)
    connections.append(("marker", mdir, m_rows, m_cols, target))

    q = deque(selected)
    while q:
        cur = q.popleft()
        for d, rows, cols, sr, sc in nodes[cur]["ports"]:
            t = find_target(d, rows, cols, sr, sc, cur)
            connections.append(("node", d, rows, cols, t))
            if t is not None and t not in selected:
                selected.add(t)
                q.append(t)

    # ---------- painting ----------
    def paint_cells(cells):
        for r, c in cells:
            out[r][c] = 2

    def paint_rect(r1, r2, c1, c2):
        r1, r2 = min(r1, r2), max(r1, r2)
        c1, c2 = min(c1, c2), max(c1, c2)
        for r in range(r1, r2 + 1):
            for c in range(c1, c2 + 1):
                if 0 <= r < H and 0 <= c < W:
                    out[r][c] = 2

    # selected nodes
    for idx in selected:
        paint_cells(nodes[idx]["cells"])

    # marker cells
    paint_cells([(hr, hc)] + tail)

    # marker connection
    kind, d, rows, cols, target = connections[0]
    if d == "up":
        if target is None:
            paint_rect(0, hr, hc, hc)
        else:
            tr = max(r for r, _ in nodes[target]["cells"])
            paint_rect(tr, hr, hc, hc)
    elif d == "down":
        if target is None:
            paint_rect(hr, H - 1, hc, hc)
        else:
            tr = min(r for r, _ in nodes[target]["cells"])
            paint_rect(hr, tr, hc, hc)
    elif d == "left":
        if target is None:
            paint_rect(hr, hr, 0, hc)
        else:
            tc = max(c for _, c in nodes[target]["cells"])
            paint_rect(hr, hr, hc, tc)
    else:
        if target is None:
            paint_rect(hr, hr, hc, W - 1)
        else:
            tc = min(c for _, c in nodes[target]["cells"])
            paint_rect(hr, hr, hc, tc)

    # node port connections
    for kind, d, rows, cols, target in connections[1:]:
        if d == "up":
            if target is None:
                paint_rect(0, max(rows), min(cols), max(cols))
            else:
                tr = max(r for r, _ in nodes[target]["cells"])
                paint_rect(tr, max(rows), min(cols), max(cols))
        elif d == "down":
            if target is None:
                paint_rect(min(rows), H - 1, min(cols), max(cols))
            else:
                tr = min(r for r, _ in nodes[target]["cells"])
                paint_rect(min(rows), tr, min(cols), max(cols))
        elif d == "left":
            if target is None:
                paint_rect(min(rows), max(rows), 0, max(cols))
            else:
                tc = max(c for _, c in nodes[target]["cells"])
                paint_rect(min(rows), max(rows), min(cols), tc)
        else:
            if target is None:
                paint_rect(min(rows), max(rows), min(cols), W - 1)
            else:
                tc = min(c for _, c in nodes[target]["cells"])
                paint_rect(min(rows), max(rows), min(cols), tc)

    return out

import numpy as np
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = np.full((h, w), 4, dtype=int)

    # 8-connected components of 1s
    seen = np.zeros((h, w), dtype=bool)
    comps = []
    for r in range(h):
        for c in range(w):
            if g[r, c] == 1 and not seen[r, c]:
                q = deque([(r, c)])
                seen[r, c] = True
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            if dy == 0 and dx == 0:
                                continue
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < h and 0 <= nx < w and not seen[ny, nx] and g[ny, nx] == 1:
                                seen[ny, nx] = True
                                q.append((ny, nx))
                comps.append(cells)

    # For each component, find enclosed background holes (4-cells not connected to outside)
    for cells in comps:
        comp_mask = np.zeros((h, w), dtype=bool)
        for y, x in cells:
            comp_mask[y, x] = True

        # background cells not in component
        bg = (g == 4) & (~comp_mask)

        # flood fill outside background from all border background cells
        outside = np.zeros((h, w), dtype=bool)
        q = deque()
        for r in range(h):
            for c in (0, w - 1):
                if bg[r, c] and not outside[r, c]:
                    outside[r, c] = True
                    q.append((r, c))
        for c in range(w):
            for r in (0, h - 1):
                if bg[r, c] and not outside[r, c]:
                    outside[r, c] = True
                    q.append((r, c))

        while q:
            y, x = q.popleft()
            for dy in (-1, 0, 1):
                for dx in (-1, 0, 1):
                    if dy == 0 and dx == 0:
                        continue
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and bg[ny, nx] and not outside[ny, nx]:
                        outside[ny, nx] = True
                        q.append((ny, nx))

        holes = bg & (~outside)

        # If component has holes: 1 -> 8, holes -> 6, border -> 2
        if holes.any():
            out[comp_mask] = 8
            out[holes] = 6
            # border: 8-neighbourhood of component, excluding component and holes
            border = np.zeros((h, w), dtype=bool)
            for y, x in cells:
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w:
                            border[ny, nx] = True
            border &= (~comp_mask) & (~holes)
            out[border] = 2
        else:
            # solid component: keep 1s, add 2 border
            out[comp_mask] = 1
            border = np.zeros((h, w), dtype=bool)
            for y, x in cells:
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w:
                            border[ny, nx] = True
            border &= (~comp_mask)
            out[border] = 2

    return out.tolist()
